step("Farm run: waiting counts down, gives up after 10 minutes", function()
    local Z = 1462
    ns.db.nodes[Z] = { { id = "o1731", name = "Copper Vein", type = "ore", x = 0.52, y = 0.5, count = 1, last = 1 } }
    player.map, player.x, player.y = Z, 0.5, 0.5
