    local old, herb = methods.GetStringHeight, { PROFS[1][2], PROFS[1][3] }
    methods.GetStringHeight = TextHeight
    PROFS[1][2], PROFS[1][3] = 75, 75 -- end of a rank: the long trainer verdict
    ns.ToggleMain("overview") advance(3)
    local scroll = _G.GathercraftHereScroll
    assert(scroll, "no scroll area for the zone's nodes")
    local function Rows()
        local rows = {}
        for _, f in ipairs(allFrames) do
            if f.__kind == "Frame" and f.__parent and f.__parent.__parent == scroll and f.__shown and f.__pts then rows[#rows + 1] = f end
        end
        return rows
    end
    local cap = ns.L["|cffffd060No skill-ups until you train the next rank|r"]
    local function Check(what)
        local rows, capped = Rows(), 0
        assert(#rows > 0, what .. ": no rows")
        for _, row in ipairs(rows) do
            local name, info
            for _, f in ipairs(allFrames) do
                if f.__parent == row and f.__kind == "FontString" then
                    if f.__pts.TOPLEFT[1] == row.icon then name = f else info = f end
                end
            end
            assert(name.__w and info.__w and name.__w + 28 <= row.__w, what .. ": texts wider than the row")
            assert(row.__h >= name:GetStringHeight() + info:GetStringHeight(), ("%s: row %s px for %s + %s px of text"):format(
                what, row.__h, name:GetStringHeight(), info:GetStringHeight()))
            if info.__text:find(cap, 1, true) then capped = capped + 1 end
        end
        assert(capped > 0, what .. ": no row with the trainer verdict")
        NoOverlap(rows, what)
        return rows
    end
    Check("overview")
    -- the list ends above the run buttons (they sit 10 px up, 22 px high)
    local br = scroll.__pts.BOTTOMRIGHT
    assert(br and br[4] >= 34, "the list runs into the buttons below")
    -- narrower: more lines, laid out again by the size change alone
    local rowsBefore = Rows()
    local hBefore = 0 for _, r in ipairs(rowsBefore) do hBefore = hBefore + r.__h end
    scroll.__scripts.OnSizeChanged(scroll, 180, 300)
    local hAfter = 0 for _, r in ipairs(Check("narrow")) do hAfter = hAfter + r.__h end
    assert(hAfter > hBefore, "rows did not grow when the area got narrower")
    scroll.__scripts.OnSizeChanged(scroll, 414, 300)
    ns.HideMain()
    methods.GetStringHeight = old
    PROFS[1][2], PROFS[1][3] = herb[1], herb[2]
end)
step("Skills: long names and verdicts stay in their columns (v0.1.14)", function()
    local old, herb = methods.GetStringHeight, { PROFS[1][2], PROFS[1][3] }
    methods.GetStringHeight = TextHeight
    PROFS[1][2], PROFS[1][3] = 75, 75
    local stats = ns.KindStats()
    local added = {
        ["herb:briarthorn"] = { name = "Briarthorn", type = "herb", n = 3, ups = 2, minSkill = 70, maxUp = 74 },
        ["ore:ooze covered rich thorium vein"] = { name = "Ooze Covered Rich Thorium Vein", type = "ore", n = 1, ups = 0, minSkill = 275 },
    }
    for k, s in pairs(added) do stats[k] = s end
    ns.ToggleMain("skills") advance(1)
    local scroll = _G.GathercraftSkillsScroll
    local function Check(what)
        local rows = {}
        for _, f in ipairs(allFrames) do
            if f.__kind == "Frame" and f.__parent and f.__parent.__parent == scroll and f.__shown and f.__pts then rows[#rows + 1] = f end
        end
        assert(#rows >= 2, what .. ": rows missing")
        for _, row in ipairs(rows) do
            local name, verdict, info
            for _, f in ipairs(allFrames) do
                if f.__parent == row and f.__kind == "FontString" then
                    local a = f.__pts.TOPLEFT
                    if a[1] == row.icon then name = f elseif a[1] == row then info = f else verdict = f end
                end
            end
            assert(name and verdict and info, what .. ": texts not found")
            assert(name.__w and verdict.__w and 32 + name.__w + 12 + verdict.__w <= row.__w,
                what .. ": name + verdict wider than the row")
            local top = math.max(name:GetStringHeight(), verdict:GetStringHeight())
            assert(-info.__pts.TOPLEFT[4] >= top, what .. ": numbers overlap name or verdict")
            assert(row.__h >= top + info:GetStringHeight(), what .. ": row lower than its texts")
        end
        NoOverlap(rows, what)
    end
    Check("skills")
    local cap = ns.L["|cffffd060No skill-ups until you train the next rank|r"]
    local found
    for _, f in ipairs(allFrames) do if f.__text == cap then found = true end end
    assert(found, "Briarthorn at 75/75 does not show the trainer verdict")
    scroll.__scripts.OnSizeChanged(scroll, 420, 300) -- narrower: laid out again
    Check("narrow")
    scroll.__scripts.OnSizeChanged(scroll, 698, 300)
    ns.HideMain()
    for k in pairs(added) do stats[k] = nil end
    methods.GetStringHeight = old
    PROFS[1][2], PROFS[1][3] = herb[1], herb[2]
end)
step("Language change without reload: no English left, craft hint too (v0.1.14)", function()
    local keep = ns.db.language
    local target = ns.Language() == "deDE" and "frFR" or "deDE"
    -- like the language buttons in Options: apply, then the options refresh
    ns.db.language = target ns.ApplyLanguage() _G.GathercraftOptions:Refresh()
    local L, dict = ns.L, ns.Locales[target]
    local craft = L["Colored names: recipes you know (color = skill-up chance). Grey: not learned yet, with the skill it needs. "] ..
        L["Hover a line for the reagents. \"Can make\" counts bags and bank. Visit trainers to add their recipes."]
    local farm = L["~ = estimate from known spawn points, your skill and prices. After 10 minutes of farm runs "] ..
        L["in a zone your real numbers are shown instead (green). Click a column title to sort."]
    local gotCraft, gotFarm
    for _, f in ipairs(allFrames) do
        if f.__text == craft then gotCraft = true end
        if f.__text == farm then gotFarm = true end
    end
    assert(gotCraft, "craft page hint not in " .. target .. " after the switch")
    assert(gotFarm, "farm spots hint not in " .. target .. " after the switch")
    -- every page as you see it: no label keeps an English text that has a
    -- translation. The game runs OnShow of a shown frame's children too
    -- (the mock only for the frame itself), so that is done here
    local keys = {}
    for k, v in pairs(dict) do if v ~= k and #k >= 3 then keys[#keys + 1] = k end end
    local main, left, seen = _G.GathercraftMain, {}, {}
    local function InMain(f)
        while f do if f == main then return true end f = f.__parent end
    end
    for _, tab in ipairs({ "overview", "farm", "craft", "zones", "skills", "options" }) do
        ns.ToggleMain(tab) advance(3)
        for _, f in ipairs(allFrames) do
            if f ~= main and f.__scripts.OnShow and InMain(f) and f:IsVisible() then f.__scripts.OnShow(f) end
        end
        for _, f in ipairs(allFrames) do
            local t = f.__kind == "FontString" and type(f.__text) == "string" and f.__text
            if t and not seen[t] and f:IsVisible() and InMain(f) then
                for _, k in ipairs(keys) do
                    if (#k >= 8 and t:find(k, 1, true)) or t == k then seen[t] = true left[#left + 1] = tab .. ": " .. t:sub(1, 60) break end
                end
            end
        end
    end
    ns.HideMain()
    ns.db.language = keep ns.ApplyLanguage()
    assert(#left == 0, ("%d English texts after switching to %s: %s"):format(#left, target, table.concat(left, " | ")))
end)
step("Pins: a zone change on the same continent moves only the minimap pins (v0.1.14)", function()
    -- Mulgore <-> The Barrens (both Kalimdor in the mock, like Thunder Bluff <-> Mulgore)
    local pins = LibStub("HereBeDragons-Pins-2.0")
    local keep = { pins.AddWorldMapIconMap, pins.RemoveWorldMapIcon, pins.AddMinimapIconMap, pins.RemoveMinimapIcon }
    local world, mini, active = { add = 0, rem = 0 }, { add = 0, rem = 0 }, {}
    pins.AddWorldMapIconMap = function(self, ref, icon, ...) if ref == "Gathercraft" then world.add = world.add + 1 end return keep[1](self, ref, icon, ...) end
    pins.RemoveWorldMapIcon = function(self, ref, icon, ...) if ref == "Gathercraft" then world.rem = world.rem + 1 end return keep[2](self, ref, icon, ...) end
    pins.AddMinimapIconMap = function(self, ref, icon, ...)
        if ref == "Gathercraft" then mini.add = mini.add + 1 active[icon] = icon.node end
        return keep[3](self, ref, icon, ...)
    end
    pins.RemoveMinimapIcon = function(self, ref, icon, ...)
        if ref == "Gathercraft" then mini.rem = mini.rem + 1 active[icon] = nil end
        return keep[4](self, ref, icon, ...)
    end
    local map = player.map
    local function Go(mapID)
        world.add, world.rem, mini.add, mini.rem = 0, 0, 0, 0
        player.map = mapID
        fire("ZONE_CHANGED_NEW_AREA") advance(1)
    end
    local function MiniNodes()
        local set, n = {}, 0
        for _, node in pairs(active) do set[node] = true n = n + 1 end
        return set, n
    end
    ns.ImportQuestieZone(1412, true) ns.ImportQuestieZone(1413, true) advance(1)
    -- Mining 110/150 and a known spot where Copper or Tin can be: Copper alone
    -- is grey there, the spot shows Tin's yellow
    local ore = { PROFS[2][2], PROFS[2][3] }
    PROFS[2][2], PROFS[2][3] = 110, 150
    -- (20 yd from where you stand: since 0.1.23 only the nodes near you have a registered minimap pin)
    local copper = { id = "o1731", name = "Copper Vein", type = "ore", x = player.x + 0.004, y = player.y, count = 0, last = 0, source = "questie" }
    local tin = { id = "o1732", name = "Tin Vein", type = "ore", x = copper.x, y = copper.y, count = 0, last = 0, source = "questie" }
    table.insert(ns.db.nodes[1413], copper) table.insert(ns.db.nodes[1413], tin)
    ns.TogglePins() ns.TogglePins() advance(4)
    Go(1412) Go(1413)
    assert(world.add == 0 and world.rem == 0, ("Mulgore -> Barrens: %d world map pins off, %d on"):format(world.rem, world.add))
    assert(mini.add > 0 and mini.rem > 0, "minimap pins did not move")
    local moved, count = MiniNodes()
    local inBarrens = {}
    for _, node in ipairs(ns.db.nodes[1413]) do inBarrens[node] = true end
    for node in pairs(moved) do assert(node.pendingReport or inBarrens[node], "minimap pin of another zone: " .. tostring(node.name)) end
    -- the same pins as a full rebuild: which nodes, the kinds sharing a spot,
    -- ring texture and colour, alpha
    local function Look()
        local out = {}
        for icon, node in pairs(active) do
            local ring, c = icon.ring, icon.ring and icon.ring.__color
            out[node] = ("%s|%s|%s|%.2f|%s"):format(tostring(ring and ring.__tex),
                c and ("%.2f,%.2f,%.2f"):format(c[1], c[2], c[3]) or "-", tostring(icon.level), icon:GetAlpha(),
                icon.othersOf and tostring(#(icon.othersOf.others or {})) or "no link")
        end
        return out
    end
    local afterMove = Look()
    local spot = afterMove[copper] or afterMove[tin]
    assert(spot and spot:find("|yellow|", 1, true), "Copper/Tin spot after the move: " .. tostring(spot))
    ns.TogglePins() ns.TogglePins() advance(1)
    local rebuilt, count2 = MiniNodes()
    assert(count == count2, ("minimap pins after the move %d, after a rebuild %d"):format(count, count2))
    for node in pairs(rebuilt) do assert(moved[node], "a node has a minimap pin only after the rebuild: " .. tostring(node.name)) end
    for node, look in pairs(Look()) do
        assert(afterMove[node] == look, ("%s: after the move %s, after a rebuild %s"):format(tostring(node.name), tostring(afterMove[node]), look))
    end
    for i = #ns.db.nodes[1413], 1, -1 do
        if ns.db.nodes[1413][i] == copper or ns.db.nodes[1413][i] == tin then table.remove(ns.db.nodes[1413], i) end
    end
    PROFS[2][2], PROFS[2][3] = ore[1], ore[2]
    -- another continent: rebuilt as before (grey report pins depend on it)
    Go(1429)
    assert(world.add > 0, "continent change: no rebuild")
    Go(map)
    pins.AddWorldMapIconMap, pins.RemoveWorldMapIcon, pins.AddMinimapIconMap, pins.RemoveMinimapIcon = keep[1], keep[2], keep[3], keep[4]
    advance(1)
end)
step("Run: the empty check after arriving (20 yd) - gathers, other kinds, late records (v0.1.14)", function()
    -- Mulgore in the mock: 1 yd = 0.0002 map x. A far Peacebloom keeps a next target.
    local keepNodes, keepArrive, keepMap, keepX, keepY = ns.db.nodes[1412], ns.db.arriveDist, player.map, player.x, player.y
    local OBJ = { Earthroot = { 1619, 2449, "herb" }, Peacebloom = { 1618, 2447, "herb" }, ["Copper Vein"] = { 1731, 2770, "ore" } }
    local seq = 0
    local function Node(name, xYd, extra)
        local o = OBJ[name]
        local n = { id = "o" .. o[1], name = name, type = o[3], item = o[2], x = 0.5 + xYd / 5000, y = 0.5, count = 1, last = 1 }
        for k, v in pairs(extra or {}) do n[k] = v end
        return n
    end
    local function At(xYd) player.map, player.x, player.y = 1412, 0.5 + xYd / 5000, 0.5 end
    local function Wait(s) for _ = 1, s * 2 do advance(0.5) end end
    local function Cast(name)
        seq = seq + 1
        local id = "emptycheck" .. seq
        fire("UNIT_SPELLCAST_SENT", "player", name, id, OBJ[name][3] == "ore" and 2575 or 2366)
        return id
    end
    local function Done(name, id, withLoot)
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", id, OBJ[name][3] == "ore" and 2575 or 2366)
        if withLoot ~= false then
            loot = { { guid = ("GameObject-0-1-1-1-%d-EC%06d"):format(OBJ[name][1], seq), item = OBJ[name][2], qty = 2 } }
            fire("LOOT_READY") fire("LOOT_OPENED")
            loot = {}
        end
    end
    local function Run(nodes, filter)
        ns.db.nodes[1412] = nodes
        table.insert(nodes, Node("Peacebloom", 2500))
        ns.NotifyNodesChanged() advance(1)
        At(-200)
        ns.StartRun(filter, 1412) Wait(1)
        At(-19) Wait(1) -- the first point is reached (19 yd)
    end
    ns.db.arriveDist = 20
    -- a gather still running when the 25 s are over: its result decides
    local A = Node("Earthroot", 0)
    Run({ A }, "herb")
    At(-2) Wait(20)
    local id = Cast("Earthroot") Wait(5) Done("Earthroot", id)
    Wait(30)
    assert(not A.misses and A.hits == 1, ("gather running at the check: misses %s"):format(tostring(A.misses)))
    ns.StopRun(true)
    -- a second try only after the 25 s: the miss is taken back when it works
    A = Node("Earthroot", 0)
    Run({ A }, "herb")
    At(-2) Wait(10)
    id = Cast("Earthroot") Wait(2) fire("UNIT_SPELLCAST_INTERRUPTED", "player", id, 2366)
    Wait(14)
    id = Cast("Earthroot") Wait(3) Done("Earthroot", id)
    Wait(30)
    assert((A.misses or 0) == 0 and A.hits == 1, ("late second try: misses %s"):format(tostring(A.misses)))
    ns.StopRun(true)
    -- another kind gathered 20 yd away says nothing: the empty Earthroot spot is learned
    for _, other in ipairs({ { "Peacebloom", "herb" }, { "Copper Vein", nil } }) do
        A = Node("Earthroot", 0)
        local B = Node(other[1], 22)
        Run({ A, B }, other[2])
        At(20) Wait(2)
        id = Cast(other[1]) Wait(3) Done(other[1], id)
        At(80) Wait(30)
        assert(A.emptyStreak == 1 and A.misses == 1, other[1] .. " next to it counted as an Earthroot harvest")
        ns.StopRun(true)
    end
    -- the herb grows 12 yd from the known point; no loot event at all: since v0.1.14
    -- (round 10) nothing is booked, and the gather without loot keeps the known
    -- point from being called empty (it is not judged)
    A = Node("Earthroot", 0, { source = "questie" })
    Run({ A }, "herb")
    At(12) Wait(2)
    id = Cast("Earthroot") Wait(3) Done("Earthroot", id, false)
    At(55) Wait(32)
    assert(not A.misses, "a late record far away made the known point empty")
    ns.StopRun(true)
    -- unchanged: really empty target = learned; passed by in combat = short rest only
    A = Node("Earthroot", 0)
    Run({ A }, "herb")
    At(-2) Wait(30)
    assert(A.emptyStreak == 1 and A.misses == 1, "empty target not learned")
    ns.StopRun(true)
    A = Node("Earthroot", 0)
    Run({ A }, "herb")
    UnitAffectingCombat = function() return true end
    Wait(15)
    UnitAffectingCombat = nil
    At(-2) Wait(15)
    assert(not A.misses and ns.IsOnCooldown(A), "combat: should be a short rest only")
    ns.StopRun(true)
    ns.db.nodes[1412], ns.db.arriveDist = keepNodes, keepArrive
    player.map, player.x, player.y = keepMap, keepX, keepY
    ns.NotifyNodesChanged() advance(2)
end)
-- shared by the two steps below: a clean Mulgore with chosen nodes
local function IdentityWorld()
    local W = { keepNodes = ns.db.nodes[1412], keepArrive = ns.db.arriveDist, map = player.map, x = player.x, y = player.y, seq = 0 }
    function W.P(xYd) return 0.5 + xYd / 5000, 0.5 end
    function W.At(xYd) player.map = 1412 player.x, player.y = W.P(xYd) end
    function W.Wait(s) for _ = 1, math.floor(s / 0.5 + 0.5) do advance(0.5) end end
    function W.Node(id, name, xYd, extra)
        local x, y = W.P(xYd)
        local n = { id = id, name = name, type = "herb", x = x, y = y, count = 1, last = 1 }
        for k, v in pairs(extra or {}) do n[k] = v end
        return n
    end
    function W.Set(list)
        table.insert(list, W.Node("o1618", "Peacebloom", 2500, { item = 2447 })) -- a far next target
        ns.db.nodes[1412] = list
        ns.NotifyNodesChanged() advance(1)
    end
    function W.Loot(objectID, item, tag, event)
        loot = objectID and { { guid = ("GameObject-0-1-1-1-%d-%s"):format(objectID, tag or "ID0001"), item = item, qty = 2 } } or {}
        fire(event or "LOOT_READY")
        loot = {}
    end
    function W.Cast(target, spell)
        W.seq = W.seq + 1
        local id = "ident" .. W.seq
        fire("UNIT_SPELLCAST_SENT", "player", target, id, spell or 2366)
        return id
    end
    function W.Done(id, spell) fire("UNIT_SPELLCAST_SUCCEEDED", "player", id, spell or 2366) end
    function W.Count(name)
        local c = 0
        for _, n in ipairs(ns.db.nodes[1412]) do if n.name == name then c = c + 1 end end
        return c
    end
    function W.Restore()
        if ns.run then ns.StopRun(true) end
        ns.db.nodes[1412], ns.db.arriveDist = W.keepNodes, W.keepArrive
        player.map, player.x, player.y = W.map, W.x, W.y
        loot = {}
        ns.NotifyNodesChanged() advance(2)
    end
    return W
end
step("Recorder: a gather keeps its identity - late, empty, repeated or crossed loot (v0.1.14)", function()
    local W = IdentityWorld()
    local unknown = ns.L["Unknown Herb"]
    local function Fresh()
        local s = W.Node("o1617", "Silverleaf", 0, { item = 765 })
        W.Set({ s })
        W.At(0)
        return s
    end
    -- control: no target name, loot in time: it is the Silverleaf
    local s = Fresh()
    local id = W.Cast("") W.Wait(2) W.Done(id) advance(0.2) W.Loot(1617, 765, "C0001") W.Wait(3)
    assert(s.count == 2 and W.Count(unknown) == 0, "control: no-name gather with loot not on the Silverleaf")
    -- loot only 2.0 s after the cast (the recorder used to stop at 1.5 s): no Unknown Herb
    s = Fresh()
    id = W.Cast("") W.Wait(2) W.Done(id) advance(2.0) W.Loot(1617, 765, "C0002") W.Wait(3)
    assert(W.Count(unknown) == 0, "late loot: an Unknown Herb was stored")
    assert(s.count == 2 and (s.hits or 0) == 1, "late loot: the Silverleaf did not get its harvest")
    -- R3, a SIMULATED special case (not seen in the real client): an empty loot event first
    s = Fresh()
    id = W.Cast("") W.Wait(2) W.Done(id) advance(0.1) W.Loot(nil) advance(0.2) W.Loot(1617, 765, "C0003", "LOOT_OPENED") W.Wait(3)
    assert(W.Count(unknown) == 0 and s.count == 2, "empty first loot event: the identity got lost")
    -- the same loot twice (LOOT_READY + LOOT_OPENED): one record
    s = Fresh()
    id = W.Cast("Silverleaf") W.Wait(2) W.Done(id) W.Loot(1617, 765, "C0004") W.Loot(1617, 765, "C0004", "LOOT_OPENED") W.Wait(3)
    assert(s.count == 2 and (s.hits or 0) == 1, ("repeated loot event: count %d, hits %s"):format(s.count, tostring(s.hits)))
    -- the other Silverleaf object (o3725) fits a Silverleaf gather: same kind, other ID
    s = Fresh()
    id = W.Cast("Silverleaf") W.Wait(2) W.Done(id) W.Loot(3725, 765, "C0005") W.Wait(3)
    assert(W.Count("Silverleaf") >= 1 and W.Count(unknown) == 0, "second object of the same kind rejected")
    local fitted = false
    for _, n in ipairs(ns.db.nodes[1412]) do if n.id == "o3725" or (n == s and n.count == 2) then fitted = true end end
    assert(fitted, "Silverleaf o3725 loot was not used")
    -- no name and no loot at all: nothing recorded (after the 10 s upper bound)
    s = Fresh()
    local before = #ns.db.nodes[1412]
    id = W.Cast("") W.Wait(2) W.Done(id) W.Wait(12)
    assert(#ns.db.nodes[1412] == before and s.count == 1, "a gather without identity was stored")
    -- interrupted: nothing
    s = Fresh()
    id = W.Cast("") W.Wait(1) fire("UNIT_SPELLCAST_INTERRUPTED", "player", id, 2366) W.Wait(12)
    assert(#ns.db.nodes[1412] == before and s.count == 1, "an interrupted gather was stored")
    -- crossed: the next gather (Peacebloom, 8 yd) starts before the Silverleaf loot came
    s = Fresh()
    local p = W.Node("o1618", "Peacebloom", 8, { item = 2447 })
    table.insert(ns.db.nodes[1412], p) ns.NotifyNodesChanged() advance(1)
    local sx = s.x
    id = W.Cast("Silverleaf") W.Wait(2) W.Done(id)
    W.At(8)
    local id2 = W.Cast("Peacebloom")
    W.Loot(1617, 765, "C0006") -- the Silverleaf loot arrives now
    W.Wait(2) W.Done(id2) W.Loot(1618, 2447, "C0007") W.Wait(3)
    assert(s.count == 2 and math.abs(s.x - sx) < 1e-9, "crossed: the Silverleaf was not booked at its own spot")
    assert(p.count == 2, ("crossed: the Peacebloom was not booked (count %d)"):format(p.count))
    -- crossed without a name: the loot fits both (the first could be any herb):
    -- nobody can tell whose, so neither is booked
    s = Fresh()
    before = #ns.db.nodes[1412]
    id = W.Cast("") W.Wait(2) W.Done(id)
    id2 = W.Cast("Silverleaf") W.Wait(2) W.Done(id2) W.Loot(1617, 765, "C0008") W.Wait(12)
    assert(#ns.db.nodes[1412] == before and s.count == 1, "crossed without a name: a gather of uncertain loot was booked")
    -- only loot of another kind (a wrong name or someone else's loot): nothing rather than a wrong kind
    s = Fresh()
    before = #ns.db.nodes[1412]
    id = W.Cast("Silverleaf") W.Wait(2) W.Done(id) W.Loot(1618, 2447, "C0009") W.Wait(12)
    assert(#ns.db.nodes[1412] == before and s.count == 1, "loot of another kind: something was booked")
    -- Wilted Peacebloom (o656160) is its own Forever herb, even though its loot
    -- holds the Peacebloom item 2447 (the beta starter data says so)
    local function WiltedWorld(wiltedYd)
        local list = { W.Node("o1618", "Peacebloom", 5, { item = 2447 }) }
        if wiltedYd then table.insert(list, W.Node("o656160", "Wilted Peacebloom", wiltedYd, { item = 2447, source = "starter" })) end
        W.Set(list)
        W.At(0)
        return list[1], list[2]
    end
    local function Stats(key) local st = ns.KindStats()[key] return st and st.n or 0 end
    -- (a) named: booked on the Wilted record, never on the Peacebloom 5 yd away
    local pb, wp = WiltedWorld(3)
    local pbStats, wpStats = Stats("herb:peacebloom"), Stats("herb:wilted peacebloom")
    id = W.Cast("Wilted Peacebloom") W.Wait(2) W.Done(id) W.Loot(656160, 2447, "WP0001") W.Wait(3)
    assert(wp.count == 2 and pb.count == 1, ("Wilted gather booked on: wilted %d, peacebloom %d"):format(wp.count, pb.count))
    assert(Stats("herb:wilted peacebloom") == wpStats + 1 and Stats("herb:peacebloom") == pbStats, "Wilted skill stats mixed with Peacebloom")
    -- (b) no name: the name our records give the object, not the item's
    pb, wp = WiltedWorld(60)
    before = #ns.db.nodes[1412]
    id = W.Cast("") W.Wait(2) W.Done(id) W.Loot(656160, 2447, "WP0002") W.Wait(3)
    local new = ns.db.nodes[1412][#ns.db.nodes[1412]]
    assert(#ns.db.nodes[1412] == before + 1 and new.name == "Wilted Peacebloom" and new.id == "o656160" and pb.count == 1,
        ("no-name Wilted gather: %s [%s], peacebloom count %d"):format(tostring(new.name), tostring(new.id), pb.count))
    -- (c) no name, no record of the object in the zone: still not a Peacebloom
    pb = WiltedWorld(nil)
    id = W.Cast("") W.Wait(2) W.Done(id) W.Loot(656160, 2447, "WP0003") W.Wait(3)
    new = ns.db.nodes[1412][#ns.db.nodes[1412]]
    assert(pb.count == 1 and new.id == "o656160" and new.name ~= "Peacebloom", "unnamed Wilted gather became a Peacebloom")
    -- (d) crossed: late Wilted loot does not fit a Peacebloom gather
    pb, wp = WiltedWorld(3)
    id = W.Cast("Wilted Peacebloom") W.Wait(2) W.Done(id)
    W.At(5)
    id2 = W.Cast("Peacebloom")
    W.Loot(656160, 2447, "WP0004")
    W.Wait(2) W.Done(id2) W.Loot(1618, 2447, "PB0004") W.Wait(3)
    -- the Wilted loot fits only the Wilted gather still waiting: it is its own, booked there
    assert(pb.count == 2 and pb.lastSpawn == "PB0004" and wp.count == 2 and wp.lastSpawn == "WP0004",
        "crossed Wilted/Peacebloom: loot of the one booked on the other")
    -- (e) a Peacebloom gather that only gets Wilted loot (no earlier gather waiting):
    -- the kind check alone must reject it - nothing booked, no Peacebloom with o656160
    pb, wp = WiltedWorld(3)
    before = #ns.db.nodes[1412]
    id = W.Cast("Peacebloom") W.Wait(2) W.Done(id) W.Loot(656160, 2447, "WP0005") W.Wait(12)
    assert(#ns.db.nodes[1412] == before and pb.count == 1 and wp.count == 1 and pb.id == "o1618",
        "a Peacebloom gather took Wilted Peacebloom loot")
    -- crossed, same kind: Silverleaf A, then Silverleaf B 8 yd on before A's loot came.
    -- Same kind is not enough to know whose loot it is: neither is booked (no
    -- count, no spawn, no skill stat) rather than a guess
    local a = W.Node("o1617", "Silverleaf", 0, { item = 765 })
    local b = W.Node("o1617", "Silverleaf", 8, { item = 765 })
    W.Set({ a, b })
    local ax, bx = a.x, b.x
    local slStats = Stats("herb:silverleaf")
    W.At(0)
    id = W.Cast("Silverleaf") W.Wait(2) W.Done(id)
    W.At(8)
    id2 = W.Cast("Silverleaf") W.Wait(2) W.Done(id2)
    W.Loot(1617, 765, "SLA001") W.Loot(1617, 765, "SLA001", "LOOT_OPENED") -- A's loot, late, twice
    W.Loot(1617, 765, "SLB001") W.Loot(1617, 765, "SLB001", "LOOT_OPENED") -- B's own, twice
    W.Wait(12)
    assert(a.count == 1 and b.count == 1 and Stats("herb:silverleaf") == slStats,
        ("same kind crossed: A %d, B %d, stats +%d"):format(a.count, b.count, Stats("herb:silverleaf") - slStats))
    assert(math.abs(a.x - ax) < 1e-9 and math.abs(b.x - bx) < 1e-9, "same kind crossed: a spot moved")
    assert(not a.lastSpawn and not b.lastSpawn, "same kind crossed: a spawn of uncertain owner was booked")
    -- three Silverleafs, each cast before the loot of the one before, every loot
    -- twice: no count, hit or skill stat grows more than once per gather (here: none)
    local three = { W.Node("o1617", "Silverleaf", 0, { item = 765 }), W.Node("o1617", "Silverleaf", 8, { item = 765 }),
        W.Node("o1617", "Silverleaf", 16, { item = 765 }) }
    W.Set({ three[1], three[2], three[3] })
    slStats = Stats("herb:silverleaf")
    for i = 1, 3 do
        W.At((i - 1) * 8)
        local c = W.Cast("Silverleaf") W.Wait(2) W.Done(c)
        if i > 1 then W.Loot(1617, 765, "TRI" .. (i - 1)) W.Loot(1617, 765, "TRI" .. (i - 1), "LOOT_OPENED") end
    end
    W.Loot(1617, 765, "TRI3") W.Loot(1617, 765, "TRI3", "LOOT_OPENED")
    W.Wait(13)
    local grew = 0
    for _, n in ipairs(three) do
        assert(n.count <= 2 and (n.hits or 0) <= 1, "three crossed: a node grew more than once")
        grew = grew + n.count - 1
    end
    assert(grew == Stats("herb:silverleaf") - slStats and grew <= 3, ("three crossed: counts +%d, stats +%d"):format(
        grew, Stats("herb:silverleaf") - slStats))
    -- one copper vein mined three times (one spawn), every loot twice: counted once
    -- when the loot comes in time, at most once (here: dropped) when it comes late
    for _, late in ipairs({ false, true }) do
        local v = W.Node("o1731", "Copper Vein", 0, { type = "ore", item = 2770 })
        W.Set({ v })
        W.At(0)
        local st = Stats("ore:copper vein")
        for i = 1, 3 do
            local c = W.Cast("Copper Vein", 2575) W.Wait(2) W.Done(c, 2575)
            if not late then
                W.Loot(1731, 2770, "VEIN01") W.Loot(1731, 2770, "VEIN01", "LOOT_OPENED") W.Wait(1)
            elseif i > 1 then
                W.Loot(1731, 2770, "VEIN01") W.Loot(1731, 2770, "VEIN01", "LOOT_OPENED")
            end
        end
        if late then W.Loot(1731, 2770, "VEIN01") W.Loot(1731, 2770, "VEIN01", "LOOT_OPENED") end
        W.Wait(13)
        local grown = Stats("ore:copper vein") - st
        assert(v.count - 1 <= 1 and (v.hits or 0) <= 1 and grown <= 1,
            ("vein mined 3x (loot %s): count +%d, hits %s, stats +%d"):format(late and "late" or "in time", v.count - 1, tostring(v.hits), grown))
        if not late then assert(v.count == 2 and grown == 1, "vein mined 3x, loot in time: not counted once") end
    end
    -- one rule: booked only with its own loot. The same vein mined three times
    -- without any loot event: nothing booked, no count, hit or skill stat
    do
        local v = W.Node("o1731", "Copper Vein", 0, { type = "ore", item = 2770 })
        W.Set({ v })
        W.At(0)
        local st = Stats("ore:copper vein")
        for _ = 1, 3 do
            local c = W.Cast("Copper Vein", 2575) W.Wait(2) W.Done(c, 2575) W.Wait(4)
        end
        W.Wait(12)
        assert(v.count == 1 and not v.hits and Stats("ore:copper vein") == st and #ns.db.nodes[1412] == 2,
            ("vein mined 3x without loot: count +%d, hits %s, stats +%d"):format(v.count - 1, tostring(v.hits), Stats("ore:copper vein") - st))
    end
    -- a single herb, its own loot late (5 s) but clear: booked once, with its spawn
    do
        local sl = W.Node("o1617", "Silverleaf", 0, { item = 765 })
        W.Set({ sl })
        W.At(0)
        local st = Stats("herb:silverleaf")
        local c = W.Cast("Silverleaf") W.Wait(2) W.Done(c) W.Wait(5)
        W.Loot(1617, 765, "LATE01") W.Loot(1617, 765, "LATE01", "LOOT_OPENED") W.Wait(12)
        assert(sl.count == 2 and sl.hits == 1 and sl.lastSpawn == "LATE01" and Stats("herb:silverleaf") == st + 1,
            ("single herb, late loot: count +%d, hits %s, spawn %s, stats +%d"):format(sl.count - 1, tostring(sl.hits),
                tostring(sl.lastSpawn), Stats("herb:silverleaf") - st))
    end
    -- unchanged: loot in time is booked at once (no 10 s wait), every loot event twice counts once
    do
        local sl = W.Node("o1617", "Silverleaf", 0, { item = 765 })
        W.Set({ sl })
        W.At(0)
        local st = Stats("herb:silverleaf")
        local c = W.Cast("Silverleaf") W.Wait(2) W.Done(c)
        W.Loot(1617, 765, "NOW001") W.Loot(1617, 765, "NOW001", "LOOT_OPENED")
        assert(sl.count == 2 and sl.lastSpawn == "NOW001", "loot in time: not booked at once")
        W.Wait(12)
        assert(sl.count == 2 and sl.hits == 1 and Stats("herb:silverleaf") == st + 1, "loot in time, twice: counted more than once")
    end
    -- the object name lookup uses the zone index: a new record's name is found
    -- at once, and a renamed record too (index kept up to date)
    local o = W.Node("o987654", "Shimmer Moss", 30, { item = 2447 })
    W.Set({ o })
    assert(ns.ObjectName(987654, 1412) == "Shimmer Moss", "object name not found")
    local o2 = W.Node("o987655", "Glow Cap", 40, { item = 2447 })
    table.insert(ns.db.nodes[1412], o2) ns.NotifyNodesChanged("add", 1412, o2)
    assert(ns.ObjectName(987655, 1412) == "Glow Cap", "object name of a new record not found")
    W.Restore()
end)
step("Run: points without identity learn nothing; known kinds stay apart (v0.1.14)", function()
    local W = IdentityWorld()
    ns.db.arriveDist = 20
    local function Run(list)
        W.Set(list)
        W.At(-200) ns.StartRun("herb", 1412) W.Wait(1)
        W.At(-15) W.Wait(1)
    end
    local function Harvest(objectID, item, name)
        local id = W.Cast(name) W.Wait(2) W.Done(id) W.Loot(objectID, item, "R" .. W.seq) W.Wait(1)
    end
    -- the log case: Silverleaf gathered, an old Unknown Herb [nil] 8 yd away
    local s = W.Node("o1617", "Silverleaf", 0, { item = 765, source = "questie", count = 0 })
    local u = W.Node(nil, "Unknown Herb", 6)
    Run({ s, u })
    W.At(-1) W.Wait(10)
    Harvest(1617, 765, "Silverleaf")
    W.Wait(30)
    assert(not u.misses and not u.emptyStreak and not u.hits, "unknown point next to a harvest learned something")
    ns.StopRun(true)
    -- nothing harvested: an unknown point only rests, it learns nothing
    u = W.Node(nil, "Unknown Herb", 0)
    Run({ u })
    W.At(-1) W.Wait(30)
    assert(not u.misses and not u.emptyStreak and ns.IsOnCooldown(u), "unknown point without harvest: should only rest")
    ns.StopRun(true)
    -- known kinds stay apart: an empty Peacebloom 8 yd from a harvested Silverleaf is empty
    s = W.Node("o1617", "Silverleaf", 0, { item = 765 })
    local pb = W.Node("o1618", "Peacebloom", 8, { item = 2447 })
    Run({ s, pb })
    W.At(-1) W.Wait(2)
    Harvest(1617, 765, "Silverleaf")
    W.At(60) W.Wait(30)
    assert(pb.misses == 1, "an empty known Peacebloom next to a Silverleaf harvest was not learned")
    ns.StopRun(true)
    -- Wilted Peacebloom is another herb: its harvest does not cover an empty Peacebloom point
    local wp = W.Node("o656160", "Wilted Peacebloom", 0, { item = 2447 })
    pb = W.Node("o1618", "Peacebloom", 8, { item = 2447 })
    Run({ wp, pb })
    W.At(-1) W.Wait(2)
    Harvest(656160, 2447, "Wilted Peacebloom")
    W.At(60) W.Wait(30)
    assert(pb.misses == 1 and not wp.misses, "a Wilted Peacebloom harvest counted for the Peacebloom point")
    ns.StopRun(true)
    -- an ore harvest does not cover an unknown herb point
    u = W.Node(nil, "Unknown Herb", 0)
    local v = W.Node("o1731", "Copper Vein", 8, { type = "ore", item = 2770 })
    W.Set({ u, v })
    W.At(-200) ns.StartRun(nil, 1412) W.Wait(1) W.At(-15) W.Wait(1)
    W.At(8) W.Wait(2)
    local id = W.Cast("Copper Vein", 2575) W.Wait(2) W.Done(id, 2575) W.Loot(1731, 2770, "R0") W.Wait(1)
    W.At(60) W.Wait(30)
    assert(not u.misses and ns.IsOnCooldown(u), "unknown herb: an ore harvest should not count, a rest only")
    W.Restore()
end)
step("Sync: parking or unparking one node changes only its pins and the route list (v0.1.14)", function()
    local Z = 1412
    local pins = LibStub("HereBeDragons-Pins-2.0")
    local keep = { pins.AddWorldMapIconMap, pins.RemoveWorldMapIcon, pins.AddMinimapIconMap, pins.RemoveMinimapIcon }
    local adds, active = 0, {}
    pins.AddWorldMapIconMap = function(self, ref, icon, ...)
        if ref == "Gathercraft" then adds = adds + 1 active[icon] = "world" end
        return keep[1](self, ref, icon, ...)
    end
    pins.RemoveWorldMapIcon = function(self, ref, icon, ...) if ref == "Gathercraft" then active[icon] = nil end return keep[2](self, ref, icon, ...) end
    pins.AddMinimapIconMap = function(self, ref, icon, ...)
        if ref == "Gathercraft" then adds = adds + 1 active[icon] = "mini" end
        return keep[3](self, ref, icon, ...)
    end
    pins.RemoveMinimapIcon = function(self, ref, icon, ...) if ref == "Gathercraft" then active[icon] = nil end return keep[4](self, ref, icon, ...) end
    local notified = {}
    local Notify = ns.NotifyNodesChanged
    ns.NotifyNodesChanged = function(kind, ...) notified[#notified + 1] = tostring(kind) return Notify(kind, ...) end
    local function Count() adds = 0 wipe(notified) end
    -- what the map shows: per node and pin kind ring, colour, level, alpha, kinds sharing the spot
    local function Look()
        local out = {}
        for icon, where in pairs(active) do
            local ring, c = icon.ring, icon.ring and icon.ring.__color
            local key = tostring(icon.node and icon.node.name) .. "@" .. tostring(icon.node) .. ":" .. where
            out[key] = ("%s|%s|%s|%.2f|%d"):format(tostring(ring and ring.__tex), c and ("%.2f,%.2f,%.2f"):format(c[1], c[2], c[3]) or "-",
                tostring(icon.level), icon:GetAlpha(), #(icon.others or (icon.othersOf and icon.othersOf.others) or {}))
        end
        return out
    end
    local function RouteLook()
        local set = {}
        for _, p in ipairs(ns.run and ns.run.points or {}) do set[p.node] = true end
        return set, ns.run and ns.run.target
    end
    -- the targeted update against a full rebuild of pins and route list
    local function SameAsRebuild(what)
        local look, route, tgt = Look(), RouteLook()
        ns.TogglePins() ns.TogglePins()
        if ns.run then ns.run.pointsDirty = true ns.RouteGoalChanged() end
        advance(1)
        local look2, route2, tgt2 = Look(), RouteLook()
        for k, v in pairs(look) do assert(look2[k] == v, ("%s: %s is %s, after a rebuild %s"):format(what, k, v, tostring(look2[k]))) end
        for k, v in pairs(look2) do assert(look[k] == v, ("%s: %s only after a rebuild (%s)"):format(what, k, v)) end
        for n in pairs(route) do assert(route2[n], what .. ": in the route list only before the rebuild: " .. tostring(n.name)) end
        for n in pairs(route2) do assert(route[n], what .. ": in the route list only after the rebuild: " .. tostring(n.name)) end
        assert(tgt == tgt2, what .. ": another target after the rebuild")
    end
    local function AllUpdates(what)
        for _, k in ipairs(notified) do assert(k == "update", what .. ": told everyone '" .. k .. "' (all pins are rebuilt)") end
    end

    local keepNodes = ns.db.nodes[Z]
    ns.db.nodes[Z] = {}
    ns.ImportQuestieZone(Z, true)
    -- a node only other players reported, empty four times over 13 hours
    local S = { id = "o1618", name = "Peacebloom", type = "herb", x = 0.3012, y = 0.2987, count = 1, last = time() - 50000,
        item = 2447, source = "sync", heard = 1, heardBy = { Alice = true } }
    local function Unlucky() S.healMisses, S.healFirst, S.healAt = 4, time() - 13 * 3600, time() - 700 end
    Unlucky()
    table.insert(ns.db.nodes[Z], S)
    -- one of our own further on: the run keeps a target after S (the empty
    -- check after arriving only runs while there is one)
    table.insert(ns.db.nodes[Z], { id = "o1618", name = "Peacebloom", type = "herb", x = S.x + 300 / 5000, y = S.y, count = 2, last = 1, item = 2447 })
    ns.NotifyNodesChanged() ns.ForgetSeenKinds()
    player.map, player.x, player.y = Z, S.x + 30 / 5000, S.y
    ns.StartRun("herb", Z) advance(1)
    assert(ns.run and ns.run.target == S, "test setup: the shared node is the target")

    -- (1) parked by SelfHeal: arrived, nothing there for 25 s
    Count()
    player.x = S.x advance(27)
    assert(S.parked, "not parked after the fifth empty visit")
    AllUpdates("parked")
    assert(adds <= 2, ("parking one node registered %d pins"):format(adds))
    local route = RouteLook()
    assert(not route[S] and ns.run.target ~= S, "the parked node is still in the route list or the target")
    local look = Look()
    local w = look["Peacebloom@" .. tostring(S) .. ":world"]
    assert(w and w:find("|0.25|", 1, true), "parked node not faded on the world map: " .. tostring(w))
    SameAsRebuild("parked")
    -- the same again: nothing changes
    Count()
    assert(not ns.SyncSelfHeal(S), "parked twice")
    advance(1)
    assert(adds == 0 and #notified == 0, "parking again changed something")

    -- (2) back through sync: someone new reports it
    local text = ("N:%d;o1618,h,%d,%d,2447"):format(Z, math.floor(S.x * 10000 + 0.5), math.floor(S.y * 10000 + 0.5))
    Count()
    fire("CHAT_MSG_ADDON", "Gathercraft", text, "CHANNEL", "Newcomer-Realm") advance(1)
    assert(not S.parked, "not back after a new player reported it")
    AllUpdates("back by sync")
    assert(adds <= 2, ("unparking one node registered %d pins"):format(adds))
    assert(RouteLook()[S], "the node is back but not in the route list")
    SameAsRebuild("back by sync")
    -- the same message again, and one more player: nothing to change
    Count()
    fire("CHAT_MSG_ADDON", "Gathercraft", text, "CHANNEL", "Newcomer-Realm") advance(2)
    fire("CHAT_MSG_ADDON", "Gathercraft", text, "CHANNEL", "Another-Realm") advance(1)
    assert(adds == 0 and #notified == 0, "a report of a node that is back changed something")

    -- (3) parked again, back by a look on the minimap
    Unlucky()
    Count()
    assert(ns.SyncSelfHeal(S) and S.parked, "test setup: parked again")
    advance(1)
    AllUpdates("parked again")
    assert(adds <= 2 and not RouteLook()[S], "parked again: pins or route list")
    advance(6)
    Count()
    ns.SeenOnMinimap(Z, S.x, S.y, S.name, 10) advance(1)
    assert(not S.parked, "not back after a look on the minimap")
    AllUpdates("back by a look")
    assert(adds <= 4, ("unparking by a look registered %d pins"):format(adds))
    assert(RouteLook()[S], "back by a look but not in the route list")
    SameAsRebuild("back by a look")
    -- seen with your own eyes: never parked again
    Unlucky()
    Count()
    assert(not ns.SyncSelfHeal(S) and not S.parked, "a node seen on the minimap was parked")
    advance(1)
    assert(adds == 0 and #notified == 0, "a refused park changed something")

    -- (4) the map follows the Zones tab and the zone is off: no pins, before and after
    ns.StopRun() advance(1)
    S.seenAt, S.upAt = nil, nil
    ns.db.mapFollowsZones, ns.db.disabledZones[Z] = true, true
    ns.TogglePins() ns.TogglePins() advance(1)
    Unlucky()
    Count()
    assert(ns.SyncSelfHeal(S) and S.parked, "test setup: parked in a zone that is off")
    advance(1)
    assert(adds == 0, "a node of a zone that is off got pins")
    SameAsRebuild("zone off")
    ns.db.mapFollowsZones, ns.db.disabledZones[Z] = nil, nil

    ns.NotifyNodesChanged = Notify
    pins.AddWorldMapIconMap, pins.RemoveWorldMapIcon, pins.AddMinimapIconMap, pins.RemoveMinimapIcon = keep[1], keep[2], keep[3], keep[4]
    ns.db.nodes[Z] = keepNodes
    ns.NotifyNodesChanged() ns.ForgetSeenKinds()
    player.map, player.x, player.y = 1412, 0.45, 0.72
    advance(1)
end)
step("Run: checks after arriving come due also while the run has no target (v0.1.14)", function()
    local Z = 1471
    local saved = { debug = ns.db.debug, arrive = ns.db.arriveDist }
    ns.db.debug, ns.db.arriveDist = true, 20
    local seq = 0
    -- one route point only: once it is reached, the run has no target
    local function Setup()
        ns.StopRun() advance(1)
        local S = { id = "o1618", name = "Peacebloom", type = "herb", x = 0.50, y = 0.50, count = 3, last = 1, item = 2447 }
        ns.db.nodes[Z] = { S }
        ns.NotifyNodesChanged() ns.ForgetSeenKinds()
        player.map, player.x, player.y = Z, 0.50 + 60 / 5000, 0.50
        ns.StartRun("herb", Z) advance(1)
        assert(ns.run and ns.run.target == S, "test setup: target")
        player.x = 0.50 advance(1)
        assert(not ns.run.target and #ns.run.checking == 1, "test setup: reached, no target, one check open")
        return S, #log
    end
    local function Cast()
        seq = seq + 1
        fire("UNIT_SPELLCAST_SENT", "player", "Peacebloom", "nt" .. seq, 2366)
        return "nt" .. seq
    end
    local function Loot(id)
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", id, 2366)
        loot = { { guid = ("GameObject-0-1-1-1-1618-NT%04d"):format(seq), item = 2447, qty = 2 } }
        fire("LOOT_READY") loot = {}
    end
    local function Said(text, from)
        for i = from, #log do if log[i]:find(text, 1, true) then return true end end
    end

    -- (a) really empty: counted as empty, and the run goes on (it used to wait
    -- for the open check until it gave up after 10 minutes)
    local S, mark = Setup()
    advance(30)
    assert(S.misses == 1 and ns.IsOnCooldown(S), "an empty point was not counted as empty while the run had no target")
    assert(Said("since arriving 25 s ago (target, no combat)", mark), "no check line for the empty point")
    assert(#ns.run.checking == 0, "the check is still open")
    advance(600)
    assert(ns.run, "the run gave up although its point came back")

    -- (b) harvested: the check closes as harvested, nothing counted as empty
    S, mark = Setup()
    local id = Cast() advance(2) Loot(id)
    advance(30)
    assert(S.hits == 1 and not S.misses and Said("harvested (this node", mark), "harvest without a target: not checked as harvested")
    assert(#ns.run.checking == 0, "harvested: the check is still open")

    -- (c) a gather still running when the check comes due: waited for, then harvested
    S, mark = Setup()
    advance(21)
    id = Cast() advance(5)
    assert(Said("still gathering", mark) and not S.misses, "a running gather was not waited for")
    Loot(id) advance(5)
    assert(S.hits == 1 and not S.misses and Said("harvested (this node", mark), "harvested after waiting: not checked as harvested")

    -- (d) a gather that succeeded without loot of its own: not judged, nothing learned
    S, mark = Setup()
    id = Cast() advance(2) fire("UNIT_SPELLCAST_SUCCEEDED", "player", id, 2366)
    advance(30)
    assert(Said("not judged, nothing learned", mark) and not S.misses and not S.hits, "an uncertain gather was judged")

    -- (e) stopped before the check came due: nothing is judged afterwards
    S, mark = Setup()
    advance(5)
    ns.StopRun() advance(40)
    assert(not S.misses and not ns.IsOnCooldown(S) and not Said("check Peacebloom", mark), "a check was judged after the run stopped")

    ns.db.debug, ns.db.arriveDist = saved.debug, saved.arrive
    ns.db.nodes[Z] = nil
    ns.NotifyNodesChanged()
    player.map, player.x, player.y = 1412, 0.45, 0.72
    advance(1)
end)
step("Run: spots from other players are taken in together, ones the run can't use not at all (v0.1.14)", function()
    local keep = { [1412] = ns.db.nodes[1412], [1413] = ns.db.nodes[1413], [1429] = ns.db.nodes[1429] }
    local saved = { skill = PROFS[1][2], max = PROFS[1][3], disabled = ns.db.disabledZones[1413] }
    ns.db.nodes[1412], ns.db.nodes[1413], ns.db.nodes[1429] = {}, {}, {}
    -- a few of our own, so the run has something to do
    for i = 1, 6 do
        table.insert(ns.db.nodes[1412], { id = "o1618", name = "Peacebloom", type = "herb", x = 0.30 + i * 0.02, y = 0.30, count = 2, last = 1, item = 2447 })
    end
    ns.NotifyNodesChanged() ns.ForgetSeenKinds()
    local briar
    for id, k in pairs(GathercraftQuestieData.kinds) do if k[3] == "Briarthorn" then briar = id end end
    -- the node list of the run: how often it was collected again
    local collects, lastPoints = 0, nil
    local watch = C_Timer.NewTicker(0.05, function()
        local r = ns.run
        if r and r.points ~= lastPoints then
            if lastPoints then collects = collects + 1 end
            lastPoints = r.points
        end
    end)
    local function InRun(n)
        for _, p in ipairs(ns.run and ns.run.points or {}) do if p.node == n then return true end end
    end
    local senders = 0
    local function Import(mapID, entries)
        senders = senders + 1 -- one guild member per message: the rate limit stays out of it
        local parts = {}
        for i, e in ipairs(entries) do
            parts[i] = ("%s,%s,%d,%d,%d"):format(e[1], e[2], math.floor(e[3] * 10000 + 0.5), math.floor(e[4] * 10000 + 0.5), e[5] or 0)
        end
        fire("CHAT_MSG_ADDON", "Gathercraft", "N:" .. mapID .. ";" .. table.concat(parts, ";"), "GUILD", "Guild" .. senders .. "-Realm")
    end
    local function Find(mapID, id, x, y) return ns.FindNode(mapID, id, x, y, 5) end
    local function Start(filter, zone)
        ns.StopRun() advance(1)
        player.map, player.x, player.y = 1412, 0.30, 0.32
        ns.StartRun(filter, zone) advance(2)
        assert(ns.run and ns.run.points, "test setup: no run")
        lastPoints, collects = ns.run.points, 0
    end

    -- (1) spots this run can't use: stored and on the map, the run's list stays as it is
    Start("herb", 1412)
    PIN_ADDS = 0
    Import(1412, { { "o1731", "o", 0.40, 0.40, 2770 } }) advance(1.2)  -- ore: another type
    Import(1413, { { "o1618", "h", 0.40, 0.40, 2447 } }) advance(1.2)  -- herb, but another zone
    Import(1429, { { "o1618", "h", 0.40, 0.40, 2447 } }) advance(1.2)  -- herb, another continent
    advance(15)
    assert(Find(1412, "o1731", 0.40, 0.40) and Find(1413, "o1618", 0.40, 0.40) and Find(1429, "o1618", 0.40, 0.40), "an import was not stored")
    assert(PIN_ADDS >= 3, "an import was not shown on the map")
    assert(collects == 0, ("spots the run can't use collected its list again %d times"):format(collects))
    -- a run over all zones: another continent is another world (the mini WoW
    -- has one world for all maps, so Elwynn Forest gets instance 0 here)
    local HBD = LibStub("HereBeDragons-2.0")
    local Coords = HBD.GetWorldCoordinatesFromZone
    HBD.GetWorldCoordinatesFromZone = function(self, x, y, map)
        local wx, wy, inst = Coords(self, x, y, map)
        return wx, wy, map == 1429 and 0 or inst
    end
    Start("herb")
    Import(1429, { { "o1618", "h", 0.45, 0.45, 2447 } }) advance(12)
    HBD.GetWorldCoordinatesFromZone = Coords
    assert(Find(1429, "o1618", 0.45, 0.45) and collects == 0, "a spot on another continent collected the list of a run over all zones")

    -- (2) a stream of usable ones (30 s): taken in together, each at the latest 10 s after it came
    local arrived, n = {}, 0
    local late = 0
    local check = C_Timer.NewTicker(0.5, function()
        for node, t in pairs(arrived) do
            if not InRun(node) and GetTime() - t > 10.5 then late = late + 1 arrived[node] = nil end
            if InRun(node) then arrived[node] = nil end
        end
    end)
    for k = 1, 25 do
        local entries = {}
        for j = 1, 6 do
            n = n + 1
            entries[j] = { "o1618", "h", 0.10 + (n % 30) * 0.02, 0.50 + math.floor(n / 30) * 0.02, 2447 }
        end
        Import(1412, entries)
        for _, e in ipairs(entries) do
            local node = Find(1412, e[1], e[3], e[4])
            assert(node, "test setup: import not stored")
            arrived[node] = GetTime()
        end
        advance(1.2)
    end
    advance(12)
    check:Cancel()
    assert(late == 0, late .. " imported spots were not in the run 10 s after they came")
    assert(next(arrived) == nil, "imported spots never reached the run")
    assert(collects >= 3 and collects <= 4, ("25 messages in 30 s: the list was collected %d times (expected 3-4)"):format(collects))

    -- (3) spots that did not fit count once the run fits them: filter, zone, skill
    Start("ore", 1412)
    assert(InRun(Find(1412, "o1731", 0.40, 0.40)), "after a filter change: the ore vein that came during a herb run is missing")
    Start("herb", 1413)
    assert(InRun(Find(1413, "o1618", 0.40, 0.40)), "a run in the other zone: its imported herb is missing")
    ns.db.disabledZones[1413] = true
    Start("herb")
    Import(1413, { { "o1618", "h", 0.60, 0.60, 2447 } }) advance(12)
    assert(collects == 0, "a spot in a zone switched off collected the list again")
    ns.db.disabledZones[1413] = nil
    ns.NotifyNodesChanged() advance(1) -- the Zones tab: zone back on
    assert(InRun(Find(1413, "o1618", 0.60, 0.60)), "zone switched on again: its imported herb is missing")
    PROFS[1][2] = 40 -- Herbalism 40: Briarthorn (70) can't be gathered yet
    Start("herb", 1412)
    Import(1412, { { briar, "h", 0.70, 0.70, 2450 } }) advance(11)
    local b = Find(1412, briar, 0.70, 0.70)
    assert(InRun(b), "a Briarthorn import is not in the run's list")
    local bp
    for _, p in ipairs(ns.run.points) do if p.node == b then bp = p end end
    assert((ns.run.weights[bp.kind] or 0) == 0, "test setup: Briarthorn at skill 40 is not left out")
    -- the weights are worked out again with the next plan after 30 s (riding on)
    PROFS[1][2], PROFS[1][3] = 100, 300 advance(31)
    player.x = player.x + 60 / 5000 advance(1)
    assert((ns.run.weights[bp.kind] or 0) > 0, "after the skill went up: the imported Briarthorn is still left out")

    -- (4) our own harvest of a new spot: in the run at once, as before
    Start("herb", 1412)
    player.x, player.y = 0.90, 0.90
    fire("UNIT_SPELLCAST_SENT", "player", "Peacebloom", "imp1", 2366)
    fire("UNIT_SPELLCAST_SUCCEEDED", "player", "imp1", 2366)
    loot = { { guid = "GameObject-0-1-1-1-1618-IMP001", item = 2447, qty = 2 } }
    fire("LOOT_READY") loot = {} advance(1)
    local own = Find(1412, "o1618", 0.90, 0.90)
    assert(own and not own.source and InRun(own), "our own new spot is not in the run a second later")

    watch:Cancel()
    ns.StopRun()
    for m, list in pairs(keep) do ns.db.nodes[m] = list end
    ns.db.disabledZones[1413] = saved.disabled
    PROFS[1][2], PROFS[1][3] = saved.skill, saved.max
    ns.NotifyNodesChanged() ns.ForgetSeenKinds()
    player.map, player.x, player.y = 1412, 0.45, 0.72
    advance(1)
end)
longStep("Self-healing: one empty visit per stay at a spot, not one per check (v0.1.14)", function()
    local Z = 1471
    local saved = { arrive = ns.db.arriveDist }
    ns.db.arriveDist = 25 -- gone from the spot = more than 2 x max(25, 30) = 60 yd
    local S
    local function Setup()
        ns.StopRun() advance(1)
        S = { id = "o1618", name = "Peacebloom", type = "herb", x = 0.50, y = 0.50, count = 1, last = 1, item = 2447,
            source = "sync", heard = 1, heardBy = { Alice = true } }
        ns.db.nodes[Z] = { S }
        ns.NotifyNodesChanged() ns.ForgetSeenKinds()
        player.map, player.x, player.y = Z, 0.50, 0.50
        ns.StartRun("herb", Z) advance(30)
        assert(S.healMisses == 1 and S.healStay, "test setup: the first empty visit did not count")
    end
    local function At(yards) player.x = 0.50 + yards / 5000 end

    -- (1) standing there for two hours: the checks go on (each one gives the
    -- point its rest), the point learns "empty" once (experiment O1), and
    -- self-healing counts the stay once
    local dbg = ns.db.debug
    ns.db.debug = true
    Setup()
    local mark = #log
    advance(7200)
    ns.db.debug = dbg
    local again = 0
    for i = mark, #log do if log[i]:find("the same stay, rest only", 1, true) then again = again + 1 end end
    assert(ns.run and again >= 10, "the checks stopped while standing there: " .. again .. " checks")
    assert(S.misses == 1, "two hours at one spot: the point learned 'empty' " .. tostring(S.misses) .. " times")
    assert(S.healMisses == 1 and not S.parked, ("two hours at one spot counted %d empty visits"):format(S.healMisses))

    -- (2) moving about at the spot, also past the arrival radius (25 yd) and
    -- the empty check radius (30 yd), but never 60 yd away: the same stay
    Setup()
    for _ = 1, 20 do
        At(45) advance(150) At(55) advance(150) At(10) advance(150)
    end
    assert(S.healMisses == 1, ("small moves at the spot counted %d empty visits"):format(S.healMisses))

    -- (3) gone and back: a new visit, under the old time limits
    Setup()
    At(100) advance(2) -- 100 yd away: gone
    assert(not S.healStay, "100 yd away is not gone from the spot")
    At(0) advance(30) -- back within 10 minutes of the counted visit: too soon
    assert(S.healMisses == 1, "back after a minute counted a new empty visit (10 minutes apart at least)")
    At(100) advance(700) -- away for longer than 10 minutes
    At(0) advance(30)
    assert(S.healMisses == 2, ("gone for 12 minutes and back: %s empty visits counted (expected 2)"):format(tostring(S.healMisses)))
    advance(1800) -- and again a long stay: still 2
    assert(S.healMisses == 2, "the second stay counted more than once")

    -- (4) a stop and a new run at the same spot are still the same stay
    Setup()
    ns.StopRun() advance(700)
    ns.StartRun("herb", Z) advance(60)
    assert(S.healStay and S.healMisses == 1, "a new run at the same spot counted a new empty visit")
    -- ... also without a run while you wait: only being seen away counts
    ns.StopRun() At(200) advance(5) At(0) advance(700)
    ns.StartRun("herb", Z) advance(60)
    assert(S.healMisses == 1, "away and back without a run in between counted a new empty visit")
    At(100) advance(2) At(0) advance(180) -- back; the point's 2 minute rest runs out, then it is checked
    assert(S.healMisses == 2, "gone during a run and back: not counted")

    ns.StopRun()
    ns.db.arriveDist = saved.arrive
    ns.db.nodes[Z] = nil
    ns.NotifyNodesChanged()
    player.map, player.x, player.y = 1412, 0.45, 0.72
    advance(1)
end)
longStep("Experiment O1: a point learns 'empty' once per stay, the checks and rests go on", function()
    local Z = 1471
    local saved = { arrive = ns.db.arriveDist, debug = ns.db.debug }
    ns.db.arriveDist, ns.db.debug = 25, true -- gone from the spot = more than 60 yd
    local S, seq = nil, 0
    local function At(yards) player.x = 0.50 + yards / 5000 end
    -- one point of our own: once it is reached, the run has no target
    local function Setup()
        ns.StopRun() advance(1)
        S = { id = "o1618", name = "Peacebloom", type = "herb", x = 0.50, y = 0.50, count = 3, last = 1, item = 2447 }
        ns.db.nodes[Z] = { S }
        ns.NotifyNodesChanged() ns.ForgetSeenKinds()
        player.map, player.y = Z, 0.50 At(60)
        ns.StartRun("herb", Z) advance(1)
        At(0) advance(30)
        assert(S.misses == 1 and S.learnStay, "test setup: the first empty visit was not learned")
    end
    local function Harvest()
        seq = seq + 1
        local id = "o1x" .. seq
        fire("UNIT_SPELLCAST_SENT", "player", "Peacebloom", id, 2366) advance(2)
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", id, 2366)
        loot = { { guid = ("GameObject-0-1-1-1-1618-O1%04d"):format(seq), item = 2447, qty = 2 } }
        fire("LOOT_READY") loot = {}
    end

    -- (1) an hour standing there: checked again and again (each one gives the
    -- point its rest), learned once; its chance only comes back, never drops again
    Setup()
    local c1 = ns.NodeChance(S)
    local mark = #log
    advance(3600)
    local again = 0
    for i = mark, #log do if log[i]:find("the same stay, rest only", 1, true) then again = again + 1 end end
    assert(again >= 10, "standing there: only " .. again .. " checks")
    assert(S.misses == 1 and (S.emptyStreak or 0) == 1, "an hour at one spot learned 'empty' " .. tostring(S.misses) .. " times")
    assert(ns.NodeChance(S) >= c1, "standing there lowered the chance again")
    assert(ns.IsOnCooldown(S) or S.emptyUntil, "no rest any more while standing there")

    -- (2) small moves at the spot (never 60 yd away): still the same stay
    Setup()
    for _ = 1, 8 do At(45) advance(150) At(55) advance(150) At(10) advance(150) end
    assert(S.misses == 1, "small moves at the spot learned 'empty' " .. tostring(S.misses) .. " times")

    -- (3) gone (100 yd) and back: a new visit, learned again
    Setup()
    At(100) advance(2)
    assert(not S.learnStay, "100 yd away is not gone from the spot")
    At(0) advance(180)
    assert(S.misses == 2, "gone and back: " .. tostring(S.misses) .. " learned (expected 2)")

    -- (4) a stop and a new run at the same spot: the same stay
    Setup()
    ns.StopRun() advance(300)
    ns.StartRun("herb", Z) advance(200)
    assert(S.misses == 1 and S.learnStay, "a new run at the same spot learned 'empty' again")

    -- (5) a real find later: counted, and a check of the same stay that
    -- learned nothing is not "taken back" (the miss of the first visit stays)
    Setup()
    advance(150) -- the next check of this stay: rest only
    assert(S.misses == 1, "test setup: the second check learned")
    Harvest() advance(5)
    assert(S.hits == 1 and S.misses == 1, ("found after a check that learned nothing: hits %s, misses %s (expected 1, 1)"):format(tostring(S.hits), tostring(S.misses)))
    assert(not S.learnStay, "a find did not end the empty stay")

    -- (6) a gather without loot of its own (uncertain): not judged, nothing learned
    Setup()
    At(100) advance(2) At(0) advance(150) -- a new visit: the check comes in 25 s
    local before = S.misses
    seq = seq + 1
    fire("UNIT_SPELLCAST_SENT", "player", "Peacebloom", "o1u" .. seq, 2366) advance(2)
    fire("UNIT_SPELLCAST_SUCCEEDED", "player", "o1u" .. seq, 2366)
    advance(40)
    assert(S.misses == before, "an uncertain gather was learned as empty")

    ns.StopRun()
    ns.db.arriveDist, ns.db.debug = saved.arrive, saved.debug
    ns.db.nodes[Z] = nil
    ns.NotifyNodesChanged()
    player.map, player.x, player.y = 1412, 0.45, 0.72
    advance(1)
end)
step("Skill plan: unknown prices, fees, training, what you can make yourself (v0.1.14)", function()
    local d = ns.CraftData
    local saved = { known = d.Known, have = d.Have, rank = ns.ProfessionRank, price = ns.GetPrice, vendor = ns.db.vendorPrices }
    local recipes = GathercraftRecipeData.professions
    local knownBy = {} -- profession -> { recipe name -> packed }
    d.Known = function(p) return knownBy[p] or {} end
    d.Have = function() return 0 end
    local ranks = {} -- profession -> { rank, maxRank }
    ns.ProfessionRank = function(p) local r = ranks[p] if r then return r[1], r[2] end end
    ns.db.vendorPrices = {}
    local function Texts()
        local list = {}
        for _, o in ipairs(allFrames) do
            local t = o.GetText and o:GetText()
            if type(t) == "string" and o.IsShown and o:IsShown() then list[#list + 1] = t end
        end
        return list
    end
    local function Shows(text)
        for _, t in ipairs(Texts()) do if t:find(text, 1, true) then return t end end
    end
    local function Mat(mats, id) for _, m in ipairs(mats) do if m.id == id then return m end end end

    -- (1) no prices at all: the missing materials count as unknown, never as 0
    ns.GetPrice = function() end
    local steps, mats, total, _, unknown, info = ns.SkillPlan("Blacksmithing", 1, 75)
    local noPrice = 0
    for _, m in ipairs(mats) do if m.missing > 0 and not m.cost then noPrice = noPrice + 1 end end
    assert(#steps > 0 and noPrice > 0 and unknown, "test setup: a plan without prices")
    assert(info.matsUnknown == noPrice and total == 0, ("%d missing materials without a price counted as %d"):format(noPrice, info.matsUnknown))
    ranks.Blacksmithing = { 1, 75 }
    local keepTargets1 = ns.db.planTargets
    ns.db.planTargets = nil
    ns.ShowSkillPlan("Blacksmithing") advance(1)
    ns.db.planTargets = keepTargets1
    assert(Shows((ns.L["Missing materials cost: unknown (%d without a price)"]):format(noPrice)), "the total shows a price where none is known")
    -- (since 0.2, A3: no stand-in prices - such a choice is "not fully comparable")
    assert(Shows(ns.L["? = a part of the cost is unknown: this choice is not fully comparable."]), "a choice without prices is not explained")
    assert(not Shows(ns.L["~ = planned with an estimated price."]), "a missing price is called an estimate")

    -- (2) every price known: the total is the sum by hand
    ns.GetPrice = function() return 100, "AH scan" end
    steps, mats, total, _, _, info = ns.SkillPlan("Blacksmithing", 1, 75)
    local sum = 0
    for _, m in ipairs(mats) do if not m.madeFrom then sum = sum + m.missing * 100 end end
    assert(info.matsUnknown == 0 and total == sum and sum > 0, ("total %d, by hand %d"):format(total, sum))

    -- (3) trainer fees of the recipes you don't know yet, once each; a known one costs nothing
    local fees, seen, firstTrainer = 0, {}, nil
    for _, s in ipairs(steps) do
        local r = s.recipe
        if r.how == "trainer" and not seen[r] then seen[r] = true fees = fees + r.fee firstTrainer = firstTrainer or r end
    end
    assert(firstTrainer and info.fees == fees and info.feesUnknown == 0, ("fees %d, by hand %d"):format(info.fees, fees))
    knownBy.Blacksmithing = { [firstTrainer.key] = recipes.Blacksmithing[firstTrainer.key] }
    local steps2, _, _, _, _, info2 = ns.SkillPlan("Blacksmithing", 1, 75)
    assert(info2.fees == fees - firstTrainer.fee, "a recipe you know still costs its trainer fee")
    -- (since 0.2, A4, the fee is part of the choice: a recipe you know may be
    -- used more than before - it is still in the plan, as a known one)
    local stillUsed
    for _, s in ipairs(steps2) do
        if s.recipe.key == firstTrainer.key then stillUsed = s.recipe.how end
    end
    assert(stillUsed == "known", "a recipe you know dropped out of the plan: " .. tostring(stillUsed))
    knownBy.Blacksmithing = nil
    -- recipe items from vendors: counted, with a price only where a vendor showed one
    local csteps, _, _, _, _, cinfo = ns.SkillPlan("Cooking", 1, 75)
    local items, oneItem = 0, nil
    seen = {}
    for _, s in ipairs(csteps) do
        local r = s.recipe
        if r.how == "vendor" and not seen[r] then seen[r] = true items = items + 1 oneItem = oneItem or r.recipeItem end
    end
    assert(items > 0 and cinfo.items == items and cinfo.itemsUnknown == items and cinfo.itemCost == 0, "recipe items to buy")
    ns.db.vendorPrices[oneItem] = 500
    _, _, _, _, _, cinfo = ns.SkillPlan("Cooking", 1, 75)
    assert(cinfo.itemCost == 500 and cinfo.itemsUnknown == items - 1, "a recipe item price a vendor showed")
    ns.db.vendorPrices[oneItem] = nil

    -- (4) training: your own maximum, else the usual caps (assumed).
    -- (Since 0.2, A6, the target stays as it was set: a fresh one here.)
    local keepTargets = ns.db.planTargets
    ns.db.planTargets = nil
    ranks.Blacksmithing = { 75, 75 }
    ns.ShowSkillPlan("Blacksmithing") advance(1)
    assert(Shows((ns.L["Train the next rank at your trainer (needed at %d)."]):format(75)), "no training step at your maximum")
    assert(Shows((ns.L["Your skill: %d / %d"]):format(75, 75)), "your maximum is not shown")
    assert(_G.GathercraftSkillPlanTarget:GetText() == "150", "the default target above 75 is not 150: " .. tostring(_G.GathercraftSkillPlanTarget:GetText()))
    ranks.Blacksmithing = { 75 } -- the maximum is unknown
    ns.db.planTargets = nil
    ns.ShowSkillPlan("Blacksmithing") advance(1)
    assert(Shows((ns.L["Train the next rank at your trainer (at ~%d, cap assumed)."]):format(75)), "assumed caps are not marked")
    ns.db.planTargets = keepTargets

    -- (5) what you can make yourself: profession, recipe and its skill (smelting
    -- for a blacksmith). Since 0.2 (A2) making is compared with buying, at the
    -- moment the plan needs the item: bars and grinding stones are dear at
    -- the auction house here (bars 100c; a grinding stone 1c, its two rough
    -- stones 0.8c), ore cheap (1c)
    local cheap = { [2842] = 100, [3470] = 1, [2840] = 100, [2841] = 100, [3576] = 100, [2775] = 1, [2770] = 1, [2771] = 1, [2835] = 0.4 }
    ns.GetPrice = function(id) return cheap[id] or 1000, "AH scan" end
    local function Bars(from, to)
        local s, m, _, _, _, i = ns.SkillPlan("Blacksmithing", from, to)
        return Mat(m, 2840), Mat(m, 2841), Mat(m, 3470), m, s, i
    end
    local copper, bronze, _, m = Bars(75, 150)
    assert(bronze and not bronze.madeFrom and bronze.missing > 0, "no Mining: bronze bars are not bought")
    assert(not copper and not Mat(m, 2770) and not Mat(m, 2771), "no Mining: bars broken down into ore anyway")
    knownBy.Mining = recipes.Mining
    ranks.Mining = { 30, 75 } -- Smelt Bronze needs 65
    copper, bronze = Bars(75, 150)
    assert(bronze and not bronze.madeFrom, "Mining 30: bronze bars (65) are made")
    ranks.Mining = { 150, 150 }
    copper, bronze = Bars(75, 150)
    assert(bronze and bronze.madeFrom and bronze.madeFrom.prof == "Mining", "Mining 150: bronze bars are not made")
    assert(copper and copper.madeFrom, "Mining 150: the copper bars inside the bronze are not made")
    -- cheaper to buy than to make: bought, also with Mining 150
    cheap[2841] = 1
    copper, bronze = Bars(75, 150)
    assert(bronze and not bronze.madeFrom and bronze.missing > 0, "bronze bars cheaper at the auction house are made all the same")
    cheap[2841] = 100
    ranks.Mining = nil -- learned recipes, but the profession is gone
    _, bronze = Bars(75, 150)
    assert(bronze and not bronze.madeFrom, "without the profession: bars are made")
    knownBy.Mining = nil
    -- the same profession: Rough Grinding Stone (25, at the trainer for 90c).
    -- Not known yet: since 0.2 it is made all the same, learned in the plan
    -- (its fee is counted); a quest or drop recipe would not be
    -- (made: as extra crafts, or - while the recipe still gives skill points -
    -- as a step of its own "for materials")
    local function Made(row) return row ~= nil and row.missing == 0 and (row.madeFrom ~= nil or row.planned >= row.need - row.have) end
    local _, _, stone, _, _, info5 = Bars(75, 90)
    assert(Made(stone), "a recipe your trainer teaches is not made in the plan: "
        .. (stone and ("grinding stones need " .. stone.need .. ", bought " .. stone.missing) or "no grinding stones in the plan"))
    local feesWith = info5.fees
    knownBy.Blacksmithing = { ["Rough Grinding Stone"] = recipes.Blacksmithing["Rough Grinding Stone"] }
    _, _, stone, _, _, info5 = Bars(75, 90)
    assert(Made(stone), "a known recipe of your profession is not made")
    assert(info5.fees == feesWith - 90, ("the fee of the recipe learned for an extra craft: %d with, %d known"):format(feesWith, info5.fees))
    -- from 20: made only where the plan needs it at 25 or later (0.1.18
    -- looked at the skill at the start of the plan only)
    local _, _, stone20, _, steps20 = Bars(20, 90)
    local firstUse
    for _, s in ipairs(steps20) do
        for _, r in ipairs(s.recipe.reagents) do
            if r.id == 3470 and not firstUse then firstUse = s.from end
        end
    end
    assert(stone20 and firstUse, "test setup: no grinding stones from 20 to 90")
    assert(Made(stone20) == (firstUse >= 25), ("grinding stones first needed at %d: %s"):format(firstUse, Made(stone20) and "made" or "bought"))
    knownBy.Blacksmithing = nil

    -- (6) a recipe you learned from a quest stays usable; not learned, it is left
    -- out. Kaldorei Spider Kabob (quest reward, needs 10): its one ingredient is
    -- cheap, everything else expensive
    cheap = { [5465] = 1 }
    local function Uses(name)
        for _, s in ipairs(ns.SkillPlan("Cooking", 15, 40)) do if s.recipe.key == name then return s.recipe.how end end
    end
    assert(not Uses("Kaldorei Spider Kabob"), "a quest recipe you don't have is planned")
    knownBy.Cooking = { ["Kaldorei Spider Kabob"] = recipes.Cooking["Kaldorei Spider Kabob"] }
    assert(Uses("Kaldorei Spider Kabob") == "known", "a quest recipe you learned is not used")
    knownBy.Cooking = nil

    d.Known, d.Have, ns.ProfessionRank, ns.GetPrice, ns.db.vendorPrices = saved.known, saved.have, saved.rank, saved.price, saved.vendor
    if _G.GathercraftSkillPlan then _G.GathercraftSkillPlan:Hide() end
end)
step("Skill plan: what the plan makes itself is counted once, every profession (v0.1.18 S1-S4)", function()
    -- One shared stock per item for the whole plan: what you have plus what
    -- the plan's own steps make. Extra crafts of an intermediate only for the
    -- need that is still not covered after that.
    -- The steps are fixed by the test: each recipe gets a required skill and
    -- colours (yellow = grey = "upto") so it gives one point per craft from
    -- its required skill up to "upto" and nothing after it. Reagent amounts
    -- come from Data/RecipeData.lua; the test checks them first.
    local d = ns.CraftData
    local data = GathercraftRecipeData
    local saved = { known = d.Known, have = d.Have, rank = ns.ProfessionRank, price = ns.GetPrice,
        vendor = ns.db.vendorPrices, all = d.AllRecipes, spells = data.spells, colors = data.colors }
    local recipes = data.professions
    -- the stand-ins go back also when an assert fails (later steps use them)
    local ok, err = pcall(function()
    local function Uses(prof, key, id)
        local _, reagents = recipes[prof][key]:match("^([^|]+)|(.*)$")
        return tonumber((reagents or ""):match("%f[%d]" .. id .. ":(%d+)")) or 0
    end
    local function Makes(prof, key)
        local product, lo, hi = recipes[prof][key]:match("^(%d+):(%d+):(%d+):")
        return tonumber(product), (tonumber(lo) + tonumber(hi)) / 2
    end
    local stock, ranks, known = {}, {}, {}
    d.Have = function(id) return stock[id] or 0 end
    ns.ProfessionRank = function(p) local r = ranks[p] if r then return r, r end end
    d.Known = function(p) return known[p] or {} end
    -- prices: everything 10c at the auction house; vendor items cost what a vendor showed
    ns.db.vendorPrices = {}
    -- since 0.2 (A2) buying an intermediate is compared with making it. These
    -- cases check the material sums of MAKING it, so the intermediates are
    -- dear at the auction house (1000c): leather, bolts, grinding stones,
    -- copper bars, blasting powder, blackmouth oil
    local DEAR = { [2318] = true, [2996] = true, [3470] = true, [2840] = true, [4357] = true, [6370] = true }
    local function AH(price)
        ns.GetPrice = function(id) if DEAR[id] then return 1000, "AH scan" end return price(id) end
    end
    AH(function() return 10, "AH scan" end)
    -- plan(prof, from, to, { { key, req, upto[, start] }, ... }): only these recipes, all known
    local function Plan(prof, from, to, list)
        local all, spells, colors = {}, {}, {}
        known[prof] = {}
        for i, r in ipairs(list) do
            local packed = recipes[prof][r[1]]:gsub("^(%d+:%d+:%d+:)%d+", "%1" .. r[2])
            all[r[1]], known[prof][r[1]] = packed, packed
            spells[r[1]] = 900000 + i
            colors[900000 + i] = r[3] .. ":" .. r[3]
        end
        d.AllRecipes = function(p) return p == prof and all or {} end
        data.spells, data.colors = { [prof] = spells }, colors
        local parts, mats, total, stuck = ns.SkillPlan(prof, from, to)
        data.spells, data.colors = saved.spells, saved.colors
        assert(not stuck, prof .. ": test setup: the plan got stuck at " .. tostring(stuck))
        -- since 0.2 (A4) a step ends where a rank ends (training comes
        -- between): the parts of one recipe are added up again here
        local steps = {}
        for _, s in ipairs(parts) do
            local last = steps[#steps]
            if last and last.recipe.key == s.recipe.key then
                last.crafts, last.to = last.crafts + s.crafts, s.to
            else
                steps[#steps + 1] = { recipe = s.recipe, crafts = s.crafts, from = s.from, to = s.to }
            end
        end
        for i, r in ipairs(list) do
            local s = steps[i]
            -- r[4]: where the step starts when that is not its required skill
            assert(s and s.recipe.key == r[1] and s.crafts == r[3] - (r[4] or math.max(r[2], from)),
                ("%s: test setup: step %d is %s x%s"):format(prof, i, s and s.recipe.key or "-", s and s.crafts or "-"))
        end
        local byId = {}
        for _, m in ipairs(mats) do
            assert(not byId[m.id], prof .. ": item " .. m.id .. " listed twice")
            byId[m.id] = m
        end
        return byId, total
    end
    local function Is(prof, m, id, need, missing, made)
        local row = m[id]
        assert(row, ("%s: item %d not in the list"):format(prof, id))
        assert(row.need == need and row.missing == missing,
            ("%s: item %d need %d missing %d, want %d / %d"):format(prof, id, row.need, row.missing, need, missing))
        assert((row.madeFrom ~= nil) == (made == true), ("%s: item %d %s"):format(prof, id, made and "is not made" or "is made"))
        if made then assert(row.cost == 0, prof .. ": an item you make has a cost") end
    end

    -- Leatherworking, Sven's plan: 1-25 Light Leather x24, 25-74 Light Armor Kit
    -- x49, 74-97 Embossed Leather Gloves x23
    assert(Uses("Leatherworking", "Light Leather", 2934) == 3 and Uses("Leatherworking", "Light Armor Kit", 2318) == 1
        and Uses("Leatherworking", "Embossed Leather Gloves", 2318) == 3 and Uses("Leatherworking", "Embossed Leather Gloves", 2320) == 2,
        "test setup: leather amounts changed in RecipeData")
    local LW = { { "Light Leather", 1, 25 }, { "Light Armor Kit", 25, 74 }, { "Embossed Leather Gloves", 74, 97 } }
    -- Light Leather: need 49 x 1 + 23 x 3 = 118; you have 35, the steps make 24
    -- -> 118 - 35 - 24 = 59 more; made in all 24 + 59 = 83 -> scraps 83 x 3 = 249
    -- Coarse Thread 23 x 2 = 46 (vendor 10c, at the AH 50c: the vendor counts)
    AH(function(id) return id == 2320 and 50 or 10, "AH scan" end)
    ns.db.vendorPrices[2320] = 10
    stock = { [2318] = 35 }
    local m, total = Plan("Leatherworking", 1, 97, LW)
    Is("Leatherworking", m, 2318, 118, 0, true)
    Is("Leatherworking", m, 2934, 249, 249)
    Is("Leatherworking", m, 2320, 46, 46)
    -- what is missing, nothing else: 249 x 10c + 46 x 10c (vendor)
    assert(total == 249 * 10 + 46 * 10, ("Leatherworking: total %d, want %d"):format(total, 249 * 10 + 46 * 10))
    -- 34 in your bags: 60 more -> 84 crafts -> 252 scraps (S1 apart from S2)
    stock = { [2318] = 34 }
    m = Plan("Leatherworking", 1, 97, LW)
    Is("Leatherworking", m, 2934, 252, 252)
    -- enough leather already: no extra crafts, only the 24 of the steps (72 scraps)
    stock = { [2318] = 200, [2934] = 10 }
    m = Plan("Leatherworking", 1, 97, LW)
    Is("Leatherworking", m, 2934, 72, 62)
    AH(function() return 10, "AH scan" end)

    -- Tailoring: 1-11 Bolt of Linen Cloth x10, 11-31 Brown Linen Robe x20
    assert(Uses("Tailoring", "Bolt of Linen Cloth", 2589) == 2 and Uses("Tailoring", "Brown Linen Robe", 2996) == 3
        and Uses("Tailoring", "Brown Linen Robe", 2320) == 1, "test setup: tailoring amounts changed")
    -- bolts: need 20 x 3 = 60; you have 5, the steps make 10 -> 45 more;
    -- linen (10 + 45) x 2 = 110; thread 20
    stock = { [2996] = 5 }
    m = Plan("Tailoring", 1, 31, { { "Bolt of Linen Cloth", 1, 11 }, { "Brown Linen Robe", 11, 31 } })
    Is("Tailoring", m, 2996, 60, 0, true)
    Is("Tailoring", m, 2589, 110, 110)
    Is("Tailoring", m, 2320, 20, 20)

    -- Blacksmithing with smelting (Mining 150, Smelt Copper known):
    -- 1-11 Rough Sharpening Stone x10, 11-21 Rough Grinding Stone x10,
    -- 21-41 Runed Copper Gauntlets x20
    assert(Uses("Blacksmithing", "Rough Sharpening Stone", 2835) == 1 and Uses("Blacksmithing", "Rough Grinding Stone", 2835) == 2
        and Uses("Blacksmithing", "Runed Copper Gauntlets", 2840) == 8 and Uses("Blacksmithing", "Runed Copper Gauntlets", 3470) == 2
        and Uses("Mining", "Smelt Copper", 2770) == 1, "test setup: blacksmithing amounts changed")
    ranks.Mining = 150
    known.Mining = { ["Smelt Copper"] = recipes.Mining["Smelt Copper"] }
    -- grinding stones: need 20 x 2 = 40, the steps make 10 -> 30 more (Rough
    -- Grinding Stone from skill 1 here, so you can make it at the start);
    -- rough stone 10 + (10 + 30) x 2 = 90; copper bars 20 x 8 = 160, you have
    -- 30 -> 130 smelted -> copper ore 130
    stock = { [2840] = 30 }
    m = Plan("Blacksmithing", 1, 41, { { "Rough Sharpening Stone", 1, 11 }, { "Rough Grinding Stone", 1, 21, 11 }, { "Runed Copper Gauntlets", 21, 41 } })
    Is("Blacksmithing", m, 3470, 40, 0, true)
    Is("Blacksmithing", m, 2835, 90, 90)
    Is("Blacksmithing", m, 2840, 160, 0, true)
    Is("Blacksmithing", m, 2770, 130, 130)

    -- Engineering: 1-11 Rough Blasting Powder x10, 11-31 Handful of Copper
    -- Bolts x20, 31-51 Rough Copper Bomb x20 (two bombs a craft)
    assert(Uses("Engineering", "Rough Blasting Powder", 2835) == 1 and Uses("Engineering", "Handful of Copper Bolts", 2840) == 1
        and Uses("Engineering", "Rough Copper Bomb", 4357) == 2 and Uses("Engineering", "Rough Copper Bomb", 4359) == 1
        and Uses("Engineering", "Rough Copper Bomb", 2840) == 1 and Uses("Engineering", "Rough Copper Bomb", 2589) == 1,
        "test setup: engineering amounts changed")
    -- powder: need 20 x 2 = 40, the steps make 10 -> 30 more -> rough stone 40;
    -- bolts: need 20, the steps make 20 -> none more; copper bars 20 (bolts)
    -- + 20 (bombs) = 40, you have 5 -> 35 smelted -> copper ore 35; linen 20
    AH(function(id) return id == 2840 and 50 or 10, "AH scan" end) -- bars dear: powder first
    stock = { [2840] = 5 }
    m = Plan("Engineering", 1, 51, { { "Rough Blasting Powder", 1, 11 }, { "Handful of Copper Bolts", 11, 31 }, { "Rough Copper Bomb", 31, 51 } })
    Is("Engineering", m, 4357, 40, 0, true)
    Is("Engineering", m, 2835, 40, 40)
    Is("Engineering", m, 4359, 20, 0)
    Is("Engineering", m, 2840, 40, 0, true)
    Is("Engineering", m, 2770, 35, 35)
    Is("Engineering", m, 2589, 20, 20)
    AH(function() return 10, "AH scan" end)
    ranks.Mining, known.Mining = nil, nil

    -- Enchanting: 1-2 Runed Copper Rod x1, 2-22 Enchant Bracer - Minor Stamina
    -- x20. The rod is a tool: no enchanting recipe lists it as a reagent, so
    -- it is made once and never counted again. The Copper Rod comes from a
    -- vendor (an enchanter can't make it): 1 x its vendor price.
    assert(Uses("Enchanting", "Runed Copper Rod", 6217) == 1 and Uses("Enchanting", "Enchant Bracer - Minor Stamina", 10940) == 2,
        "test setup: enchanting amounts changed")
    for key in pairs(recipes.Enchanting) do
        assert(Uses("Enchanting", key, 6218) == 0, "test setup: " .. key .. " uses up a Runed Copper Rod")
    end
    ns.db.vendorPrices[6217] = 124
    AH(function(id) if id ~= 6217 then return 10, "AH scan" end end) -- the rod: vendor only
    stock = {}
    m, total = Plan("Enchanting", 1, 22, { { "Runed Copper Rod", 1, 2 }, { "Enchant Bracer - Minor Stamina", 2, 22 } })
    Is("Enchanting", m, 6217, 1, 1)
    assert(not m[6218], "Enchanting: the Runed Copper Rod is listed as a material")
    Is("Enchanting", m, 10940, 40, 40)
    local other = Uses("Enchanting", "Runed Copper Rod", 247786)
    Is("Enchanting", m, 247786, other, other)
    assert(total == 124 + 40 * 10 + other * 10, ("Enchanting: total %d"):format(total))
    AH(function() return 10, "AH scan" end)

    -- Mining: 1-66 Smelt Copper x65, 66-76 Smelt Bronze x10 (1 copper + 1 tin
    -- -> 2 bronze). Copper bars: need 10, the steps make 65 -> none more ->
    -- copper ore 65 (not 75); tin bars 10, you have 10
    assert(Uses("Mining", "Smelt Bronze", 2840) == 1 and Uses("Mining", "Smelt Bronze", 3576) == 1, "test setup: smelting amounts changed")
    stock = { [3576] = 10 }
    m = Plan("Mining", 1, 76, { { "Smelt Copper", 1, 66 }, { "Smelt Bronze", 66, 76 } })
    Is("Mining", m, 2770, 65, 65)
    Is("Mining", m, 2840, 10, 0) -- the steps make them all: nothing extra to smelt
    Is("Mining", m, 3576, 10, 0)

    -- Alchemy: 1-21 Blackmouth Oil x20, 21-46 Swim Speed Potion x25
    assert(Uses("Alchemy", "Blackmouth Oil", 6358) == 2 and Uses("Alchemy", "Blackmouth Oil", 3371) == 1
        and Uses("Alchemy", "Swim Speed Potion", 6370) == 1 and Uses("Alchemy", "Swim Speed Potion", 3371) == 1
        and Uses("Alchemy", "Swim Speed Potion", 2452) == 1, "test setup: alchemy amounts changed")
    -- oil: need 25, you have 2, the steps make 20 -> 3 more; oily blackmouth
    -- (20 + 3) x 2 = 46; vials 20 + 3 (oil) + 25 (potions) = 48 at the vendor (4c)
    ns.db.vendorPrices[3371] = 4
    stock = { [6370] = 2 }
    m, total = Plan("Alchemy", 1, 46, { { "Blackmouth Oil", 1, 21 }, { "Swim Speed Potion", 21, 46 } })
    Is("Alchemy", m, 6370, 25, 0, true)
    Is("Alchemy", m, 6358, 46, 46)
    Is("Alchemy", m, 3371, 48, 48)
    Is("Alchemy", m, 2452, 25, 25)
    assert(total == 46 * 10 + 48 * 4 + 25 * 10, ("Alchemy: total %d"):format(total))

    -- Cooking and First Aid: the same calculation, no list of exceptions.
    -- 1-11 Charred Wolf Meat x10, 11-31 Spiced Wolf Meat x20: meat 30, spices
    -- 20 at the vendor (10c) -> 30 x 10c + 20 x 10c
    assert(Uses("Cooking", "Charred Wolf Meat", 2672) == 1 and Uses("Cooking", "Spiced Wolf Meat", 2678) == 1, "test setup: cooking amounts changed")
    AH(function(id) return id == 2678 and 99 or 10, "AH scan" end)
    ns.db.vendorPrices[2678] = 10
    stock = {}
    m, total = Plan("Cooking", 1, 31, { { "Charred Wolf Meat", 1, 11 }, { "Spiced Wolf Meat", 11, 31 } })
    Is("Cooking", m, 2672, 30, 30)
    Is("Cooking", m, 2678, 20, 20)
    assert(total == 30 * 10 + 20 * 10, ("Cooking: total %d"):format(total))
    AH(function() return 10, "AH scan" end)
    -- 1-41 Linen Bandage x40, 41-61 Heavy Linen Bandage x20: linen 40 + 40 = 80,
    -- you have 15 -> 65 missing
    assert(Uses("First Aid", "Linen Bandage", 2589) == 1 and Uses("First Aid", "Heavy Linen Bandage", 2589) == 2, "test setup: first aid amounts changed")
    stock = { [2589] = 15 }
    m, total = Plan("First Aid", 1, 61, { { "Linen Bandage", 1, 41 }, { "Heavy Linen Bandage", 41, 61 } })
    Is("First Aid", m, 2589, 80, 65)
    assert(total == 65 * 10, ("First Aid: total %d"):format(total))

    end)
    d.Known, d.Have, ns.ProfessionRank, ns.GetPrice, ns.db.vendorPrices = saved.known, saved.have, saved.rank, saved.price, saved.vendor
    d.AllRecipes, data.spells, data.colors = saved.all, saved.spells, saved.colors
    if not ok then error(err, 0) end
end)
step("Skill plan: counts again when the bags change (v0.1.18 S2)", function()
    -- Sven had 35 Light Leather, the plan said 34: the plan counted once when
    -- it opened, and loot, crafting or the bank after that never reached it
    local d = ns.CraftData
    local saved = { have = d.Have, rank = ns.ProfessionRank }
    local stock = { [2318] = 34 }
    d.Have = function(id) return stock[id] or 0 end
    ns.ProfessionRank = function(p) if p == "Leatherworking" then return 30, 75 end end
    ns.ShowSkillPlan("Leatherworking") advance(1)
    local win = _G.GathercraftSkillPlan
    local name = ns.ItemName and ns.ItemName(2318) or "2318"
    -- (since 0.2, A6: the row's own column "have / need")
    local function Row()
        for _, o in ipairs(allFrames) do
            if o.left and o.mid and o:IsShown() and o.left:GetText() == name then return o.mid:GetText() end
        end
    end
    local before = Row()
    assert(before and before:find("34 / ", 1, true), "test setup: Light Leather is not in the plan: " .. tostring(before))
    for _, e in ipairs({ "BAG_UPDATE_DELAYED", "PLAYERBANKSLOTS_CHANGED", "BANKFRAME_OPENED" }) do
        stock[2318] = (stock[2318] or 0) + 1
        fire(e) fire(e) fire(e) advance(1)
        local want = stock[2318] .. " / "
        assert((Row() or ""):find(want, 1, true), ("after %s: %s, want %s"):format(e, tostring(Row()), want))
    end
    -- closed: nothing is counted
    win:Hide()
    local calls = 0
    d.Have = function(id) calls = calls + 1 return stock[id] or 0 end
    fire("BAG_UPDATE_DELAYED") advance(1)
    assert(calls == 0, "the closed plan counted again")
    d.Have, ns.ProfessionRank = saved.have, saved.rank
end)
step("Skill plan: the reagent bag counts, /gcr debug shows the parts (v0.1.18 S2)", function()
    -- C_Item.GetItemCount(item, includeBank, includeUses, includeReagentBank, ...):
    -- the reagent BANK is not the reagent BAG, so no parameter is guessed.
    -- The bag slots are counted too: holding more than the client's count
    -- without the bank, the client left the reagent bag out
    local saved = { count = C_Item.GetItemCount, info = C_Container.GetContainerItemInfo, slots = C_Container.GetContainerNumSlots,
        enum = Enum.BagIndex, debug = ns.db.debug }
    local slots = { [0] = { { itemID = 2318, stackCount = 20 }, { itemID = 2318, stackCount = 14 } }, [5] = { { itemID = 2318, stackCount = 1 } } }
    Enum.BagIndex = { ReagentBag = 5 }
    C_Container.GetContainerNumSlots = function(b) return slots[b] and #slots[b] or 0 end
    C_Container.GetContainerItemInfo = function(b, s) return slots[b] and slots[b][s] end
    local d = ns.CraftData
    local function Parts(what, total, bags, reagent, bank)
        fire("BAG_UPDATE_DELAYED")
        assert(d.Have(2318) == total, ("%s: you have %d, want %d"):format(what, d.Have(2318), total))
        local t, b, r, k = d.HaveParts(2318)
        assert(t == total and b == bags and r == reagent and k == bank,
            ("%s: total %s, bags %s, reagent bag %s, bank %s"):format(what, tostring(t), tostring(b), tostring(r), tostring(k)))
    end
    -- a client that leaves the reagent bag out: 34 in the bags, 3 in the bank
    C_Item.GetItemCount = function(id, bank) if id ~= 2318 then return 0 end return bank and 37 or 34 end
    Parts("reagent bag left out", 38, 34, 1, 3)
    -- a client that counts it: nothing is added twice
    C_Item.GetItemCount = function(id, bank) if id ~= 2318 then return 0 end return bank and 38 or 35 end
    Parts("reagent bag counted", 38, 34, 1, 3)
    -- the bags changed: counted again after the update
    slots[5][1].stackCount = 4
    Parts("after a bag update", 41, 34, 4, 3)
    -- no slot functions: the client's count alone
    C_Container.GetContainerItemInfo = nil
    fire("BAG_UPDATE_DELAYED")
    assert(d.Have(2318) == 38 and select(2, d.HaveParts(2318)) == nil, "without slot functions")
    C_Container.GetContainerItemInfo = function(b, s) return slots[b] and slots[b][s] end
    -- /gcr debug: one line per material, again only when its count changes
    ns.db.debug = true
    local saveRank = ns.ProfessionRank
    ns.ProfessionRank = function(p) if p == "Leatherworking" then return 30, 75 end end
    C_Item.GetItemCount = function(id, bank) if id ~= 2318 then return 0 end return bank and 37 or 34 end
    fire("BAG_UPDATE_DELAYED")
    local name = ns.ItemName and ns.ItemName(2318) or "2318"
    local line = ("PLAN have %s: bags 34, reagent bag 4, bank 3, total 41"):format(name)
    local function Said(from)
        local n = 0
        for i = from + 1, #log do if log[i]:find(line, 1, true) then n = n + 1 end end
        return n
    end
    local mark = #log
    ns.ShowSkillPlan("Leatherworking") advance(1)
    ns.ShowSkillPlan("Leatherworking") advance(1)
    assert(Said(mark) == 1, ("the debug line came %d times: %s"):format(Said(mark), line))
    ns.db.debug = false
    mark = #log
    slots[0][1].stackCount = 21
    fire("BAG_UPDATE_DELAYED")
    ns.ShowSkillPlan("Leatherworking") advance(1)
    for i = mark + 1, #log do assert(not log[i]:find("PLAN have", 1, true), "a debug line without /gcr debug") end
    _G.GathercraftSkillPlan:Hide()
    ns.ProfessionRank = saveRank
    C_Item.GetItemCount, C_Container.GetContainerItemInfo, C_Container.GetContainerNumSlots = saved.count, saved.info, saved.slots
    Enum.BagIndex, ns.db.debug = saved.enum, saved.debug
    fire("BAG_UPDATE_DELAYED")
end)
step("Recipe import: a hotfix only changes the source values it was written for (v0.1.18, Codex N3)", function()
    -- tools/import_skillup.lua on a small SkillUp source of one recipe,
    -- Tanning Rack (hotfix 06.11.2026: skill 140 -> 125, thresholds 15
    -- lower), written to a temp folder
    local windows = package.config:sub(1, 1) == "\\"
    local dir = os.tmpname()
    os.remove(dir)
    os.execute(windows and ('mkdir "' .. dir .. '\\Data"') or ("mkdir -p '" .. dir .. "/Data'"))
    local function Write(file, body)
        local f = assert(io.open(dir .. "/Data/" .. file, "w"))
        f:write("local _, ns = ...\n" .. body .. "\n")
        f:close()
    end
    local function Import(required, t)
        Write("Recipes.lua", "ns.RecipeData = { [1263031] = { skillLine = 165, output = { itemID = 1263032, quantity = 1 }, "
            .. "reagents = { { itemID = 2318, quantity = 4 } } } }\nns.RecipeNames = { [165] = { [\"Tanning Rack\"] = 1263031 } }")
        Write("Thresholds.lua", ("ns.Thresholds = { [1263031] = { %d, %d, %d, %d } }"):format(t[1], t[2], t[3], t[4]))
        Write("Trainer.lua", ("ns.TrainerFees = { [1263031] = { 500, %d } }"):format(required))
        local out, warn = {}, {}
        local keep = { print = print, arg = arg, stderr = io.stderr }
        print = function(s) out[#out + 1] = tostring(s) end
        arg = { dir }
        io.stderr = { write = function(_, s) warn[#warn + 1] = s end }
        local ok, err = pcall(assert(loadfile(ROOT .. "/tools/import_skillup.lua")))
        print, arg, io.stderr = keep.print, keep.arg, keep.stderr
        assert(ok, "import: " .. tostring(err))
        local text = table.concat(out, "\n")
        local req = tonumber(text:match('%["Tanning Rack"%] = "%d+:%d+:%d+:(%d+)|'))
        local colors = text:match('%[1263031%]="(%d+:%d+)"')
        local hotfixWarn
        for _, w in ipairs(warn) do if w:find("hotfix Tanning Rack", 1, true) then hotfixWarn = w end end
        return req, colors, hotfixWarn
    end
    local ok, err = pcall(function()
        -- the old source: the hotfix applies
        local req, colors, warn = Import(140, { 140, 140, 142, 145 })
        assert(req == 125 and colors == "125:130" and not warn, ("old source: %s %s %s"):format(tostring(req), tostring(colors), tostring(warn)))
        -- a source that has the hotfix already: not lowered a second time (was 110:115)
        req, colors, warn = Import(125, { 125, 125, 127, 130 })
        assert(req == 125 and colors == "125:130", ("updated source: %s %s"):format(tostring(req), tostring(colors)))
        assert(warn and warn:find("already", 1, true), "updated source: no note")
        -- other values: left as they are, with a warning
        req, colors, warn = Import(150, { 150, 150, 152, 155 })
        assert(req == 150 and colors == "150:155" and warn, ("other source: %s %s %s"):format(tostring(req), tostring(colors), tostring(warn)))
    end)
    os.execute(windows and ('rmdir /s /q "' .. dir .. '"') or ("rm -rf '" .. dir .. "'"))
    if not ok then error(err, 0) end
end)
step("Minimap guesses nobody confirmed go after 30 days (v0.1.18 S6)", function()
    local DAY = 24 * 3600
    local now = time()
    local keep = ns.db.nodes[1450]
    local function Guess(id, age, extra)
        local n = { id = id, name = "Peacebloom", type = "herb", x = 0.1 + #ns.db.nodes[1450] * 0.05, y = 0.3, count = 1, last = 1,
            seenOnly = true, seenAt = age and (now - age) or nil, upAt = 1, seenErr = 20 }
        for k, v in pairs(extra or {}) do n[k] = v end
        table.insert(ns.db.nodes[1450], n)
        return n
    end
    ns.db.nodes[1450] = {}
    local d29 = Guess("o2001", 29 * DAY)
    local d30 = Guess("o2002", 30 * DAY)
    local d31 = Guess("o2003", 31 * DAY)
    local again = Guess("o2004", 40 * DAY)
    local undated = Guess("o2005", nil)
    local questie = Guess("o2006", 90 * DAY, { source = "questie" })
    local starter = Guess("o2007", 90 * DAY, { source = "starter" })
    local synced = Guess("o2008", 90 * DAY, { source = "sync", heard = 1 })
    local confirmed = Guess("o2009", 90 * DAY, { heard = 1, heardBy = { Someone = true } })
    -- harvested: a normal node (no longer a guess), however old
    local harvested = { id = "o2010", name = "Peacebloom", type = "herb", x = 0.9, y = 0.9, count = 3, hits = 3, last = now - 90 * DAY }
    table.insert(ns.db.nodes[1450], harvested)
    ns.NotifyNodesChanged() ns.ForgetSeenKinds()
    -- seen again on the minimap just now: its 40 days start over
    player.map, player.x, player.y = 1450, again.x, again.y
    advance(10)
    ns.SeenOnMinimap(1450, again.x, again.y, "Peacebloom", 20)
    assert(again.seenAt == time(), "test setup: the new look didn't reach the old guess")
    -- the ages exactly at the login below: 29, 30 and 31 days
    d29.seenAt, d30.seenAt, d31.seenAt = time() - 29 * DAY, time() - 30 * DAY, time() - 31 * DAY
    -- the login clears up (all zones in one go, one debug line)
    local wasDebug = ns.db.debug
    ns.db.debug = true
    local mark = #log
    for f in pairs(eventFrames.PLAYER_LOGIN) do
        if eventFrames.ADDON_LOADED and eventFrames.ADDON_LOADED[f] then f.__scripts.OnEvent(f, "PLAYER_LOGIN") end
    end
    ns.db.debug = wasDebug
    local left = {}
    for _, n in ipairs(ns.db.nodes[1450] or {}) do left[n] = true end
    assert(left[d29], "29 days: gone")
    assert(not left[d30] and not left[d31], "30 / 31 days: still there")
    assert(left[again], "seen again: gone")
    assert(left[undated] and undated.seenAt and undated.seenAt >= now, "without a date: gone or no date set")
    assert(left[questie] and left[starter] and left[synced], "a Questie, starter or shared node went")
    assert(left[confirmed], "a guess another player confirmed went")
    assert(left[harvested], "a harvested node went")
    local said = 0
    for i = mark + 1, #log do
        if log[i]:find("2 rough minimap guesses gone", 1, true) then said = said + 1 end
    end
    assert(said == 1, "the login said it " .. said .. " times")
    ns.db.nodes[1450] = keep
    ns.NotifyNodesChanged() ns.ForgetSeenKinds()
    player.map, player.x, player.y = 1412, 0.45, 0.72
end)
step("Minimap guesses: merging at login keeps what protects them from the 30 days (v0.1.18 F1)", function()
    -- Codex H1 (08.11.): ConsolidateSeen runs right before ExpireGuesses. Two
    -- undated guesses got the date 0 (gone at once), and a confirmation on
    -- the second guess of a pair was lost (gone, or not, by list order).
    local DAY = 24 * 3600
    local Z = 1450
    local keep = ns.db.nodes[Z]
    ns.db.nodes[Z] = {}
    local spot = 0
    -- a pair of guesses of one kind about 5 yd apart, each pair far from the others
    local function Pair(id, a, b)
        spot = spot + 1
        local x = 0.05 + spot * 0.07
        local out = {}
        for i, extra in ipairs({ a, b }) do
            local n = { id = id, name = "Peacebloom", type = "herb", x = x + (i - 1) * 0.001, y = 0.4, count = 1, last = 1,
                seenOnly = true, seenErr = 20, upAt = 1 }
            for k, v in pairs(extra) do n[k] = v end
            table.insert(ns.db.nodes[Z], n)
            out[i] = n
        end
        return out[1], out[2], x
    end
    local now = time()
    local function Ago(days) return now - days * DAY end
    -- A: both without a date
    local A1, A2, ax = Pair("o2101", {}, {})
    -- B: 40 days old, the confirmed one second, then first
    local B1, B2, bx = Pair("o2102", { seenAt = Ago(40) }, { seenAt = Ago(40), heard = 1, heardBy = { Reporter = true } })
    local C1, C2, cx = Pair("o2103", { seenAt = Ago(40), heard = 1, heardBy = { Reporter = true } }, { seenAt = Ago(40) })
    -- shared spots: the source of the second one counts too
    local S1, S2, sx = Pair("o2104", { seenAt = Ago(90) }, { seenAt = Ago(90), source = "sync" })
    -- the youngest known date counts; an unknown one is no date
    local D29a, D29b, d29x = Pair("o2105", { seenAt = Ago(35) }, { seenAt = Ago(29) })
    local D30a, D30b, d30x = Pair("o2106", { seenAt = Ago(40) }, { seenAt = Ago(30) })
    local D31a, D31b, d31x = Pair("o2107", { seenAt = Ago(45) }, { seenAt = Ago(31) })
    local U1, U2, ux = Pair("o2108", {}, { seenAt = Ago(29) })
    -- confirmations by the same and by another player: each player once
    local H1, H2, hx = Pair("o2109", { seenAt = Ago(60), heard = 1, heardBy = { Ann = true } },
        { seenAt = Ago(60), heard = 2, heardBy = { Ann = true, Bob = true } })
    -- close to a harvested node: the guesses merge and go, the node stays
    local G1, G2, gx = Pair("o2110", { seenAt = Ago(40) }, { seenAt = Ago(40) })
    local harvested = { id = "o2110", name = "Peacebloom", type = "herb", x = gx + 0.0005, y = 0.4, count = 3, hits = 3, last = Ago(90) }
    table.insert(ns.db.nodes[Z], harvested)
    ns.NotifyNodesChanged() ns.ForgetSeenKinds()
    -- the login: merge, then the 30 days (the whole chain)
    for f in pairs(eventFrames.PLAYER_LOGIN) do
        if eventFrames.ADDON_LOADED and eventFrames.ADDON_LOADED[f] then f.__scripts.OnEvent(f, "PLAYER_LOGIN") end
    end
    local at = {}
    for _, n in ipairs(ns.db.nodes[Z] or {}) do
        local key = math.floor((n.x - 0.05) / 0.07 + 0.5)
        at[key] = at[key] or {}
        table.insert(at[key], n)
    end
    local function Left(x, what)
        local list = at[math.floor((x - 0.05) / 0.07 + 0.5)] or {}
        local guesses = {}
        for _, n in ipairs(list) do if n.seenOnly then guesses[#guesses + 1] = n end end
        assert(#guesses <= 1, ("%s: %d guesses left, not merged into one"):format(what, #guesses))
        return guesses[1], list
    end
    local a = Left(ax, "A")
    assert(a, "A: two close undated guesses went at the login")
    assert(a.seenAt and a.seenAt >= now, "A: no date of today after the merge: " .. tostring(a.seenAt))
    local b = Left(bx, "B")
    assert(b and (b.heard or 0) >= 1 and b.heardBy and b.heardBy.Reporter, "B: the confirmation of the second guess was lost")
    local c = Left(cx, "B reversed")
    assert(c and (c.heard or 0) >= 1 and c.heardBy and c.heardBy.Reporter, "B reversed: the confirmed guess went")
    local s = Left(sx, "shared")
    assert(s and s.source == "sync", "a shared spot merged into an own guess went: " .. tostring(s and s.source))
    local d29 = Left(d29x, "29 days")
    assert(d29 and d29.seenAt == Ago(29), "29 days after the merge: gone, or not the youngest date")
    assert(not Left(d30x, "30 days") and not Left(d31x, "31 days"), "30 / 31 days after the merge: still there")
    local u = Left(ux, "one date unknown")
    assert(u and u.seenAt == Ago(29), "an unknown date took the place of the known one: " .. tostring(u and u.seenAt))
    local h = Left(hx, "confirmations")
    assert(h and h.heardBy and h.heardBy.Ann and h.heardBy.Bob, "confirmations: not every player kept")
    local names = 0
    for _ in pairs(h.heardBy) do names = names + 1 end
    assert(names == 2 and h.heard == 2, ("confirmations: %d players, heard %s (each player once)"):format(names, tostring(h.heard)))
    local g, glist = Left(gx, "harvested")
    assert(not g, "next to a harvested node: 40 days old guesses stayed")
    assert(#glist == 1 and glist[1] == harvested, "next to a harvested node: the harvested node went or changed")
    ns.db.nodes[Z] = keep
    ns.NotifyNodesChanged() ns.ForgetSeenKinds()
end)
step("Skill plan 2.0: the calculation is its own module and runs on plain tables (v0.2 A1)", function()
    -- concept 3.1: one core, apart from the window; everything comes in as input
    local core = ns.PlanCore
    assert(core and core.Compute and core.Chance, "no ns.PlanCore")
    -- loaded before the window that shows it
    local a, b = toc:find("PlanCore.lua", 1, true), toc:find("Planner.lua", 1, true)
    assert(a and b and a < b, "PlanCore.lua is not loaded before Planner.lua")
    -- the core reads nothing from the game: its source knows the addon table
    -- only to hang itself on, no saved variables, no game functions, no texts
    local f = assert(io.open(ROOT .. "/PlanCore.lua"))
    local src = f:read("*a") f:close()
    local code = src:gsub("%-%-[^\n]*", "") -- comments may name things
    for use in code:gmatch("ns%.([%w_]+)") do assert(use == "PlanCore", "PlanCore.lua reads ns." .. use) end
    for _, word in ipairs({ "_G", "CreateFrame", "C_Item", "C_Timer", "GetItemCount", "GetTime", "Gathercraft[%u]", "L%[", "print%(", "RegisterEvent" }) do
        assert(not code:find(word), "PlanCore.lua uses " .. word)
    end
    -- a plan from plain tables, with every door to the game shut
    local function Recipe(key, product, made, req, yellow, grey, reagents, learn)
        return { prof = "Testing", key = key, name = key, product = product, made = made, req = req, yellow = yellow, grey = grey,
            reagents = reagents, learn = learn or "known" }
    end
    local function Input(order)
        local list = {
            Recipe("Alpha", 9001, 1, 1, 6, 6, { { id = 9101, n = 2 } }),
            Recipe("Beta", 9002, 1, 6, 11, 11, { { id = 9001, n = 1 }, { id = 9102, n = 3 } }),
        }
        if order == "reverse" then list[1], list[2] = list[2], list[1] end
        return { prof = "Testing", skill = 1, target = 11, recipes = { Testing = list }, professions = { Testing = { rank = 1 } },
            stock = { [9102] = 4 }, prices = { [9101] = { copper = 10 }, [9102] = { copper = 7 }, [9001] = { copper = 500 } },
            recipeItemPrices = {}, nodes = {} }
    end
    local d = ns.CraftData
    local saved = { have = d.Have, cost = d.ReagentCost, known = d.Known, all = d.AllRecipes, rank = ns.ProfessionRank, price = ns.GetPrice }
    local function Shut() error("the calculation reached into the game", 0) end
    d.Have, d.ReagentCost, d.Known, d.AllRecipes, ns.ProfessionRank, ns.GetPrice = Shut, Shut, Shut, Shut, Shut, Shut
    local ok, plan = pcall(core.Compute, Input())
    local ok2, plan2 = pcall(core.Compute, Input("reverse"))
    d.Have, d.ReagentCost, d.Known, d.AllRecipes, ns.ProfessionRank, ns.GetPrice = saved.have, saved.cost, saved.known, saved.all, saved.rank, saved.price
    assert(ok, "the calculation with plain tables: " .. tostring(plan))
    assert(ok2, "the calculation with plain tables (other order): " .. tostring(plan2))
    -- 1-6 Alpha x5 (makes 5 of 9001), 6-11 Beta x5 (uses 5 of 9001: all made by the steps)
    assert(#plan.steps == 2 and plan.steps[1].recipe.key == "Alpha" and plan.steps[1].crafts == 5
        and plan.steps[2].recipe.key == "Beta" and plan.steps[2].crafts == 5 and not plan.stuck, "the steps")
    local byId = {}
    for _, m in ipairs(plan.materials) do byId[m.id] = m end
    assert(byId[9101] and byId[9101].need == 10 and byId[9101].missing == 10, "material 9101")
    assert(byId[9102] and byId[9102].need == 15 and byId[9102].have == 4 and byId[9102].missing == 11, "material 9102")
    assert(byId[9001] and byId[9001].need == 5 and byId[9001].missing == 0, "the intermediate made by the steps")
    assert(plan.total == 10 * 10 + 11 * 7, "the cost of what is missing: " .. tostring(plan.total))
    -- the order the recipes come in changes nothing
    assert(#plan2.steps == 2 and plan2.steps[1].recipe.key == "Alpha" and plan2.steps[2].crafts == 5 and plan2.total == plan.total, "another input order, another plan")
    -- the window's entry point is a thin wrapper around it
    f = assert(io.open(ROOT .. "/Planner.lua"))
    local planner = f:read("*a") f:close()
    assert(planner:find("ns.PlanCore.Compute", 1, true), "Planner.lua does not call the core")
    assert(not planner:find("local function MakePlan", 1, true) and not planner:find("local function Materials", 1, true), "Planner.lua still calculates itself")
    assert(not planner:lower():find("cheapest", 1, true), "Planner.lua calls the plan the cheapest")
end)
step("Skill plan 2.0: one stock per item, in the order the plan is carried out (v0.2 A2)", function()
    -- concept 4.3 and 4.7, on plain tables. A recipe here gives one point per
    -- craft from its required skill up to `upto` and nothing after (yellow =
    -- grey = upto), unless colours are given.
    local core = ns.PlanCore
    local function R(prof, key, product, made, req, upto, reagents, learn, yellow, grey)
        local list = {}
        for _, r in ipairs(reagents) do list[#list + 1] = { id = r[1], n = r[2] } end
        return { prof = prof, key = key, name = key, product = product, made = made, req = req, yellow = yellow or upto, grey = grey or upto,
            reagents = list, learn = learn == nil and "known" or learn or nil }
    end
    local function Input(prof, from, to, recipes, stock, prices, professions)
        local p = {}
        for id, copper in pairs(prices or {}) do p[id] = { copper = copper } end
        local byProf = {}
        for _, r in ipairs(recipes) do
            byProf[r.prof] = byProf[r.prof] or {}
            table.insert(byProf[r.prof], r)
        end
        local profs = professions or {}
        profs[prof] = profs[prof] or { rank = from }
        return { prof = prof, skill = from, target = to, recipes = byProf, professions = profs, stock = stock or {}, prices = p,
            recipeItemPrices = {}, nodes = {}, caps = {} }
    end
    local function Reversed(input)
        for _, list in pairs(input.recipes) do
            for i = 1, math.floor(#list / 2) do list[i], list[#list + 1 - i] = list[#list + 1 - i], list[i] end
            for _, r in ipairs(list) do
                for i = 1, math.floor(#r.reagents / 2) do r.reagents[i], r.reagents[#r.reagents + 1 - i] = r.reagents[#r.reagents + 1 - i], r.reagents[i] end
            end
        end
        return input
    end
    local function Plan(input)
        local plan = core.Compute(input)
        local ok, why = core.CheckBalance(plan)
        assert(ok, "the books do not balance: " .. tostring(why))
        local m = {}
        for _, row in ipairs(plan.materials) do
            assert(not m[row.id], "item " .. row.id .. " listed twice")
            m[row.id] = row
        end
        return plan, m
    end
    local function Extra(plan, key)
        for _, e in ipairs(plan.extras) do if e.recipe.key == key then return e.times end end
        return 0
    end
    local function Has(plan, code)
        for _, d in ipairs(plan.diagnostics) do if d.code == code then return d end end
    end

    -- (1) the leather golden: steps 24 / 49 / 23, 35 leather, 9 thread -> 249
    -- scraps, 37 thread missing; 34 leather -> 252 scraps
    local function Leather(leather)
        return Input("Leatherworking", 1, 97, {
            R("Leatherworking", "Light Leather", 2318, 1, 1, 25, { { 2934, 3 } }),
            R("Leatherworking", "Light Armor Kit", 2304, 1, 25, 74, { { 2318, 1 } }),
            R("Leatherworking", "Embossed Leather Gloves", 4239, 1, 74, 97, { { 2318, 3 }, { 2320, 2 } }),
        }, { [2318] = leather, [2320] = 9 }, { [2318] = 1000, [2934] = 10, [2320] = 10 })
    end
    local plan, m = Plan(Leather(35))
    assert(#plan.steps == 3 and plan.steps[1].crafts == 24 and plan.steps[2].crafts == 49 and plan.steps[3].crafts == 23, "golden: the steps are not 24 / 49 / 23")
    assert(m[2318].need == 118 and m[2318].have == 35 and m[2318].missing == 0 and m[2318].planned == 24, "golden: leather 118 needed, 35 there, 24 from the steps")
    assert(m[2934].need == 249 and m[2934].missing == 249, ("golden: %d scraps, want 249"):format(m[2934].need))
    assert(m[2320].need == 46 and m[2320].have == 9 and m[2320].missing == 37, ("golden: thread missing %d, want 37"):format(m[2320].missing))
    assert(Extra(plan, "Light Leather") == 59, "golden: extra leather crafts " .. Extra(plan, "Light Leather") .. ", want 59")
    assert(plan.total == 249 * 10 + 37 * 10 and plan.status == "ok" and plan.valid and plan.complete, "golden: cost or status")
    local b = plan.ledger[2318]
    assert(b.start == 35 and b.madePlan == 24 and b.madeExtra == 59 and b.bought == 0 and b.used == 118 and b.rest == 0, "golden: the books of the leather")
    plan, m = Plan(Leather(34))
    assert(m[2934].need == 252, ("golden with 34 leather: %d scraps, want 252"):format(m[2934].need))
    plan, m = Plan(Reversed(Leather(35)))
    assert(m[2934].need == 249 and m[2320].missing == 37, "golden: another input order, other amounts")

    -- (2) shared needs in several depths, stock of raw material and of the
    -- intermediates, batches of 3 with a rest. A x10 needs 20 X and 10 Y.
    --   X (have 4): 16 more = 6 batches of 3 = 18 (2 left) <- 12 Z (have 5, buy 7)
    --   Y (have 2): 8 more, each 1 X + 1 W: X 8 = 2 left + 6 more = 2 batches <- 4 Z (buy 4); W 8 (buy 8)
    local function Shared()
        return Input("Testing", 1, 11, {
            R("Testing", "A", 9200, 1, 1, 11, { { 9201, 2 }, { 9202, 1 } }),
            R("Testing", "Make X", 9201, 3, 1, 1, { { 9203, 2 } }),
            R("Testing", "Make Y", 9202, 1, 1, 1, { { 9201, 1 }, { 9204, 1 } }),
        }, { [9201] = 4, [9202] = 2, [9203] = 5 }, { [9201] = 1000, [9202] = 5000, [9203] = 1, [9204] = 1 })
    end
    for _, input in ipairs({ Shared(), Reversed(Shared()) }) do
        plan, m = Plan(input)
        assert(#plan.steps == 1 and plan.steps[1].crafts == 10, "shared: the step")
        assert(m[9201].need == 28 and m[9201].missing == 0 and m[9201].madeFrom and m[9201].madeFrom.key == "Make X", "shared: X need " .. m[9201].need)
        assert(m[9202].need == 10 and m[9202].missing == 0 and m[9202].madeFrom.key == "Make Y", "shared: Y")
        assert(m[9203].need == 16 and m[9203].have == 5 and m[9203].missing == 11, ("shared: Z need %d missing %d, want 16 / 11"):format(m[9203].need, m[9203].missing))
        assert(m[9204].need == 8 and m[9204].missing == 8, "shared: W")
        assert(Extra(plan, "Make X") == 8 and Extra(plan, "Make Y") == 8, "shared: extra crafts")
        assert(plan.ledger[9201].madeExtra == 24 and plan.ledger[9201].rest == 0, "shared: what the batches made")
        assert(plan.total == 11 + 8, "shared: only what is bought costs: " .. plan.total)
    end
    -- a batch makes more than is needed: the rest stays in the books, nothing is bought for it
    plan, m = Plan(Input("Testing", 1, 3, {
        R("Testing", "A", 9200, 1, 1, 3, { { 9201, 2 } }),
        R("Testing", "Make X", 9201, 5, 1, 1, { { 9203, 1 } }),
    }, {}, { [9201] = 1000, [9203] = 1 }))
    assert(m[9201].need == 4 and Extra(plan, "Make X") == 1 and plan.ledger[9201].rest == 1 and m[9203].need == 1, "a batch of 5 for a need of 4")

    -- (3) what can really be carried out
    -- a chain that leads back to itself: reported, nothing made from itself, no endless loop
    plan, m = Plan(Input("Testing", 1, 3, {
        R("Testing", "A", 9200, 1, 1, 3, { { 9211, 1 } }),
        R("Testing", "One from two", 9211, 1, 1, 1, { { 9212, 1 } }),
        R("Testing", "Two from one", 9212, 1, 1, 1, { { 9211, 1 } }),
    }, {}, {}))
    assert(Has(plan, "cycle"), "a chain back to itself is not reported")
    assert(plan.status == "incomplete" and not plan.complete and plan.valid, "a plan with such a chain called complete")
    assert(m[9211].need == 2, "the chain: what the step needs")
    -- no producer and no price: missing, its cost unknown (never 0)
    plan, m = Plan(Input("Testing", 1, 3, { R("Testing", "A", 9200, 1, 1, 3, { { 9213, 2 } }) }, {}, {}))
    assert(m[9213].missing == 4 and m[9213].cost == nil and not m[9213].madeFrom and plan.learn.matsUnknown == 1 and plan.total == 0, "no producer, no price")
    -- two producers: the less costly one, whatever order they come in
    local function Two()
        return Input("Testing", 1, 3, {
            R("Testing", "A", 9200, 1, 1, 3, { { 9214, 1 } }),
            R("Testing", "Dear way", 9214, 1, 1, 1, { { 9215, 1 } }),
            R("Testing", "Cheap way", 9214, 1, 1, 1, { { 9216, 1 } }),
        }, {}, { [9214] = 1000, [9215] = 50, [9216] = 5 })
    end
    for _, input in ipairs({ Two(), Reversed(Two()) }) do
        plan, m = Plan(input)
        assert(m[9214].madeFrom.key == "Cheap way" and m[9216] and not m[9215], "two producers: not the less costly one")
    end
    -- buying is compared with making: cheaper to buy -> bought
    plan, m = Plan(Input("Testing", 1, 3, {
        R("Testing", "A", 9200, 1, 1, 3, { { 9214, 1 } }),
        R("Testing", "Dear way", 9214, 1, 1, 1, { { 9215, 1 } }),
    }, {}, { [9214] = 20, [9215] = 50 }))
    assert(not m[9214].madeFrom and m[9214].missing == 2 and not m[9215], "an item cheaper to buy is made")
    -- a recipe to learn in the plan (trainer) is used and its fee counted;
    -- one nobody can count on (quest, drop: learn = nil) is not
    local function Learn(how)
        local make = R("Testing", "Make X", 9201, 1, 1, 1, { { 9203, 1 } }, how)
        make.fee = 75
        return Plan(Input("Testing", 1, 3, { R("Testing", "A", 9200, 1, 1, 3, { { 9201, 1 } }), make }, {}, { [9201] = 1000, [9203] = 1 }))
    end
    plan, m = Learn("trainer")
    assert(m[9201].madeFrom and plan.learn.trainer == 1 and plan.learn.fees == 75, "a recipe your trainer teaches: not made, or its fee not counted")
    plan, m = Learn(false)
    assert(not m[9201].madeFrom and m[9201].missing == 2 and plan.learn.trainer == 0, "a recipe nobody can count on is made")
    -- the skill at the moment of need counts, not the skill at the start:
    -- Make X needs 5. Step one (1-5) buys its X, step two (5-9) makes it
    plan, m = Plan(Input("Testing", 1, 9, {
        R("Testing", "Early", 9200, 1, 1, 5, { { 9201, 1 } }),
        R("Testing", "Late", 9205, 1, 5, 9, { { 9201, 1 }, { 9206, 1 } }),
        R("Testing", "Make X", 9201, 1, 5, 5, { { 9203, 1 } }),
    }, {}, { [9201] = 1000, [9203] = 1, [9206] = 1 }))
    assert(m[9201].need == 8 and m[9201].missing == 4 and Extra(plan, "Make X") == 4 and m[9203].need == 4, "made before its required skill, or not made after it")
    -- another profession: only one you have, with its skill and the recipe known - any profession, not only smelting
    local function Second(professions, known)
        return Plan(Input("Testing", 1, 3, {
            R("Testing", "A", 9200, 1, 1, 3, { { 9201, 1 } }),
            R("Weaving", "Weave X", 9201, 1, 50, 50, { { 9203, 1 } }, known),
        }, {}, { [9201] = 1000, [9203] = 1 }, professions))
    end
    plan, m = Second({})
    assert(not m[9201].madeFrom and m[9201].missing == 2, "a profession you don't have makes things")
    plan, m = Second({ Weaving = { rank = 60 } })
    assert(m[9201].madeFrom and m[9201].madeFrom.prof == "Weaving", "your second profession (not smelting) is not used")
    plan, m = Second({ Weaving = { rank = 40 } })
    assert(not m[9201].madeFrom, "your second profession below the recipe's skill is used")
    plan, m = Second({ Weaving = { rank = 60 } }, "trainer")
    assert(not m[9201].madeFrom, "a recipe of another profession you don't know yet is used")
    -- an extra craft of the planned profession can give a point itself: Make X
    -- gives 4 % at 97 (25 crafts for a point). A x10 would need 30 X: 25 of
    -- them come as a step for materials (97-98), A starts at 98 and needs 9
    -- crafts = 27 X, so 2 more X without a point: 27 Make X in all, not 30
    plan, m = Plan(Input("Testing", 97, 107, {
        R("Testing", "A", 9200, 1, 97, 107, { { 9201, 3 } }),
        R("Testing", "Make X", 9201, 1, 1, 0, { { 9203, 1 } }, nil, 1, 101),
    }, {}, { [9201] = 1000, [9203] = 1 }))
    assert(#plan.steps == 2 and plan.steps[1].forMaterials and plan.steps[1].recipe.key == "Make X" and plan.steps[1].crafts == 25
        and plan.steps[1].from == 97 and plan.steps[1].to == 98, "extra crafts that give a point are not a step of their own")
    assert(plan.steps[2].recipe.key == "A" and plan.steps[2].from == 98 and plan.steps[2].crafts == 9, "the step after them does not start later")
    assert(m[9201].need == 27 and m[9203].need == 27 and Extra(plan, "Make X") == 2, ("extra crafts with a skill gain: %d X"):format(m[9203].need))
    -- when they are grey they give nothing: all 30, A x10
    plan, m = Plan(Input("Testing", 97, 107, {
        R("Testing", "A", 9200, 1, 97, 107, { { 9201, 3 } }),
        R("Testing", "Make X", 9201, 1, 1, 50, { { 9203, 1 } }),
    }, {}, { [9201] = 1000, [9203] = 1 }))
    assert(#plan.steps == 1 and plan.steps[1].crafts == 10 and m[9203].need == 30, "grey extra crafts counted towards the skill")
    -- a tool is made once and is no material of anything (no recipe uses it up)
    plan, m = Plan(Input("Testing", 1, 6, {
        R("Testing", "Make the tool", 9220, 1, 1, 2, { { 9221, 1 } }),
        R("Testing", "Use the tool", 9222, 1, 2, 6, { { 9223, 2 } }),
    }, {}, { [9221] = 1, [9223] = 1 }))
    assert(not m[9220] and m[9221].need == 1 and m[9223].need == 8, "a tool is listed as a material")
    -- an enchantment makes no item (product 0): a step all the same, nothing goes into the stock
    plan, m = Plan(Input("Testing", 1, 4, { R("Testing", "Enchant", 0, 1, 1, 4, { { 9230, 2 } }) }, {}, { [9230] = 3 }))
    assert(#plan.steps == 1 and plan.steps[1].crafts == 3 and m[9230].need == 6 and plan.total == 18 and plan.ledger[0] == nil, "an enchantment without an item")

    -- (4) nothing to plan from is never a plan
    for _, bad in ipairs({ false, {}, { prof = "Testing" }, { prof = "Testing", skill = 1, target = 5, recipes = { Testing = {} }, stock = {}, prices = {} },
        { prof = "Testing", skill = 1, target = 5, recipes = { Testing = { R("Testing", "A", 1, 1, 1, 5, { { 2, 1 } }) } } } }) do
        local p = core.Compute(bad or nil)
        assert(p.status == "invalid" and p.valid == false and p.complete == false and #p.steps == 0, "a plan from nothing")
    end
    -- you are there already: done, nothing to do
    plan = core.Compute(Input("Testing", 5, 5, { R("Testing", "A", 9200, 1, 1, 9, { { 9201, 1 } }) }, {}, {}))
    assert(plan.status == "done" and #plan.steps == 0 and #plan.materials == 0, "at the target: not done")
    -- no recipe for a skill: stuck, said so
    plan = core.Compute(Input("Testing", 1, 9, { R("Testing", "A", 9200, 1, 1, 4, { { 9201, 1 } }) }, {}, {}))
    assert(plan.stuck == 4 and plan.status == "incomplete" and Has(plan, "stuck"), "a gap is not reported")

    -- (5) the nine crafting categories through this one core, with the game's
    -- own recipe data: every plan balances and says where it ends
    assert(ns.SkillPlanSnapshot, "no snapshot for the calculation")
    for _, prof in ipairs({ "Alchemy", "Blacksmithing", "Enchanting", "Engineering", "Leatherworking", "Tailoring", "Cooking", "First Aid", "Mining" }) do
        local p = core.Compute(ns.SkillPlanSnapshot(prof, 1, 300))
        local ok, why = core.CheckBalance(p)
        assert(ok, prof .. ": " .. tostring(why))
        assert(p.valid and #p.steps > 0 and #p.materials > 0, prof .. ": no plan")
        if prof == "Mining" then
            assert(p.stuck and p.status == "incomplete", "Mining: the gap after the last smelting recipe is not shown")
        else
            assert(not p.stuck and p.steps[#p.steps].to == 300, prof .. ": the plan ends at " .. tostring(p.steps[#p.steps].to))
        end
    end
end)
step("Skill plan 2.0: every price is known, estimated or unknown - into the choice and the sum (v0.2 A3)", function()
    -- concept 4.5. Plain tables; a recipe gives one point per craft from its
    -- required skill up to `upto`.
    local core = ns.PlanCore
    local function R(key, product, req, upto, reagents)
        local list = {}
        for _, r in ipairs(reagents) do list[#list + 1] = { id = r[1], n = r[2] } end
        return { prof = "Testing", key = key, name = key, product = product, made = 1, req = req, yellow = upto, grey = upto, reagents = list, learn = "known" }
    end
    local function Plan(recipes, prices, stock, to)
        local plan = core.Compute({ prof = "Testing", skill = 1, target = to or 6, recipes = { Testing = recipes }, professions = { Testing = { rank = 1 } },
            stock = stock or {}, prices = prices, recipeItemPrices = {}, nodes = {}, caps = {} })
        local m = {}
        for _, row in ipairs(plan.materials) do m[row.id] = row end
        return plan, m
    end
    local known, est, none = function(c) return { status = "known", copper = c, source = "AH scan", age = 60 } end,
        function(c) return { status = "estimated", copper = c, source = "vendor (est.)" } end, { status = "unknown" }
    local A, B = function() return R("A", 9300, 1, 6, { { 9301, 2 } }) end, function() return R("B", 9310, 1, 6, { { 9311, 1 } }) end

    -- everything known: the sum by hand, no gaps
    local plan, m = Plan({ A() }, { [9301] = known(7) })
    assert(plan.cost.known == 5 * 2 * 7 and plan.cost.estimated == 0 and #plan.cost.unknownItems == 0 and plan.total == 70, "all known: the sum")
    assert(m[9301].costStatus == "known" and m[9301].cost == 70 and m[9301].price.source == "AH scan" and m[9301].price.age == 60, "all known: the row")
    assert(not plan.notComparable and plan.steps[1].comparable, "all known: called not comparable")
    -- a real price of 0 is a price: known, 0, comparable
    plan, m = Plan({ A() }, { [9301] = known(0) })
    assert(m[9301].costStatus == "known" and m[9301].cost == 0 and #plan.cost.unknownItems == 0 and not plan.notComparable, "a real price of 0")
    -- an estimated price: in the sum, but apart and named
    plan, m = Plan({ A() }, { [9301] = est(4) })
    assert(plan.cost.known == 0 and plan.cost.estimated == 40 and plan.cost.estimatedItems[1] == 9301 and plan.total == 40, "estimated: the sum")
    assert(m[9301].costStatus == "estimated" and plan.steps[1].estimated and plan.steps[1].comparable, "estimated: the row or the step")
    -- no price: unknown - not 0, not in any sum, the item named
    for _, prices in ipairs({ {}, { [9301] = none }, { [9301] = { status = "known" } }, { [9301] = { copper = "12" } } }) do
        plan, m = Plan({ A() }, prices)
        assert(m[9301].missing == 10 and m[9301].cost == nil and m[9301].costStatus == "unknown", "unknown: a cost for a missing material without a price")
        assert(plan.cost.known == 0 and plan.cost.estimated == 0 and plan.total == 0 and plan.cost.unknownItems[1] == 9301 and plan.learn.matsUnknown == 1, "unknown: the sum")
        assert(plan.notComparable and plan.steps[1].comparable == false, "unknown: the choice is called comparable")
    end
    -- partly unknown: the known part is a sum, the rest is listed - never one "cost" for both
    plan, m = Plan({ R("A", 9300, 1, 6, { { 9301, 2 }, { 9302, 1 } }) }, { [9301] = known(7) })
    assert(plan.cost.known == 70 and #plan.cost.unknownItems == 1 and plan.cost.unknownItems[1] == 9302 and m[9302].cost == nil, "partly unknown")
    -- nothing is missing: nothing to pay, whatever the price is
    plan, m = Plan({ A() }, {}, { [9301] = 10 })
    assert(m[9301].missing == 0 and m[9301].cost == 0 and m[9301].costStatus == "none" and #plan.cost.unknownItems == 0, "nothing missing, but a cost or a gap")

    -- the choice: a recipe with a gap never wins because its part sum is small.
    -- A: 2 x 9301 at 500c = 1000c a craft, all known. B: 1 x 9311, no price.
    plan = Plan({ A(), B() }, { [9301] = known(500) })
    assert(#plan.steps == 1 and plan.steps[1].recipe.key == "A" and not plan.notComparable, "a recipe without a price beat one with a known cost")
    -- B with a second material at 1c: its part sum (1c) is far below A's 1000c - still A
    plan = Plan({ A(), R("B", 9310, 1, 6, { { 9311, 1 }, { 9312, 1 } }) }, { [9301] = known(500), [9312] = known(1) })
    assert(plan.steps[1].recipe.key == "A", "a part sum won the comparison")
    -- both whole: the lower cost wins, an estimate counts with its number
    plan = Plan({ A(), B() }, { [9301] = known(500), [9311] = est(300) })
    assert(plan.steps[1].recipe.key == "B" and plan.steps[1].estimated, "an estimated price is not compared")
    -- only recipes with gaps: the one with fewer pieces without a price, and the plan says it is not comparable
    plan = Plan({ A(), B() }, {})
    assert(plan.steps[1].recipe.key == "B" and plan.notComparable, "only gaps: not the smaller gap, or not said")
    -- where the comparable recipe ends (grey at 4) the other one takes over, marked
    plan = Plan({ R("A", 9300, 1, 4, { { 9301, 1 } }), B() }, { [9301] = known(5) })
    assert(#plan.steps == 2 and plan.steps[1].recipe.key == "A" and plan.steps[2].recipe.key == "B" and plan.steps[2].comparable == false and plan.notComparable,
        "the recipe with a gap does not take over where nothing else is left")

    -- buying against making: an estimated price takes part with its number;
    -- an unknown buying price does not make the item free, it is made
    plan, m = Plan({ R("A", 9300, 1, 6, { { 9320, 1 } }), R("Make it", 9320, 1, 1, { { 9321, 1 } }) }, { [9320] = est(3), [9321] = known(10) })
    assert(not m[9320].madeFrom and m[9320].costStatus == "estimated" and m[9320].cost == 15, "an estimated buying price is not compared with making")
    plan, m = Plan({ R("A", 9300, 1, 6, { { 9320, 1 } }), R("Make it", 9320, 1, 1, { { 9321, 1 } }) }, { [9321] = known(10) })
    assert(m[9320].madeFrom and m[9321].cost == 50 and #plan.cost.unknownItems == 0, "no buying price: not made from what has a price")

    -- the snapshot (Planner.lua): what a vendor PAYS is no buying price, the
    -- old stand-ins are gone, the Crafting tab's own estimate is "estimated"
    local d = ns.CraftData
    local saved = { price = ns.GetPrice, vendor = ns.db.vendorPrices, cost = d.ReagentCost }
    local ok, err = pcall(function()
        ns.db.vendorPrices = { [9401] = 30 }
        ns.GetPrice = function(id)
            if id == 9402 then return 55, "AH scan" end
            if id == 9403 then return 9, "vendor" end -- what a vendor pays for it
        end
        local prices = ns.SkillPlanSnapshot("Alchemy", 1, 5).prices
        assert(prices[9401].status == "known" and prices[9401].copper == 30 and prices[9401].source == "vendor", "a vendor's buying price")
        assert(prices[9402].status == "known" and prices[9402].copper == 55 and prices[9402].source == "AH scan", "an auction price")
        assert(prices[9403].status == "unknown" and prices[9403].copper == nil, "a vendor's SELL price was taken for a buying price (or four times it)")
        assert(prices[9404].status == "unknown" and prices[9404].copper == nil, "no price at all became a number")
        d.ReagentCost = function(id) if id == 9405 then return 12, "vendor (est.)", true end return saved.cost(id) end
        prices = ns.SkillPlanSnapshot("Alchemy", 1, 5).prices
        assert(prices[9405].status == "estimated" and prices[9405].copper == 12, "the Crafting tab's estimate is not marked estimated")
    end)
    ns.GetPrice, ns.db.vendorPrices, d.ReagentCost = saved.price, saved.vendor, saved.cost
    if not ok then error(err, 0) end
    local f = assert(io.open(ROOT .. "/Planner.lua"))
    local src = f:read("*a") f:close()
    assert(not src:find("UNKNOWN_PRICE", 1, true) and not src:find("sell * 4", 1, true), "Planner.lua still has a stand-in price")
    f = assert(io.open(ROOT .. "/PlanCore.lua"))
    src = f:read("*a") f:close()
    assert(not src:find("standin", 1, true), "PlanCore.lua still uses a stand-in price")
end)
step("Skill plan 2.0: chance, number of crafts with its range, and the recipe choice (v0.2 A4)", function()
    -- concept 4.1 and 4.2, on plain tables
    local core = ns.PlanCore
    -- (1) the chance of a recipe: orange 1, falling to 0 at grey, unknown without thresholds
    local r = { req = 10, yellow = 20, grey = 40 }
    assert(core.ChanceOf(r, 5) == 0 and core.ChanceOf(r, 10) == 1 and core.ChanceOf(r, 19) == 1, "below the required skill 0, orange 1")
    assert(core.ChanceOf(r, 20) == 1 and core.ChanceOf(r, 30) == 0.5 and core.ChanceOf(r, 35) == 0.25, "between yellow and grey (no green threshold is made up)")
    assert(core.ChanceOf(r, 40) == 0 and core.ChanceOf(r, 300) == 0, "grey gives nothing")
    for _, bad in ipairs({ { req = 1 }, { req = 1, yellow = 20 }, { req = 1, grey = 40 }, { req = 1, yellow = "20", grey = 40 }, { req = 1, yellow = 40, grey = 20 } }) do
        assert(core.ChanceOf(bad, 10) == nil, "missing or wrong thresholds give a chance")
    end
    assert(core.ChanceOf({ req = 1, yellow = 30, grey = 30 }, 29) == 1 and core.ChanceOf({ req = 1, yellow = 30, grey = 30 }, 30) == 0, "yellow = grey: no division")

    -- (2) how many crafts: the mean and the 10th / 90th percentile, against
    -- small cases worked out by hand
    local function Is(ps, expected, low, high, what)
        local a = core.Attempts(ps)
        assert(a and math.abs(a.expected - expected) < 1e-9 and a.low == low and a.high == high,
            ("%s: mean %s, range %s-%s, want %s, %s-%s"):format(what, tostring(a and a.expected), tostring(a and a.low), tostring(a and a.high), expected, low, high))
    end
    Is({ 1, 1, 1 }, 3, 3, 3, "three certain points")
    -- one point at 50 %: done within n crafts with 1 - 0.5^n -> 0.5, 0.75, 0.875, 0.9375
    Is({ 0.5 }, 2, 1, 4, "one point at 50 %")
    -- one point at 10 %: 1 - 0.9^n reaches 0.1 at n = 1 and 0.9 at n = 22 (0.9^21 = 0.109, 0.9^22 = 0.098)
    Is({ 0.1 }, 10, 1, 22, "one point at 10 %")
    -- two points at 50 %: done within n with 1 - (n + 1) / 2^n -> n = 2: 0.25; n = 6: 0.891; n = 7: 0.9375
    Is({ 0.5, 0.5 }, 4, 2, 7, "two points at 50 %")
    -- a changing chance: a certain point, then one at 50 %: one craft more than the single 50 % point
    Is({ 1, 0.5 }, 3, 2, 5, "a certain point and one at 50 %")
    Is({}, 0, 0, 0, "no point to make")
    assert(core.Attempts({ 0.5, 0 }) == nil and core.Attempts({ 0 }) == nil, "a chance of 0 gives a number of crafts")
    -- the same input, the same range: no random numbers
    local a1, a2 = core.Attempts({ 0.3, 0.2, 0.15 }), core.Attempts({ 0.3, 0.2, 0.15 })
    assert(a1.low == a2.low and a1.high == a2.high and a1.low < a1.expected and a1.expected < a1.high, "the range is not the same twice, or the mean is outside it")

    local function R(key, product, req, yellow, grey, reagents, learn)
        local list = {}
        for _, x in ipairs(reagents) do list[#list + 1] = { id = x[1], n = x[2] } end
        return { prof = "Testing", key = key, name = key, product = product, made = 1, req = req, yellow = yellow, grey = grey, reagents = list,
            learn = learn == nil and "known" or learn or nil }
    end
    local function Plan(from, to, recipes, prices, more)
        local p = {}
        for id, copper in pairs(prices or {}) do p[id] = { status = "known", copper = copper } end
        local input = { prof = "Testing", skill = from, target = to, recipes = { Testing = recipes }, professions = { Testing = { rank = from } },
            stock = {}, prices = p, recipeItemPrices = {}, nodes = {}, caps = {} }
        for k, v in pairs(more or {}) do input[k] = v end
        return core.Compute(input)
    end
    local function Has(plan, code)
        for _, d in ipairs(plan.diagnostics) do if d.code == code then return d end end
    end

    -- (3) the steps carry the mean and the model's range
    local plan = Plan(1, 6, { R("A", 9500, 1, 6, 6, { { 9501, 1 } }) }, { [9501] = 1 })
    assert(plan.steps[1].crafts == 5 and plan.steps[1].low == 5 and plan.steps[1].high == 5 and plan.steps[1].chanceFrom == 1, "certain points: a range")
    -- 6 -> 8 with yellow 1, grey 11: 50 % and 40 % -> 2 + 2.5 = 4.5 crafts, shown as 5
    plan = Plan(6, 8, { R("A", 9500, 1, 1, 11, { { 9501, 1 } }) }, { [9501] = 1 })
    local s = plan.steps[1]
    local want = core.Attempts({ 0.5, 0.4 })
    assert(math.abs(s.expected - 4.5) < 1e-9 and s.crafts == 5 and s.low == want.low and s.high == want.high and s.low < 5 and s.high > 5,
        ("a yellow step: mean %s, %s-%s"):format(tostring(s.expected), tostring(s.low), tostring(s.high)))
    assert(s.chanceFrom == 0.5 and s.chanceTo == 0.4, "the chance at the start and the end of the step")
    -- the plan's sum is the sum of the means; the steps' ranges are not added up
    plan = Plan(6, 10, { R("A", 9500, 1, 1, 11, { { 9501, 1 } }) }, { [9501] = 1 }, { caps = { 8 } })
    assert(#plan.steps == 2 and math.abs(plan.crafts - (plan.steps[1].expected + plan.steps[2].expected)) < 1e-9, "the plan's crafts are not the sum of the means")
    assert(plan.low == nil and plan.high == nil, "a range for the whole plan made from the steps' ranges")
    -- grey only: no number of crafts gets there - stuck, no division by zero
    plan = Plan(50, 55, { R("A", 9500, 1, 10, 20, { { 9501, 1 } }) }, { [9501] = 1 })
    assert(plan.stuck == 50 and #plan.steps == 0 and plan.status == "incomplete" and Has(plan, "stuck"), "a grey recipe is planned")
    -- thresholds missing: the recipe is named, never counted
    plan = Plan(1, 5, { R("A", 9500, 1, nil, nil, { { 9501, 1 } }) }, { [9501] = 1 })
    assert(#plan.steps == 1 and plan.steps[1].chanceUnknown and plan.steps[1].recipe.key == "A" and plan.steps[1].crafts == nil, "a recipe of unknown chance got a number of crafts")
    assert(Has(plan, "chance_unknown") and plan.status == "incomplete" and not plan.complete and #plan.materials == 0 and plan.stuck == 1, "unknown chance: not said, or materials counted")
    -- wrong thresholds (grey below yellow) the same
    plan = Plan(1, 5, { R("A", 9500, 1, 30, 10, { { 9501, 1 } }) }, { [9501] = 1 })
    assert(plan.steps[1] and plan.steps[1].chanceUnknown, "wrong thresholds are counted")
    -- next to a recipe with a known chance it is not used at all
    plan = Plan(1, 5, { R("A", 9500, 1, nil, nil, { { 9501, 1 } }), R("B", 9510, 1, 5, 5, { { 9511, 1 } }) }, { [9501] = 1, [9511] = 1000 })
    assert(#plan.steps == 1 and plan.steps[1].recipe.key == "B" and not Has(plan, "chance_unknown") and plan.complete, "a recipe of unknown chance beat a known one")

    -- (4) where a rank ends: training is a step between, no craft is planned across it
    local function Ranks(from, to, maxRank)
        return Plan(from, to, { R("A", 9500, 1, 300, 300, { { 9501, 1 } }) }, { [9501] = 1 }, { maxRank = maxRank, caps = { 75, 150, 225, 300 } })
    end
    plan = Ranks(60, 100, 75)
    assert(#plan.training == 1 and plan.training[1].at == 75 and plan.training[1].assumed == false, "your own maximum is not a training step")
    assert(#plan.steps == 2 and plan.steps[1].to == 75 and plan.steps[2].from == 75, "a step runs across the end of the rank")
    plan = Ranks(60, 100, nil)
    assert(#plan.training == 1 and plan.training[1].at == 75 and plan.training[1].assumed == true, "an assumed rank end is not marked assumed")
    plan = Ranks(60, 100, 150)
    assert(#plan.training == 0 and #plan.steps == 1, "training inside your rank")
    plan = Ranks(75, 160, 75)
    assert(plan.training[1].at == 75 and plan.training[2].at == 150 and plan.training[2].assumed and plan.steps[1].from == 75 and plan.steps[1].to == 150, "at your maximum: train first, then the next rank end")
    plan = Ranks(100, 100, 150)
    assert(plan.status == "done" and #plan.steps == 0 and #plan.training == 0, "at the target: not done")
    plan = Ranks(120, 100, 150)
    assert(plan.status == "done" and #plan.steps == 0, "past the target: not done")

    -- (5) the choice: the gold on top of what you have
    -- what is in stock costs nothing, but only as far as it goes: 3 of 9601
    -- (100c each) for A, then B at 10c - the stock is not free ten times
    plan = Plan(1, 11, { R("A", 9600, 1, 11, 11, { { 9601, 1 } }), R("B", 9610, 1, 11, 11, { { 9611, 1 } }) }, { [9601] = 100, [9611] = 10 }, { stock = { [9601] = 3 } })
    assert(#plan.steps == 2 and plan.steps[1].recipe.key == "A" and plan.steps[1].crafts == 3 and plan.steps[2].recipe.key == "B" and plan.steps[2].crafts == 7,
        ("stock in the choice: %s x%s, then %s"):format(plan.steps[1].recipe.key, tostring(plan.steps[1].crafts), tostring(plan.steps[2] and plan.steps[2].recipe.key)))
    assert(plan.total == 70, "what the plan costs on top: " .. plan.total)
    -- without the stock: B all the way
    plan = Plan(1, 11, { R("A", 9600, 1, 11, 11, { { 9601, 1 } }), R("B", 9610, 1, 11, 11, { { 9611, 1 } }) }, { [9601] = 100, [9611] = 10 })
    assert(#plan.steps == 1 and plan.steps[1].recipe.key == "B", "no stock: the dear recipe is used")
    -- "why this recipe": the next best one is named with its cost
    assert(plan.steps[1].why and plan.steps[1].why.other and plan.steps[1].why.other.key == "A" and plan.steps[1].why.comparable
        and plan.steps[1].why.other.score > plan.steps[1].why.score, "why this recipe: no comparison")
    -- learning costs once: B (4c a craft, 50c at the trainer) against A (10c, known).
    -- Ten points: 40 + 50 = 90 < 100 -> B. Five points: 20 + 50 = 70 > 50 -> A.
    local function Fee(to, fee, how)
        local b = R("B", 9610, 1, 99, 99, { { 9611, 1 } }, how or "trainer")
        b.fee = fee
        return Plan(1, to, { R("A", 9600, 1, 99, 99, { { 9601, 1 } }), b }, { [9601] = 10, [9611] = 4 })
    end
    plan = Fee(11, 50)
    assert(#plan.steps == 1 and plan.steps[1].recipe.key == "B" and plan.learn.fees == 50 and plan.learn.trainer == 1, "a fee that pays off over ten points")
    plan = Fee(6, 50)
    assert(#plan.steps == 1 and plan.steps[1].recipe.key == "A" and plan.learn.trainer == 0, "a fee that does not pay off over five points")
    -- a fee nobody knows: not fully comparable, the known recipe wins
    plan = Fee(11, nil)
    assert(plan.steps[1].recipe.key == "A", "a recipe with an unknown fee won the comparison")
    -- a recipe item from a vendor: its price counts when a vendor showed it
    local function Item(price)
        local b = R("B", 9610, 1, 99, 99, { { 9611, 1 } }, "vendor")
        b.recipeItem = 9699
        return Plan(1, 11, { R("A", 9600, 1, 99, 99, { { 9601, 1 } }), b }, { [9601] = 10, [9611] = 4 }, { recipeItemPrices = { [9699] = price } })
    end
    plan = Item(50)
    assert(plan.steps[1].recipe.key == "B" and plan.learn.items == 1 and plan.learn.itemCost == 50, "a recipe item with a price")
    plan = Item(nil)
    assert(plan.steps[1].recipe.key == "A", "a recipe item without a price won the comparison")
    plan = Item(5000)
    assert(plan.steps[1].recipe.key == "A", "a recipe item dearer than what it saves")
    -- a recipe nobody can count on (quest, drop: learn = nil) is left out; known, it is used
    plan = Plan(1, 6, { R("A", 9600, 1, 99, 99, { { 9601, 1 } }), R("Q", 9620, 1, 99, 99, { { 9621, 1 } }, false) }, { [9601] = 10, [9621] = 1 })
    assert(plan.steps[1].recipe.key == "A", "a quest recipe you don't have is planned")
    plan = Plan(1, 6, { R("A", 9600, 1, 99, 99, { { 9601, 1 } }), R("Q", 9620, 1, 99, 99, { { 9621, 1 } }, "known") }, { [9601] = 10, [9621] = 1 })
    assert(plan.steps[1].recipe.key == "Q", "a quest recipe you know is not used")
    -- a material you can make for less than it costs to buy counts at what making costs
    plan = Plan(1, 6, { R("A", 9600, 1, 99, 99, { { 9630, 1 } }), R("B", 9610, 1, 99, 99, { { 9611, 1 } }), R("Make it", 9630, 1, 1, 1, { { 9631, 1 } }) },
        { [9630] = 1000, [9631] = 5, [9611] = 50 })
    assert(plan.steps[1].recipe.key == "A" and plan.total == 25, "buying against making is not part of the choice")
    -- the plan's own output is spoken for like stock: A makes 9640, B uses it
    plan = Plan(1, 11, { R("A", 9640, 1, 6, 6, { { 9641, 1 } }), R("B", 9650, 6, 11, 11, { { 9640, 1 } }), R("C", 9660, 6, 11, 11, { { 9661, 1 } }) },
        { [9641] = 10, [9640] = 500, [9661] = 100 })
    assert(#plan.steps == 2 and plan.steps[2].recipe.key == "B" and plan.total == 50, "what the plan makes itself does not count in the choice")
    -- the comments and texts promise no "cheapest" way
    for _, file in ipairs({ "PlanCore.lua", "Planner.lua" }) do
        local f = assert(io.open(ROOT .. "/" .. file))
        local src = f:read("*a"):lower() f:close()
        assert(not src:find("cheapest", 1, true) and not src:find("guaranteed", 1, true), file .. " promises too much")
    end
end)
step("Skill plan 2.0: what you really have, progress, one plan per state (v0.2 A5)", function()
    -- concept 4.4 and 4.6
    local core = ns.PlanCore
    local function R(key, product, req, upto, reagents)
        local list = {}
        for _, x in ipairs(reagents) do list[#list + 1] = { id = x[1], n = x[2] } end
        return { prof = "Leatherworking", key = key, name = key, product = product, made = 1, req = req, yellow = upto, grey = upto, reagents = list, learn = "known" }
    end
    local function Leather(from, stock)
        local plan = core.Compute({ prof = "Leatherworking", skill = from, target = 97, professions = { Leatherworking = { rank = from } },
            recipes = { Leatherworking = {
                R("Light Leather", 2318, 1, 25, { { 2934, 3 } }),
                R("Light Armor Kit", 2304, 25, 74, { { 2318, 1 } }),
                R("Embossed Leather Gloves", 4239, 74, 97, { { 2318, 3 }, { 2320, 2 } }),
            } },
            stock = stock, prices = { [2318] = { copper = 1000 }, [2934] = { copper = 10 }, [2320] = { copper = 10 } },
            recipeItemPrices = {}, nodes = {}, caps = {} })
        assert(core.CheckBalance(plan))
        local m = {}
        for _, row in ipairs(plan.materials) do m[row.id] = row end
        return plan, m
    end
    local function Has(plan, code)
        for _, d in ipairs(plan.diagnostics) do if d.code == code then return d end end
    end

    -- (1) the stock: a number, a table with its parts, "unknown", or not listed (none)
    local plan, m = Leather(1, { [2318] = 35, [2320] = { n = 9, bags = 5, reagent = 0, bank = 4 } })
    assert(m[2318].have == 35 and m[2318].haveKnown and m[2320].have == 9 and m[2320].haveKnown and m[2320].stock.bank == 4, "a count as a number or with its parts")
    assert(m[2934].have == 0 and m[2934].haveKnown and m[2934].missing == 249, "an item the snapshot does not list: none")
    assert(plan.complete and not Has(plan, "stock_unknown"), "known counts: called unknown")
    -- a count that could not be read is not 0: the row says so, gets no tick, the plan is not called complete
    for _, unknown in ipairs({ { unknown = true }, { n = nil }, { n = "9" } }) do
        plan, m = Leather(1, { [2318] = 35, [2320] = unknown })
        assert(m[2320].haveKnown == false and m[2320].covered == false, "an unreadable count is taken for a number")
        assert(Has(plan, "stock_unknown") and Has(plan, "stock_unknown").item == 2320 and plan.status == "incomplete" and not plan.complete and plan.valid, "an unreadable count: the plan is called complete")
        assert(m[2320].missing == 46, "an unreadable count: what is to buy is not worked out from none")
        local result = core.Result(plan)
        assert(result.items[2320].have == nil and result.items[2320].haveKnown == false, "the result gives a number for an unreadable count")
    end
    -- a known 0 is a count
    plan, m = Leather(1, { [2318] = 35, [2320] = 0 })
    assert(m[2320].haveKnown and m[2320].have == 0 and plan.complete, "a known 0 is called unknown")

    -- (2) the tick: only what you really have. Leather: 118 needed, 35 there,
    -- 24 from the steps, 59 made extra - nothing to buy, and no tick
    plan, m = Leather(1, { [2318] = 35, [2320] = 9 })
    assert(m[2318].missing == 0 and m[2318].planned == 24 and m[2318].covered == false, "a tick for leather the plan has yet to make")
    assert(m[2320].covered == false and m[2934].covered == false, "a tick for what is missing")
    plan, m = Leather(1, { [2318] = 118, [2320] = 46, [2934] = 72 })
    assert(m[2318].covered and m[2320].covered and m[2934].covered and plan.total == 0, "no tick although everything is there")
    -- what a step makes for the next one is a forecast: B needs 5 of what A makes
    local chain = core.Compute({ prof = "Testing", skill = 1, target = 11, professions = {}, recipeItemPrices = {}, nodes = {}, caps = {},
        recipes = { Testing = {
            { prof = "Testing", key = "A", name = "A", product = 9700, made = 1, req = 1, yellow = 6, grey = 6, reagents = { { id = 9701, n = 1 } }, learn = "known" },
            { prof = "Testing", key = "B", name = "B", product = 9710, made = 1, req = 6, yellow = 11, grey = 11, reagents = { { id = 9700, n = 1 } }, learn = "known" } } },
        stock = {}, prices = { [9701] = { copper = 1 }, [9700] = { copper = 500 } } })
    local row
    for _, x in ipairs(chain.materials) do if x.id == 9700 then row = x end end
    assert(row and row.need == 5 and row.missing == 0 and row.planned == 5 and row.have == 0 and row.covered == false, "a tick for a product of a later step")
    assert(core.Result(chain).items[9700].covered == false and core.Result(chain).items[9700].planned == 5, "the result ticks a forecast")

    -- (3) progress: the plan is made again from what is there now, so what is
    -- done counts once. After the first step (24 Light Leather made from 72
    -- scraps): skill 25, leather 35 + 24 = 59, no scraps left
    plan, m = Leather(25, { [2318] = 59, [2320] = 9 })
    assert(#plan.steps == 2 and plan.steps[1].recipe.key == "Light Armor Kit", "progress: the done step is planned again")
    assert(m[2318].need == 118 and m[2318].have == 59 and m[2934].need == 177, ("progress: %d scraps, want 249 - 72 = 177"):format(m[2934].need))
    assert(m[2320].missing == 37, "progress: the thread")
    -- you bought the thread: ticked, nothing more to buy of it
    plan, m = Leather(25, { [2318] = 59, [2320] = 46 })
    assert(m[2320].covered and m[2320].missing == 0 and plan.total == 177 * 10, "progress: bought thread")
    -- 10 leather from the bank: 10 extra crafts less, 30 scraps less
    plan, m = Leather(25, { [2318] = 69, [2320] = 46 })
    assert(m[2934].need == 147, "progress: leather from the bank")
    -- half of the kits done (skill 50: 25 kits made, 25 leather used up)
    plan, m = Leather(50, { [2318] = 44, [2320] = 46 })
    assert(m[2318].need == 24 + 69 and m[2934].need == (93 - 44) * 3, "progress: used leather is asked for again, or made leather counted twice")
    -- at the end: done
    plan = Leather(97, {})
    assert(plan.status == "done" and #plan.materials == 0, "progress: at the target")

    -- (4) the window calculates on one snapshot with a revision
    local d = ns.CraftData
    local saved = { have = d.Have, rank = ns.ProfessionRank, price = ns.GetPrice, compute = core.Compute, secret = issecretvalue, listeners = ns.skillPlanListeners }
    local ok, err = pcall(function()
        local stock, rank, computes, counts, heard = { [2318] = 34 }, 30, 0, {}, {}
        d.Have = function(id) counts[id] = (counts[id] or 0) + 1 return stock[id] or 0 end
        ns.ProfessionRank = function(p) if p == "Leatherworking" then return rank, 75 end end
        core.Compute = function(input) computes = computes + 1 return saved.compute(input) end
        ns.skillPlanListeners = { function(result) heard[#heard + 1] = result.revision end }
        ns.ShowSkillPlan("Leatherworking") advance(1)
        local win = _G.GathercraftSkillPlan
        local result = ns.SkillPlanResult()
        assert(result and result.revision and result.prof == "Leatherworking" and result.valid, "no result to read")
        local rev = result.revision
        assert(result.items[2318] and result.items[2318].have == 34 and result.items[2318].need > 0 and result.items[2318].missing ~= nil, "the result has no need / have / missing per item")
        -- one count per item and plan, also when several recipes use it
        for id, n in pairs(counts) do assert(n <= 2, ("item %d was counted %d times for one plan"):format(id, n)) end
        -- nothing changed: a burst of events calculates nothing, the revision stays
        computes, heard = 0, {}
        for _ = 1, 3 do fire("BAG_UPDATE_DELAYED") fire("PLAYERBANKSLOTS_CHANGED") end
        advance(1)
        fire("BAG_UPDATE_DELAYED") advance(1)
        assert(computes == 0 and ns.SkillPlanResult().revision == rev and #heard == 0, ("nothing changed, calculated %d times"):format(computes))
        -- a change: one new plan for the whole burst
        stock[2318] = 40
        for _ = 1, 3 do fire("BAG_UPDATE_DELAYED") end
        advance(1)
        assert(computes == 1 and ns.SkillPlanResult().revision == rev + 1 and ns.SkillPlanResult().items[2318].have == 40 and #heard == 1 and heard[1] == rev + 1,
            ("a change in the bags: calculated %d times, revision %d"):format(computes, ns.SkillPlanResult().revision - rev))
        -- the same event again, late: nothing
        fire("BAG_UPDATE_DELAYED") advance(1)
        assert(computes == 1, "a late event of the same change calculated again")
        -- the skill went up
        rank = 31
        fire("SKILL_LINES_CHANGED") advance(1)
        assert(computes == 2 and ns.SkillPlanResult().from == 31, "a skill point does not make a new plan")
        -- a price changed: the next look takes it, not before
        ns.GetPrice = function(id) return 77, "AH scan" end
        assert(computes == 2, "a new price made the plan jump on its own")
        fire("BAG_UPDATE_DELAYED") advance(1)
        assert(computes == 3, "a changed price is not taken at the next look")
        -- closed: nothing is counted or calculated, the last result stays
        win:Hide()
        local before = ns.SkillPlanResult().revision
        computes, counts = 0, {}
        stock[2318] = 99
        fire("BAG_UPDATE_DELAYED") fire("SKILL_LINES_CHANGED") advance(2)
        assert(computes == 0 and next(counts) == nil and ns.SkillPlanResult().revision == before, "the closed plan calculates")
        -- a count the client hides, or a count function that fails: unknown, no error
        local SECRET = newproxy(true)
        issecretvalue = function(v) return rawequal(v, SECRET) end
        d.Have = function(id) if id == 2318 then return SECRET end return 0 end
        local snap = ns.SkillPlanSnapshot("Leatherworking", 30, 75)
        assert(snap.stock[2318].unknown and snap.stock[2320].n == 0, "a hidden count is taken for a number")
        d.Have = function(id) if id == 2318 then error("no count") end return 0 end
        snap = ns.SkillPlanSnapshot("Leatherworking", 30, 75)
        assert(snap.stock[2318].unknown, "a failing count is taken for a number")
        d.Have = function() return nil end
        assert(ns.SkillPlanSnapshot("Leatherworking", 30, 75).stock[2318].unknown, "no answer is taken for 0")
        d.Have = function(id) if id == 2318 then return SECRET end return 0 end
        local shown, why = pcall(function() ns.ShowSkillPlan("Leatherworking") advance(1) end)
        assert(shown, "a hidden count breaks the window: " .. tostring(why))
        assert(ns.SkillPlanResult().items[2318] and ns.SkillPlanResult().items[2318].haveKnown == false and ns.SkillPlanResult().complete == false, "a hidden count: the plan is called complete")
        win:Hide()
    end)
    d.Have, ns.ProfessionRank, ns.GetPrice, core.Compute, issecretvalue, ns.skillPlanListeners = saved.have, saved.rank, saved.price, saved.compute, saved.secret, saved.listeners
    if _G.GathercraftSkillPlan then _G.GathercraftSkillPlan:Hide() end
    if not ok then error(err, 0) end
end)
step("Skill plan 2.0: the window - one profession, skill read, target menu, have / need (v0.2 A6)", function()
    -- concept 5
    local L, core, d = ns.L, ns.PlanCore, ns.CraftData
    local saved = { rank = ns.ProfessionRank, have = d.Have, known = d.Known, price = ns.GetPrice, filter = ns.CraftFilter, compute = core.Compute,
        lines = GetNumSkillLines, line = GetSkillLineInfo, secret = issecretvalue, targets = ns.db.planTargets, tab = ns.db.craftTab,
        waypoint = ns.SetWaypoint, run = ns.StartRun, vendor = ns.db.vendorPrices, log = ns.db.craftLog }
    local function Rows()
        local list = {}
        for _, o in ipairs(allFrames) do
            if o.left and o.mid and o.right and o:IsShown() and o.__pts and o.__pts.TOPLEFT then list[#list + 1] = o end
        end
        table.sort(list, function(a, b) return a.__pts.TOPLEFT[2] > b.__pts.TOPLEFT[2] end)
        return list
    end
    local function Shows(text)
        for _, row in ipairs(Rows()) do
            for _, part in ipairs({ row.left, row.mid, row.right }) do
                local t = part:GetText()
                if type(t) == "string" and t:find(text, 1, true) then return row end
            end
        end
    end
    local function Tip(row)
        local lines = {}
        if row and row.tip then row.tip({ AddLine = function(_, t) lines[#lines + 1] = t end }) end
        return table.concat(lines, "\n")
    end
    local win
    local ok, err = pcall(function()
        local ranks, computes, filter = {}, 0, "mine"
        ns.ProfessionRank = function(p) local r = ranks[p] if r then return r[1], r[2] end end
        d.Have = function() return 0 end
        d.Known = function() return {} end
        ns.GetPrice = function() return 10, "AH scan" end
        ns.db.vendorPrices = {}
        ns.CraftFilter = function() return filter end
        core.Compute = function(input) computes = computes + 1 return saved.compute(input) end
        ns.db.planTargets = nil

        -- (1) no single profession chosen: said so, nothing planned, no plan of another profession
        ns.ShowSkillPlan() advance(1)
        win = _G.GathercraftSkillPlan
        local target = _G.GathercraftSkillPlanTarget
        assert(win:IsShown() and Shows(L["Choose a profession first."]), "no profession chosen: not said")
        assert(computes == 0 and not target:IsShown(), "no profession chosen: a plan was made")
        slash("plan") advance(1)
        assert(Shows(L["Choose a profession first."]) and computes == 0, "/gcr plan without a chosen profession plans something")
        -- no switch for the profession in the window (no < > buttons)
        for _, o in ipairs(allFrames) do
            if o.__kind == "Button" and o.__parent == win then
                assert(o.__text ~= "<" and o.__text ~= ">", "the plan window has arrows")
            end
        end
        -- (2) the profession chosen on the Crafting tab, and a change there
        local function Label()
            for _, o in ipairs(allFrames) do
                if o.__kind == "FontString" and o.__parent == win and o.__pts and o.__pts.TOPLEFT and o.__pts.TOPLEFT[1] == 26 then return o:GetText() end
            end
        end
        ranks.Tailoring, ranks.Alchemy = { 81, 150 }, { 10, 75 }
        filter = "Tailoring"
        ns.ShowSkillPlan() advance(1)
        assert(Label() == d.ProfLabel("Tailoring") and computes > 0, "the profession of the Crafting tab is not planned: " .. tostring(Label()))
        filter = "Alchemy"
        slash("plan") advance(1)
        assert(Label() == d.ProfLabel("Alchemy"), "a change on the Crafting tab is not followed")
        slash("plan tailoring") advance(1)
        assert(Label() == d.ProfLabel("Tailoring"), "/gcr plan <profession>")
        -- the Crafting tab's own button passes the profession it shows
        local f = assert(io.open(ROOT .. "/Crafting.lua"))
        local crafting = f:read("*a") f:close()
        assert(crafting:find('ns.ShowSkillPlan(filter ~= "mine" and filter or nil)', 1, true) and crafting:find("ns.CraftFilter = function() return filter end", 1, true),
            "the Crafting tab does not hand over its profession")

        -- (3) the target: the default once, then it stays as set
        -- What else is saved stays as it is, whatever is done with the target
        -- (Codex round 1, N2): recipes and a craft log prepared for it, written
        -- out in full before and compared with the same after.
        local function Dump(v)
            if type(v) ~= "table" then return type(v) .. ":" .. tostring(v) end
            local keys = {}
            for k in pairs(v) do keys[#keys + 1] = k end
            table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
            local parts = {}
            for _, k in ipairs(keys) do parts[#parts + 1] = tostring(k) .. "=" .. Dump(v[k]) end
            return "{" .. table.concat(parts, ",") .. "}"
        end
        saved.known("Tailoring") -- (the real reader once: this character's own entry is there before the comparison)
        ns.db.recipes["Other-Realm"] = { Tailoring = { rank = 7, list = { ["Bolt of Linen Cloth"] = "2996:1:1:1|2589:2" } } }
        local log = {}
        for i, entry in ipairs(saved.log or {}) do log[i] = entry end
        log[#log + 1] = { t = 1, prof = "Tailoring", name = "Bolt of Linen Cloth", before = 6, after = 7 }
        ns.db.craftLog = log
        local function Saved() return Dump(ns.db.recipes) .. "|" .. Dump(ns.db.craftLog) end
        local savedBefore = Saved()
        assert(savedBefore:find("Other-Realm", 1, true) and savedBefore:find("after=number:7", 1, true), "test setup: nothing prepared to compare")
        assert(target:IsShown() and target:GetText() == "150", "skill 81: the default target is not 150: " .. tostring(target:GetText()))
        ranks.Tailoring = { 82, 150 }
        fire("SKILL_LINES_CHANGED") advance(1)
        assert(target:GetText() == "150", "the target moved on its own")
        -- the menu: plain buttons 75 / 150 / 225 / 300, the default, a value of your own
        local menu, edit = _G.GathercraftSkillPlanTargetMenu, _G.GathercraftSkillPlanTargetEdit
        assert(menu and edit and not menu:IsShown(), "no target menu, or open at once")
        target.__scripts.OnClick(target)
        assert(menu:IsShown() and #menu.items == 5 and menu.items[1].__text == "75" and menu.items[4].__text == "300", "the menu's entries")
        menu.items[3].__scripts.OnClick(menu.items[3]) advance(1)
        assert(not menu:IsShown() and target:GetText() == "225", "a menu entry does not set the target")
        local key
        for k, v in pairs(ns.db.planTargets) do if v.Tailoring == 225 then key = k end end
        assert(key, "the target is not kept per character and profession (ns.db.planTargets)")
        -- a value of your own
        local function Type(text)
            target.__scripts.OnClick(target)
            edit:SetText(text)
            edit.__scripts.OnEnterPressed(edit)
            advance(1)
        end
        Type("120")
        assert(target:GetText() == "120" and Shows("82-") , "a value of your own is not taken")
        local note
        for _, o in ipairs(allFrames) do
            local at = o.__parent == win and o.__kind == "FontString" and o.__pts and o.__pts.BOTTOMLEFT
            if at and at[2] == 24 then note = o end
        end
        for _, bad in ipairs({ "abc", "0", "301", "12.5", "-5" }) do
            Type(bad)
            assert(target:GetText() == "120", "an invalid target was taken: " .. bad)
            assert((note:GetText() or ""):find((L["Enter a whole number from %d to %d."]):format(1, 300), 1, true), "no hint for " .. bad)
        end
        Type("82")
        assert(target:GetText() == "120" and (note:GetText() or ""):find((L["Your skill is already %d: choose a higher target."]):format(82), 1, true), "a target at your skill")
        Type("")
        assert(target:GetText() == "150" and not (note:GetText() or ""):find("|cffff7070", 1, true), "an empty value does not give the default back")
        Type("120")
        target.__scripts.OnClick(target)
        menu.items[5].__scripts.OnClick(menu.items[5]) advance(1)
        assert(target:GetText() == "150", "the Default entry")
        -- reached: done, no jump to the next rank
        Type("100")
        ranks.Tailoring = { 100, 150 }
        fire("SKILL_LINES_CHANGED") advance(1)
        assert(target:GetText() == "100" and Shows((L["Done: you have reached your target (%d)."]):format(100)), "target reached: not done, or the target jumped")
        ranks.Tailoring = { 300, 300 }
        ns.db.planTargets = nil
        ns.ShowSkillPlan("Tailoring") advance(1)
        assert(target:GetText() == "300" and Shows((L["Done: you have reached your target (%d)."]):format(300)), "at 300: a new plan")
        -- another profession keeps its own target
        ranks.Tailoring = { 82, 150 }
        ns.ShowSkillPlan("Tailoring") advance(1)
        assert(ns.SkillPlanSetTarget(120), "test setup: a target for Tailoring")
        ns.ShowSkillPlan("Alchemy") advance(1)
        assert(ns.SkillPlanSetTarget(60), "test setup: a target for Alchemy")
        ns.ShowSkillPlan("Tailoring") advance(1)
        assert(target:GetText() == "120", "another profession's target changed this one: " .. tostring(target:GetText()))
        ns.ShowSkillPlan("Alchemy") advance(1)
        assert(target:GetText() == "60", "a profession does not keep its own target")
        -- ... and nothing else that is saved was touched by any of it: the
        -- prepared recipes and craft log are, entry for entry, what they were
        assert(Saved() == savedBefore, "the plan window changed other saved data")
        -- (the comparison is not blind: one changed value, one removed entry and it fails)
        log[#log].after = 8
        assert(Saved() ~= savedBefore, "test setup: a changed craft log entry goes unnoticed")
        log[#log].after = 7
        local kept = ns.db.recipes["Other-Realm"].Tailoring.list
        ns.db.recipes["Other-Realm"].Tailoring.list = {}
        assert(Saved() ~= savedBefore, "test setup: a removed recipe goes unnoticed")
        ns.db.recipes["Other-Realm"].Tailoring.list = kept
        assert(Saved() == savedBefore, "test setup: the prepared data was not put back")

        -- (4) the skill is read, never assumed
        ns.db.planTargets = nil
        ranks.Alchemy = nil
        GetNumSkillLines = function() return 3 end
        GetSkillLineInfo = function(i) return ({ "Professions", "Herbalism", "Secondary" })[i], i ~= 2, true, 20, 0, 0, 75 end
        computes = 0
        ns.ShowSkillPlan("Alchemy") advance(1)
        assert(Shows(L["Not learned yet - learn it from a trainer. This is a preview from skill 1."]) and Shows("1-") and computes == 1 and target:GetText() == "75",
            "positively not learned: no preview from 1")
        -- a folded group may hide it: unknown, not "not learned"
        GetSkillLineInfo = function(i) return ({ "Professions", "Herbalism", "Secondary" })[i], i ~= 2, i ~= 3, 20, 0, 0, 75 end
        computes = 0
        ns.ShowSkillPlan("Alchemy") advance(1)
        assert(Shows(L["Your skill could not be read, so there is no plan yet."]) and computes == 0 and not target:IsShown(), "a folded skill group: planned from 1")
        -- no skill list at all, an empty one, a hidden line: unknown
        for _, case in ipairs({ function() GetNumSkillLines = function() return 0 end end, function() GetNumSkillLines = nil end,
            function() GetNumSkillLines = function() return 2 end GetSkillLineInfo = function() return nil end end }) do
            GetNumSkillLines, GetSkillLineInfo = saved.lines, saved.line
            case()
            computes = 0
            ns.ShowSkillPlan("Alchemy") advance(1)
            assert(Shows(L["Your skill could not be read, so there is no plan yet."]) and computes == 0, "an unreadable skill list: a plan from 1")
        end
        GetNumSkillLines, GetSkillLineInfo = saved.lines, saved.line
        -- a hidden skill value: unknown before anything is compared or counted
        local SECRET = newproxy(true)
        issecretvalue = function(v) return rawequal(v, SECRET) end
        ranks.Alchemy = { SECRET, 75 }
        computes = 0
        local shown, why = pcall(function() ns.ShowSkillPlan("Alchemy") advance(1) end)
        assert(shown, "a hidden skill breaks the window: " .. tostring(why))
        assert(Shows(L["Your skill could not be read, so there is no plan yet."]) and computes == 0, "a hidden skill: planned")
        ranks.Alchemy = { 10, SECRET }
        shown, why = pcall(function() ns.ShowSkillPlan("Alchemy") advance(1) end)
        local header
        for _, o in ipairs(allFrames) do
            if o.__kind == "FontString" and o.__parent == win and o:GetText() == (L["Your skill: %d"]):format(10) then header = o end
        end
        assert(shown and header and computes > 0, "a hidden maximum: the skill itself is not used: " .. tostring(why))
        issecretvalue = saved.secret
        ranks.Alchemy = { 10, 75 }

        -- (5) have / need, the tick, the forecast - on a plan made for it.
        -- A x7 (1-8) makes 9800 from 9801; B (8-11, about 4 crafts) needs 9800 and
        -- 2 x 9802; B's recipe is sold by a vendor. You have 60 of 9802, 2 of 9801.
        local recipeItem, vendorName
        for item, packed in pairs(GathercraftRecipeSources.items) do
            local id = packed:match("V:(%d+)")
            local npc = id and GathercraftRecipeSources.npcs[tonumber(id)]
            local name, area, friendly = (npc or ""):match("^([^|]*)|(%d*)|([^|]*)|")
            -- (a vendor both sides can buy from, so the test does not depend on the faction)
            local both = friendly == "" or (friendly and friendly:find("A", 1, true) and friendly:find("H", 1, true))
            -- (a recipe with one vendor: which of several is shown is the step of the 0.2 places)
            local one = packed:match("^V:%d+$") or packed:match("^V:%d+|") and not packed:find("V:%d+,")
            if name and name ~= "" and both and one and GathercraftAreaMaps[tonumber(area)] and (not recipeItem or item < recipeItem) then
                recipeItem, vendorName = item, name
            end
        end
        assert(recipeItem, "test setup: no vendor recipe in the shipped data")
        core.Compute = function(input)
            return saved.compute({ prof = input.prof, skill = 1, target = 11, professions = {}, caps = {}, nodes = { [9801] = "Test Vein" },
                recipes = { [input.prof] = {
                    { prof = input.prof, key = "A", name = "Recipe A", product = 9800, made = 1, req = 1, yellow = 8, grey = 8, reagents = { { id = 9801, n = 1 } }, learn = "known" },
                    { prof = input.prof, key = "B", name = "Recipe B", product = 9810, made = 1, req = 8, yellow = 8, grey = 16, reagents = { { id = 9800, n = 1 }, { id = 9802, n = 2 } },
                        learn = "vendor", recipeItem = recipeItem } } },
                stock = { [9802] = { n = 60 }, [9801] = { n = 2 } }, recipeItemPrices = { [recipeItem] = 500 },
                prices = { [9801] = { status = "known", copper = 10, source = "AH scan", age = 7200 }, [9800] = { status = "known", copper = 900 }, [9802] = { status = "known", copper = 5 } } })
        end
        ns.db.planTargets = nil
        ns.ShowSkillPlan("Alchemy") advance(1)
        local head = Shows(L["Materials"])
        assert(head and head.mid:GetText():find(L["have / need"], 1, true) and head.right:GetText() == L["missing"], "the column head have / need")
        local function Mat(id)
            local name = ns.ItemName and ns.ItemName(id) or (L["item "] .. id)
            for _, row in ipairs(Rows()) do if row.left:GetText() == name then return row end end
        end
        local covered, forecast, missing = Mat(9802), Mat(9800), Mat(9801)
        assert(covered and forecast and missing, "test setup: the material rows")
        -- what you really have covers it: tick (a texture, not a sign) and green
        assert(covered.check:IsShown() and covered.check.__tex and covered.check.__tex:find("ReadyCheck", 1, true), "no tick texture on a covered row")
        assert(covered.mid:GetText():find("60 / ", 1, true) and covered.mid:GetText():find("|cff55ff55", 1, true) and covered.right:GetText():find(L["enough"], 1, true), "a covered row: " .. covered.mid:GetText())
        for _, row in ipairs(Rows()) do
            for _, part in ipairs({ row.left, row.mid, row.right }) do
                assert(not (part:GetText() or ""):find("\226\156\147", 1, true), "a tick as a text sign")
            end
        end
        -- what the plan will make: no tick, called a forecast
        assert(not forecast.check:IsShown() and forecast.mid:GetText():find("0 / ", 1, true) and forecast.right:GetText():find(L["(from the plan's steps)"], 1, true),
            "a product of a later step is ticked or not named: " .. tostring(forecast.right:GetText()))
        assert(Tip(forecast):find((L["The plan's own steps will make %d - a forecast, not stock."]):format(7), 1, true), "the forecast is not explained")
        -- what is missing: how many, where from, what it costs, a farm run
        assert(not missing.check:IsShown() and missing.mid:GetText():find("2 / 7", 1, true) and missing.right:GetText():find("5", 1, true)
            and missing.right:GetText():find(L["AH"], 1, true), "a missing row: " .. tostring(missing.right:GetText()))
        assert(Tip(missing):find((L["You have %d of the %d the plan needs."]):format(2, 7), 1, true) and Tip(missing):find("AH scan", 1, true), "the row's tooltip")
        local ran
        ns.StartRun = function(what) ran = what end
        assert(missing.button:IsShown() and not covered.button:IsShown(), "the Farm button")
        missing.button.__scripts.OnClick(missing.button)
        assert(ran == "item:9801", "the Farm button starts " .. tostring(ran))
        -- the steps: range, chance, about how many with the model's range
        local stepA, stepB = Shows("Recipe A"), nil
        for _, row in ipairs(Rows()) do if (row.left:GetText() or ""):find("Recipe B", 1, true) and (row.left:GetText() or ""):find("8-", 1, true) then stepB = row end end
        assert(stepA and stepA.left:GetText():find("1-8", 1, true) and stepA.right:GetText():find("100 %", 1, true) and stepA.right:GetText():find((L["%dx"]):format(7), 1, true),
            "a certain step: " .. tostring(stepA and stepA.right:GetText()))
        assert(stepB and stepB.right:GetText():find("~", 1, true) and stepB.right:GetText():find("%(%d+%-%d+%)"), "a step with a chance has no range: " .. tostring(stepB and stepB.right:GetText()))
        local tip = Tip(stepB)
        assert(tip:find(L["A range of the model, not a guarantee."], 1, true) and tip:find("8", 1, true), "the range is not called a model range")
        assert(not tip:lower():find("cheapest", 1, true) and not tip:lower():find("guarantee%a") , "the tooltip promises too much")
        -- the recipe to learn: who sells it, a waypoint on a click
        assert(Shows(L["Recipes to learn"]), "no list of recipes to learn")
        local learn
        for _, row in ipairs(Rows()) do if row.left:GetText() == "Recipe B" and (row.right:GetText() or ""):find(vendorName, 1, true) then learn = row end end
        assert(learn and learn.click, "the vendor recipe is not listed with its vendor (" .. vendorName .. ")")
        local way
        ns.SetWaypoint = function(mapID, x, y) way = { mapID, x, y } return true end
        learn.click()
        assert(way and way[1] and way[2] > 0 and way[2] < 1, "no waypoint to the vendor")
        assert(Tip(learn):find(vendorName, 1, true) and Tip(learn):find(L["Click: set a waypoint."], 1, true), "the vendor's tooltip")
        -- a trainer recipe: "<profession> trainer"; the place of the nearest trainer of your
        -- faction (Data/Trainers.lua, 0.2 places) in the tooltip and on a click
        core.Compute = function(input)
            return saved.compute({ prof = input.prof, skill = 1, target = 6, professions = {}, caps = {}, nodes = {}, stock = {}, recipeItemPrices = {},
                recipes = { [input.prof] = { { prof = input.prof, key = "T", name = "Recipe T", product = 9820, made = 1, req = 1, yellow = 6, grey = 6,
                    reagents = { { id = 9821, n = 1 } }, learn = "trainer", fee = 250 } } },
                prices = { [9821] = { status = "known", copper = 10 } } })
        end
        ranks.Alchemy = { 11, 75 } -- (a new state, so the plan is made again)
        ns.ShowSkillPlan("Alchemy") advance(1)
        local trainer
        for _, row in ipairs(Rows()) do if row.left:GetText() == "Recipe T" then trainer = row end end
        assert(trainer and trainer.right:GetText():find((L["%s trainer"]):format(d.ProfLabel("Alchemy")), 1, true), "a trainer recipe: not said")
        local horde = false
        for _, packed in pairs(GathercraftTrainers.Alchemy) do
            local name, friendly = packed:match("^([^|]+)|%d|([AH]+)|")
            if friendly:find("H", 1, true) and Tip(trainer):find(name, 1, true) then horde = true end
        end
        assert(trainer.click and horde and Tip(trainer):find(L["Place from the Questie database: the NPC may not be there right now."], 1, true),
            "a trainer recipe: no trainer of your faction from the shipped data: " .. Tip(trainer))
        -- a recipe of unknown chance: named, not counted
        core.Compute = function(input)
            return saved.compute({ prof = input.prof, skill = 1, target = 6, professions = {}, caps = {}, nodes = {}, stock = {}, recipeItemPrices = {},
                recipes = { [input.prof] = { { prof = input.prof, key = "U", name = "Recipe U", product = 9830, made = 1, req = 1,
                    reagents = { { id = 9831, n = 1 } }, learn = "known" } } }, prices = { [9831] = { status = "known", copper = 12 } } })
        end
        ranks.Alchemy = { 12, 75 }
        ns.ShowSkillPlan("Alchemy") advance(1)
        local unknown = Shows("Recipe U")
        assert(unknown and unknown.right:GetText():find(L["chance unknown"], 1, true) and not unknown.right:GetText():find("%dx"), "a recipe of unknown chance got a number")
        -- nothing to plan from: said so, no rows of a plan
        core.Compute = function() return saved.compute({}) end
        ranks.Alchemy = { 13, 75 }
        ns.ShowSkillPlan("Alchemy") advance(1)
        assert(Shows(L["No plan: there is nothing to plan from."]) and not Shows(L["Materials"]), "nothing to plan from is shown as a plan")
    end)
    ns.ProfessionRank, d.Have, d.Known, ns.GetPrice, ns.CraftFilter, core.Compute = saved.rank, saved.have, saved.known, saved.price, saved.filter, saved.compute
    GetNumSkillLines, GetSkillLineInfo, issecretvalue = saved.lines, saved.line, saved.secret
    ns.db.planTargets, ns.db.craftTab, ns.SetWaypoint, ns.StartRun, ns.db.vendorPrices = saved.targets, saved.tab, saved.waypoint, saved.run, saved.vendor
    ns.db.craftLog = saved.log
    if ns.db.recipes then ns.db.recipes["Other-Realm"] = nil end
    if win then win:Hide() end
    if not ok then error(err, 0) end
end)
step("Trainer places: Data/Trainers.lua from the Questie database, rank from the English title (0.2 places, part 1)", function()
    -- the shipped file: credited, in the TOC, the skill plan's professions, every place on a known map
    local toc = assert(io.open(ROOT .. "/Gathercraft.toc")):read("*a")
    assert(toc:find("\nData\\Trainers.lua", 1, true) and toc:find("\nPlaces.lua", 1, true), "Data/Trainers.lua or Places.lua is not in the TOC")
    local f = assert(io.open(ROOT .. "/Data/Trainers.lua"))
    local text = f:read("*a") f:close()
    assert(text:find("^%-%- Generated by tools/import_trainers.py") and text:find("with the permission of the Questie team", 1, true), "the file's head does not credit the Questie team")
    f = assert(io.open(ROOT .. "/NOTICE.md"))
    local notice = f:read("*a") f:close()
    assert(notice:find("**Data/Trainers.lua**", 1, true) and notice:find("tools/import_trainers.py", 1, true), "NOTICE.md does not name Data/Trainers.lua")
    -- the source as it was when the file was made: the QuestieDB commit, in the head and in the README (R3 B-N2)
    local head = text:match("^(.-)\nGathercraftTrainers = {") or ""
    assert(head:find("\n-- Source: QuestieDB commit 3f10ca075123d3aeb110315adc17dc85d7c20f5e, data/Forever/foreverNpcDB.lua.\n", 1, true),
        "the file's head does not name the QuestieDB commit it was made from")
    f = assert(io.open(ROOT .. "/README.md"))
    local readme = f:read("*a") f:close()
    assert(readme:find("`Data/Trainers.lua`", 1, true) and readme:find("`tools/import_trainers.py`", 1, true)
        and readme:find("3f10ca0", 1, true), "the README does not name the trainer places and their source")
    local data = assert(GathercraftTrainers, "no GathercraftTrainers")
    local count = 0
    for _, prof in ipairs({ "Alchemy", "Blacksmithing", "Enchanting", "Engineering", "Leatherworking", "Tailoring", "Cooking", "First Aid", "Mining" }) do
        local n = 0
        for id, packed in pairs(assert(data[prof], "no trainers of " .. prof)) do
            local name, rank, friendly, places = packed:match("^([^|]+)|(%d)|([AH]+)|(.+)$")
            assert(name and tonumber(rank) <= 5 and (friendly == "A" or friendly == "H" or friendly == "AH"), "a trainer line: " .. packed)
            for place in (places .. ";"):gmatch("([^;]*);") do
                local area, x, y = place:match("^(%d+):(%d+):(%d+)$")
                assert(area and GathercraftAreaMaps[tonumber(area)] and tonumber(x) <= 10000 and tonumber(y) <= 10000, "a trainer place without a known map: " .. packed)
            end
            n = n + 1
        end
        assert(n >= 5, prof .. ": only " .. n .. " trainers")
        count = count + n
    end
    -- the ranks as the English titles name them ("Expert Alchemist", "Master Alchemist",
    -- "Alchemy Trainer"), no specialisation trainers ("Master Goblin Engineer")
    assert(data.Alchemy[3347] == "Yelmak|3|H|1637:5684:3303" and data.Alchemy[7948]:find("^Kylanna Windwhisper|5|A|"), "the ranks from the titles")
    assert(data.Engineering[8126] == nil and data.Engineering[7406] == nil and data.Leatherworking[7871] == nil, "a specialisation trainer is listed")
    local untitled = 0
    for _, packed in pairs(data.Mining) do if packed:find("^[^|]+|0|") then untitled = untitled + 1 end end
    assert(untitled > 0, "test setup: mining trainers' titles name no rank")
    assert(count >= 120, "only " .. count .. " trainers")
end)
step("Skill plan: the nearest trainer of your faction, sure before unsure, worked out when drawn (0.2 places, part 1)", function()
    local L, core, d = ns.L, ns.PlanCore, ns.CraftData
    local saved = { rank = ns.ProfessionRank, have = d.Have, known = d.Known, price = ns.GetPrice, filter = ns.CraftFilter, compute = core.Compute,
        targets = ns.db.planTargets, waypoint = ns.SetWaypoint, trainers = GathercraftTrainers, maps = GathercraftAreaMaps,
        map = player.map, x = player.x, y = player.y, faction = UnitFactionGroup }
    local function Rows()
        local list = {}
        for _, o in ipairs(allFrames) do
            if o.left and o.mid and o.right and o:IsShown() and o.__pts and o.__pts.TOPLEFT then list[#list + 1] = o end
        end
        table.sort(list, function(a, b) return a.__pts.TOPLEFT[2] > b.__pts.TOPLEFT[2] end)
        return list
    end
    local function Shows(text)
        for _, row in ipairs(Rows()) do
            local t = row.left:GetText()
            if type(t) == "string" and t:find(text, 1, true) then return row end
        end
    end
    local function Tip(row)
        local lines = {}
        if row and row.tip then row.tip({ AddLine = function(_, t) lines[#lines + 1] = t end }) end
        return table.concat(lines, "\n")
    end
    local ok, err = pcall(function()
        local ranks, plan = { Alchemy = { 60, 75 } }, { skill = 60, target = 80, maxRank = 75, caps = { 75 } }
        ns.ProfessionRank = function(p) local r = ranks[p] if r then return r[1], r[2] end end
        d.Have = function() return 0 end
        d.Known = function() return {} end
        ns.GetPrice = function() return 10, "AH scan" end
        ns.CraftFilter = function() return "Alchemy" end
        ns.db.planTargets = nil
        core.Compute = function(input)
            return saved.compute({ prof = input.prof, skill = plan.skill, target = plan.target, maxRank = plan.maxRank, caps = plan.caps, professions = {}, nodes = {}, stock = {},
                recipeItemPrices = {}, recipes = { [input.prof] = { { prof = input.prof, key = "A", name = "Recipe A", product = 9800, made = 1, req = 1, yellow = 500, grey = 500,
                    reagents = { { id = 9801, n = 1 } }, learn = "known" } } }, prices = { [9801] = { status = "known", copper = 10 } } })
        end
        -- areas of this test: 9001 Zone1413, 9002 Zone1440, 9003 Zone1412 (Kalimdor), 9004 Zone1420 (another continent)
        GathercraftAreaMaps = setmetatable({ [9001] = 1413, [9002] = 1440, [9003] = 1412, [9004] = 1420 }, { __index = saved.maps })
        -- (the nearer one has the higher NPC ID: not the first, the nearest)
        GathercraftTrainers = { Alchemy = {
            [901] = "Far Horde|2|AH|9002:5000:5000",
            [902] = "Near Horde|2|H|9001:5000:5000",
            [903] = "Alliance Next Door|2|A|9003:5100:5000",
            [904] = "Over The Sea|2|H|9004:5000:5000",
        } }
        player.map, player.x, player.y = 1412, 0.5, 0.5
        UnitFactionGroup = function() return "Horde", "Horde" end
        local function Draw(r)
            ranks.Alchemy = r -- (a new state, so the plan is made again)
            ns.ShowSkillPlan("Alchemy") advance(1)
        end
        local function Sub()
            local train = Shows((L["Train the next rank at your trainer (needed at %d)."]):format(plan.maxRank))
            assert(train, "test setup: no training step")
            for i, row in ipairs(Rows()) do
                if row == train then local nextRow = Rows()[i + 1] return train, nextRow end
            end
        end
        -- (1) two of your faction: the nearer; one of the other faction nearer still: not taken
        Draw({ 60, 75 })
        local train, sub = Sub()
        assert(sub and sub.left:GetText():find((L["Nearest trainer: %s (%s)"]):format("Near Horde", ns.GetZoneName(1413)), 1, true),
            "not the nearest trainer of your faction: " .. tostring(sub and sub.left:GetText()))
        assert(not sub.left:GetText():find(L["May not teach this rank."], 1, true), "a hint for Journeyman")
        local way
        ns.SetWaypoint = function(mapID, x, y) way = { mapID, x, y } return true end
        assert(sub.click and train.click, "no waypoint on a click")
        sub.click()
        assert(way and way[1] == 1413 and math.abs(way[2] - 0.5) < 1e-9 and math.abs(way[3] - 0.5) < 1e-9, "the waypoint is not the trainer's place")
        assert(Tip(sub):find(L["Place from the Questie database: the NPC may not be there right now."], 1, true) and Tip(train) == Tip(sub), "the tooltip does not name the source")
        -- (2) nothing worked out while you point at it, nor on a redraw where you are
        local searches = ns.PlacesSearches
        local lookups, keep = 0, ns.PlacesTrainer
        ns.PlacesTrainer = function(...) lookups = lookups + 1 return keep(...) end
        for _ = 1, 5 do Tip(sub) Tip(train) end
        ns.PlacesTrainer = keep
        assert(ns.PlacesSearches == searches and lookups == 0, "the trainer is looked up while you point at the row (" .. lookups .. ")")
        Draw({ 61, 75 })
        assert(ns.PlacesSearches == searches, "the trainer is searched again where you are")
        -- a bigger move: searched again; a zone change: searched again
        player.x = 0.6 -- (500 yards)
        Draw({ 62, 75 })
        assert(ns.PlacesSearches == searches + 1, "a move of 500 yards: not searched again (" .. (ns.PlacesSearches - searches) .. ")")
        fire("ZONE_CHANGED_NEW_AREA")
        Draw({ 63, 75 })
        assert(ns.PlacesSearches == searches + 2, "a zone change: not searched again")
        -- Journeyman from a trainer whose title names no rank ("Alchemy Trainer"): no hint
        GathercraftTrainers = { Alchemy = { [908] = "Untitled|0|H|9001:5000:5000" } }
        fire("ZONE_CHANGED_NEW_AREA")
        Draw({ 63, 75 })
        train, sub = Sub()
        assert(sub.left:GetText():find("Untitled", 1, true) and not sub.left:GetText():find(L["May not teach this rank."], 1, true)
            and not Tip(sub):find(L["May not teach this rank."], 1, true), "Journeyman: a hint from a title without a rank")
        GathercraftTrainers = { Alchemy = {
            [901] = "Far Horde|2|AH|9002:5000:5000",
            [902] = "Near Horde|2|H|9001:5000:5000",
            [903] = "Alliance Next Door|2|A|9003:5100:5000",
            [904] = "Over The Sea|2|H|9004:5000:5000",
        } }
        fire("ZONE_CHANGED_NEW_AREA")
        -- (3) the Alliance: the one next door
        UnitFactionGroup = function() return "Alliance", "Alliance" end
        Draw({ 64, 75 })
        train, sub = Sub()
        assert(sub.left:GetText():find("Alliance Next Door", 1, true), "an Alliance player: " .. sub.left:GetText())
        UnitFactionGroup = function() return "Horde", "Horde" end
        -- (4) on another continent: the one there; none on yours: another continent, its zone named
        player.map, player.x, player.y = 1420, 0.4, 0.5
        Draw({ 65, 75 })
        train, sub = Sub()
        assert(sub.left:GetText():find((L["Nearest trainer: %s (%s)"]):format("Over The Sea", ns.GetZoneName(1420)), 1, true), "the trainer of your continent: " .. sub.left:GetText())
        GathercraftTrainers = { Alchemy = { [901] = "Far Horde|2|AH|9002:5000:5000", [902] = "Near Horde|2|H|9001:5000:5000" } }
        fire("ZONE_CHANGED_NEW_AREA")
        Draw({ 66, 75 })
        train, sub = Sub()
        assert(sub.left:GetText():find((L["Trainer on another continent: %s (%s)"]):format("Far Horde", ns.GetZoneName(1440)), 1, true),
            "none on your continent: not the first by ID, its zone named: " .. sub.left:GetText())
        -- (5) Expert: a trainer whose title names Journeyman is not taken; one whose title names
        -- no rank is marked; a sure one on your continent comes first
        player.map, player.x, player.y = 1412, 0.5, 0.5
        plan.skill, plan.target, plan.maxRank, plan.caps = 140, 160, 150, { 150 }
        GathercraftTrainers = { Alchemy = {
            [905] = "Untitled Next Door|0|H|9003:5050:5000",
            [906] = "Expert Far Away|3|H|9002:5000:5000",
            [907] = "Journeyman Near|2|H|9003:5010:5000",
        } }
        fire("ZONE_CHANGED_NEW_AREA")
        Draw({ 140, 150 })
        train, sub = Sub()
        assert(sub.left:GetText():find("Expert Far Away", 1, true) and not sub.left:GetText():find(L["May not teach this rank."], 1, true),
            "Expert: not the trainer whose title names it: " .. sub.left:GetText())
        GathercraftTrainers = { Alchemy = { [905] = GathercraftTrainers.Alchemy[905], [907] = GathercraftTrainers.Alchemy[907] } }
        fire("ZONE_CHANGED_NEW_AREA")
        Draw({ 141, 150 })
        train, sub = Sub()
        assert(sub.left:GetText():find("Untitled Next Door", 1, true) and sub.left:GetText():find(L["May not teach this rank."], 1, true)
            and Tip(sub):find(L["May not teach this rank."], 1, true), "Expert from a trainer whose title names no rank: no hint: " .. sub.left:GetText())
        -- (6) no data: the plan as before, no row, no error
        GathercraftTrainers = nil
        fire("ZONE_CHANGED_NEW_AREA")
        Draw({ 142, 150 })
        train = Sub()
        assert(not train.click and not train.tip, "no trainer data: the training step got a place")
        for _, row in ipairs(Rows()) do
            assert(not (row.left:GetText() or ""):find("Untitled Next Door", 1, true), "no trainer data: a place was made up")
        end
    end)
    ns.ProfessionRank, d.Have, d.Known, ns.GetPrice, ns.CraftFilter, core.Compute = saved.rank, saved.have, saved.known, saved.price, saved.filter, saved.compute
    ns.db.planTargets, ns.SetWaypoint, GathercraftTrainers, GathercraftAreaMaps = saved.targets, saved.waypoint, saved.trainers, saved.maps
    player.map, player.x, player.y, UnitFactionGroup = saved.map, saved.x, saved.y, saved.faction
    fire("ZONE_CHANGED_NEW_AREA")
    if _G.GathercraftSkillPlan then _G.GathercraftSkillPlan:Hide() end
    if not ok then error(err, 0) end
end)
step("Skill plan: the nearest vendor of a recipe, else the first as before (0.2 places, part 2)", function()
    local L, core, d = ns.L, ns.PlanCore, ns.CraftData
    local saved = { rank = ns.ProfessionRank, have = d.Have, known = d.Known, price = ns.GetPrice, filter = ns.CraftFilter, compute = core.Compute,
        targets = ns.db.planTargets, waypoint = ns.SetWaypoint, sources = GathercraftRecipeSources, maps = GathercraftAreaMaps,
        map = player.map, x = player.x, y = player.y, faction = UnitFactionGroup }
    local function Learn()
        for _, o in ipairs(allFrames) do
            if o.left and o.right and o:IsShown() and o.left:GetText() == "Recipe V" then return o end
        end
    end
    local function Tip(row)
        local lines = {}
        if row and row.tip then row.tip({ AddLine = function(_, t) lines[#lines + 1] = t end }) end
        return table.concat(lines, "\n")
    end
    local ok, err = pcall(function()
        local ranks = {}
        ns.ProfessionRank = function(p) local r = ranks[p] if r then return r[1], r[2] end end
        d.Have = function() return 0 end
        d.Known = function() return {} end
        ns.GetPrice = function() return 10, "AH scan" end
        ns.CraftFilter = function() return "Alchemy" end
        ns.db.planTargets = nil
        core.Compute = function(input)
            return saved.compute({ prof = input.prof, skill = 1, target = 6, professions = {}, caps = {}, nodes = {}, stock = {}, recipeItemPrices = { [99901] = 500 },
                recipes = { [input.prof] = { { prof = input.prof, key = "V", name = "Recipe V", product = 9840, made = 1, req = 1, yellow = 6, grey = 6,
                    reagents = { { id = 9841, n = 1 } }, learn = "vendor", recipeItem = 99901 } } },
                prices = { [9841] = { status = "known", copper = 10 } } })
        end
        GathercraftAreaMaps = setmetatable({ [9001] = 1413, [9002] = 1440, [9003] = 1412 }, { __index = saved.maps })
        GathercraftRecipeSources = setmetatable({ items = { [99901] = "V:801,802,803,804" }, npcs = {
            [801] = "First By ID|9002|H|5000|5000",
            [802] = "The Nearest|9001|AH|5000|5000",
            [803] = "Alliance Next Door|9003|A|5100|5000",
            [804] = "No Map Yet|77777|H|5000|5000",
        } }, { __index = saved.sources })
        player.map, player.x, player.y = 1412, 0.5, 0.5
        UnitFactionGroup = function() return "Horde", "Horde" end
        fire("ZONE_CHANGED_NEW_AREA")
        local function Draw(r) ranks.Alchemy = r ns.ShowSkillPlan("Alchemy") advance(1) return Learn() end
        -- (1) three of your faction with a place: the nearest; the other faction's nearer one: not taken
        local row = Draw({ 1, 75 })
        assert(row and row.right:GetText():find("The Nearest", 1, true), "not the nearest vendor: " .. tostring(row and row.right:GetText()))
        local way
        ns.SetWaypoint = function(mapID, x, y) way = { mapID, x, y } return true end
        row.click()
        assert(way and way[1] == 1413, "the waypoint is not the nearest vendor's")
        assert(Tip(row):find((L["Sold by %s (%s)."]):format("The Nearest", ns.GetZoneName(1413)), 1, true)
            and Tip(row):find(L["Place from the Questie database: the NPC may not be there right now."], 1, true), "the vendor's tooltip: " .. Tip(row))
        local searches = ns.PlacesSearches
        local lookups, keep = 0, ns.PlacesVendor
        ns.PlacesVendor = function(...) lookups = lookups + 1 return keep(...) end
        for _ = 1, 5 do Tip(row) end
        ns.PlacesVendor = keep
        assert(ns.PlacesSearches == searches and lookups == 0, "the vendor is looked up while you point at the row (" .. lookups .. ")")
        -- (2) none on your continent: the first by ID with a place, as before
        player.map = 1420
        fire("ZONE_CHANGED_NEW_AREA")
        row = Draw({ 2, 75 })
        assert(row and row.right:GetText():find("First By ID", 1, true), "none on your continent: not the first as before: " .. tostring(row and row.right:GetText()))
        -- (3) no place known for any: the first by name as before, no waypoint
        GathercraftRecipeSources = setmetatable({ items = { [99901] = "V:804,805" }, npcs = { [804] = "No Map Yet|77777|H|5000|5000", [805] = "No Map Either|0|H|0|0" } },
            { __index = saved.sources })
        fire("ZONE_CHANGED_NEW_AREA")
        row = Draw({ 3, 75 })
        assert(row and row.right:GetText():find("No Map Yet", 1, true) and not row.click
            and Tip(row):find((L["Sold by %s (%s)."]):format("No Map Yet", L["place unknown"]), 1, true), "no place known: not the first as before")
    end)
    ns.ProfessionRank, d.Have, d.Known, ns.GetPrice, ns.CraftFilter, core.Compute = saved.rank, saved.have, saved.known, saved.price, saved.filter, saved.compute
    ns.db.planTargets, ns.SetWaypoint, GathercraftRecipeSources, GathercraftAreaMaps = saved.targets, saved.waypoint, saved.sources, saved.maps
    player.map, player.x, player.y, UnitFactionGroup = saved.map, saved.x, saved.y, saved.faction
    fire("ZONE_CHANGED_NEW_AREA")
    if _G.GathercraftSkillPlan then _G.GathercraftSkillPlan:Hide() end
    if not ok then error(err, 0) end
end)
step("Skill plan: an open window follows where you are - after a zone change or a longer way the nearest trainer and vendor again, text and click, and the plan is not worked out again (0.2 places, R3 B-M1)", function()
    -- Codex round 3 of the places, B-M1: the window was left open, you went
    -- to another zone - the row still named the trainer of before, and a
    -- click set his waypoint. Now the rows of places follow you, with
    -- nothing drawn by the test: only the real zone event, or walking, and
    -- time. The plan itself is not worked out again because you move.
    local L, core, d = ns.L, ns.PlanCore, ns.CraftData
    local saved = { rank = ns.ProfessionRank, have = d.Have, known = d.Known, price = ns.GetPrice, cost = d.ReagentCost, filter = ns.CraftFilter, compute = core.Compute,
        targets = ns.db.planTargets, waypoint = ns.SetWaypoint, trainers = GathercraftTrainers, sources = GathercraftRecipeSources, maps = GathercraftAreaMaps,
        map = player.map, x = player.x, y = player.y, faction = UnitFactionGroup }
    local function Rows()
        local list = {}
        for _, o in ipairs(allFrames) do
            if o.left and o.mid and o.right and o:IsShown() and o.__pts and o.__pts.TOPLEFT then list[#list + 1] = o end
        end
        table.sort(list, function(a, b) return a.__pts.TOPLEFT[2] > b.__pts.TOPLEFT[2] end)
        return list
    end
    local function Tip(row)
        local lines = {}
        if row and row.tip then row.tip({ AddLine = function(_, t) lines[#lines + 1] = t end }) end
        return table.concat(lines, "\n")
    end
    local ok, err = pcall(function()
        local ranks, price, computed = { Alchemy = { 60, 75 } }, 10, 0
        ns.ProfessionRank = function(p) local r = ranks[p] if r then return r[1], r[2] end end
        d.Have = function() return 0 end
        d.Known = function() return {} end
        ns.GetPrice = function() return price, "AH scan" end
        d.ReagentCost = function() return price, "AH scan" end
        ns.CraftFilter = function() return "Alchemy" end
        ns.db.planTargets = nil
        local way
        ns.SetWaypoint = function(mapID, x, y) way = { mapID, x, y } return true end
        -- a plan with a training step at 75 (the trainers), or one with a recipe to buy (the vendors)
        local vendorPlan = false
        core.Compute = function(input)
            computed = computed + 1
            local _ = input.prices[9801] -- (what it read: a price - a changed one makes a new plan)
            if vendorPlan then
                return saved.compute({ prof = input.prof, skill = 1, target = 6, professions = {}, caps = {}, nodes = {}, stock = {}, recipeItemPrices = { [99901] = 500 },
                    recipes = { [input.prof] = { { prof = input.prof, key = "V", name = "Recipe V", product = 9840, made = 1, req = 1, yellow = 6, grey = 6,
                        reagents = { { id = 9841, n = 1 } }, learn = "vendor", recipeItem = 99901 } } },
                    prices = { [9841] = { status = "known", copper = 10 } } })
            end
            return saved.compute({ prof = input.prof, skill = 60, target = 80, maxRank = 75, caps = { 75 }, professions = {}, nodes = {}, stock = {},
                recipeItemPrices = {}, recipes = { [input.prof] = { { prof = input.prof, key = "A", name = "Recipe A", product = 9800, made = 1, req = 1, yellow = 500, grey = 500,
                    reagents = { { id = 9801, n = 1 } }, learn = "known" } } }, prices = { [9801] = { status = "known", copper = 10 } } })
        end
        -- areas: 9001 Zone1413, 9002 Zone1440, 9003 Zone1412 (Kalimdor), 9004 Zone1420 (another continent)
        GathercraftAreaMaps = setmetatable({ [9001] = 1413, [9002] = 1440, [9003] = 1412, [9004] = 1420 }, { __index = saved.maps })
        UnitFactionGroup = function() return "Horde", "Horde" end
        local function Sub()
            local train
            for i, row in ipairs(Rows()) do
                if (row.left:GetText() or ""):find((L["Train the next rank at your trainer (needed at %d)."]):format(75), 1, true) then
                    train = row
                    return train, Rows()[i + 1]
                end
            end
            error("test setup: no training step")
        end
        local function Trainer(name, mapID)
            return (L["Nearest trainer: %s (%s)"]):format(name, ns.GetZoneName(mapID))
        end

        -- (1) a zone change, the window open: the trainer of where you are now - text, tooltip, click
        GathercraftTrainers = { Alchemy = {
            [902] = "Near Horde|2|H|9001:5000:5000",
            [904] = "Over The Sea|2|H|9004:5000:5000",
        } }
        player.map, player.x, player.y = 1412, 0.5, 0.5
        fire("ZONE_CHANGED_NEW_AREA")
        ns.ShowSkillPlan("Alchemy") advance(1)
        local train, sub = Sub()
        assert(sub and sub.left:GetText():find(Trainer("Near Horde", 1413), 1, true), "test setup: " .. tostring(sub and sub.left:GetText()))
        sub.click()
        assert(way and way[1] == 1413, "test setup: the trainer's waypoint")
        -- (a price changed, without an event of the window: the plan would be worked out
        -- anew if it were asked again - moving must not ask it)
        price = 11
        local before = computed
        player.map, player.x, player.y = 1420, 0.4, 0.5
        fire("ZONE_CHANGED_NEW_AREA")
        advance(2)
        train, sub = Sub()
        assert(sub.left:GetText():find(Trainer("Over The Sea", 1420), 1, true), "a zone change, the window open: still " .. sub.left:GetText())
        way = nil
        sub.click()
        assert(way and way[1] == 1420 and math.abs(way[2] - 0.5) < 1e-9, "a zone change: the click sets the waypoint of before (" .. tostring(way and way[1]) .. ")")
        way = nil
        train.click()
        assert(way and way[1] == 1420, "a zone change: the training row's click sets the waypoint of before")
        assert(Tip(sub):find(Trainer("Over The Sea", 1420), 1, true) and Tip(train) == Tip(sub), "a zone change: the tooltip names the trainer of before")
        assert(computed == before, "the plan was worked out again because you moved (" .. (computed - before) .. ")")
        -- pointing at it still looks nothing up
        local searches = ns.PlacesSearches
        for _ = 1, 5 do Tip(sub) Tip(train) end
        assert(ns.PlacesSearches == searches, "the trainer is looked up while you point at the row")
        -- staying there: nothing looked up again
        advance(3)
        assert(ns.PlacesSearches == searches, "standing still: the places are looked up again (" .. (ns.PlacesSearches - searches) .. ")")
        -- the plan itself is still brought up to date by its own events
        fire("BAG_UPDATE_DELAYED")
        advance(1)
        assert(computed == before + 1, "test setup: the changed price did not make a new plan with the next event (" .. (computed - before) .. ")")

        -- (2) a longer way on the same map, no zone event: the trainer nearer now
        GathercraftTrainers = { Alchemy = {
            [910] = "West Horde|2|H|9003:1000:5000",
            [911] = "East Horde|2|H|9003:9000:5000",
        } }
        player.map, player.x, player.y = 1412, 0.3, 0.5
        fire("ZONE_CHANGED_NEW_AREA")
        ns.ShowSkillPlan("Alchemy") advance(1)
        train, sub = Sub()
        assert(sub.left:GetText():find(Trainer("West Horde", 1412), 1, true), "test setup: " .. sub.left:GetText())
        before, searches = computed, ns.PlacesSearches
        player.x = 0.32 -- (100 yards: not a move that counts)
        advance(2)
        assert(ns.PlacesSearches == searches, "100 yards: the places are looked up again")
        -- (choosing a target meanwhile: its menu stays open)
        local menu = assert(_G.GathercraftSkillPlanTargetMenu, "test setup: no target menu")
        menu:Show()
        player.x = 0.7 -- (2000 yards)
        advance(2)
        train, sub = Sub()
        assert(sub.left:GetText():find(Trainer("East Horde", 1412), 1, true), "a longer way, the window open: still " .. sub.left:GetText())
        assert(menu:IsShown(), "the rows of places drawn again: the target menu was closed")
        menu:Hide()
        way = nil
        sub.click()
        assert(way and way[1] == 1412 and math.abs(way[2] - 0.9) < 1e-9, "a longer way: the click sets the waypoint of before")
        assert(computed == before, "the plan was worked out again because you walked (" .. (computed - before) .. ")")

        -- (3) the vendor of a recipe, a zone change: the vendor of where you are now - text, tooltip, click
        vendorPlan = true
        ranks.Alchemy = { 1, 75 }
        GathercraftRecipeSources = setmetatable({ items = { [99901] = "V:802,806" }, npcs = {
            [802] = "The Nearest|9001|AH|5000|5000",
            [806] = "Sea Vendor|9004|H|5000|5000",
        } }, { __index = saved.sources })
        player.map, player.x, player.y = 1412, 0.5, 0.5
        fire("ZONE_CHANGED_NEW_AREA")
        ns.ShowSkillPlan("Alchemy") advance(1)
        local function Learn()
            for _, o in ipairs(Rows()) do
                if o.left:GetText() == "Recipe V" then return o end
            end
        end
        local row = Learn()
        assert(row and row.right:GetText():find("The Nearest", 1, true), "test setup: " .. tostring(row and row.right:GetText()))
        way = nil
        row.click()
        assert(way and way[1] == 1413, "test setup: the vendor's waypoint")
        before = computed
        player.map, player.x, player.y = 1420, 0.4, 0.5
        fire("ZONE_CHANGED_NEW_AREA")
        advance(2)
        row = Learn()
        assert(row and row.right:GetText():find("Sea Vendor", 1, true), "a zone change: the vendor of before: " .. tostring(row and row.right:GetText()))
        way = nil
        row.click()
        assert(way and way[1] == 1420, "a zone change: the vendor's click sets the waypoint of before")
        assert(Tip(row):find((L["Sold by %s (%s)."]):format("Sea Vendor", ns.GetZoneName(1420)), 1, true), "a zone change: the vendor's tooltip: " .. Tip(row))
        assert(computed == before, "the plan was worked out again because you moved (vendor, " .. (computed - before) .. ")")
    end)
    ns.ProfessionRank, d.Have, d.Known, ns.GetPrice, ns.CraftFilter, core.Compute = saved.rank, saved.have, saved.known, saved.price, saved.filter, saved.compute
    d.ReagentCost = saved.cost
    ns.db.planTargets, ns.SetWaypoint, GathercraftTrainers, GathercraftRecipeSources, GathercraftAreaMaps = saved.targets, saved.waypoint, saved.trainers, saved.sources, saved.maps
    player.map, player.x, player.y, UnitFactionGroup = saved.map, saved.x, saved.y, saved.faction
    fire("ZONE_CHANGED_NEW_AREA")
    if _G.GathercraftSkillPlan then _G.GathercraftSkillPlan:Hide() end
    if not ok then error(err, 0) end
end)
step("Places: your faction cannot be read - only a trainer or vendor friendly to both factions, else none; never one of a single faction (0.2 places, R3 B-N1)", function()
    -- Codex round 3 of the places, B-N1: a faction that cannot be read (none,
    -- or a hidden value) let every trainer and vendor through - also the
    -- nearer one of the other faction. Now only one friendly to both, else
    -- no place at all (the plan says what it said before, no waypoint).
    local saved = { faction = UnitFactionGroup, secret = ns.AnySecret, trainers = GathercraftTrainers, sources = GathercraftRecipeSources, maps = GathercraftAreaMaps,
        map = player.map, x = player.x, y = player.y }
    local ok, err = pcall(function()
        GathercraftAreaMaps = setmetatable({ [9001] = 1412 }, { __index = saved.maps })
        player.map, player.x, player.y = 1412, 0.5, 0.5
        local both = { Alchemy = {
            [1] = "Alliance Only|3|A|9001:5000:5000",
            [2] = "Horde Only|3|H|9001:5100:5000",
            [3] = "Both Factions|3|AH|9001:7000:5000",
        } }
        local single = { Alchemy = { [1] = "Alliance Only|3|A|9001:5000:5000", [2] = "Horde Only|3|H|9001:5100:5000" } }
        local function Vendors(npcs)
            local ids = {}
            for id in pairs(npcs) do ids[#ids + 1] = id end
            table.sort(ids)
            GathercraftRecipeSources = setmetatable({ items = { [99901] = "V:" .. table.concat(ids, ",") }, npcs = npcs }, { __index = saved.sources })
        end
        local function Look()
            fire("ZONE_CHANGED_NEW_AREA")
            local t, v = ns.PlacesTrainer("Alchemy", 3), ns.PlacesVendor(99901)
            return t and t.name, v and v.name
        end
        -- the faction is read: yours, the nearest (as before)
        UnitFactionGroup = function() return "Horde", "Horde" end
        GathercraftTrainers = both
        Vendors({ [801] = "Alliance Only|9001|A|5000|5000", [802] = "Horde Only|9001|H|5100|5000", [803] = "Both Factions|9001|AH|7000|5000" })
        local t, v = Look()
        assert(t == "Horde Only" and v == "Horde Only", "test setup: the Horde's own: " .. tostring(t) .. ", " .. tostring(v))
        for _, case in ipairs({
            { "none", function() return nil end, saved.secret },
            { "a hidden value", function() return "Horde", "Horde" end, function(where, ...) if where == "faction" then return true end return saved.secret(where, ...) end },
        }) do
            UnitFactionGroup, ns.AnySecret = case[2], case[3]
            -- one friendly to both: that one, though the others are nearer
            GathercraftTrainers = both
            Vendors({ [801] = "Alliance Only|9001|A|5000|5000", [802] = "Horde Only|9001|H|5100|5000", [803] = "Both Factions|9001|AH|7000|5000" })
            t, v = Look()
            assert(t == "Both Factions", "faction " .. case[1] .. ": the trainer " .. tostring(t))
            assert(v == "Both Factions", "faction " .. case[1] .. ": the vendor " .. tostring(v))
            -- none friendly to both: no place - not one of a single faction, not by name either
            GathercraftTrainers = single
            Vendors({ [801] = "Alliance Only|9001|A|5000|5000", [804] = "No Faction Known|9001||5000|5000", [805] = "Horde No Map|77777|H|5000|5000" })
            t, v = Look()
            assert(t == nil, "faction " .. case[1] .. ": a trainer of a single faction: " .. tostring(t))
            assert(v == nil, "faction " .. case[1] .. ": a vendor that may be hostile: " .. tostring(v))
            ns.AnySecret = saved.secret
        end
    end)
    UnitFactionGroup, ns.AnySecret, GathercraftTrainers, GathercraftRecipeSources, GathercraftAreaMaps = saved.faction, saved.secret, saved.trainers, saved.sources, saved.maps
    player.map, player.x, player.y = saved.map, saved.x, saved.y
    fire("ZONE_CHANGED_NEW_AREA")
    if not ok then error(err, 0) end
end)
step("Skill plan 2.0: texts in every language, the release 0.2.0 - its what's new stays, the TOC and the changelog are 0.2.2's (v0.2 A7)", function()
    -- 0.2 was built block by block under internal marks (b1 ... b3) and was
    -- published as one release: the TOC said 0.2.0, "What's new" has its
    -- entry and the changelog had its section with the date.
    local version = toc:match("## Version: ([%w%.%-]+)")
    -- 0.2.1: the TOC says 0.2.1; what follows checks the What's new of 0.2.0,
    -- which stays for players who skip a version. The changelog holds the
    -- current version only: the 0.2.0 section is in the history (tag v0.2.0).
    -- the changelog is 0.2.2's (0.2.1's is in the history, tag v0.2.1); the TOC says the build's version
    assert(version == "0.2.3-a3", "TOC version: " .. tostring(version))
    version = "0.2.0"
    -- the two files of building block 2 load last: they read the data files only after login
    assert(toc:gsub("\r", ""):match("\nStarter%.lua\nSpawnCounts%.lua\nItemTooltip%.lua\n?$"), "the TOC does not end with Starter.lua, SpawnCounts.lua, ItemTooltip.lua")
    assert(toc:match("## Interface: (%d+)") == "16001", "TOC interface changed")
    local function Read(name)
        local f = assert(io.open(ROOT .. "/" .. name))
        local text = f:read("*a") f:close()
        return text
    end
    local welcome, changelog = Read("Welcome.lua"), Read("CHANGELOG.md")
    local entry = welcome:match('%["0%.2%.0"%] = "([^"]+)"')
    assert(entry, "What's new has no entry for 0.2.0")
    assert(not welcome:find('%["0%.2%.0%-'), "What's new has an entry for an internal build")
    -- "Coming next" names what comes after 0.2.0 (Sven, 20.11.2026), not what 0.2.0 ships
    assert(welcome:find('local COMING_NEXT = "Smoother Loop routes · More spawn points for the new Forever zones · Disenchant values"', 1, true),
        "Coming next is not the three points after 0.2.0")
    assert(not welcome:find("Shopping list on the map", 1, true), "Coming next still names what 0.2.0 ships")
    local heading = changelog:match("^(## v[^\r\n]*)")
    assert(heading == "## v0.2.2 – 2026-11-23", "CHANGELOG heading: " .. tostring(heading))
    -- the release shows "what's new" at the first login after 0.1.23, with the text of 0.2.0
    local keep = { meta = C_AddOns.GetAddOnMetadata, last = ns.db.lastVersion, fresh = ns.freshInstall }
    C_AddOns.GetAddOnMetadata = function() return version end
    ns.freshInstall = false
    ns.db.lastVersion = "0.1.23"
    local win = _G.GathercraftWhatsNew
    if win then win:Hide() end
    local ok, err = pcall(ns.WelcomeOnLogin)
    win = _G.GathercraftWhatsNew
    local shown = win and win:IsShown()
    local body = shown and win.body:GetText()
    local remembered = ns.db.lastVersion
    if win then win:Hide() end
    C_AddOns.GetAddOnMetadata, ns.db.lastVersion, ns.freshInstall = keep.meta, keep.last, keep.fresh
    assert(ok, "the login of the release: " .. tostring(err))
    assert(shown and body == ns.L[entry], "the release shows no what's new window with the text of 0.2.0")
    assert(remembered == version, "the new version is not remembered: " .. tostring(remembered))

    -- every text of the plan window: English key, nine translations, the same placeholders
    local planner = Read("Planner.lua")
    local keys, count = {}, 0
    for key in planner:gmatch('L%["(.-)"%]') do keys[key] = true end
    for key in planner:gmatch('ns%.LText%([%w%.]+, "(.-)"') do keys[key] = true end
    local function Codes(s)
        local list = {}
        for code in s:gmatch("%%[%d%$]*[sd]") do list[#list + 1] = code end
        return table.concat(list, " ")
    end
    for key in pairs(keys) do
        count = count + 1
        for _, code in ipairs({ "deDE", "esES", "frFR", "itIT", "koKR", "ptBR", "ruRU", "zhCN", "zhTW" }) do
            local tr = ns.Locales[code] and ns.Locales[code][key]
            assert(type(tr) == "string" and tr ~= "", ("no %s translation of %q"):format(code, key))
            assert(Codes(tr) == Codes(key), ("%s: other placeholders in %q: %s"):format(code, key, tr))
        end
    end
    assert(count >= 70, "test setup: the texts of Planner.lua: " .. count)
    -- no promise the plan cannot keep, in any language of the new texts
    for key in pairs(keys) do
        local low = key:lower()
        assert(not low:find("cheapest", 1, true) and not low:find("fastest", 1, true) and not low:find("guaranteed", 1, true) and not low:find("error-free", 1, true),
            "a text promises too much: " .. key)
    end
    -- the short labels fit their fixed places in this language (an estimate:
    -- 6 px a letter, 11 px a CJK sign - no real font metrics here)
    local function Px(t)
        local px = 0
        for ch in (t or ""):gmatch("[%z\1-\127\194-\244][\128-\191]*") do px = px + (#ch >= 3 and 11 or 6) end
        return px
    end
    local L = ns.L
    -- (the head "have / need" has 140 px - it grows to the left of its column, next to "Materials" in 130)
    assert(planner:find('head.mid:SetPoint("RIGHT", head, "LEFT", 280, 0)', 1, true) and planner:find("head.mid:SetWidth(140)", 1, true)
        and planner:find("head.left:SetWidth(130)", 1, true), "the column head has only the width of its numbers")
    for _, fit in ipairs({ { "Target", 90 }, { "have / need", 140 }, { "Materials", 130 }, { "Custom value", 134 }, { "Default", 138 }, { "missing", 150 }, { "enough", 150 },
        { "(from the plan's steps)", 150 }, { "chance unknown", 150 }, { "Not learned yet", 200 } }) do
        assert(Px(L[fit[1]]) <= fit[2], ("%s: %q needs %d px of %d"):format(LOCALE, L[fit[1]], Px(L[fit[1]]), fit[2]))
    end
    assert(Px((L["Your skill: %d / %d"]):format(300, 300)) <= 200, LOCALE .. ": the skill line is too long")
    assert(Px((L["%s trainer"]):format(ns.CraftData.ProfLabel("Leatherworking")) .. "  99g 99s") <= 150 + 60, LOCALE .. ": a trainer line is far too long")
    -- long recipe names and big numbers: the step and material rows do not wrap (one line each, cut by the game)
    assert(planner:find("row.left:SetWordWrap(wide)", 1, true) and planner:find("row.right:SetWordWrap(false)", 1, true) and planner:find("row.mid:SetWordWrap(false)", 1, true),
        "a row with two columns can wrap into the next one")
    -- no change to the route, the recorder or the sync for this block: Planner.lua calls them as before
    assert(planner:find('ns.StartRun("item:" .. m.id)', 1, true), "the Farm button no longer starts the item's run")
end)
step("Skill plan 2.0: buying against making by the gold it really takes on top (v0.2 r1 F1)", function()
    -- Codex round 1, B1 (concept 4.2 / 4.5): an intermediate is bought or made
    -- by what THIS need costs on top of what you have - raw stock deeper down
    -- is free, a batch costs a whole batch, learning the recipe costs once,
    -- and a cost nobody knows never wins by its known part. Plain tables; a
    -- recipe gives one point per craft from `req` up to `upto`.
    local core = ns.PlanCore
    local function R(key, product, req, upto, mats, extra)
        local r = { prof = "Testing", key = key, name = key, product = product, made = 1, req = req, yellow = upto, grey = upto, reagents = {}, learn = "known" }
        for _, x in ipairs(mats) do r.reagents[#r.reagents + 1] = { id = x[1], n = x[2] } end
        for k, v in pairs(extra or {}) do r[k] = v end
        return r
    end
    local function Plan(recipes, stock, prices, from, to, more)
        local p = {}
        for id, copper in pairs(prices) do p[id] = type(copper) == "table" and copper or { status = "known", copper = copper } end
        local input = { prof = "Testing", skill = from or 1, target = to or 2, recipes = { Testing = recipes }, stock = stock, prices = p,
            professions = {}, recipeItemPrices = {}, caps = {} }
        for k, v in pairs(more or {}) do input[k] = v end
        local plan = core.Compute(input)
        local ok, why = core.CheckBalance(plan)
        assert(ok, "the books do not balance: " .. tostring(why))
        local m = {}
        for _, row in ipairs(plan.materials) do m[row.id] = row end
        return plan, m
    end
    local function Extra(plan, key)
        for _, e in ipairs(plan.extras) do if e.recipe.key == key then return e.times end end
        return 0
    end

    -- Codex RAW_STOCK: one X needed, the raw material for it is in the bags.
    -- X costs 20c, the raw material 50c at the AH: made from stock, 0c on top
    local plan, m = Plan({ R("A", 10, 1, 2, { { 11, 1 } }), R("Make X", 11, 1, 1, { { 12, 1 } }) }, { [12] = 1 }, { [11] = 20, [12] = 50 })
    assert(plan.total == 0 and m[11].missing == 0 and m[11].madeFrom and Extra(plan, "Make X") == 1, ("raw stock is there, X is bought all the same (%s copper)"):format(tostring(plan.total)))
    assert(m[12] and m[12].need == 1 and m[12].have == 1 and m[12].missing == 0 and m[12].covered, "the raw stock is not what X is made from")
    assert(plan.steps[1].comparable and not plan.notComparable and plan.status == "ok", "a wholly known choice called not comparable")

    -- Codex INTERMEDIATE_FEE: X costs 20c; making it takes 1c of material and
    -- 10000c to learn the recipe first: bought
    local function Fee(fee)
        return Plan({ R("A", 10, 1, 2, { { 11, 1 } }), R("Make X", 11, 1, 1, { { 12, 1 } }, { learn = "trainer", fee = fee }) }, {}, { [11] = 20, [12] = 1 })
    end
    plan, m = Fee(10000)
    assert(plan.total == 20 and m[11].missing == 1 and not m[11].madeFrom and not m[12], ("a 10000c fee to save 19c: %s copper"):format(tostring(plan.total)))
    assert(plan.learn.fees == 0 and plan.learn.trainer == 0 and #plan.learn.list == 0, "the fee of a recipe the plan does not use is counted")
    assert(plan.steps[1].comparable and not plan.notComparable, "a wholly known choice called not comparable")

    -- Codex UNKNOWN_INTERMEDIATE_FEE: the same with a fee nobody knows. X is
    -- bought at its known price; the open fee reaches the comparison: the
    -- step and the plan are not called fully comparable
    plan, m = Fee(nil)
    assert(plan.total == 20 and m[11].missing == 1 and not m[11].madeFrom, ("an unknown fee wins by its known part: %s copper"):format(tostring(plan.total)))
    assert(plan.learn.feesUnknown == 0 and plan.learn.trainer == 0, "the unknown fee of a recipe the plan does not use is listed")
    assert(plan.steps[1].comparable == false and plan.notComparable == true, "an open fee in the comparison: the choice is called fully comparable")
    assert(plan.openLearn == true and not plan.openPrices, "what is open is not named (a learning cost, no price)")
    -- ... but an open fee that cannot change the choice does not make it open:
    -- the material alone costs more than buying X
    plan, m = Plan({ R("A", 10, 1, 2, { { 11, 1 } }), R("Make X", 11, 1, 1, { { 12, 1 } }, { learn = "trainer" }) }, {}, { [11] = 20, [12] = 50 })
    assert(plan.total == 20 and plan.steps[1].comparable and not plan.notComparable and not plan.openLearn, "an open fee that cannot matter makes the choice open")

    -- Codex BATCH_COST: one X needed; a batch of three costs 30c, one bought
    -- X 20c: bought (what a batch makes too much is no saving)
    plan, m = Plan({ R("A", 10, 1, 2, { { 11, 1 } }), R("Make X", 11, 1, 1, { { 12, 1 } }, { made = 3 }) }, {}, { [11] = 20, [12] = 30 })
    assert(plan.total == 20 and m[11].missing == 1 and not m[11].madeFrom and not m[12], ("a batch of three for one X: %s copper"):format(tostring(plan.total)))
    -- three needed: the batch (30c) against 60c -> made
    plan, m = Plan({ R("A", 10, 1, 4, { { 11, 1 } }), R("Make X", 11, 1, 1, { { 12, 1 } }, { made = 3 }) }, {}, { [11] = 20, [12] = 30 }, 1, 4)
    assert(plan.total == 30 and m[11].madeFrom and Extra(plan, "Make X") == 1 and m[11].missing == 0, ("a batch that is worth it is not made: %s copper"):format(tostring(plan.total)))
    -- four needed: one batch for three (30c), the fourth bought (20c) - a
    -- second batch for one X would cost 30c
    plan, m = Plan({ R("A", 10, 1, 5, { { 11, 1 } }), R("Make X", 11, 1, 1, { { 12, 1 } }, { made = 3 }) }, {}, { [11] = 20, [12] = 30 }, 1, 5)
    assert(plan.total == 50 and Extra(plan, "Make X") == 1 and m[11].missing == 1 and m[11].madeFrom and plan.ledger[11].rest == 0,
        ("three from a batch and one bought: %s copper"):format(tostring(plan.total)))

    -- the fee pays off over the need of the step: 30 X at 20c against 30c of
    -- material and a fee of 100c
    plan, m = Plan({ R("A", 10, 1, 31, { { 11, 1 } }), R("Make X", 11, 1, 1, { { 12, 1 } }, { learn = "trainer", fee = 100 }) }, {}, { [11] = 20, [12] = 1 }, 1, 31)
    assert(plan.total == 30 and plan.learn.fees == 100 and plan.learn.trainer == 1 and Extra(plan, "Make X") == 30, "a fee that pays off is not paid")
    -- raw stock for a part of the need: that part is made (0c), the rest
    -- bought (20c each) - not all bought (60c), not all made (100c)
    plan, m = Plan({ R("A", 10, 1, 4, { { 11, 1 } }), R("Make X", 11, 1, 1, { { 12, 1 } }) }, { [12] = 1 }, { [11] = 20, [12] = 50 }, 1, 4)
    assert(plan.total == 40 and Extra(plan, "Make X") == 1 and m[11].missing == 2 and m[12].missing == 0, ("raw stock for one of three: %s copper"):format(tostring(plan.total)))
    -- the same raw stock is not free twice: two intermediates share it
    plan, m = Plan({ R("A", 10, 1, 2, { { 11, 1 }, { 13, 1 } }), R("Make X", 11, 1, 1, { { 12, 1 } }), R("Make Y", 13, 1, 1, { { 12, 1 } }) },
        { [12] = 1 }, { [11] = 20, [13] = 20, [12] = 50 })
    assert(plan.total == 20 and Extra(plan, "Make X") + Extra(plan, "Make Y") == 1 and m[12].need == 1, ("one raw piece used for two things: %s copper"):format(tostring(plan.total)))
    -- raw stock two levels down counts as well: X from W, W from raw
    plan, m = Plan({ R("A", 10, 1, 2, { { 11, 1 } }), R("Make X", 11, 1, 1, { { 14, 1 } }), R("Make W", 14, 1, 1, { { 12, 2 } }) },
        { [12] = 2 }, { [11] = 20, [14] = 500, [12] = 50 })
    assert(plan.total == 0 and Extra(plan, "Make X") == 1 and Extra(plan, "Make W") == 1 and m[12].covered, "raw stock two levels down is not used")
    -- no price for X at all: made, whatever it costs (as before)
    plan, m = Plan({ R("A", 10, 1, 2, { { 11, 1 } }), R("Make X", 11, 1, 1, { { 12, 1 } }) }, {}, { [12] = 50 })
    assert(plan.total == 50 and m[11].madeFrom and plan.steps[1].comparable, "no price to buy it: not made")
    -- a way to make it with a material nobody has a price for, cheaper by its
    -- known part: X is bought at its known price, the choice is open (a price)
    plan, m = Plan({ R("A", 10, 1, 2, { { 11, 1 } }), R("Make X", 11, 1, 1, { { 12, 1 } }) }, {}, { [11] = 20 })
    assert(plan.total == 20 and not m[11].madeFrom and plan.steps[1].comparable == false and plan.openPrices and not plan.openLearn, "a material without a price in the other way: not open")

    -- a recipe of another profession with the same name does not make this
    -- one learned: Y is made with the known "Make it" of your second
    -- profession, X would need the planned profession's "Make it" (10000c to
    -- learn) - X is bought, no fee is counted
    plan = core.Compute({ prof = "Testing", skill = 1, target = 2, stock = {}, professions = { Weaving = { rank = 50 } }, recipeItemPrices = {}, caps = {},
        recipes = { Testing = { R("A", 10, 1, 2, { { 21, 1 }, { 22, 1 } }), R("Make it", 22, 1, 1, { { 12, 1 } }, { learn = "trainer", fee = 10000 }) },
            Weaving = { R("Make it", 21, 1, 1, { { 12, 1 } }, { prof = "Weaving" }) } },
        prices = { [21] = { status = "known", copper = 20 }, [22] = { status = "known", copper = 20 }, [12] = { status = "known", copper = 1 } } })
    assert(plan.total == 21 and plan.learn.fees == 0 and plan.ledger[22].bought == 1 and plan.ledger[21].madeExtra == 1,
        ("a recipe of the same name in another profession: %s copper, fees %s"):format(tostring(plan.total), tostring(plan.learn.fees)))

    -- a recipe of another profession is used only when you know it: one your
    -- second profession could still learn - even for nothing - is not yours
    local function Second(learn, fee)
        local p = core.Compute({ prof = "Testing", skill = 1, target = 2, stock = {}, professions = { Weaving = { rank = 50 } }, recipeItemPrices = {}, caps = {},
            recipes = { Testing = { R("A", 10, 1, 2, { { 21, 1 } }) }, Weaving = { R("Weave it", 21, 1, 1, { { 12, 1 } }, { prof = "Weaving", learn = learn, fee = fee }) } },
            prices = { [21] = { status = "known", copper = 20 }, [12] = { status = "known", copper = 1 } } })
        return p
    end
    assert(Second("known").total == 1 and Second("known").ledger[21].madeExtra == 1, "test setup: the known recipe of the second profession is used")
    for _, fee in ipairs({ 0, 5, false }) do
        plan = Second("trainer", fee or nil)
        assert(plan.total == 20 and plan.ledger[21].bought == 1 and plan.ledger[21].madeExtra == 0 and not plan.notComparable and plan.learn.fees == 0,
            "a recipe of another profession you have not learned is used or counted (fee " .. tostring(fee) .. ")")
    end

    -- the same with a material nobody has a price for: X (20c) could be made
    -- from Z (50c) and a piece without a price. The known part alone is more
    -- than buying X - the piece without a price cannot change the choice: not open
    plan, m = Plan({ R("A", 10, 1, 2, { { 11, 1 } }), R("Make X", 11, 1, 1, { { 12, 1 }, { 23, 1 } }) }, {}, { [11] = 20, [12] = 50 })
    assert(plan.total == 20 and not m[11].madeFrom and plan.steps[1].comparable and not plan.notComparable and not plan.openPrices,
        "a piece without a price that cannot matter makes the choice open")

    -- the choice between recipes sees it too: A needs X (20c at the AH, 0c
    -- from raw stock), B needs a 5c material. With the raw stock A is free
    local function Two(stock)
        return Plan({ R("A", 10, 1, 2, { { 11, 1 } }), R("B", 15, 1, 2, { { 16, 1 } }), R("Make X", 11, 1, 1, { { 12, 1 } }) }, stock, { [11] = 20, [12] = 50, [16] = 5 })
    end
    plan = Two({ [12] = 1 })
    assert(plan.steps[1].recipe.key == "A" and plan.total == 0, "the recipe choice does not see the raw stock of an intermediate")
    plan = Two({})
    assert(plan.steps[1].recipe.key == "B" and plan.total == 5, "without the raw stock: the less costly recipe")
    -- ... and the fee of an intermediate recipe: A's X is made for 1c after a
    -- 10000c fee, or bought for 20c; B costs 15c a point. B it is
    plan = Plan({ R("A", 10, 1, 2, { { 11, 1 } }), R("B", 15, 1, 2, { { 16, 1 } }), R("Make X", 11, 1, 1, { { 12, 1 } }, { learn = "trainer", fee = 10000 }) },
        {}, { [11] = 20, [12] = 1, [16] = 15 })
    assert(plan.steps[1].recipe.key == "B" and plan.total == 15 and plan.learn.fees == 0, "the recipe choice forgets the fee of an intermediate recipe")

    -- a fee that is worth paying over the three points A can give (30c: 10c
    -- a point) is part of what a point of A costs: 1c + 10c against B's 5c
    plan = Plan({ R("A", 10, 1, 4, { { 11, 1 } }), R("B", 15, 1, 4, { { 16, 1 } }), R("Make X", 11, 1, 1, { { 12, 1 } }, { learn = "trainer", fee = 30 }) },
        {}, { [11] = 20, [12] = 1, [16] = 5 }, 1, 4)
    assert(#plan.steps == 1 and plan.steps[1].recipe.key == "B" and plan.total == 15, "a point of A is counted without the fee its intermediate takes")
    -- a fee that is not worth it over those points (90c: 30c a point, X costs
    -- 20c) is not paid: X is bought, a point of A costs 20c - less than B's 25c
    plan = Plan({ R("A", 10, 1, 4, { { 11, 1 } }), R("B", 15, 1, 4, { { 16, 1 } }), R("Make X", 11, 1, 1, { { 12, 1 } }, { learn = "trainer", fee = 90 }) },
        {}, { [11] = 20, [12] = 1, [16] = 25 }, 1, 4)
    assert(#plan.steps == 1 and plan.steps[1].recipe.key == "A" and plan.total == 60 and plan.learn.fees == 0, "the choice pays a fee that is not worth it, or counts it all the same")

    -- a chain that leads back to itself is reported when the PLAN meets it -
    -- not because a recipe that is never taken has one: B (not taken, its
    -- material P is made from Q, and Q from P) leaves the plan of A complete
    plan = Plan({ R("A", 10, 1, 3, { { 11, 1 } }), R("B", 15, 1, 3, { { 41, 1 } }), R("P from Q", 41, 1, 1, { { 42, 1 } }), R("Q from P", 42, 1, 1, { { 41, 1 } }) },
        {}, { [11] = 5 }, 1, 3)
    assert(#plan.steps == 1 and plan.steps[1].recipe.key == "A" and plan.total == 10, "test setup: A is the plan")
    assert(plan.status == "ok" and plan.complete and #plan.diagnostics == 0, "a chain back to itself in a recipe the plan does not use makes the plan incomplete")
    -- ... and it is reported when the plan needs the thing (as before)
    plan = Plan({ R("B", 15, 1, 3, { { 41, 1 } }), R("P from Q", 41, 1, 1, { { 42, 1 } }), R("Q from P", 42, 1, 1, { { 41, 1 } }) }, {}, {}, 1, 3)
    assert(plan.status == "incomplete" and plan.diagnostics[1] and plan.diagnostics[1].code == "cycle", "a chain back to itself in the plan is not reported")

    -- The choice remembers what an item costs by the piece - and drops it
    -- when the books change. Y is made from one X (50c) or bought (100c): at
    -- 1 it costs 50c a piece (D needs it there, and far more). A (1-3, the
    -- only sensible recipe up to 3) makes two X as it goes. From 3 on C needs
    -- one Y, B a 5c material: at 3 and 4 C is free - its Y from the X the
    -- steps made - and only then B is the less costly one
    plan = Plan({ R("A", 31, 1, 3, { { 32, 1 } }), R("B", 33, 3, 9, { { 34, 1 } }), R("C", 35, 3, 9, { { 36, 1 } }), R("D", 37, 1, 9, { { 36, 1 }, { 38, 1 } }),
        R("Make Y", 36, 1, 1, { { 31, 1 } }) }, {}, { [31] = 50, [32] = 60, [34] = 5, [36] = 100, [38] = 1000 }, 1, 6)
    assert(#plan.steps == 3 and plan.steps[1].recipe.key == "A" and plan.steps[2].recipe.key == "C" and plan.steps[2].from == 3 and plan.steps[2].to == 5
        and plan.steps[3].recipe.key == "B" and plan.total == 2 * 60 + 5, "what the steps made is not seen by the choice of the next recipe")
    -- ... and when a recipe further down can be used from a higher skill on:
    -- A needs X (1000c; from 5 on made for 1c), B a 500c material
    plan = Plan({ R("A", 10, 1, 9, { { 11, 1 } }), R("B", 15, 1, 9, { { 16, 1 } }), R("Make X", 11, 5, 5, { { 12, 1 } }) }, {}, { [11] = 1000, [12] = 1, [16] = 500 }, 1, 9)
    assert(#plan.steps == 2 and plan.steps[1].recipe.key == "B" and plan.steps[1].to == 5 and plan.steps[2].recipe.key == "A" and plan.total == 4 * 500 + 4,
        "the choice does not see that a recipe further down unlocks")
    -- the next best recipe is still named with what it would cost (it is
    -- judged in full although only the best is taken)
    plan = Plan({ R("A", 10, 1, 2, { { 11, 1 } }), R("B", 15, 1, 2, { { 16, 1 } }), R("C", 17, 1, 2, { { 18, 1 } }), R("D", 19, 1, 2, { { 20, 1 } }) },
        {}, { [11] = 40, [16] = 30, [18] = 10, [20] = 20 })
    local why = plan.steps[1].why
    assert(plan.steps[1].recipe.key == "C" and why.other and why.other.key == "D" and math.abs(why.other.score - 21 * 1.08) < 1e-9, "the next best recipe is not the second least costly one")

    -- the window: a row that is partly made and partly bought says how many
    -- are still to buy, and what is open is named in the note
    local L, d = ns.L, ns.CraftData
    local saved = { rank = ns.ProfessionRank, have = d.Have, known = d.Known, price = ns.GetPrice, compute = core.Compute, targets = ns.db.planTargets }
    local win
    local ok, err = pcall(function()
        local rank = 1
        ns.ProfessionRank = function(p) if p == "Alchemy" then return rank, 75 end end
        d.Have = function() return 0 end
        d.Known = function() return {} end
        ns.GetPrice = function() return 10, "AH scan" end
        ns.db.planTargets = nil
        local function Show(recipes, stock, prices)
            core.Compute = function(input)
                local p = {}
                for id, copper in pairs(prices) do p[id] = { status = "known", copper = copper, source = "AH scan" } end
                for _, r in ipairs(recipes) do r.prof = input.prof end
                return saved.compute({ prof = input.prof, skill = 1, target = 4, professions = {}, caps = {}, nodes = {}, stock = stock, recipeItemPrices = {},
                    recipes = { [input.prof] = recipes }, prices = p })
            end
            rank = rank + 1 -- (a new state, so the plan is made again)
            ns.ShowSkillPlan("Alchemy") advance(1)
            win = _G.GathercraftSkillPlan
        end
        local function Row(id)
            local name = ns.ItemName and ns.ItemName(id) or (L["item "] .. id)
            for _, o in ipairs(allFrames) do
                if o.left and o.mid and o.right and o:IsShown() and o.left:GetText() == name then return o end
            end
        end
        local function Text(needle)
            for _, o in ipairs(allFrames) do
                local parts = {}
                if o.left and o.mid and o.right and o:IsShown() then
                    parts = { o.left, o.mid, o.right }                -- a row of the plan
                elseif o.__kind == "FontString" and o.__parent == win then
                    parts = { o }                                     -- the sum and the note below
                end
                for _, part in ipairs(parts) do
                    local t = part:GetText()
                    if type(t) == "string" and t:find(needle, 1, true) then return true end
                end
            end
        end
        Show({ R("A", 9810, 1, 4, { { 9811, 1 } }), R("Make X", 9811, 1, 1, { { 9812, 1 } }) }, { [9812] = { n = 1 } }, { [9811] = 20, [9812] = 50 })
        local row = Row(9811)
        assert(row and row.right:GetText():find("|cffff70702|r", 1, true) and row.right:GetText():find(L["AH"], 1, true),
            "a row partly made, partly bought hides what is to buy: " .. tostring(row and row.right:GetText()))
        local tip = {}
        row.tip({ AddLine = function(_, t) tip[#tip + 1] = t end })
        assert(table.concat(tip, "\n"):find((L["The rest you make yourself (%s)."]):format(d.ProfLabel("Alchemy")), 1, true), "the made part is not named in the tooltip")
        assert(not Text(L["A learning cost is unknown: your trainer or the vendor shows it."]), "a note about an open cost without one")
        -- an open fee: the step is marked, the legend and the note say what is open
        Show({ R("A", 9810, 1, 4, { { 9811, 1 } }), R("Make X", 9811, 1, 1, { { 9812, 1 } }, { learn = "trainer" }) }, {}, { [9811] = 20, [9812] = 1 })
        assert(Text(L["? = a part of the cost is unknown: this choice is not fully comparable."]), "no legend for the open choice")
        assert(Text(L["A learning cost is unknown: your trainer or the vendor shows it."]), "the note does not name the open learning cost")
        assert(not Text(L["Some prices are unknown: scan the auction house for a better plan."]), "an open fee is called an unknown price")
        -- the note is one line at the bottom of the card, in this language too
        -- (an estimate: 6 px a letter, 11 px a CJK sign)
        local px = 0
        for ch in (L["A learning cost is unknown: your trainer or the vendor shows it."]):gmatch("[%z\1-\127\194-\244][\128-\191]*") do px = px + (#ch >= 3 and 11 or 6) end
        assert(px <= 500, ("%s: the note about a learning cost needs %d px of 500"):format(LOCALE, px))
        -- an open price: the note sends you to the auction house, as before
        Show({ R("A", 9810, 1, 4, { { 9813, 1 } }) }, {}, {})
        assert(Text(L["Some prices are unknown: scan the auction house for a better plan."]), "an unknown price: no note")
    end)
    ns.ProfessionRank, d.Have, d.Known, ns.GetPrice, core.Compute, ns.db.planTargets = saved.rank, saved.have, saved.known, saved.price, saved.compute, saved.targets
    if win then win:Hide() end
    if not ok then error(err, 0) end
end)
step("Skill plan 2.0: a recipe that unlocks inside a step is used from there on (v0.2 r1 F2)", function()
    -- Codex round 1, B2 (concept 4.3): what can be made is asked with the
    -- skill reached at that craft, not with the skill at the start of the
    -- step. A step is cut inside where a recipe further down its ingredients
    -- becomes usable; what is shown is one step all the same.
    local core = ns.PlanCore
    local function R(key, product, req, upto, mats, extra)
        local r = { prof = "Testing", key = key, name = key, product = product, made = 1, req = req, yellow = upto, grey = upto, reagents = {}, learn = "known" }
        for _, x in ipairs(mats) do r.reagents[#r.reagents + 1] = { id = x[1], n = x[2] } end
        for k, v in pairs(extra or {}) do r[k] = v end
        return r
    end
    local function Plan(recipes, stock, prices, from, to)
        local p = {}
        for id, copper in pairs(prices) do p[id] = { status = "known", copper = copper } end
        local plan = core.Compute({ prof = "Testing", skill = from, target = to, recipes = { Testing = recipes }, stock = stock, prices = p,
            professions = {}, recipeItemPrices = {}, caps = {} })
        local ok, why = core.CheckBalance(plan)
        assert(ok, "the books do not balance: " .. tostring(why))
        local m = {}
        for _, row in ipairs(plan.materials) do m[row.id] = row end
        return plan, m
    end
    local function Extra(plan, key)
        for _, e in ipairs(plan.extras) do if e.recipe.key == key then return e.times end end
        return 0
    end

    -- Codex UNLOCK_WITHIN_SEGMENT: A gives sure points from 1 to 9 and needs
    -- one X each. X costs 1000c; from skill 5 a trainer recipe makes it for
    -- 1c. Four X bought, four made: 4004c - not 8000c
    local function Unlock(fee)
        return Plan({ R("A", 10, 1, 9, { { 11, 1 } }), R("Make X", 11, 5, 5, { { 12, 1 } }, { learn = "trainer", fee = fee }) }, {}, { [11] = 1000, [12] = 1 }, 1, 9)
    end
    local plan, m = Unlock(0)
    assert(plan.total == 4004, ("a recipe that unlocks at 5 inside the step 1-9: %s copper, want 4004"):format(tostring(plan.total)))
    assert(m[11].need == 8 and m[11].missing == 4 and Extra(plan, "Make X") == 4 and m[12].need == 4 and m[12].missing == 4, "four bought, four made")
    -- shown as one step, counted as one step
    assert(#plan.steps == 1 and plan.steps[1].recipe.key == "A" and plan.steps[1].from == 1 and plan.steps[1].to == 9
        and plan.steps[1].crafts == 8 and plan.steps[1].expected == 8 and plan.steps[1].low == 8 and plan.steps[1].high == 8, "the step is shown in pieces")
    assert(plan.status == "ok" and plan.steps[1].comparable and not plan.notComparable, "status of the plan")
    -- its fee is paid when it pays off (4 x 1000c against 4c and 75c)
    plan = Unlock(75)
    assert(plan.total == 4004 and plan.learn.fees == 75 and plan.learn.trainer == 1, "the fee of the recipe that unlocks")
    -- not before its skill, also when the step starts right below it
    plan, m = Plan({ R("A", 10, 1, 9, { { 11, 1 } }), R("Make X", 11, 5, 5, { { 12, 1 } }) }, {}, { [11] = 1000, [12] = 1 }, 4, 6)
    assert(plan.total == 1001 and m[11].missing == 1 and Extra(plan, "Make X") == 1, "one bought at 4, one made at 5")

    -- with a chance below 1 the number of crafts stays the rounded-up mean of
    -- the whole step: A is yellow from 1 (grey at 21), 1-9 takes 9.89 crafts
    -- on average -> 10. The part before 5 takes 4.34 -> 5 of them (X bought),
    -- the other 5 come after it (X made)
    local function Yellow(more)
        local recipes = { R("A", 10, 1, 9, { { 11, 1 } }, { yellow = 1, grey = 21 }) }
        for _, r in ipairs(more) do recipes[#recipes + 1] = r end
        return Plan(recipes, {}, { [11] = 1000, [12] = 1, [13] = 1 }, 1, 9)
    end
    plan, m = Yellow({ R("Make X", 11, 5, 5, { { 12, 1 } }) })
    local s = plan.steps[1]
    assert(#plan.steps == 1 and s.crafts == 10 and math.abs(s.expected - 9.8906) < 0.001 and s.from == 1 and s.to == 9, ("the crafts of a step cut inside: %s"):format(tostring(s.crafts)))
    assert(m[11].need == 10 and m[11].missing == 5 and Extra(plan, "Make X") == 5 and plan.total == 5005, ("five bought, five made: %s copper"):format(tostring(plan.total)))
    local whole = core.Attempts(s.ps)
    assert(#s.ps == 8 and s.low == whole.low and s.high == whole.high and s.low < 10 and s.high > 10, "the range of a step cut inside is not the range of the whole step")
    -- a recipe that unlocks at 5 but makes nothing this step needs cuts nothing
    plan, m = Yellow({ R("Other", 14, 5, 5, { { 13, 1 } }) })
    assert(#plan.steps == 1 and plan.steps[1].crafts == 10 and m[11].missing == 10 and plan.total == 10000, "a recipe the step does not need changes it")

    -- two levels down: X is made from W all along (W bought, 600c); from 5
    -- on W can be made from a 1c material
    plan, m = Plan({ R("A", 10, 1, 9, { { 11, 1 } }), R("Make X", 11, 1, 1, { { 15, 1 } }), R("Make W", 15, 5, 5, { { 12, 1 } }) },
        {}, { [11] = 1000, [15] = 600, [12] = 1 }, 1, 9)
    assert(plan.total == 4 * 600 + 4 and Extra(plan, "Make X") == 8 and Extra(plan, "Make W") == 4 and m[15].missing == 4, ("a recipe two levels down unlocks: %s copper"):format(tostring(plan.total)))

    -- an intermediate recipe that unlocks inside the step and still gives
    -- points itself: its crafts come as a step "for materials" from its own
    -- skill on - none before it, and the plan still ends at the target
    -- (Make X gives a point in 4 of 100 crafts at 5: 25 crafts for one. A
    -- needs 10 X a craft: 1-5 buys 40; at 5 the 40 X of the rest would be
    -- made, 25 of them as a step with a point; A goes on at 6 with 3 crafts)
    plan, m = Plan({ R("A", 10, 1, 9, { { 11, 10 } }), R("Make X", 11, 5, 9, { { 12, 1 } }, { yellow = -187, grey = 13 }) }, {}, { [11] = 1000, [12] = 1 }, 1, 9)
    local at, last
    for _, st in ipairs(plan.steps) do
        if st.forMaterials then at = at or st.from end
        last = st
    end
    assert(at == 5 and last.to == 9 and plan.steps[1].recipe.key == "A" and plan.steps[1].from == 1 and plan.steps[1].to == 5, "extra crafts that give points, from the skill their recipe unlocks at")
    assert(#plan.steps == 3 and plan.steps[2].crafts == 25 and plan.steps[3].from == 6 and plan.steps[3].crafts == 3, "the step after the extra crafts")
    assert(m[11].missing == 40, "before the recipe unlocks its product is bought")
    -- training between two parts of a step still comes between them
    local input = { prof = "Testing", skill = 1, target = 9, maxRank = 5, caps = {}, professions = {}, recipeItemPrices = {}, stock = {},
        recipes = { Testing = { R("A", 10, 1, 9, { { 11, 1 } }), R("Make X", 11, 5, 5, { { 12, 1 } }) } },
        prices = { [11] = { status = "known", copper = 1000 }, [12] = { status = "known", copper = 1 } } }
    plan = core.Compute(input)
    assert(#plan.steps == 2 and plan.steps[1].to == 5 and plan.steps[2].from == 5 and plan.training[1].at == 5 and plan.total == 4004, "training at the same skill: the step is not shown in two parts")
end)
step("Skill plan 2.0: amounts are a planning estimate, and said to be one (v0.2 r1 F3)", function()
    -- Codex round 1, B3, as Sven decided on 10.11.: the amounts and the cost
    -- of a plan are a PLANNING ESTIMATE from the rounded-up mean number of
    -- crafts of each step - not an expected value over all the ways a plan
    -- can go (concept 4.1 / 4.3 is changed in this for 0.2, on purpose). The
    -- plan says so, and an output that varies is marked as an assumption.
    local core, L, d = ns.PlanCore, ns.L, ns.CraftData
    local function R(key, product, req, upto, mats, extra)
        local r = { prof = "Testing", key = key, name = key, product = product, made = 1, req = req, yellow = upto, grey = upto, reagents = {}, learn = "known" }
        for _, x in ipairs(mats) do r.reagents[#r.reagents + 1] = { id = x[1], n = x[2] } end
        for k, v in pairs(extra or {}) do r[k] = v end
        return r
    end
    local function Plan(recipes, stock, prices, from, to)
        local p = {}
        for id, copper in pairs(prices) do p[id] = { status = "known", copper = copper } end
        local plan = core.Compute({ prof = "Testing", skill = from, target = to, recipes = { Testing = recipes }, stock = stock, prices = p,
            professions = {}, recipeItemPrices = {}, caps = {} })
        local ok, why = core.CheckBalance(plan)
        assert(ok, "the books do not balance: " .. tostring(why))
        local m = {}
        for _, row in ipairs(plan.materials) do m[row.id] = row end
        return plan, m
    end
    local function Extra(plan, key)
        for _, e in ipairs(plan.extras) do if e.recipe.key == key then return e.times end end
        return 0
    end

    -- Codex JOINT_EXPECTATION, kept as a DOCUMENTED DEVIATION: A gives the
    -- point 1-2 with a chance of 1/2 and makes one X a craft; B (2-3, sure)
    -- needs two X. Going through every way the plan can go, the raw material
    -- needed is max(T, 2) for T tries of A - 2.5 on average. The planning
    -- estimate counts the rounded-up mean of the step instead: 2 crafts of A,
    -- 2 X, 2 raw pieces. (The joint expectation would be 2.5; by design it is
    -- not modelled.)
    local plan, m = Plan({ R("A", 11, 1, 2, { { 12, 1 } }, { yellow = 0 }), R("B", 10, 2, 3, { { 11, 2 } }) }, {}, { [11] = 1000, [12] = 1 }, 1, 3)
    assert(#plan.steps == 2 and plan.steps[1].recipe.key == "A" and plan.steps[1].crafts == 2 and plan.steps[1].expected == 2
        and plan.steps[1].low == 1 and plan.steps[1].high == 4, "A: 2 crafts on average, 1 to 4 in 8 of 10 cases")
    assert(m[12].need == 2 and plan.total == 2 and m[11].need == 2 and m[11].missing == 0 and Extra(plan, "A") == 0,
        ("the planning estimate of the documented case changed: %s raw pieces"):format(tostring(m[12].need)))
    -- ... and it is called what it is: an estimate of the amounts, because a
    -- step's number of crafts is a mean
    assert(type(plan.estimate) == "table" and plan.estimate.crafts == true and plan.estimate.output == false, "the plan does not say that its amounts are an estimate")
    assert(core.Result(plan).estimate and core.Result(plan).estimate.crafts == true, "the second reader is not told")
    -- every step certain, every output fixed: the amounts are what the model
    -- says exactly, nothing is called an estimate
    plan = Plan({ R("A", 11, 1, 3, { { 12, 1 } }) }, {}, { [12] = 1 }, 1, 3)
    assert(plan.estimate.crafts == false and plan.estimate.output == false, "a plan of certain steps is called an estimate")

    -- Codex SUPPLEMENT, also on purpose: two extra crafts of Make X (4 of 100
    -- for a point at 97) are needed. They are made, their material is
    -- counted, their output is used - but no part of a skill point is
    -- counted for them: an extra craft counts towards the skill only as a
    -- whole point, once its crafts reach the mean for one (25 here). Counting
    -- less would promise a point that mostly does not come.
    plan, m = Plan({ R("A", 10, 97, 99, { { 11, 1 } }), R("Make X", 11, 1, 101, { { 12, 1 } }, { yellow = 1 }) }, {}, { [11] = 1000, [12] = 1 }, 97, 99)
    assert(#plan.steps == 1 and plan.steps[1].recipe.key == "A" and plan.steps[1].crafts == 2 and not plan.steps[1].forMaterials,
        "two extra crafts with a small chance changed the steps")
    assert(Extra(plan, "Make X") == 2 and m[12].need == 2 and m[11].need == 2 and m[11].missing == 0 and plan.total == 2, "the extra crafts or their output are dropped")

    -- an output that varies (the game makes 1 to 2: counted with the mean,
    -- 1.5) is an ASSUMPTION, not a known amount: the step, the item it makes
    -- and what its extra crafts use are marked
    plan, m = Plan({ R("A", 11, 1, 2, { { 12, 1 } }, { made = 1.5, madeVaries = true }), R("B", 10, 2, 3, { { 11, 2 } }) }, {}, { [11] = 100, [12] = 1 }, 1, 3)
    assert(plan.steps[1].outputAssumed == true and not plan.steps[2].outputAssumed, "a step with a varying output is not marked")
    assert(m[11].outputAssumed == true and m[12].outputAssumed == true, "the items that rest on a varying output are not marked")
    assert(plan.estimate.output == true and core.Result(plan).items[11].outputAssumed == true, "a varying output is not passed on as an assumption")
    -- (a mean that is no whole number is one too, also when nobody said so)
    plan = Plan({ R("A", 11, 1, 2, { { 12, 1 } }, { made = 1.5 }), R("B", 10, 2, 3, { { 11, 2 } }) }, {}, { [11] = 100, [12] = 1 }, 1, 3)
    assert(plan.steps[1].outputAssumed == true and plan.estimate.output == true, "a mean output that is no whole number is taken for a fixed amount")
    -- a fixed output of more than one is no assumption
    plan, m = Plan({ R("A", 11, 1, 2, { { 12, 1 } }, { made = 2 }), R("B", 10, 2, 3, { { 11, 2 } }) }, {}, { [11] = 100, [12] = 1 }, 1, 3)
    assert(not plan.steps[1].outputAssumed and not m[11].outputAssumed and plan.estimate.output == false, "a fixed output is called an assumption")

    -- the snapshot tells the calculation which outputs vary (the game's
    -- recipe record says "makes 1 to 2")
    local saved = { rank = ns.ProfessionRank, have = d.Have, known = d.Known, all = d.AllRecipes, price = ns.GetPrice, compute = core.Compute, targets = ns.db.planTargets }
    local win
    local ok, err = pcall(function()
        local rank = 1
        ns.ProfessionRank = function(p) if p == "Tailoring" then return rank, 75 end end
        d.Have = function() return 0 end
        d.AllRecipes = function(p) return p == "Tailoring" and { ["Bolt of Linen Cloth"] = "2996:1:2:1|2589:2", ["Linen Bandage"] = "1251:1:1:1|2589:1" } or {} end
        d.Known = d.AllRecipes
        local snapshot = ns.SkillPlanSnapshot("Tailoring", 1, 2)
        local byKey = {}
        for _, r in ipairs(snapshot.recipes.Tailoring) do byKey[r.key] = r end
        assert(byKey["Bolt of Linen Cloth"].made == 1.5 and byKey["Bolt of Linen Cloth"].madeVaries == true, "the snapshot does not say that an output varies")
        assert(byKey["Linen Bandage"].made == 1 and not byKey["Linen Bandage"].madeVaries, "a fixed output is said to vary")
        d.Known, d.AllRecipes = saved.known, saved.all

        -- the window says it: one line under the materials, and in the tooltips
        d.Known = function() return {} end
        ns.GetPrice = function() return 10, "AH scan" end
        ns.db.planTargets = nil
        local function Show(recipes)
            core.Compute = function(input)
                for _, r in ipairs(recipes) do r.prof = input.prof end
                return saved.compute({ prof = input.prof, skill = 1, target = 3, professions = {}, caps = {}, nodes = {}, stock = {}, recipeItemPrices = {},
                    recipes = { [input.prof] = recipes }, prices = { [9841] = { status = "known", copper = 100, source = "AH scan" }, [9842] = { status = "known", copper = 1, source = "AH scan" } } })
            end
            rank = rank + 1 -- (a new state, so the plan is made again)
            ns.ShowSkillPlan("Tailoring") advance(1)
            win = _G.GathercraftSkillPlan
        end
        local function Rows()
            local list = {}
            for _, o in ipairs(allFrames) do
                if o.left and o.mid and o.right and o:IsShown() then list[#list + 1] = o end
            end
            return list
        end
        local function Shows(text)
            for _, row in ipairs(Rows()) do
                local t = row.left:GetText()
                if type(t) == "string" and t:find(text, 1, true) then return row end
            end
        end
        local function Tip(row)
            local lines = {}
            if row and row.tip then row.tip({ AddLine = function(_, t) lines[#lines + 1] = t end }) end
            return table.concat(lines, "\n")
        end
        local ESTIMATE = L["Planning estimate from the average number of crafts per step - what you really need varies."]
        local OUTPUT = L["Counted with the average output per craft - what a craft really makes varies."]
        Show({ R("A", 9841, 1, 2, { { 9842, 1 } }, { yellow = 0, made = 1.5, madeVaries = true, name = "Recipe A" }), R("B", 9840, 2, 3, { { 9841, 2 } }, { name = "Recipe B" }) })
        assert(Shows(ESTIMATE), "the window does not call the amounts a planning estimate")
        local stepA = Shows("Recipe A")
        assert(stepA and Tip(stepA):find(OUTPUT, 1, true), "the step's tooltip does not say that its output varies")
        local function Mat(id)
            local name = ns.ItemName and ns.ItemName(id) or (L["item "] .. id)
            for _, row in ipairs(Rows()) do if row.left:GetText() == name then return row end end
        end
        local raw, made = Mat(9842), Mat(9841)
        assert(raw and Tip(raw):find(ESTIMATE, 1, true), "a material's tooltip does not say that its amount is an estimate")
        assert(made and Tip(made):find(OUTPUT, 1, true) and not Tip(raw):find(OUTPUT, 1, true), "the item with the varying output is not marked in its tooltip")
        assert(not Tip(Shows("Recipe B")):find(OUTPUT, 1, true), "a fixed output is said to vary")
        -- nothing is promised by these texts
        for _, text in ipairs({ ESTIMATE, OUTPUT }) do
            local low = text:lower()
            assert(not low:find("exact", 1, true) and not low:find("guarantee", 1, true) and not low:find("cheapest", 1, true), "a text promises too much: " .. text)
        end
        -- a plan of certain steps with fixed outputs: no such line
        Show({ R("A", 9841, 1, 3, { { 9842, 1 } }, { name = "Recipe A" }) })
        assert(not Shows(ESTIMATE), "a plan without anything estimated is called an estimate")
    end)
    ns.ProfessionRank, d.Have, d.Known, d.AllRecipes, ns.GetPrice, core.Compute, ns.db.planTargets = saved.rank, saved.have, saved.known, saved.all, saved.price, saved.compute, saved.targets
    if win then win:Hide() end
    if not ok then error(err, 0) end
end)
step("Skill plan 2.0: a changed recipe is a new plan (v0.2 r1 F4)", function()
    -- Codex round 1, B4 (concept 4.6): the plan is kept only as long as
    -- everything it was made from is the same - also the recipes themselves:
    -- what they need, what and how many they make, their skill and colours,
    -- how they are learned and what that costs.
    local d = ns.CraftData
    local saved = { rank = ns.ProfessionRank, have = d.Have, cost = d.ReagentCost, known = d.Known, all = d.AllRecipes }
    local key = "Bolt of Linen Cloth"
    local spell = GathercraftRecipeData.spells.Tailoring[key]
    assert(spell and GathercraftRecipeData.colors[spell], "test setup: " .. key .. " has no colour data")
    local colours, fee = GathercraftRecipeData.colors[spell], GathercraftRecipeSources.trainer[spell]
    local ok, err = pcall(function()
        local packed, knows = "2996:1:1:1|2589:2", true
        ns.ProfessionRank = function(p) if p == "Tailoring" then return 1, 75 end end
        d.AllRecipes = function(p) return p == "Tailoring" and { [key] = packed } or {} end
        d.Known = function(p) return (p == "Tailoring" and knows) and { [key] = packed } or {} end
        d.Have = function() return 0 end
        d.ReagentCost = function() return 1, "AH scan", false end
        local function Calc()
            local plan, new = ns.SkillPlanCalculate("Tailoring", 1, 2)
            local m = {}
            for _, row in ipairs(plan.materials) do m[row.id] = row end
            return plan, new, m
        end
        local plan, new, m = Calc()
        local revision = plan.revision
        assert(m[2589] and m[2589].need == 2, "test setup: the plan needs 2 Linen Cloth")
        -- nothing changed: the same plan, the same revision
        plan, new = Calc()
        assert(not new and plan.revision == revision, "the same state gives a new plan")
        local function Changed(what)
            local p, isNew, rows = Calc()
            assert(isNew and p.revision == revision + 1, what .. ": the old plan is kept (revision " .. tostring(p.revision) .. ")")
            assert(ns.SkillPlanResult().revision == p.revision, what .. ": the second reader has the old revision")
            revision = p.revision
            return p, rows
        end
        -- Codex RECIPE_REVISION: the recipe now needs 5 Linen Cloth, not 2
        packed = "2996:1:1:1|2589:5"
        plan, m = Changed("another amount of an ingredient")
        assert(m[2589].need == 5, ("the plan still needs %d Linen Cloth, want 5"):format(m[2589].need))
        -- another ingredient
        packed = "2996:1:1:1|2592:5"
        plan, m = Changed("another ingredient")
        assert(m[2592] and m[2592].need == 5 and not m[2589], "the plan still needs the old ingredient")
        -- the same name, the same ingredients, the same prices - only what a craft makes
        packed = "2996:2:2:1|2592:5"
        plan = Changed("another number made")
        assert(plan.ledger[2996].madePlan == 2, "the plan still makes one a craft")
        packed = "2997:2:2:1|2592:5"
        plan = Changed("another product")
        assert(plan.ledger[2997] and not plan.ledger[2996], "the plan still makes the old product")
        packed = "2997:1:3:1|2592:5" -- (the same mean, now a varying output)
        Changed("an output that varies")
        -- its colours
        local yellow, grey = colours:match("^(%d+):(%d+)$")
        GathercraftRecipeData.colors[spell] = ("%d:%d"):format(yellow, grey + 10)
        Changed("another colour threshold")
        -- how it is learned, and what that costs
        knows = false
        GathercraftRecipeSources.trainer[spell] = 50
        plan = Changed("not known any more")
        assert(plan.learn.trainer == 1 and plan.learn.fees == 50, "test setup: the recipe is learned from a trainer for 50c")
        GathercraftRecipeSources.trainer[spell] = 70
        plan = Changed("another trainer fee")
        assert(plan.learn.fees == 70, "the plan still counts the old fee")
        -- and again nothing changed
        plan, new = Calc()
        assert(not new and plan.revision == revision, "the same state gives a new plan (after the changes)")
    end)
    ns.ProfessionRank, d.Have, d.ReagentCost, d.Known, d.AllRecipes = saved.rank, saved.have, saved.cost, saved.known, saved.all
    GathercraftRecipeData.colors[spell], GathercraftRecipeSources.trainer[spell] = colours, fee
    if not ok then error(err, 0) end
    -- every field of a recipe the calculation reads comes from what the
    -- signature holds: the record as the game gave it, and what the snapshot adds
    local f = assert(io.open(ROOT .. "/Planner.lua"))
    local planner = f:read("*a") f:close()
    local sig = planner:match("local function RecipeSignature%(r%)(.-)\nend")
    assert(sig, "no signature of a recipe")
    for _, field in ipairs({ "key", "packed", "learn", "req", "yellow", "grey", "fee", "recipeItem" }) do
        assert(sig:find("r." .. field, 1, true), "the signature of a recipe leaves out " .. field)
    end
end)
step("Skill plan 2.0: a profession that is there with an unreadable skill is never \"not learned\" (v0.2 r1 F5)", function()
    -- Codex round 1, B5 (concept 5): "not learned" needs proof - the whole
    -- skill list readable AND the profession not in it. A line of the
    -- profession whose skill cannot be read is the profession found with an
    -- unknown skill: "skill unknown", no plan from 1. Through the real reader
    -- of the skill list (ns.ProfessionRank), not a stand-in for it.
    local L, core = ns.L, ns.PlanCore
    local saved = { lines = GetNumSkillLines, line = GetSkillLineInfo, secret = issecretvalue, recipes = ns.db.recipes, targets = ns.db.planTargets,
        compute = core.Compute }
    local win
    local ok, err = pcall(function()
        ns.db.recipes = {}     -- no skill remembered from a profession window
        ns.db.planTargets = nil
        local SECRET = newproxy(true)
        issecretvalue = function(v) return rawequal(v, SECRET) end
        local rank, maxRank, name = SECRET, 75, "Tailoring"
        GetNumSkillLines = function() return 3 end
        GetSkillLineInfo = function(i)
            if i == 1 then return "Professions", true, true, 0, 0, 0, 0 end
            if i == 2 then return name, false, true, rank, 0, 0, maxRank end
            return "Secondary Skills", true, true, 0, 0, 0, 0
        end
        local computes = 0
        core.Compute = function(input) computes = computes + 1 return saved.compute(input) end
        local function Shows(text)
            for _, o in ipairs(allFrames) do
                if o.left and o.mid and o.right and o:IsShown() then
                    local t = o.left:GetText()
                    if type(t) == "string" and t:find(text, 1, true) then return true end
                end
            end
        end
        local function Header(text)
            for _, o in ipairs(allFrames) do
                if o.__kind == "FontString" and o.__parent == win and o:GetText() == text then return true end
            end
        end

        -- Codex' probe: the line is there, its skill is hidden
        assert(ns.ProfessionRank("Tailoring") == nil, "test setup: the real reader gives a hidden skill out")
        local state, r, m, why = ns.SkillPlanSkillState("Tailoring")
        assert(state == "unknown", "a profession with a hidden skill is called " .. tostring(state))
        assert(r == nil and m == nil and why == "rank", "found with an unknown skill is not told apart")
        local shown, problem = pcall(function() ns.ShowSkillPlan("Tailoring") advance(1) end)
        win = _G.GathercraftSkillPlan
        assert(shown, "a hidden skill breaks the window: " .. tostring(problem))
        assert(Shows(L["Your skill could not be read, so there is no plan yet."]) and computes == 0, "a hidden skill: a plan was made")
        assert(not Shows(L["Not learned yet - learn it from a trainer. This is a preview from skill 1."]) and not Header(L["Not learned yet"]),
            "a profession with a hidden skill is shown as not learned")
        assert(Header(L["Your skill: ? (open your profession window once)"]) and not _G.GathercraftSkillPlanTarget:IsShown(), "skill unknown is not shown")
        -- a skill that is no number, or missing in the line: the same
        for _, odd in ipairs({ "12", false }) do
            rank = odd or nil
            state, r, m, why = ns.SkillPlanSkillState("Tailoring")
            assert(state == "unknown" and why == "rank", "a line without a usable skill is called " .. tostring(state))
        end
        -- readable: learned, with its numbers (the way Codex' probe ends)
        rank = 25
        state, r, m = ns.SkillPlanSkillState("Tailoring")
        assert(state == "learned" and r == 25 and m == 75, "a readable skill: " .. tostring(state))
        -- only the maximum hidden: the real reader skips the line, the skill itself is still used
        maxRank = SECRET
        assert(ns.ProfessionRank("Tailoring") == nil, "test setup: a line with a hidden maximum is read")
        state, r, m = ns.SkillPlanSkillState("Tailoring")
        assert(state == "learned" and r == 25 and m == nil, "a hidden maximum hides the skill: " .. tostring(state))
        computes = 0
        ns.ShowSkillPlan("Tailoring") advance(1)
        assert(computes > 0 and Header((L["Your skill: %d"]):format(25)), "a hidden maximum: no plan from the readable skill")
        maxRank = 75
        -- the profession really is not in a list that can be read whole: not learned, a preview from 1
        name = "Herbalism"
        state = ns.SkillPlanSkillState("Tailoring")
        assert(state == "unlearned", "positively not learned is called " .. tostring(state))
        computes = 0
        ns.db.planTargets = nil
        ns.ShowSkillPlan("Tailoring") advance(1)
        assert(computes > 0 and Shows(L["Not learned yet - learn it from a trainer. This is a preview from skill 1."]), "positively not learned: no preview")
        -- a line whose NAME is hidden could be the profession: unknown
        name = SECRET
        state = ns.SkillPlanSkillState("Tailoring")
        assert(state == "unknown", "a hidden line: called " .. tostring(state))
    end)
    GetNumSkillLines, GetSkillLineInfo, issecretvalue, ns.db.recipes, ns.db.planTargets, core.Compute = saved.lines, saved.line, saved.secret, saved.recipes, saved.targets, saved.compute
    if win then win:Hide() end
    if not ok then error(err, 0) end
end)
step("Skill plan 2.0: a count that is not known stays unknown, and the sum says what it assumes (v0.2 r1 F6)", function()
    -- Codex round 1, B6 (concept 4.4 - 4.6)
    local L, core, d = ns.L, ns.PlanCore, ns.CraftData
    local saved = { rank = ns.ProfessionRank, have = d.Have, known = d.Known, price = ns.GetPrice, compute = core.Compute, targets = ns.db.planTargets,
        item = C_Item, count = GetItemCount }
    local win
    local ok, err = pcall(function()
        -- (1) neither of the game's counting functions is there: the count is
        -- unknown - not the 0 the counting falls back to (the real d.Have)
        C_Item, GetItemCount = nil, nil
        local entry = ns.SkillPlanSnapshot("Tailoring", 1, 2).stock[2589]
        C_Item, GetItemCount = saved.item, saved.count
        assert(type(entry) == "table" and entry.unknown == true and entry.n == nil,
            ("no way to count: the count is %s, unknown %s"):format(tostring(entry and entry.n), tostring(entry and entry.unknown)))
        -- with a way to count it is a number again
        entry = ns.SkillPlanSnapshot("Tailoring", 1, 2).stock[2589]
        assert(type(entry.n) == "number" and not entry.unknown, "a count that can be read is unknown")

        -- (2) the plan goes on with 0 for a count it does not know - and says
        -- that what is missing of it, and its cost, rest on that assumption
        local function R(key, product, req, upto, mats, extra)
            local r = { prof = "Testing", key = key, name = key, product = product, made = 1, req = req, yellow = upto, grey = upto, reagents = {}, learn = "known" }
            for _, x in ipairs(mats) do r.reagents[#r.reagents + 1] = { id = x[1], n = x[2] } end
            for k, v in pairs(extra or {}) do r[k] = v end
            return r
        end
        local function Plan(recipes, stock)
            local plan = core.Compute({ prof = "Testing", skill = 1, target = 4, recipes = { Testing = recipes }, stock = stock, professions = {}, recipeItemPrices = {}, caps = {},
                prices = { [12] = { status = "known", copper = 2 }, [13] = { status = "known", copper = 3 }, [14] = { status = "known", copper = 500 }, [15] = { status = "known", copper = 1 } } })
            assert(core.CheckBalance(plan))
            local m = {}
            for _, row in ipairs(plan.materials) do m[row.id] = row end
            return plan, m, core.Result(plan)
        end
        local plan, m, result = Plan({ R("A", 10, 1, 4, { { 12, 1 }, { 13, 1 } }) }, { [12] = { unknown = true }, [13] = 5 })
        assert(m[12].haveKnown == false and m[12].missing == 3 and m[12].cost == 6 and not m[12].covered and plan.status == "incomplete", "an unknown count: as before")
        assert(m[12].missingAssumed == true and not m[13].missingAssumed, "what is missing of an item with an unknown count is not marked as assumed")
        assert(#plan.cost.assumedItems == 1 and plan.cost.assumedItems[1] == 12, "the sum does not say which items it assumes none of")
        assert(result.items[12].missingAssumed == true and result.items[12].have == nil and result.items[12].missing == 3, "the second reader cannot tell an assumed amount")
        assert(result.items[13].missingAssumed == false and result.items[13].have == 5 and result.stockAssumed == 1, "a known count is marked as assumed")
        -- also when the plan makes the thing instead of buying it
        plan, m, result = Plan({ R("A", 10, 1, 4, { { 14, 1 } }), R("Make it", 14, 1, 1, { { 15, 1 } }) }, { [14] = { unknown = true } })
        assert(m[14].madeFrom and m[14].missing == 0 and m[14].missingAssumed == true and result.items[14].missingAssumed == true and result.stockAssumed == 1,
            "an item made for the plan with an unknown count is not marked")
        -- every count known: nothing is assumed
        plan, m, result = Plan({ R("A", 10, 1, 4, { { 12, 1 }, { 13, 1 } }) }, { [12] = 1, [13] = 5 })
        assert(#plan.cost.assumedItems == 0 and result.stockAssumed == 0 and not m[12].missingAssumed, "known counts are called assumed")

        -- (3) the window says it where the sum is, and in the row's tooltip
        local rank = 1
        ns.ProfessionRank = function(p) if p == "Alchemy" then return rank, 75 end end
        d.Known = function() return {} end
        ns.GetPrice = function() return 10, "AH scan" end
        ns.db.planTargets = nil
        local function Show(stock)
            core.Compute = function(input)
                local a = R("A", 9850, 1, 4, { { 9851, 1 }, { 9852, 1 } }, { name = "Recipe A" })
                a.prof = input.prof
                return saved.compute({ prof = input.prof, skill = 1, target = 4, professions = {}, caps = {}, nodes = {}, stock = stock, recipeItemPrices = {},
                    recipes = { [input.prof] = { a } },
                    prices = { [9851] = { status = "known", copper = 200, source = "AH scan" }, [9852] = { status = "known", copper = 1, source = "AH scan" } } })
            end
            rank = rank + 1 -- (a new state, so the plan is made again)
            ns.ShowSkillPlan("Alchemy") advance(1)
            win = _G.GathercraftSkillPlan
        end
        local function Bottom()
            local note, total
            for _, o in ipairs(allFrames) do
                local at = o.__kind == "FontString" and o.__parent == win and o.__pts and o.__pts.BOTTOMLEFT
                if at and at[2] == 24 then note = o elseif at and at[2] == 42 then total = o end
            end
            assert(note and total, "test setup: the note and the sum at the bottom")
            return note:GetText() or "", total:GetText() or ""
        end
        local function Row(id)
            local name = ns.ItemName and ns.ItemName(id) or (L["item "] .. id)
            for _, o in ipairs(allFrames) do
                if o.left and o.mid and o.right and o:IsShown() and o.left:GetText() == name then return o end
            end
        end
        local ASSUMED = (L["Counted as if you had none of the %d marked ?: the sum may be too high."]):format(1)
        Show({ [9851] = { unknown = true }, [9852] = { n = 9 } })
        local note, total = Bottom()
        assert(total:find((L["Missing materials cost about %s"]):format(ns.Money(600)), 1, true), "the sum under an unknown count: " .. total)
        assert(note:find(ASSUMED, 1, true), "the sum does not say that it assumes none in stock: " .. note)
        local row = Row(9851)
        assert(row and row.mid:GetText():find("? / 3", 1, true) and not row.check:IsShown(), "the row of an unknown count")
        local tip = {}
        row.tip({ AddLine = function(_, t) tip[#tip + 1] = t end })
        tip = table.concat(tip, "\n")
        assert(tip:find(L["How many you have could not be read."], 1, true) and tip:find(L["What is missing is counted as if you had none."], 1, true), "the row's tooltip does not name the assumption")
        -- the note is one line at the bottom of the card, in this language too
        -- (an estimate: 6 px a letter, 11 px a CJK sign)
        local px = 0
        for ch in ((L["Counted as if you had none of the %d marked ?: the sum may be too high."]):format(12)):gmatch("[%z\1-\127\194-\244][\128-\191]*") do px = px + (#ch >= 3 and 11 or 6) end
        assert(px <= 500, ("%s: the note about assumed stock needs %d px of 500"):format(LOCALE, px))
        -- every count known: no such note, no such line
        Show({ [9851] = { n = 0 }, [9852] = { n = 9 } })
        note = Bottom()
        tip = {}
        Row(9851).tip({ AddLine = function(_, t) tip[#tip + 1] = t end })
        assert(not note:find(ASSUMED, 1, true) and not table.concat(tip, "\n"):find(L["What is missing is counted as if you had none."], 1, true), "known counts: the sum says it assumes something")
    end)
    C_Item, GetItemCount = saved.item, saved.count
    ns.ProfessionRank, d.Have, d.Known, ns.GetPrice, core.Compute, ns.db.planTargets = saved.rank, saved.have, saved.known, saved.price, saved.compute, saved.targets
    if win then win:Hide() end
    if not ok then error(err, 0) end
end)
step("Skill plan 2.0: what the plan does not check is said once, tools are not listed (v0.2 r1 F8)", function()
    -- Concept 4.7, as Sven set it for building block 1 on 10.11.: a forge, an
    -- anvil, a cooldown (and reputation, character level) are not in the
    -- shipped data, so the plan does not check them - it says so in one line.
    -- Tools are not listed at all. No requirement is made up.
    local L, core, d = ns.L, ns.PlanCore, ns.CraftData
    local saved = { rank = ns.ProfessionRank, have = d.Have, known = d.Known, price = ns.GetPrice, compute = core.Compute, targets = ns.db.planTargets, filter = ns.CraftFilter }
    local win
    local ok, err = pcall(function()
        local rank = 1
        ns.ProfessionRank = function(p) if p == "Blacksmithing" or p == "Enchanting" then return rank, 75 end end
        d.Have = function() return 0 end
        d.Known = function() return {} end
        ns.GetPrice = function() return 10, "AH scan" end
        ns.db.planTargets = nil
        local NOTE = L["Some recipes also need a tool, a forge or an anvil, or have a cooldown - the plan does not check that."]
        -- how many rows of the plan are exactly this line (the whole text: a
        -- short word like "Steps" is part of other lines in some languages)
        local function Count(text)
            local n = 0
            for _, o in ipairs(allFrames) do
                if o.left and o.mid and o.right and o:IsShown() and o.left:GetText() == text then n = n + 1 end
            end
            return n
        end
        -- a real plan from the shipped data: the line is there, once
        rank = rank + 1
        ns.ShowSkillPlan("Blacksmithing") advance(1)
        win = _G.GathercraftSkillPlan
        assert(Count(L["Steps"]) == 1 and Count(L["Materials"]) == 1, "test setup: no plan shown")
        assert(Count(NOTE) == 1, ("what the plan does not check is said %d times, want once"):format(Count(NOTE)))
        -- it promises nothing and names no requirement of a certain recipe
        local low = NOTE:lower()
        assert(not low:find("guarantee", 1, true) and not low:find("always", 1, true), "the line promises too much")
        -- tools are not listed: the rod an enchanter makes once is no material
        -- row and no row "needed, not used up"
        rank = rank + 1
        ns.ShowSkillPlan("Enchanting") advance(1)
        local rod = ns.ItemName and ns.ItemName(6218)
        assert(rod and Count(NOTE) == 1, "test setup: the rod's name")
        for _, o in ipairs(allFrames) do
            if o.left and o.mid and o.right and o:IsShown() and o.left:GetText() == rod then
                error("the Runed Copper Rod is listed as a material: " .. tostring(o.mid:GetText()), 0)
            end
        end
        -- the calculation knows no requirement beyond the recipe's record:
        -- nothing in a plan claims that one is met or missing
        local plan = core.Compute(ns.SkillPlanSnapshot("Enchanting", 1, 75))
        assert(plan.valid and plan.requirements == nil and plan.tools == nil, "the plan claims to know requirements")
        for _, s in ipairs(plan.steps) do
            assert(s.requires == nil and s.tools == nil and s.cooldown == nil, "a step claims to know a requirement")
        end
        -- at the target there is nothing to craft: no line
        ns.SkillPlanSetTarget(rank + 5)
        rank = rank + 5
        ns.ShowSkillPlan("Enchanting") advance(1)
        assert(Count((L["Done: you have reached your target (%d)."]):format(rank)) == 1 and Count(NOTE) == 0, "the line at the target")
        -- no plan, no line: nothing chosen, nothing to plan from
        core.Compute = function() return saved.compute({}) end
        rank = rank + 1
        ns.ShowSkillPlan("Blacksmithing") advance(1)
        assert(Count(L["No plan: there is nothing to plan from."]) == 1 and Count(NOTE) == 0, "the line without a plan")
        core.Compute = saved.compute
        ns.CraftFilter = function() return "mine" end
        ns.ShowSkillPlan() advance(1)
        assert(Count(L["Choose a profession first."]) == 1 and Count(NOTE) == 0, "the line without a profession")
    end)
    ns.ProfessionRank, d.Have, d.Known, ns.GetPrice, core.Compute, ns.db.planTargets, ns.CraftFilter = saved.rank, saved.have, saved.known, saved.price, saved.compute, saved.targets, saved.filter
    if win then win:Hide() end
    if not ok then error(err, 0) end
end)
step("Skill plan 2.0: the recipe choice counts whole batches, like the material balance (v0.2 r2 G1)", function()
    -- Codex round 2, R2-M1 (concept 4.2 / 4.3): which recipe gives the next
    -- point is judged by what the material balance would really count for
    -- its crafts - whole batches of what they need, or the piece bought. A
    -- part of a batch ("a third of a batch of three") cannot be made and is
    -- no cost to compare with. Plain tables; a recipe gives one point per
    -- craft from `req` up to `upto`.
    local core = ns.PlanCore
    local function R(key, product, req, upto, mats, extra)
        local r = { prof = "Testing", key = key, name = key, product = product, made = 1, req = req, yellow = upto, grey = upto, reagents = {}, learn = "known" }
        for _, x in ipairs(mats) do r.reagents[#r.reagents + 1] = { id = x[1], n = x[2] } end
        for k, v in pairs(extra or {}) do r[k] = v end
        return r
    end
    local function Plan(recipes, stock, prices, from, to)
        local p = {}
        for id, copper in pairs(prices) do p[id] = { status = "known", copper = copper } end
        local plan = core.Compute({ prof = "Testing", skill = from or 1, target = to or 2, recipes = { Testing = recipes }, stock = stock, prices = p,
            professions = {}, recipeItemPrices = {}, caps = {} })
        local ok, why = core.CheckBalance(plan)
        assert(ok, "the books do not balance: " .. tostring(why))
        local m = {}
        for _, row in ipairs(plan.materials) do m[row.id] = row end
        return plan, m
    end
    local function Says(plan) -- "B 15" : the recipes of the steps in order, and the sum
        local keys = {}
        for _, s in ipairs(plan.steps) do keys[#keys + 1] = s.recipe.key end
        return table.concat(keys, ",") .. " " .. tostring(plan.total)
    end
    local function Near(a, b) return type(a) == "number" and math.abs(a - b) < 1e-6 end

    -- Codex BATCH_PRIMARY_CHOICE: one point, both recipes give it for sure.
    -- A needs one X: 20c at the AH, or a batch of three from 30c of raw
    -- material. B needs an ingredient for 15c. A really costs 20c (one X
    -- bought) - not 10c, a third of a batch - so B is the one to take.
    local a = R("A", 10, 1, 2, { { 11, 1 } })
    local makeX = R("Make X", 11, 1, 1, { { 12, 1 } }, { made = 3 })
    local function B(copper) return R("B", 20, 1, 2, { { 21, 1 } }), copper end
    local plan, m = Plan({ a, (B(15)), makeX }, {}, { [11] = 20, [12] = 30, [21] = 15 })
    assert(Says(plan) == "B 15", ("a third of a batch of three beats 15c: %s"):format(Says(plan)))
    -- what the choice compared: B 15c, A 20c (each + 1, a new recipe x 1.08)
    local why = plan.steps[1].why
    assert(Near(why.score, 17.28) and why.other and why.other.key == "A" and Near(why.other.score, 22.68),
        ("the choice compared %s with %s (%s)"):format(tostring(why.score), tostring(why.other and why.other.score), tostring(why.other and why.other.key)))
    -- Codex BATCH_ONLY_B: B alone gives the same 15c
    plan = Plan({ (B(15)), makeX }, {}, { [11] = 20, [12] = 30, [21] = 15 })
    assert(Says(plan) == "B 15", "B alone: " .. Says(plan))
    -- B dearer than one X bought: A, with its X bought (not a batch for one)
    plan, m = Plan({ a, (B(25)), makeX }, {}, { [11] = 20, [12] = 30, [21] = 25 })
    assert(Says(plan) == "A 20" and m[11].missing == 1 and not m[11].madeFrom, "B at 25c: " .. Says(plan))
    -- where the batch IS the least costly way for the need, it counts in the
    -- choice: A needs three X per craft - one batch, 30c, against 60c bought
    plan, m = Plan({ R("A", 10, 1, 2, { { 11, 3 } }), (B(35)), makeX }, {}, { [11] = 20, [12] = 30, [21] = 35 })
    assert(Says(plan) == "A 30" and m[11].madeFrom and m[11].missing == 0, "a whole batch for three: " .. Says(plan))
    plan = Plan({ R("A", 10, 1, 2, { { 11, 3 } }), (B(25)), makeX }, {}, { [11] = 20, [12] = 30, [21] = 25 })
    assert(Says(plan) == "B 25", "a whole batch for three against 25c: " .. Says(plan))

    -- the four cases of round 1 (Codex B1), each with a second recipe for the
    -- point - its cost lies between what A really costs and what a wrong
    -- count would make of it
    -- RAW_STOCK: the raw material for A's X is in the bags: A costs nothing
    plan, m = Plan({ a, (B(5)), R("Make X", 11, 1, 1, { { 12, 1 } }) }, { [12] = 1 }, { [11] = 20, [12] = 50, [21] = 5 })
    assert(Says(plan) == "A 0" and m[11].madeFrom and m[12].covered, "raw stock for A's X, B at 5c: " .. Says(plan))
    -- INTERMEDIATE_FEE: making X takes 1c and a fee of 10000c: A is 20c (X
    -- bought) - B at 15c wins, B at 25c does not
    local function Fee(fee, bCost)
        return Plan({ a, (B(bCost)), R("Make X", 11, 1, 1, { { 12, 1 } }, { learn = "trainer", fee = fee }) }, {}, { [11] = 20, [12] = 1, [21] = bCost })
    end
    plan = Fee(10000, 15)
    assert(Says(plan) == "B 15", "a 10000c fee, B at 15c: " .. Says(plan))
    plan = Fee(10000, 25)
    assert(Says(plan) == "A 20" and plan.learn.trainer == 0, "a 10000c fee, B at 25c: " .. Says(plan))
    -- UNKNOWN_INTERMEDIATE_FEE: the same with a fee nobody knows - A is not
    -- 1c (the known part of making X)
    plan = Fee(nil, 15)
    assert(Says(plan) == "B 15", "an unknown fee, B at 15c: " .. Says(plan))
    plan = Fee(nil, 25)
    assert(Says(plan) == "A 20" and plan.notComparable == true and plan.openLearn == true, "an unknown fee, B at 25c: " .. Says(plan))
    -- BATCH_COST is the first case above.

    -- The number of crafts a point is expected to take is kept apart from
    -- the batch: at skill 2 A gives a point in 2 of 3 crafts (yellow from 1,
    -- grey at 4), so a point takes 1.5 crafts. One craft costs 20c (one X
    -- bought), two cost 30c (a batch for two X is less than 40c): 25c in
    -- between - not 15c, half a batch.
    local yellowA = R("A", 10, 1, 4, { { 11, 1 } }, { yellow = 1 })
    local function B2(copper) return R("B", 20, 1, 3, { { 21, 1 } }) end
    plan = Plan({ yellowA, B2(), makeX }, {}, { [11] = 20, [12] = 30, [21] = 22 }, 2, 3)
    assert(Says(plan) == "B 22", ("1.5 crafts of A against 22c: %s"):format(Says(plan)))
    why = plan.steps[1].why
    assert(Near(why.score, 24.84) and why.other and why.other.key == "A" and Near(why.other.score, 28.08),
        ("1.5 crafts: the choice compared %s with %s"):format(tostring(why.score), tostring(why.other and why.other.score)))
    -- B at 28c: A - and the step then counts whole crafts: two, with one
    -- batch for their two X (30c)
    plan, m = Plan({ yellowA, B2(), makeX }, {}, { [11] = 20, [12] = 30, [21] = 28 }, 2, 3)
    assert(Says(plan) == "A 30" and plan.steps[1].crafts == 2 and m[11].need == 2 and m[11].madeFrom, ("1.5 crafts of A against 28c: %s"):format(Says(plan)))

    -- the choice's own books count whole pieces too: two X in the bags make
    -- two points of A free, the third costs 20c - there B (5c) takes over
    plan, m = Plan({ R("A", 10, 1, 4, { { 11, 1 } }), R("B", 20, 1, 4, { { 21, 1 } }) }, { [11] = 2 }, { [11] = 20, [21] = 5 }, 1, 4)
    assert(Says(plan) == "A,B 5" and plan.steps[1].to == 3 and m[11].covered and m[21].missing == 1, "two X in stock, three points: " .. Says(plan))
    -- ... and whole crafts, as the plan's step will carry them out: the
    -- point at skill 2 takes 1.5 crafts of the yellow A - two crafts, two X,
    -- both from the bags. So none is left for the point at 3 (three crafts,
    -- 60c): B (55c) takes over. (Half an X left on the books would make A
    -- look like 50c there.)
    plan, m = Plan({ yellowA, R("B", 20, 1, 9, { { 21, 1 } }) }, { [11] = 2 }, { [11] = 20, [21] = 55 }, 2, 4)
    assert(Says(plan) == "A,B 55" and plan.steps[1].crafts == 2 and m[11].need == 2 and m[11].covered, "1.5 crafts carried out on the choice's books: " .. Says(plan))
    -- ... counted on over the points of one recipe, like the step: three
    -- points of an A that is yellow from 1 and grey at 31 take 1.03, 1.07
    -- and 1.11 crafts - 3.2 together, four crafts, not two for each point.
    -- With four X in the bags the third point still finds one (its second
    -- craft, should it come to that, would cost 20c): A stays below B (10c).
    -- (Rounded up point by point, the first two points would have used all
    -- four, and B would take the third.)
    plan, m = Plan({ R("A", 10, 1, 31, { { 11, 1 } }, { yellow = 1 }), R("B", 20, 1, 9, { { 21, 1 } }) }, { [11] = 4 }, { [11] = 20, [21] = 10 }, 2, 5)
    assert(Says(plan) == "A 0" and plan.steps[1].crafts == 4 and m[11].covered, "the crafts of three points in a row on the choice's books: " .. Says(plan))
end)
-- The calculation without its shortcuts, for the two steps below: the same
-- PlanCore.lua, loaded a second time with the switch off (a copy for the
-- tests - nothing of it reaches the addon). And a comparison of two plans as
-- whole objects: every step, amount, cost, flag and book entry, no tolerance.
local function PlanCoreWithoutShortcuts()
    local f = assert(io.open(ROOT .. "/PlanCore.lua", "rb"))
    local src = f:read("*a")
    f:close()
    local plain, count = src:gsub("\nlocal SHORTCUTS = true\n", "\nlocal SHORTCUTS = false\n")
    assert(count == 1, "PlanCore.lua has no switch for its shortcuts (or more than one)")
    -- nothing else decides about a shortcut: every use of the switch is a
    -- plain test of it
    local code = plain:gsub("%-%-[^\n]*", "")
    for line in code:gmatch("[^\n]*SHORTCUTS[^\n]*") do
        assert(line:find("^local SHORTCUTS = false") or line:find("if not SHORTCUTS then") or line:find("if SHORTCUTS then")
            or line:find("= SHORTCUTS and "), "the switch is used in another way: " .. line)
    end
    local other = {}
    assert(loadstring(plain, "=PlanCore(without shortcuts)"))("Gathercraft", other)
    -- a third copy that counts how often a shortcut was really taken (so a
    -- comparison that never used one proves nothing)
    PLAN_SHORTCUTS_TAKEN = { recalled = 0, repeated = 0, trials = 0 }
    local counted, n1, n2, n3 = src, 0, 0, 0
    counted, n1 = counted:gsub("        Redo%(ctx, L, e%.changes, 1%)\n", "        PLAN_SHORTCUTS_TAKEN.recalled = PLAN_SHORTCUTS_TAKEN.recalled + 1\n        Redo(ctx, L, e.changes, 1)\n")
    counted, n2 = counted:gsub("        if more > 0 then\n            local changes = Changes", "        if more > 0 then\n            PLAN_SHORTCUTS_TAKEN.repeated = PLAN_SHORTCUTS_TAKEN.repeated + more\n            local changes = Changes")
    counted, n3 = counted:gsub("        if e then return e%.acc end", "        if e then PLAN_SHORTCUTS_TAKEN.trials = PLAN_SHORTCUTS_TAKEN.trials + 1 return e.acc end")
    assert(n1 == 1 and n2 == 1 and n3 == 1, ("the places where a shortcut is taken were not found (%d, %d, %d)"):format(n1, n2, n3))
    local third = {}
    assert(loadstring(counted, "=PlanCore(counting)"))("Gathercraft", third)
    return other.PlanCore, third.PlanCore, PLAN_SHORTCUTS_TAKEN
end
local function SamePlan(a, b, path, seen)
    if type(a) ~= type(b) then return false, path .. ": " .. type(a) .. " / " .. type(b) end
    if type(a) ~= "table" then
        if a ~= b then return false, path .. ": " .. tostring(a) .. " / " .. tostring(b) end
        return true
    end
    if a == b then return true end
    seen = seen or {}
    if seen[a] == b then return true end
    seen[a] = b
    for k, v in pairs(a) do
        local ok, why = SamePlan(v, b[k], path .. "." .. tostring(k), seen)
        if not ok then return false, why end
    end
    for k in pairs(b) do
        if a[k] == nil then return false, path .. "." .. tostring(k) .. ": nil / " .. type(b[k]) end
    end
    return true
end

step("Skill plan 2.0: a shortcut never changes the plan - compared with the calculation without one (v0.2 r2 G2)", function()
    -- Codex round 2, R2-M2: what the calculation leaves out to be fast must
    -- come to exactly the plan the full calculation gives. The full
    -- calculation decides every need on its own and tries every batch one by
    -- one; the ways to get what is lacking are: buy it, make batch by batch
    -- and buy the rest, or make all of it in one go.
    local core = ns.PlanCore
    local function R(key, product, req, upto, mats, extra)
        local r = { prof = "Testing", key = key, name = key, product = product, made = 1, req = req, yellow = upto, grey = upto, reagents = {}, learn = "known" }
        for _, x in ipairs(mats) do r.reagents[#r.reagents + 1] = { id = x[1], n = x[2] } end
        for k, v in pairs(extra or {}) do r[k] = v end
        return r
    end
    local function Input(recipes, stock, prices, from, to)
        local p = {}
        for id, copper in pairs(prices) do p[id] = { status = "known", copper = copper } end
        return { prof = "Testing", skill = from or 1, target = to or 2, recipes = { Testing = recipes }, stock = stock, prices = p,
            professions = {}, recipeItemPrices = {}, caps = {} }
    end
    local function Says(plan) -- "A,B 15": the recipes of the steps in order, and the sum
        local keys = {}
        for _, s in ipairs(plan.steps) do keys[#keys + 1] = s.recipe.key end
        return table.concat(keys, ",") .. " " .. tostring(plan.total)
    end
    local function Extra(plan, key)
        for _, e in ipairs(plan.extras) do if e.recipe.key == key then return e.times end end
        return 0
    end

    -- ---- what the plan must be, as plain numbers (no second calculation)
    -- Four Y needed. A Y takes one X and one S; three S are in the bags (a
    -- fourth costs 5c). An X costs 20c, or two come from a batch for 30c.
    -- Batch by batch each Y buys its X (a batch for one X is no saving): 85c.
    -- All four in one go: two batches of X for the four of them, one S bought:
    -- 65c - the less costly way. (Lots of batches that were halved at the
    -- place where the S ran out gave a third number, 75c.)
    local plan = core.Compute(Input({ R("A", 10, 1, 2, { { 13, 4 } }), R("Make Y", 13, 1, 1, { { 11, 1 }, { 14, 1 } }),
        R("Make X", 11, 1, 1, { { 12, 1 } }, { made = 2 }) }, { [14] = 3 }, { [13] = 100, [11] = 20, [12] = 30, [14] = 5 }))
    assert(plan.total == 65 and Extra(plan, "Make Y") == 4 and Extra(plan, "Make X") == 2 and plan.ledger[12].bought == 2 and plan.ledger[14].bought == 1,
        ("four Y, the X in batches of two, three S in stock: %s copper"):format(tostring(plan.total)))
    assert(core.CheckBalance(plan))
    -- Codex' smallest case: A takes twelve X; an X costs 460c or is made from
    -- three raw pieces (220c each), 26 of them are there. Nine X made (27
    -- pieces, one bought: 220c), three X bought (1380c): 1600c - below B's
    -- 1605c. The tenth X would take 660c of raw material: bought.
    local function Smallest(rawStock, bCost)
        local list = { R("A", 10, 1, 2, { { 11, 12 } }), R("Make X", 11, 1, 1, { { 12, 3 } }) }
        if bCost then list[#list + 1] = R("B", 20, 1, 2, { { 21, 1 } }) end
        return Input(list, { [12] = rawStock }, { [11] = 460, [12] = 220, [21] = bCost or 1 })
    end
    plan = core.Compute(Smallest(26, 1605))
    assert(Says(plan) == "A 1600" and Extra(plan, "Make X") == 9 and plan.ledger[11].bought == 3 and plan.ledger[12].bought == 1, "A at 1600c against B at 1605c: " .. Says(plan))
    plan = core.Compute(Smallest(26, 1595))
    assert(Says(plan) == "B 1595", "A at 1600c against B at 1595c: " .. Says(plan))
    -- the same need with other counts of raw material - also ones that are
    -- no whole number of batches: every three pieces make an X for nothing,
    -- one or two left over make the next X cost 440c or 220c (below 460c),
    -- the rest is bought
    for _, rawStock in ipairs({ 0, 1, 2, 3, 4, 5, 6, 7, 24, 25, 26, 27, 28, 29, 33, 34, 35, 36, 37, 40 }) do
        local free = math.min(12, math.floor(rawStock / 3))
        local left, want = rawStock - free * 3, 0
        if free < 12 then
            want = (12 - free) * 460
            if left > 0 then want = (3 - left) * 220 + (12 - free - 1) * 460 end
        end
        plan = core.Compute(Smallest(rawStock))
        assert(plan.total == want and core.CheckBalance(plan), ("%d raw pieces for twelve X: %s copper, want %d"):format(rawStock, tostring(plan.total), want))
    end

    -- ---- every plan below: with the shortcuts and without, the same object
    local reference, counting, taken = PlanCoreWithoutShortcuts()
    local compared = 0
    local function Both(input, what)
        local a, b = core.Compute(input), reference.Compute(input)
        local ok, why = SamePlan(a, b, "plan")
        assert(ok, ("%s: with the shortcuts the plan is another one (%s)"):format(what, tostring(why)))
        local okA, whyA = core.CheckBalance(a)
        assert(okA, what .. ": the books do not balance: " .. tostring(whyA))
        counting.Compute(input)
        compared = compared + 1
        return a
    end
    -- the cases above
    Both(Smallest(26, 1605), "Codex' smallest case")
    for rawStock = 0, 40 do Both(Smallest(rawStock, 1605), rawStock .. " raw pieces") end
    for _, bCost in ipairs({ 200, 900, 1595, 1600, 1601, 5000 }) do Both(Smallest(26, bCost), "B at " .. bCost) end

    -- One case for each thing a shortcut rests on; each of them gives another
    -- plan when that one thing is left out (the counter-probes do so).
    -- a batch that learns a recipe is not the batch after it: four Y, each
    -- from an X (its recipe costs 6c to learn, once) and an S (three are
    -- there, a fourth costs 100c): three Y made for 1c each and the fee, the
    -- fourth bought for 30c - 33c and 6c, below Q's 45c
    plan = Both(Input({ R("P", 10, 1, 2, { { 13, 4 } }), R("Q", 20, 1, 2, { { 21, 1 } }), R("Make Y", 13, 1, 1, { { 11, 1 }, { 14, 1 } }),
        R("Make X", 11, 1, 1, { { 12, 1 } }, { learn = "trainer", fee = 6 }) }, { [14] = 3 }, { [13] = 30, [11] = 50, [12] = 1, [14] = 100, [21] = 45 }), "a fee inside the first batch")
    assert(Says(plan) == "P 33" and plan.learn.fees == 6 and Extra(plan, "Make Y") == 3, "a fee inside the first batch: " .. Says(plan))
    -- what a recipe's share of a one-time cost is belongs to what was worked
    -- out: A1 gives one point (the 100c fee of X counts whole: X is bought),
    -- B9 gives many (a tenth of it: X is made)
    plan = Both(Input({ R("A1", 10, 1, 2, { { 11, 1 } }), R("B9", 20, 1, 30, { { 11, 1 } }),
        R("Make X", 11, 1, 1, { { 12, 1 } }, { learn = "trainer", fee = 100 }) }, {}, { [11] = 20, [12] = 1 }, 1, 11), "one fee, two shares")
    assert(Says(plan) == "B9 10" and plan.learn.fees == 100 and Extra(plan, "Make X") == 10, "one fee, two shares: " .. Says(plan))
    -- what was worked out for an item is not used where one of the things it
    -- looked at is being made around it: B from A is fine on its own, not
    -- inside the making of A
    -- (P takes a B and two A: 10c and 20c. Q takes four A: 40c bought - not
    -- 20c, made from two B that would be made from A)
    plan = Both(Input({ R("P", 10, 1, 2, { { 11, 1 }, { 12, 2 } }), R("Q", 20, 1, 2, { { 12, 4 } }), R("Make A", 12, 1, 1, { { 11, 1 } }, { made = 2 }),
        R("Make B", 11, 1, 1, { { 12, 1 } }), R("Also B", 11, 1, 1, { { 13, 3 } }) }, {}, { [11] = 100, [12] = 10, [13] = 10 }), "a chain back to itself, the item first")
    assert(Says(plan) == "P 30" and Extra(plan, "Make A") == 0, "B from A, then A: " .. Says(plan))
    -- ... and what was worked out INSIDE such a chain is not kept for later:
    -- A is bought while B is being made from it, but made (from B) on its own
    plan = Both(Input({ R("P", 10, 1, 2, { { 11, 1 }, { 12, 1 } }), R("Make A", 12, 1, 1, { { 11, 1 } }), R("Make B", 11, 1, 1, { { 12, 1 } }),
        R("Also B", 11, 1, 1, { { 13, 3 } }) }, {}, { [11] = 100, [12] = 100, [13] = 10 }), "a chain back to itself, inside first")
    assert(plan.total == 60 and Extra(plan, "Make A") == 1 and Extra(plan, "Also B") == 2, "A inside the making of B, then on its own: " .. Says(plan))
    -- what was worked out before is used inside a batch: the batch rests on
    -- what that rested on (two raw pieces left for five Y)
    plan = Both(Input({ R("P", 10, 1, 2, { { 13, 1 } }), R("Q", 20, 2, 3, { { 13, 5 } }), R("Make Y", 13, 1, 1, { { 11, 1 } }), R("Make X", 11, 1, 1, { { 12, 1 } }) },
        { [12] = 3 }, { [13] = 200, [11] = 50, [12] = 40 }, 1, 3), "remembered inside a batch")
    assert(Says(plan) == "P,Q 120" and plan.ledger[12].bought == 3 and plan.ledger[12].rest == 0, "three raw pieces for six Y: " .. Says(plan))
    -- a count that did not cover the need is exact: two R are one too few for
    -- P2; once P1 has made the third, P2 costs nothing
    plan = Both(Input({ R("P1", 12, 1, 3, { { 21, 1 } }), R("P2", 30, 1, 3, { { 12, 3 } }) }, { [12] = 2 }, { [12] = 40, [21] = 10 }, 1, 3), "a count that did not cover")
    assert(Says(plan) == "P1,P2 10", "two R, a third from the first step: " .. Says(plan))
    -- the last batch replaces fewer pieces than a whole one: seven X in
    -- batches of three (45c) against 20c a piece - two batches, one X bought
    plan = Both(Input({ R("P", 10, 1, 2, { { 11, 7 } }), R("Make X", 11, 1, 1, { { 12, 1 } }, { made = 3 }) }, {}, { [11] = 20, [12] = 45 }), "a last batch for one piece")
    assert(plan.total == 110 and Extra(plan, "Make X") == 2 and plan.ledger[11].bought == 1, "seven X in batches of three: " .. Says(plan))
    -- a recipe that can be used from a higher skill on: what was worked out
    -- below that skill does not hold from there (Codex' UNLOCK_WITHIN_SEGMENT)
    plan = Both(Input({ R("A", 10, 1, 9, { { 11, 1 } }), R("Make X", 11, 5, 5, { { 12, 1 } }) }, {}, { [11] = 1000, [12] = 1 }, 1, 9), "a recipe that unlocks at 5")
    assert(plan.total == 4004, "a recipe that unlocks at 5: " .. Says(plan))
    -- stock that covers some batches and then runs out, three levels down,
    -- with a yellow recipe on top (1.5 crafts a point)
    for _, rawStock in ipairs({ 0, 5, 17, 18, 19, 40, 41, 200 }) do
        Both(Input({ R("P", 10, 1, 8, { { 13, 2 }, { 16, 1 } }, { yellow = 2 }), R("Q", 20, 1, 8, { { 21, 3 } }), R("Make Y", 13, 1, 1, { { 11, 3 } }),
            R("Make X", 11, 1, 1, { { 12, 2 }, { 15, 1 } }), R("Make Z", 16, 1, 1, { { 12, 1 } }, { made = 2 }) },
            { [12] = rawStock, [15] = 7, [11] = 2 }, { [13] = 900, [11] = 250, [12] = 30, [15] = 12, [16] = 25, [21] = 150 }, 1, 8), rawStock .. " raw pieces, three levels")
    end

    -- ---- many small made-up professions (the same on every machine): chains
    -- of intermediates, batches of several pieces, fees, unknown prices and
    -- counts, stock at every level, a second profession, chains back to
    -- themselves
    local state = 20261110
    local function rnd(n)
        state = (state * 1103515245 + 12345) % 2147483648
        return math.floor(state / 65536) % n + 1
    end
    local function chance(percent) return rnd(100) <= percent end
    local function Case()
        local nRaw, nMid = 2 + rnd(4), rnd(5)
        local raw, mid = {}, {}
        for i = 1, nRaw do raw[i] = 100 + i end
        for i = 1, nMid do mid[i] = 200 + i end
        local recipes, other = {}, {}
        local function Mats(level, most)
            local list, used = {}, {}
            for _ = 1, rnd(most) do
                local id
                if level > 1 and chance(60) then id = mid[chance(8) and rnd(nMid) or rnd(level - 1)] else id = raw[rnd(nRaw)] end
                if not used[id] then
                    used[id] = true
                    list[#list + 1] = { id = id, n = rnd(4) }
                end
            end
            return list
        end
        for i = 1, nMid do
            local made = ({ 1, 1, 1, 1, 2, 3, 5, 1.5 })[rnd(8)]
            local r = { key = "Make " .. i, name = "Make " .. i, product = mid[i], made = made, madeVaries = made == 1.5 or nil,
                req = chance(70) and 1 or rnd(12), yellow = 1, grey = 1, reagents = Mats(i, 3) }
            if chance(25) then
                r.prof, r.learn = "Other", chance(80) and "known" or nil
                other[#other + 1] = r
            else
                r.prof = "Testing"
                local how = rnd(10)
                r.learn = how <= 6 and "known" or how <= 8 and "trainer" or how == 9 and "vendor" or nil
                if r.learn == "trainer" and chance(80) then r.fee = rnd(3) == 1 and 0 or rnd(300) end
                if r.learn == "vendor" then r.recipeItem = 900 + i end
                if chance(30) then r.yellow, r.grey = r.req + rnd(6), r.req + 6 + rnd(8) end
                recipes[#recipes + 1] = r
            end
            if chance(10) and i > 1 then
                recipes[#recipes + 1] = { prof = "Testing", key = "Also " .. i, name = "Also " .. i, product = mid[i], made = rnd(2), req = 1, yellow = 1, grey = 1,
                    reagents = Mats(i, 2), learn = "known" }
            end
        end
        for i = 1, 2 + rnd(4) do
            local req = rnd(8)
            local yellow = req + rnd(8)
            local r = { prof = "Testing", key = "Point " .. i, name = "Point " .. i, product = chance(50) and (300 + i) or 0, made = 1,
                req = req, yellow = yellow, grey = yellow + (chance(40) and 0 or rnd(10)), reagents = Mats(nMid + 1, 3) }
            local how = rnd(10)
            r.learn = how <= 6 and "known" or how <= 8 and "trainer" or "vendor"
            if r.learn == "trainer" and chance(85) then r.fee = rnd(500) end
            if r.learn == "vendor" then r.recipeItem = 950 + i end
            if chance(15) and nMid > 0 then r.product = mid[rnd(nMid)] end
            recipes[#recipes + 1] = r
        end
        local stock, prices, recipeItemPrices = {}, {}, {}
        local function Fill(ids, stockChance, most)
            for _, id in ipairs(ids) do
                if chance(stockChance) then stock[id] = rnd(most) end
                if chance(4) then stock[id] = { unknown = true } end
                local kind = rnd(20)
                if kind <= 16 then
                    prices[id] = { status = "known", copper = rnd(60) * (chance(50) and 1 or 10) }
                elseif kind <= 18 then
                    prices[id] = { status = "estimated", copper = rnd(60) * 5 }
                end
            end
        end
        Fill(raw, 45, 30)
        Fill(mid, 30, 12)
        for i = 1, 60 do
            if chance(70) then recipeItemPrices[900 + i] = rnd(400) end
        end
        local skill = rnd(6)
        local input = { prof = "Testing", skill = skill, target = skill + rnd(18), recipes = { Testing = recipes }, stock = stock, prices = prices,
            professions = { Testing = { rank = skill } }, recipeItemPrices = recipeItemPrices, caps = { 10, 20 }, maxRank = chance(50) and 10 or nil }
        if #other > 0 and chance(85) then
            input.recipes.Other = other
            input.professions.Other = { rank = rnd(14) }
        end
        return input
    end
    for case = 1, 400 do Both(Case(), "made-up profession " .. case) end

    -- the shortcuts were really taken in all that
    assert(taken.recalled > 500 and taken.repeated > 200 and taken.trials > 500,
        ("the comparison hardly used a shortcut: remembered %d, batches repeated %d, recipes remembered %d"):format(taken.recalled, taken.repeated, taken.trials))
    assert(compared > 450, "plans compared: " .. compared)
    PLAN_SHORTCUTS_TAKEN = nil
end)
step("Skill plan 2.0: the plans of Codex' matrix, with the shortcuts and without (v0.2 r2 G2)", function()
    -- Codex round 2, R2-M2: the matrix that found four differing plans - the
    -- shipped recipes of nine professions, four states of stock and
    -- knowledge, three states of the prices, two targets: 216 plans. Each is
    -- worked out with the shortcuts and without, and compared as a whole
    -- object. The calculation without shortcuts takes minutes for all of
    -- them, and the plans do not depend on the client language: all 216 run
    -- as enUS, the other languages run the part where the old shortcuts went
    -- wrong (Blacksmithing with much stock and every recipe) and one plan of
    -- each other state. GC_PLAN_MATRIX=full / part sets it by hand.
    local reference = PlanCoreWithoutShortcuts()
    local core = ns.PlanCore
    local d = ns.CraftData
    local saved = { have = d.Have, cost = d.ReagentCost, known = d.Known, rank = ns.ProfessionRank }
    local profs = { "Alchemy", "Blacksmithing", "Enchanting", "Engineering", "Leatherworking", "Tailoring", "Cooking", "First Aid", "Mining" }
    local all = {}
    for _, p in ipairs(profs) do all[p] = d.AllRecipes(p) end
    local function Input(prof, mode, prices, target)
        -- mode 1: new, nothing known, no stock; 2: skill 150, the recipes up
        -- to it known, Mining next to it, 15 of every third item; 3: the
        -- same at 225; 4: every profession at 300, every recipe known, 50 of
        -- four items in five.  prices 1: none; 2: all known; 3: every fourth
        -- item without one, every seventh an estimate
        local skill = mode == 2 and 150 or mode == 3 and 225 or 1
        ns.ProfessionRank = function(q)
            if mode == 4 or q == prof then return mode == 4 and 300 or skill, 300 elseif mode >= 2 and q == "Mining" then return 300, 300 end
        end
        d.Known = function(q)
            local t = {}
            for key, packed in pairs(all[q] or {}) do
                local _, _, req = d.Unpack(packed)
                if mode == 4 or (mode >= 2 and (req or 0) <= skill) then t[key] = packed end
            end
            return t
        end
        d.Have = function(id)
            if mode == 4 then return id % 5 ~= 0 and 50 or 0 elseif mode >= 2 then return id % 3 == 0 and 15 or 0 end
            return 0
        end
        d.ReagentCost = function(id)
            if prices == 1 or prices == 3 and id % 4 == 0 then return nil end
            return (id % 97 + 1) * 10, "review", prices == 3 and id % 7 == 0
        end
        return ns.SkillPlanSnapshot(prof, skill, target)
    end
    local how = os.getenv("GC_PLAN_MATRIX")
    local full = how == "full" or (how ~= "part" and LOCALE == "enUS")
    local function Wanted(mode, prices, prof, target)
        if full then return true end
        if mode == 4 and prof == "Blacksmithing" and prices >= 2 then return true end -- (the four plans that differed)
        return prices == 2 and target == 250 and ((mode == 1 and prof == "Tailoring") or (mode == 2 and prof == "Leatherworking") or (mode == 3 and prof == "Alchemy"))
    end
    local compared, steps, firstDiff = 0, 0, nil
    local ok, err = pcall(function()
        for mode = 1, 4 do
            for prices = 1, 3 do
                for _, prof in ipairs(profs) do
                    for _, target in ipairs({ 250, 300 }) do
                        if Wanted(mode, prices, prof, target) then
                            local input = Input(prof, mode, prices, target)
                            -- (the shortcut code runs faster without the JIT compiler, the full calculation with it)
                            if jit then jit.off() end
                            local a = core.Compute(input)
                            if jit then jit.on() end
                            local b = reference.Compute(input)
                            local same, why = SamePlan(a, b, prof)
                            if not same and not firstDiff then firstDiff = ("state %d, prices %d, %s to %d: %s"):format(mode, prices, prof, target, tostring(why)) end
                            assert(core.CheckBalance(a) and reference.CheckBalance(b), "the books do not balance")
                            compared, steps = compared + 1, steps + #a.steps
                        end
                    end
                end
            end
        end
    end)
    if jit then jit.on() end
    d.Have, d.ReagentCost, d.Known, ns.ProfessionRank = saved.have, saved.cost, saved.known, saved.rank
    assert(ok, err)
    assert(not firstDiff, "with the shortcuts a plan of the matrix is another one - " .. tostring(firstDiff))
    assert(compared == (full and 216 or 7) and steps > compared, ("plans of the matrix compared: %d, with %d steps"):format(compared, steps))
end)
step("Skill plan 2.0: skill points of extra crafts that are not counted make the plan an estimate too (v0.2 r2 G5)", function()
    -- Codex round 2, R2-N1 (the case SUPPLEMENT): two certain crafts of A
    -- need two X; an X is made by a recipe that still gives a point now and
    -- then (4 in 100). Those two extra crafts are counted with their
    -- materials and their output, but not towards the skill - never a part
    -- of a point (Sven, 10.11.2026). So the plan asks for rather too much:
    -- that is a planning estimate, and the plan, its result and the window
    -- say so - like they do for a mean number of crafts.
    local core, d = ns.PlanCore, ns.CraftData
    local L = ns.L
    local function R(key, product, req, yellow, grey, mats, extra)
        local r = { prof = "Testing", key = key, name = key, product = product, made = 1, req = req, yellow = yellow, grey = grey, reagents = {}, learn = "known" }
        for _, x in ipairs(mats) do r.reagents[#r.reagents + 1] = { id = x[1], n = x[2] } end
        for k, v in pairs(extra or {}) do r[k] = v end
        return r
    end
    local function Input(makeX)
        return { prof = "Testing", skill = 97, target = 99, recipes = { Testing = { R("A", 9840, 97, 99, 99, { { 9841, 1 } }, { name = "Recipe A" }), makeX } }, stock = {},
            prices = { [9841] = { status = "known", copper = 1000, source = "AH scan" }, [9842] = { status = "known", copper = 1, source = "AH scan" } },
            professions = {}, recipeItemPrices = {}, caps = {}, nodes = {} }
    end
    local function Extra(plan, key)
        for _, e in ipairs(plan.extras) do if e.recipe.key == key then return e.times end end
        return 0
    end
    -- Codex SUPPLEMENT: Make X is green-ish at 97 (yellow from 1, grey at 101)
    local supplement = function() return Input(R("Make X", 9841, 1, 1, 101, { { 9842, 1 } }, { name = "Recipe X" })) end
    local plan = core.Compute(supplement())
    assert(#plan.steps == 1 and plan.steps[1].crafts == 2 and Extra(plan, "Make X") == 2 and plan.total == 2 and plan.status == "ok", "the plan of SUPPLEMENT changed")
    assert(plan.estimate.crafts == false and plan.estimate.output == false, "certain crafts with a fixed output are called a mean")
    assert(plan.estimate.skill == true, "skill points of extra crafts are not counted, and the plan does not say so")
    assert(plan.steps[1].extraSkill == true, "the step the extra crafts were made for is not marked")
    local result = core.Result(plan)
    assert(result.estimate.skill == true and result.estimate.crafts == false and result.estimate.output == false, "the result does not pass it on")
    -- an extra craft that gives no point any more (grey): nothing is left out
    plan = core.Compute(Input(R("Make X", 9841, 1, 1, 50, { { 9842, 1 } })))
    assert(Extra(plan, "Make X") == 2 and plan.estimate.skill == false and not plan.steps[1].extraSkill and core.Result(plan).estimate.skill == false,
        "extra crafts of a grey recipe are called an estimate")
    -- an extra craft that gives a point for sure (orange) is a step of its
    -- own and counted: nothing is left out
    plan = core.Compute(Input(R("Make X", 9841, 1, 200, 200, { { 9842, 1 } })))
    assert(plan.steps[1].forMaterials and plan.estimate.skill == false, "extra crafts that are counted as steps are called not counted")
    -- nothing made extra: no such mark
    plan = core.Compute(Input(R("Make X", 9841, 1, 1, 101, { { 9842, 2000 } })))
    assert(Extra(plan, "Make X") == 0 and plan.estimate.skill == false, "a plan without extra crafts is marked")
    -- an invalid plan has the field too
    assert(core.Compute({}).estimate.skill == false, "no estimate.skill on an invalid plan")

    -- the window: the line under the materials and the materials' tooltips
    local saved = { rank = ns.ProfessionRank, have = d.Have, known = d.Known, price = ns.GetPrice, compute = core.Compute, targets = ns.db.planTargets }
    local win
    local ok, err = pcall(function()
        local rank = 96
        ns.ProfessionRank = function(p) if p == "Alchemy" then return rank, 150 end end
        d.Have = function() return 0 end
        d.Known = function() return {} end
        ns.GetPrice = function() return 10, "AH scan" end
        ns.db.planTargets = nil
        local function Show(input)
            core.Compute = function(real)
                for _, r in ipairs(input.recipes.Testing) do r.prof = real.prof end
                input.prof, input.recipes = real.prof, { [real.prof] = input.recipes.Testing }
                return saved.compute(input)
            end
            rank = rank + 1 -- (a new state, so the plan is made again)
            ns.ShowSkillPlan("Alchemy") advance(1)
            win = _G.GathercraftSkillPlan
        end
        local function Rows()
            local list = {}
            for _, o in ipairs(allFrames) do
                if o.left and o.mid and o.right and o:IsShown() then list[#list + 1] = o end
            end
            return list
        end
        local function Count(text)
            local n = 0
            for _, row in ipairs(Rows()) do if row.left:GetText() == text then n = n + 1 end end
            return n
        end
        local function Tip(row)
            local lines = {}
            if row and row.tip then row.tip({ AddLine = function(_, t) lines[#lines + 1] = t end }) end
            return table.concat(lines, "\n")
        end
        local function Mat(id)
            local name = ns.ItemName and ns.ItemName(id) or (L["item "] .. id)
            for _, row in ipairs(Rows()) do if row.left:GetText() == name then return row end end
        end
        local ESTIMATE = L["Planning estimate from the average number of crafts per step - what you really need varies."]
        Show(supplement())
        assert(Count(ESTIMATE) == 1, ("the window calls SUPPLEMENT a planning estimate %d times, want once"):format(Count(ESTIMATE)))
        local raw, made = Mat(9842), Mat(9841)
        assert(raw and made, "the materials of SUPPLEMENT are not shown")
        assert(Tip(raw):find(ESTIMATE, 1, true) and Tip(made):find(ESTIMATE, 1, true), "a material's tooltip does not say that its amount is an estimate")
        local shown = ns.SkillPlanResult()
        assert(shown and shown.estimate.skill == true and shown.estimate.crafts == false and shown.estimate.output == false, "the result of the shown plan does not say it")
        -- the grey one: no such line, no such tooltip
        Show(Input(R("Make X", 9841, 1, 1, 50, { { 9842, 1 } }, { name = "Recipe X" })))
        assert(Count(ESTIMATE) == 0 and Mat(9842) and not Tip(Mat(9842)):find(ESTIMATE, 1, true), "a plan with nothing estimated is called an estimate")
        assert(ns.SkillPlanResult().estimate.skill == false, "the result of a plan with nothing estimated says estimate")
    end)
    ns.ProfessionRank, d.Have, d.Known, ns.GetPrice, core.Compute, ns.db.planTargets = saved.rank, saved.have, saved.known, saved.price, saved.compute, saved.targets
    if win then win:Hide() end
    if not ok then error(err, 0) end
end)
step("Skill plan 2.0: a skill seen last is a preview - never your skill now, never \"done\" (v0.2 r2 G3)", function()
    -- Codex round 2, R2-M3 (concept 5): when the skill list hides your skill,
    -- the reader falls back to the skill that was seen last. That is no
    -- current skill: the window and the result say "last seen", there is no
    -- "done" and nothing to rely on. And a skill that was read live is kept
    -- as the one seen last, so an older, lower one from the profession window
    -- never takes its place. Through the real reader (ns.ProfessionRank) and
    -- the place it keeps the skill in, not a stand-in.
    local L, core, d = ns.L, ns.PlanCore, ns.CraftData
    local saved = { lines = GetNumSkillLines, line = GetSkillLineInfo, secret = issecretvalue, recipes = ns.db.recipes, targets = ns.db.planTargets,
        have = d.Have, known = d.Known, all = d.AllRecipes }
    local win
    local ok, err = pcall(function()
        ns.db.recipes = {}
        ns.db.planTargets = nil
        d.Have = function() return 0 end
        local SECRET = newproxy(true)
        issecretvalue = function(v) return rawequal(v, SECRET) end
        local rank, maxRank, name = 25, 75, "Tailoring"
        GetNumSkillLines = function() return 3 end
        GetSkillLineInfo = function(i)
            if i == 1 then return "Professions", true, true, 0, 0, 0, 0 end
            if i == 2 then return name, false, true, rank, 0, 0, maxRank end
            return "Secondary Skills", true, true, 0, 0, 0, 0
        end
        local function Rows()
            local list = {}
            for _, o in ipairs(allFrames) do
                if o.left and o.mid and o.right and o:IsShown() then list[#list + 1] = o end
            end
            return list
        end
        local function Shows(text)
            for _, row in ipairs(Rows()) do
                if row.left:GetText() == text then return row end
            end
        end
        local function Header(text)
            for _, o in ipairs(allFrames) do
                if o.__kind == "FontString" and o.__parent == win and o:GetText() == text then return o end
            end
        end
        local function Bottom(y) -- the sum (42) and the note below it (24), by their place
            for _, o in ipairs(allFrames) do
                local at = o.__parent == win and o.__kind == "FontString" and o.__pts and o.__pts.BOTTOMLEFT
                if at and at[2] == y then return o end
            end
        end
        local function Total() return Bottom(42) end
        local function Note() return Bottom(24) end
        local function Px(t) -- (an estimate: 6 px a letter, 11 px a CJK sign; colour codes take no room)
            t = (t or ""):gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", "")
            local px = 0
            for ch in t:gmatch("[%z\1-\127\194-\244][\128-\191]*") do px = px + (#ch >= 3 and 11 or 6) end
            return px
        end
        local function Refresh() ns.RefreshSkillPlan() advance(1) end
        local DONE = (L["Done: you have reached your target (%d)."]):format(75)
        local AMOUNTS = L["Preview - the amounts below are for the skill seen last, not for your skill now."]
        local function Seen(ago) return (L["Your skill cannot be read right now. This is a preview from the skill seen last (%s): open your profession window to update it."]):format(ago) end
        local SEEN_ONCE = L["Your skill cannot be read right now. This is a preview from the skill seen last: open your profession window to update it."]
        local SUM_NOTE = L["A preview from the skill seen last, not from your skill now."]

        -- ---- read now: "current", and nothing is kept for a profession
        -- whose window was never read
        local r, m, source = ns.ProfessionRank("Tailoring")
        assert(r == 25 and m == 75 and source == nil, "the reader does not give the skill read now")
        local state, sr, sm, _, ssource = ns.SkillPlanSkillState("Tailoring")
        assert(state == "learned" and sr == 25 and sm == 75 and ssource == "current", "a skill read now is not called current")
        local mine
        for _, char in pairs(ns.db.recipes) do mine = char end
        assert(mine and mine.Tailoring == nil, "a profession record was made up to keep a skill in")
        ns.ShowSkillPlan("Tailoring") advance(1)
        win = _G.GathercraftSkillPlan
        assert(ns.SkillPlanSetTarget(75), "test setup: the target")
        advance(1)
        local res = ns.SkillPlanResult()
        assert(res.from == 25 and res.status == "ok" and res.skillSource == "current" and res.reliable == true and res.skillSeenAt == nil, "the result of a plan from the skill read now")
        local revision = res.revision

        -- ---- the profession window was read once, long ago, at 25 (as the
        -- game left it: no time kept with it)
        mine.Tailoring = { rank = 25, list = { ["Bolt of Linen Cloth"] = "2996:1:1:1|2589:2" } }
        -- now the skill list reads 75: read live - and kept as the one seen last
        rank = 75
        local before = time()
        Refresh()
        res = ns.SkillPlanResult()
        assert(res.from == 75 and res.status == "done" and res.reliable == true, ("live 75 of 75: %s from %s"):format(tostring(res.status), tostring(res.from)))
        assert(Shows(DONE) and Header((L["Your skill: %d / %d"]):format(75, 75)), "live 75 of 75 is not shown as done")
        assert(mine.Tailoring.rank == 75 and type(mine.Tailoring.rankAt) == "number" and mine.Tailoring.rankAt >= before,
            ("a skill read live is not kept as the one seen last (%s)"):format(tostring(mine.Tailoring.rank)))
        assert(next(mine.Tailoring.list), "the recipes of the profession window are gone")
        -- the list hides the skill (Codex STALE_25): not back to 25, and not "done"
        rank = SECRET
        r, m, source = ns.ProfessionRank("Tailoring")
        assert(r == 75 and m == nil and source == "lastSeen", ("the reader gives %s (%s) for a hidden skill after a live 75"):format(tostring(r), tostring(source)))
        state, sr, sm, _, ssource = ns.SkillPlanSkillState("Tailoring")
        assert(state == "learned" and sr == 75 and ssource == "lastSeen", "a skill seen last is not told apart from a current one")
        Refresh()
        res = ns.SkillPlanResult()
        assert(res.from == 75, ("an older cache undercuts the skill that was read live: the plan is from %s"):format(tostring(res.from)))
        assert(res.status == "preview" and res.skillSource == "lastSeen" and res.reliable == false and res.complete == false,
            ("a plan from a skill seen last: status %s, source %s, reliable %s"):format(tostring(res.status), tostring(res.skillSource), tostring(res.reliable)))
        assert(res.skillSeenAt == mine.Tailoring.rankAt, "the result does not say when the skill was seen")
        assert(not Shows(DONE), "\"Done\" from a skill that is not read now")
        assert(Header((L["Skill last seen: %d"]):format(75)) and not Header((L["Your skill: %d"]):format(75)) and not Header((L["Your skill: %d / %d"]):format(75, 75)),
            "a skill seen last is shown as your skill")
        assert(Shows(Seen(L["just now"])), "the window does not say that this is a preview from the skill seen last")
        for _, row in ipairs(Rows()) do assert(not row.check:IsShown(), "a tick in a preview of a reached target") end
        -- two hours later it still cannot be read: the age is said
        advance(7200)
        Refresh()
        assert(Shows(Seen(2 .. L[" h ago"])), "the age of the skill seen last is not said")
        -- readable again (Codex RESTORED_75)
        rank = 75
        Refresh()
        res = ns.SkillPlanResult()
        assert(res.from == 75 and res.status == "done" and res.skillSource == "current" and res.reliable == true and Shows(DONE), "readable again: not back to the plan from the skill read now")
        assert(not Shows(Seen(L["just now"])) and not Shows(SEEN_ONCE) and not Header((L["Skill last seen: %d"]):format(75)), "readable again: still called last seen")

        -- ---- Codex' control: 75 kept from the profession window (no time
        -- with it), the skill never readable - no "done" from that either
        mine.Tailoring = { rank = 75, list = { ["Bolt of Linen Cloth"] = "2996:1:1:1|2589:2" } }
        rank = SECRET
        state, sr, sm, _, ssource = ns.SkillPlanSkillState("Tailoring")
        assert(state == "learned" and sr == 75 and ssource == "lastSeen", "a kept skill with a hidden line: " .. tostring(state))
        Refresh()
        res = ns.SkillPlanResult()
        assert(res.status == "preview" and res.reliable == false and res.skillSeenAt == nil and not Shows(DONE), "a kept 75 with a hidden skill is \"done\"")
        assert(Shows(SEEN_ONCE), "a skill seen at an unknown time: the window does not say that it is a preview")

        -- ---- a preview with something to do: 25 seen last, the target 75
        -- (the maximum is hidden all along, so that nothing but "read now"
        -- against "seen last" tells the two states apart)
        mine.Tailoring = { rank = 25, rankAt = time() - 600, list = { ["Bolt of Linen Cloth"] = "2996:1:1:1|2589:2" } }
        rank, maxRank = 25, SECRET
        Refresh()
        res = ns.SkillPlanResult()
        assert(res.status == "ok" and res.from == 25 and res.reliable == true and res.skillSource == "current", "test setup: the plan from a live 25")
        revision = res.revision
        local liveTotal = Total():GetText()
        rank = SECRET
        Refresh()
        res = ns.SkillPlanResult()
        assert(res.from == 25 and res.status == "preview" and res.reliable == false and res.revision > revision, "the same skill, now only seen last, is not a new state")
        local missing = 0
        for _, item in pairs(res.items) do missing = missing + item.missing end
        assert(missing > 0, "test setup: the preview has nothing to buy")
        assert(Shows(L["Steps"]) and Shows(AMOUNTS), "the materials of a preview are not marked as a preview")
        -- the sum: the line below it says what it is (the sum line itself has
        -- no room for more in most languages)
        assert(Note():GetText() == SUM_NOTE, "the sum of a preview is not marked: " .. tostring(Note():GetText()))
        assert(Px(SUM_NOTE) <= 500, ("%s: the note under the sum of a preview needs %d px of 500"):format(LOCALE, Px(SUM_NOTE)))
        assert(Total():GetText() == liveTotal, "the sum of the preview is another one than that of the same plan read live")
        local head = Header((L["Skill last seen: %d"]):format(25))
        assert(head and Px(head:GetText()) <= 200 and Px((L["Skill last seen: %d"]):format(300)) <= 200, LOCALE .. ": \"Skill last seen\" does not fit its 200 px")
        -- a live plan has no such marks
        rank = 25
        Refresh()
        assert(not Shows(AMOUNTS) and Note():GetText() ~= SUM_NOTE, "a plan from the skill read now is marked as a preview")
        maxRank = 75

        -- ---- proof beats what was seen: the whole list can be read and the
        -- profession is not in it - not learned (any more), whatever was kept
        name = "Herbalism"
        state = ns.SkillPlanSkillState("Tailoring")
        assert(state == "unlearned", "a profession that is not in the list is called " .. tostring(state) .. " because a skill was seen once")
        name = "Tailoring"
        -- nothing kept and hidden: unknown, as before (round 1, B5)
        ns.db.recipes = {}
        rank = SECRET
        local why
        state, sr, sm, why = ns.SkillPlanSkillState("Tailoring")
        assert(state == "unknown" and sr == nil and why == "rank", "hidden with nothing kept: " .. tostring(state))
        -- a line the reader leaves out for its hidden MAXIMUM: the skill is
        -- read now all the same - and kept
        for _, char in pairs(ns.db.recipes) do mine = char end
        mine.Tailoring = { rank = 10, list = {} }
        rank, maxRank = 30, SECRET
        assert(select(3, ns.ProfessionRank("Tailoring")) == "lastSeen", "test setup: the reader reads a line with a hidden maximum")
        state, sr, sm, _, ssource = ns.SkillPlanSkillState("Tailoring")
        assert(state == "learned" and sr == 30 and ssource == "current", "a hidden maximum: the readable skill is not the current one")
        assert(mine.Tailoring.rank == 30 and mine.Tailoring.rankAt, "a skill the window read itself is not kept as the one seen last")
        maxRank = 75
        -- a value that is no skill is never kept
        mine.Tailoring = { rank = 40, rankAt = 5, list = {} }
        rank = "12"
        ns.ProfessionRank("Tailoring")
        rank = 0
        ns.ProfessionRank("Tailoring")
        assert(mine.Tailoring.rank == 40 and mine.Tailoring.rankAt == 5, "a value that is no skill was kept as the skill seen last")
    end)
    GetNumSkillLines, GetSkillLineInfo, issecretvalue, ns.db.recipes, ns.db.planTargets = saved.lines, saved.line, saved.secret, saved.recipes, saved.targets
    d.Have, d.Known, d.AllRecipes = saved.have, saved.known, saved.all
    if win then win:Hide() end
    if not ok then error(err, 0) end

    -- the calculation itself: a plan from a skill seen last is a preview,
    -- whatever it comes to
    local function Input(skill, source)
        return { prof = "Testing", skill = skill, target = 3, skillSource = source, skillSeenAt = source and 1234 or nil,
            recipes = { Testing = { { prof = "Testing", key = "A", name = "A", product = 10, made = 1, req = 1, yellow = 9, grey = 9, reagents = { { id = 11, n = 1 } }, learn = "known" } } },
            stock = {}, prices = { [11] = { status = "known", copper = 5 } }, professions = {}, recipeItemPrices = {}, caps = {} }
    end
    local plan = core.Compute(Input(3, "lastSeen"))
    assert(plan.status == "preview" and plan.reliable == false and plan.complete == false and plan.skillSource == "lastSeen" and plan.skillSeenAt == 1234,
        "at the target by a skill seen last: " .. tostring(plan.status))
    local said = false
    for _, diag in ipairs(plan.diagnostics) do said = said or diag.code == "skill_last_seen" end
    assert(said, "the plan does not say why it is not complete")
    plan = core.Compute(Input(1, "lastSeen"))
    assert(plan.status == "preview" and #plan.steps == 1 and plan.total == 10 and core.Result(plan).reliable == false and core.Result(plan).status == "preview", "a preview with steps")
    plan = core.Compute(Input(3))
    assert(plan.status == "done" and plan.reliable == true and plan.skillSource == "current" and plan.skillSeenAt == nil and core.Result(plan).reliable == true, "the skill read now: " .. tostring(plan.status))
    plan = core.Compute(Input(1))
    assert(plan.status == "ok" and plan.complete == true and plan.reliable == true, "a plan from the skill read now is not reliable")
    assert(core.Compute({}).reliable == false and core.Result(core.Compute({})).reliable == false, "an invalid plan is called reliable")
end)
step("Skill plan 2.0: a big plan is worked out in parts - the same plan, never a part of one shown (v0.2 r2 G4)", function()
    -- Codex round 2, R2-M4: one long call would hold the game up. The window
    -- works its plan out in parts of a few milliseconds, one per frame; the
    -- plan of before stays until the new one is finished; a new state drops
    -- what was begun; a closed window works on nothing. And the plan is the
    -- one the calculation in one go gives.
    local L, core, d = ns.L, ns.PlanCore, ns.CraftData
    local f = assert(io.open(ROOT .. "/PlanCore.lua"))
    local coreCode = f:read("*a"):gsub("%-%-[^\n]*", "")
    f:close()
    f = assert(io.open(ROOT .. "/Planner.lua"))
    local planner = f:read("*a")
    f:close()
    -- the calculation knows no clock and no coroutine: it only calls the
    -- pause it is given, and never from where a coroutine could not yield
    for _, word in ipairs({ "pcall", "coroutine", "debugprofilestop", "os%.clock", "GetTimePreciseSec" }) do
        assert(not coreCode:find(word), "PlanCore.lua uses " .. word)
    end
    assert(not coreCode:find("table%.sort%([^\n]*Rest%("), "a rest inside a sort")
    local budget = tonumber(planner:match("\nlocal BUDGET_MS = ([%d.]+)\n"))
    assert(budget and budget >= 1 and budget <= 5, "the time a part may take is not a few milliseconds: " .. tostring(budget))
    assert(planner:find("coroutine.create", 1, true) and planner:find("C_Timer.After(0,", 1, true), "Planner.lua does not spread the calculation over frames")

    local saved = { clock = ns.SkillPlanClock, rank = ns.ProfessionRank, have = d.Have, known = d.Known, cost = d.ReagentCost, compute = core.Compute,
        targets = ns.db.planTargets, listeners = ns.skillPlanListeners, price = ns.GetPrice }
    local win
    local ok, err = pcall(function()
        -- Codex' case: Leatherworking at 150 (maximum 225) with Mining next to
        -- it, no recipe known, 15 of every third item, every price known
        local skill, bonus = 150, 0
        ns.ProfessionRank = function(p)
            if p == "Leatherworking" then return skill, 225 elseif p == "Mining" then return 300, 300 elseif p == "Tailoring" then return 1, 75 end
        end
        d.Known = function() return {} end
        d.Have = function(id) return (id % 3 == 0 and 15 or 0) + bonus end
        d.ReagentCost = function(id) return (id % 97 + 1) * 10, "review", false end
        ns.db.planTargets = nil
        local published = {}
        ns.skillPlanListeners = { function(result) published[#published + 1] = result end }
        local starts, rests = 0, 0
        core.Compute = function(input, pause)
            starts = starts + 1
            if not pause then return saved.compute(input) end
            return saved.compute(input, function()
                rests = rests + 1
                pause()
            end)
        end
        local function Whole(target) -- the plan of the state as it is, in one go
            return saved.compute(ns.SkillPlanSnapshot("Leatherworking", skill, target))
        end
        local function Rows()
            local list = {}
            for _, o in ipairs(allFrames) do
                if o.left and o.mid and o.right and o:IsShown() then list[#list + 1] = o end
            end
            return list
        end
        local function Shows(text)
            for _, row in ipairs(Rows()) do
                if row.left:GetText() == text then return row end
            end
        end
        local WORKING, UPDATING, STEPS = L["Working out the plan ..."], L["Updating the plan ..."], L["Steps"]

        -- ---- the calculation: put down at EVERY resting place, taken up
        -- again - the same plan as in one go
        local input = ns.SkillPlanSnapshot("Leatherworking", 150, 225)
        local whole = saved.compute(input)
        assert(whole.status == "ok" and #whole.steps > 3, "test setup: the plan of Codex' case")
        local asked = 0
        local co = coroutine.create(function() return saved.compute(input, function() asked = asked + 1 coroutine.yield() end) end)
        local resumed, inParts = 0, nil
        repeat
            local fine, result = coroutine.resume(co)
            assert(fine, tostring(result))
            resumed, inParts = resumed + 1, result
        until coroutine.status(co) == "dead"
        local same, why = SamePlan(whole, inParts, "plan")
        assert(same, "put down and taken up again, the plan is another one: " .. tostring(why))
        assert(asked > 1000 and resumed == asked + 1, ("the calculation asks for a pause %d times (taken up %d times)"):format(asked, resumed))
        -- something that is no function is no pause
        same = SamePlan(whole, saved.compute(input, true), "plan")
        assert(same, "a pause that is no function changes the plan")

        -- ---- the window. A plan of another profession first, done at once
        -- (the harness' clock stands still)
        ns.ShowSkillPlan("Tailoring")
        win = _G.GathercraftSkillPlan
        assert(not ns.SkillPlanBusy() and ns.SkillPlanResult().prof == "Tailoring" and Shows(STEPS), "with a clock that stands still the plan is not done at once")
        local revision, given = ns.SkillPlanResult().revision, #published
        -- now a clock that goes on: 0.01 ms with every look at it, so a part
        -- ends after about 400 resting places
        local now, looks, onLook = 0, 0, nil
        ns.SkillPlanClock = function()
            now, looks = now + 0.01, looks + 1
            if onLook then onLook(looks) end
            return now
        end
        starts, rests = 0, 0
        ns.ShowSkillPlan("Leatherworking")
        -- the first part is done, the plan is not: nothing of it is shown
        assert(ns.SkillPlanBusy() and starts == 1, "a big plan is not worked out in parts")
        local firstPart = rests
        assert(firstPart > 100 and firstPart < 1000, ("the first part went over %d resting places"):format(firstPart))
        assert(Shows(WORKING) and #Rows() == 1, "while the first plan is worked out, something else than \"Working out the plan\" is shown")
        assert(not Shows(STEPS) and not Shows(UPDATING), "a part of a plan is shown")
        local result = ns.SkillPlanResult()
        assert(result.prof == "Tailoring" and result.revision == revision and result.updating == true and #published == given, "a result was given out before the plan was finished")
        -- the frames after it: part by part, then the finished plan
        advance(1)
        assert(not ns.SkillPlanBusy() and starts == 1 and rests > firstPart * 3, ("the rest was not worked out in parts (%d resting places, %d in the first part)"):format(rests, firstPart))
        result = ns.SkillPlanResult()
        assert(result.prof == "Leatherworking" and result.target == 225 and result.status == "ok" and result.updating == nil and result.revision == revision + 1 and #published == given + 1,
            "the finished plan did not take the place of the one before")
        assert(Shows(STEPS) and not Shows(WORKING) and not Shows(UPDATING), "the finished plan is not shown")
        -- it is the plan the calculation in one go gives
        local shown, new = ns.SkillPlanCalculate("Leatherworking", 150, 225)
        assert(new == false, "test setup: the state changed")
        local inOneGo = Whole(225)
        inOneGo.revision = shown.revision
        same, why = SamePlan(shown, inOneGo, "plan")
        assert(same, "worked out in parts, the plan is another one than in one go: " .. tostring(why))

        -- ---- a new target: the plan of before stays, marked, until the new one is finished
        starts = 0
        assert(ns.SkillPlanSetTarget(300), "test setup: the target")
        assert(ns.SkillPlanBusy() and starts == 1, "a new target: nothing is worked out")
        assert(Shows(UPDATING) and Shows(STEPS) and not Shows(WORKING), "the plan of before is not shown, marked as being updated")
        result = ns.SkillPlanResult()
        assert(result.target == 225 and result.updating == true and result.revision == revision + 1, "the result of before is not marked as being updated")
        advance(1)
        result = ns.SkillPlanResult()
        assert(not ns.SkillPlanBusy() and result.target == 300 and result.updating == nil and result.revision == revision + 2 and not Shows(UPDATING), "the plan to 300 did not take over")
        shown = ns.SkillPlanCalculate("Leatherworking", 150, 300)
        inOneGo = Whole(300)
        inOneGo.revision = shown.revision
        same, why = SamePlan(shown, inOneGo, "plan")
        assert(same, "to 300, in parts: another plan than in one go: " .. tostring(why))

        -- ---- "Done" belongs to the state as it is: at 225 of 225 it is
        -- shown; with a new target it is gone while the new plan is worked out
        assert(ns.SkillPlanSetTarget(225)) advance(1)
        skill = 225
        ns.RefreshSkillPlan() advance(1)
        local DONE = (L["Done: you have reached your target (%d)."]):format(225)
        assert(ns.SkillPlanResult().status == "done" and Shows(DONE), "test setup: 225 of 225 is done")
        assert(ns.SkillPlanSetTarget(300), "test setup: the target")
        assert(ns.SkillPlanBusy() and Shows(UPDATING), "test setup: the plan from 225 to 300 is done in one part")
        assert(not Shows(DONE), "\"Done\" of the plan before is shown while a new plan is worked out")
        for _, row in ipairs(Rows()) do
            assert(row.left:GetText() ~= (L["Done: you have reached your target (%d)."]):format(300), "\"Done\" from a plan that is not finished")
        end
        advance(1)
        assert(not ns.SkillPlanBusy() and ns.SkillPlanResult().status ~= "done" and ns.SkillPlanResult().from == 225, "the plan from 225 did not take over")
        skill = 150
        ns.RefreshSkillPlan() advance(1)

        -- ---- the bags change while it is worked out: what was begun is not
        -- finished into a plan of two states
        local count = #published
        starts = 0
        local from = looks
        onLook = function(n) if n == from + 1500 then bonus = 1 end end -- (in the middle of a later part)
        assert(ns.SkillPlanSetTarget(250), "test setup: the target")
        advance(1)
        onLook = nil
        assert(bonus == 1 and starts == 2, ("the state changed while the plan was worked out: %d calculations were begun, want 2"):format(starts))
        assert(#published == count + 1, ("%d plans were given out, want the one of the new state only"):format(#published - count))
        shown = ns.SkillPlanCalculate("Leatherworking", 150, 250)
        inOneGo = Whole(250)
        inOneGo.revision = shown.revision
        same, why = SamePlan(shown, inOneGo, "plan")
        assert(same, "after a change in the middle the plan is not that of the new state: " .. tostring(why))
        for id, item in pairs(published[#published].items) do
            assert(item.have == (id % 3 == 0 and 15 or 0) + 1, "the plan that was given out counted an item before the change")
        end

        -- ---- many events while it is worked out, and nothing has changed:
        -- still the one calculation
        count, starts = #published, 0
        assert(ns.SkillPlanSetTarget(260), "test setup: the target")
        for _ = 1, 20 do fire("BAG_UPDATE_DELAYED") end
        advance(1)
        assert(starts == 1 and #published == count + 1 and ns.SkillPlanResult().target == 260, ("20 events without a change: %d calculations begun"):format(starts))

        -- ---- the window is closed: nothing goes on, nothing is given out
        count, starts = #published, 0
        assert(ns.SkillPlanSetTarget(270), "test setup: the target")
        assert(ns.SkillPlanBusy(), "test setup: a calculation is running")
        win:Hide()
        local before = looks
        advance(1)
        assert(not ns.SkillPlanBusy() and #published == count and starts == 1, "a closed window goes on working out its plan")
        local after = looks
        advance(1)
        assert(looks == after and after - before <= 2, "a closed window still looks at the clock")
        assert(ns.SkillPlanResult().target == 260 and ns.SkillPlanResult().updating == true, "the result of before is not marked as out of date")
        -- opened again: worked out anew
        ns.ShowSkillPlan("Leatherworking") advance(1)
        assert(not ns.SkillPlanBusy() and #published == count + 1 and ns.SkillPlanResult().target == 270 and ns.SkillPlanResult().updating == nil, "opened again: no plan")

        -- ---- the window shows no plan any more (no profession chosen):
        -- nothing is worked out for it
        assert(ns.SkillPlanSetTarget(275), "test setup: the target")
        assert(ns.SkillPlanBusy(), "test setup: a calculation is running")
        count = #published
        ns.ShowSkillPlan("No such profession")
        assert(Shows(L["Choose a profession first."]) and not ns.SkillPlanBusy(), "a window without a profession goes on working out a plan")
        advance(1)
        assert(#published == count, "a plan was given out for a window that shows none")
        ns.ShowSkillPlan("Leatherworking") advance(1)
        assert(not ns.SkillPlanBusy() and ns.SkillPlanResult().target == 275, "test setup: back to the plan")

        -- ---- an error in the calculation is an error, not a silence
        core.Compute = function() error("the calculation broke", 0) end
        local fine, problem = pcall(ns.SkillPlanSetTarget, 280)
        assert(not fine and tostring(problem):find("the calculation broke", 1, true), "an error in the calculation is swallowed")
        assert(not ns.SkillPlanBusy(), "a calculation that broke is still called running")
        core.Compute = saved.compute

        -- ---- with the clock the game has (here: the machine's): the same
        -- (asked again by the player: what broke before is tried once more)
        ns.SkillPlanClock = nil
        ns.ShowSkillPlan("Leatherworking") advance(1)
        assert(not ns.SkillPlanBusy() and ns.SkillPlanResult().target == 280 and ns.SkillPlanResult().updating == nil, "asked again after an error, the window has no plan")
        shown, new = ns.SkillPlanCalculate("Leatherworking", 150, 280)
        assert(new == false, "the window's plan is not that of the state as it is")
        inOneGo = Whole(280)
        inOneGo.revision = shown.revision
        same, why = SamePlan(shown, inOneGo, "plan")
        assert(same and not ns.SkillPlanBusy() and ns.SkillPlanResult().target == 280, "with a real clock: " .. tostring(why))
    end)
    ns.SkillPlanClock, ns.ProfessionRank, d.Have, d.Known, d.ReagentCost, core.Compute = saved.clock, saved.rank, saved.have, saved.known, saved.cost, saved.compute
    ns.db.planTargets, ns.skillPlanListeners, ns.GetPrice = saved.targets, saved.listeners, saved.price
    if win then win:Hide() end
    if not ok then error(err, 0) end
end)
step("Skill plan 2.0: what a batch made too much is used by the next need (v0.2 r2 G6)", function()
    -- Codex round 2 (the note on "no look ahead"): a need is decided when it
    -- comes up, and what a batch makes too much is no saving at that moment
    -- (selling it is not part of the plan). But a surplus that IS there is
    -- stock like any other: the next need uses it before anything is bought
    -- or made - on the plan's books and on the books of the recipe choice.
    local core = ns.PlanCore
    local function R(key, product, req, upto, mats, extra)
        local r = { prof = "Testing", key = key, name = key, product = product, made = 1, req = req, yellow = upto, grey = upto, reagents = {}, learn = "known" }
        for _, x in ipairs(mats) do r.reagents[#r.reagents + 1] = { id = x[1], n = x[2] } end
        for k, v in pairs(extra or {}) do r[k] = v end
        return r
    end
    local function Plan(recipes, prices, to)
        local p = {}
        for id, copper in pairs(prices) do p[id] = { status = "known", copper = copper } end
        local plan = core.Compute({ prof = "Testing", skill = 1, target = to or 3, recipes = { Testing = recipes }, stock = {}, prices = p,
            professions = {}, recipeItemPrices = {}, caps = {} })
        local ok, why = core.CheckBalance(plan)
        assert(ok, "the books do not balance: " .. tostring(why))
        local keys = {}
        for _, s in ipairs(plan.steps) do keys[#keys + 1] = s.recipe.key end
        return plan, table.concat(keys, ",") .. " " .. tostring(plan.total)
    end
    -- an X costs 20c, a batch of three 30c
    local makeX = R("Make X", 11, 1, 1, { { 12, 1 } }, { made = 3 })
    local prices = { [11] = 20, [12] = 30, [21] = 5 }
    -- the first step takes two X: a batch (30c, below 40c) - one X is left.
    -- The second step takes one X: the one that is left, nothing is bought
    local plan, says = Plan({ R("A", 10, 1, 2, { { 11, 2 } }), R("B", 20, 2, 3, { { 11, 1 } }), makeX }, prices)
    local x = plan.ledger[11]
    assert(says == "A,B 30", "one X left from the batch, one X needed: " .. says)
    assert(x.madeExtra == 3 and x.used == 3 and x.bought == 0 and x.rest == 0, ("the X: made %d, used %d, bought %d, left %d"):format(x.madeExtra, x.used, x.bought, x.rest))
    -- the recipe choice sees it too: with the X that is left B costs nothing
    -- at the second point - C (5c) is not taken. (Without it B would cost
    -- 20c and C would be.)
    plan, says = Plan({ R("A", 10, 1, 2, { { 11, 2 } }), R("B", 20, 2, 3, { { 11, 1 } }), R("C", 30, 2, 3, { { 21, 1 } }), makeX }, prices)
    assert(says == "A,B 30", "the recipe choice does not count the X that is left: " .. says)
    -- a surplus that covers a part of the next need: the rest is decided
    -- for itself - one more X bought (20c), no second batch (30c)
    plan, says = Plan({ R("A", 10, 1, 2, { { 11, 2 } }), R("B", 20, 2, 3, { { 11, 2 } }), makeX }, prices)
    x = plan.ledger[11]
    assert(says == "A,B 50" and x.madeExtra == 3 and x.bought == 1 and x.used == 4 and x.rest == 0, "one X left, two needed: " .. says)
    -- and what is left at the end is left: it is in the books, not sold, not
    -- counted as a saving
    plan, says = Plan({ R("A", 10, 1, 2, { { 11, 2 } }), makeX }, prices, 2)
    x = plan.ledger[11]
    assert(says == "A 30" and x.madeExtra == 3 and x.used == 2 and x.rest == 1, "what is left at the end: " .. says)
end)
step("Skill plan 2.0: a profession you no longer have makes nothing, one that cannot be read makes a preview (v0.2 r3 H1)", function()
    -- Codex round 3, R3-M1: a profession next to the planned one was taken
    -- from what was remembered of it - its skill and its recipes - also when
    -- the skill list proved that you do not have it any more. It is read
    -- like the planned profession now: proof that it is not learned ends
    -- making with it; a skill that was only seen last makes the plan a
    -- preview. Through the real reader and the real snapshot.
    local L, core, d = ns.L, ns.PlanCore, ns.CraftData
    local saved = { lines = GetNumSkillLines, line = GetSkillLineInfo, secret = issecretvalue, recipes = ns.db.recipes, targets = ns.db.planTargets,
        compute = core.Compute, have = d.Have, cost = d.ReagentCost }
    local win
    local ok, err = pcall(function()
        ns.db.recipes = {}
        ns.db.planTargets = nil
        d.Have = function() return 0 end
        local SECRET = newproxy(true)
        issecretvalue = function(v) return rawequal(v, SECRET) end
        -- the skill list: Tailoring 75 / 150, and what `alchemy` says
        local alchemy, folded = nil, false -- nil: not in the list; else its skill
        local function Lines()
            local list = { { "Professions", true, not folded, 0, 0, 0, 0 }, { "Tailoring", false, true, 75, 0, 0, 150 } }
            if alchemy ~= nil then list[#list + 1] = { "Alchemy", false, true, alchemy, 0, 0, 300 } end
            return list
        end
        GetNumSkillLines = function() return #Lines() end
        GetSkillLineInfo = function(i) return unpack(Lines()[i]) end
        ns.ProfessionRank("Tailoring")
        local mine
        for _, char in pairs(ns.db.recipes) do mine = char end
        assert(mine, "test setup: no record of this character")
        -- what the Alchemy window left behind, an hour ago: skill 300, one
        -- recipe - a potion (999001) from one herb (999002)
        local seenAt = time() - 3600
        mine.Alchemy = { rank = 300, rankAt = seenAt, list = { Potion = "999001:1:1:1|999002:1" } }
        -- the plan: one point of Tailoring with a recipe that takes one
        -- potion. The potion costs 100c, the herb 1c.
        local function Plan()
            local input = ns.SkillPlanSnapshot("Tailoring", 75, 76)
            local seen = { prof = input.professions.Alchemy, recipes = input.recipes.Alchemy }
            input.recipes.Tailoring = { { prof = "Tailoring", key = "A", name = "A", product = 999003, made = 1, req = 1, yellow = 100, grey = 120, learn = "known",
                reagents = { { id = 999001, n = 1 } } } }
            input.stock, input.recipeItemPrices = {}, {}
            input.prices = { [999001] = { status = "known", copper = 100 }, [999002] = { status = "known", copper = 1 } }
            local plan = core.Compute(input)
            assert(core.CheckBalance(plan))
            return plan, core.Result(plan), seen
        end
        local function Made(plan)
            local n = 0
            for _, e in ipairs(plan.extras) do n = n + e.times end
            return n
        end

        -- ---- Codex' case: the whole list can be read, Alchemy is not in it
        local state = ns.SkillPlanSkillState("Alchemy")
        assert(state == "unlearned", "test setup: Alchemy is called " .. tostring(state))
        local plan, res, seen = Plan()
        assert(seen.prof == nil and seen.recipes == nil, ("a profession that is proved gone is in the snapshot (skill %s, %d recipes)"):format(
            tostring(seen.prof and seen.prof.rank), seen.recipes and #seen.recipes or 0))
        assert(plan.total == 100 and Made(plan) == 0, ("a profession you no longer have makes the potion: %s copper"):format(tostring(plan.total)))
        assert(res.status == "ok" and res.complete == true and res.reliable == true and #res.lastSeenProfessions == 0, "a plan that only buys is not called reliable")
        -- what was kept of it is not thrown away
        assert(mine.Alchemy.rank == 300 and mine.Alchemy.rankAt == seenAt and mine.Alchemy.list.Potion, "what was kept of the profession was changed")

        -- ---- Alchemy is in the list, its skill is hidden: the skill seen
        -- last is used and said to be that - the plan that makes the potion
        -- with it is a preview
        alchemy = SECRET
        local _, r, _, _, source = ns.SkillPlanSkillState("Alchemy")
        assert(r == 300 and source == "lastSeen", "test setup: a hidden Alchemy skill")
        plan, res, seen = Plan()
        assert(seen.prof and seen.prof.rank == 300 and seen.prof.source == "lastSeen" and seen.prof.seenAt == seenAt and #seen.recipes == 1,
            "a profession whose skill cannot be read is not passed on as seen last")
        assert(plan.total == 1 and Made(plan) == 1, "test setup: the potion is not made")
        assert(plan.status == "preview" and plan.reliable == false and plan.complete == false,
            ("made with a profession that cannot be read: status %s, reliable %s, complete %s"):format(tostring(plan.status), tostring(plan.reliable), tostring(plan.complete)))
        assert(#plan.lastSeenProfessions == 1 and plan.lastSeenProfessions[1] == "Alchemy", "the plan does not name the profession it is unsure of")
        local said
        for _, diag in ipairs(plan.diagnostics) do if diag.code == "profession_last_seen" and diag.prof == "Alchemy" and diag.seenAt == seenAt then said = true end end
        assert(said, "the plan does not say why it is not complete")
        assert(res.status == "preview" and res.reliable == false and res.complete == false and res.lastSeenProfessions[1] == "Alchemy"
            and res.items[999001].make == true and res.items[999001].makeLastSeen == true, "the result does not pass it on")
        assert(plan.skillSource == "current", "the planned profession is called seen last")
        -- the same when the list itself cannot be read (a folded group)
        alchemy, folded = nil, true
        plan, res = Plan()
        assert(plan.total == 1 and res.status == "preview" and res.reliable == false, "a skill list that cannot be read: " .. tostring(res.status))
        folded = false
        -- ... but a plan that makes nothing with it rests on nothing unsure:
        -- the potion at 1c is bought (the herb at 100c)
        alchemy = SECRET
        local input = ns.SkillPlanSnapshot("Tailoring", 75, 76)
        input.recipes.Tailoring = { { prof = "Tailoring", key = "A", name = "A", product = 999003, made = 1, req = 1, yellow = 100, grey = 120, learn = "known",
            reagents = { { id = 999001, n = 1 } } } }
        input.stock, input.recipeItemPrices = {}, {}
        input.prices = { [999001] = { status = "known", copper = 1 }, [999002] = { status = "known", copper = 100 } }
        plan = core.Compute(input)
        assert(plan.total == 1 and Made(plan) == 0 and plan.status == "ok" and plan.reliable == true and #plan.lastSeenProfessions == 0,
            "a plan that makes nothing with the unreadable profession is called a preview")

        -- ---- Alchemy read now: as before
        alchemy = 300
        plan, res, seen = Plan()
        assert(seen.prof and seen.prof.rank == 300 and seen.prof.source == nil, "a profession read now is called seen last")
        assert(plan.total == 1 and Made(plan) == 1 and res.status == "ok" and res.reliable == true and res.complete == true and res.items[999001].makeLastSeen == false,
            "a profession read now: " .. tostring(res.status))
        -- hidden with nothing kept: not used at all
        mine.Alchemy = { list = { Potion = "999001:1:1:1|999002:1" } }
        alchemy = SECRET
        plan, res, seen = Plan()
        assert(seen.prof == nil and plan.total == 100 and res.reliable == true, "a profession of unknown skill is used")

        -- ---- gone and back: learned anew at skill 1, what was kept of it
        -- counts again - as far as the skill allows
        mine.Alchemy = { rank = 300, rankAt = seenAt, list = { Potion = "999001:1:1:1|999002:1", Elixir = "999004:1:1:250|999002:1" } }
        alchemy = nil
        plan = Plan()
        assert(plan.total == 100, "test setup: gone")
        alchemy = 1
        plan, res, seen = Plan()
        assert(seen.prof and seen.prof.rank == 1 and seen.prof.source == nil and #seen.recipes == 2, "learned again: what was kept does not count")
        assert(plan.total == 1 and Made(plan) == 1 and res.reliable == true, "learned again: the potion is not made")
        assert(mine.Alchemy.rank == 1, "learned again: the skill read now is not kept")

        -- ---- the window: the plan made with a profession seen last is
        -- marked, and it is another state than the same plan read live
        mine.Alchemy = { rank = 300, rankAt = seenAt, list = { Potion = "999001:1:1:1|999002:1" } }
        -- (the prices and counts come through the snapshot's own readers,
        -- so a state that has not changed is seen as that)
        d.ReagentCost = function(id)
            if id == 999001 then return 100, "AH scan" elseif id == 999002 then return 1, "AH scan" end
        end
        core.Compute = function(input, pause)
            input.recipes.Tailoring = { { prof = "Tailoring", key = "A", name = "Recipe A", product = 999003, made = 1, req = 1, yellow = 100, grey = 120, learn = "known",
                reagents = { { id = 999001, n = 1 } } } }
            return saved.compute(input, pause)
        end
        local function Rows()
            local list = {}
            for _, o in ipairs(allFrames) do
                if o.left and o.mid and o.right and o:IsShown() then list[#list + 1] = o end
            end
            return list
        end
        local function Count(text)
            local n = 0
            for _, row in ipairs(Rows()) do if row.left:GetText() == text then n = n + 1 end end
            return n
        end
        local function Note()
            for _, o in ipairs(allFrames) do
                local at = o.__parent == win and o.__kind == "FontString" and o.__pts and o.__pts.BOTTOMLEFT
                if at and at[2] == 24 then return o:GetText() end
            end
        end
        local function Header(text)
            for _, o in ipairs(allFrames) do
                if o.__kind == "FontString" and o.__parent == win and o:GetText() == text then return o end
            end
        end
        local function Px(t)
            local px = 0
            for ch in (t or ""):gmatch("[%z\1-\127\194-\244][\128-\191]*") do px = px + (#ch >= 3 and 11 or 6) end
            return px
        end
        local OTHER = (L["Your %s skill cannot be read right now. The plan makes materials with it, going by the skill seen last: until it can be read, this is a preview."]):format(d.ProfLabel("Alchemy"))
        local SUM_NOTE = L["A preview: it uses a profession whose skill cannot be read right now."]
        alchemy = 300
        ns.ShowSkillPlan("Tailoring") advance(1)
        win = _G.GathercraftSkillPlan
        assert(ns.SkillPlanSetTarget(76), "test setup: the target")
        advance(1)
        local live = ns.SkillPlanResult()
        assert(live.status == "ok" and live.reliable == true and live.from == 75 and live.target == 76, "test setup: the plan with Alchemy read live")
        assert(Count(OTHER) == 0 and Note() ~= SUM_NOTE, "a plan with every skill read now is marked as a preview")
        ns.RefreshSkillPlan() advance(1)
        assert(ns.SkillPlanResult().revision == live.revision, "test setup: a state that has not changed gives a new plan")
        alchemy = SECRET
        ns.RefreshSkillPlan() advance(1)
        local res2 = ns.SkillPlanResult()
        assert(res2.revision > live.revision, "the same skill of the other profession, now only seen last, is not a new state")
        assert(res2.status == "preview" and res2.reliable == false and res2.lastSeenProfessions[1] == "Alchemy", "the window's result: " .. tostring(res2.status))
        assert(Count(OTHER) == 1, ("the window names the profession it is unsure of %d times, want once"):format(Count(OTHER)))
        assert(Note() == SUM_NOTE, "the sum is not marked as that of a preview: " .. tostring(Note()))
        assert(Px(SUM_NOTE) <= 500, ("%s: the note under the sum needs %d px of 500"):format(LOCALE, Px(SUM_NOTE)))
        assert(Header((L["Your skill: %d / %d"]):format(75, 150)), "the planned profession's skill is not shown as read now")
        for _, row in ipairs(Rows()) do
            assert(not (row.left:GetText() or ""):find(L["Done: you have reached your target (%d)."]:gsub("%%d.*", ""), 1, true), "\"Done\" in a preview")
        end
        -- gone for good: no mark, the potion is bought
        alchemy = nil
        ns.RefreshSkillPlan() advance(1)
        local res3 = ns.SkillPlanResult()
        assert(res3.revision > res2.revision and res3.status == "ok" and res3.reliable == true and res3.items[999001].missing == 1 and res3.items[999001].make == false,
            "the window still makes the potion with a profession that is gone")
        assert(Count(OTHER) == 0 and Note() ~= SUM_NOTE, "a plan without the profession is marked as a preview")
    end)
    GetNumSkillLines, GetSkillLineInfo, issecretvalue, ns.db.recipes, ns.db.planTargets = saved.lines, saved.line, saved.secret, saved.recipes, saved.targets
    core.Compute, d.Have, d.ReagentCost = saved.compute, saved.have, saved.cost
    if win then win:Hide() end
    if not ok then error(err, 0) end
end)
step("Skill plan 2.0: a calculation that breaks in a later part leaves no \"Updating\" behind (v0.2 r3 H2)", function()
    -- Codex round 3: an error in the first part of the calculation was
    -- tested. When it breaks only after it was put down once, the error was
    -- reported and the work dropped - but "Updating the plan ..." stayed on
    -- the screen until the next refresh. Now the window is drawn anew (the
    -- plan of before, no "Updating", a line that says what happened), then
    -- the error is raised; and nothing is begun again for the same state.
    local L, core, d = ns.L, ns.PlanCore, ns.CraftData
    local saved = { clock = ns.SkillPlanClock, rank = ns.ProfessionRank, have = d.Have, known = d.Known, cost = d.ReagentCost, compute = core.Compute,
        targets = ns.db.planTargets, listeners = ns.skillPlanListeners }
    local win
    local reported = #errors
    local ok, err = pcall(function()
        local bonus = 0
        ns.ProfessionRank = function(p)
            if p == "Leatherworking" then return 150, 225 elseif p == "Mining" then return 300, 300 elseif p == "Tailoring" then return 1, 75 end
        end
        d.Known = function() return {} end
        d.Have = function(id) return (id % 3 == 0 and 15 or 0) + bonus end
        d.ReagentCost = function(id) return (id % 97 + 1) * 10, "review", false end
        ns.db.planTargets = nil
        local published = 0
        ns.skillPlanListeners = { function() published = published + 1 end }
        -- the calculation, breaking after `breakAt` resting places (nil: never)
        local starts, breakAt = 0, nil
        core.Compute = function(input, pause)
            starts = starts + 1
            if not pause then return saved.compute(input) end
            local rests = 0
            return saved.compute(input, function()
                rests = rests + 1
                if breakAt and rests > breakAt then error("the calculation broke after a rest", 0) end
                pause()
            end)
        end
        local function Rows()
            local list = {}
            for _, o in ipairs(allFrames) do
                if o.left and o.mid and o.right and o:IsShown() then list[#list + 1] = o end
            end
            return list
        end
        local function Count(text)
            local n = 0
            for _, row in ipairs(Rows()) do if row.left:GetText() == text then n = n + 1 end end
            return n
        end
        -- the errors the harness caught since the last look (and takes them
        -- off its list: they are what this step is about)
        local function Caught()
            local list = {}
            while #errors > reported do list[#list + 1] = table.remove(errors) end
            return list
        end
        local WORKING, UPDATING, STEPS = L["Working out the plan ..."], L["Updating the plan ..."], L["Steps"]
        local BROKE = L["The plan could not be worked out: an error occurred."]

        -- a finished plan to 225 first (the harness' clock stands still)
        ns.ShowSkillPlan("Leatherworking")
        win = _G.GathercraftSkillPlan
        assert(ns.SkillPlanSetTarget(225), "test setup: the target")
        local before = ns.SkillPlanResult()
        assert(before.prof == "Leatherworking" and before.target == 225 and Count(STEPS) == 1 and #Caught() == 0, "test setup: the plan to 225")
        -- a clock that goes on: a part ends after about 400 resting places
        local now = 0
        ns.SkillPlanClock = function()
            now = now + 0.01
            return now
        end

        -- ---- the calculation breaks in a later part
        starts, published, breakAt = 0, 0, 600
        assert(ns.SkillPlanSetTarget(300), "test setup: the target")
        assert(ns.SkillPlanBusy() and Count(UPDATING) == 1 and #Caught() == 0, "test setup: the first part did not go through")
        advance(1)
        local caught = Caught()
        assert(#caught == 1 and tostring(caught[1]):find("the calculation broke after a rest", 1, true),
            ("an error in a later part is reported %d times, want once (%s)"):format(#caught, tostring(caught[1])))
        assert(not ns.SkillPlanBusy(), "a calculation that broke is still called running")
        assert(Count(UPDATING) == 0 and Count(WORKING) == 0, "\"Updating the plan ...\" stays on the screen after the calculation broke")
        assert(Count(BROKE) == 1, ("the window says %d times that the plan could not be worked out, want once"):format(Count(BROKE)))
        assert(Count(STEPS) == 1, "the plan of before is gone after the calculation broke")
        local result = ns.SkillPlanResult()
        assert(result.target == 225 and result.revision == before.revision and result.updating == true and published == 0, "a result was given out by a calculation that broke")
        -- nothing is begun again for the same state: no error every 0.2 s
        for _ = 1, 5 do fire("BAG_UPDATE_DELAYED") end
        advance(1)
        assert(starts == 1 and #Caught() == 0, ("the same state after an error: %d calculations begun"):format(starts))
        assert(Count(BROKE) == 1 and Count(UPDATING) == 0, "the line about the error does not stay for the same state")
        -- a new state is worked out again - and when that goes well, the line is gone
        breakAt, bonus = nil, 1
        fire("BAG_UPDATE_DELAYED")
        advance(1)
        result = ns.SkillPlanResult()
        assert(starts == 2 and #Caught() == 0 and not ns.SkillPlanBusy() and result.target == 300 and result.updating == nil and published == 1, "a new state after an error is not worked out")
        assert(Count(BROKE) == 0 and Count(UPDATING) == 0 and Count(STEPS) == 1, "the line about the error stays after a plan that went well")

        -- ---- it breaks in a later part with no plan of the profession to
        -- show: "Working out the plan ..." does not stay either
        ns.ShowSkillPlan("Tailoring") advance(1)
        assert(#Caught() == 0 and ns.SkillPlanResult().prof == "Tailoring", "test setup: a plan of another profession")
        starts, published, breakAt = 0, 0, 600
        ns.ShowSkillPlan("Leatherworking")
        assert(ns.SkillPlanBusy() and Count(WORKING) == 1 and #Rows() == 1, "test setup: nothing to show while the first part runs")
        advance(1)
        caught = Caught()
        assert(#caught == 1 and Count(WORKING) == 0 and Count(BROKE) == 1 and #Rows() == 1 and not ns.SkillPlanBusy(), "\"Working out the plan ...\" stays after the calculation broke")
        assert(ns.SkillPlanResult().prof == "Tailoring" and ns.SkillPlanResult().updating == true and published == 0, "a result was given out")
        -- asked again by the player: tried once more
        breakAt = nil
        ns.ShowSkillPlan("Leatherworking") advance(1)
        assert(#Caught() == 0 and ns.SkillPlanResult().prof == "Leatherworking" and Count(BROKE) == 0 and Count(STEPS) == 1, "opened again after an error: no plan")

        -- ---- it breaks in the very first part: raised to the one who asked
        -- (as before) - and the window does not keep an old "Updating"
        breakAt = 600
        assert(ns.SkillPlanSetTarget(260), "test setup: the target")
        assert(ns.SkillPlanBusy() and Count(UPDATING) == 1, "test setup: a calculation is running")
        breakAt = 0 -- (the next calculation breaks at its first resting place)
        local fine, problem = pcall(ns.SkillPlanSetTarget, 270)
        assert(not fine and tostring(problem):find("the calculation broke after a rest", 1, true), "an error in the first part is swallowed")
        assert(not ns.SkillPlanBusy() and Count(UPDATING) == 0 and Count(BROKE) == 1, "an error in the first part: \"Updating\" of the calculation before stays")
        advance(1)
        assert(#Caught() == 0, "the error of the first part is reported a second time")
    end)
    while #errors > reported do table.remove(errors) end
    ns.SkillPlanClock, ns.ProfessionRank, d.Have, d.Known, d.ReagentCost, core.Compute = saved.clock, saved.rank, saved.have, saved.known, saved.cost, saved.compute
    ns.db.planTargets, ns.skillPlanListeners = saved.targets, saved.listeners
    if win then win:Hide() end
    if not ok then error(err, 0) end
end)
-- (end of the skill plan 2.0 steps, v0.2 building block 1)
step("Craft log: one entry per finished craft, failures and odd cases marked apart (v0.1.18 S5)", function()
    local data = GathercraftRecipeData
    local spell = data.spells.Leatherworking["Light Leather"]
    local saved = { rank = ns.ProfessionRank, have = ns.CraftData.Have, colors = data.colors[spell], log = ns.db.craftLog,
        off = ns.db.craftLogOff, secret = issecretvalue }
    local rank, maxRank, bag = 10, 75, 0
    ns.ProfessionRank = function(p) if p == "Leatherworking" then return rank, maxRank end end
    ns.CraftData.Have = function(id) return id == 2318 and bag or 0 end
    data.colors[spell] = "20:40" -- orange below 20, yellow below 30, green below 40, grey from 40
    ns.db.craftLog, ns.db.craftLogOff = {}, nil
    local keepMulti = ns.db.craftMulti ns.db.craftMulti = nil -- (F2: the note of a multi-point craft)
    local n = 0
    local function Craft(gain, events, made)
        n = n + 1
        local guid = "Cast-3-1-1-1-" .. spell .. "-" .. n
        for _, e in ipairs(events or { "UNIT_SPELLCAST_START", "UNIT_SPELLCAST_SUCCEEDED" }) do
            if e == "UNIT_SPELLCAST_SUCCEEDED" then
                if gain and gain ~= 0 then rank = rank + gain end
                bag = bag + (made or 1)
            end
            fire(e, "player", guid, spell)
        end
        advance(2)
        return guid
    end
    local function Last() return ns.db.craftLog[#ns.db.craftLog] end
    local ok, err = pcall(function()
        -- a skill-up: everything that is known about it
        Craft(1)
        local e = Last()
        assert(#ns.db.craftLog == 1 and e.result == "ok", "no entry for a finished craft")
        assert(e.prof == "Leatherworking" and e.recipe == "Light Leather" and e.spell == spell, "profession or recipe")
        assert(e.before == 10 and e.after == 11 and e.gain == 1 and e.max == 75, ("skill %s -> %s"):format(tostring(e.before), tostring(e.after)))
        assert(e.colour == "orange" and e.yellow == 20 and e.grey == 40, "colour " .. tostring(e.colour))
        assert(e.made == 1 and e.build == 70450 and e.t, ("made %s, build %s"):format(tostring(e.made), tostring(e.build)))
        assert(not e.multi and not e.atCap and not e.secret, "marked although nothing odd")
        -- no skill-up (yellow at 25)
        rank = 25
        Craft(0)
        assert(Last().gain == 0 and Last().colour == "yellow", "a craft without a skill-up")
        -- failed: FAILED and INTERRUPTED of one cast are one entry
        Craft(0, { "UNIT_SPELLCAST_START", "UNIT_SPELLCAST_FAILED", "UNIT_SPELLCAST_INTERRUPTED" })
        assert(#ns.db.craftLog == 3 and Last().result == "failed", "a failed cast")
        Craft(0, { "UNIT_SPELLCAST_START", "UNIT_SPELLCAST_INTERRUPTED" })
        assert(#ns.db.craftLog == 4 and Last().result == "interrupted", "an interrupted cast")
        -- more than one point
        rank = 35
        Craft(2)
        assert(Last().multi and Last().gain == 2 and Last().colour == "yellow", "a gain of two points (35 of 20:40 is yellow since K3, no green threshold)")
        -- at the rank's maximum
        rank, maxRank = 75, 75
        Craft(0)
        assert(Last().atCap, "a craft at the maximum")
        rank, maxRank = 45, 75
        -- the same cast twice, and a late failure of it: one craft
        local count = #ns.db.craftLog
        local guid = Craft(1)
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", guid, spell)
        fire("UNIT_SPELLCAST_FAILED", "player", guid, spell)
        advance(2)
        assert(#ns.db.craftLog == count + 1 and Last().colour == "grey", ("one cast: %d entries"):format(#ns.db.craftLog - count))
        -- a value the client hides: marked, nothing made up
        local SECRET = newproxy(true)
        issecretvalue = function(v) return rawequal(v, SECRET) end
        rank = SECRET
        Craft(0)
        assert(Last().secret and Last().before == nil and Last().gain == nil, "a hidden skill")
        rank = 45
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", SECRET, spell) advance(2)
        -- since F2 (Codex M2): only a recipe spell counts, and it says which
        assert(Last().secret and Last().recipe == "Light Leather" and Last().gain == nil, "a hidden cast")
        issecretvalue = saved.secret
        -- not a recipe (a gathering spell): nothing
        count = #ns.db.craftLog
        fire("UNIT_SPELLCAST_START", "player", "Cast-x", 2366) fire("UNIT_SPELLCAST_SUCCEEDED", "player", "Cast-x", 2366) advance(2)
        assert(#ns.db.craftLog == count, "a gathering spell in the craft log")
        -- /gcr craftlog: per colour and per distance to grey; the odd ones apart
        local mark = #log
        slash("craftlog")
        local text = table.concat(log, "\n", mark + 1)
        -- (7 since 0.1.21, T7: the two failed or interrupted casts are no crafts)
        assert(text:find((ns.L["Craft log: %d crafts (kept on this computer, never shared)."]):format(7), 1, true), "no count in /gcr craftlog: " .. text)
        assert(text:find((ns.L["  %s: %d crafts, %d skill-ups (%d%%)"]):format("|cffff8040" .. ns.L["orange"] .. "|r", 1, 1, 100), 1, true), "orange line: " .. text)
        assert(text:find((ns.L["  %s points below grey: %d crafts, %d skill-ups (%d%%)"]):format("5-9", 1, 1, 100), 1, true), "distance line: " .. text)
        assert(text:find((ns.L["  Not counted: %d failed or interrupted, %d unreadable, %d overlapping, %d at the rank's maximum; %d gave more than one point."]):format(2, 2, 0, 1, 1), 1, true), "not counted: " .. text)
        -- turned off: nothing is recorded
        ns.db.craftLogOff = true
        count = #ns.db.craftLog
        Craft(1)
        assert(#ns.db.craftLog == count, "recorded although turned off")
        ns.db.craftLogOff = nil
        -- the newest 5000 are kept
        local full = {}
        for i = 1, 5000 do full[i] = { t = i, result = "ok", colour = "unknown" } end
        ns.db.craftLog = full
        Craft(1)
        assert(#ns.db.craftLog == 5000 and ns.db.craftLog[1].t == 2 and Last().recipe == "Light Leather", "the list is not kept at 5000")
        slash("craftlog clear")
        assert(#ns.db.craftLog == 0, "/gcr craftlog clear")
    end)
    ns.ProfessionRank, ns.CraftData.Have, data.colors[spell] = saved.rank, saved.have, saved.colors
    ns.db.craftLog, ns.db.craftLogOff, issecretvalue = saved.log, saved.off, saved.secret
    ns.db.craftMulti = keepMulti
    if not ok then error(err, 0) end
end)
step("Craft log: only clear observations count; no other spells, hidden amounts, clear (v0.1.18 F2)", function()
    -- Codex M1, M2, V1, N2 (08.11.)
    local data = GathercraftRecipeData
    local spell = data.spells.Leatherworking["Light Leather"]
    local saved = { rank = ns.ProfessionRank, have = ns.CraftData.Have, colors = data.colors[spell], log = ns.db.craftLog,
        off = ns.db.craftLogOff, secret = issecretvalue }
    local SECRET = newproxy(true)
    local rank, maxRank, bag = 10, 75, 0
    ns.ProfessionRank = function(p) if p == "Leatherworking" then return rank, maxRank end end
    ns.CraftData.Have = function(id) if id == 2318 then return bag end return 0 end
    data.colors[spell] = "20:40"
    ns.db.craftLog, ns.db.craftLogOff = {}, nil
    local keepMulti = ns.db.craftMulti ns.db.craftMulti = nil -- (F2: the note of a multi-point craft)
    local n = 0
    local function Guid() n = n + 1 return "Cast-3-1-1-1-" .. spell .. "-f2-" .. n end
    local function Line()
        local mark = #log
        slash("craftlog")
        return table.concat(log, "\n", mark + 1)
    end
    local ok, err = pcall(function()
        -- M1: two crafts, the second ends before the first is read again.
        -- Really: one skill-up, two items. Neither may count as a clear 1/1.
        -- Since K2 (0.1.20) the two are one block: 2 tries, 1 skill-up.
        local g1, g2 = Guid(), Guid()
        fire("UNIT_SPELLCAST_START", "player", g1, spell)
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", g1, spell)
        bag = bag + 1
        advance(0.5)
        fire("UNIT_SPELLCAST_START", "player", g2, spell)
        rank = rank + 1
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", g2, spell)
        bag = bag + 1
        advance(2)
        assert(#ns.db.craftLog == 3, "two chained crafts: " .. #ns.db.craftLog .. " entries (want 2 and their block)")
        for i = 1, 2 do assert(ns.db.craftLog[i].overlap and ns.db.craftLog[i].inSeries, "a chained craft not marked") end
        local block = ns.db.craftLog[3]
        assert(block.kind == "series" and block.n == 2 and block.before == 10 and block.after == 11 and block.gain == 1, "the block of the two")
        local byColour, _, other = ns.CraftLogSummary()
        assert(byColour.orange and byColour.orange.tries == 2 and byColour.orange.ups == 1, ("the block in the rate: %s/%s"):format(
            tostring(byColour.orange and byColour.orange.ups), tostring(byColour.orange and byColour.orange.tries)))
        assert(other.overlap == 0 and other.series == 1, "counted as overlapping although a clear block: " .. tostring(other.overlap))
        local text = Line()
        assert(text:find((ns.L["  Not counted: %d failed or interrupted, %d unreadable, %d overlapping, %d at the rank's maximum; %d gave more than one point."]):format(0, 0, 0, 0, 0), 1, true),
            "/gcr craftlog: the block's crafts named as overlapping: " .. text)
        -- started while the one before was still being read: overlapping too
        local g3, g4 = Guid(), Guid()
        fire("UNIT_SPELLCAST_START", "player", g3, spell)
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", g3, spell)
        advance(0.5)
        fire("UNIT_SPELLCAST_START", "player", g4, spell)
        advance(1.5)
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", g4, spell)
        advance(2)
        assert(ns.db.craftLog[4].overlap and ns.db.craftLog[5].overlap, "a craft started inside the last one's reading: not marked")
        assert(ns.db.craftLog[6] and ns.db.craftLog[6].kind == "series" and ns.db.craftLog[6].n == 2 and ns.db.craftLog[6].gain == 0, "a chained pair without a skill-up: no block of 2 tries, 0 ups")
        -- single crafts with time between them: as before
        ns.db.craftLog = {}
        rank = 10
        local g5 = Guid()
        fire("UNIT_SPELLCAST_START", "player", g5, spell)
        rank = rank + 1 bag = bag + 1
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", g5, spell)
        advance(2)
        local g6 = Guid()
        fire("UNIT_SPELLCAST_START", "player", g6, spell)
        bag = bag + 1
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", g6, spell)
        advance(2)
        byColour = ns.CraftLogSummary()
        assert(byColour.orange and byColour.orange.tries == 2 and byColour.orange.ups == 1, "single crafts no longer counted")
        assert(not ns.db.craftLog[1].overlap and not ns.db.craftLog[2].overlap and ns.db.craftLog[1].made == 1, "single crafts marked")
        -- M2: a hidden cast ID, but a spell that is no recipe (Herbalism): nothing
        issecretvalue = function(v) return rawequal(v, SECRET) end
        local count = #ns.db.craftLog
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", SECRET, 2366)
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", SECRET, 2366)
        advance(2)
        assert(#ns.db.craftLog == count, "a gathering spell with a hidden cast ID in the craft log: " .. (#ns.db.craftLog - count))
        -- spell hidden too: not a craft
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", SECRET, SECRET) advance(2)
        assert(#ns.db.craftLog == count, "a cast with nothing readable stored as a craft")
        -- a real craft with a hidden cast ID, its event twice: one entry
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", SECRET, spell)
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", SECRET, spell)
        advance(2)
        assert(#ns.db.craftLog == count + 1, "a hidden-ID craft twice: " .. (#ns.db.craftLog - count) .. " entries")
        local e = ns.db.craftLog[#ns.db.craftLog]
        assert(e.secret and e.recipe == "Light Leather" and e.gain == nil, "a hidden-ID craft: what it is or that it is unreadable")
        -- V1: the amount in the bags is hidden: unreadable, no error
        local g7 = Guid()
        bag = SECRET
        fire("UNIT_SPELLCAST_START", "player", g7, spell)
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", g7, spell)
        advance(2)
        e = ns.db.craftLog[#ns.db.craftLog]
        assert(e.recipe == "Light Leather" and e.secret and e.made == nil, "a hidden amount: not marked unreadable")
        bag = 5
        local g8 = Guid()
        fire("UNIT_SPELLCAST_START", "player", g8, spell)
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", g8, spell)
        bag = SECRET
        advance(2)
        e = ns.db.craftLog[#ns.db.craftLog]
        assert(e.secret and e.made == nil, "a hidden amount after the craft: not marked unreadable")
        bag = 5
        issecretvalue = saved.secret
        -- N2: clear while a craft is still being read: it stays empty
        local g9 = Guid()
        fire("UNIT_SPELLCAST_START", "player", g9, spell)
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", g9, spell)
        advance(0.5)
        slash("craftlog clear")
        advance(2)
        assert(#ns.db.craftLog == 0, "/gcr craftlog clear: a craft read afterwards came back")
        -- after the clear the log works again
        local g10 = Guid()
        fire("UNIT_SPELLCAST_START", "player", g10, spell)
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", g10, spell)
        advance(2)
        assert(#ns.db.craftLog == 1 and not ns.db.craftLog[1].overlap, "after the clear: no new entry, or marked overlapping")
    end)
    ns.ProfessionRank, ns.CraftData.Have, data.colors[spell] = saved.rank, saved.have, saved.colors
    ns.db.craftLog, ns.db.craftLogOff, issecretvalue = saved.log, saved.off, saved.secret
    ns.db.craftMulti = keepMulti
    if not ok then error(err, 0) end
end)
step("Craft log: a craft with a hidden cast ID marks the one still being read as overlapping (v0.1.18 B1)", function()
    -- Codex round 2 (08.11.): A readable, no skill-up; 0.5 s later B, same
    -- recipe, hidden cast ID, one skill-up. A must not count as 1/1.
    local data = GathercraftRecipeData
    local spell = data.spells.Leatherworking["Light Leather"]
    local saved = { rank = ns.ProfessionRank, have = ns.CraftData.Have, colors = data.colors[spell], log = ns.db.craftLog,
        off = ns.db.craftLogOff, secret = issecretvalue }
    local SECRET = newproxy(true)
    local rank, bag = 10, 0
    ns.ProfessionRank = function(p) if p == "Leatherworking" then return rank, 75 end end
    ns.CraftData.Have = function(id) if id == 2318 then return bag end return 0 end
    data.colors[spell] = "20:40"
    ns.db.craftLog, ns.db.craftLogOff = {}, nil
    local keepMulti = ns.db.craftMulti ns.db.craftMulti = nil -- (F2: the note of a multi-point craft)
    local ok, err = pcall(function()
        issecretvalue = function(v) return rawequal(v, SECRET) end
        fire("UNIT_SPELLCAST_START", "player", "Cast-b1-A", spell)
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", "Cast-b1-A", spell)
        bag = bag + 1
        advance(0.5)
        rank, bag = rank + 1, bag + 1
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", SECRET, spell)
        advance(2)
        assert(#ns.db.craftLog == 2, "entries: " .. #ns.db.craftLog)
        local a = ns.db.craftLog[1].recipe and not ns.db.craftLog[1].secret and ns.db.craftLog[1] or ns.db.craftLog[2]
        assert(a.overlap, ("A was read alone: gain %s, made %s"):format(tostring(a.gain), tostring(a.made)))
        local byColour, _, other = ns.CraftLogSummary()
        assert(not byColour.orange, ("A in the rate: %s/%s"):format(tostring(byColour.orange and byColour.orange.ups),
            tostring(byColour.orange and byColour.orange.tries)))
        assert(other.overlap >= 1, "not counted as overlapping")
        -- the other way round: B hidden first, A readable while nothing is read: A alone counts
        ns.db.craftLog = {}
        advance(3)
        fire("UNIT_SPELLCAST_START", "player", "Cast-b1-C", spell)
        rank, bag = rank + 1, bag + 1
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", "Cast-b1-C", spell)
        advance(2)
        assert(not ns.db.craftLog[1].overlap and ns.db.craftLog[1].gain == 1, "a single readable craft is marked")
    end)
    ns.ProfessionRank, ns.CraftData.Have, data.colors[spell] = saved.rank, saved.have, saved.colors
    ns.db.craftLog, ns.db.craftLogOff, issecretvalue = saved.log, saved.off, saved.secret
    ns.db.craftMulti = keepMulti
    if not ok then error(err, 0) end
end)
step("Craft log: clear while a craft is still being cast drops it too (v0.1.18 B2)", function()
    -- Codex round 2 (08.11.): START, /gcr craftlog clear, SUCCEEDED - the
    -- success made a new entry in the log just emptied
    local data = GathercraftRecipeData
    local spell = data.spells.Leatherworking["Light Leather"]
    local saved = { rank = ns.ProfessionRank, have = ns.CraftData.Have, log = ns.db.craftLog, off = ns.db.craftLogOff }
    ns.ProfessionRank = function(p) if p == "Leatherworking" then return 10, 75 end end
    ns.CraftData.Have = function() return 0 end
    ns.db.craftLog, ns.db.craftLogOff = {}, nil
    local keepMulti = ns.db.craftMulti ns.db.craftMulti = nil -- (F2: the note of a multi-point craft)
    local ok, err = pcall(function()
        advance(3)
        fire("UNIT_SPELLCAST_START", "player", "Cast-b2-A", spell)
        slash("craftlog clear")
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", "Cast-b2-A", spell)
        advance(2)
        assert(#ns.db.craftLog == 0, "a craft cast through the clear came back: " .. #ns.db.craftLog)
        -- a failure of it after the clear: nothing either
        fire("UNIT_SPELLCAST_START", "player", "Cast-b2-B", spell)
        slash("craftlog clear")
        fire("UNIT_SPELLCAST_FAILED", "player", "Cast-b2-B", spell)
        advance(2)
        assert(#ns.db.craftLog == 0, "a failed cast through the clear came back")
        -- a craft started after the clear is logged as usual
        fire("UNIT_SPELLCAST_START", "player", "Cast-b2-C", spell)
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", "Cast-b2-C", spell)
        advance(2)
        assert(#ns.db.craftLog == 1 and ns.db.craftLog[1].recipe == "Light Leather", "a craft after the clear is not logged")
    end)
    ns.ProfessionRank, ns.CraftData.Have = saved.rank, saved.have
    ns.db.craftLog, ns.db.craftLogOff = saved.log, saved.off
    ns.db.craftMulti = keepMulti
    if not ok then error(err, 0) end
end)
step("Craft log: a Create All series counts as one block, only when it is clear (v0.1.20 K2)", function()
    -- Sven (09.11.): 10 cooks, 3 alone (orange, 3/3), 7 by Create All -
    -- every one gave a point, all 7 landed under "overlapping"
    local data = GathercraftRecipeData
    local spell, other = data.spells.Leatherworking["Light Leather"], data.spells.Leatherworking["Light Armor Kit"]
    local saved = { rank = ns.ProfessionRank, have = ns.CraftData.Have, colors = data.colors[spell], colors2 = data.colors[other],
        log = ns.db.craftLog, off = ns.db.craftLogOff, secret = issecretvalue }
    local SECRET = newproxy(true)
    local rank, maxRank = 10, 75
    ns.ProfessionRank = function(p) if p == "Leatherworking" then return rank, maxRank end end
    ns.CraftData.Have = function() return 0 end
    data.colors[spell], data.colors[other] = "25:45", "25:45" -- orange below 25, yellow below 45, grey from 45
    ns.db.craftLog, ns.db.craftLogOff = {}, nil
    local keepMulti = ns.db.craftMulti ns.db.craftMulti = nil -- (F2: the note of a multi-point craft)
    local n = 0
    local function Guid() n = n + 1 return "Cast-k2-" .. n end
    -- one craft: START, the cast time, SUCCEEDED (or what `events` says); the skill rises by `gain`
    local function Cast(gain, castTime, events, sp)
        sp = sp or spell
        local guid = Guid()
        events = events or { "UNIT_SPELLCAST_START", "UNIT_SPELLCAST_SUCCEEDED" }
        for i, e in ipairs(events) do
            if i > 1 and castTime and castTime > 0 then advance(castTime) end
            if e == "UNIT_SPELLCAST_SUCCEEDED" and gain and gain ~= 0 then rank = rank + gain end
            fire(e, "player", guid, sp)
        end
        return guid
    end
    -- a Create All series: the next cast starts right after the last success
    local function Series(gains, castTime, sp)
        for _, g in ipairs(gains) do Cast(g, castTime, nil, sp) advance(0.3) end
        advance(2)
    end
    local function Blocks()
        local list = {}
        for _, e in ipairs(ns.db.craftLog) do if e.kind == "series" then list[#list + 1] = e end end
        return list
    end
    local function Reset(skill) ns.db.craftLog = {} rank = skill advance(3) end
    local function Text()
        local mark = #log
        slash("craftlog")
        return table.concat(log, "\n", mark + 1)
    end
    local ok, err = pcall(function()
        -- (1) Sven's case: 3 alone, then 7 by Create All, every one a point (13 -> 20, all orange)
        advance(3)
        for _ = 1, 3 do Cast(1) advance(2) end
        Series({ 1, 1, 1, 1, 1, 1, 1 })
        local blocks = Blocks()
        assert(#blocks == 1, "blocks: " .. #blocks)
        local b = blocks[1]
        assert(b.n == 7 and b.before == 13 and b.after == 20 and b.gain == 7 and b.colour == "orange" and b.recipe == "Light Leather" and b.prof == "Leatherworking", ("the block: n %s, %s -> %s, gain %s, %s"):format(tostring(b.n), tostring(b.before), tostring(b.after), tostring(b.gain), tostring(b.colour)))
        assert(b.yellow == 25 and b.grey == 45 and b.max == 75 and b.t and b.build == 70450 and b.result == "ok", "the block's thresholds, max, time or build")
        assert(#ns.db.craftLog == 3 + 7 + 1, "entries: " .. #ns.db.craftLog)
        local inSeries = 0
        for _, e in ipairs(ns.db.craftLog) do if e.inSeries then assert(e.overlap, "a series craft not marked overlapping") inSeries = inSeries + 1 end end
        assert(inSeries == 7, "crafts counted by the block: " .. inSeries)
        local byColour, byGap, others = ns.CraftLogSummary()
        assert(byColour.orange and byColour.orange.tries == 10 and byColour.orange.ups == 10, ("orange %s/%s, want 10/10"):format(tostring(byColour.orange and byColour.orange.ups), tostring(byColour.orange and byColour.orange.tries)))
        assert(others.overlap == 0 and others.series == 1 and others.seriesTries == 7 and others.seriesUps == 7, "the series counts")
        local text = Text()
        assert(text:find((ns.L["  %s: %d crafts, %d skill-ups (%d%%)"]):format("|cffff8040" .. ns.L["orange"] .. "|r", 10, 10, 100), 1, true), "orange line: " .. text)
        assert(text:find((ns.L["  from series (Create All): %d series, %d crafts, %d skill-ups - counted above"]):format(1, 7, 7), 1, true), "no series line: " .. text)
        assert(text:find((ns.L["  Not counted: %d failed or interrupted, %d unreadable, %d overlapping, %d at the rank's maximum; %d gave more than one point."]):format(0, 0, 0, 0, 0), 1, true), "not counted: " .. text)
        -- (2) realistic cast times (3 s): the series is one block too
        Reset(10)
        Series({ 1, 0, 1 }, 3)
        blocks = Blocks()
        assert(#blocks == 1 and blocks[1].n == 3 and blocks[1].gain == 2, "a series with 3 s casts: no block")
        -- a single craft after a pause counts alone
        Cast(1) advance(2)
        byColour = ns.CraftLogSummary()
        assert(byColour.orange.tries == 4 and byColour.orange.ups == 3, "the single after the series")
        -- (3) over a colour change (23 -> 27, yellow from 25): stays overlapping
        Reset(23)
        Series({ 1, 1, 1, 1 })
        assert(#Blocks() == 0, "a block over a colour change")
        byColour, byGap, others = ns.CraftLogSummary()
        assert(not byColour.orange and not byColour.yellow and others.overlap == 4, "a series over a colour change counted")
        assert(#ns.db.craftLog == 4, "entries: " .. #ns.db.craftLog)
        -- (4) over a distance group (33 -> 37: 12 and 8 below grey): stays overlapping
        Reset(33)
        Series({ 1, 1, 1, 1 })
        assert(#Blocks() == 0 and select(3, ns.CraftLogSummary()).overlap == 4, "a block over a distance group")
        -- yellow and the same group throughout (31 -> 33: 14 to 12 below grey): a block, in the 10-14 group
        Reset(31)
        Series({ 1, 0, 1 })
        assert(#Blocks() == 1 and Blocks()[1].colour == "yellow", "a yellow series in one group: no block")
        byColour, byGap = ns.CraftLogSummary()
        assert(byColour.yellow.tries == 3 and byColour.yellow.ups == 2 and byGap[2] and byGap[2].tries == 3 and byGap[2].ups == 2, "the yellow block in colour and distance")
        -- (5) a failed cast inside: no block, the rest overlapping
        Reset(10)
        Cast(1) advance(0.3)
        Cast(0, nil, { "UNIT_SPELLCAST_START", "UNIT_SPELLCAST_FAILED" }) advance(0.3)
        Cast(1) advance(2)
        assert(#Blocks() == 0, "a block with a failure inside")
        byColour, byGap, others = ns.CraftLogSummary()
        assert(others.failed == 1 and others.overlap == 2 and not byColour.orange, "a series with a failure counted")
        -- a failure as the last cast, nothing left to read: the first is marked all the same
        Reset(10)
        Cast(1) advance(1.6)
        assert(not ns.db.craftLog[1].overlap, "test setup: the first alone")
        -- (the first's reading is over; a cast started inside it fails now)
        Reset(10)
        Cast(1) advance(0.3)
        Cast(0, 2, { "UNIT_SPELLCAST_START", "UNIT_SPELLCAST_FAILED" }) advance(2)
        assert(#Blocks() == 0 and ns.db.craftLog[1].overlap and select(3, ns.CraftLogSummary()).overlap == 1, "a failure after the reading left the first as a clear craft")
        -- (6) a hidden cast ID inside: no block
        Reset(10)
        issecretvalue = function(v) return rawequal(v, SECRET) end
        Cast(1) advance(0.3)
        rank = rank + 1
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", SECRET, spell) advance(0.3)
        Cast(1) advance(2)
        issecretvalue = saved.secret
        assert(#Blocks() == 0 and not ns.CraftLogSummary().orange, "a block around a hidden cast ID")
        -- a hidden skill inside: no block
        Reset(10)
        Cast(1) advance(0.3)
        issecretvalue = function(v) return rawequal(v, SECRET) end
        local keep = rank
        rank = SECRET
        Cast(0) advance(0.3)
        rank = keep + 1
        issecretvalue = saved.secret
        Cast(1) advance(2)
        assert(#Blocks() == 0, "a block with a hidden skill inside")
        -- (7) at the rank's maximum (73 -> 75 of 75): no block
        Reset(73)
        Series({ 1, 1, 0 })
        assert(#Blocks() == 0 and select(3, ns.CraftLogSummary()).overlap == 3, "a block at the maximum")
        -- (8) more points than casts (k > n): no block
        Reset(10)
        Series({ 2, 2 })
        assert(#Blocks() == 0, "a block with more points than casts")
        -- (9) mixed recipes: no block, all overlapping
        Reset(10)
        Cast(1) advance(0.3)
        Cast(1, nil, nil, other) advance(0.3)
        Cast(1) advance(2)
        assert(#Blocks() == 0 and select(3, ns.CraftLogSummary()).overlap == 3, "a block of mixed recipes")
        -- two chained, then another recipe inside the last reading: the series is broken, no block of the two
        Reset(10)
        Cast(1) advance(0.3) Cast(1) advance(0.3)
        Cast(1, nil, nil, other) advance(2)
        assert(#Blocks() == 0 and select(3, ns.CraftLogSummary()).overlap == 3, "a block of two with another recipe chained after them")
        -- two chained, then a hidden cast ID inside the last reading (no point
        -- from it, so only the shared reading tells): the same
        Reset(10)
        Cast(1) advance(0.3) Cast(1) advance(0.3)
        issecretvalue = function(v) return rawequal(v, SECRET) end
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", SECRET, spell) advance(2)
        issecretvalue = saved.secret
        assert(#Blocks() == 0 and not ns.CraftLogSummary().orange, "a block of two with a hidden cast ID after them")
        -- (10) clear in the middle of a series: no block; what comes after counts anew
        Reset(10)
        Cast(1) advance(0.3)
        Cast(1) advance(0.3)
        slash("craftlog clear")
        advance(2) -- (since 0.1.21, T8: the cleared crafts' points may still be on the way)
        Cast(1) advance(2)
        assert(#ns.db.craftLog == 1 and not ns.db.craftLog[1].kind and not ns.db.craftLog[1].overlap and ns.db.craftLog[1].gain == 1, "after a clear in a series: " .. #ns.db.craftLog .. " entries")
        Cast(1) advance(0.3) Cast(1) advance(2)
        assert(#Blocks() == 1 and Blocks()[1].n == 2, "a series after the clear: no block")
        -- (11) recording off: no block either; turned off in the middle of a series: no block
        Reset(10)
        ns.db.craftLogOff = true
        Series({ 1, 1 })
        assert(#ns.db.craftLog == 0, "recorded although turned off")
        ns.db.craftLogOff = nil
        Cast(1) advance(0.3) Cast(1) advance(0.3)
        ns.db.craftLogOff = true
        advance(2)
        assert(#Blocks() == 0, "a block written although recording was turned off during the series")
        ns.db.craftLogOff = nil
    end)
    ns.ProfessionRank, ns.CraftData.Have, data.colors[spell], data.colors[other] = saved.rank, saved.have, saved.colors, saved.colors2
    ns.db.craftLog, ns.db.craftLogOff, issecretvalue = saved.log, saved.off, saved.secret
    ns.db.craftMulti = keepMulti
    advance(3)
    if not ok then error(err, 0) end
end)
step("Craft log: switching the recording off or on is a hard break (v0.1.20 F1)", function()
    -- Codex 09.11., B1: a cast left open over the switch held the series
    -- for ever (later crafts each read the same end skill: orange 4/4), and
    -- another recipe's craft while off was counted into the first one's series
    local data = GathercraftRecipeData
    local spell, other = data.spells.Leatherworking["Light Leather"], data.spells.Leatherworking["Light Armor Kit"]
    local saved = { rank = ns.ProfessionRank, have = ns.CraftData.Have, colors = data.colors[spell], colors2 = data.colors[other],
        log = ns.db.craftLog, off = ns.db.craftLogOff, multi = ns.db.craftMulti }
    local rank = 10
    ns.ProfessionRank = function(p) if p == "Leatherworking" then return rank, 75 end end
    ns.CraftData.Have = function() return 0 end
    data.colors[spell], data.colors[other] = "25:45", "25:45"
    ns.db.craftLog, ns.db.craftLogOff, ns.db.craftMulti = {}, nil, nil
    local n = 0
    local function Guid() n = n + 1 return "Cast-f1-" .. n end
    local function Start(sp) local g = Guid() fire("UNIT_SPELLCAST_START", "player", g, sp or spell) return g end
    local function Done(g, gain, sp) rank = rank + (gain or 0) fire("UNIT_SPELLCAST_SUCCEEDED", "player", g, sp or spell) end
    local function Blocks()
        local list = {}
        for _, e in ipairs(ns.db.craftLog) do if e.kind == "series" then list[#list + 1] = e end end
        return list
    end
    local ok, err = pcall(function()
        advance(3)
        -- Probe A: A +1; 0.3 s later B starts (the series is open); A is read;
        -- recording off; B succeeds (ignored); on again; three quick crafts 0, 0, +1
        Done(Start(), 1) advance(0.3)
        local b = Start()
        advance(2)
        ns.db.craftLogOff = true
        Done(b, 0)
        ns.db.craftLogOff = nil
        -- (2 s: since 0.1.21 a craft that starts right after one the log did
        -- not read - B - has no reliable "before": its own step, T8)
        advance(2)
        for _, gain in ipairs({ 0, 0, 1 }) do Done(Start(), gain) advance(0.3) end
        advance(2)
        local byColour, _, others = ns.CraftLogSummary()
        local o = byColour.orange
        assert(not (o and o.tries == 4 and o.ups == 4), "Probe A: orange 4/4 - the three crafts after the switch each counted the one point")
        local blocks = Blocks()
        assert(#blocks == 1 and blocks[1].n == 3 and blocks[1].gain == 1, ("Probe A: the three crafts after the switch are not one block of 3 tries, 1 point (%d blocks)"):format(#blocks))
        assert(o and o.tries == 3 and o.ups == 1, ("Probe A: orange %s/%s, want 1/3"):format(tostring(o and o.ups), tostring(o and o.tries)))
        assert(ns.db.craftLog[1].overlap and not ns.db.craftLog[1].inSeries and others.overlap == 1, "Probe A: A, whose series the switch broke, is not left as overlapping")
        -- B (cast through the switch) is in no entry: 1 (A) + 3 + their block
        assert(#ns.db.craftLog == 5, "Probe A: entries " .. #ns.db.craftLog)
        -- Probe B: two quick crafts without a point; while they are read: off,
        -- another recipe +1, on again before the last reading
        ns.db.craftLog = {}
        advance(3)
        Done(Start(), 0) advance(0.3)
        Done(Start(), 0) advance(0.3)
        ns.db.craftLogOff = true
        Done(Start(other), 1, other)
        ns.db.craftLogOff = nil
        advance(3)
        assert(#Blocks() == 0, "Probe B: a series for the first recipe (n " .. tostring(Blocks()[1] and Blocks()[1].n) .. ", gain " .. tostring(Blocks()[1] and Blocks()[1].gain) .. ")")
        byColour = ns.CraftLogSummary()
        assert(not byColour.orange, "Probe B: the first recipe's crafts counted with the other one's point")
        for _, e in ipairs(ns.db.craftLog) do assert(e.spell ~= other, "Probe B: the craft made while off is in the log") end
        -- a cast started while off and finished after switching on: no craft
        ns.db.craftLog = {}
        advance(3)
        ns.db.craftLogOff = true
        local c = Start()
        ns.db.craftLogOff = nil
        Done(c, 1) advance(2)
        assert(#ns.db.craftLog == 0, "a cast started while off was logged after switching on")
        -- the option's switch itself, no event between off and on: the open cast and reading are gone
        local box
        for _, f in ipairs(allFrames) do
            if f.__kind == "FontString" and f:GetText() == ns.L["Record crafting skill-ups (helps improve the skill plan)"] and f.__pts and f.__pts.LEFT then
                box = f.__pts.LEFT[1]
            end
        end
        assert(box and box.get and box.__scripts.OnClick, "test setup: the option's switch")
        Done(Start(), 1) advance(0.3)
        local d = Start()
        box:SetChecked(false) box.__scripts.OnClick(box)
        assert(ns.db.craftLogOff, "test setup: the switch did not turn it off")
        box:SetChecked(true) box.__scripts.OnClick(box)
        assert(not ns.db.craftLogOff, "test setup: the switch did not turn it on")
        Done(d, 1) advance(3)
        assert(#ns.db.craftLog == 0, "off and on by the option: " .. #ns.db.craftLog .. " entries of crafts open over the switch")
        -- after all that a single craft counts as ever
        Done(Start(), 1) advance(2)
        assert(#ns.db.craftLog == 1 and not ns.db.craftLog[1].overlap and ns.db.craftLog[1].gain == 1, "a single craft after the switches")
    end)
    ns.ProfessionRank, ns.CraftData.Have, data.colors[spell], data.colors[other] = saved.rank, saved.have, saved.colors, saved.colors2
    ns.db.craftLog, ns.db.craftLogOff, ns.db.craftMulti = saved.log, saved.off, saved.multi
    advance(3)
    if not ok then error(err, 0) end
end)
step("Craft log: a series' points are its successes only while no craft ever gave more than one (v0.1.20 F2)", function()
    -- Codex 09.11., B2: +2 and +0 counted as a series 2/2, alone 1/2. Sven:
    -- in WoW: Forever a craft gives at most one point - so k points are k
    -- successes, as long as that is never seen to be wrong.
    local data = GathercraftRecipeData
    local spell = data.spells.Leatherworking["Light Leather"]
    local cookKey, cook = next(data.spells.Cooking)
    local saved = { rank = ns.ProfessionRank, have = ns.CraftData.Have, colors = data.colors[spell], colors2 = data.colors[cook],
        log = ns.db.craftLog, off = ns.db.craftLogOff, multi = ns.db.craftMulti }
    local rank, cooking = 10, 10
    ns.ProfessionRank = function(p)
        if p == "Leatherworking" then return rank, 75 end
        if p == "Cooking" then return cooking, 75 end
    end
    ns.CraftData.Have = function() return 0 end
    data.colors[spell], data.colors[cook] = "25:45", "25:45"
    ns.db.craftLog, ns.db.craftLogOff, ns.db.craftMulti = {}, nil, nil
    local n = 0
    local function Cast(gain, castTime, sp)
        n = n + 1
        local guid = "Cast-f2k-" .. n
        fire("UNIT_SPELLCAST_START", "player", guid, sp or spell)
        if castTime then advance(castTime) end
        if sp == cook then cooking = cooking + gain else rank = rank + gain end
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", guid, sp or spell)
    end
    local function Series(gains, castTime, sp)
        for _, g in ipairs(gains) do Cast(g, castTime, sp) advance(0.3) end
        advance(2)
    end
    local function Blocks()
        local list = {}
        for _, e in ipairs(ns.db.craftLog) do if e.kind == "series" then list[#list + 1] = e end end
        return list
    end
    local function Fresh(skill) ns.db.craftLog = {} rank = skill or 10 advance(3) end
    local function Text()
        local mark = #log
        slash("craftlog")
        return table.concat(log, "\n", mark + 1)
    end
    local HINT = (ns.L["  Series of %s are not counted: a craft there gave more than one point."]):format(ns.L["Leatherworking"])
    local ok, err = pcall(function()
        assert(cook and cookKey, "test setup: no Cooking recipe")
        advance(3)
        -- +1 / +1: 2 of 2 (the first one's reading holds both points - no proof of a double)
        Series({ 1, 1 })
        local byColour = ns.CraftLogSummary()
        assert(#Blocks() == 1 and byColour.orange and byColour.orange.tries == 2 and byColour.orange.ups == 2, "+1/+1 is not 2/2")
        assert(not ns.db.craftMulti, "+1/+1 read together was taken for a multi-point craft")
        -- +1 / +0 / +1, never a multi-point craft seen: 2 of 3
        Fresh()
        Series({ 1, 0, 1 }, 3)
        byColour = ns.CraftLogSummary()
        assert(#Blocks() == 1 and Blocks()[1].n == 3 and Blocks()[1].gain == 2, "+1/+0/+1: no block of 3 tries, 2 points")
        assert(byColour.orange.tries == 3 and byColour.orange.ups == 2, ("+1/+0/+1: orange %d/%d, want 2/3"):format(byColour.orange.ups, byColour.orange.tries))
        assert(not Text():find(HINT, 1, true), "the hint without a multi-point craft")
        -- Codex' probe: +2 then +0; the second starts inside the first one's
        -- reading and takes 3 s, so the first is read alone: its +2 is its own
        Fresh()
        Cast(2) advance(0.3)
        Cast(0, 3) advance(2)
        assert(#Blocks() == 0, "+2/+0 counted as a series " .. tostring(Blocks()[1] and Blocks()[1].gain) .. "/" .. tostring(Blocks()[1] and Blocks()[1].n))
        local _, _, others
        byColour, _, others = ns.CraftLogSummary()
        assert(not byColour.orange and others.overlap == 2, "+2/+0: not left as overlapping")
        assert(ns.db.craftMulti and ns.db.craftMulti.Leatherworking, "the multi-point craft is not noted for the profession")
        assert(Text():find(HINT, 1, true), "/gcr craftlog does not say that series are no longer counted")
        -- from then on: series of the profession stay overlapping
        Fresh()
        Series({ 1, 1 })
        byColour, _, others = ns.CraftLogSummary()
        assert(#Blocks() == 0 and not byColour.orange and others.overlap == 2, "a series after the multi-point craft was counted")
        -- another profession is not touched by it
        Series({ 1, 1 }, nil, cook)
        local blocks = Blocks()
        assert(#blocks == 1 and blocks[1].prof == "Cooking" and blocks[1].gain == 2, "a Cooking series stopped by Leatherworking's note")
        -- clear forgets the note with everything else
        slash("craftlog clear")
        assert(ns.db.craftMulti == nil, "clear kept the note")
        advance(3)
        Series({ 1, 1 })
        assert(#Blocks() == 1, "after the clear a clean series is not counted")
        -- a single multi-point craft: later blocks overlapping
        Fresh()
        Cast(2) advance(2)
        assert(ns.db.craftLog[1].multi and ns.db.craftMulti and ns.db.craftMulti.Leatherworking, "a single +2 is not noted")
        Series({ 1, 0, 1 })
        byColour, _, others = ns.CraftLogSummary()
        assert(#Blocks() == 0 and others.overlap == 3, "a block after a single multi-point craft")
        assert(byColour.orange and byColour.orange.tries == 1 and byColour.orange.ups == 1 and others.multi == 1, "the single +2 itself: one try, one success, named apart")
        -- a log of 0.1.18 / 0.1.19 with such a craft, no note yet: found in the log
        Fresh()
        ns.db.craftMulti = nil
        ns.db.craftLog = { { t = 1, result = "ok", prof = "Leatherworking", spell = spell, colour = "orange", before = 5, after = 7, gain = 2, multi = true, yellow = 25, grey = 45, max = 75 } }
        Series({ 1, 1 })
        assert(#Blocks() == 0 and ns.db.craftMulti and ns.db.craftMulti.Leatherworking, "an old multi-point entry in the log does not stop the series")
        -- an overlapping old entry with two points proves nothing
        Fresh()
        ns.db.craftMulti = nil
        ns.db.craftLog = { { t = 1, result = "ok", prof = "Leatherworking", spell = spell, colour = "orange", before = 5, after = 7, gain = 2, multi = true, overlap = true, yellow = 25, grey = 45, max = 75 } }
        Series({ 1, 1 })
        assert(#Blocks() == 1 and not ns.db.craftMulti, "an overlapping two-point reading was taken for proof")
    end)
    ns.ProfessionRank, ns.CraftData.Have, data.colors[spell], data.colors[cook] = saved.rank, saved.have, saved.colors, saved.colors2
    ns.db.craftLog, ns.db.craftLogOff, ns.db.craftMulti = saved.log, saved.off, saved.multi
    advance(3)
    if not ok then error(err, 0) end
end)
step("Craft log: the header counts crafts, a block and its casts once (v0.1.20 F3)", function()
    -- Codex 09.11., B3: 3 single crafts and 7 by Create All said "11 crafts"
    local data = GathercraftRecipeData
    local spell = data.spells.Leatherworking["Light Leather"]
    local saved = { rank = ns.ProfessionRank, have = ns.CraftData.Have, colors = data.colors[spell], log = ns.db.craftLog, off = ns.db.craftLogOff, multi = ns.db.craftMulti }
    local rank = 10
    ns.ProfessionRank = function(p) if p == "Leatherworking" then return rank, 75 end end
    ns.CraftData.Have = function() return 0 end
    data.colors[spell] = "25:45"
    ns.db.craftLog, ns.db.craftLogOff, ns.db.craftMulti = {}, nil, nil
    local n = 0
    local function Cast(gain)
        n = n + 1
        fire("UNIT_SPELLCAST_START", "player", "Cast-f3-" .. n, spell)
        rank = rank + gain
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", "Cast-f3-" .. n, spell)
    end
    local function Header()
        local mark = #log
        slash("craftlog")
        return table.concat(log, "\n", mark + 1)
    end
    local function Says(count) return (ns.L["Craft log: %d crafts (kept on this computer, never shared)."]):format(count) end
    local ok, err = pcall(function()
        advance(3)
        for _ = 1, 3 do Cast(1) advance(2) end
        for _ = 1, 7 do Cast(1) advance(0.3) end
        advance(2)
        assert(#ns.db.craftLog == 11, "test setup: 3 singles, 7 series casts and their block: " .. #ns.db.craftLog)
        local text = Header()
        assert(text:find(Says(10), 1, true), "the header does not say 10 crafts: " .. text:sub(1, 120))
        assert(not text:find(Says(11), 1, true), "the header counts the block as a craft")
        -- a failed cast is no craft (since 0.1.21, T7: finished crafts only)
        fire("UNIT_SPELLCAST_START", "player", "Cast-f3-x", spell)
        fire("UNIT_SPELLCAST_FAILED", "player", "Cast-f3-x", spell)
        assert(Header():find(Says(10), 1, true), "a failed cast is counted as a craft")
        -- a full log that has lost the oldest casts of a block: the block still stands for all of them
        ns.db.craftLog = {
            { t = 3, result = "ok", prof = "Leatherworking", spell = spell, colour = "orange", before = 12, after = 13, gain = 1, overlap = true, inSeries = true },
            { kind = "series", t = 1, result = "ok", prof = "Leatherworking", spell = spell, colour = "orange", n = 7, before = 6, after = 13, gain = 7, yellow = 25, grey = 45, max = 75 },
            { t = 9, result = "ok", prof = "Leatherworking", spell = spell, colour = "orange", before = 13, after = 14, gain = 1, yellow = 25, grey = 45, max = 75 },
        }
        assert(Header():find(Says(8), 1, true), "a block whose oldest casts left the log: not 7 + 1 crafts")
        local byColour = ns.CraftLogSummary()
        assert(byColour.orange.tries == 8, "header and colour line disagree")
        -- an empty log says 0
        ns.db.craftLog = {}
        assert(Header():find(Says(0), 1, true), "an empty log")
    end)
    ns.ProfessionRank, ns.CraftData.Have, data.colors[spell] = saved.rank, saved.have, saved.colors
    ns.db.craftLog, ns.db.craftLogOff, ns.db.craftMulti = saved.log, saved.off, saved.multi
    advance(3)
    if not ok then error(err, 0) end
end)
step("Craft log: an orange block needs no distance group and never goes into a distance line (v0.1.20 F4)", function()
    -- Codex 09.11., B4: thresholds 55:60, skill 50 -> 53: orange throughout,
    -- 10 to 7 below grey (two groups). Accepted on purpose - orange always
    -- gives its point and is not in the distance statistic.
    local data = GathercraftRecipeData
    local spell = data.spells.Leatherworking["Light Leather"]
    local saved = { rank = ns.ProfessionRank, have = ns.CraftData.Have, colors = data.colors[spell], log = ns.db.craftLog, off = ns.db.craftLogOff, multi = ns.db.craftMulti }
    local rank = 50
    ns.ProfessionRank = function(p) if p == "Leatherworking" then return rank, 75 end end
    ns.CraftData.Have = function() return 0 end
    data.colors[spell] = "55:60"
    ns.db.craftLog, ns.db.craftLogOff, ns.db.craftMulti = {}, nil, nil
    local n = 0
    local function Series(gains)
        for _, gain in ipairs(gains) do
            n = n + 1
            fire("UNIT_SPELLCAST_START", "player", "Cast-f4-" .. n, spell)
            rank = rank + gain
            fire("UNIT_SPELLCAST_SUCCEEDED", "player", "Cast-f4-" .. n, spell)
            advance(0.3)
        end
        advance(2)
    end
    local ok, err = pcall(function()
        advance(3)
        Series({ 1, 1, 1 })
        local byColour, byGap, others = ns.CraftLogSummary()
        assert(others.series == 1 and byColour.orange and byColour.orange.tries == 3 and byColour.orange.ups == 3, "the orange block over two distance groups is not counted")
        assert(next(byGap) == nil, "an orange block went into a distance line")
        local mark = #log
        slash("craftlog")
        local text = table.concat(log, "\n", mark + 1)
        for _, group in ipairs({ "0-4", "5-9", "10-14", "15-19", "20+" }) do
            assert(not text:find((ns.L["  %s points below grey: %d crafts, %d skill-ups (%d%%)"]):format(group, 3, 3, 100), 1, true), "a distance line from the orange block: " .. group)
        end
        -- yellow/green keeps the rule: 55 -> 57 is 5 to 3 below grey, two groups: no block
        ns.db.craftLog = {}
        rank = 55
        advance(3)
        Series({ 1, 1 })
        byColour, byGap, others = ns.CraftLogSummary()
        assert(others.series == 0 and others.overlap == 2 and next(byGap) == nil, "a yellow block over two distance groups")
        -- and inside one group (56 -> 57: 4 and 3 below grey) it counts, in its line
        ns.db.craftLog = {}
        rank = 56
        advance(3)
        Series({ 1, 0 })
        byColour, byGap, others = ns.CraftLogSummary()
        assert(others.series == 1 and byGap[0] and byGap[0].tries == 2 and byGap[0].ups == 1, "a yellow block inside one distance group")
    end)
    ns.ProfessionRank, ns.CraftData.Have, data.colors[spell] = saved.rank, saved.have, saved.colors
    ns.db.craftLog, ns.db.craftLogOff, ns.db.craftMulti = saved.log, saved.off, saved.multi
    advance(3)
    if not ok then error(err, 0) end
end)
step("Craft log: no green threshold is made up; yellow/green is one honest line (v0.1.20 K3)", function()
    -- skill plan 2.0 concept 4.1: the shipped colours are yellow and grey
    -- only. The distance to grey stays the real statistic.
    local data = GathercraftRecipeData
    local spell = data.spells.Leatherworking["Light Leather"]
    local saved = { rank = ns.ProfessionRank, have = ns.CraftData.Have, colors = data.colors[spell], log = ns.db.craftLog, off = ns.db.craftLogOff }
    local rank = 35
    ns.ProfessionRank = function(p) if p == "Leatherworking" then return rank, 75 end end
    ns.CraftData.Have = function() return 0 end
    data.colors[spell] = "20:40"
    ns.db.craftLog, ns.db.craftLogOff = {}, nil
    local keepMulti = ns.db.craftMulti ns.db.craftMulti = nil -- (F2: the note of a multi-point craft)
    local ok, err = pcall(function()
        advance(3)
        -- 35 of 20:40 was "green" before: now yellow, the thresholds kept as they are
        fire("UNIT_SPELLCAST_START", "player", "Cast-k3-A", spell)
        rank = 36
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", "Cast-k3-A", spell)
        advance(2)
        local e = ns.db.craftLog[1]
        assert(e and e.colour == "yellow" and e.yellow == 20 and e.grey == 40 and e.before == 35, ("colour %s, %s:%s"):format(tostring(e and e.colour), tostring(e and e.yellow), tostring(e and e.grey)))
        -- 20 (the threshold itself) is yellow, 39 is yellow, 40 is grey
        rank = 20
        fire("UNIT_SPELLCAST_START", "player", "Cast-k3-B", spell) fire("UNIT_SPELLCAST_SUCCEEDED", "player", "Cast-k3-B", spell) advance(2)
        rank = 39
        fire("UNIT_SPELLCAST_START", "player", "Cast-k3-C", spell) fire("UNIT_SPELLCAST_SUCCEEDED", "player", "Cast-k3-C", spell) advance(2)
        rank = 40
        fire("UNIT_SPELLCAST_START", "player", "Cast-k3-D", spell) fire("UNIT_SPELLCAST_SUCCEEDED", "player", "Cast-k3-D", spell) advance(2)
        assert(ns.db.craftLog[2].colour == "yellow" and ns.db.craftLog[3].colour == "yellow" and ns.db.craftLog[4].colour == "grey", "the thresholds")
        -- an entry of 0.1.18 still saying "green": counted with yellow, never on a line of its own
        table.insert(ns.db.craftLog, { t = 1, result = "ok", colour = "green", before = 34, after = 35, gain = 1, yellow = 20, grey = 40, max = 75 })
        local byColour = ns.CraftLogSummary()
        assert(byColour.yellow and byColour.yellow.tries == 4 and byColour.yellow.ups == 2, ("yellow: %s/%s"):format(tostring(byColour.yellow and byColour.yellow.ups), tostring(byColour.yellow and byColour.yellow.tries)))
        assert(not byColour.green, "a green line of its own")
        local mark = #log
        slash("craftlog")
        local text = table.concat(log, "\n", mark + 1)
        assert(text:find((ns.L["  %s: %d crafts, %d skill-ups (%d%%)"]):format("|cffffff00" .. ns.L["yellow/green"] .. "|r", 4, 2, 50), 1, true), "no yellow/green line: " .. text)
        assert(not text:find("|cff40c040", 1, true), "a green line in /gcr craftlog: " .. text)
        -- the distance to grey is still counted (5 below grey: 35 and 34 -> 5-9; 39 -> 0-4)
        assert(text:find((ns.L["  %s points below grey: %d crafts, %d skill-ups (%d%%)"]):format("5-9", 2, 2, 100), 1, true), "distance line: " .. text)
    end)
    ns.ProfessionRank, ns.CraftData.Have, data.colors[spell] = saved.rank, saved.have, saved.colors
    ns.db.craftLog, ns.db.craftLogOff = saved.log, saved.off
    ns.db.craftMulti = keepMulti
    if not ok then error(err, 0) end
end)
step("Sharing counts what other players sent, over all sessions (v0.1.18 S7)", function()
    local db = ns.db.sync
    local saved = { counts = db.counts, enabled = db.enabled, public = db.public, friend = C_FriendList.GetFriendInfo }
    db.enabled, db.public, db.counts = true, true, nil
    local Z = 1463
    ns.db.nodes[Z] = {}
    local function Send(id, x, who, where)
        local text = ("N:%d;%s,h,%d,5000,2447"):format(Z, id, x)
        if where == "GUILD" then
            fire("CHAT_MSG_ADDON", "Gathercraft", text, "GUILD", who)
        else
            fire("CHAT_MSG_ADDON", "Gathercraft", text, "CHANNEL", who, nil, nil, nil, "GathercraftSync")
        end
        advance(1)
    end
    local function Counts(what, received, new, confirmed, trusted, public)
        local r, n, c, t, p = ns.SyncCounts()
        assert(r == received and n == new and c == confirmed and t == trusted and p == public,
            ("%s: received %d, new %d, confirmed %d, guild/friends %d, public %d"):format(what, r, n, c, t, p))
    end
    local ok, err = pcall(function()
        -- a guild member: a new spot at once
        Send("o3001", 1000, "Guild Mate", "GUILD")
        Counts("guild", 1, 1, 0, 1, 0)
        -- the same message again: nothing more
        Send("o3001", 1000, "Guild Mate", "GUILD")
        Counts("the same message twice", 1, 1, 0, 1, 0)
        -- public: one report, two reports, waiting; the third takes it
        Send("o3002", 3000, "Stranger One")
        Counts("public, 1 report", 1, 1, 0, 1, 0)
        Send("o3002", 3000, "Stranger One") -- one player twice is still one report
        Send("o3002", 3000, "Stranger Two")
        Counts("public, 2 reports", 1, 1, 0, 1, 0)
        Send("o3002", 3000, "Stranger Three")
        Counts("public, 3 reports", 2, 2, 0, 1, 1)
        -- someone new reports a spot you know: a confirmation, once per player
        Send("o3001", 1000, "Stranger Four")
        Counts("a known spot", 3, 2, 1, 1, 1)
        Send("o3001", 1000, "Stranger Four")
        Send("o3002", 3000, "Stranger Two") -- already one of its reporters
        Counts("the same players again", 3, 2, 1, 1, 1)
        -- a friend in the public channel counts like the guild
        C_FriendList.GetFriendInfo = function(name) if name == "Good Friend" then return { name = name } end end
        Send("o3003", 5000, "Good Friend")
        Counts("a friend", 4, 3, 1, 2, 1)
        C_FriendList.GetFriendInfo = saved.friend
        -- one report waiting: shown as waiting, not counted
        Send("o3004", 7000, "Stranger Five")
        Counts("waiting", 4, 3, 1, 2, 1)
        -- kept over sessions: in the saved variables
        assert(ns.db.sync.counts and ns.db.sync.counts.received == 4, "not in the saved variables")
        -- /gcr sync and Options > Sharing
        local mark = #log
        slash("sync")
        local said
        local want = (ns.L["  Received from other players (all sessions): %d spots, %d new (%d guild/friends, %d public, confirmed), %d confirm spots you know"]):format(4, 3, 2, 1, 1)
        for i = mark + 1, #log do if log[i]:find(want, 1, true) then said = true end end
        assert(said, "/gcr sync: " .. want)
        -- the Sharing section, also when an earlier step left the options open elsewhere
        local win = _G.GathercraftOptions
        local wasOpen, wasSection = win:IsShown(), ns.db.optionsSection
        if not wasOpen then ns.ToggleOptions() end
        ns.ShowOptionsSection("sync")
        win:Refresh()
        advance(1)
        local line = (ns.L["Received from other players: %d spots (%d new)"]):format(4, 3)
        local shown
        for _, o in ipairs(allFrames) do
            local t = o.GetText and o:GetText()
            if type(t) == "string" and t:find(line, 1, true) and o:IsShown() then shown = true end
        end
        assert(shown, "Options > Sharing: " .. line)
        -- no names in the options
        for _, o in ipairs(allFrames) do
            local t = o.GetText and o:IsShown() and o:GetText()
            if type(t) == "string" and t:find(line, 1, true) then assert(not t:find("Stranger", 1, true), "a name in the options") end
        end
        ns.ShowOptionsSection(wasSection or "map")
        if not wasOpen then ns.ToggleOptions() end
    end)
    C_FriendList.GetFriendInfo = saved.friend
    db.counts, db.enabled, db.public = saved.counts, saved.enabled, saved.public
    ns.db.nodes[Z] = nil
    if db.pending then db.pending[Z] = nil end
    ns.NotifyNodesChanged()
    if not ok then error(err, 0) end
end)
step("README says what the addon does, no more (v0.1.18 S8)", function()
    local f = assert(io.open(ROOT .. "/README.md"))
    local text = f:read("*a") f:close()
    -- the plan follows your prices: never "the cheapest"
    assert(not text:lower():find("cheapest", 1, true), "README calls the plan the cheapest")
    -- prices: your own scan first, the others only when fresher (Prices.lua, v0.1.16)
    assert(not text:find("only used if you have no scan yet", 1, true) and not text:find("are used until your first own scan", 1, true),
        "README: Auctionator or TSM only until the first scan")
    -- the price order: its own step since F3 (Codex M3)
    assert(text:find("An optional louder splash helps in busy spots.", 1, true), "README: the louder splash")
    local nextUp = text:match("Next up.-\n\n(.-)\n\n")
    -- (0.2.0: the rebuilt skill plan is published - it stands under "Live now", see the release step)
    assert(nextUp and not nextUp:find("Skill plan rebuilt", 1, true) and nextUp:find("Smoother Loop routes", 1, true)
        and nextUp:find("Disenchant values", 1, true) and nextUp:find("new Forever zones", 1, true), "README: Next up")
end)
step("README: the price text says what Prices.lua does (v0.1.18 F3)", function()
    -- Codex M3 (08.11.): "Auctionator or TSM only fill in when they have a
    -- fresher price" - TSM never wins on freshness. The rule, from the code:
    local f = assert(io.open(ROOT .. "/Prices.lua"))
    local code = f:read("*a") f:close()
    local fresh = tonumber(code:match("local FRESH_PRICE = (%d+) %* 3600"))
    local maxAge = tonumber(code:match("local MAX_PRICE_AGE = (%d+) %* 86400"))
    assert(fresh and maxAge, "test setup: the price ages in Prices.lua")
    -- only Auctionator is compared by age; TSM is a fallback only
    assert(code:find('local other = age >= FRESH_PRICE and AuctionatorPrice(itemID)', 1, true), "test setup: the Auctionator age check")
    f = assert(io.open(ROOT .. "/README.md"))
    local text = f:read("*a") f:close()
    local first, fallback = 0, 0
    -- every sentence about the price sources
    for sentence in (text:gsub("\n", " ")):gmatch("[^%.%?!]+") do
        local s = sentence:lower()
        if s:find("tsm", 1, true) then
            assert(not s:find("fresh", 1, true) and not s:find("newer", 1, true) and not s:find("recent", 1, true),
                "README: TSM described as fresher: " .. sentence)
            if s:find(("%d days"):format(maxAge), 1, true) then fallback = fallback + 1 end
        end
        if s:find("scan comes first", 1, true) then
            first = first + 1
            assert(s:find(("%d hours"):format(fresh), 1, true) and s:find("fresher auctionator", 1, true),
                ("README: not that a fresher Auctionator price may take over after %d hours: %s"):format(fresh, sentence))
        end
    end
    -- in both places (features and FAQ)
    assert(first == 2, "README: your own scan first, then a fresher Auctionator: " .. first .. " times")
    assert(fallback == 2, ("README: Auctionator or TSM fill in without an own scan of the last %d days: %d times"):format(maxAge, fallback))
end)
step("Skill plan: hints, fees and totals fit, also long translations and big amounts (v0.1.14)", function()
    -- no real font metrics: the estimate of TextHeight (6 px a letter, 11 px
    -- a CJK sign) shows whether the window makes room, not how the game draws it
    local function Px(t)
        t = (t or ""):gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", "")
        local px = 0
        for ch in t:gmatch("[%z\1-\127\194-\244][\128-\191]*") do px = px + (#ch >= 3 and 11 or 6) end
        return px
    end
    local d = ns.CraftData
    local saved = { known = d.Known, have = d.Have, rank = ns.ProfessionRank, price = ns.GetPrice, vendor = ns.db.vendorPrices,
        height = methods.GetStringHeight }
    methods.GetStringHeight = TextHeight
    d.Known = function() return {} end
    d.Have = function() return 0 end
    ns.GetPrice = function() end -- no prices: estimated steps, unknown totals
    ns.db.vendorPrices = {}
    local rank = {}
    ns.ProfessionRank = function(p) if p == rank.prof then return rank[1], rank[2] end end
    local scroll = _G.GathercraftSkillPlanScroll
    local function Check(what)
        local win = _G.GathercraftSkillPlan
        local content
        for _, o in ipairs(allFrames) do if o.__parent == scroll and o.__kind == "Frame" then content = o end end
        assert(content, "test setup: the list of the planner")
        local rows = {}
        for _, o in ipairs(allFrames) do
            if o.__parent == content and o.left and o:IsShown() and o.__pts and o.__pts.TOPLEFT then rows[#rows + 1] = o end
        end
        table.sort(rows, function(a, b) return a.__pts.TOPLEFT[2] > b.__pts.TOPLEFT[2] end)
        local hints = 0
        for i, row in ipairs(rows) do
            local text, y, h = row.left:GetText() or "", -row.__pts.TOPLEFT[2], row.__h or 18
            if (row.right:GetText() or "") == "" then
                -- a hint: the whole width, and as high as its wrapped text
                hints = hints + 1
                assert(row.left.__w >= 480, ("%s: a hint in a narrow column (%d px): %s"):format(what, row.left.__w or 0, text))
                assert(h >= TextHeight(row.left), ("%s: %d px row for %d px of text: %s"):format(what, h, TextHeight(row.left), text))
            end
            local nextRow = rows[i + 1]
            if nextRow then
                assert(y + h <= -nextRow.__pts.TOPLEFT[2], ("%s: rows overlap at %q"):format(what, text))
            end
        end
        assert(hints > 0, what .. ": test setup: no hints")
        -- the note and the total at the bottom of the card (by their place, any language)
        local note, total
        for _, o in ipairs(allFrames) do
            local at = o.__parent == win and o.__kind == "FontString" and o.__pts and o.__pts.BOTTOMLEFT
            if at and at[2] == 24 then note = o elseif at and at[2] == 42 then total = o end
        end
        assert(note and total, what .. ": test setup: note and total")
        local nt, tt = note:GetText() or "", total:GetText() or ""
        assert(Px(nt) <= 500, ("%s: the note at the bottom needs %d px of 500: %s"):format(what, Px(nt), nt))
        assert(tt ~= "" and total.__w and Px(tt) <= total.__w, ("%s: the total needs %d px of %s: %s"):format(what, Px(tt), tostring(total.__w), tt))
    end
    -- training at your maximum, fees, estimated prices, unknown total
    rank.prof, rank[1], rank[2] = "Blacksmithing", 75, 75
    ns.ShowSkillPlan("Blacksmithing") advance(1)
    Check("Blacksmithing 75/75")
    -- caps assumed (no maximum)
    rank[2] = nil
    ns.ShowSkillPlan("Blacksmithing") advance(1)
    Check("Blacksmithing, cap assumed")
    -- recipe items with a big price and without one
    rank.prof, rank[1], rank[2] = "Cooking", 1, 75
    local _, _, _, _, _, info = ns.SkillPlan("Cooking", 1, 75)
    for _, s in ipairs((ns.SkillPlan("Cooking", 1, 75))) do
        if s.recipe.how == "vendor" then ns.db.vendorPrices[s.recipe.recipeItem] = 12345678 break end
    end
    -- (since 0.2, A4, a recipe item is part of the choice: one without a price
    -- is taken only where nothing else gives a point, a dear one hardly ever -
    -- how many the plan uses is no longer fixed here)
    assert(info.items >= 0, "test setup: recipe items")
    ns.ShowSkillPlan("Cooking") advance(1)
    Check("Cooking, recipe items 1234g")

    d.Known, d.Have, ns.ProfessionRank, ns.GetPrice, ns.db.vendorPrices = saved.known, saved.have, saved.rank, saved.price, saved.vendor
    methods.GetStringHeight = saved.height
    _G.GathercraftSkillPlan:Hide()
end)
step("Farm Spots: the Go buttons of reused rows follow a language change (v0.1.14)", function()
    -- rows are made once and reused: their buttons must keep the English key, so
    -- a switch without reload relabels them (both ways: de -> en and en -> de)
    local keep = ns.db.language
    local scroll = _G.GathercraftFarmScroll
    local function GoButtons()
        local list = {}
        for _, f in ipairs(allFrames) do
            local row = f.__kind == "Button" and f.__parent
            if row and row.go == f and row.__parent and row.__parent.__parent == scroll then list[#list + 1] = f end
        end
        return list
    end
    local function Switch(lang)
        ns.db.language = lang ns.ApplyLanguage() _G.GathercraftOptions:Refresh()
        ns.ToggleMain("overview") advance(1) ns.ToggleMain("farm") advance(1)
        local list = GoButtons()
        assert(#list > 0, "no zone rows on Farm Spots")
        for _, b in ipairs(list) do
            assert(b.__text == ns.L["Go"], ("%s: Go button shows %q, expected %q"):format(lang, tostring(b.__text), ns.L["Go"]))
        end
    end
    -- like a German player at login: new rows are made while German is on
    -- ("Los"). 40 more Kalimdor zones (mock) need more rows; you stand in
    -- Mulgore, so Kalimdor is the continent shown
    local start, map = ns.Language(), player.map
    player.map = 1412
    local info = C_Map.GetMapInfo
    C_Map.GetMapInfo = function(id)
        if id >= 1460 and id <= 1499 then return { mapID = id, name = "Extra" .. id, mapType = 3, parentMapID = 1414 } end
        return info(id)
    end
    -- the rows of the zones known so far (past the 60 s list cache), then German,
    -- then the new zones: their rows are made in German
    ns.ToggleMain("overview") advance(61) ns.ToggleMain("farm") advance(1)
    local before = #GoButtons()
    ns.db.language = "deDE" ns.ApplyLanguage() _G.GathercraftOptions:Refresh()
    for id = 1460, 1499 do
        local list = {}
        for k = 1, 8 do list[k] = { id = "o1618", name = "Peacebloom", type = "herb", x = 0.1 * k, y = 0.5, count = 3, last = 1 } end
        ns.db.nodes[id] = list
    end
    ns.ToggleMain("overview") advance(61) ns.ToggleMain("farm") advance(1)
    assert(#GoButtons() > before, "no new rows made while German was on")
    -- then every language this client offers, de -> en and en -> de included,
    -- and back to the start
    local order = { start:sub(1, 2) == "en" and "deDE" or "enUS", start:sub(1, 2) == "en" and "enUS" or "deDE" }
    for _, lang in ipairs(ns.UsableLanguages()) do
        if lang.code ~= "auto" and lang.code ~= order[1] and lang.code ~= order[2] then order[#order + 1] = lang.code end
    end
    order[#order + 1] = "deDE"
    order[#order + 1] = start
    for _, lang in ipairs(order) do Switch(lang) end
    ns.HideMain()
    for id = 1460, 1499 do ns.db.nodes[id] = nil end
    C_Map.GetMapInfo = info
    player.map = map
    ns.db.language = keep ns.ApplyLanguage()
    ns.NotifyNodesChanged() advance(2)
end)
step("Sharing status: waiting spots need the number of players the code asks for (v0.1.18 F4)", function()
    -- Sven's find (08.11.): "Waiting for a second player" - a public spot
    -- needs CONFIRMATIONS (3) different players; guild and friends count at once
    local f = assert(io.open(ROOT .. "/Sync.lua"))
    local code = f:read("*a") f:close()
    local need = tonumber(code:match("local CONFIRMATIONS = (%d+)"))
    assert(need and need >= 2, "test setup: CONFIRMATIONS in Sync.lua")
    local db = ns.db.sync
    local was = { enabled = db.enabled, public = db.public }
    db.enabled, db.public = true, true
    local win = _G.GathercraftOptions
    local wasOpen = win:IsShown()
    local ok, err = pcall(function()
        if not wasOpen then ns.ToggleOptions() end
        ns.ShowOptionsSection("sync")
        win:Refresh()
        advance(3)
        local waiting = select(3, ns.SyncSummary())
        local want = (ns.L["Waiting for confirmation by %d different players: %d"]):format(need, waiting)
        assert(want ~= ("Waiting for confirmation by %d different players: %d"):format(need, waiting) or LOCALE == "enUS" or LOCALE == "enGB",
            "no translation of the waiting line in " .. LOCALE)
        local status
        for _, o in ipairs(allFrames) do
            local t = o.GetText and o:IsShown() and o:GetText()
            if type(t) == "string" and t:find(want, 1, true) then status = t end
        end
        assert(status, "Options > Sharing: " .. want)
        assert(not status:lower():find("second", 1, true), "still a second player: " .. status)
        -- one line in the status area (6 px a letter, 11 px a CJK sign; about 500 px wide)
        local px = 0
        for ch in want:gmatch("[%z\1-\127\194-\244][\128-\191]*") do px = px + (#ch >= 3 and 11 or 6) end
        assert(px <= 480, ("the waiting line needs %d px: %s"):format(px, want))
    end)
    db.enabled, db.public = was.enabled, was.public
    if not wasOpen then ns.ToggleOptions() end
    if not ok then error(err, 0) end
end)
step("Sharing shows what it does; chests can be hidden", function()
    slash("sync on")
    local function said(text)
        for _, l in ipairs(log) do if l:find(text, 1, true) then return true end end
    end
    -- a friend's (guild) spot arrives: one line in chat a little later
    -- (for those who turned the line on - since 0.1.21, T9, it is off by default)
    local keepOn, keepOff = ns.db.sync.announceOn, ns.db.sync.announceOff
    ns.db.sync.announceOn, ns.db.sync.announceOff = true, nil
    for i, l in ipairs(log) do if l:find(ns.GetZoneName(1412), 1, true) then log[i] = "" end end
    fire("CHAT_MSG_ADDON", "Gathercraft", "N:1412;o1620,h,6111,2222,785", "GUILD", "Guildie Three")
    advance(200) -- at most one note every 3 minutes (an earlier step may just have had one)
    assert(said(ns.GetZoneName(1412)), "no note about spots from other players")
    local peers, received = ns.SyncSummary()
    assert(received >= 1, "summary without the received spot")
    -- the note can be turned off
    ns.db.sync.announceOn = nil
    for i, l in ipairs(log) do if l:find(ns.GetZoneName(1412), 1, true) then log[i] = "" end end
    fire("CHAT_MSG_ADDON", "Gathercraft", "N:1412;o1619,h,3555,4666,2449", "GUILD", "Guildie Three")
    advance(240)
    assert(not said(ns.GetZoneName(1412)), "note shown although turned off")
    ns.db.sync.announceOn, ns.db.sync.announceOff = keepOn, keepOff
    -- chests: off in the options = no pins
    ns.db.nodes[1450] = { { id = "o2843", name = "Battered Chest", type = "chest", x = 0.5, y = 0.5, count = 1, last = 1 } }
    HBD_ADDS["Gathercraft"] = { world = 0, mini = 0 }
    ns.db.chestsHidden = true
    ns.NotifyNodesChanged() advance(2)
    local hidden = HBD_ADDS["Gathercraft"].world
    ns.db.chestsHidden = nil
    HBD_ADDS["Gathercraft"] = { world = 0, mini = 0 }
    ns.NotifyNodesChanged() advance(2)
    assert(HBD_ADDS["Gathercraft"].world > hidden, "chests not back on the map")
    -- the Zones tab is for "Start run": an unticked zone stays on the map,
    -- unless the option says the map follows it (v0.1.13)
    local chest = ns.db.nodes[1450][1]
    local pins = LibStub("HereBeDragons-Pins-2.0")
    local add = pins.AddWorldMapIconMap
    local chestPinned
    pins.AddWorldMapIconMap = function(self, ref, frame, mapID, x, y, ...)
        if mapID == 1450 and x == chest.x and y == chest.y then chestPinned = true end
        return add(self, ref, frame, mapID, x, y, ...)
    end
    ns.db.disabledZones[1450] = true
    chestPinned = false
    ns.NotifyNodesChanged() advance(2)
    assert(chestPinned, "an unticked zone hides its pins")
    ns.db.mapFollowsZones = true
    chestPinned = false
    ns.NotifyNodesChanged() advance(2)
    assert(not chestPinned, "the option does not hide the unticked zone")
    pins.AddWorldMapIconMap = add
    ns.db.mapFollowsZones, ns.db.disabledZones[1450] = nil, nil
    ns.db.nodes[1450] = nil
    ns.NotifyNodesChanged() advance(1)
end)
step("Sync: single reports in a new zone show as grey pins", function()
    local function GreyPins()
        local c, seen = 0, {}
        for _, f in ipairs(allFrames) do
            if f.node and f.node.pendingReport and not seen[f.node] then
                seen[f.node] = true
                c = c + 1
            end
        end
        return c
    end
    assert(not ns.HasKnownSpawns(2521) and ns.HasKnownSpawns(1412), "known spawn zones")
    local om, ox, oy = player.map, player.x, player.y
    player.map, player.x, player.y = 2521, 0.5, 0.5 -- you are on that continent
    fire("ZONE_CHANGED_NEW_AREA") advance(2)
    fire("CHAT_MSG_ADDON", "Gathercraft", "N:2521;o990001,h,5000,5000,2447;o990002,o,5100,5100,2770", "CHANNEL", "Stranger One", nil, nil, nil, "GathercraftSync")
    fire("CHAT_MSG_ADDON", "Gathercraft", "N:1412;o1617,h,1234,1234,765", "CHANNEL", "Stranger One", nil, nil, nil, "GathercraftSync")
    fire("CHAT_MSG_ADDON", "Gathercraft", "N:2521;o990003,h,nan,nan,0;o990004,h,1e3,200,0", "CHANNEL", "Stranger One", nil, nil, nil, "GathercraftSync")
    advance(1)
    local pend = ns.SyncPending(2521)
    assert(pend and #pend == 2, "reports in the new zone: " .. tostring(pend and #pend))
    local grey = GreyPins()
    assert(grey == 2, "grey pins " .. grey)
    -- a guild member confirms one: it becomes a node, its grey pin goes
    fire("CHAT_MSG_ADDON", "Gathercraft", "N:2521;o990001,h,5000,5000,2447", "GUILD", "Guildie Two")
    advance(1)
    assert(#ns.SyncPending(2521) == 1, "confirmed report still pending")
    assert(GreyPins() == 1, "grey pin of the confirmed node still there: " .. GreyPins())
    player.map, player.x, player.y = om, ox, oy
    fire("ZONE_CHANGED_NEW_AREA") advance(2)
    for _, f in ipairs(allFrames) do
        if f.node and f.node.pendingReport and f.__scripts.OnEnter then f.__scripts.OnEnter(f) f.__scripts.OnLeave(f) break end
    end
    -- never routed: unconfirmed reports are not in the node database
    for _, n in ipairs(ns.db.nodes[2521] or {}) do assert(n.id ~= "o990002", "report became a node") end
    note("grey pins", grey)
end)
