    local ringed, plain = 0, 0
    for _, f in ipairs(allFrames) do
        if f.node and f.isMini == nil and not f.isTarget and f.icon then
            if f.ring and f.ring:IsShown() then ringed = ringed + 1 else plain = plain + 1 end
        end
    end
    assert(ringed > 0, "no world map pin in a ring")
    ns.db.worldPinStyle = "normal"
    ns.NotifyNodesChanged() advance(2)
    local ringedAfter = 0
    for _, f in ipairs(allFrames) do
        if f.node and f.isMini == nil and not f.isTarget and f.icon and f.ring and f.ring:IsShown() then ringedAfter = ringedAfter + 1 end
    end
    assert(ringedAfter == 0, "world map pins still in rings with the normal style")
    ns.db.worldPinStyle = nil
    ns.NotifyNodesChanged() advance(2)
end)
step("Questing mode: on and off by command, Ctrl + right-click, key and option; a run or fishing ends it (v0.1.19 Q1)", function()
    local L = ns.L
    local keepCtrl = IsControlKeyDown
    local calls = {}
    local function Listen(on) calls[#calls + 1] = on end
    local ok, err = pcall(function()
        assert(ns.QuestModeOn and ns.SetQuestMode and ns.questModeListeners, "no questing mode")
        table.insert(ns.questModeListeners, Listen)
        ns.SetQuestMode(false)
        local function Said(text, mark)
            for i = mark + 1, #log do if log[i]:find(text, 1, true) then return true end end
        end
        -- /gcr quest
        local mark = #log
        slash("quest")
        assert(ns.QuestModeOn() and ns.db.questMode, "/gcr quest did not turn it on")
        assert(Said(L["Questing mode on – nearby nodes get a gold ring"], mark), "no chat line when turned on")
        mark = #log
        slash("quest")
        assert(not ns.QuestModeOn() and ns.db.questMode == nil, "/gcr quest did not turn it off")
        assert(Said(L["Questing mode off"], mark), "no chat line when turned off")
        assert(#calls == 2 and calls[1] == true and calls[2] == false, "the rings are not told: " .. #calls)
        -- Ctrl + right-click on the minimap button: no farm run
        IsControlKeyDown = function() return true end
        ldbObj.OnClick(nil, "RightButton")
        assert(ns.QuestModeOn() and not ns.run, "Ctrl + right-click: not on, or a run started")
        -- the tooltip says it, with the state
        local lines = {}
        local tt = { AddLine = function(_, t) lines[#lines + 1] = t end }
        ldbObj.OnTooltipShow(tt)
        local onLine = L["Ctrl + right-click: questing mode"] .. " |cff00ff00" .. L["on"] .. "|r"
        local found = false
        for _, l in ipairs(lines) do if l == onLine then found = true end end
        assert(found, "tooltip: " .. onLine .. " | " .. table.concat(lines, " | "))
        ldbObj.OnClick(nil, "RightButton")
        assert(not ns.QuestModeOn() and not ns.run, "Ctrl + right-click again: not off")
        lines = {}
        ldbObj.OnTooltipShow(tt)
        local offLine = L["Ctrl + right-click: questing mode"] .. " |cff999999" .. L["off"] .. "|r"
        found = false
        for _, l in ipairs(lines) do if l == offLine then found = true end end
        assert(found, "tooltip: " .. offLine)
        IsControlKeyDown = keepCtrl
        -- a plain right-click still starts the run
        ldbObj.OnClick(nil, "RightButton") advance(1)
        assert(ns.run, "right-click no longer starts a run")
        ns.StopRun()
        -- key binding
        local f = assert(io.open(ROOT .. "/Bindings.xml"))
        local xml = f:read("*a") f:close()
        assert(xml:find('<Binding name="GATHERCRAFT_QUEST" category="ADDONS">Gathercraft_QuestMode()</Binding>', 1, true), "no key binding")
        assert(BINDING_NAME_GATHERCRAFT_QUEST == L["Questing mode on / off"], "binding name: " .. tostring(BINDING_NAME_GATHERCRAFT_QUEST))
        Gathercraft_QuestMode()
        assert(ns.QuestModeOn(), "the key did not turn it on")
        Gathercraft_QuestMode()
        assert(not ns.QuestModeOn(), "the key did not turn it off")
        -- Options > Leveling (since 0.2.2, Sven 21.11.2026: Map & minimap
        -- makes room for the tooltip choices; its rows flow there, the label
        -- hangs on its box by TOPLEFT)
        local box
        for _, o in ipairs(allFrames) do
            local at = o.__kind == "FontString" and o:GetText() == L["Questing mode"] and o.__pts and (o.__pts.TOPLEFT or o.__pts.LEFT)
            if at and type(at[1]) == "table" and at[1].__kind == "CheckButton" then
                local cb = at[1]
                if cb.get then box = cb end
                local p = o.__parent
                while p and not p.key do p = p.__parent end
                assert(p and p.key == "level", "the switch is not under Leveling")
            end
        end
        assert(box, "no switch in the options")
        assert(box.get() == false, "the switch shows on while off")
        box:SetChecked(true) box.__scripts.OnClick(box)
        assert(ns.QuestModeOn() and box.get() == true, "the switch did not turn it on")
        -- kept over /reload and login (saved variables); the rings are told again
        local before = #calls
        local watch = _G.GathercraftQuestWatch
        assert(watch and eventFrames.PLAYER_LOGIN[watch], "test setup: the questing mode's login frame")
        watch.__scripts.OnEvent(watch, "PLAYER_LOGIN")
        assert(ns.db.questMode and ns.QuestModeOn(), "not kept over the login")
        assert(#calls > before and calls[#calls] == true, "after the login the rings are not told")
        -- a farm run turns it off, with a word; after the run it stays off
        mark = #log
        slash("run herb") advance(2)
        assert(ns.run, "test setup: no run")
        assert(not ns.QuestModeOn(), "still on during a farm run")
        assert(Said(L["Questing mode off: a farm run started."], mark), "no word why it went off (run)")
        slash("stop") advance(1)
        assert(not ns.QuestModeOn(), "back on after the run")
        -- fishing too
        ns.SetQuestMode(true)
        mark = #log
        fire("UNIT_SPELLCAST_CHANNEL_START", "player", "q1fish", 7620) advance(1)
        assert(not ns.QuestModeOn(), "still on while fishing")
        assert(Said(L["Questing mode off: you started fishing."], mark), "no word why it went off (fishing)")
        fire("UNIT_SPELLCAST_CHANNEL_STOP", "player", "q1fish", 7620) advance(1)
        assert(not ns.QuestModeOn(), "back on after fishing")
        -- the second cast of the same fishing session turns it off too, and
        -- the session goes on (Codex 09.11., B1)
        local session = ns.FishingSession()
        assert(session and session.start, "test setup: no fishing session after the first cast")
        local started = session.start
        advance(30)
        ns.SetQuestMode(true)
        mark = #log
        fire("UNIT_SPELLCAST_CHANNEL_START", "player", "q1fish2", 7620) advance(1)
        assert(not ns.QuestModeOn(), "still on at the second cast of the session")
        assert(Said(L["Questing mode off: you started fishing."], mark), "no word why it went off (second cast)")
        assert(ns.FishingSession() and ns.FishingSession().start == started, "the second cast started the fishing session anew")
        fire("UNIT_SPELLCAST_CHANNEL_STOP", "player", "q1fish2", 7620) advance(1)
        ns.StopFishing()
        assert(not ns.QuestModeOn(), "back on after fishing")
    end)
    IsControlKeyDown = keepCtrl
    for i = #ns.questModeListeners, 1, -1 do if ns.questModeListeners[i] == Listen then table.remove(ns.questModeListeners, i) end end
    if ns.StopRun then ns.StopRun() end
    if ns.SetQuestMode then ns.SetQuestMode(false) end
    if not ok then error(err, 0) end
end)
step("Questing mode: gold rings on nearby nodes you can gather, minimap only (v0.1.19 Q2)", function()
    -- map 5000 x 3333 yd in the mock: 0.001 in x is 5 yd
    local Z, Z2 = 1460, 1461
    local keep = { nodes = ns.db.nodes[Z], nodes2 = ns.db.nodes[Z2], style = ns.db.miniPinStyle, chests = ns.db.chestsHidden, grey = ns.db.hideGreyNodes,
        gp = ns.GatherProfessions, skill = ns.GetSkill, pos = ns.GetPlayerPos, secret = issecretvalue,
        map = player.map, x = player.x, y = player.y }
    local px, py = 0.5, 0.5
    local function At(yd, name, kind, extra)
        local n = { id = "o9" .. math.random(100000, 999999), name = name, type = kind, x = px + yd / 5000, y = py, count = 1, last = 1, hits = 1 }
        for k, v in pairs(extra or {}) do n[k] = v end
        table.insert(ns.db.nodes[Z], n)
        return n
    end
    local ok, err = pcall(function()
        ns.SetQuestMode(false)
        ns.db.nodes[Z] = {}
        local near = At(20, "Peacebloom", "herb")
        local edge = At(75, "Mageroyal", "herb")          -- skill 50, yours 52
        local out = At(76, "Peacebloom", "herb")
        local ore = At(40, "Copper Vein", "ore")
        -- (other herbs stand more than 10 yd from `near`: since 0.1.21 herbs
        -- that close are one place with one ring - its own step, T1)
        local herbHigh = At(-40, "Briarthorn", "herb")   -- needs 70
        local oreHigh = At(12, "Tin Vein", "ore")        -- needs 65, yours 30
        local chest = At(30, "Battered Chest", "chest")
        local resting = At(-15, "Silverleaf", "herb", { emptyUntil = time() + 300 }) -- just harvested / found empty
        ns.db.nodes[Z2] = {}
        local other = { id = "o1617", name = "Silverleaf", type = "herb", x = px + 0.001, y = py, count = 1, last = 1, hits = 1 }
        table.insert(ns.db.nodes[Z2], other)
        player.map, player.x, player.y = Z, px, py
        fire("ZONE_CHANGED_NEW_AREA") advance(1) -- the minimap pins move to this zone
        ns.db.miniPinStyle, ns.db.chestsHidden = nil, nil -- ring only, chests shown
        ns.NotifyNodesChanged() advance(1)
        -- off: nothing lit
        assert(not next(ns.QuestRings()), "rings while the mode is off")
        local REF = "GathercraftQuest"
        HBD_ADDS[REF] = { world = 0, mini = 0 }
        ns.SetQuestMode(true) advance(1)
        local lit = ns.QuestRings()
        local function Lit(n) return lit[n] ~= nil end
        assert(Lit(near) and Lit(edge) and Lit(ore) and Lit(chest), ("a node you can gather in reach is not lit: near %s edge %s ore %s chest %s"):format(tostring(Lit(near)), tostring(Lit(edge)), tostring(Lit(ore)), tostring(Lit(chest))))
        assert(not Lit(out), "lit outside the radius (76 yd)")
        assert(not Lit(herbHigh) and not Lit(oreHigh), "lit although your skill is too low")
        assert(not Lit(resting), "lit although just harvested or found empty")
        assert(not Lit(other), "a node of another zone lit")
        -- the minimap only
        assert(HBD_ADDS[REF].mini >= 4 and HBD_ADDS[REF].world == 0, ("rings: %d minimap, %d world map"):format(HBD_ADDS[REF].mini, HBD_ADDS[REF].world))
        -- the look of the run target (ring only: its size, no icon - and since
        -- 0.1.21 the thin gold ring where the target has the broad one: T6)
        local function Tex(pin) return tostring(pin.ring and pin.ring.__tex or "") end
        local function TargetLook(style)
            ns.db.miniPinStyle = style
            ns.SetRouteTarget(Z, near)
            local _, mini = ns.RouteTargetPins()
            local w, shown, tex = mini.__w, mini.icon.__shown ~= false, Tex(mini)
            ns.ClearRouteTarget()
            return w, shown, tex
        end
        for _, style in ipairs({ "ring", "subtle", "normal" }) do
            local tw, tshown, ttex = TargetLook(style ~= "ring" and style or nil)
            ns.NotifyNodesChanged() advance(1) -- the options rebuild the pins
            local pin = ns.QuestRings()[near]
            assert(pin, style .. ": the ring went with the rebuild")
            local want = style == "ring" and ttex:gsub("RingGoldBold$", "RingGold") or ttex
            assert(Tex(pin) == want and pin.__w == tw and (pin.icon.__shown ~= false) == tshown,
                ("%s: ring %s %spx icon %s, the run target %s %spx icon %s"):format(style, Tex(pin), tostring(pin.__w),
                    tostring(pin.icon.__shown ~= false), ttex, tostring(tw), tostring(tshown)))
            if style == "ring" then assert(ttex:find("RingGoldBold$") and not tshown, "test setup: ring only target") end
        end
        ns.db.miniPinStyle = nil
        ns.NotifyNodesChanged() advance(1)
        -- the node's own minimap pin steps aside under its ring, comes back after
        local mine
        for _, pin in ipairs(MINI_ICONS) do if pin.node == near and pin.isMini and not pin.isQuest then mine = pin end end
        assert(mine and mine.__alpha == 0, "the normal minimap pin still shows under the ring")
        -- chests only while shown
        ns.db.chestsHidden = true
        advance(3) -- the questing mode looks again at least every 2 s (Q4)
        assert(not ns.QuestRings()[chest] and ns.QuestRings()[near], "a chest lit while chests are hidden")
        ns.db.chestsHidden = nil
        advance(3) -- the questing mode looks again at least every 2 s (Q4)
        assert(ns.QuestRings()[chest], "the chest not lit again")
        -- a profession you don't have: none of its nodes
        ns.GatherProfessions = function() return false, true, true end
        advance(3) -- the questing mode looks again at least every 2 s (Q4)
        assert(not ns.QuestRings()[near] and not ns.QuestRings()[edge] and ns.QuestRings()[ore], "herbs lit without Herbalism")
        ns.GatherProfessions = keep.gp
        ns.GetSkill = function(t) if t == "herb" then return keep.skill(t) end end -- Mining not learned
        advance(3) -- the questing mode looks again at least every 2 s (Q4)
        assert(ns.QuestRings()[near] and not ns.QuestRings()[ore], "ore lit without Mining")
        -- "Hide grey nodes" (Options > Leveling): a node that gives no more
        -- skill-ups gets no ring while the option is on (Sven, 09.11.)
        ns.GetSkill = function(t) if t == "herb" then return 160, 225, 160 end return keep.skill(t) end -- Peacebloom (1) is grey from 100
        ns.db.hideGreyNodes = true
        ns.NotifyNodesChanged() advance(3) -- the questing mode looks again at least every 2 s (Q4)
        assert(not ns.QuestRings()[near] and ns.QuestRings()[ore], "a grey herb lit although grey nodes are hidden")
        ns.db.hideGreyNodes = nil
        ns.NotifyNodesChanged() advance(3) -- the questing mode looks again at least every 2 s (Q4)
        assert(ns.QuestRings()[near], "a grey herb not lit although grey nodes are shown")
        ns.GetSkill = keep.skill
        advance(3) -- the questing mode looks again at least every 2 s (Q4)
        -- a hidden skill: nothing of it, no error
        local SECRET = newproxy(true)
        issecretvalue = function(v) return rawequal(v, SECRET) end
        ns.GetSkill = function(t) if t == "herb" then return SECRET, 75, SECRET end return keep.skill(t) end
        ns.GetSkill("ore") -- (only the questing mode reads it now: no other timer meets the stand-in)
        ns.UpdateQuestRings()
        assert(not ns.QuestRings()[near] and ns.QuestRings()[ore], "a hidden Herbalism skill: herbs lit")
        ns.GetSkill, issecretvalue = keep.skill, keep.secret
        -- the position can't be read (hidden): no rings, no error
        ns.GetPlayerPos = function() end
        advance(3) -- the questing mode looks again at least every 2 s (Q4)
        assert(not next(ns.QuestRings()), "rings without a position")
        ns.GetPlayerPos = keep.pos
        advance(3) -- the questing mode looks again at least every 2 s (Q4)
        assert(ns.QuestRings()[near], "the rings did not come back")
        -- another zone: its nodes, not the old ones
        player.map, player.x, player.y = Z2, px, py
        fire("ZONE_CHANGED_NEW_AREA") advance(1)
        assert(ns.QuestRings()[other] and not ns.QuestRings()[near], "after a zone change: the old zone's rings")
        player.map = Z
        fire("ZONE_CHANGED_NEW_AREA") advance(1)
        -- walking away: the rings go
        player.x = px + 0.05
        advance(3) -- the questing mode looks again at least every 2 s (Q4)
        assert(not next(ns.QuestRings()), "rings 250 yd away")
        player.x = px
        advance(3) -- the questing mode looks again at least every 2 s (Q4)
        -- off: all rings go, the normal pin is back
        ns.SetQuestMode(false) advance(1)
        assert(not next(ns.QuestRings()), "rings after turning it off")
        assert(mine.__alpha and mine.__alpha > 0, "the normal minimap pin did not come back")
    end)
    ns.SetQuestMode(false)
    ns.GatherProfessions, ns.GetSkill, ns.GetPlayerPos, issecretvalue = keep.gp, keep.skill, keep.pos, keep.secret
    ns.db.nodes[Z], ns.db.nodes[Z2], ns.db.miniPinStyle, ns.db.chestsHidden, ns.db.hideGreyNodes = keep.nodes, keep.nodes2, keep.style, keep.chests, keep.grey
    player.map, player.x, player.y = keep.map, keep.x, keep.y
    fire("ZONE_CHANGED_NEW_AREA") advance(1)
    ns.NotifyNodesChanged() advance(1)
    if not ok then error(err, 0) end
end)
step("Questing mode: radius 50 / 75 / 100 yd and the arrow to the nearest ring (v0.1.19 Q3)", function()
    local L = ns.L
    local Z = 1460
    local keep = { nodes = ns.db.nodes[Z], radius = ns.db.questRadius, arrow = ns.db.questArrow,
        map = player.map, x = player.x, y = player.y }
    local win = _G.GathercraftOptions
    local wasOpen, wasSection = win:IsShown(), ns.db.optionsSection
    local px, py = 0.5, 0.5
    -- dir: east, west or north of you (the map is 5000 x 3333 yd)
    -- (kind: the three nodes at a limit are a herb, a vein and a chest - one
    -- yard apart, three of one kind would be one place with one ring: T1)
    local KINDS = { herb = { "o1618", "Peacebloom" }, ore = { "o1731", "Copper Vein" }, chest = { "o2843", "Battered Chest" } }
    local function Node(yd, dir, kind)
        local x, y = px, py
        if dir == "east" then x = px + yd / 5000 elseif dir == "west" then x = px - yd / 5000 else y = py - yd / 3333 end
        local n = { id = KINDS[kind][1], name = KINDS[kind][2], type = kind, x = x, y = y, count = 1, last = 1, hits = 1 }
        table.insert(ns.db.nodes[Z], n)
        return n
    end
    local function PageOf(o)
        local p = o.__parent
        while p and not p.key do p = p.__parent end
        return p and p.key
    end
    local ok, err = pcall(function()
        assert(ns.QUEST_RADII and #ns.QUEST_RADII == 3 and ns.QUEST_RADII[1] == 50 and ns.QUEST_RADII[2] == 75 and ns.QUEST_RADII[3] == 100, "not 50 / 75 / 100")
        ns.db.questRadius, ns.db.questArrow = nil, nil
        assert(ns.QuestRadius() == 75, "the default is not 75: " .. tostring(ns.QuestRadius()))
        ns.db.nodes[Z] = {}
        player.map, player.x, player.y = Z, px, py
        fire("ZONE_CHANGED_NEW_AREA") advance(1)
        -- three nodes at each limit, each radius in its own direction
        local rows = {}
        for r, dir in pairs({ [50] = "east", [75] = "west", [100] = "north" }) do
            rows[r] = { Node(r - 1, dir, "herb"), Node(r, dir, "ore"), Node(r + 1, dir, "chest") }
        end
        ns.NotifyNodesChanged() advance(1)
        ns.SetQuestMode(true) advance(1)
        local function Check(r)
            local lit = ns.QuestRings()
            for limit, row in pairs(rows) do
                for k, n in ipairs(row) do
                    local d = limit - 2 + k -- limit-1, limit, limit+1
                    local want = d <= r
                    assert((lit[n] ~= nil) == want, ("radius %d: a node at %d yd %s"):format(r, d, want and "not lit" or "lit"))
                end
            end
        end
        Check(75)
        -- the < > control in Options > Leveling (since 0.2.2; open, so it shows its value)
        if not win:IsShown() then ns.ToggleOptions() end
        ns.ShowOptionsSection("level")
        win:Refresh()
        local valueText, plus, minus
        for _, o in ipairs(allFrames) do
            if o.__kind == "FontString" and o:GetText() == (L["%d yd"]):format(75) and PageOf(o) == "level" and o.__pts and o.__pts.LEFT then
                minus = o.__pts.LEFT[1]
                valueText = o
            end
        end
        assert(valueText and minus and minus.__kind == "Button", "no radius control under Leveling")
        for _, o in ipairs(allFrames) do
            if o.__kind == "Button" and o.__pts and o.__pts.LEFT and o.__pts.LEFT[1] == valueText then plus = o end
        end
        assert(plus, "test setup: the > button")
        plus.__scripts.OnClick(plus) advance(1)
        assert(ns.QuestRadius() == 100 and ns.db.questRadius == 100 and valueText:GetText() == (L["%d yd"]):format(100), "> did not go to 100 yd")
        Check(100)
        plus.__scripts.OnClick(plus) advance(1)
        assert(ns.QuestRadius() == 100, "> went past 100 yd")
        minus.__scripts.OnClick(minus) minus.__scripts.OnClick(minus) advance(1)
        assert(ns.QuestRadius() == 50 and ns.db.questRadius == 50, "< did not go to 50 yd")
        Check(50)
        minus.__scripts.OnClick(minus) advance(1)
        assert(ns.QuestRadius() == 50, "< went below 50 yd")
        plus.__scripts.OnClick(plus) advance(1)
        assert(ns.QuestRadius() == 75 and ns.db.questRadius == nil, "back at 75: not saved as the default")
        -- an odd saved value: the default
        ns.db.questRadius = 60
        assert(ns.QuestRadius() == 75, "a saved 60 yd is used")
        ns.db.questRadius = nil
        -- the arrow: off by default
        advance(1)
        local arrow = _G.GathercraftArrow
        assert(arrow and not arrow:IsShown() and not ns.QuestArrowNode(), "the arrow shows although it is off")
        local box
        for _, o in ipairs(allFrames) do
            local at = o.__kind == "FontString" and o:GetText() == L["Arrow to the nearest gold ring"] and o.__pts and (o.__pts.TOPLEFT or o.__pts.LEFT)
            if at and type(at[1]) == "table" and at[1].__kind == "CheckButton" then
                box = at[1]
                assert(PageOf(o) == "level", "the arrow switch is not under Leveling (since 0.2.2)")
            end
        end
        assert(box and box.get and box.get() ~= true, "no arrow switch, or it is on")
        box:SetChecked(true) box.__scripts.OnClick(box) advance(1)
        assert(ns.db.questArrow, "the switch did not turn the arrow on")
        local n = ns.QuestArrowNode()
        assert(n == rows[50][1], "the arrow does not point at the nearest ring: " .. tostring(n and n.x))
        assert(arrow:IsShown(), ("the arrow does not show: run %s, shown %s, hidden %s"):format(tostring(ns.run), tostring(arrow.__shown), tostring(ns.db.arrowHidden)))
        -- only which way and how far: no route, no line
        assert(not ns.run, "a run started")
        -- walking: it follows the nearest one
        player.x = px - 75 / 5000 -- 75 yd west: right at the middle node of that row
        advance(1)
        assert(ns.QuestArrowNode() == rows[75][2], "the arrow did not move on to the nearest ring")
        player.x = px
        advance(1)
        -- off again: gone
        box:SetChecked(false) box.__scripts.OnClick(box) advance(1)
        assert(not ns.QuestArrowNode() and not arrow:IsShown(), "the arrow stays when switched off")
        -- with the mode off: no arrow either
        ns.db.questArrow = true
        ns.SetQuestMode(false) advance(1)
        assert(not ns.QuestArrowNode() and not arrow:IsShown(), "the arrow stays with the questing mode off")
    end)
    ns.SetQuestMode(false)
    ns.db.nodes[Z], ns.db.questRadius, ns.db.questArrow = keep.nodes, keep.radius, keep.arrow
    player.map, player.x, player.y = keep.map, keep.x, keep.y
    ns.ShowOptionsSection(wasSection or "map")
    if win:IsShown() ~= wasOpen then ns.ToggleOptions() end
    fire("ZONE_CHANGED_NEW_AREA") advance(1)
    ns.NotifyNodesChanged() advance(1)
    if not ok then error(err, 0) end
end)
step("Questing mode: looks again only after 5 yd, a change or 2 s; nothing while off; Hillsbrad (v0.1.19 Q4)", function()
    local Z = 1424 -- Hillsbrad Foothills: every herb and ore spawn point of the Questie data
    local keep = { nodes = ns.db.nodes[Z], map = player.map, x = player.x, y = player.y }
    local ok, err = pcall(function()
        ns.SetQuestMode(false)
        ns.ImportQuestieZone(Z, true)
        local questie = #(ns.db.nodes[Z] or {})
        assert(questie >= 600, "test setup: Hillsbrad has " .. questie .. " Questie nodes")
        -- plus own finds up to 700 (Sven's zone had 680+)
        for i = questie + 1, 700 do
            table.insert(ns.db.nodes[Z], { id = "o1617", name = "Silverleaf", type = "herb", x = (i % 40) / 40, y = math.floor(i / 40) / 20, count = 1, last = 1, hits = 1 })
        end
        local count = #ns.db.nodes[Z]
        ns.NotifyNodesChanged() advance(1)
        note("Hillsbrad nodes", questie, "from Questie,", count, "in all")
        player.map, player.x, player.y = Z, 0.5, 0.5
        fire("ZONE_CHANGED_NEW_AREA") advance(1)
        -- off: nothing is gone through, however long
        local p0 = ns.QuestPicks()
        advance(10)
        assert(ns.QuestPicks() == p0, "the nodes were gone through while the mode is off")
        -- on: once at once
        ns.SetQuestMode(true)
        local p1 = ns.QuestPicks()
        assert(p1 == p0 + 1, "not looked at once when turned on")
        -- standing still for 10 s (20 ticks): only the 2 s refresh
        advance(10)
        local still = ns.QuestPicks() - p1
        assert(still >= 3 and still <= 6, "standing still 10 s: gone through " .. still .. " times (want every 2 s, not every tick)")
        -- 4 yd walked: nothing new; 6 yd: at once
        advance(2.1)
        local p2 = ns.QuestPicks()
        player.x = player.x + 4 / 5000
        advance(0.6)
        assert(ns.QuestPicks() == p2, "4 yd walked: gone through again")
        player.x = player.x + 2 / 5000
        advance(0.6)
        assert(ns.QuestPicks() == p2 + 1, "6 yd walked: not gone through again")
        -- a node changed (harvested, options): at the next tick
        local p3 = ns.QuestPicks()
        ns.NotifyNodesChanged()
        advance(0.6)
        assert(ns.QuestPicks() > p3, "a node change: not looked again")
        -- one look at 680+ nodes is quick (the mock's clock: a rough bound only)
        local t0 = os.clock()
        for _ = 1, 20 do ns.UpdateQuestRings() end
        local ms = (os.clock() - t0) * 1000 / 20
        note("questing mode, one look at Hillsbrad", ("%.2f ms"):format(ms), "rings", (function() local c = 0 for _ in pairs(ns.QuestRings()) do c = c + 1 end return c end)())
        assert(ms < 25, ("one look at %d nodes takes %.1f ms"):format(count, ms))
        -- only this zone: a node of another zone is never looked at
        local seen = {}
        local realDistance = ns.Distance
        ns.Distance = function(mapID, ...) seen[mapID] = true return realDistance(mapID, ...) end
        ns.UpdateQuestRings()
        ns.Distance = realDistance
        for m in pairs(seen) do assert(m == Z, "a node of another zone was measured: " .. tostring(m)) end
        -- off: the ticker stops (no more looks)
        ns.SetQuestMode(false)
        local p4 = ns.QuestPicks()
        player.x = player.x + 0.01
        advance(5)
        assert(ns.QuestPicks() == p4, "still looking after turning it off")
    end)
    ns.SetQuestMode(false)
    ns.db.nodes[Z] = keep.nodes
    player.map, player.x, player.y = keep.map, keep.x, keep.y
    fire("ZONE_CHANGED_NEW_AREA") advance(1)
    ns.NotifyNodesChanged() advance(1)
    if not ok then error(err, 0) end
end)
-- Every herb and ore spawn point of a zone as the shipped Questie data has
-- it, as fresh node tables (the starter import itself runs once per session
-- and merges what lies close together: the 0.1.21 steps want the raw points)
local function QuestieZoneNodes(mapID)
    local data = GathercraftQuestieData
    local kindOf = { h = "herb", o = "ore" }
    local list = {}
    for id, xs, ys in (data.zones[mapID] or ""):gmatch("(%d+),(%d+),(%d+)") do
        local kind = data.kinds["o" .. id]
        if kind and kindOf[kind[1]] then
            list[#list + 1] = { id = "o" .. id, type = kindOf[kind[1]], name = kind[3], x = tonumber(xs) / 10000, y = tonumber(ys) / 10000,
                count = 0, last = 0, hits = 1, source = "questie" }
        end
    end
    return list
end
step("Questing mode: a look reads your skill once and asks only the nodes near you; the same rings (v0.1.21 T3)", function()
    -- Sven, 10.11.2026, Hillsbrad: a short hitch every few yards while the
    -- questing mode is on. A look went through every node of the zone and
    -- read the skill for each one (the whole skill list of the game, node by
    -- node), also for the nodes far away. Now the skill is read once per
    -- look, and only the nodes within the radius are asked the rest. Which
    -- nodes get a ring - and which one the arrow points at - is what it was:
    -- compared here with a copy of the old way, on a full zone with every
    -- kind of state mixed in.
    local Z = 1424 -- Hillsbrad Foothills
    local keep = { nodes = ns.db.nodes[Z], map = player.map, x = player.x, y = player.y, gp = ns.GatherProfessions, skill = ns.GetSkill, cool = ns.IsOnCooldown,
        secret = issecretvalue, chests = ns.db.chestsHidden, grey = ns.db.hideGreyNodes, radius = ns.db.questRadius, arrow = ns.db.questArrow,
        debug = ns.db.debug, say = ns.Debug }
    local ok, err = pcall(function()
        ns.SetQuestMode(false)
        -- one entry per place and kind (what several entries at one place do
        -- is another step): an entry closer than 15 yd to an earlier one of
        -- its kind is left out
        local all, list = QuestieZoneNodes(Z), {}
        assert(#all >= 600, "test setup: Hillsbrad has " .. #all .. " spawn points")
        for _, n in ipairs(all) do
            local alone = true
            for _, m in ipairs(list) do
                if m.type == n.type and ns.Distance(Z, m.x, m.y, n.x, n.y) < 15 then alone = false break end
            end
            if alone then list[#list + 1] = n end
        end
        assert(#list >= 300, "test setup: Hillsbrad has " .. #list .. " places")
        -- every kind of state, spread over the zone
        local now = time()
        for i, n in ipairs(list) do
            n.emptyUntil, n.parked, n.source, n.hits, n.pendingReport = nil, nil, nil, 1, nil
            if i % 7 == 0 then n.emptyUntil = now + 600 end                        -- just harvested / found empty
            if i % 11 == 0 then n.emptyUntil = now - 5 end                         -- rested long ago
            if i % 13 == 0 then n.parked, n.source, n.hits = true, "sync", 0 end   -- parked as always empty
            if i % 17 == 0 then n.pendingReport = {} end                           -- a report nobody confirmed
        end
        for i = 1, 40 do
            local at = list[i * 7]
            list[#list + 1] = { id = "o9" .. (800000 + i), name = "Battered Chest", type = "chest", x = at.x + 0.004, y = at.y + 0.003, count = 1, last = 1, hits = 1 }
            list[#list + 1] = { id = "o9" .. (810000 + i), name = "School of Fish", type = "fish", x = at.x - 0.004, y = at.y + 0.003, count = 1, last = 1, hits = 1 }
        end
        list[#list + 1] = { id = "o9820000", name = "Peacebloom", type = "herb", count = 1, last = 1, hits = 1 } -- no place
        ns.db.nodes[Z] = list
        ns.NotifyNodesChanged() advance(1)

        -- ---- the old way (0.1.20), word for word
        local function OldCanGather(n)
            if not (n and n.x and n.y) or n.pendingReport then return false end
            if ns.IsOnCooldown and ns.IsOnCooldown(n) then return false end
            if ns.IsParked and ns.IsParked(n) then return false end
            if n.type == "chest" then return not ns.db.chestsHidden end
            if n.type ~= "herb" and n.type ~= "ore" then return false end
            if ns.GatherProfessions then
                local herb, ore, known = ns.GatherProfessions()
                if known and not ((n.type == "herb" and herb) or (n.type == "ore" and ore)) then return false end
            end
            local rank, _, effective
            if ns.GetSkill then rank, _, effective = ns.GetSkill(n.type) end
            if not rank or ns.AnySecret("questing mode", rank, effective) then return false end
            local level = ns.SkillLevel(n.name, n.id, rank, effective)
            if level == "red" then return false end
            if level == "grey" and ns.db.hideGreyNodes then return false end
            return true
        end
        -- (since T1, the next step, rings go by places: the slow way does too.
        -- Every distance asked from ns.Distance, node by node; a place is the
        -- entries of one kind within 10 yd of its first entry, in the zone's
        -- order; it has a ring on its first entry OldCanGather says yes to,
        -- and none while an entry of it rests.)
        local function OldPick()
            local mapID, px, py = ns.GetPlayerPos()
            if not (mapID and px and py) then return end
            local want, r = {}, ns.QuestRadius()
            local places = {}
            for _, n in ipairs(ns.db.nodes[mapID] or {}) do
                local lit = n.x and n.y and not n.pendingReport
                    and (n.type == "herb" or n.type == "ore" or (n.type == "chest" and not ns.db.chestsHidden))
                if lit then
                    local d = math.floor(ns.Distance(mapID, px, py, n.x, n.y) + 0.5)
                    if d <= r then
                        local place
                        for _, s in ipairs(places) do
                            if not place and s.kind == n.type and ns.Distance(mapID, s[1].n.x, s[1].n.y, n.x, n.y) <= 10 then place = s end
                        end
                        if not place then
                            place = { kind = n.type }
                            places[#places + 1] = place
                        end
                        place[#place + 1] = { n = n, d = d }
                    end
                end
            end
            local nearest, nearestD
            for _, s in ipairs(places) do
                local resting, first
                for _, e in ipairs(s) do
                    if (ns.IsOnCooldown and ns.IsOnCooldown(e.n)) or (ns.IsParked and ns.IsParked(e.n)) then resting = true end
                    if not first and OldCanGather(e.n) then first = e end
                end
                if first and not resting then
                    want[first.n] = true
                    if not nearestD or first.d < nearestD then nearest, nearestD = first.n, first.d end
                end
            end
            return mapID, want, nearest
        end

        -- ---- the same rings and the same arrow, state by state
        local SECRET = newproxy(true)
        local herbSkill, oreSkill = { 100, 150, 105 }, { 70, 75, 70 }
        ns.GetSkill = function(kind)
            local s = kind == "herb" and herbSkill or kind == "ore" and oreSkill or nil
            if s then return s[1], s[2], s[3] end
        end
        ns.GatherProfessions = function() return true, true, true end
        ns.db.questArrow = true
        player.map = Z
        fire("ZONE_CHANGED_NEW_AREA") advance(1)
        ns.SetQuestMode(true)
        local compared, lit, arrows = 0, 0, 0
        -- places to stand: next to nodes spread over the zone, and one in the open
        local stands = { { 0.05, 0.95 } }
        for _, i in ipairs({ 15, 70, 130, 190, 250 }) do stands[#stands + 1] = { list[i].x + 0.002, list[i].y + 0.001 } end
        local function Same(what)
            for _, pos in ipairs(stands) do
                player.x, player.y = pos[1], pos[2]
                for _, radius in ipairs({ 50, 75, 100 }) do
                    ns.db.questRadius = radius
                    local _, want, nearest = OldPick()
                    ns.UpdateQuestRings()
                    local rings = ns.QuestRings()
                    for n in pairs(want) do
                        assert(rings[n], ("%s, at %.2f / %.2f, %d yd: %s has no ring any more"):format(what, pos[1], pos[2], radius, tostring(n.name)))
                        lit = lit + 1
                    end
                    for n in pairs(rings) do
                        assert(want[n], ("%s, at %.2f / %.2f, %d yd: %s has a ring it did not have"):format(what, pos[1], pos[2], radius, tostring(n.name)))
                    end
                    assert(ns.QuestArrowNode() == nearest, ("%s, at %.2f / %.2f, %d yd: the arrow points at another node"):format(what, pos[1], pos[2], radius))
                    if nearest then arrows = arrows + 1 end
                    compared = compared + 1
                end
            end
        end
        Same("every profession")
        ns.db.hideGreyNodes = true
        Same("grey nodes hidden")
        ns.db.hideGreyNodes = nil
        ns.db.chestsHidden = true
        Same("chests hidden")
        ns.db.chestsHidden = nil
        ns.GatherProfessions = function() return false, true, true end
        Same("no Herbalism")
        ns.GatherProfessions = function() return true, false, false end -- (not known for sure: the skill decides)
        Same("professions not known for sure")
        ns.GatherProfessions = function() return true, true, true end
        oreSkill = nil
        Same("Mining not learned")
        oreSkill = { 300, 300, 300 }
        herbSkill = { 1, 75, 1 }
        Same("Herbalism at 1, Mining at 300")
        issecretvalue = function(v) return rawequal(v, SECRET) end
        herbSkill = { SECRET, 150, SECRET }
        Same("a hidden Herbalism skill")
        issecretvalue = keep.secret
        herbSkill, oreSkill = { 100, 150, 105 }, { 70, 75, 70 }
        ns.GatherProfessions = nil
        Same("no profession watch")
        ns.GatherProfessions = function() return true, true, true end
        assert(compared == 9 * 18 and lit > 150 and arrows > 60, ("test setup: %d looks compared, %d rings, %d arrows"):format(compared, lit, arrows))
        -- asking about one node (the way other parts ask) gives the old answer too
        for _, n in ipairs(list) do
            assert(ns.QuestCanGather(n) == OldCanGather(n), "asked alone, " .. tostring(n.name) .. " gets another answer")
        end

        -- ---- what a look costs: the skill once per kind, the rest only near you
        -- (where it asks the most nodes for their skill colour: there the
        -- skill would be read the most often)
        ns.db.questRadius = 100
        local realLevel = ns.SkillLevel
        local asks, best = 0, nil
        for i = 5, #list, 5 do
            local at = list[i]
            if at.x then
                player.x, player.y = at.x + 0.001, at.y
                ns.UpdateQuestRings()
                local levels = 0
                ns.SkillLevel = function(...) levels = levels + 1 return realLevel(...) end
                ns.UpdateQuestRings()
                ns.SkillLevel = realLevel
                if levels > asks then asks, best = levels, at end
            end
        end
        assert(best and asks >= 4, "test setup: no place where a look asks 4 nodes or more for their colour (" .. asks .. ")")
        player.x, player.y = best.x + 0.001, best.y
        local within = 0
        for _, n in ipairs(list) do
            if n.x and math.floor(ns.Distance(Z, player.x, player.y, n.x, n.y) + 0.5) <= 100 then within = within + 1 end
        end
        assert(within > 0 and within < 80, "test setup: " .. within .. " nodes within 100 yd")
        ns.UpdateQuestRings() -- (the rings of this place are lit: the pins have asked what they ask)
        local skillReads, restAsked = 0, 0
        local realSkill, realCool = ns.GetSkill, ns.IsOnCooldown
        ns.GetSkill = function(kind) skillReads = skillReads + 1 return realSkill(kind) end
        ns.IsOnCooldown = function(n) restAsked = restAsked + 1 return realCool(n) end
        ns.UpdateQuestRings()
        ns.GetSkill, ns.IsOnCooldown = realSkill, realCool
        local ringCount = 0
        for _ in pairs(ns.QuestRings()) do ringCount = ringCount + 1 end
        assert(ringCount > 0, "test setup: no ring at this place")
        assert(skillReads >= 1 and skillReads <= 2, ("one look read your skill %d times (%d nodes in the zone, %d asked for their colour)"):format(skillReads, #list, asks))
        assert(restAsked <= within, ("one look asked %d nodes whether they rest, %d are within the radius"):format(restAsked, within))
        local info = ns.QuestLook()
        assert(info.nodes == #list and info.near > 0 and info.near <= within and info.rings == ringCount,
            ("what the look says about itself: %d nodes, %d near, %d rings"):format(info.nodes, info.near, info.rings))

        -- ---- /gcr debug: how long a look took, a line now and then
        local lines = {}
        ns.Debug = function(text) if tostring(text):find("^QUEST ") then lines[#lines + 1] = text end end
        ns.db.debug = false
        advance(6)
        assert(#lines == 0, "a line about the look without /gcr debug")
        ns.db.debug = true
        for _ = 1, 8 do ns.UpdateQuestRings() end
        assert(#lines == 1, ("8 looks in a row wrote %d lines, want one"):format(#lines))
        local ms, nodes, near, rings = lines[1]:match("^QUEST look ([%d%.]+) ms: (%d+) nodes in the zone, (%d+) near, (%d+) rings$")
        assert(ms and tonumber(nodes) == #list and tonumber(near) == info.near and tonumber(rings) == info.rings, "the line about the look: " .. tostring(lines[1]))
        advance(21) -- (about ten looks: one every 2 s)
        assert(#lines >= 3 and #lines <= 6, ("21 s wrote %d lines, want one about every 5 s"):format(#lines))
    end)
    ns.SetQuestMode(false)
    ns.GatherProfessions, ns.GetSkill, ns.IsOnCooldown, issecretvalue, ns.Debug = keep.gp, keep.skill, keep.cool, keep.secret, keep.say
    ns.db.chestsHidden, ns.db.hideGreyNodes, ns.db.questRadius, ns.db.questArrow, ns.db.debug = keep.chests, keep.grey, keep.radius, keep.arrow, keep.debug
    ns.db.nodes[Z] = keep.nodes
    player.map, player.x, player.y = keep.map, keep.x, keep.y
    fire("ZONE_CHANGED_NEW_AREA") advance(1)
    ns.NotifyNodesChanged() advance(1)
    if not ok then error(err, 0) end
end)
step("Questing mode: one ring per place, and none while something of its kind rests there (v0.1.21 T1)", function()
    -- Sven, 10.11.2026, Hillsbrad 57.0 / 8.5: Copper, Tin and Silver Vein are
    -- three entries at the very same spot (the starter data has one per sort
    -- a spawn point can hold). The tin was mined: only the tin entry rested,
    -- copper and silver there still counted - the gold ring stayed on a vein
    -- that was gone. For the rings, entries of one kind at one place are ONE
    -- place now. Nothing is written to the nodes for it.
    -- map 5000 x 3333 yd in the mock: 0.001 in x is 5 yd
    local Z, H = 1460, 1424
    local keep = { nodes = ns.db.nodes[Z], hills = ns.db.nodes[H], chests = ns.db.chestsHidden, grey = ns.db.hideGreyNodes, radius = ns.db.questRadius,
        arrow = ns.db.questArrow, gp = ns.GatherProfessions, skill = ns.GetSkill, map = player.map, x = player.x, y = player.y }
    local px, py = 0.5, 0.5
    local function At(yd, name, kind, extra)
        local n = { id = "o9" .. math.random(100000, 999999), name = name, type = kind, x = px + yd / 5000, y = py, count = 1, last = 1, hits = 1 }
        for k, v in pairs(extra or {}) do n[k] = v end
        table.insert(ns.db.nodes[Z], n)
        return n
    end
    local function Rings(among)
        ns.UpdateQuestRings()
        local lit, count = ns.QuestRings(), 0
        for _, n in ipairs(among) do if lit[n] then count = count + 1 end end
        return count
    end
    local ok, err = pcall(function()
        ns.SetQuestMode(false)
        ns.db.nodes[Z] = {}
        ns.db.chestsHidden, ns.db.hideGreyNodes, ns.db.questRadius, ns.db.questArrow = nil, nil, 75, true
        ns.GatherProfessions = function() return true, true, true end
        ns.GetSkill = function(kind) if kind == "ore" then return 70, 75, 70 elseif kind == "herb" then return 60, 75, 60 end end
        -- three sorts at one place, 20 yd away: copper (1) and tin (65) you
        -- can mine at 70, silver (75) not
        local copper = At(20, "Copper Vein", "ore")
        local tin = At(20, "Tin Vein", "ore")
        local silver = At(20, "Silver Vein", "ore")
        local vein = { copper, tin, silver }
        -- further out, another place of its own
        local far = At(60, "Copper Vein", "ore")
        player.map, player.x, player.y = Z, px, py
        fire("ZONE_CHANGED_NEW_AREA") advance(1)
        ns.NotifyNodesChanged() advance(1)
        ns.SetQuestMode(true) advance(1)
        local lit = ns.QuestRings()
        -- nothing mined: one ring for the place, on a sort you can mine
        assert(Rings(vein) == 1, ("three sorts at one place: %d rings, want one"):format(Rings(vein)))
        assert(lit[copper] and not lit[silver], "the ring of the place is not on a sort you can mine")
        assert(lit[far], "test setup: the other place")
        assert(ns.QuestArrowNode() == copper, "the arrow does not point at the place 20 yd away")
        -- the tin is mined (the recorder puts THAT entry to rest): the whole
        -- place has no ring, and the arrow goes on to the next one
        local before = {}
        for _, n in ipairs(vein) do before[n] = { n.emptyUntil, n.parked, n.source, n.hits, n.x, n.y, n.count, n.last } end
        tin.emptyUntil = time() + 600
        before[tin][1] = tin.emptyUntil
        assert(Rings(vein) == 0, ("the tin is mined: the place still has %d ring(s)"):format(Rings(vein)))
        assert(lit[far] and ns.QuestArrowNode() == far, "the arrow still points at a place where the vein is gone")
        -- ... and nothing was written to its neighbours for that
        for _, n in ipairs(vein) do
            local b = before[n]
            assert(n.emptyUntil == b[1] and n.parked == b[2] and n.source == b[3] and n.hits == b[4] and n.x == b[5] and n.y == b[6] and n.count == b[7] and n.last == b[8],
                "the questing mode wrote to a node: " .. n.name)
        end
        assert(ns.IsOnCooldown(tin) and not ns.IsOnCooldown(copper) and not ns.IsOnCooldown(silver), "a rest time was put on a neighbour")
        -- the rest is over: the ring is back
        tin.emptyUntil = time() - 1
        assert(Rings(vein) == 1 and ns.QuestArrowNode() == copper, "the ring does not come back when the rest is over")
        -- the sort you cannot mine rests: still the whole place
        silver.emptyUntil = time() + 600
        assert(Rings(vein) == 0, "the silver rests (a sort you cannot mine): the place keeps its ring")
        silver.emptyUntil = nil
        -- a parked entry at the place: no ring either
        tin.parked, tin.source, tin.hits = true, "sync", 0
        assert(ns.IsParked(tin) and Rings(vein) == 0, "a parked entry at the place: the place keeps its ring")
        tin.parked, tin.source, tin.hits = nil, nil, 1
        assert(Rings(vein) == 1, "test setup: the place again")
        -- only sorts you cannot mine at a place: no ring
        local onlyHigh = { At(-30, "Silver Vein", "ore"), At(-30, "Gold Vein", "ore") }
        assert(Rings(onlyHigh) == 0, "a place with only sorts you cannot mine has a ring")
        -- the first sort you cannot, the second you can: the ring is on the second
        local mixed = { At(-45, "Silver Vein", "ore"), At(-45, "Tin Vein", "ore") }
        assert(Rings(mixed) == 1 and lit[mixed[2]], "a place whose first entry you cannot mine gets no ring from the second")
        -- other kinds at the same spot are places of their own: a herb next
        -- to the vein keeps its ring while the vein rests, and the other way
        local herb = At(20, "Mageroyal", "herb")
        tin.emptyUntil = time() + 600
        assert(Rings(vein) == 0 and Rings({ herb }) == 1, "a resting vein takes the ring of a herb at the same spot")
        tin.emptyUntil = nil
        herb.emptyUntil = time() + 600
        assert(Rings(vein) == 1 and Rings({ herb }) == 0, "a resting herb takes the ring of a vein at the same spot")
        herb.emptyUntil = nil
        -- chests: two entries at one spot are one place too
        local chests = { At(35, "Battered Chest", "chest"), At(35, "Solid Chest", "chest") }
        assert(Rings(chests) == 1, ("two chests at one spot: %d rings"):format(Rings(chests)))
        chests[2].emptyUntil = time() + 600
        assert(Rings(chests) == 0, "one chest of the spot was opened: the spot keeps its ring")
        chests[2].emptyUntil = nil
        -- how close is one place: 8 yd apart is one (the recorder's own rule
        -- for "the same node"), 12 and 20 yd apart are two
        local eight = { At(-60, "Copper Vein", "ore"), At(-52, "Tin Vein", "ore") }
        local twelve = { At(-10, "Copper Vein", "ore"), At(2, "Tin Vein", "ore") }
        local twenty = { At(40, "Copper Vein", "ore"), At(40, "Tin Vein", "ore", { y = py + 20 / 3333 }) }
        assert(Rings(eight) == 1, ("8 yd apart: %d rings, want one"):format(Rings(eight)))
        assert(Rings(twelve) == 2, ("12 yd apart: %d rings, want two"):format(Rings(twelve)))
        assert(Rings(twenty) == 2, ("20 yd apart: %d rings, want two"):format(Rings(twenty)))
        twelve[1].emptyUntil = time() + 600
        assert(Rings(twelve) == 1 and lit[twelve[2]], "a resting vein 12 yd away takes the ring of the next place")
        twelve[1].emptyUntil = nil

        -- ---- Sven's place: the shipped spawn points of Hillsbrad
        local hills = QuestieZoneNodes(H)
        local spot = {}
        for _, n in ipairs(hills) do
            if math.abs(n.x - 0.57) < 0.0006 and math.abs(n.y - 0.085) < 0.0006 and n.type == "ore" then spot[#spot + 1] = n end
        end
        local names = {}
        for _, n in ipairs(spot) do names[#names + 1] = n.name end
        table.sort(names)
        assert(table.concat(names, ", ") == "Copper Vein, Silver Vein, Tin Vein", "test setup: at 57.0 / 8.5 the data has " .. table.concat(names, ", "))
        ns.db.nodes[H] = hills
        player.map, player.x, player.y = H, 0.5702, 0.0852
        fire("ZONE_CHANGED_NEW_AREA") advance(1)
        ns.NotifyNodesChanged() advance(1)
        assert(Rings(spot) == 1, ("Hillsbrad 57.0 / 8.5, nothing mined: %d rings"):format(Rings(spot)))
        for _, n in ipairs(spot) do if n.name == "Tin Vein" then n.emptyUntil = time() + 600 end end
        assert(Rings(spot) == 0, ("Hillsbrad 57.0 / 8.5, the tin mined: %d ring(s) stay"):format(Rings(spot)))
        -- the whole zone: no place has two rings
        ns.db.questRadius = 100
        for _, pos in ipairs({ { 0.5702, 0.0852 }, { 0.3, 0.4 }, { 0.62, 0.2 }, { 0.45, 0.72 } }) do
            player.x, player.y = pos[1], pos[2]
            ns.UpdateQuestRings()
            local carriers = {}
            for n in pairs(ns.QuestRings()) do carriers[#carriers + 1] = n end
            for i = 1, #carriers do
                for j = i + 1, #carriers do
                    local a, b = carriers[i], carriers[j]
                    assert(a.type ~= b.type or ns.Distance(H, a.x, a.y, b.x, b.y) > 10, ("two rings at one place: %s and %s"):format(a.name, b.name))
                end
            end
        end
        -- a look at the full zone stays quick (the mock's clock: a rough bound only)
        local t0 = os.clock()
        for _ = 1, 20 do ns.UpdateQuestRings() end
        local ms = (os.clock() - t0) * 1000 / 20
        assert(ms < 25, ("one look at %d nodes takes %.1f ms"):format(#hills, ms))
    end)
    ns.SetQuestMode(false)
    ns.GatherProfessions, ns.GetSkill = keep.gp, keep.skill
    ns.db.chestsHidden, ns.db.hideGreyNodes, ns.db.questRadius, ns.db.questArrow = keep.chests, keep.grey, keep.radius, keep.arrow
    ns.db.nodes[Z], ns.db.nodes[H] = keep.nodes, keep.hills
    player.map, player.x, player.y = keep.map, keep.x, keep.y
    fire("ZONE_CHANGED_NEW_AREA") advance(1)
    ns.NotifyNodesChanged() advance(1)
    if not ok then error(err, 0) end
end)
step("Minimap tooltip: a frame that covers the whole minimap counts as the minimap, a pin does not (v0.1.21 T2)", function()
    -- Sven, 10.11.2026, with Ellesmere UI: the game's tooltip showed "Tin
    -- Vein", Gathercraft said "minimap tooltip [UIParent, ignored]". Under the
    -- mouse was not the minimap but a nameless frame, a child of it, 255 x 256
    -- - like the minimap itself. Such a frame counts as the minimap now, for
    -- the tooltip of ours below the game's AND for learning by pointing (one
    -- check for both). A pin on the minimap does not, as before.
    local Z = 1466
    local names = GathercraftNodeNames and GathercraftNodeNames[GetLocale()]
    local herbName = names and names[1618] or "Peacebloom"
    local keep = { nodes = ns.db.nodes[Z], map = player.map, x = player.x, y = player.y, foci = GetMouseFoci, focus = GetMouseFocus, cursor = GetCursorPosition,
        cvar = GetCVar, secret = issecretvalue, learnOff = ns.db.minimapLearnOff }
    local mm, gt = {}, {}
    for _, k in ipairs({ "IsMouseOver", "GetCenter", "GetWidth", "GetHeight", "GetZoom", "GetEffectiveScale" }) do mm[k] = rawget(Minimap, k) end
    for _, k in ipairs({ "IsShown", "GetOwner", "NumLines" }) do gt[k] = rawget(GameTooltip, k) end
    local texts = {}
    local ok, err = pcall(function()
        -- the minimap as Ellesmere shows it: 255 x 256, centre at 500 / 400
        local lines, owner = {}, UIParent
        Minimap.IsMouseOver = function() return true end
        Minimap.GetCenter = function() return 500, 400 end
        Minimap.GetWidth = function() return 255 end
        Minimap.GetHeight = function() return 256 end
        Minimap.GetZoom = function() return 0 end
        Minimap.GetEffectiveScale = function() return 1 end
        GameTooltip.IsShown = function() return #lines > 0 end
        GameTooltip.GetOwner = function() return owner end
        GameTooltip.NumLines = function() return #lines end
        for i = 1, 3 do
            local fs = _G["GameTooltipTextLeft" .. i] or newObject("FontString", "GameTooltipTextLeft" .. i)
            _G["GameTooltipTextLeft" .. i] = fs
            texts[i] = rawget(fs, "GetText")
            fs.GetText = function() return lines[i] end
        end
        GetCursorPosition = function() return 540, 400 end
        GetCVar = function() return "0" end
        ns.db.minimapLearnOff = nil
        player.map, player.x, player.y = Z, 0.5, 0.5
        local mapID, cx, cy = ns.CursorOnMap()
        assert(mapID == Z and cx and cy, "test setup: the cursor on the map")
        -- a herb we know, right under the cursor, resting: pointing at it
        -- marks it as up (learning) and shows our tooltip below the game's
        local herb = { id = "o1618", name = herbName, type = "herb", x = cx, y = cy, count = 1, last = 1, source = "questie" }
        ns.db.nodes[Z] = { herb }
        ns.NotifyNodesChanged() advance(1)
        local tip
        -- what is under the mouse -> learned, our tooltip shown
        local function Point(focus)
            lines = {}
            advance(6) -- (the same name at the same place counts again after 5 s)
            herb.seenAt, herb.upAt, herb.emptyUntil = nil, nil, time() + 600
            if focus == "none" then
                GetMouseFoci, GetMouseFocus = nil, nil
            else
                GetMouseFoci = function() return { focus } end
            end
            lines = { herbName }
            local fine, problem = pcall(advance, 2)
            assert(fine, "pointing at the minimap raises an error: " .. tostring(problem))
            tip = tip or _G.GathercraftMinimapTooltip
            local learned = herb.seenAt ~= nil and not herb.emptyUntil
            local shown = (tip and tip:IsShown() and tip.node == herb) and true or false
            if ns.MouseOnMinimapItself then assert(ns.MouseOnMinimapItself() == learned, "the check for the mouse and the learning disagree") end
            return learned, shown
        end
        local function Child(w, h, x, y, parent)
            local f = newObject("Frame", nil, parent or Minimap)
            f:SetSize(w, h)
            f.GetCenter = function() return x or 500, y or 400 end
            return f
        end
        local learned, shown
        -- the minimap itself, as before
        learned, shown = Point(Minimap)
        assert(learned and shown, "the minimap under the mouse: not read any more")
        -- Sven's case: a nameless child of the minimap, as big as the minimap
        local cover = Child(255, 256)
        assert(cover:GetParent() == Minimap and cover:GetName() == nil, "test setup: the frame over the minimap")
        learned, shown = Point(cover)
        assert(learned, "a frame over the whole minimap: the tooltip is ignored (nothing learned)")
        assert(shown, "a frame over the whole minimap: our tooltip does not show below the game's")
        -- a few pixels off is still "the whole minimap", also at another scale
        learned, shown = Point(Child(253, 258, 502, 399))
        assert(learned and shown, "a frame 2 px off the minimap's size and place is not taken as the minimap")
        local scaled = Child(510, 512, 1000, 800)
        scaled.GetEffectiveScale = function() return 0.5 end
        learned, shown = Point(scaled)
        assert(learned and shown, "a frame over the whole minimap at half the scale is not taken as the minimap")
        -- a pin of another addon: a small child of the minimap
        learned, shown = Point(Child(16, 16, 540, 400))
        assert(not learned and not shown, "another addon's pin under the mouse: its tooltip was read")
        -- one of our own pins - whatever its size
        local ours = Child(255, 256)
        ours.node = herb
        learned, shown = Point(ours)
        assert(not learned and not shown, "one of our own pins is taken for the minimap")
        local target = Child(255, 256)
        target.isTarget = true
        learned = Point(target)
        assert(not learned, "the run target's pin is taken for the minimap")
        -- another size, another place, another parent: not the minimap
        learned = Point(Child(200, 256))
        assert(not learned, "a child 55 px narrower than the minimap is taken for it")
        learned = Point(Child(255, 200))
        assert(not learned, "a child 56 px lower than the minimap is taken for it")
        learned = Point(Child(255, 256, 540, 400))
        assert(not learned, "a child 40 px beside the minimap's place is taken for it")
        learned = Point(Child(255, 256, 500, 400, UIParent))
        assert(not learned, "a frame as big as the minimap that is no child of it is taken for it")
        local grand = Child(255, 256, 500, 400, Child(255, 256))
        learned = Point(grand)
        assert(not learned, "a grandchild of the minimap is taken for it")
        -- things that cannot be read: not the minimap, and no error
        learned = Point({})
        assert(not learned, "a thing without a size is taken for the minimap")
        local broken = Child(255, 256)
        broken.GetWidth = function() error("no width") end
        learned = Point(broken)
        assert(not learned, "a frame whose size cannot be read is taken for the minimap")
        local SECRET = newproxy(true)
        issecretvalue = function(v) return rawequal(v, SECRET) end
        local hidden = Child(255, 256)
        hidden.GetHeight = function() return SECRET end
        learned = Point(hidden)
        assert(not learned, "a frame with a hidden size is taken for the minimap")
        issecretvalue = keep.secret
        local odd = Child(255, 256)
        odd.GetCenter = function() return nil end
        learned = Point(odd)
        assert(not learned, "a frame without a place is taken for the minimap")
        -- the client tells nothing about the mouse (neither function): as before
        learned, shown = Point("none")
        assert(learned and shown, "without GetMouseFoci / GetMouseFocus the minimap tooltip is not read any more")
        -- only the old function, with the cover under the mouse
        GetMouseFoci, GetMouseFocus = nil, function() return cover end
        lines = {}
        advance(6)
        herb.seenAt, herb.upAt, herb.emptyUntil = nil, nil, time() + 600
        lines = { herbName }
        advance(2)
        assert(herb.seenAt and not herb.emptyUntil, "the cover under the mouse, told by the old function: not read")
        -- nothing was changed on the frames we looked at
        assert(cover:GetParent() == Minimap and cover.__w == 255 and cover.__h == 256 and cover.__shown ~= false, "a frame of another addon was changed")
        lines = {}
        advance(2)
    end)
    GetMouseFoci, GetMouseFocus, GetCursorPosition, GetCVar, issecretvalue = keep.foci, keep.focus, keep.cursor, keep.cvar, keep.secret
    for _, k in ipairs({ "IsMouseOver", "GetCenter", "GetWidth", "GetHeight", "GetZoom", "GetEffectiveScale" }) do Minimap[k] = mm[k] end
    for _, k in ipairs({ "IsShown", "GetOwner", "NumLines" }) do GameTooltip[k] = gt[k] end
    for i = 1, 3 do if _G["GameTooltipTextLeft" .. i] then _G["GameTooltipTextLeft" .. i].GetText = texts[i] end end
    ns.db.nodes[Z], ns.db.minimapLearnOff = keep.nodes, keep.learnOff
    player.map, player.x, player.y = keep.map, keep.x, keep.y
    ns.NotifyNodesChanged() advance(2)
    if not ok then error(err, 0) end
end)
step("Herbs / minerals switch button: on the screen, not on the minimap; follows it; the shape can be chosen (v0.1.21 T5)", function()
    -- Sven, 10.11.2026, Ellesmere UI, square minimap: the button was shown but
    -- had an effective alpha of 0 - something that goes through the minimap's
    -- children had faded it - and with no GetMinimapShape it sat on a circle.
    -- The button is a child of the screen now, only anchored to the minimap,
    -- and the shape can be chosen in the options.
    local btn = GathercraftTrackButton
    assert(btn, "no switch button")
    local saved = { shape = _G.GetMinimapShape, w = rawget(Minimap, "GetWidth"), h = rawget(Minimap, "GetHeight"), es = rawget(Minimap, "GetEffectiveScale"),
        ues = rawget(UIParent, "GetEffectiveScale"), angle = ns.db.trackButtonAngle, combat = InCombatLockdown, known = IsPlayerSpell,
        choice = ns.db.minimapShape, hidden = ns.db.trackButtonHidden, mparent = Minimap.__parent, mshown = Minimap.__shown,
        setAlpha = rawget(btn, "SetAlpha"), setScale = rawget(btn, "SetScale") }
    local function Pos()
        local p = btn.__pts and btn.__pts.CENTER
        assert(p and p[1] == Minimap and p[2] == "CENTER", "the button is not anchored to the minimap's centre")
        return p[3], p[4]
    end
    local function Near(a, b) return math.abs(a - b) < 0.5 end
    local function Radius() local x, y = Pos() return math.sqrt(x * x + y * y) end
    local ok, err = pcall(function()
        -- not a child of the minimap, nowhere up the line
        assert(btn:GetParent() ~= Minimap, "the button is a child of the minimap")
        assert(btn:GetParent() == UIParent, "the button is not a child of the screen (UIParent)")
        for _, o in ipairs(allFrames) do
            if o.__parent == Minimap then
                assert(o ~= btn and (not o.GetName or o:GetName() ~= "GathercraftTrackButton"), "the minimap has the switch button as a child")
            end
        end
        local alphas, scale = 0, nil
        btn.SetAlpha = function() alphas = alphas + 1 end
        btn.SetScale = function(_, s) scale = s end
        Minimap.GetWidth = function() return 140 end
        Minimap.GetHeight = function() return 140 end
        _G.GetMinimapShape = nil
        ns.db.minimapShape, ns.db.trackButtonAngle, ns.db.trackButtonHidden = nil, 250, nil
        IsPlayerSpell = function(id) return id == 2383 or id == 2580 or saved.known(id) end
        Minimap.__shown = true
        ns.UpdateTrackButton()
        assert(btn:IsShown(), "test setup: the button shows with both tracking spells")
        -- place, strata and level as before: on the minimap's edge, above it
        assert(Near(Radius(), 75), ("round: %.1f from the centre, want 75"):format(Radius()))
        assert(btn:GetFrameStrata() == "MEDIUM" and btn:GetFrameLevel() == Minimap:GetFrameLevel() + 8, "strata or level changed")
        -- as big as a child of the minimap would be: the minimap's scale
        assert(scale == 1, "the button's scale with minimap and screen at the same scale: " .. tostring(scale))
        Minimap.GetEffectiveScale = function() return 0.6 end
        UIParent.GetEffectiveScale = function() return 0.75 end
        ns.PlaceTrackButton()
        assert(scale and Near(scale * 100, 80), "a minimap at 0.6 on a screen at 0.75: the button's scale is " .. tostring(scale) .. ", want 0.8")
        Minimap.GetEffectiveScale = function() return nil end
        assert(pcall(ns.PlaceTrackButton) and scale == 1, "a scale that cannot be read: an error, or not 1")
        Minimap.GetEffectiveScale = function() error("no scale") end
        assert(pcall(ns.PlaceTrackButton) and scale == 1, "a scale that raises an error: an error, or not 1")
        Minimap.GetEffectiveScale, UIParent.GetEffectiveScale = saved.es, saved.ues

        -- the minimap hidden: the button goes; shown again: back
        Minimap:Hide()
        assert(not btn:IsShown(), "the minimap is hidden, the button still shows")
        Minimap:Show()
        assert(btn:IsShown(), "the minimap is back, the button is not")
        -- hidden through what the minimap sits in (its cluster)
        local cluster = newObject("Frame", nil, UIParent)
        Minimap.__parent = cluster
        cluster:Hide()
        ns.UpdateTrackButton()
        assert(not btn:IsShown(), "the minimap's parent is hidden, the button still shows")
        cluster:Show()
        ns.UpdateTrackButton()
        assert(btn:IsShown(), "the minimap's parent is back, the button is not")
        Minimap.__parent = saved.mparent
        -- in a fight nothing changes (a protected frame); the fight's end catches up
        InCombatLockdown = function() return true end
        Minimap:Hide()
        assert(btn:IsShown(), "the button was hidden in combat")
        InCombatLockdown = saved.combat
        fire("PLAYER_REGEN_ENABLED")
        assert(not btn:IsShown(), "after the fight the button still shows, the minimap is hidden")
        InCombatLockdown = function() return true end
        Minimap:Show()
        assert(not btn:IsShown(), "the button was shown in combat")
        InCombatLockdown = saved.combat
        fire("PLAYER_REGEN_ENABLED")
        assert(btn:IsShown(), "after the fight the button is not back")
        -- the option off: hidden, whatever the minimap does
        ns.db.trackButtonHidden = true
        ns.UpdateTrackButton()
        Minimap:Hide() Minimap:Show()
        assert(not btn:IsShown(), "the option is off, the button shows when the minimap comes back")
        ns.db.trackButtonHidden = nil
        ns.UpdateTrackButton()
        assert(btn:IsShown(), "the option is on again, no button")
        -- only one of the two spells known: no button when the minimap comes back
        IsPlayerSpell = saved.known
        Minimap:Hide() Minimap:Show()
        assert(not btn:IsShown(), "the button shows without both tracking spells when the minimap comes back")
        IsPlayerSpell = function(id) return id == 2383 or id == 2580 or saved.known(id) end
        ns.UpdateTrackButton()
        -- no fight against another addon: the alpha is never set
        assert(alphas == 0, "the button's alpha was set " .. alphas .. " times")

        -- the shape: Auto as before (what a UI addon tells, else round)
        local x, y
        _G.GetMinimapShape = function() return "SQUARE" end
        ns.PlaceTrackButton()
        x, y = Pos()
        assert(Near(y, -75) and math.abs(x) < 75, "Auto with a UI addon saying SQUARE: not on the rectangle's edge")
        _G.GetMinimapShape = nil
        ns.PlaceTrackButton()
        assert(Near(Radius(), 75), "Auto without a shape function: not round")
        -- Square chosen, no shape function (Sven's case): the rectangle's edge
        ns.db.minimapShape = "square"
        ns.PlaceTrackButton()
        x, y = Pos()
        assert(Near(y, -75), ("Square chosen, at 250 degrees: y %.1f, want -75 (the bottom edge)"):format(y))
        assert(Near(x / y, math.cos(math.rad(250)) / math.sin(math.rad(250))), "Square chosen: not in the direction of the angle")
        Minimap.GetWidth = function() return 255 end
        Minimap.GetHeight = function() return 256 end
        ns.db.trackButtonAngle = 180
        ns.PlaceTrackButton()
        x, y = Pos()
        assert(Near(x, -132.5) and Near(y, 0), ("Square chosen, a minimap of 255 x 256 at 180 degrees: %.1f, %.1f"):format(x, y))
        ns.db.trackButtonAngle = 45
        ns.PlaceTrackButton()
        x, y = Pos()
        assert(Near(x, 132.5) and Near(y, 132.5), ("Square chosen, 255 x 256 at 45 degrees: %.1f, %.1f"):format(x, y))
        Minimap.GetWidth = function() return 140 end
        Minimap.GetHeight = function() return 140 end
        -- Round chosen wins over a UI addon that says SQUARE
        ns.db.minimapShape = "round"
        _G.GetMinimapShape = function() return "SQUARE" end
        ns.PlaceTrackButton()
        assert(Near(Radius(), 75), "Round chosen: not on the circle")
        -- an odd saved value: Auto
        ns.db.minimapShape = "hexagon"
        ns.PlaceTrackButton()
        x, y = Pos()
        assert(Near(x, 75) and Near(y, 75), "an unknown saved shape is not taken as Auto")
        _G.GetMinimapShape = nil
        ns.db.minimapShape = nil

        -- the option: under General, next to the button's other things
        local label, less, more, value
        for _, o in ipairs(allFrames) do
            if o.GetText and o:GetText() == ns.L["Minimap shape"] then label = o end
            if o.gcShapeStep == -1 then less = o elseif o.gcShapeStep == 1 then more = o end
            if o.gcShapeValue then value = o end
        end
        assert(label and less and more and value, "no choice \"Minimap shape\" in the options")
        local p = label.__parent
        while p and not p.key do p = p.__parent end
        assert(p and p.key == "general", "the choice of the shape is not under General")
        assert(less.__parent == p and more.__parent == p, "the buttons of the choice are on another page")
        ns.db.trackButtonAngle = 45
        GathercraftOptions:Refresh() -- (as opening the options does)
        local function Shown() return value:GetText() end
        assert(Shown() == ns.L["Auto"], "the choice does not start at Auto: " .. tostring(Shown()))
        more.__scripts.OnClick(more)
        assert(ns.db.minimapShape == "round" and Shown() == ns.L["Round"], "> after Auto is not Round")
        assert(Near(Radius(), 75), "Round picked: the button did not move at once")
        more.__scripts.OnClick(more)
        assert(ns.db.minimapShape == "square" and Shown() == ns.L["Square"], "> after Round is not Square")
        x, y = Pos()
        assert(Near(x, 75) and Near(y, 75), "Square picked: the button did not move to the corner at once")
        more.__scripts.OnClick(more)
        assert(ns.db.minimapShape == nil and Shown() == ns.L["Auto"], "> after Square is not Auto (nothing saved)")
        less.__scripts.OnClick(less)
        assert(ns.db.minimapShape == "square", "< before Auto is not Square")
        less.__scripts.OnClick(less)
        less.__scripts.OnClick(less)
        assert(ns.db.minimapShape == nil, "< twice more is not Auto")
        -- in a fight the choice is saved, the button moves after it
        InCombatLockdown = function() return true end
        more.__scripts.OnClick(more) more.__scripts.OnClick(more)
        assert(ns.db.minimapShape == "square" and Near(Radius(), 75), "picked in combat: not saved, or the button moved")
        InCombatLockdown = saved.combat
        fire("PLAYER_REGEN_ENABLED")
        x, y = Pos()
        assert(Near(x, 75) and Near(y, 75), "picked in combat: not placed after the fight")
        assert(pcall(more.__scripts.OnEnter, more), "the tooltip of the choice")
        -- the page still fits
        local used = ns.OptionsUsedHeight()
        assert(used.general <= 640 - 112 - 18 - 4 - 66, "Options, General: " .. tostring(used.general) .. " px, too long")
        -- shift-drag still saves the angle
        local realShift, realCursor = IsShiftKeyDown, GetCursorPosition
        IsShiftKeyDown = function() return true end
        GetCursorPosition = function() return 400, 300 end
        ns.db.trackButtonAngle = nil
        btn.__scripts.OnDragStart(btn)
        assert(btn.__scripts.OnUpdate and pcall(btn.__scripts.OnUpdate, btn, 0.1), "dragging does not follow the cursor")
        btn.__scripts.OnDragStop(btn)
        IsShiftKeyDown, GetCursorPosition = realShift, realCursor
        assert(ns.db.trackButtonAngle, "dragging did not save the angle")
        assert(alphas == 0, "the button's alpha was set")
    end)
    _G.GetMinimapShape, InCombatLockdown, IsPlayerSpell = saved.shape, saved.combat, saved.known
    Minimap.GetWidth, Minimap.GetHeight, Minimap.GetEffectiveScale, UIParent.GetEffectiveScale = saved.w, saved.h, saved.es, saved.ues
    Minimap.__parent, Minimap.__shown = saved.mparent, saved.mshown
    btn.SetAlpha, btn.SetScale = saved.setAlpha, saved.setScale
    ns.db.trackButtonAngle, ns.db.minimapShape, ns.db.trackButtonHidden = saved.angle, saved.choice, saved.hidden
    ns.UpdateTrackButton()
    GathercraftOptions:Refresh()
    if not ok then error(err, 0) end
end)
step("Questing mode: in \"Ring only\" the rings are the thin gold ring, the run target stays broad (v0.1.21 T6)", function()
    -- Sven, 10.11.2026 23:11, about the questing mode's ring: "der ist mords
    -- dick". In the minimap style "Ring only" its rings took the run target's
    -- broad ring (RingGoldBold: the wall is 22 % of the texture). They take
    -- the thin one now (RingGold: 14 %), at the same size - the middle, where
    -- the game's yellow dot shows, gets wider. The run target is as it was.
    -- map 5000 x 3333 yd in the mock: 0.001 in x is 5 yd
    local Z = 1460
    local keep = { nodes = ns.db.nodes[Z], style = ns.db.miniPinStyle, size = ns.db.pinSize, chests = ns.db.chestsHidden,
        gp = ns.GatherProfessions, map = player.map, x = player.x, y = player.y }
    local px, py = 0.5, 0.5
    local function At(yd, name, kind)
        local n = { id = "o9" .. math.random(100000, 999999), name = name, type = kind, x = px + yd / 5000, y = py, count = 1, last = 1, hits = 1 }
        table.insert(ns.db.nodes[Z], n)
        return n
    end
    local function Tex(pin) return tostring(pin.ring and pin.ring.__tex or "") end
    local ok, err = pcall(function()
        ns.SetQuestMode(false)
        ns.db.nodes[Z] = {}
        local herb, ore, chest = At(20, "Peacebloom", "herb"), At(40, "Copper Vein", "ore"), At(-30, "Battered Chest", "chest")
        local far = At(60, "Silverleaf", "herb")
        player.map, player.x, player.y = Z, px, py
        fire("ZONE_CHANGED_NEW_AREA") advance(1)
        ns.db.miniPinStyle, ns.db.chestsHidden, ns.db.pinSize = nil, nil, nil -- ring only, chests shown
        ns.GatherProfessions = function() return true, true, true end
        ns.NotifyNodesChanged() advance(1)
        ns.SetQuestMode(true) advance(1)
        local function Rings()
            local list = {}
            for _, n in ipairs({ herb, ore, chest, far }) do
                local pin = ns.QuestRings()[n]
                assert(pin, "test setup: " .. n.name .. " has no ring")
                list[#list + 1] = pin
            end
            return list
        end
        -- the run target in a style: size, icon shown, texture
        local function TargetLook()
            ns.SetRouteTarget(Z, herb)
            local _, mini = ns.RouteTargetPins()
            local w, shown, tex = mini.__w, mini.icon.__shown ~= false, Tex(mini)
            ns.ClearRouteTarget()
            return w, shown, tex
        end
        -- ring only: every ring thin, no icon, as big as the run target
        local tw, tshown, ttex = TargetLook()
        assert(ttex:find("RingGoldBold$") and not tshown, "ring only: the run target is no longer the broad gold ring without an icon (" .. ttex .. ")")
        for _, pin in ipairs(Rings()) do
            assert(Tex(pin):find("RingGold$"), "ring only: the ring of " .. pin.node.name .. " is not the thin gold ring (" .. Tex(pin) .. ")")
            assert(pin.icon.__shown == false, "ring only: the ring of " .. pin.node.name .. " shows an icon")
            assert(pin.ring:IsShown(), "ring only: no ring texture shown")
            assert(pin.__w == tw and pin.__h == tw, ("ring only: the ring is %s px, the run target %s px"):format(tostring(pin.__w), tostring(tw)))
        end
        -- the style changes while the mode is on: every ring takes the new look
        for _, style in ipairs({ "subtle", "normal" }) do
            ns.db.miniPinStyle = style
            ns.NotifyNodesChanged() advance(1)
            tw, tshown, ttex = TargetLook()
            ns.NotifyNodesChanged() advance(1)
            assert(ttex:find("RingGold$") and tshown, style .. ": test setup, the run target is the icon in a thin gold ring")
            for _, pin in ipairs(Rings()) do
                assert(Tex(pin) == ttex and pin.__w == tw and pin.icon.__shown ~= false,
                    ("%s: the ring of %s is %s, %s px, icon %s - not the run target's look"):format(style, pin.node.name, Tex(pin), tostring(pin.__w), tostring(pin.icon.__shown ~= false)))
            end
        end
        -- and back to ring only: thin again, the icons gone again (pins are reused)
        ns.db.miniPinStyle = nil
        ns.NotifyNodesChanged() advance(1)
        tw = TargetLook()
        ns.NotifyNodesChanged() advance(1)
        for _, pin in ipairs(Rings()) do
            assert(Tex(pin):find("RingGold$") and pin.icon.__shown == false and pin.__w == tw, "back to ring only: the ring of " .. pin.node.name .. " kept the other style's look")
        end
        -- another pin size: the rings follow, still thin
        ns.db.pinSize = 20
        ns.NotifyNodesChanged() advance(1)
        local big = TargetLook()
        ns.NotifyNodesChanged() advance(1)
        assert(big > tw, "test setup: a bigger pin size gives a bigger target")
        for _, pin in ipairs(Rings()) do
            assert(Tex(pin):find("RingGold$") and pin.__w == big, "pin size 20: the ring of " .. pin.node.name .. " did not follow")
        end
        ns.db.pinSize = nil
        ns.NotifyNodesChanged() advance(1)
        -- a ring lit later (walking up to it) is thin too; one that went and came back as well
        ns.SetQuestMode(false) advance(1)
        ns.SetQuestMode(true) advance(1)
        for _, pin in ipairs(Rings()) do
            assert(Tex(pin):find("RingGold$") and pin.icon.__shown == false, "lit anew: the ring of " .. pin.node.name .. " is not thin")
        end
        -- the run target next to the rings: still the broad one
        ns.SetRouteTarget(Z, herb)
        local _, mini = ns.RouteTargetPins()
        assert(Tex(mini):find("RingGoldBold$") and mini.icon.__shown == false, "the run target lost its broad ring")
        ns.ClearRouteTarget()
    end)
    ns.SetQuestMode(false)
    ns.GatherProfessions = keep.gp
    ns.db.nodes[Z], ns.db.miniPinStyle, ns.db.pinSize, ns.db.chestsHidden = keep.nodes, keep.style, keep.size, keep.chests
    player.map, player.x, player.y = keep.map, keep.x, keep.y
    fire("ZONE_CHANGED_NEW_AREA") advance(1)
    ns.NotifyNodesChanged() advance(1)
    if not ok then error(err, 0) end
end)
step("Craft log: Create All ended by an aborted cast keeps its block; the header counts finished crafts (v0.1.21 T7)", function()
    -- Sven, 11.11.2026 19:05, 0.1.20: 3 crafts alone (quickly: a series, 3/3),
    -- then Create All, ended by moving after 5 successes - the usual way to
    -- end it. The log said "1 series, 3 crafts", "1 failed or interrupted",
    -- 5 overlapping, and the header counted the aborted cast as a craft.
    local data = GathercraftRecipeData
    local spell, other = data.spells.Leatherworking["Light Leather"], data.spells.Leatherworking["Light Armor Kit"]
    local saved = { rank = ns.ProfessionRank, have = ns.CraftData.Have, colors = data.colors[spell], colors2 = data.colors[other],
        log = ns.db.craftLog, off = ns.db.craftLogOff, multi = ns.db.craftMulti, secret = issecretvalue }
    local SECRET = newproxy(true)
    local rank, maxRank = 10, 75
    ns.ProfessionRank = function(p) if p == "Leatherworking" then return rank, maxRank end end
    ns.CraftData.Have = function() return 0 end
    data.colors[spell], data.colors[other] = "25:45", "25:45" -- orange below 25, yellow below 45, grey from 45
    ns.db.craftLog, ns.db.craftLogOff, ns.db.craftMulti = {}, nil, nil
    local n = 0
    local function Guid() n = n + 1 return "Cast-t7-" .. n end
    local function Start(sp) local g = Guid() fire("UNIT_SPELLCAST_START", "player", g, sp or spell) return g end
    local function Ok(g, gain, sp) rank = rank + (gain or 0) fire("UNIT_SPELLCAST_SUCCEEDED", "player", g, sp or spell) end
    local function Abort(g, how, sp) fire(how or "UNIT_SPELLCAST_INTERRUPTED", "player", g, sp or spell) end
    -- Create All: every cast takes castTime, the next starts the moment the
    -- last succeeded; returns the cast that is running at the end
    local function CreateAll(gains, castTime)
        local g = Start()
        for _, gain in ipairs(gains) do
            advance(castTime or 3)
            Ok(g, gain)
            g = Start()
        end
        return g
    end
    local function Blocks()
        local list = {}
        for _, e in ipairs(ns.db.craftLog) do if e.kind == "series" then list[#list + 1] = e end end
        return list
    end
    local function Reset(skill) advance(3) ns.db.craftLog, ns.db.craftMulti = {}, nil rank = skill advance(3) end
    local function Text()
        local mark = #log
        slash("craftlog")
        return table.concat(log, "\n", mark + 1)
    end
    local function Says(count) return (ns.L["Craft log: %d crafts (kept on this computer, never shared)."]):format(count) end
    local function NotCounted(failed, unreadable, overlap, cap, multi)
        return (ns.L["  Not counted: %d failed or interrupted, %d unreadable, %d overlapping, %d at the rank's maximum; %d gave more than one point."]):format(failed, unreadable, overlap, cap, multi)
    end
    local ok, err = pcall(function()
        advance(3)
        -- (1) Sven's case: 3 quickly one after the other, then Create All:
        -- 5 successes, the sixth cast ended by moving
        for _ = 1, 3 do Ok(Start(), 1) advance(0.3) end
        advance(3)
        local g = CreateAll({ 1, 1, 1, 1, 1 })
        advance(1)
        Abort(g)
        advance(3)
        local blocks = Blocks()
        assert(#blocks == 2, "Sven's case: " .. #blocks .. " blocks, want the 3 and the 5")
        local b = blocks[2]
        assert(b.n == 5 and b.before == 13 and b.after == 18 and b.gain == 5 and b.colour == "orange",
            ("the block of Create All: n %s, %s -> %s, gain %s, %s"):format(tostring(b.n), tostring(b.before), tostring(b.after), tostring(b.gain), tostring(b.colour)))
        local byColour, _, others = ns.CraftLogSummary()
        assert(others.series == 2 and others.seriesTries == 8 and others.seriesUps == 8, "the series line: " .. others.series .. " series, " .. others.seriesTries .. " crafts")
        assert(others.failed == 1 and others.overlap == 0, ("%d failed, %d overlapping - want 1 and 0"):format(others.failed, others.overlap))
        assert(byColour.orange.tries == 8 and byColour.orange.ups == 8, "orange: " .. byColour.orange.ups .. "/" .. byColour.orange.tries)
        local text = Text()
        assert(text:find(Says(8), 1, true), "the header does not say 8 crafts (the aborted cast is none): " .. text:sub(1, 90))
        assert(text:find(NotCounted(1, 0, 0, 0, 0), 1, true), "not counted: " .. text)
        -- the aborted cast is in the log, as it was: outside the block
        local aborted
        for _, e in ipairs(ns.db.craftLog) do if e.result == "interrupted" then aborted = e end end
        assert(aborted and not aborted.inSeries and not aborted.kind, "the aborted cast is not in the log as interrupted")

        -- (2) the abort comes while the last success is still being read
        -- (within 1.5 s), and the client tells it twice (interrupted, failed)
        Reset(31) -- (31 -> 34: 14 to 11 below grey, one distance group)
        g = CreateAll({ 1, 0, 1, 1, 0 })
        advance(0.4)
        Abort(g) Abort(g, "UNIT_SPELLCAST_FAILED")
        advance(3)
        blocks = Blocks()
        assert(#blocks == 1 and blocks[1].n == 5 and blocks[1].gain == 3 and blocks[1].before == 31 and blocks[1].after == 34 and blocks[1].colour == "yellow",
            "an abort 0.4 s after the last success: no block of 5 with 3 points")
        byColour, _, others = ns.CraftLogSummary()
        assert(others.failed == 1 and others.overlap == 0 and byColour.yellow.tries == 5 and byColour.yellow.ups == 3, "yellow 3/5 and one failed")
        assert(Text():find(Says(5), 1, true), "the header after 5 crafts and an abort")

        -- (3) a cast that fails (not interrupted) at the end: the same
        Reset(10)
        g = CreateAll({ 1, 1 })
        advance(2)
        Abort(g, "UNIT_SPELLCAST_FAILED")
        advance(3)
        assert(#Blocks() == 1 and Blocks()[1].n == 2 and select(3, ns.CraftLogSummary()).failed == 1, "a failed cast at the end: no block of 2")

        -- (4) a failure that never started (no START of its own), at the end
        Reset(10)
        Ok(Start(), 1) advance(0.3)
        Ok(Start(), 1) advance(0.3)
        Ok(Start(), 1) advance(0.3)
        Abort(Guid(), "UNIT_SPELLCAST_FAILED")
        advance(3)
        assert(#Blocks() == 1 and Blocks()[1].n == 3 and Blocks()[1].gain == 3, "a failure without a start at the end: no block of 3")
        assert(select(3, ns.CraftLogSummary()).failed == 1, "the failure without a start is not in the log")

        -- (5) two aborted attempts after the last success: still the block
        Reset(10)
        g = CreateAll({ 1, 1, 1 }, 0.3)
        Abort(g)
        advance(0.2)
        g = Start()
        advance(0.2)
        Abort(g)
        advance(3)
        assert(#Blocks() == 1 and Blocks()[1].n == 3, "two aborted casts at the end: no block of 3")
        assert(select(3, ns.CraftLogSummary()).failed == 2, "two aborted casts: not 2 failed")

        -- (6) an abort in the middle - a success of the same series after it:
        -- everything stays overlapping, as before
        Reset(10)
        Ok(Start(), 1) advance(0.3)
        Ok(Start(), 1) advance(0.3)
        g = Start() advance(0.2) Abort(g) advance(0.2)
        Ok(Start(), 1) advance(0.3)
        Ok(Start(), 1) advance(3)
        byColour, _, others = ns.CraftLogSummary()
        assert(#Blocks() == 0 and others.overlap == 4 and others.failed == 1 and not byColour.orange,
            ("an abort in the middle: %d blocks, %d overlapping, %d failed"):format(#Blocks(), others.overlap, others.failed))
        assert(Text():find(Says(4), 1, true), "the header: 4 overlapping crafts are crafts, the aborted cast is none")
        -- a failure without a start in the middle: the same
        Reset(10)
        Ok(Start(), 1) advance(0.3)
        Ok(Start(), 1) advance(0.3)
        Abort(Guid(), "UNIT_SPELLCAST_FAILED") advance(0.2)
        Ok(Start(), 1) advance(3)
        byColour, _, others = ns.CraftLogSummary()
        assert(#Blocks() == 0 and others.overlap == 3 and others.failed == 1 and not byColour.orange, "a failure without a start in the middle: counted")

        -- (7) an abort as the only cast: only "failed", no craft
        Reset(10)
        g = Start() advance(1) Abort(g) advance(3)
        byColour, _, others = ns.CraftLogSummary()
        assert(#ns.db.craftLog == 1 and others.failed == 1 and others.overlap == 0 and not next(byColour), "an abort alone")
        assert(Text():find(Says(0), 1, true), "an abort alone: the header does not say 0 crafts")
        -- one success and the abort of the next cast: no block of one (a
        -- block needs two); the craft stays overlapping, as before
        Reset(10)
        g = CreateAll({ 1 })
        advance(1) Abort(g) advance(3)
        byColour, _, others = ns.CraftLogSummary()
        assert(#Blocks() == 0 and others.overlap == 1 and others.failed == 1, "one success and an abort")
        assert(Text():find(Says(1), 1, true), "one success and an abort: the header does not say 1 craft")

        -- (8) the other conditions of a block stay: a colour change (23 -> 27)
        Reset(23)
        g = CreateAll({ 1, 1, 1, 1 })
        advance(1) Abort(g) advance(3)
        assert(#Blocks() == 0 and select(3, ns.CraftLogSummary()).overlap == 4, "aborted at the end, over a colour change: a block")
        -- at the rank's maximum
        Reset(73)
        g = CreateAll({ 1, 1, 0 })
        advance(1) Abort(g) advance(3)
        assert(#Blocks() == 0, "aborted at the end, at the maximum: a block")
        -- more points than crafts
        Reset(10)
        g = CreateAll({ 2, 2 })
        advance(2) Abort(g) advance(3)
        assert(#Blocks() == 0, "aborted at the end, more points than crafts: a block")
        -- a hidden skill inside
        Reset(10)
        g = Start() advance(3) Ok(g, 1)
        issecretvalue = function(v) return rawequal(v, SECRET) end
        local keepRank = rank
        rank = SECRET
        g = Start()
        rank = keepRank
        issecretvalue = saved.secret
        advance(3) Ok(g, 1)
        g = Start() advance(1) Abort(g) advance(3)
        assert(#Blocks() == 0, "aborted at the end, a hidden skill inside: a block")
        -- the note that a craft of this profession gave more than one point
        Reset(10)
        ns.db.craftMulti = { Leatherworking = true }
        g = CreateAll({ 1, 1, 1 })
        advance(1) Abort(g) advance(3)
        assert(#Blocks() == 0 and select(3, ns.CraftLogSummary()).overlap == 3, "aborted at the end, with the note of a multi-point craft: a block")
        -- another recipe started while the last success is being read
        Reset(10)
        g = CreateAll({ 1, 1 }, 0.3)
        Abort(g)
        Ok(Start(other), 1, other) advance(3)
        assert(#Blocks() == 0, "aborted, then another recipe inside the last reading: a block")

        -- (9) the switch (a hard break) is as it was: off while the series runs - no block
        Reset(10)
        g = CreateAll({ 1, 1, 1 })
        advance(0.4)
        ns.db.craftLogOff = true
        ns.CraftLogBreak()
        Abort(g)
        ns.db.craftLogOff = nil
        ns.CraftLogBreak()
        advance(3)
        assert(#Blocks() == 0, "switched off before the abort: a block")
        -- cleared between the last success and the abort: nothing of it comes back
        Reset(10)
        g = CreateAll({ 1, 1, 1 })
        advance(0.4)
        slash("craftlog clear")
        Abort(g)
        advance(3)
        assert(#ns.db.craftLog == 0, "cleared before the abort: " .. #ns.db.craftLog .. " entries came back")

        -- (10) after the abort, once everything is read, the next Create All
        -- is a series of its own
        Reset(10)
        g = CreateAll({ 1, 1, 1 })
        advance(2) Abort(g)
        g = CreateAll({ 1, 1 })
        advance(1) Abort(g) advance(3)
        blocks = Blocks()
        assert(#blocks == 2 and blocks[1].n == 3 and blocks[1].before == 10 and blocks[1].after == 13 and blocks[2].n == 2 and blocks[2].before == 13 and blocks[2].after == 15,
            "two Create All, each ended by an abort: not a block of 3 and one of 2")
        assert(Text():find(Says(5), 1, true), "two aborted Create All: the header does not say 5 crafts")

        -- (11) the header: a failed cast is no craft, a block stands for its
        -- crafts, old entries count as before
        ns.db.craftLog = {
            { t = 1, result = "failed", prof = "Leatherworking", spell = spell, colour = "orange", before = 5 },
            { t = 2, result = "interrupted", prof = "Leatherworking", spell = spell, colour = "orange", before = 5 },
            { t = 3, result = "ok", prof = "Leatherworking", spell = spell, colour = "orange", before = 12, after = 13, gain = 1, overlap = true, inSeries = true },
            { kind = "series", t = 1, result = "ok", prof = "Leatherworking", spell = spell, colour = "orange", n = 7, before = 6, after = 13, gain = 7, yellow = 25, grey = 45, max = 75 },
            { t = 9, result = "ok", prof = "Leatherworking", spell = spell, colour = "orange", before = 13, after = 14, gain = 1, yellow = 25, grey = 45, max = 75 },
            { t = 10, result = "ok", prof = "Leatherworking", spell = spell, colour = "unknown", secret = true },
            { t = 11, result = "ok", prof = "Leatherworking", spell = spell, colour = "orange", before = 14, after = 15, gain = 1, overlap = true },
        }
        assert(ns.CraftLogCrafts() == 10, "the header's count: " .. tostring(ns.CraftLogCrafts()) .. ", want 7 + 1 + 1 + 1")
        text = Text()
        assert(text:find(Says(10), 1, true) and text:find(NotCounted(2, 1, 1, 0, 0), 1, true), "the header and the line of what is not counted: " .. text)
    end)
    ns.ProfessionRank, ns.CraftData.Have, data.colors[spell], data.colors[other] = saved.rank, saved.have, saved.colors, saved.colors2
    ns.db.craftLogOff, issecretvalue = saved.off, saved.secret
    advance(3)
    ns.db.craftLog, ns.db.craftMulti = saved.log, saved.multi
    advance(3)
    if not ok then error(err, 0) end
end)
step("Craft log: a craft without a reliable \"before\" is no proof of a multi-point craft and in no rate (v0.1.21 T8)", function()
    -- Sven, 11.11.2026 19:10, 0.1.20: during Create All (Cooking) recording
    -- switched off and on again for a craft or two. After that: "Series of
    -- Cooking are not counted: a craft there gave more than one point." The
    -- chat showed exactly +1 after every "You create".
    local data = GathercraftRecipeData
    local spell, other = data.spells.Leatherworking["Light Leather"], data.spells.Leatherworking["Light Armor Kit"]
    local saved = { rank = ns.ProfessionRank, have = ns.CraftData.Have, colors = data.colors[spell], colors2 = data.colors[other],
        log = ns.db.craftLog, off = ns.db.craftLogOff, multi = ns.db.craftMulti, secret = issecretvalue }
    local SECRET = newproxy(true)
    local rank, maxRank = 10, 75
    ns.ProfessionRank = function(p) if p == "Leatherworking" then return rank, maxRank end end
    ns.CraftData.Have = function() return 0 end
    data.colors[spell], data.colors[other] = "25:45", "25:45" -- orange below 25
    ns.db.craftLog, ns.db.craftLogOff, ns.db.craftMulti = {}, nil, nil
    local n = 0
    local function Guid() n = n + 1 return "Cast-t8-" .. n end
    local function Start(sp) local g = Guid() fire("UNIT_SPELLCAST_START", "player", g, sp or spell) return g end
    -- the point of a craft arrives LAG seconds after its success (as in the
    -- game: later than the event)
    local LAG = 0.5
    local function Ok(g, gain, sp)
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", g, sp or spell)
        if gain and gain ~= 0 then C_Timer.After(LAG, function() rank = rank + gain end) end
    end
    -- the option's switch, as Options.lua does it
    local function Switch(on)
        ns.db.craftLogOff = not on or nil
        ns.CraftLogBreak()
    end
    local function Blocks()
        local list = {}
        for _, e in ipairs(ns.db.craftLog) do if e.kind == "series" then list[#list + 1] = e end end
        return list
    end
    local function Reset(skill) advance(3) ns.db.craftLog, ns.db.craftMulti = {}, nil rank = skill advance(3) end
    local function NoteLine()
        local mark = #log
        slash("craftlog")
        local text = table.concat(log, "\n", mark + 1)
        return text:find((ns.L["  Series of %s are not counted: a craft there gave more than one point."]):format(ns.L["Leatherworking"]), 1, true) ~= nil, text
    end
    -- nothing in the log says more points than crafts
    local function Honest(what)
        local byColour, byGap, others = ns.CraftLogSummary()
        for colour, c in pairs(byColour) do assert(c.ups <= c.tries, what .. ": " .. colour .. " " .. c.ups .. "/" .. c.tries) end
        for _, g in pairs(byGap) do assert(g.ups <= g.tries, what .. ": a distance line with more points than crafts") end
        assert(others.multi == 0, what .. ": " .. others.multi .. " \"gave more than one point\"")
        for _, e in ipairs(ns.db.craftLog) do
            assert(not (e.multi and not e.overlap), what .. ": a craft with " .. tostring(e.gain) .. " points counts alone")
        end
        return byColour, others
    end
    local ok, err = pcall(function()
        advance(3)
        -- (1) Sven's test 6: Create All with 3 s casts, every craft +1. Off
        -- during the second cast, on again during the third.
        local g = Start()                    -- A
        advance(3) Ok(g, 1) g = Start()      -- B runs
        advance(1) Switch(false)
        advance(2) Ok(g, 1) g = Start()      -- B succeeds (off), C runs
        advance(1) Switch(true)
        advance(2) Ok(g, 1) g = Start()      -- C succeeds: over for the log. D starts - C's point is not there yet
        advance(3) Ok(g, 1) g = Start()      -- D succeeds, E runs
        advance(2)                           -- D is read: 2 more than at its start
        assert(not (ns.db.craftMulti and ns.db.craftMulti.Leatherworking), "switched off and on during Create All: the note \"a craft gave more than one point\" is set")
        advance(1) Ok(g, 1) g = Start()      -- E succeeds, F runs
        advance(3) Ok(g, 1) g = Start()      -- F succeeds, a last cast runs
        advance(1) fire("UNIT_SPELLCAST_INTERRUPTED", "player", g, spell) -- ended by moving
        advance(3)
        assert(rank == 16, "test setup: six crafts, six points (" .. rank .. ")")
        local noted, text = NoteLine()
        assert(not noted and not ns.db.craftMulti, "the line \"Series of ... are not counted\" shows: " .. text)
        local byColour, others = Honest("after the switch")
        assert(not byColour.orange or byColour.orange.tries <= 1, "crafts after the switch are in the rates: orange " .. tostring(byColour.orange and byColour.orange.ups) .. "/" .. tostring(byColour.orange and byColour.orange.tries))
        assert(#Blocks() == 0, "a block out of the crafts after the switch")
        -- D is in the log, marked: it started while C's point was on its way
        local blind = 0
        for _, e in ipairs(ns.db.craftLog) do
            if e.blind then
                blind = blind + 1
                assert(e.blind == "settle" and e.overlap and e.result == "ok", "the craft after the switch: blind " .. tostring(e.blind))
            end
        end
        assert(blind == 1, blind .. " crafts marked as started while another's point was on its way, want 1 (D)")
        -- the next Create All, after a pause, counts as ever: a block of 3
        advance(3)
        g = Start()
        for _ = 1, 3 do advance(3) Ok(g, 1) g = Start() end
        advance(1) fire("UNIT_SPELLCAST_INTERRUPTED", "player", g, spell)
        advance(3)
        assert(#Blocks() == 1 and Blocks()[1].n == 3 and Blocks()[1].gain == 3 and Blocks()[1].before == 16 and Blocks()[1].after == 19,
            "the next Create All after the switch is not a block of 3 (" .. #Blocks() .. " blocks)")

        -- (2) the same with single crafts: one made while off, the next
        -- started at once after switching on
        Reset(10)
        Switch(false)
        g = Start() advance(3) Ok(g, 1)
        Switch(true)
        g = Start() advance(3) Ok(g, 1) advance(3)
        assert(not ns.db.craftMulti, "a craft started right after one made while off: taken as proof of a multi-point craft")
        assert(#ns.db.craftLog == 1 and ns.db.craftLog[1].blind == "settle" and ns.db.craftLog[1].overlap, "that craft is not marked overlapping")
        Honest("a craft right after one made while off")
        -- one second after it: still inside the 1.5 s
        Reset(10)
        Switch(false)
        g = Start() advance(3) Ok(g, 1)
        Switch(true)
        advance(1)
        g = Start() advance(3) Ok(g, 1) advance(3)
        assert(#ns.db.craftLog == 1 and ns.db.craftLog[1].blind == "settle" and ns.db.craftLog[1].overlap, "a craft 1 s after one made while off counts")
        -- 1.5 s after the craft made while off, a craft counts as ever
        Reset(10)
        Switch(false)
        g = Start() advance(3) Ok(g, 1)
        Switch(true)
        advance(1.6)
        g = Start() advance(3) Ok(g, 1) advance(3)
        byColour = ns.CraftLogSummary()
        assert(#ns.db.craftLog == 1 and not ns.db.craftLog[1].overlap and not ns.db.craftLog[1].blind and ns.db.craftLog[1].gain == 1 and byColour.orange.tries == 1 and byColour.orange.ups == 1,
            "a craft 1.6 s after one made while off does not count")

        -- (3) a success whose start was never seen (after a reload in the
        -- middle of a cast, say): no "before" at all
        Reset(10)
        Ok(Guid(), 1) -- no START
        g = Start()   -- Create All goes on
        advance(3) Ok(g, 1) g = Start()
        advance(3) Ok(g, 1)
        advance(3)
        assert(not ns.db.craftMulti, "a success without a start: taken as proof of a multi-point craft")
        local first = ns.db.craftLog[1]
        assert(first and first.blind == "start" and first.before == nil and first.overlap and first.result == "ok" and first.gain == nil,
            "a success without a start: blind " .. tostring(first and first.blind) .. ", before " .. tostring(first and first.before))
        byColour, others = Honest("a success without a start")
        assert(not next(byColour) and #Blocks() == 0 and others.overlap == 3, "a success without a start, then two more of Create All: " .. others.overlap .. " overlapping, want all 3")
        -- with a late point that makes two at once: still no note
        Reset(10)
        g = Start() advance(3) Ok(g, 1)        -- a normal craft, its point 0.5 s later
        advance(0.2)
        Ok(Guid(), 1)                          -- a success without a start, inside the reading
        advance(3)
        assert(not ns.db.craftMulti, "a success without a start inside a reading: the note is set")
        Honest("a success without a start inside a reading")
        assert(select(3, ns.CraftLogSummary()).overlap == 2, "both are not overlapping")

        -- (4) login, reload, a loading screen: what succeeded just before was not seen
        Reset(10)
        fire("PLAYER_ENTERING_WORLD", false, true)
        C_Timer.After(LAG, function() rank = rank + 1 end) -- the point of a craft made just before
        g = Start() advance(3) Ok(g, 1) advance(3)
        assert(not ns.db.craftMulti and ns.db.craftLog[1].blind == "settle" and ns.db.craftLog[1].overlap, "a craft started right after a reload: counted alone, +" .. tostring(ns.db.craftLog[1].gain))
        Honest("right after a reload")
        Reset(10)
        fire("PLAYER_ENTERING_WORLD", false, true)
        advance(1.6)
        g = Start() advance(3) Ok(g, 1) advance(3)
        assert(not ns.db.craftLog[1].blind and not ns.db.craftLog[1].overlap, "a craft 1.6 s after a reload does not count")

        -- (5) cleared while a craft is still being read, the next starts at once
        Reset(10)
        g = Start() advance(3) Ok(g, 1)
        advance(0.2)
        slash("craftlog clear")
        g = Start() advance(3) Ok(g, 1) advance(3)
        assert(not ns.db.craftMulti, "a craft started right after a clear: taken as proof of a multi-point craft")
        assert(#ns.db.craftLog == 1 and ns.db.craftLog[1].blind == "settle" and ns.db.craftLog[1].overlap, "a craft started right after a clear inside a reading is not overlapping")
        -- cleared with nothing being read: the next craft counts
        Reset(10)
        slash("craftlog clear")
        g = Start() advance(3) Ok(g, 1) advance(3)
        assert(#ns.db.craftLog == 1 and not ns.db.craftLog[1].overlap and ns.db.craftLog[1].gain == 1, "a craft after a clear with nothing open does not count")

        -- (6) a craft with a hidden cast ID, the next starts at once
        Reset(10)
        issecretvalue = function(v) return rawequal(v, SECRET) end
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", SECRET, spell)
        C_Timer.After(LAG, function() rank = rank + 1 end)
        issecretvalue = saved.secret
        g = Start() advance(3) Ok(g, 1) advance(3)
        assert(not ns.db.craftMulti, "a craft started right after one with a hidden cast ID: taken as proof of a multi-point craft")
        Honest("right after a hidden cast ID")

        -- (7) a cast open at a switch that succeeds later, the next at once
        Reset(10)
        g = Start()
        advance(1) Switch(false) Switch(true)
        advance(2) Ok(g, 1)
        g = Start() advance(3) Ok(g, 1) advance(3)
        assert(not ns.db.craftMulti and #ns.db.craftLog == 1 and ns.db.craftLog[1].overlap, "a craft started right after a cast that was open at a switch")
        Honest("right after a cast open at a switch")

        -- (8) what must stay: a repeated event of a logged cast is nothing
        -- new - Create All stays a block
        Reset(10)
        g = Start()
        for _ = 1, 4 do
            advance(3)
            Ok(g, 1)
            fire("UNIT_SPELLCAST_SUCCEEDED", "player", g, spell) -- told twice
            g = Start()
        end
        advance(1) fire("UNIT_SPELLCAST_INTERRUPTED", "player", g, spell)
        advance(3)
        assert(#Blocks() == 1 and Blocks()[1].n == 4 and Blocks()[1].gain == 4, "successes told twice: no block of 4")
        -- a spell that is no recipe, cast while off or ignored, makes nothing blind
        Reset(10)
        Switch(false)
        fire("UNIT_SPELLCAST_START", "player", "Cast-t8-hearth", 8690)
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", "Cast-t8-hearth", 8690)
        Switch(true)
        g = Start() advance(3) Ok(g, 1) advance(3)
        assert(#ns.db.craftLog == 1 and not ns.db.craftLog[1].blind and not ns.db.craftLog[1].overlap, "a spell that is no recipe made the next craft blind")
        -- a cast begun while off that is aborted after switching on made
        -- nothing: the next craft counts
        Reset(10)
        Switch(false)
        g = Start()
        advance(1)
        Switch(true)
        fire("UNIT_SPELLCAST_INTERRUPTED", "player", g, spell)
        g = Start() advance(3) Ok(g, 1) advance(3)
        assert(#ns.db.craftLog == 1 and not ns.db.craftLog[1].blind and not ns.db.craftLog[1].overlap and ns.db.craftLog[1].gain == 1,
            "an aborted cast that was begun while off made the next craft blind")
        -- a blind cast breaks a series that is still open (its last cast
        -- never ended for the log - a loading screen, say): no block
        Reset(10)
        g = Start() advance(3) Ok(g, 0)   -- A, no point
        local b = Start()                   -- B, in A's reading: a series
        advance(2)
        fire("PLAYER_ENTERING_WORLD", false, false)
        local c = Start()                   -- C: blind
        advance(1) Ok(c, 1)
        advance(0.2) Ok(b, 1)               -- B's success after all
        advance(3)
        assert(#Blocks() == 0, "a blind cast while a series was open: a block of 2 with 2 points (A gave none)")
        Honest("a blind cast while a series was open")
        -- a failure never makes the next craft blind
        Reset(10)
        fire("UNIT_SPELLCAST_FAILED", "player", Guid(), spell)
        g = Start() advance(3) Ok(g, 1) advance(3)
        local counted = 0
        for _, e in ipairs(ns.db.craftLog) do if e.result == "ok" and not e.overlap and e.gain == 1 then counted = counted + 1 end end
        assert(counted == 1, "a craft after a failure without a start does not count")

        -- (9) a real single craft with two points, its start seen, nothing
        -- unsettled: the note is set as before
        Reset(10)
        g = Start() advance(3) Ok(g, 2) advance(3)
        assert(ns.db.craftMulti and ns.db.craftMulti.Leatherworking, "a clear single craft with two points: no note")
        assert(NoteLine(), "the line of the note does not show")
        -- and an old log (0.1.20) with such an entry still gives the note
        ns.db.craftMulti = nil
        ns.db.craftLog = {
            { t = 1, result = "ok", prof = "Leatherworking", spell = spell, colour = "orange", before = 10, after = 12, gain = 2, multi = true },
        }
        g = Start() advance(0.3) Ok(g, 1) g = Start() advance(0.3) Ok(g, 1) advance(3)
        assert(ns.db.craftMulti and ns.db.craftMulti.Leatherworking and #Blocks() == 0, "an old entry with two points: the note is not found again")
        -- an entry marked blind never gives it
        ns.db.craftMulti = nil
        ns.db.craftLog = {
            { t = 1, result = "ok", prof = "Leatherworking", spell = spell, colour = "orange", before = 10, after = 12, gain = 2, multi = true, blind = "settle" },
        }
        rank = 12
        advance(3)
        g = Start() advance(0.3) Ok(g, 1) g = Start() advance(0.3) Ok(g, 1) advance(3)
        assert(not ns.db.craftMulti and #Blocks() == 1, "an entry marked blind is taken as proof of a multi-point craft")
    end)
    advance(3)
    ns.ProfessionRank, ns.CraftData.Have, data.colors[spell], data.colors[other] = saved.rank, saved.have, saved.colors, saved.colors2
    ns.db.craftLogOff, issecretvalue = saved.off, saved.secret
    if ns.CraftLogBreak then ns.CraftLogBreak() end
    advance(3)
    ns.db.craftLog, ns.db.craftMulti = saved.log, saved.multi
    if not ok then error(err, 0) end
end)
step("Gathering help: in the questing mode the Fish key gathers only while a node is marked, else it fishes (v0.1.21 T4)", function()
    -- Sven, 10.11.2026 20:36, 0.1.19: the option on, the questing mode on, at
    -- the water - the Fish key did nothing. It was "interact" for as long as
    -- the mode was on; with no node marked nothing happened, and since no
    -- cast came about, the mode never went off either.
    local saved = { get = GetCVar, set = SetCVar, set2 = SetOverrideBinding, clear = ClearOverrideBindings, combat = InCombatLockdown,
        bind = GetBindingKey, mark = ns.db.gatherMark, key = ns.db.gatherKey, cvars = ns.db.fishingCVars, bobber = ns.db.fishMarkBobber,
        map = player.map, x = player.x, y = player.y, guid = UnitGUID, secret = issecretvalue, nodes = ns.db.nodes[1412], debug = ns.Debug, modeOff = ns.QuestModeOff }
    local store = {}
    local binds = {} -- owner -> key -> command
    local fighting = false
    local marked = nil -- what UnitGUID("softinteract") answers
    local asked = 0
    -- the look for the mark is the only ticker of 0.2 s: its ticks are counted
    local realTicker, ticks = C_Timer.NewTicker, 0
    local SECRET = newproxy(true)
    local HERB = "GameObject-0-4444-0-55-1618-00001A2B3C"      -- Peacebloom
    local VEIN = "GameObject-0-4444-0-55-1731-00001A2B3D"      -- Copper Vein
    local CHEST = "GameObject-0-4444-0-55-2843-00001A2B3E"     -- Battered Chest
    local MAILBOX = "GameObject-0-4444-0-55-32349-00001A2B3F"  -- a mailbox
    local NPC = "Creature-0-4444-0-55-1618-00001A2B40"         -- an NPC with the Peacebloom's number
    local NEW = "GameObject-0-4444-0-55-987654-00001A2B41"     -- an object the spawn data does not know
    local function Gathers()
        for _, keys in pairs(binds) do if keys.F == "INTERACTTARGET" then return true end end
        return false
    end
    local function Owners()
        local n = 0
        for _, keys in pairs(binds) do if next(keys) then n = n + 1 end end
        return n
    end
    local function Cast() fire("UNIT_SPELLCAST_CHANNEL_START", "player", "t4fish", 7620) end
    local function Reel() fire("UNIT_SPELLCAST_CHANNEL_STOP", "player", "t4fish", 7620) advance(1) end
    -- the mark changes; the game does not tell (the look finds it)
    local function Mark(guid) marked = guid advance(0.5) end
    local ok, err = pcall(function()
        GetCVar = function(k) return store[k] or "0" end
        SetCVar = function(k, v) store[k] = tostring(v) return true end
        SetOverrideBinding = function(owner, _, key, cmd) binds[owner] = binds[owner] or {} binds[owner][key] = cmd end
        ClearOverrideBindings = function(owner) binds[owner] = nil end
        InCombatLockdown = function() return fighting end
        GetBindingKey = function(cmd) if cmd == ns.FishBinding then return "F" end return saved.bind(cmd) end
        UnitGUID = function(u)
            if u == "softinteract" then asked = asked + 1 return marked end
            return saved.guid(u)
        end
        C_Timer.NewTicker = function(s, fn)
            if s ~= 0.2 then return realTicker(s, fn) end
            return realTicker(s, function() ticks = ticks + 1 fn() end)
        end
        assert(GathercraftQuestieData.kinds.o1618 and GathercraftQuestieData.kinds.o1731 and GathercraftQuestieData.kinds.o2843 and not GathercraftQuestieData.kinds.o32349 and not GathercraftQuestieData.kinds.o987654,
            "test setup: herb, vein and chest are in the spawn data, the mailbox is not")
        ns.db.fishingCVars, ns.db.fishMarkBobber = nil, false
        player.map, player.x, player.y = 1412, 0.45, 0.72
        ns.SetQuestMode(false)
        if ns.run then ns.StopRun(true) end
        ns.db.gatherMark, ns.db.gatherKey = true, true
        ns.UpdateGatherHelp("test") advance(1)
        assert(not Gathers(), "test setup: the key gathers with nothing going on")

        -- (1) Sven's case: questing mode and option on, no node marked - the key is the Fish key
        ns.SetQuestMode(true) advance(1)
        assert(ns.QuestModeOn(), "test setup: the questing mode is off")
        assert(not Gathers() and Owners() == 0, "questing mode, nothing marked: the Fish key is overridden (it cannot fish)")
        assert(ticks >= 3, "questing mode with the option: nobody looks for the mark (" .. ticks .. " looks in a second)")
        assert(store.SoftTargetInteract == "3", "questing mode: the node in front of you is not marked any more")
        -- a node gets marked: the key gathers
        Mark(HERB)
        assert(Gathers(), "a herb is marked: the key does not gather")
        -- the mark goes: the Fish key again
        Mark(nil)
        assert(not Gathers() and Owners() == 0, "the mark is gone: the key still gathers")
        -- a vein, a chest
        Mark(VEIN)
        assert(Gathers(), "a vein is marked: the key does not gather")
        Mark(CHEST)
        assert(Gathers(), "a chest is marked: the key does not gather")
        -- not a gathering node: an NPC, a mailbox, something unknown - the key fishes
        Mark(NPC)
        assert(not Gathers(), "an NPC is marked: the key gathers")
        Mark(HERB) assert(Gathers(), "test setup")
        Mark(MAILBOX)
        assert(not Gathers(), "a mailbox is marked: the key gathers")
        Mark(NEW)
        assert(not Gathers(), "an object nobody knows is marked: the key gathers")
        -- ... until the recorder knows it: a node recorded in this zone
        ns.db.nodes[1412] = ns.db.nodes[1412] or {}
        local own = { id = "o987654", name = "Forever Bloom", type = "herb", x = 0.45, y = 0.72, count = 1, last = 1 }
        table.insert(ns.db.nodes[1412], own)
        advance(0.5)
        assert(Gathers(), "a node recorded in this zone is marked: the key does not gather")
        own.type = "fish" -- a fishing pool is no node to gather with the key
        advance(0.5)
        assert(not Gathers(), "a fishing pool is marked: the key gathers (it must cast)")
        table.remove(ns.db.nodes[1412])
        -- answers that are no mark at all: no error, the key fishes
        for _, odd in ipairs({ "", "GameObject", "GameObject-0-1-0-1-abc-1", "Player-4444-00ABCDEF", 42, true }) do
            Mark(HERB) assert(Gathers(), "test setup")
            local before = #errors
            Mark(odd)
            assert(#errors == before, "an odd answer (" .. tostring(odd) .. ") raised an error: " .. tostring(errors[#errors]))
            assert(not Gathers(), "an odd answer (" .. tostring(odd) .. "): the key gathers")
        end
        Mark(HERB) assert(Gathers(), "test setup")
        issecretvalue = function(v) return rawequal(v, SECRET) end
        Mark(SECRET)
        assert(not Gathers(), "a hidden answer: the key gathers")
        issecretvalue = saved.secret
        Mark(HERB) assert(Gathers(), "test setup")
        UnitGUID = function(u) if u == "softinteract" then error("no such unit") end return saved.guid(u) end
        local before = #errors
        advance(0.5)
        assert(#errors == before and not Gathers(), "a client that does not know the unit: an error, or the key gathers")
        UnitGUID = nil
        advance(0.5)
        assert(#errors == before and not Gathers(), "a client without UnitGUID: an error, or the key gathers")
        UnitGUID = function(u)
            if u == "softinteract" then asked = asked + 1 return marked end
            return saved.guid(u)
        end

        -- the answers as Sven saw them in the game (11.11.2026, 16001): a Gold
        -- Vein gathers, the NPC next to it does not; UnitExists is false for
        -- a game object there and must not be asked
        local realExists = UnitExists
        UnitExists = function(u) if u == "softinteract" then error("UnitExists(softinteract) was asked: it is false for game objects") end return realExists(u) end
        assert(GathercraftQuestieData.kinds.o1734, "test setup: the Gold Vein (1734) is in the spawn data")
        Mark(nil)
        marked = "GameObject-0-7094-0-16-1734-8A72C11CCB"
        local raised = #errors
        fire("PLAYER_SOFT_INTERACT_CHANGED", "Creature-0-7094-0-16-2251-9E0253AC79", "GameObject-0-7094-0-16-1734-8A72C11CCB")
        assert(Gathers(), "the Gold Vein as the game told it: the key does not gather")
        local kind, id = ns.GatherMarkedNode()
        assert(kind == "ore" and id == 1734, "the Gold Vein as the game told it: read as " .. tostring(kind) .. " " .. tostring(id))
        marked = nil
        fire("PLAYER_SOFT_INTERACT_CHANGED", "GameObject-0-7094-0-16-1734-8A72C11CCB", nil)
        assert(not Gathers(), "the mark gone as the game told it: the key still gathers")
        marked = "Creature-0-7094-0-16-2389-8DB079F6E9"
        fire("PLAYER_SOFT_INTERACT_CHANGED", nil, "Creature-0-7094-0-16-2389-8DB079F6E9")
        advance(0.5)
        assert(not Gathers(), "the NPC as the game told it: the key gathers")
        assert(#errors == raised, "UnitExists was asked about the mark: " .. tostring(errors[#errors]))
        UnitExists = realExists
        -- (2) the game tells the change itself: at once, without waiting for the look
        Mark(nil)
        marked = HERB
        fire("PLAYER_SOFT_INTERACT_CHANGED", nil, HERB)
        assert(Gathers(), "the game told the new mark: the key does not gather at once")
        marked = nil
        fire("PLAYER_SOFT_INTERACT_CHANGED", HERB, nil)
        assert(not Gathers(), "the game told the mark is gone: the key still gathers")
        -- whatever the event carries is not used: only what is marked now
        fire("PLAYER_SOFT_INTERACT_CHANGED", nil, HERB)
        assert(not Gathers(), "the event's own values were believed")

        -- (3) in a fight nothing changes; its end catches up
        fighting = true
        Mark(HERB)
        assert(not Gathers(), "the key was changed in combat (a node marked)")
        fighting = false
        fire("PLAYER_REGEN_ENABLED") advance(0.1)
        assert(Gathers(), "after the fight the key does not gather, a node is marked")
        fighting = true
        Mark(nil)
        assert(Gathers(), "the key was changed in combat (the mark gone)")
        fighting = false
        fire("PLAYER_REGEN_ENABLED") advance(0.1)
        assert(not Gathers(), "after the fight the key still gathers, nothing is marked")

        -- (4) casting with the key: the questing mode goes off (as before),
        -- the line is out - the key reels in; neither binding clears the other
        Mark(nil)
        Cast()
        assert(not ns.QuestModeOn(), "casting did not turn the questing mode off")
        assert(Gathers(), "the line is out: the key does not reel in")
        Reel()
        assert(not Gathers() and Owners() == 0, "the line is in: the key is still overridden")
        -- a node marked while the line is out (the mode on again): reeling
        -- in leaves the gathering key, and the mark going leaves the reel key
        ns.SetQuestMode(true) advance(1)
        Mark(HERB)
        assert(Gathers() and Owners() == 1, "test setup: a node marked")
        ns.QuestModeOff = nil -- (keep the mode on through the cast, to see both bindings at once)
        Cast()
        assert(Owners() == 2 and Gathers(), "line out at a marked node: not both bindings")
        Mark(nil)
        assert(Gathers() and Owners() == 1, "the mark went while the line is out: the reel key went too")
        Mark(HERB)
        Reel()
        assert(Gathers() and Owners() == 1, "the line is in at a marked node: the gathering key went too")
        Mark(nil)
        assert(not Gathers() and Owners() == 0, "after all that a binding is left")
        ns.QuestModeOff = saved.modeOff

        -- (5) a farm run: as before - the key gathers for as long as the run goes
        ns.SetQuestMode(false) advance(1)
        local looks = asked
        slash("run herb") advance(2)
        assert(ns.run and Gathers(), "a farm run, nothing marked: the key does not gather")
        Mark(NPC)
        assert(Gathers(), "a farm run, an NPC marked: the key does not gather")
        Mark(nil)
        local before = ticks
        advance(3)
        assert(asked - looks <= 3, "a farm run: the mark is looked for all the time (" .. (asked - looks) .. " times) though it decides nothing")
        assert(ticks == before, "a farm run: the look for the mark goes on (" .. (ticks - before) .. " looks in 3 s)")
        slash("stop") advance(1)
        assert(not Gathers() and Owners() == 0, "after the run the key still gathers")

        -- (6) the option off: never overridden, and nobody looks for the mark
        ns.db.gatherKey = nil
        ns.UpdateGatherHelp("test")
        ns.SetQuestMode(true) advance(1)
        looks = asked
        local before = ticks
        Mark(HERB)
        advance(3)
        assert(not Gathers() and Owners() == 0, "the option is off: the key is overridden")
        assert(asked == looks and ticks == before, "the option is off: the mark is still looked for")
        fire("PLAYER_SOFT_INTERACT_CHANGED", nil, HERB)
        assert(not Gathers() and asked == looks, "the option is off: the event is acted on")
        -- on again with a node marked: at once
        ns.db.gatherKey = true
        ns.UpdateGatherHelp("option")
        assert(Gathers(), "the option on at a marked node: the key does not gather")
        -- the questing mode off: the Fish key again, and the looking stops
        ns.SetQuestMode(false) advance(1)
        looks = asked
        before = ticks
        advance(3)
        assert(not Gathers() and Owners() == 0, "questing mode off: the key still gathers")
        assert(asked == looks and ticks == before, "questing mode off: the look for the mark goes on (" .. (ticks - before) .. " looks in 3 s)")
        -- the mode on in a fight at a marked node: after the fight
        fighting = true
        ns.SetQuestMode(true) advance(1)
        assert(not Gathers(), "the key was changed in combat (the mode began)")
        fighting = false
        fire("PLAYER_REGEN_ENABLED") advance(0.1)
        assert(Gathers(), "after the fight, the mode on at a marked node: the key does not gather")
        ns.SetQuestMode(false) advance(1)

        -- (7) /gcr debug tells every change
        local lines = {}
        ns.Debug = function(text) if tostring(text):find("^GATHER key") then lines[#lines + 1] = text end end
        Mark(nil)
        ns.SetQuestMode(true) advance(1)
        Mark(VEIN)
        Mark(nil)
        ns.Debug = saved.debug
        assert(#lines == 2 and lines[1]:find("gathers", 1, true) and lines[1]:find("1731", 1, true) and lines[2]:find("Fish key", 1, true),
            "the debug lines: " .. table.concat(lines, " | "))
        ns.SetQuestMode(false) advance(1)
    end)
    ns.Debug, ns.QuestModeOff = saved.debug, saved.modeOff
    C_Timer.NewTicker = realTicker
    GetBindingKey = saved.bind
    GetCVar, SetCVar, SetOverrideBinding, ClearOverrideBindings, InCombatLockdown = saved.get, saved.set, saved.set2, saved.clear, saved.combat
    UnitGUID, issecretvalue = saved.guid, saved.secret
    if ns.run then ns.StopRun(true) end
    ns.SetQuestMode(false)
    ns.db.gatherMark, ns.db.gatherKey, ns.db.fishingCVars, ns.db.fishMarkBobber = saved.mark, saved.key, saved.cvars, saved.bobber
    ns.db.nodes[1412] = saved.nodes
    if ns.UpdateGatherHelp then ns.UpdateGatherHelp("test end") end
    if ns.StopFishing then ns.StopFishing() end
    player.map, player.x, player.y = saved.map, saved.x, saved.y
    if not ok then error(err, 0) end
end)
step("Craft log: a success that cannot be told apart protects the next reading, and invents nothing (v0.1.21 R1)", function()
    -- Codex, 11.11.2026, round 1 on 0.1.21 (M1, a guess about the client, shown
    -- in the mock): a success of the player that comes without a cast ID, or
    -- with cast ID and spell both hidden, was passed over without a trace. If
    -- it was a craft, its point arrives a moment later - inside the reading of
    -- the craft that starts next: +2, "a craft gave more than one point".
    -- Whether the client ever sends such a success is not known; the log no
    -- longer depends on it.
    local data = GathercraftRecipeData
    local spell = data.spells.Leatherworking["Light Leather"]
    local saved = { rank = ns.ProfessionRank, have = ns.CraftData.Have, colors = data.colors[spell],
        log = ns.db.craftLog, off = ns.db.craftLogOff, multi = ns.db.craftMulti, secret = issecretvalue }
    local HIDDEN = newproxy(true)
    local rank, maxRank = 10, 75
    ns.ProfessionRank = function(p) if p == "Leatherworking" then return rank, maxRank end end
    ns.CraftData.Have = function() return 0 end
    data.colors[spell] = "25:45" -- orange below 25
    ns.db.craftLog, ns.db.craftLogOff, ns.db.craftMulti = {}, nil, nil
    local n = 0
    local function Guid() n = n + 1 return "Cast-r1-" .. n end
    local function Start(sp) local g = Guid() fire("UNIT_SPELLCAST_START", "player", g, sp or spell) return g end
    -- the point of a craft arrives LAG seconds after its success
    local LAG = 0.5
    local function Point() C_Timer.After(LAG, function() rank = rank + 1 end) end
    local function Ok(g) fire("UNIT_SPELLCAST_SUCCEEDED", "player", g, spell) Point() end
    -- a success as the client might tell it: with the given cast ID and spell
    -- (HIDDEN: a value the client hides)
    local function Success(guid, sp, craft)
        issecretvalue = function(v) return rawequal(v, HIDDEN) end
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", guid, sp)
        issecretvalue = saved.secret
        if craft then Point() end
    end
    local function Reset() advance(3) ns.CraftLogBreak() ns.db.craftLog, ns.db.craftMulti = {}, nil rank = 10 advance(3) end
    local function Blocks()
        local list = {}
        for _, e in ipairs(ns.db.craftLog) do if e.kind == "series" then list[#list + 1] = e end end
        return list
    end
    -- after the success `first`, one fully seen craft: START at once (or
    -- after `wait` s), 3 s, success, its point
    local function Next(wait)
        if wait then advance(wait) end
        local g = Start() advance(3) Ok(g) advance(3)
    end
    local ok, err = pcall(function()
        advance(3)
        -- (A) Codex: no cast ID, the recipe's spell readable - a craft for sure
        Reset()
        Success(nil, spell, true)
        Next()
        assert(rank == 12, "test setup: two crafts, two points")
        assert(not ns.db.craftMulti, "a success without a cast ID, then a craft: the note \"a craft gave more than one point\" is set")
        assert(#ns.db.craftLog == 1, "a success without a cast ID: " .. #ns.db.craftLog .. " entries, want the second craft alone (nothing made up for the first)")
        local e = ns.db.craftLog[1]
        assert(e.overlap and e.blind == "settle" and e.result == "ok", "the craft after a success without a cast ID is not overlapping")
        local byColour, _, others = ns.CraftLogSummary()
        assert(not next(byColour) and others.multi == 0 and others.overlap == 1, "the craft after a success without a cast ID is in a rate")
        assert(ns.CraftLogCrafts() == 1, "the header counts " .. ns.CraftLogCrafts() .. " crafts: the success without a cast ID was counted")
        -- (B) Codex: cast ID and spell both hidden - it may have been a craft
        Reset()
        Success(HIDDEN, HIDDEN, true)
        Next()
        assert(not ns.db.craftMulti, "a success with cast ID and spell hidden, then a craft: the note is set")
        assert(#ns.db.craftLog == 1 and ns.db.craftLog[1].overlap and ns.db.craftLog[1].blind == "settle", "the craft after a wholly hidden success is not overlapping")
        assert(ns.CraftLogCrafts() == 1, "the wholly hidden success was counted as a craft")
        -- the same, the other ways a success can be beyond telling
        Reset()
        Success(nil, HIDDEN, true) -- no cast ID, the spell hidden
        Next()
        assert(not ns.db.craftMulti and #ns.db.craftLog == 1 and ns.db.craftLog[1].overlap, "no cast ID and a hidden spell: the next craft is not overlapping")
        Reset()
        Success(Guid(), HIDDEN, true) -- a cast ID never seen before, the spell hidden
        Next()
        assert(not ns.db.craftMulti and #ns.db.craftLog == 1 and ns.db.craftLog[1].overlap, "a new cast ID and a hidden spell: the next craft is not overlapping")
        -- a cast whose start came with a hidden spell: over for the log; its
        -- success protects the next reading
        Reset()
        local g = Guid()
        issecretvalue = function(v) return rawequal(v, HIDDEN) end
        local before = #errors
        fire("UNIT_SPELLCAST_START", "player", g, HIDDEN)
        issecretvalue = saved.secret
        assert(#errors == before, "a start with a hidden spell raised an error: " .. tostring(errors[#errors]))
        advance(3)
        Success(g, HIDDEN, true)
        Next()
        assert(not ns.db.craftMulti and #ns.db.craftLog == 1 and ns.db.craftLog[1].overlap, "a cast begun with a hidden spell: the next craft is not overlapping")
        -- the control (as before, T8): the cast ID hidden, the recipe's spell
        -- readable - a craft, logged as unreadable, and the next one blind
        Reset()
        Success(HIDDEN, spell, true)
        Next()
        assert(not ns.db.craftMulti and #ns.db.craftLog == 2, "the control, cast ID hidden and recipe readable: " .. #ns.db.craftLog .. " entries")
        assert(ns.db.craftLog[1].secret and ns.db.craftLog[1].recipe == "Light Leather" and ns.db.craftLog[2].overlap, "the control: not the unreadable craft and the overlapping one")
        byColour, _, others = ns.CraftLogSummary()
        assert(others.secret == 1 and others.overlap == 1 and not next(byColour), "the control's counts changed")

        -- 1.5 s later nothing is left to settle: the next craft counts
        for _, form in ipairs({ { nil, spell }, { HIDDEN, HIDDEN }, { nil, HIDDEN } }) do
            Reset()
            Success(form[1], form[2], true)
            Next(1.6)
            assert(#ns.db.craftLog == 1 and not ns.db.craftLog[1].overlap and not ns.db.craftLog[1].blind and ns.db.craftLog[1].gain == 1,
                "a craft 1.6 s after a success beyond telling does not count")
        end
        -- one second later it is still inside
        Reset()
        Success(HIDDEN, HIDDEN, true)
        Next(1)
        assert(ns.db.craftLog[1].overlap and not ns.db.craftMulti, "a craft 1 s after a wholly hidden success counts")

        -- what is no craft for sure makes nothing blind: a readable spell that
        -- is no recipe - with a cast ID, without one, with the cast ID hidden
        for _, guid in ipairs({ "Cast-r1-hearth", false, HIDDEN }) do
            Reset()
            Success(guid or nil, 8690, false)
            Next()
            assert(#ns.db.craftLog == 1 and not ns.db.craftLog[1].overlap and not ns.db.craftLog[1].blind and ns.db.craftLog[1].gain == 1,
                "a spell that is no recipe (cast ID " .. (guid == HIDDEN and "hidden" or tostring(guid)) .. ") made the next craft blind")
        end
        -- a failure or a start beyond telling makes nothing blind either
        Reset()
        issecretvalue = function(v) return rawequal(v, HIDDEN) end
        fire("UNIT_SPELLCAST_FAILED", "player", HIDDEN, HIDDEN)
        fire("UNIT_SPELLCAST_INTERRUPTED", "player", nil, HIDDEN)
        fire("UNIT_SPELLCAST_START", "player", HIDDEN, HIDDEN)
        fire("UNIT_SPELLCAST_START", "player", nil, spell)
        issecretvalue = saved.secret
        Next()
        assert(#ns.db.craftLog == 1 and not ns.db.craftLog[1].overlap and ns.db.craftLog[1].gain == 1, "a failure or a start beyond telling made the next craft blind")

        -- in the middle of Create All: the series is not a block (the hidden
        -- success may have been a craft whose point lands in it)
        -- (1 s into the second cast the first craft is still being read: it
        -- shares its reading; 2 s into it the next start follows within 1.5 s)
        for _, into in ipairs({ 1, 2 }) do
            Reset()
            g = Start() advance(3) Ok(g)
            g = Start() advance(into)
            Success(HIDDEN, HIDDEN, false)
            advance(3 - into) Ok(g)
            g = Start() advance(3) Ok(g)
            g = Start() advance(1) fire("UNIT_SPELLCAST_INTERRUPTED", "player", g, spell)
            advance(3)
            assert(#Blocks() == 0 and not ns.db.craftMulti, "a wholly hidden success " .. into .. " s into a cast of a series: a block, or the note")
            for _, x in ipairs(ns.db.craftLog) do
                assert(x.result ~= "ok" or x.overlap, "a wholly hidden success " .. into .. " s into a cast: a craft of the series counts alone")
            end
        end
        -- a single craft still being read when such a success comes shares its reading
        Reset()
        g = Start() advance(3) Ok(g)
        advance(0.5)
        Success(nil, HIDDEN, true)
        advance(3)
        assert(rank == 12 and not ns.db.craftMulti, "a success beyond telling inside a reading: the note is set")
        assert(#ns.db.craftLog == 1 and ns.db.craftLog[1].overlap, "a craft being read when a success beyond telling came is not overlapping")
        Reset()
        g = Start() advance(3) Ok(g)
        Success(HIDDEN, HIDDEN, true)   -- together with the first craft's success
        g = Start() advance(3) Ok(g)    -- the next cast of Create All starts at once
        g = Start() advance(3) Ok(g)
        g = Start() advance(1) fire("UNIT_SPELLCAST_INTERRUPTED", "player", g, spell)
        advance(3)
        assert(#Blocks() == 0 and not ns.db.craftMulti, "a hidden success right before the next start of a series: a block (" .. #Blocks() .. "), or the note")
        for _, x in ipairs(ns.db.craftLog) do
            assert(x.result ~= "ok" or x.overlap, "a craft of the series after the hidden success counts alone")
        end

        -- recording off: nothing is recorded, and after switching on the next
        -- reading is protected as well
        Reset()
        ns.db.craftLogOff = true
        ns.CraftLogBreak()
        Success(nil, HIDDEN, true)
        ns.db.craftLogOff = nil
        ns.CraftLogBreak()
        Next()
        assert(not ns.db.craftMulti and #ns.db.craftLog == 1 and ns.db.craftLog[1].overlap, "a success beyond telling while off: the next craft is not overlapping")
        -- a real single craft with two points, its start seen, nothing
        -- unsettled: the note as before
        Reset()
        g = Start() advance(3)
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", g, spell)
        C_Timer.After(LAG, function() rank = rank + 2 end)
        advance(3)
        assert(ns.db.craftMulti and ns.db.craftMulti.Leatherworking, "a clear single craft with two points: no note")
    end)
    issecretvalue = saved.secret
    advance(3)
    ns.ProfessionRank, ns.CraftData.Have, data.colors[spell] = saved.rank, saved.have, saved.colors
    ns.db.craftLogOff = saved.off
    if ns.CraftLogBreak then ns.CraftLogBreak() end
    advance(3)
    ns.db.craftLog, ns.db.craftMulti = saved.log, saved.multi
    if not ok then error(err, 0) end
end)
step("Gathering help: which objects count as a node for the Fish key - spawn data, or a known entry of the zone, shared ones too (v0.1.21 R2)", function()
    -- Codex, 11.11.2026 (N1): the report said "nodes you recorded yourself".
    -- The code takes every entry of the zone you are in, also one that came
    -- in by sharing and was never harvested by you. That stays; this step
    -- says so (no behaviour changed with it).
    local here, other = player.map, 1413
    local keep = { nodes = ns.db.nodes[here], others = ns.db.nodes[other] }
    local ok, err = pcall(function()
        assert(here and here ~= other, "test setup: the zone you are in")
        assert(not GathercraftQuestieData.kinds.o987654 and not GathercraftQuestieData.kinds.o987655, "test setup: object IDs the spawn data does not know")
        ns.db.nodes[here], ns.db.nodes[other] = {}, {}
        -- the spawn data: whatever the zone holds
        assert(ns.GatherObjectType(1618) == "herb" and ns.GatherObjectType(1731) == "ore" and ns.GatherObjectType(2843) == "chest", "herb, vein and chest of the spawn data")
        assert(ns.GatherObjectType(987654) == nil, "an object nobody knows counts as a node")
        -- an entry that came in by sharing, never harvested here (Codex' probe)
        table.insert(ns.db.nodes[here], { id = "o987654", type = "herb", source = "sync", hits = 0, x = 0.5, y = 0.5 })
        assert(ns.GatherObjectType(987654) == "herb", "an entry of this zone that came in by sharing does not count")
        -- an entry of your own
        table.insert(ns.db.nodes[here], { id = "o987655", type = "ore", count = 3, last = 1, x = 0.4, y = 0.5 })
        assert(ns.GatherObjectType(987655) == "ore", "an entry of this zone you found yourself does not count")
        -- another zone's entry does not
        ns.db.nodes[here] = {}
        table.insert(ns.db.nodes[other], { id = "o987654", type = "herb", source = "sync", hits = 0, x = 0.5, y = 0.5 })
        assert(ns.GatherObjectType(987654) == nil, "an entry of another zone counts here")
        -- a fishing pool, a rare, anything that is no herb, vein or chest: no
        ns.db.nodes[here] = { { id = "o987654", type = "fish", x = 0.5, y = 0.5 }, { id = "o987655", type = "rare", x = 0.5, y = 0.5 } }
        assert(ns.GatherObjectType(987654) == nil and ns.GatherObjectType(987655) == nil, "a fishing pool or something else counts as a node to gather")
        -- not a number: nil, no error
        assert(ns.GatherObjectType(nil) == nil and ns.GatherObjectType("1618") == nil and ns.GatherObjectType({}) == nil, "an answer for something that is no object ID")
    end)
    ns.db.nodes[here], ns.db.nodes[other] = keep.nodes, keep.others
    if not ok then error(err, 0) end
end)
step("Craft log: a success that cannot be told apart also marks the craft that is being cast (v0.1.21 V1)", function()
    -- Codex, 12.11.2026, round 2 on 0.1.21 (R2-V1, a guess about the client,
    -- shown in the mock): a craft reads its "before" at its START, but is
    -- "being read" only from its success on. A success beyond telling in
    -- between protected later starts and running readings - not the craft
    -- that was already being cast: +2 for it, the note.
    local data = GathercraftRecipeData
    local spell = data.spells.Leatherworking["Light Leather"]
    local saved = { rank = ns.ProfessionRank, have = ns.CraftData.Have, colors = data.colors[spell],
        log = ns.db.craftLog, off = ns.db.craftLogOff, multi = ns.db.craftMulti, secret = issecretvalue }
    local HIDDEN = newproxy(true)
    local rank = 10
    ns.ProfessionRank = function(p) if p == "Leatherworking" then return rank, 75 end end
    ns.CraftData.Have = function() return 0 end
    data.colors[spell] = "25:45"
    ns.db.craftLog, ns.db.craftLogOff, ns.db.craftMulti = {}, nil, nil
    local n = 0
    local function Start() n = n + 1 local g = "Cast-v1-" .. n fire("UNIT_SPELLCAST_START", "player", g, spell) return g end
    local function Point(delta) C_Timer.After(0.5, function() rank = rank + (delta or 1) end) end
    local function Ok(g) fire("UNIT_SPELLCAST_SUCCEEDED", "player", g, spell) Point() end
    local function Unknown(guid, sp, delta)
        issecretvalue = function(v) return rawequal(v, HIDDEN) end
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", guid, sp)
        issecretvalue = saved.secret
        if delta then Point(delta) end
    end
    local function Reset() advance(3) ns.CraftLogBreak() ns.db.craftLog, ns.db.craftMulti = {}, nil rank = 10 advance(3) end
    local function Blocks()
        local c = 0
        for _, e in ipairs(ns.db.craftLog) do if e.kind == "series" then c = c + 1 end end
        return c
    end
    local ok, err = pcall(function()
        advance(3)
        -- Codex' probe (extra.lua): START A, 1 s later a wholly hidden success
        -- with a point, A succeeds after 3 s. No further start.
        for _, form in ipairs({ { HIDDEN, HIDDEN }, { false, HIDDEN }, { false, spell }, { "Cast-v1-new", HIDDEN }, { HIDDEN, spell } }) do
            Reset()
            local g = Start()
            advance(1)
            Unknown(form[1] or nil, form[2], 1)
            advance(2)
            Ok(g)
            advance(3)
            local what = (form[1] == HIDDEN and "hidden" or tostring(form[1])) .. " / " .. (form[2] == HIDDEN and "hidden" or "recipe")
            assert(rank == 12, "test setup: two points")
            assert(not ns.db.craftMulti, "a success beyond telling (" .. what .. ") during a cast: the note \"a craft gave more than one point\" is set")
            local mine
            for _, e in ipairs(ns.db.craftLog) do if not e.secret or e.before then mine = e end end
            assert(mine and mine.overlap and mine.blind == "during", "the craft that was being cast (" .. what .. ") is not overlapping: blind " .. tostring(mine and mine.blind))
            local byColour, _, others = ns.CraftLogSummary()
            assert(not next(byColour) and others.multi == 0, "the craft that was being cast (" .. what .. ") is in a rate")
        end
        -- the same in a series: the cast that was running, and with it the series
        -- (the first craft gives no point: two crafts and two points would
        -- pass for a block of 2 / 2 - one of the points is the other craft's)
        Reset()
        local g = Start() advance(3) fire("UNIT_SPELLCAST_SUCCEEDED", "player", g, spell)
        g = Start() advance(2)          -- (the first is read by now: nothing is "being read")
        Unknown(HIDDEN, HIDDEN, 1)
        advance(1) Ok(g) advance(3)
        assert(rank == 12, "test setup: the first craft none, the second and the unknown one a point each")
        assert(Blocks() == 0 and not ns.db.craftMulti, "a success beyond telling during the second cast of a series: a block of 2 with 2 points, or the note")
        local byColour = ns.CraftLogSummary()
        assert(not next(byColour), "a success beyond telling during the second cast of a series: its crafts are in a rate")
        -- what must stay: a spell that is no recipe, readable, during a cast - nothing
        Reset()
        g = Start() advance(1)
        Unknown(HIDDEN, 8690) Unknown(nil, 8690) Unknown("Cast-v1-hearth", 8690)
        advance(2) Ok(g) advance(3)
        assert(#ns.db.craftLog == 1 and not ns.db.craftLog[1].overlap and not ns.db.craftLog[1].blind and ns.db.craftLog[1].gain == 1, "a spell that is no recipe during a cast made the craft overlapping")
        -- a failure or a start beyond telling during a cast - nothing
        Reset()
        g = Start() advance(1)
        issecretvalue = function(v) return rawequal(v, HIDDEN) end
        fire("UNIT_SPELLCAST_FAILED", "player", HIDDEN, HIDDEN)
        fire("UNIT_SPELLCAST_START", "player", HIDDEN, HIDDEN)
        issecretvalue = saved.secret
        advance(2) Ok(g) advance(3)
        assert(#ns.db.craftLog == 1 and not ns.db.craftLog[1].overlap and ns.db.craftLog[1].gain == 1, "a failure beyond telling during a cast made the craft overlapping")
        -- a finished block stays as it is (Codex' own control), a later series counts
        Reset()
        g = Start() advance(3) Ok(g) g = Start() advance(3) Ok(g) advance(1.6)
        assert(Blocks() == 1, "test setup: a block")
        Unknown(HIDDEN, HIDDEN) advance(2)
        assert(Blocks() == 1 and not ns.db.craftMulti, "a finished block changed")
        g = Start() advance(3) Ok(g) g = Start() advance(3) Ok(g) advance(3)
        assert(Blocks() == 2, "a later clean series does not count")
    end)
    issecretvalue = saved.secret
    advance(3)
    ns.ProfessionRank, ns.CraftData.Have, data.colors[spell] = saved.rank, saved.have, saved.colors
    ns.db.craftLogOff = saved.off
    if ns.CraftLogBreak then ns.CraftLogBreak() end
    advance(3)
    ns.db.craftLog, ns.db.craftMulti = saved.log, saved.multi
    if not ok then error(err, 0) end
end)
step("Sharing: the chat line about spots of other players is off until you turn it on (v0.1.21 T9)", function()
    -- Sven, 12.11.2026 (a player asked how to stop the "chat spam"): off by
    -- default, also for everyone who never touched the option. The choice
    -- "on" is kept as sync.announceOn = true; the old sync.announceOff
    -- (true = turned off, nil = never touched) means "off" either way.
    local db = ns.db.sync
    local saved = { on = db.announceOn, off = db.announceOff, enabled = db.enabled }
    slash("sync on")
    local zone = ns.GetZoneName(1412)
    local function IsLine(l) -- the line in the language of this run, for 1 to 9 spots of this zone
        for k = 1, 9 do
            if l:find((ns.L["%d spots shared by other players added (%s)."]):format(k, zone), 1, true) then return true end
        end
    end
    local function Lines()
        local n = 0
        for _, l in ipairs(log) do if IsLine(l) then n = n + 1 end end
        return n
    end
    local spot = 0
    local function Arrive() -- a new spot from the guild, another place each time
        spot = spot + 1
        local before = select(2, ns.SyncSummary())
        fire("CHAT_MSG_ADDON", "Gathercraft", ("N:1412;o1620,h,%d,%d,785"):format(7100 + spot * 37, 1300 + spot * 41), "GUILD", "Guildie Nine")
        assert(select(2, ns.SyncSummary()) > before, "test setup: the spot was not taken")
    end
    local win = _G.GathercraftOptions
    local wasOpen = win:IsShown()
    local ok, err = pcall(function()
        if not wasOpen then ns.ToggleOptions() end
        ns.ShowOptionsSection("sync")
        local label
        for _, f in ipairs(allFrames) do
            if f.__kind == "FontString" and f.__text == ns.L["Tell me in chat when spots of other players arrive"] then label = f end
        end
        local box = label and ((label.__pts.TOPLEFT and label.__pts.TOPLEFT[1]) or (label.__pts.LEFT and label.__pts.LEFT[1]))
        assert(box and box.__kind == "CheckButton" and box.get and box.__scripts.OnClick, "test setup: the option's switch")
        advance(400) -- whatever an earlier step left: said and over
        -- 1. a new installation: nothing stored - no line, the box is empty
        db.announceOn, db.announceOff = nil, nil
        local n0 = Lines()
        assert(box.get() == false, "new installation: the box is ticked")
        Arrive() advance(400)
        assert(Lines() == n0, "new installation: the line came without being asked for")
        -- 2. 0.1.20 and before, turned off by hand: stays off
        db.announceOn, db.announceOff = nil, true
        assert(box.get() == false, "turned off in 0.1.20: the box is ticked")
        Arrive() advance(400)
        assert(Lines() == n0, "turned off in 0.1.20: the line came")
        assert(db.announceOff == true, "the old mark was changed without a choice")
        -- 3. tick the box: the line comes, and what arrived while it was off is not in it
        box:SetChecked(true) box.__scripts.OnClick(box)
        assert(db.announceOn == true and db.announceOff == nil, "ticked: announceOn " .. tostring(db.announceOn) .. ", announceOff " .. tostring(db.announceOff))
        assert(box.get() == true, "ticked: the box does not show it")
        advance(30)
        assert(Lines() == n0, "ticking the box alone said something")
        Arrive()
        advance(19)
        assert(Lines() == n0, "the line came before its 20 s")
        advance(2)
        assert(Lines() == n0 + 1, "ticked: no line after 20 s")
        local said
        for _, l in ipairs(log) do if IsLine(l) then said = l end end
        assert(said:find((ns.L["%d spots shared by other players added (%s)."]):format(1, zone), 1, true), "the line counts what came while it was off: " .. said)
        -- the pace is as before: at most one line every 180 s
        Arrive()
        advance(170)
        assert(Lines() == n0 + 1, "a second line within 180 s")
        advance(15)
        assert(Lines() == n0 + 2, "no second line after 180 s")
        -- 4. what is saved is the choice itself (SavedVariables: GathercraftDB)
        assert(GathercraftDB == ns.db and GathercraftDB.sync.announceOn == true, "the choice is not in the saved table")
        fire("PLAYER_LOGIN") advance(5) -- the login of the next session reads the same table
        assert(ns.db.sync.announceOn == true and box.get() == true, "the choice is gone after the next login")
        -- 5. untick: quiet again, nothing stored
        box:SetChecked(false) box.__scripts.OnClick(box)
        assert(db.announceOn == nil and db.announceOff == nil, "unticked: announceOn " .. tostring(db.announceOn) .. ", announceOff " .. tostring(db.announceOff))
        advance(400)
        local n1 = Lines()
        Arrive() advance(400)
        assert(Lines() == n1, "unticked: the line came")
        -- 6. anything but true is "off" (a broken or foreign value)
        db.announceOn = false
        Arrive() advance(400)
        assert(Lines() == n1 and box.get() == false, "announceOn = false counts as on")
    end)
    db.announceOn, db.announceOff, db.enabled = saved.on, saved.off, saved.enabled
    if not wasOpen then ns.ToggleOptions() end
    advance(400)
    if not ok then error(err, 0) end
end)
-- (end of the v0.1.21 steps)
-- ---------------------------------------------------------------- v0.1.22, part S: less sync load
-- Helpers for the steps about answers to a zone question. Each case takes a
-- zone of its own (an answered zone is not answered again for five minutes).
local function S22Zone(mapID, count)
    local list = {}
    for i = 1, count do
        list[i] = { id = "o98" .. (1000 + i), name = "X", type = "herb", x = (i % 20) / 20 + 0.01, y = math.floor(i / 20) / 21 + 0.01, count = 1 + i % 7, last = 1, item = 2447 }
    end
    ns.db.nodes[mapID] = list
    ns.NotifyNodesChanged()
end
local function S22Msg(text, who) fire("CHAT_MSG_ADDON", "Gathercraft", text, "CHANNEL", who, nil, nil, nil, "GathercraftSync") end
-- our own messages about the zone since `from`: how many, how many nodes, the first one
local function S22Sent(mapID, from)
    local messages, nodes, first = 0, 0, nil
    for i = from + 1, #sentMessages do
        if sentMessages[i]:find("^N:" .. mapID .. ";") then
            local _, k = sentMessages[i]:gsub(";", ";")
            messages, nodes, first = messages + 1, nodes + k, first or sentMessages[i]
        end
    end
    return messages, nodes, first
end
-- another player's answer packet for the zone, with `count` nodes
local function S22Other(mapID, who, count)
    local parts = {}
    for k = 1, count do parts[k] = ("o97%d,h,%d,%d,2447"):format(2000 + k, 1000 + k * 37, 2000 + k * 41) end
    S22Msg("N:" .. mapID .. ";" .. table.concat(parts, ";"), who)
end

step("Sharing: a zone question is answered only when the answer adds clearly more (v0.1.22 S1)", function()
    -- Sven's debug log, 12.11.2026: "answered zone 1420 with 150 nodes (they
    -- knew 151)". What counts is what is really sent (at most 150 a minute are
    -- taken from one player) against what the asker knows: at least a fifth
    -- more, and at least 20 more (for an asker who knows fewer than 20: at
    -- least as many more as he knows - somebody who knows nothing gets any).
    local saved = ns.db.sync.enabled
    slash("sync on")
    advance(700) -- (nothing of an earlier step is still on its way)
    local cases = {
        -- { own nodes, the asker's, nodes expected in the answer }
        { 100, 100, 0 },   -- as many
        { 110, 100, 0 },   -- a few more: not worth 14 messages
        { 119, 100, 0 },
        { 120, 100, 120 }, -- a fifth more
        { 400, 151, 0 },   -- 150 would be sent: fewer than he knows
        { 400, 125, 150 }, -- 150 sent, a fifth more than 125
        { 400, 126, 0 },
        { 5, 0, 5 },       -- he knows nothing: everything helps
        { 15, 10, 0 },
        { 20, 10, 20 },    -- 10 more than his 10
        { 39, 20, 0 },
        { 40, 20, 40 },    -- 20 more
    }
    local ok, err = pcall(function()
        for i, c in ipairs(cases) do
            local mapID = 1500 + i
            S22Zone(mapID, c[1])
            local from = #sentMessages
            S22Msg(("Q:%d:%d"):format(mapID, c[2]), "Asker" .. i .. "-Realm")
            advance(60)
            local _, nodes = S22Sent(mapID, from)
            assert(nodes == c[3], ("we know %d, the asker %d: %d nodes sent, want %d"):format(c[1], c[2], nodes, c[3]))
        end
    end)
    for i = 1, #cases do ns.db.nodes[1500 + i] = nil end
    ns.NotifyNodesChanged()
    if not saved then slash("sync off") end
    if not ok then error(err, 0) end
end)

step("Sharing: an answer stops when three others answered first, also in the middle (v0.1.22 S2)", function()
    -- Sven's debug logs, 11. and 12.11.2026: 6-7 players answered one question.
    -- The old lock only counted answers that ARRIVED before the own wait was
    -- over; an answer goes out in packets 1.2 s apart, so several started
    -- before any was heard. Now every packet asks again. Who was first is told
    -- by the channel's order, which is the same for everyone: the others'
    -- answers heard before the own first packet came back.
    local saved = ns.db.sync.enabled
    slash("sync on")
    -- (a test before this one may have told the addon about the login a second time, and
    -- this one does it for sure: there is still one ticker that sends, a packet every 1.2 s)
    fire("PLAYER_LOGIN")
    advance(700)
    local me = UnitName("player")
    local zones = {}
    local function Start(mapID)
        zones[#zones + 1] = mapID
        S22Zone(mapID, 100)
        local from = #sentMessages
        S22Msg(("Q:%d:0"):format(mapID), "Asker-Realm")
        return from
    end
    -- until our first packet is out (at most 20 s)
    local function First(mapID, from)
        for _ = 1, 100 do
            local messages, _, first = S22Sent(mapID, from)
            if messages > 0 then return first end
            advance(0.2)
        end
        error("no answer started for zone " .. mapID, 0)
    end
    local ok, err = pcall(function()
        -- three answers before ours started: we stay quiet (as before)
        local from = Start(1521)
        for k = 1, 3 do S22Other(1521, "Early" .. k .. "-Realm", 8) end
        advance(60)
        assert(S22Sent(1521, from) == 0, "three others answered during the wait, and we answered too")

        -- the lock looks at answers, not at somebody's harvest: one node in a message is no answer
        from = Start(1522)
        for k = 1, 3 do S22Other(1522, "Gatherer" .. k .. "-Realm", 1) end
        advance(60)
        local _, nodes = S22Sent(1522, from)
        assert(nodes == 100, "three harvests in the zone, and the answer had " .. nodes .. " nodes, want 100")

        -- three others were ahead of us in the channel (heard before our first packet came back)
        -- and go on with their second packet: we stop
        from = Start(1523)
        local first = First(1523, from)
        for k = 1, 3 do S22Other(1523, "Ahead" .. k .. "-Realm", 8) end
        S22Msg(first, me)
        advance(1.5)
        for k = 1, 3 do S22Other(1523, "Ahead" .. k .. "-Realm", 8) end
        advance(60)
        local messages = S22Sent(1523, from)
        assert(messages == 1, "three others were ahead, and we sent " .. messages .. " packets, want 1")
        -- ... and the question is not answered again right away
        S22Msg("Q:1523:0", "Asker Two-Realm")
        advance(60)
        assert(S22Sent(1523, from) == 1, "a stopped answer was started again within the five minutes")

        -- only two were ahead: we are the third and go on to the end
        from = Start(1524)
        first = First(1524, from)
        for k = 1, 2 do S22Other(1524, "Ahead" .. k .. "-Realm", 8) end
        S22Msg(first, me)
        for k = 1, 5 do S22Other(1524, "Behind" .. k .. "-Realm", 8) end -- (they came after us: they stop, not we)
        advance(60)
        _, nodes = S22Sent(1524, from)
        assert(nodes == 100, "we were the third to answer and sent " .. nodes .. " of 100 nodes")

        -- the same players' later packets do not count twice
        from = Start(1525)
        first = First(1525, from)
        for _ = 1, 4 do S22Other(1525, "Ahead1-Realm", 8) S22Other(1525, "Ahead2-Realm", 8) end
        S22Msg(first, me)
        advance(60)
        _, nodes = S22Sent(1525, from)
        assert(nodes == 100, "two players with many packets stopped our answer (" .. nodes .. " of 100 nodes)")

        -- our own packet never comes back (it can be lost): first packets of others stop nobody then
        -- (R1 S-M1 - the rule without the echo has a step of its own further down)
        from = Start(1526)
        First(1526, from)
        for k = 1, 3 do S22Other(1526, "Ahead" .. k .. "-Realm", 8) end
        advance(60)
        _, nodes = S22Sent(1526, from)
        assert(nodes == 100, "no echo, three others with one packet each right after our first: " .. nodes .. " of 100 nodes")
        from = Start(1527)
        First(1527, from)
        advance(1)
        assert(S22Sent(1527, from) == 1, "a second packet within a second of the first: more than one send ticker")
        advance(1) -- (our second packet is out)
        for k = 1, 3 do S22Other(1527, "Late" .. k .. "-Realm", 8) end
        advance(60)
        _, nodes = S22Sent(1527, from)
        assert(nodes == 100, "no echo, three others after our second packet: " .. nodes .. " of 100 nodes")

        -- an answer that gives way leaves nothing in the queue meanwhile: a harvest goes out at once
        from = Start(1528)
        first = First(1528, from)
        for k = 1, 3 do S22Other(1528, "Ahead" .. k .. "-Realm", 8) end
        S22Msg(first, me)
        local node = { id = "o1619", name = "Silverleaf", type = "herb", x = 0.33, y = 0.66, count = 1, last = time() }
        table.insert(ns.db.nodes[1412], node)
        local before = #sentMessages
        ns.SyncShare(1412, node)
        advance(3)
        local shared = false
        for i = before + 1, #sentMessages do if sentMessages[i]:find("^N:1412;o1619,") then shared = true end end
        for i, n in ipairs(ns.db.nodes[1412]) do if n == node then table.remove(ns.db.nodes[1412], i) break end end
        assert(shared, "while an answer gave way the own harvest waited behind its packets")

        -- the wait is spread over 2 to 15 seconds
        local realRandom = math.random
        math.random = function(a, b) if a then return b or a end return 0.999 end
        local fine, problem = pcall(function()
            advance(60) -- (the answers of the cases above are out: this one does not wait behind their packets)
            from = Start(1529)
            advance(13)
            assert(S22Sent(1529, from) == 0, "the longest wait is shorter than 13 s")
            advance(5)
            assert(S22Sent(1529, from) > 0, "the longest wait is longer than 18 s")
        end)
        math.random = realRandom
        if not fine then error(problem, 0) end
        advance(60) -- (that answer is out: the next one does not wait behind its packets)
        math.random = function(a, b) if a then return a end return 0 end
        fine, problem = pcall(function()
            from = Start(1530)
            advance(1.9)
            assert(S22Sent(1530, from) == 0, "the shortest wait is under 2 s")
            advance(2)
            assert(S22Sent(1530, from) > 0, "the shortest wait is over 3.9 s")
        end)
        math.random = realRandom
        if not fine then error(problem, 0) end
        advance(120)
    end)
    for _, mapID in ipairs(zones) do ns.db.nodes[mapID] = nil end
    ns.NotifyNodesChanged()
    if not saved then slash("sync off") end
    if not ok then error(err, 0) end
end)
step("/gcr perf: one line with the sync load of the last full minute and the memory (v0.1.22 S3)", function()
    -- Sven, 12.11.2026: the channel is full all the time, receivers refuse a
    -- lot ("rate limit hit"), Gathercraft shows 8-11 % of the addon time and
    -- 56-58 MB - and nothing in the game says how much of that is sharing.
    -- /gcr perf only reads: messages in and out, nodes read, what was
    -- refused, the time in the sync code, the addon's memory. One line.
    local db = ns.db.sync
    local saved = { enabled = db.enabled, pending = db.pending, counts = db.counts, update = UpdateAddOnMemoryUsage, get = GetAddOnMemoryUsage }
    db.pending, db.counts = {}, nil
    slash("sync on")
    advance(700)
    local function msg(text, who, prefix) fire("CHAT_MSG_ADDON", prefix or "Gathercraft", text, "CHANNEL", who, nil, nil, nil, "GathercraftSync") end
    local function nodes(count, seed)
        local parts = {}
        for k = 1, count do parts[k] = ("o96%d,h,%d,%d,2447"):format(1000 + seed * 10 + k, 1000 + (seed * 10 + k) * 7, 2000 + (seed * 10 + k) * 5) end
        return "N:1412;" .. table.concat(parts, ";")
    end
    -- the line /gcr perf printed, and that it was the only one
    local function Perf()
        local mark = #log
        slash("perf")
        local lines = {}
        for i = mark + 1, #log do if log[i]:find("^PRINT") then lines[#lines + 1] = log[i] end end
        assert(#lines == 1, "/gcr perf printed " .. #lines .. " lines, want 1")
        return lines[1]
    end
    local function Number(line, pattern)
        local v = line:match(pattern)
        assert(v, "not in the line (" .. pattern .. "): " .. line)
        return tonumber(v)
    end
    local ok, err = pcall(function()
        UpdateAddOnMemoryUsage, GetAddOnMemoryUsage = nil, nil
        -- to the start of a minute, then one minute of known traffic
        advance(60 - GetTime() % 60 + 1)
        local sentBefore = #sentMessages
        for k = 1, 5 do msg(nodes(3, k), "Stranger" .. k .. "-Realm") end              -- 5 messages, 15 nodes
        msg("Q:1412:999", "Asker-Realm")                                               -- 1 question (nothing to answer)
        for k = 1, 20 do msg(nodes(8, 10 + k), "Flood-Realm") end                      -- 20 messages: 144 nodes read, 16 over the limit per player
        for k = 1, 3 do msg("whatever", "Other" .. k .. "-Realm", "SomeOtherAddon") end -- not ours
        advance(2)
        for k = 1, 45 do msg(nodes(1, 100 + k), "Crowd" .. k .. "-Realm") end          -- one second: 40 read, 5 over the budget
        local node = { id = "o1619", name = "Silverleaf", type = "herb", x = 0.35, y = 0.64, count = 1, last = time() }
        table.insert(ns.db.nodes[1412], node)
        ns.SyncShare(1412, node)
        advance(10)
        for i, n in ipairs(ns.db.nodes[1412]) do if n == node then table.remove(ns.db.nodes[1412], i) break end end
        local sent = #sentMessages - sentBefore
        assert(sent > 0, "the harvest was not sent")
        advance(60 - GetTime() % 60 + 1)
        local line = Perf()
        assert(line:find("last full minute", 1, true), "no full minute named: " .. line)
        assert(Number(line, "sync messages received (%d+)") == 71, "messages in: " .. line)
        assert(Number(line, "send attempts (%d+)") == sent, "messages out, want " .. sent .. ": " .. line)
        assert(Number(line, "nodes announced (%d+)") == 15 + 144 + 40, "nodes read, want 199: " .. line)
        assert(Number(line, "(%d+) messages over the budget") == 5, "over the budget: " .. line)
        assert(Number(line, "(%d+) nodes over the limit per player") == 16, "over the limit: " .. line)
        assert(Number(line, "other addons' messages (%d+)") == 3, "other addons: " .. line)
        assert(Number(line, "time in the receive and send handlers ([%d.]+) ms") >= 0, "time: " .. line)
        assert(line:find("memory not readable in this client", 1, true), "no memory functions, and the line does not say so: " .. line)
        -- it only reads: asked again, the same numbers
        assert(Perf() == line, "asking twice changed the line")
        -- the memory, where the client tells it (asked for once per command)
        local updates = 0
        UpdateAddOnMemoryUsage = function() updates = updates + 1 end
        GetAddOnMemoryUsage = function(name) assert(name == "Gathercraft", "memory asked for " .. tostring(name)) return 57344 end
        line = Perf()
        assert(line:find("memory 56.0 MB", 1, true) and updates == 1, "memory (" .. updates .. " updates): " .. line)
        -- a client whose function fails: no error, said plainly
        GetAddOnMemoryUsage = function() error("blocked") end
        local before = #errors
        line = Perf()
        assert(#errors == before and line:find("memory not readable in this client", 1, true), "a failing memory function: " .. line)
        -- a quiet minute is a full minute of zeros, not the busy one again
        advance(125)
        line = Perf()
        assert(Number(line, "sync messages received (%d+)") == 0 and Number(line, "nodes announced (%d+)") == 0, "two quiet minutes later: " .. line)
        -- the help names the command
        local mark, named = #log, false
        slash("help")
        for i = mark + 1, #log do if log[i]:find("/gcr perf", 1, true) then named = true end end
        assert(named, "/gcr help does not name /gcr perf")
    end)
    UpdateAddOnMemoryUsage, GetAddOnMemoryUsage = saved.update, saved.get
    db.pending, db.counts = saved.pending, saved.counts
    if not saved.enabled then slash("sync off") end
    advance(120)
    if not ok then error(err, 0) end
end)
step("Sharing: turning the chat line off also drops a line that was already on its way (v0.1.22 S4)", function()
    -- Codex, 12.11.2026, round 3 on 0.1.21 (R3-N1): the line is said 20 s after
    -- the first spot (or 3 min after the last line), and the timer did not ask
    -- again - so one more line came after the box was unticked.
    local db = ns.db.sync
    local saved = { on = db.announceOn, off = db.announceOff, enabled = db.enabled }
    slash("sync on")
    local zone = ns.GetZoneName(1412)
    local function Lines(count)
        local n, text = 0, (ns.L["%d spots shared by other players added (%s)."]):format(count, zone)
        for _, l in ipairs(log) do if l:find(text, 1, true) then n = n + 1 end end
        return n
    end
    local function Any()
        local n = 0
        for k = 1, 9 do n = n + Lines(k) end
        return n
    end
    local spot = 0
    local function Arrive() -- a new spot from the guild, another place each time
        spot = spot + 1
        local before = select(2, ns.SyncSummary())
        fire("CHAT_MSG_ADDON", "Gathercraft", ("N:1412;o1621,h,%d,%d,2450"):format(2100 + spot * 43, 8300 + spot * 31), "GUILD", "Guildie Ten")
        assert(select(2, ns.SyncSummary()) > before, "test setup: the spot was not taken")
    end
    local ok, err = pcall(function()
        advance(400) -- whatever an earlier step left: said and over
        db.announceOn, db.announceOff = true, nil
        local n0 = Any()
        Arrive() Arrive()
        advance(5)
        -- turned off while the line waits (the options do exactly this)
        db.announceOn = nil
        advance(400)
        assert(Any() == n0, "the line came although it was turned off before its time")
        -- turned on again: what arrived before is not said late
        db.announceOn = true
        advance(400)
        assert(Any() == n0, "turning the line on said something old")
        local one = Lines(1)
        Arrive()
        advance(25)
        assert(Lines(1) == one + 1 and Any() == n0 + 1, "after turning it on again the next spot is said as one spot, once")
    end)
    db.announceOn, db.announceOff, db.enabled = saved.on, saved.off, saved.enabled
    advance(400)
    if not ok then error(err, 0) end
end)
-- ---------------------------------------------------------------- v0.1.22, part W: the paths you ride
-- A small world for the steps about recorded paths: one zone of 5000 x 2500
-- yards, a player who is moved by hand and looked at twice a second.
local function PathsWorld()
    local HBD = LibStub("HereBeDragons-2.0")
    local W = { speed = 7, falling = false, swimming = false, w = 5000, h = 2500,
        keep = { size = HBD.GetZoneSize, speed = GetUnitSpeed, fall = IsFalling, swim = IsSwimming, inst = IsInInstance, taxi = UnitOnTaxi,
            dead = UnitIsDeadOrGhost, vehicle = UnitInVehicle, fly = IsFlying, map = player.map, x = player.x, y = player.y,
            paths = ns.db.paths, secret = issecretvalue, pos = C_Map.GetPlayerMapPosition } }
    HBD.GetZoneSize = function(_, mapID) if (mapID == 1412 or mapID == 1411) and not W.noSize then return W.w, W.h end return 0, 0 end
    GetUnitSpeed = function() return W.speed end
    IsFalling = function() return W.falling end
    IsSwimming = function() return W.swimming end
    IsInInstance = function() return false, "none" end
    UnitOnTaxi = function() return false end
    UnitIsDeadOrGhost = function() return false end
    UnitInVehicle = function() return false end
    IsFlying = function() return false end
    ns.db.paths = nil
    ns.PathsSetEnabled(true)
    player.map = 1412
    -- the player at this many yards from the zone's top left corner
    function W.At(yx, yy) player.x, player.y = yx / W.w, yy / W.h end
    function W.Where() return player.x * W.w, player.y * W.h end
    -- the middle of a square
    function W.Mid(tx, ty) W.At(tx * 25 + 12.5, ty * 25 + 12.5) end
    -- one look later, moved by (dx, dy) yards
    function W.Step(dx, dy)
        local x, y = W.Where()
        W.At(x + (dx or 0), y + (dy or 0))
        advance(0.5)
    end
    -- `yards` in the direction (ux, uy), `per` yards a look
    function W.Go(ux, uy, yards, per)
        per = per or W.speed * 0.5
        for _ = 1, math.floor(yards / per + 0.5) do W.Step(ux * per, uy * per) end
    end
    -- a place nothing was learned at before: stand there, be seen once (it is more than one
    -- square from where you were: that alone is a new start)
    function W.Start(tx, ty)
        W.Mid(tx, ty)
        advance(0.5)
    end
    function W.Piece(tx, ty, dx, dy) return ns.PathsPiece(1412, tx, ty, dx, dy) end
    function W.Total() return (ns.PathsCount()) end
    function W.Done()
        local k = W.keep
        HBD.GetZoneSize, GetUnitSpeed, IsFalling, IsSwimming, IsInInstance, UnitOnTaxi = k.size, k.speed, k.fall, k.swim, k.inst, k.taxi
        UnitIsDeadOrGhost, UnitInVehicle, IsFlying, issecretvalue, C_Map.GetPlayerMapPosition = k.dead, k.vehicle, k.fly, k.secret, k.pos
        player.map, player.x, player.y = k.map, k.x, k.y
        ns.db.paths = k.paths
        fire("PLAYER_ENTERING_WORLD")
        advance(1)
    end
    return W
end

step("Paths: crossing from one 25-yard square into the next is counted, with a cost that does not depend on your speed (v0.1.22 W1, W2)", function()
    -- Sven, 12.11.2026: "wir brauchen die Routen". Collected only: every
    -- crossing between neighbouring squares with how often, its cost (the way
    -- made in the square you left, time x speed, over the straight line
    -- between the centres), falls, swims and the day.
    local W = PathsWorld()
    local ok, err = pcall(function()
        assert(ns.PathsEnabled() == true and W.Total() == 0, "test setup: recording on, nothing recorded")
        local sx, sy = ns.PathsSquare(1412, 0.5, 0.5)
        assert(sx == 100 and sy == 50, ("the middle of a 5000 x 2500 yard zone is square 100, 50 - got %s, %s"):format(tostring(sx), tostring(sy)))

        -- on foot, 7 yards a second, 150 yards east along the middle of a row
        W.speed = 7
        W.Start(100, 50)
        W.Go(1, 0, 150)
        for tx = 100, 104 do
            local count, cost, falls, swims, day = W.Piece(tx, 50, 1, 0)
            assert(count == 1, ("square %d -> %d: counted %s times, want 1"):format(tx, tx + 1, tostring(count)))
            assert(falls == 0 and swims == 0, "a walk on dry land has falls or swims")
            assert(day == math.floor(time() / 86400) - 20454, "the day of the piece is " .. tostring(day))
            if tx > 100 then assert(cost >= 1 and cost <= 1.15, ("straight through square %d: cost %.2f, want about 1"):format(tx, cost)) end
        end
        assert(W.Total() == 6, "150 yards east from the middle of a square are 6 crossings, counted " .. W.Total())
        assert(W.Piece(101, 50, -1, 0) == nil, "the way back was counted without being ridden")
        assert(W.Piece(101, 50, 0, 1) == nil and W.Piece(101, 49, 1, 0) == nil, "a piece next to the way was counted")

        -- the same kind of stretch on a mount at 14 and at 20 yards a second: the same cost
        for i, speed in ipairs({ 14, 20 }) do
            W.speed = speed
            W.Start(100, 52 + i)
            W.Go(1, 0, 150)
            local _, cost = W.Piece(102, 52 + i, 1, 0)
            assert(cost and cost >= 1 and cost <= 1.25, ("at %d yards a second: cost %s, want about 1"):format(speed, tostring(cost)))
        end

        -- a detour: 7 yards a second on your feet, but only 3.5 a second forward
        W.speed = 7
        W.Start(100, 56)
        W.Go(1, 0, 100, 1.75)
        local _, detour = W.Piece(102, 56, 1, 0)
        assert(detour and detour >= 1.8 and detour <= 2.2, ("twice the way through a square: cost %s, want about 2"):format(tostring(detour)))

        -- the same piece again, straight this time: counted twice, the cost is the mean
        W.Start(100, 56)
        W.Go(1, 0, 100)
        local count, mean = W.Piece(102, 56, 1, 0)
        assert(count == 2 and mean > 1.3 and mean < 1.7, ("once about 2, once about 1: count %s, cost %s"):format(tostring(count), tostring(mean)))

        -- across a corner: the straight line is longer (35 yards), the cost is about 1 again
        W.speed = 7
        W.Start(100, 60)
        W.Go(1, 1, 100, 2.5)
        local c, diagonal = W.Piece(102, 62, 1, 1)
        assert(c == 1 and diagonal >= 1 and diagonal <= 1.15, ("diagonally: count %s, cost %s"):format(tostring(c), tostring(diagonal)))

        -- the way back is a piece of its own
        W.Start(104, 64)
        W.Go(-1, 0, 100)
        assert(W.Piece(103, 64, -1, 0) == 1 and W.Piece(102, 64, 1, 0) == nil, "riding west: the piece west, not the piece east")

        -- standing still learns nothing and costs nothing later
        local before = W.Total()
        W.speed = 0
        W.Start(100, 66)
        advance(30)
        W.speed = 7
        W.Go(1, 0, 60)
        local _, afterRest = W.Piece(101, 66, 1, 0)
        assert(W.Total() == before + 2 and afterRest <= 1.15, ("a rest of 30 s made the next square cost %s"):format(tostring(afterRest)))

        -- a fall: in the air for a second or more while crossing - a jump is not one
        W.Start(100, 70)
        W.Go(1, 0, 7)
        W.falling = true
        W.Go(1, 0, 14) -- 2 s in the air, into square 101
        W.falling = false
        W.Go(1, 0, 30)
        local _, _, falls = W.Piece(100, 70, 1, 0)
        assert(falls == 1, "two seconds in the air on the way out of the square: " .. tostring(falls) .. " falls, want 1")
        W.Start(100, 72)
        W.Go(1, 0, 7)
        W.falling = true
        W.Go(1, 0, 3.5) -- half a second: a jump
        W.falling = false
        W.Go(1, 0, 30)
        _, _, falls = W.Piece(100, 72, 1, 0)
        assert(falls == 0, "a jump was taken for a fall")

        -- swimming, where the client tells it
        W.Start(100, 74)
        W.swimming = true
        W.Go(1, 0, 40)
        W.swimming = false
        local _, _, _, swims = W.Piece(100, 74, 1, 0)
        assert(swims == 1, "swum out of the square: " .. tostring(swims) .. " swims, want 1")
        -- ... and a client without the function (not seen live yet: Sven had no water on 12.11.)
        local before2, errorsBefore = W.Total(), #errors
        IsSwimming = nil
        W.Start(100, 76)
        W.Go(1, 0, 40)
        assert(#errors == errorsBefore and W.Total() == before2 + 2, "without IsSwimming nothing is learned any more")
        _, _, _, swims = W.Piece(100, 76, 1, 0)
        assert(swims == 0, "no IsSwimming, and a swim was counted")

        -- what is kept: numbers only - no names, no times, no trace
        local p = ns.db.paths
        local sum = 0
        for key, value in pairs(p) do
            assert(key == "zones" or key == "total" or key == "off", "saved with the paths: " .. tostring(key))
            assert(type(value) ~= "string", "a text is saved with the paths")
        end
        for mapID, z in pairs(p.zones) do
            assert(type(mapID) == "number", "a zone is not kept by its number")
            for key, value in pairs(z) do assert(key == "n" or key == "e", "saved with a zone: " .. tostring(key)) end
            local n = 0
            for key, value in pairs(z.e) do
                assert(type(key) == "number" and type(value) == "number" and value == math.floor(value) and value < 2 ^ 48, "a piece is not one whole number")
                n = n + 1
            end
            assert(n == z.n, "the zone's count is " .. tostring(z.n) .. ", it holds " .. n)
            sum = sum + n
        end
        assert(sum == p.total and sum == W.Total(), "the total is " .. tostring(p.total) .. ", there are " .. sum)
    end)
    W.Done()
    if not ok then error(err, 0) end
end)

step("Paths: nothing is learned where you are carried, dead, in an instance, teleported or where the client hides values (v0.1.22 W3)", function()
    local W = PathsWorld()
    local SECRET = newproxy(true)
    local row = 80
    -- a straight ride of 60 yards from the middle of a fresh row; returns how many pieces it made
    local function Ride(prepare, undo)
        row = row + 2
        W.Start(100, row)
        local before = W.Total()
        if prepare then prepare() end
        W.Go(1, 0, 60, 3.5)
        if undo then undo() end
        return W.Total() - before
    end
    local ok, err = pcall(function()
        assert(Ride() == 2, "test setup: a plain ride of 60 yards makes 2 pieces")
        local cases = {
            { "in an instance", function() IsInInstance = function() return true, "party" end end, function() IsInInstance = function() return false, "none" end end },
            { "on a flight path", function() UnitOnTaxi = function() return true end end, function() UnitOnTaxi = function() return false end end },
            { "dead or a ghost", function() UnitIsDeadOrGhost = function() return true end end, function() UnitIsDeadOrGhost = function() return false end end },
            { "in a vehicle", function() UnitInVehicle = function() return true end end, function() UnitInVehicle = function() return false end end },
            { "flying", function() IsFlying = function() return true end end, function() IsFlying = function() return false end end },
            { "carried (no speed of your own)", function() W.speed = 0 end, function() W.speed = 7 end },
            { "a hidden speed", function() issecretvalue = function(v) return rawequal(v, SECRET) end W.speed = SECRET end, function() W.speed = 7 issecretvalue = W.keep.secret end },
            { "a hidden position", function()
                issecretvalue = function(v) return rawequal(v, SECRET) end
                C_Map.GetPlayerMapPosition = function() return { GetXY = function() return SECRET, SECRET end } end
            end, function() C_Map.GetPlayerMapPosition = W.keep.pos issecretvalue = W.keep.secret end },
            { "a zone without a size", function() W.noSize = true end, function() W.noSize = false end },
            { "recording turned off", function() ns.PathsSetEnabled(false) end, function() ns.PathsSetEnabled(true) end },
        }
        for _, c in ipairs(cases) do
            local errorsBefore = #errors
            local made = Ride(c[2], c[3])
            assert(#errors == errorsBefore, c[1] .. ": an error")
            assert(made == 0, c[1] .. ": " .. made .. " pieces learned, want none")
            -- ... and right after it everything is learned again
            assert(Ride() == 2, "after \"" .. c[1] .. "\" a plain ride makes no pieces any more")
        end
        assert(ns.db.paths.off == nil, "turned on again, and the saved data still says off")
        ns.PathsSetEnabled(false)
        assert(ns.db.paths.off == true and ns.PathsEnabled() == false, "turned off: not kept")
        ns.PathsSetEnabled(true)

        -- taken off the flight path in the middle of a square: the way made in the air does not count
        row = row + 2
        W.Start(100, row)
        local before = W.Total()
        UnitOnTaxi = function() return true end
        W.Go(1, 0, 20)
        UnitOnTaxi = function() return false end
        W.Go(1, 0, 60)
        local count, cost = W.Piece(101, row, 1, 0)
        assert(count == 1 and cost <= 1.15, ("the square after landing: count %s, cost %s"):format(tostring(count), tostring(cost)))

        -- a teleport: far away in one look - no piece between the two places, both learn on
        row = row + 2
        W.Start(100, row)
        before = W.Total()
        W.Go(1, 0, 7)
        W.Step(40 * 25, 0)
        assert(W.Total() == before, "a teleport made a piece")
        W.Go(1, 0, 60)
        assert(W.Total() == before + 2 and W.Piece(141, row, 1, 0) == 1, "after a teleport nothing is learned at the new place")
        -- two squares in one look (a hitch): no piece either, not a made-up one
        row = row + 2
        W.Start(100, row)
        before = W.Total()
        W.Go(1, 0, 7)
        W.Step(50, 0)
        assert(W.Total() == before, "two squares in one look made a piece")

        -- a loading screen in between: the way made before it does not count for the square after it
        row = row + 2
        W.Start(100, row)
        before = W.Total()
        W.Go(1, 0, 10.5) -- 23 yards into the square, 2 from its edge
        fire("PLAYER_ENTERING_WORLD")
        W.Step(3.5, 0)   -- seen again in the next square
        assert(W.Total() == before, "across a loading screen a piece was learned")

        -- another zone: no piece from one zone into the other
        row = row + 2
        W.Start(100, row)
        before = W.Total()
        W.Go(1, 0, 7)
        player.map = 1411
        W.Step(3.5, 0)
        W.Go(1, 0, 60)
        player.map = 1412
        local _, zones = ns.PathsCount()
        assert(zones == 2 and ns.PathsPiece(1411, 101, row, 1, 0) == 1, "the other zone's pieces are not kept under that zone")
        assert(W.Piece(100, row, 1, 0) == nil, "a piece from one zone into the other")
    end)
    W.Done()
    if not ok then error(err, 0) end
end)

step("Paths: a look costs the same however much is known, at most two a second (v0.1.22 W5)", function()
    local W = PathsWorld()
    local keepTime = GetTime
    local ok, err = pcall(function()
        -- the ticker: looks happen twice a second and not more often
        W.Start(100, 100)
        local looks, realSpeed = 0, GetUnitSpeed
        GetUnitSpeed = function() looks = looks + 1 return 7 end
        advance(60)
        GetUnitSpeed = realSpeed
        assert(looks >= 118 and looks <= 121, looks .. " looks in a minute, want 120")
        -- 16,000 looks along a zigzag through two zones, on a clock of our own (no other timer runs)
        W.speed = 20 -- (10 yards a look, as the zigzag below moves)
        local clock = GetTime()
        GetTime = function() return clock end
        local function Batch(count, row0)
            local x, y, dir = 300, row0 * 25 + 12.5, 1
            local t0 = os.clock()
            for _ = 1, count do
                x = x + dir * 10
                if x > 4700 or x < 300 then dir, y = -dir, y + 25 end
                W.At(x, y)
                clock = clock + 0.5
                ns.PathsLook()
            end
            return (os.clock() - t0) / count * 1e6
        end
        local first = Batch(8000, 2)
        local known = W.Total()
        player.map = 1411
        local last = Batch(8000, 2)
        player.map = 1412
        note(("paths: %.1f us a look with %d pieces known, %.1f us with %d"):format(first, known, last, W.Total()))
        assert(W.Total() > 2 * known * 0.9 and known > 2000, "test setup: the looks did not learn pieces (" .. known .. ", " .. W.Total() .. ")")
        assert(last < first * 3 + 20, ("a look took %.1f us with few pieces known and %.1f us with many"):format(first, last))
    end)
    GetTime = keepTime
    W.Done()
    if not ok then error(err, 0) end
end)
step("Paths: at most 30,000 pieces, 8,000 a zone - the longest unused go first; the size of the saved data (v0.1.22 W4)", function()
    local W = PathsWorld()
    local keepTime, keepClock = time, GetTime
    local HBD = LibStub("HereBeDragons-2.0")
    local ok, err = pcall(function()
        local maxTotal, maxZone, tile = ns.PathsLimits()
        assert(maxTotal == 30000 and maxZone == 8000 and tile == 25, ("limits %s / %s, squares of %s"):format(tostring(maxTotal), tostring(maxZone), tostring(tile)))
        -- four zones with a size, a calendar and a clock of our own
        HBD.GetZoneSize = function(_, mapID) if mapID >= 1411 and mapID <= 1414 then return W.w, W.h end return 0, 0 end
        local day = 0
        time = function() return (20454 + 100 + day) * 86400 + 4000 end
        local clock = GetTime()
        GetTime = function() return clock end
        W.speed = 25 -- 12.5 yards a look: every second look crosses into the next square
        local function Pieces(mapID) local z = ns.db.paths.zones[mapID] return z and z.n or 0 end
        local function Look(x, y)
            W.At(x, y)
            clock = clock + 0.5
            ns.PathsLook()
        end
        -- rides east along row after row of the zone until `add` new pieces are made; returns the next free row
        local function Fill(mapID, row, add)
            player.map = mapID
            local made = 0
            while made < add do
                clock = clock + 10 -- (a new start)
                local y = row * 25 + 12.5
                Look(300, y)
                local x, madeBefore = 300, made
                while x < 4700 and made < add do
                    x = x + 12.5
                    local before = ns.PathsPiece(mapID, math.floor(x / 25) - 1, row, 1, 0)
                    Look(x, y)
                    if not before and ns.PathsPiece(mapID, math.floor(x / 25) - 1, row, 1, 0) then made = made + 1 end
                end
                -- (said as a failure: a recording that notes nothing must not ride on for ever)
                assert(made > madeBefore, "a whole row of zone " .. mapID .. " ridden (row " .. row .. ") and no path piece noted")
                row = row + 1
            end
            return row
        end
        -- rides the first `count` squares of a row again
        local function Again(mapID, row, count)
            player.map = mapID
            clock = clock + 10
            local y = row * 25 + 12.5
            Look(300, y)
            for i = 1, count * 2 do Look(300 + i * 12.5, y) end
        end
        local function ByDay(mapID)
            local days = {}
            for _, v in pairs(ns.db.paths.zones[mapID].e) do
                local d = v % 16384
                days[d] = (days[d] or 0) + 1
            end
            return days
        end

        -- one zone: 4000 pieces on the first day, 100 of them ridden twice; 4000 on the second
        day = 1
        local row = Fill(1412, 0, 4000)
        Again(1412, 0, 100)
        day = 2
        row = Fill(1412, row, 4000)
        assert(Pieces(1412) == 8000 and ns.PathsCount() == 8000, "test setup: 8000 pieces in the zone")
        -- the third day: 50 old pieces are used again, then one new piece is one too many
        day = 3
        Again(1412, 1, 50)
        assert(Pieces(1412) == 8000, "riding known pieces again made new ones")
        Fill(1412, row, 1)
        local days = ByDay(1412)
        local d1, d2, d3 = days[101] or 0, days[102] or 0, days[103] or 0
        assert(Pieces(1412) == 7201 and d1 + d2 + d3 == 7201, ("after the 8001st piece the zone holds %d, want 7201 (a tenth gone)"):format(Pieces(1412)))
        assert(d2 == 4000 and d3 == 51, ("gone from the newer days: day 2 holds %d of 4000, day 3 %d of 51"):format(d2, d3))
        assert(d1 == 3150, ("day 1 holds %d, want 3150 (4000 less the 50 used again and the 800 that went)"):format(d1))
        -- of the oldest day the rarely used went first: the 100 ridden twice are all there
        local twice = 0
        for tx = 12, 111 do
            local count = ns.PathsPiece(1412, tx, 0, 1, 0)
            if count == 2 then twice = twice + 1 end
        end
        assert(twice == 100, "of the pieces ridden twice on the oldest day " .. twice .. " of 100 are left")
        assert(ns.PathsCount() == 7201, "the total does not follow the zone: " .. ns.PathsCount())

        -- all zones together: three more zones, 30,000 in all, the oldest a small zone of its own
        ns.db.paths = nil
        day = 1
        Fill(1414, 0, 40)
        day = 2
        Fill(1411, 0, 7960)
        Fill(1412, 0, 8000)
        day = 3
        Fill(1413, 0, 8000)
        Fill(1411, 60, 40) -- (rows the zone has not seen yet)
        local row14 = Fill(1414, 10, 5960)
        local total, zones = ns.PathsCount()
        assert(total == 30000 and zones == 4, ("test setup: %d pieces in %d zones"):format(total, zones))
        local t0 = os.clock()
        Fill(1414, row14, 1)
        local took = (os.clock() - t0) * 1000
        total, zones = ns.PathsCount()
        assert(total == 27001, "after the 30,001st piece " .. total .. " are kept, want 27,001 (a tenth gone)")
        -- the 40 of day 1 went, the rest from day 2; nothing of day 3
        local left = { [101] = 0, [102] = 0, [103] = 0 }
        local sum = 0
        for mapID, z in pairs(ns.db.paths.zones) do
            local n = 0
            for d, c in pairs(ByDay(mapID)) do left[d] = (left[d] or 0) + c n = n + c end
            assert(n == z.n, "zone " .. mapID .. " counts " .. z.n .. " and holds " .. n)
            sum = sum + n
        end
        assert(sum == 27001 and left[101] == 0 and left[102] == 15960 - 2960 and left[103] == 14001,
            ("left by day: %d / %d / %d, want 0 / 13000 / 14001"):format(left[101], left[102], left[103]))
        note(("paths: making room at the limit took %.1f ms"):format(took))
        assert(took < 500, ("making room took %.0f ms"):format(took))

        -- a zone whose pieces all went is gone itself
        ns.db.paths = nil
        day = 1
        Fill(1414, 0, 30)
        day = 2
        Fill(1412, 0, 8000) Fill(1411, 0, 8000) Fill(1413, 0, 8000)
        player.map = 1414
        day = 3
        local need = 30000 - ns.PathsCount()
        assert(need == 5970, "test setup: " .. need .. " pieces to the limit")
        -- fill up with pieces of day 3 in a zone that has room, then one more
        HBD.GetZoneSize = function(_, mapID) if mapID >= 1411 and mapID <= 1415 then return W.w, W.h end return 0, 0 end
        Fill(1415, 0, 5971)
        total, zones = ns.PathsCount()
        assert(total == 27001 and zones == 4 and ns.db.paths.zones[1414] == nil, ("%d pieces in %d zones; the emptied zone is %s"):format(total, zones, ns.db.paths.zones[1414] and "still there" or "gone"))

        -- the saved data at the limit, written the way the game writes it
        ns.db.paths = nil
        day = 1
        Fill(1411, 0, 8000) Fill(1412, 0, 8000) Fill(1413, 0, 8000) Fill(1414, 0, 6000)
        assert(ns.PathsCount() == 30000, "test setup: the limit")
        local bytes = 0
        for mapID, z in pairs(ns.db.paths.zones) do
            bytes = bytes + #(("\t\t\t[%d] = {\n\t\t\t\t[\"n\"] = %d,\n\t\t\t\t[\"e\"] = {\n\t\t\t\t},\n\t\t\t},\n"):format(mapID, z.n))
            for key, value in pairs(z.e) do
                bytes = bytes + #(("\t\t\t\t\t[%d] = %.0f,\n"):format(key, value))
            end
        end
        note(("paths: 30000 pieces are %.0f KB in the saved file, %.1f bytes a piece"):format(bytes / 1024, bytes / 30000))
        assert(bytes < 1024 * 1024, ("the saved paths are %.0f KB at the limit, want under 1 MB"):format(bytes / 1024))
    end)
    time, GetTime = keepTime, keepClock
    W.Done()
    if not ok then error(err, 0) end
end)
step("Paths: on by default with a switch in the options, a note once, /gcr paths and /gcr paths clear (v0.1.22 W7)", function()
    -- Sven, 12.11.2026: always outside, on by default, a note the first
    -- time, a switch in the options; the data stays on this computer.
    local W = PathsWorld()
    local L = ns.L
    local win = _G.GathercraftOptions
    local wasOpen = win:IsShown()
    local nodesBefore = 0
    for _, list in pairs(ns.db.nodes) do nodesBefore = nodesBefore + #list end
    local function Said(from, text)
        for i = from + 1, #log do if log[i]:find(text, 1, true) then return true end end
        return false
    end
    local NOTE = (L["New: Gathercraft notes which ways you ride, as small pieces per map square - only on this computer, nothing is sent. Later routes can go around obstacles with it. Switch: Options, %s. What it holds: /gcr paths"]):format(L["Sharing"])
    local ok, err = pcall(function()
        -- the note: once, some seconds after the first login with this version
        advance(30) -- (the note of the session's own login is said and over)
        ns.db.paths = nil
        local mark = #log
        fire("PLAYER_LOGIN")
        advance(5)
        assert(not Said(mark, NOTE), "the note came in the first seconds of the login")
        advance(20)
        assert(Said(mark, NOTE), "no note after the first login")
        assert(ns.PathsEnabled() == true and ns.db.paths.off == nil, "not on by default")
        mark = #log
        fire("PLAYER_LOGIN")
        advance(30)
        assert(not Said(mark, NOTE), "the note came a second time")
        -- somebody who turned it off before the note is not told that it records
        ns.db.paths = { off = true }
        mark = #log
        fire("PLAYER_LOGIN")
        advance(30)
        assert(not Said(mark, NOTE) and ns.PathsEnabled() == false, "turned off, and the note says it records")
        ns.PathsSetEnabled(true)

        -- the switch: on the page with room for it, with its header and its hint
        if not wasOpen then ns.ToggleOptions() end
        ns.ShowOptionsSection("sync")
        local function Find(text)
            for _, f in ipairs(allFrames) do
                if f.__kind == "FontString" and f.__text == text then return f end
            end
        end
        local label = Find(L["Record the paths I ride"])
        assert(label, "no switch \"Record the paths I ride\" in the options")
        assert(Find(L["Paths"]) and Find(L["Only on this computer, nothing is sent. Helps routes later."]), "the switch has no header or no hint")
        local box = (label.__pts.TOPLEFT and label.__pts.TOPLEFT[1]) or (label.__pts.LEFT and label.__pts.LEFT[1])
        assert(box and box.__kind == "CheckButton" and box.get and box.__scripts.OnClick, "test setup: the switch")
        local page = label.__parent
        while page and not page.key do page = page.__parent end
        assert(page and page.key == "sync", "the switch is on page " .. tostring(page and page.key))
        assert(box.get() == true, "on by default, and the box is empty")
        box:SetChecked(false) box.__scripts.OnClick(box)
        assert(ns.db.paths.off == true and ns.PathsEnabled() == false and box.get() == false, "unticked: still recording")
        local before = W.Total()
        W.Start(100, 120)
        W.Go(1, 0, 60)
        assert(W.Total() == before, "unticked, and a ride was recorded")
        box:SetChecked(true) box.__scripts.OnClick(box)
        assert(ns.db.paths.off == nil and ns.PathsEnabled() == true and box.get() == true, "ticked again: not recording")
        W.Start(100, 122)
        W.Go(1, 0, 60)
        assert(W.Total() == before + 2, "ticked again, and a ride was not recorded")
        -- every page still ends above the footer
        local used = ns.OptionsUsedHeight()
        local ROOM = 640 - 112 - 18 - 4 - 66
        assert(used.sync <= ROOM, ("Options sync: %d px of %d"):format(used.sync, ROOM))

        -- /gcr paths: on or off, pieces, zones, the limit, the size - and the zones
        ns.db.paths = nil
        mark = #log
        slash("paths")
        local _, _, _, bytes = ns.PathsLimits()
        assert(Said(mark, (L["Paths: recording is %s. %d path pieces in %d zones (at most %d), about %d KB in the saved data. Only on this computer."]):format(L["|cff00ff00ON|r"], 0, 0, 30000, 0)), "/gcr paths with nothing recorded")
        W.Start(100, 124)
        W.Go(1, 0, 110)
        player.map = 1411
        W.Start(100, 124)
        W.Go(1, 0, 60)
        player.map = 1412
        mark = #log
        slash("paths")
        assert(Said(mark, (L["Paths: recording is %s. %d path pieces in %d zones (at most %d), about %d KB in the saved data. Only on this computer."]):format(L["|cff00ff00ON|r"], 6, 2, 30000, math.floor(6 * bytes / 1024 + 0.5))), "/gcr paths after two rides")
        assert(Said(mark, ("  %s: %d"):format(ns.GetZoneName(1412), 4)) and Said(mark, ("  %s: %d"):format(ns.GetZoneName(1411), 2)), "/gcr paths does not list the zones with their pieces")
        assert(bytes >= 25 and bytes <= 29, "a piece is said to take " .. tostring(bytes) .. " bytes; the saved file has 26.7")
        -- /gcr paths off and on do what the switch does
        slash("paths off")
        assert(ns.db.paths.off == true and box.get() == false, "/gcr paths off")
        mark = #log
        slash("paths")
        assert(Said(mark, L["|cffff0000OFF|r"]), "/gcr paths does not say that it is off")
        slash("paths on")
        assert(ns.db.paths.off == nil and box.get() == true, "/gcr paths on")

        -- /gcr paths clear asks first, deletes only the paths, and says so
        mark = #log
        slash("paths clear")
        assert(Said(mark, (L["This deletes the %d recorded path pieces and nothing else. To do it: /gcr paths clear yes"]):format(6)), "/gcr paths clear does not ask")
        assert(W.Total() == 6, "/gcr paths clear deleted without the yes")
        slash("paths clear no")
        assert(W.Total() == 6, "/gcr paths clear no deleted")
        mark = #log
        slash("paths clear yes")
        assert(Said(mark, (L["Recorded paths deleted (%d path pieces). Your nodes and everything else are untouched."]):format(6)), "/gcr paths clear yes does not say what it did")
        local total, zones = ns.PathsCount()
        assert(total == 0 and zones == 0, "/gcr paths clear yes left pieces")
        assert(ns.db.paths.off == nil and ns.PathsEnabled() == true, "/gcr paths clear yes turned the recording off")
        local nodesAfter = 0
        for _, list in pairs(ns.db.nodes) do nodesAfter = nodesAfter + #list end
        assert(nodesAfter == nodesBefore, "/gcr paths clear yes changed the nodes")
        mark = #log
        slash("paths clear")
        assert(Said(mark, L["No paths recorded yet."]), "/gcr paths clear with nothing recorded")
        -- recording goes on right after it
        W.Start(100, 126)
        W.Go(1, 0, 60)
        assert(W.Total() == 2, "after /gcr paths clear yes nothing is recorded any more")
        -- the help names the command
        mark = #log
        slash("help")
        assert(Said(mark, L["  /gcr paths        - the ways you ride, noted on this computer"]), "/gcr help does not name /gcr paths")
        -- every text in this language
        if LOCALE ~= "enUS" then
            for _, key in ipairs({ "Paths", "Record the paths I ride", "Only on this computer, nothing is sent. Helps routes later.", "  ... and %d more zones",
                "No paths recorded yet.", "  /gcr paths        - the ways you ride, noted on this computer" }) do
                assert(L[key] ~= key, "not translated: " .. key)
            end
        end
        -- more than ten zones: the ten with the most pieces, and how many more
        local z = ns.db.paths.zones
        for i = 1, 13 do z[2000 + i] = { n = i, e = {} } end
        mark = #log
        slash("paths")
        assert(Said(mark, (L["  ... and %d more zones"]):format(4)), "14 zones: the line about the rest")
    end)
    if not wasOpen and win:IsShown() then ns.ToggleOptions() end
    W.Done()
    if not ok then error(err, 0) end
end)
step("Paths: damaged saved path data is put right once, only where it is damaged, and makes no error (v0.1.22 R1 W-H1)", function()
    -- Codex, 13.11.2026 (W-H1): a zone without its table of pieces, a zone
    -- without its count, a total that does not fit - each made a Lua error
    -- while riding. The saved data is looked through once when it is taken
    -- over (not at every look): what is damaged is put right or dropped, in
    -- the zone it is in.
    local W = PathsWorld()
    local HBD = LibStub("HereBeDragons-2.0")
    local row = 200
    local ok, err = pcall(function()
        HBD.GetZoneSize = function(_, mapID) if mapID >= 1411 and mapID <= 1414 then return W.w, W.h end return 0, 0 end
        -- a real piece to build saved data from
        W.Start(100, row)
        W.Go(1, 0, 60)
        local key, value
        for k, v in pairs(ns.db.paths.zones[1412].e) do key, value = k, v end
        assert(key and W.Total() == 2, "test setup: a ride of 60 yards makes 2 pieces")
        -- the saved data fits itself: every zone counts what it holds, the total is the sum
        local function Fits()
            local p = ns.db.paths
            if type(p) ~= "table" or type(p.zones) ~= "table" or type(p.total) ~= "number" then return "no zones or no total" end
            local sum = 0
            for mapID, z in pairs(p.zones) do
                if type(mapID) ~= "number" or type(z) ~= "table" then return "zone " .. tostring(mapID) .. " is no zone" end
                if type(z.e) ~= "table" or type(z.n) ~= "number" then return "zone " .. mapID .. ": e is a " .. type(z.e) .. ", n a " .. type(z.n) end
                local n = 0
                for k, v in pairs(z.e) do
                    if type(k) ~= "number" or type(v) ~= "number" or v ~= math.floor(v) or v < 0 or v >= 2 ^ 48 then return "zone " .. mapID .. " holds " .. tostring(k) .. " = " .. tostring(v) end
                    n = n + 1
                end
                if n ~= z.n then return "zone " .. mapID .. " counts " .. z.n .. " and holds " .. n end
                if n == 0 then return "zone " .. mapID .. " is kept empty" end
                sum = sum + n
            end
            if sum ~= p.total then return "the total is " .. p.total .. ", there are " .. sum end
        end
        -- loads `saved` as the saved data, rides 60 yards in zone 1412 and looks at /gcr paths
        local function Loaded(what, saved, want)
            row = row + 2
            local errorsBefore = #errors
            -- (the saved table is taken over with its first use - no login is played here: every
            -- login in this test world starts the tickers of all modules once more)
            ns.db.paths = saved
            W.Start(100, row)
            W.Go(1, 0, 60)
            slash("paths")
            assert(#errors == errorsBefore, what .. ": " .. tostring(errors[#errors]))
            assert(W.Piece(100, row, 1, 0) == 1 and W.Piece(101, row, 1, 0) == 1, what .. ": the ride after it is not recorded")
            local wrong = Fits()
            assert(not wrong, what .. ": " .. tostring(wrong))
            if want then assert(W.Total() == want, what .. ": " .. W.Total() .. " pieces, want " .. want) end
        end
        local function Zone(n) return { n = n or 1, e = { [key] = value } } end

        -- Codex's three shapes
        Loaded("a zone without its pieces", { hinted = true, total = 0, zones = { [1412] = { n = 0 } } }, 2)
        Loaded("a zone without its count", { hinted = true, total = 0, zones = { [1412] = { e = {} } } }, 2)
        Loaded("a full total and nothing there", { hinted = true, total = 30000, zones = {} }, 2)
        -- the wrong kind of thing in every place
        Loaded("the paths are a text", "paths", 2)
        Loaded("the zones are a number", { hinted = true, total = 3, zones = 5 }, 2)
        Loaded("the total is a text", { hinted = true, total = "many", zones = { [1411] = Zone() } }, 3)
        Loaded("a zone is a text", { hinted = true, total = 1, zones = { [1412] = "zone" } }, 2)
        Loaded("a zone under a name", { hinted = true, total = 1, zones = { Mulgore = Zone() } }, 2)
        Loaded("a count that is a text, pieces that are a text", { hinted = true, total = 5, zones = { [1412] = { n = "5", e = "pieces" } } }, 2)
        Loaded("a count that is a text over real pieces", { hinted = true, total = 1, zones = { [1412] = { n = "1", e = { [key] = value } } } }, 3)
        Loaded("pieces that are no whole numbers", { hinted = true, total = 8, zones = { [1412] = { n = 8, e = {
            [key] = value, [key + 9] = "text", [key + 18] = true, [key + 27] = 1.5, [key + 36] = -1, [key + 45] = 2 ^ 50, [key + 54] = 0 / 0,
            name = value, [1.5] = value, [-9] = value } } } }, 3)
        -- counts that do not fit what is there
        Loaded("a zone that counts too many", { hinted = true, total = 99, zones = { [1411] = Zone(99) } }, 3)
        Loaded("a total that is too small", { hinted = true, total = 0, zones = { [1411] = Zone(), [1413] = Zone() } }, 4)
        Loaded("an empty zone", { hinted = true, total = 0, zones = { [1413] = { n = 0, e = {} } } }, 2)
        assert(ns.db.paths.zones[1413] == nil, "an empty zone is kept")

        -- only the damaged zone: its neighbour keeps every piece as it was, and what was chosen stays chosen
        local healthy = { n = 3, e = { [key] = value, [key + 9] = value + 16384, [key + 18] = value + 5 * 16384 } }
        Loaded("one damaged zone beside a healthy one", { hinted = true, off = nil, total = 3, zones = { [1411] = healthy, [1412] = { n = 7 } } }, 5)
        local z = ns.db.paths.zones[1411]
        assert(z == healthy and z.n == 3 and z.e[key] == value and z.e[key + 9] == value + 16384 and z.e[key + 18] == value + 5 * 16384, "the healthy zone was touched")
        assert(ns.db.paths.hinted == true, "the note is forgotten")
        ns.db.paths = { hinted = true, off = true, total = 1, zones = { [1412] = { n = 0 } } }
        local errorsBefore = #errors
        slash("paths")
        assert(#errors == errorsBefore and ns.PathsEnabled() == false and ns.db.paths.off == true, "damaged data, and the recording that was off is on (or an error)")
        ns.PathsSetEnabled(true)

        -- making room where there is nothing is harmless: a full count over an empty zone
        Loaded("a zone that counts 8000 and holds nothing", { hinted = true, total = 8000, zones = { [1412] = { n = 8000, e = {} } } }, 2)

        -- ... also when a count goes wrong while playing: nothing goes, the counts are put right
        ns.db.paths.total = 30000
        ns.db.paths.zones[1412].n = 8000
        local held = 0
        for _ in pairs(ns.db.paths.zones[1412].e) do held = held + 1 end
        row = row + 2
        local errorsNow = #errors
        W.Start(100, row)
        W.Go(1, 0, 60)
        assert(#errors == errorsNow and not Fits(), "counts gone wrong while playing: " .. tostring(errors[#errors] or Fits()))
        assert(ns.db.paths.zones[1412].n == held + 2, "making room with wrong counts took pieces away: " .. ns.db.paths.zones[1412].n .. " of " .. (held + 2))

        -- once, not at every look: what breaks later in another zone is not looked for while riding
        Loaded("healthy data", { hinted = true, total = 1, zones = { [1411] = Zone() } }, 3)
        ns.db.paths.zones[1413] = { n = 5 }
        row = row + 2
        W.Start(100, row)
        W.Go(1, 0, 60)
        local later = ns.db.paths.zones[1413]
        assert(later and later.n == 5 and later.e == nil, "the saved data is looked through again while riding")
        ns.db.paths.zones[1413] = nil

        -- looking through the most there can be takes a moment, not a second
        local full = { hinted = true, total = 30000, zones = {} }
        for m = 1411, 1414 do
            local e, n = {}, m == 1414 and 6000 or 8000
            for i = 1, n do e[i * 9 + 5] = value end
            full.zones[m] = { n = n, e = e }
        end
        ns.db.paths = full
        local t0 = os.clock()
        local total = ns.PathsCount()
        local took = (os.clock() - t0) * 1000
        assert(total == 30000, "30000 healthy pieces: " .. tostring(total) .. " kept")
        note(("paths: looking through 30000 saved pieces once took %.1f ms"):format(took))
        assert(took < 500, ("looking through the saved paths took %.0f ms"):format(took))
    end)
    W.Done()
    if not ok then error(err, 0) end
end)
step("Paths: a crossing you are carried over is no piece, however far you went yourself before it (v0.1.22 R1 W-M1)", function()
    -- Codex, 13.11.2026 (W-M1): 12 yards on your own feet up to the edge of a
    -- square, then carried across it with no speed of your own - a piece was
    -- kept, as if you had gone there yourself. The rule now:
    --   - a crossing seen while your own speed is 0 is never a piece;
    --   - standing still changes nothing: the way made in the square stays;
    --   - after a carried crossing the next square starts from nothing.
    local W = PathsWorld()
    local ok, err = pcall(function()
        -- Codex's run: from the middle of a square 7, 4, 1 and 0.4 yards at 14, 8, 2 and 1 yards a
        -- second, then one yard across the edge at speed 0
        W.Start(100, 50)
        for _, s in ipairs({ { 7, 14 }, { 4, 8 }, { 1, 2 }, { 0.4, 1 } }) do
            W.speed = s[2]
            W.Step(s[1], 0)
        end
        assert(W.Total() == 0, "test setup: still in the first square")
        W.speed = 0
        W.Step(1, 0)
        assert(select(1, ns.PathsSquare(1412, player.x, player.y)) == 101, "test setup: carried into the next square")
        assert(W.Total() == 0 and W.Piece(100, 50, 1, 0) == nil, "carried across the edge after a way of your own: a piece was kept")
        -- ... and the square you were set down in starts from nothing: the way before does not count for it
        W.speed = 7
        W.Go(1, 0, 3.5 * 7) -- from 0.9 yards into square 101 to 25.4: just across, 24.5 yards made
        local count, cost = W.Piece(101, 50, 1, 0)
        assert(count == 1 and cost <= 1.05, ("the square after a carried crossing: count %s, cost %s (the way before it was counted in)"):format(tostring(count), tostring(cost)))

        -- carried over several squares, walking a little in between: no piece of a carried crossing
        W.Start(100, 54)
        local before = W.Total()
        for _ = 1, 6 do
            W.speed = 7
            W.Step(3.5, 0)  -- a few steps on the deck
            W.speed = 0
            W.Step(12, 0)   -- the boat moves on
            W.Step(12, 0)
        end
        local x = select(1, ns.PathsSquare(1412, player.x, player.y))
        assert(x >= 106, "test setup: carried six squares on, at " .. tostring(x))
        local made = W.Total() - before
        assert(made == 0, "carried over six squares with a few steps of your own: " .. made .. " pieces")

        -- standing still at the edge and then going on yourself is a piece as before
        W.Start(100, 58)
        W.speed = 7
        W.Go(1, 0, 10.5) -- 2 yards from the edge
        W.speed = 0
        advance(20)
        W.speed = 7
        W.Go(1, 0, 7)
        count, cost = W.Piece(100, 58, 1, 0)
        assert(count == 1 and cost <= 1.15, ("a rest before the edge, then across yourself: count %s, cost %s"):format(tostring(count), tostring(cost)))
        -- stopped right behind the edge (speed 0 at the look that sees the new square): not kept -
        -- it cannot be told from being pushed over, and the next ride there keeps it
        W.Start(100, 60)
        W.speed = 7
        W.Go(1, 0, 10.5)
        W.speed = 0
        W.Step(3.5, 0)
        assert(W.Piece(100, 60, 1, 0) == nil, "seen in the next square with no speed: kept")
        W.Start(100, 60)
        W.speed = 7
        W.Go(1, 0, 30)
        assert(W.Piece(100, 60, 1, 0) == 1, "the next ride over the same edge is not kept")
    end)
    W.Done()
    if not ok then error(err, 0) end
end)
step("Paths: the cost of a piece follows what you ride now and never freezes, also after 255 crossings (v0.1.22 R1 W-M2)", function()
    -- Codex, 13.11.2026 (W-M2): 255 crossings at cost 2.00, then 1000 straight
    -- ones at 1.00 - the cost stayed 2.00, every small step of the mean was
    -- rounded away. The rule now: a crossing moves the kept cost towards its
    -- own by the step of the mean ((new - kept) / count, rounded to a
    -- hundredth), and by one hundredth at least whenever the two differ.
    local W = PathsWorld()
    local keepClock = GetTime
    local ok, err = pcall(function()
        local clock = GetTime()
        GetTime = function() return clock end
        local day = math.floor(time() / 86400) - 20454
        local function Value(count, cost) return (cost * 256 + count) * 16384 + day end
        local function Key(tx, ty) return (ty * 1024 + tx) * 9 + 5 end -- (the piece east out of the square)
        local function Look(x, y)
            W.At(x, y)
            clock = clock + 0.5
            ns.PathsLook()
        end
        -- rides east over square 14 of the row `times` times, `per` yards forward a look (the way made
        -- is the speed x half a second a look: at 25 yards a second 12.5 forward is straight, cost 1.00)
        local function Cross(row, times, per)
            per = per or 12.5
            for _ = 1, times do
                clock = clock + 10
                local x, y = 337.5, row * 25 + 12.5
                Look(x, y)
                while x < 380 do
                    x = x + per
                    Look(x, y)
                end
            end
        end
        local function Cost(row) return select(2, ns.PathsPiece(1412, 14, row, 1, 0)) end
        local function Count(row) return (ns.PathsPiece(1412, 14, row, 1, 0)) end
        W.speed = 25

        -- test setup: a straight crossing costs exactly 1.00, one at half the pace forward 2.00
        Cross(1, 1)
        assert(Count(1) == 1 and Cost(1) == 1, "test setup: a straight crossing costs " .. tostring(Cost(1)))
        Cross(2, 1, 6.25)
        assert(Cost(2) == 2, "test setup: twice the way costs " .. tostring(Cost(2)))

        -- Codex's case: 255 crossings at 2.00 are kept, then straight ones
        ns.db.paths = { hinted = true, total = 1, zones = { [1412] = { n = 1, e = { [Key(14, 10)] = Value(255, 200) } } } }
        assert(Count(10) == 255 and Cost(10) == 2, "test setup: a piece crossed 255 times at 2.00")
        Cross(10, 1)
        assert(Cost(10) < 2, "after 255 crossings at 2.00 one at 1.00 leaves the cost at " .. Cost(10))
        Cross(10, 49)
        assert(Count(10) == 255, "the count went past 255")
        assert(math.abs(Cost(10) - 1.5) < 0.005, ("50 straight crossings after 255 at 2.00: cost %.2f, want 1.50"):format(Cost(10)))
        Cross(10, 50)
        assert(Cost(10) == 1, ("100 straight crossings after 255 at 2.00: cost %.2f, want 1.00"):format(Cost(10)))
        Cross(10, 20)
        assert(Cost(10) == 1, "the cost went past what is ridden: " .. Cost(10))
        -- ... and up again the same way
        Cross(10, 30, 6.25)
        assert(math.abs(Cost(10) - 1.3) < 0.005, ("30 crossings at 2.00 after that: cost %.2f, want 1.30"):format(Cost(10)))

        -- a small difference is not lost before the count is full either: 10 crossings at 1.00, then 1.04
        ns.db.paths = { hinted = true, total = 1, zones = { [1412] = { n = 1, e = { [Key(14, 12)] = Value(10, 100) } } } }
        W.speed = 26 -- (26 yards made for the 25 forward)
        Cross(12, 1)
        local first = Cost(12)
        assert(first == 1.01, "a crossing at 1.04 after ten at 1.00 leaves the cost at " .. first)
        Cross(12, 5)
        assert(Count(12) == 16 and Cost(12) == 1.04, ("six crossings at 1.04 after ten at 1.00: cost %.2f, want 1.04"):format(Cost(12)))
        W.speed = 25

        -- with few crossings it is the plain mean: 2.00 and 1.00 are 1.50, a third at 1.00 makes 1.33
        Cross(14, 1, 6.25)
        Cross(14, 1)
        assert(Cost(14) == 1.5, "2.00 and 1.00: " .. Cost(14))
        Cross(14, 1)
        assert(math.abs(Cost(14) - 1.33) < 0.006, "2.00, 1.00, 1.00: " .. Cost(14))
        -- the step is never larger than the difference, and the cost stays between 1.00 and 10.23
        ns.db.paths = { hinted = true, total = 2, zones = { [1412] = { n = 2, e = { [Key(14, 16)] = Value(1, 101), [Key(14, 18)] = Value(255, 1023) } } } }
        Cross(16, 1)
        assert(Cost(16) == 1, "1.01 and 1.00 made " .. Cost(16))
        Cross(18, 1, 0.5)
        assert(Cost(18) == 10.23, "a cost over the top made " .. Cost(18))
    end)
    GetTime = keepClock
    W.Done()
    if not ok then error(err, 0) end
end)
step("/gcr paths: in every language the number of pieces stands with the pieces and the number of zones with the zones (v0.1.22 R1 W-M3)", function()
    -- Codex, 13.11.2026 (W-M3): the Korean line said "100 zones, 1 path
    -- piece" for 100 pieces in one zone - the sentence named the first number
    -- as zones, the code hands the pieces first. A check with the same
    -- placeholders cannot see that; this one uses different numbers and the
    -- words of each language.
    local KEY = "Paths: recording is %s. %d path pieces in %d zones (at most %d), about %d KB in the saved data. Only on this computer."
    local words = {
        enUS = { "path pieces", "zones" }, deDE = { "Wegstücke", "Zonen" }, esES = { "tramos", "zonas" }, frFR = { "tronçons", "zones" },
        itIT = { "tratti", "zone" }, koKR = { "길 조각", "구역", true }, ptBR = { "trechos", "zonas" }, ruRU = { "Отрезков пути", "зон", true },
        zhCN = { "段路径", "个区域" }, zhTW = { "段路徑", "個區域" },
    }
    local PIECES, ZONES, MOST, KB = 4111, 37, 30000, 152
    local function Check(code, text)
        local w = words[code]
        assert(w, "no words for " .. code)
        local line = text:format("ON", PIECES, ZONES, MOST, KB)
        local function At(what)
            local from, to = line:find(what, 1, true)
            assert(from, code .. ": \"" .. what .. "\" is not in the line: " .. line)
            return { from, to }
        end
        -- the order in the line: "4111 pieces ... 37 zones", or (w[3]) "pieces 4111 ... zones 37"
        local pieces, zones, pWord, zWord = At(tostring(PIECES)), At(tostring(ZONES)), At(w[1]), At(w[2])
        local order = w[3] and { pWord, pieces, zWord, zones } or { pieces, pWord, zones, zWord }
        for i = 1, 3 do
            assert(order[i][2] < order[i + 1][1], code .. ": the numbers of pieces and zones do not stand with their words: " .. line)
        end
        -- the limit is a number of pieces and comes third, the size last
        assert(At(tostring(MOST))[1] > zones[1] and At(tostring(KB))[1] > At(tostring(MOST))[1], code .. ": the limit or the size is out of place: " .. line)
    end
    Check("enUS", KEY)
    for _, code in ipairs({ "deDE", "esES", "frFR", "itIT", "koKR", "ptBR", "ruRU", "zhCN", "zhTW" }) do
        local text = ns.Locales[code] and ns.Locales[code][KEY]
        assert(text, "no " .. code .. " text for the /gcr paths line")
        Check(code, text)
    end
    -- every other new text of 0.1.22 has one number at most: nothing there to swap
    for _, key in ipairs({ "  ... and %d more zones", "Recorded paths deleted (%d path pieces). Your nodes and everything else are untouched.",
        "This deletes the %d recorded path pieces and nothing else. To do it: /gcr paths clear yes" }) do
        local _, n = key:gsub("%%d", "")
        assert(n == 1, "test setup: " .. key)
    end
    -- (that the command hands the pieces first and the zones second is checked in the W7 step: 6 pieces, 2 zones)
end)
step("Paths: after more than 2 seconds without a look no piece is made, also into the square next door (v0.1.22 R1, gap)", function()
    -- Codex, 13.11.2026: with the check for a gap of more than 2 seconds
    -- taken out, every step stayed green - a loading screen (the event) and a
    -- jump over two squares were tested, the gap itself was not. Here: the
    -- game stands still for a moment (a hitch, a loading screen without its
    -- event), and you are seen again in the very next square.
    local W = PathsWorld()
    local keepClock = GetTime
    local ok, err = pcall(function()
        local clock = GetTime()
        GetTime = function() return clock end
        W.speed = 25
        local function Look(x, y, after)
            W.At(x, y)
            clock = clock + (after or 0.5)
            ns.PathsLook()
        end
        local function Piece(tx, row) return (ns.PathsPiece(1412, tx, row, 1, 0)) end
        -- 20 yards made in square 12 (300-325), then seen in square 13 - `gap` seconds after the last look
        local function Ride(row, gap)
            local y = row * 25 + 12.5
            clock = clock + 10
            Look(302, y)
            Look(312, y)
            Look(322, y)
            Look(327, y, gap)
            return Piece(12, row)
        end
        assert(Ride(1, 0.5) == 1, "test setup: half a second later in the next square is a piece")
        assert(Ride(2, 2) == 1, "exactly 2 seconds between two looks is still a piece")
        assert(Ride(3, 2.5) == nil, "2.5 seconds without a look, then the next square: a piece was made")
        assert(Ride(4, 30) == nil, "30 seconds without a look, then the next square: a piece was made")
        -- ... and after the gap everything starts anew: the way made before it is not counted in
        local y = 5 * 25 + 12.5
        clock = clock + 10
        W.speed = 10
        Look(302, y) Look(307, y) Look(312, y) -- 10 yards made in square 12: not enough for a piece
        Look(318, y, 5)                         -- a gap, still in square 12
        Look(322, y)                            -- (seen again: a new start)
        Look(327, y)                            -- across with 5 yards made since the gap
        assert(Piece(12, 5) == nil, "the way made before a gap was counted in after it")
        -- (without the gap the same looks are a piece: 15 yards made)
        clock = clock + 10
        y = 7 * 25 + 12.5
        Look(302, y) Look(307, y) Look(312, y) Look(318, y) Look(322, y) Look(327, y)
        assert(Piece(12, 7) == 1, "test setup: the same looks without a gap are a piece")
        W.speed = 25
        -- a clock that goes backwards makes nothing either. (A tenth of a
        -- second only, and after 25 yards made: going back takes way off
        -- again, and with too little left the rule for the way made alone
        -- already makes no piece - 2.5 yards off 25 leave 22.5, enough.)
        clock = clock + 10
        y = 6 * 25 + 12.5
        Look(302, y) Look(308, y) Look(315, y) Look(322, y) -- (the first look after the pause is the start, the second the start in the square)
        Look(327, y, -0.1)
        assert(Piece(12, 6) == nil, "the clock went back and a piece was made")
    end)
    GetTime = keepClock
    W.Done()
    if not ok then error(err, 0) end
end)
step("Sharing: an answer has two nodes at least, and two more than the asker knows - a single node is left to the harvest (v0.1.22 R1 S-M2)", function()
    -- Codex, 13.11.2026 (S-M2): eight players with one new node each all
    -- answered one question - a message with one node does not count as an
    -- answer for the others (it looks like a harvest), so nobody stopped.
    -- Sven, 13.11.2026 (E1): who could add only one node does not answer; the
    -- node comes with its next harvest. So every answer can be counted: its
    -- first packet has two nodes or more.
    local saved = ns.db.sync.enabled
    slash("sync on")
    advance(700)
    local zones = {}
    local function Ask(mapID, own, theirs, long)
        zones[#zones + 1] = mapID
        local list = {}
        for i = 1, own do
            -- (long: the longest a node can be in a message - ten digits of an id and of an item)
            list[i] = { id = long and ("o42949%05d"):format(i) or ("o98" .. (1000 + i)), name = "X", type = "herb", x = 0.9 + i / 10000, y = 0.9 + i / 10000,
                count = 1, last = 1, item = long and 2147483647 or 2447 }
        end
        ns.db.nodes[mapID] = list
        ns.NotifyNodesChanged()
        local from = #sentMessages
        S22Msg(("Q:%d:%d"):format(mapID, theirs), "Asker" .. mapID .. "-Realm")
        advance(60)
        local packets = {}
        for i = from + 1, #sentMessages do
            if sentMessages[i]:find("^N:" .. mapID .. ";") then
                local _, k = sentMessages[i]:gsub(";", ";")
                packets[#packets + 1] = k
            end
        end
        return packets
    end
    local function Sum(packets) local n = 0 for _, k in ipairs(packets) do n = n + k end return n end
    local ok, err = pcall(function()
        local cases = {
            -- { own nodes, the asker's, nodes expected in the answer }
            { 1, 0, 0 },  -- one node: no answer
            { 2, 0, 2 },  -- two: an answer
            { 2, 1, 0 },  -- one more than he knows: no answer
            { 3, 1, 3 },  -- two more
            { 3, 2, 0 },
            { 4, 2, 4 },
            { 5, 3, 0 },  -- (as before: he knows 3, so 3 more are wanted)
            { 6, 3, 6 },
        }
        for i, c in ipairs(cases) do
            local packets = Ask(1540 + i, c[1], c[2])
            assert(Sum(packets) == c[3], ("we know %d, the asker %d: %d nodes sent, want %d"):format(c[1], c[2], Sum(packets), c[3]))
        end
        -- the first packet of every answer has two nodes or more - whatever the size, also with the longest nodes
        for own = 2, 26 do
            for _, long in ipairs({ false, true }) do
                local packets = Ask(1560 + own * 2 + (long and 1 or 0), own, 0, long)
                assert(Sum(packets) == own, ("%d nodes known (%s): %d sent"):format(own, long and "long" or "short", Sum(packets)))
                assert(packets[1] >= 2, ("%d nodes known (%s): the first packet has %d"):format(own, long and "long" or "short", packets[1]))
            end
        end
    end)
    for _, mapID in ipairs(zones) do ns.db.nodes[mapID] = nil end
    ns.NotifyNodesChanged()
    if not saved then slash("sync off") end
    if not ok then error(err, 0) end
end)
step("Sharing: when our own packet does not come back in time, we go on - and stop only for three who went on too and come first by name (v0.1.22 R1 S-M1)", function()
    -- Codex, 13.11.2026 (S-M1): eight players who know the same 120 nodes
    -- start at the same moment, and nobody hears his own packet. Each heard
    -- three others before his second packet and stopped: 8 packets, 9 of 120
    -- nodes learned, no answer. The rule without the own packet back in time:
    --   - the second packet goes out anyway;
    --   - from then on we stop only when three OTHERS who went past their
    --     first packet too come before us by name. Who only sent one packet
    --     stops nobody - he may have stopped himself.
    -- The one whose name comes first never stops, so one answer always arrives.
    -- And with the own packet back in time, three ahead of us are no reason to
    -- stop for good either: we wait four seconds for their second packets.
    local saved = ns.db.sync.enabled
    slash("sync on")
    fire("PLAYER_LOGIN")
    advance(700)
    local me = UnitName("player")
    assert(me == "Test Player", "test setup: the names below are chosen around \"Test Player\", this is " .. tostring(me))
    local zones = {}
    local function Start(mapID)
        zones[#zones + 1] = mapID
        S22Zone(mapID, 100)
        local from = #sentMessages
        S22Msg(("Q:%d:0"):format(mapID), "Asker-Realm")
        return from
    end
    -- until `count` of our packets are out
    local function Packets(mapID, from, count)
        for _ = 1, 300 do
            local messages, _, first = S22Sent(mapID, from)
            if messages >= count then return first end
            advance(0.2)
        end
        error("zone " .. mapID .. ": our packet " .. count .. " never went out", 0)
    end
    local function Rest(mapID, from)
        advance(60)
        local messages, nodes = S22Sent(mapID, from)
        return messages, nodes
    end
    local ok, err = pcall(function()
        -- three others answer right after our first packet and then stop (as all eight did): we finish
        local from = Start(1601)
        Packets(1601, from, 1)
        for k = 1, 3 do S22Other(1601, "Ahead" .. k .. "-Realm", 8) end
        local messages, nodes = Rest(1601, from)
        assert(nodes == 100, ("no echo, three others sent one packet each: we sent %d packets with %d of 100 nodes"):format(messages, nodes))

        -- three others go on (a second packet each) and come before us by name: we stop after our second packet
        from = Start(1602)
        Packets(1602, from, 1)
        for k = 1, 3 do S22Other(1602, "Ahead" .. k .. "-Realm", 8) end
        for k = 1, 3 do S22Other(1602, "Ahead" .. k .. "-Realm", 8) end
        messages = Rest(1602, from)
        assert(messages == 2, "no echo, three who went on come first by name: " .. messages .. " packets, want 2")
        -- ... and that question is not answered again right away
        S22Msg("Q:1602:0", "Asker Two-Realm")
        advance(60)
        assert(S22Sent(1602, from) == 2, "a stopped answer was started again within the five minutes")

        -- the same three with names after ours: they stop for us, not we for them
        from = Start(1603)
        Packets(1603, from, 1)
        for _ = 1, 2 do for k = 1, 3 do S22Other(1603, "Zed" .. k .. "-Realm", 8) end end
        messages, nodes = Rest(1603, from)
        assert(nodes == 100, "no echo, three who went on come after us by name: " .. nodes .. " of 100 nodes")

        -- two before us and five after us: we are the third
        from = Start(1604)
        Packets(1604, from, 1)
        for _ = 1, 2 do
            for k = 1, 2 do S22Other(1604, "Ahead" .. k .. "-Realm", 8) end
            for k = 1, 5 do S22Other(1604, "Zed" .. k .. "-Realm", 8) end
        end
        messages, nodes = Rest(1604, from)
        assert(nodes == 100, "no echo, two who went on before us by name: " .. nodes .. " of 100 nodes")

        -- one player with many packets is one player
        from = Start(1605)
        Packets(1605, from, 1)
        for _ = 1, 5 do S22Other(1605, "Ahead1-Realm", 8) S22Other(1605, "Ahead2-Realm", 8) end
        messages, nodes = Rest(1605, from)
        assert(nodes == 100, "no echo, two players with five packets each stopped us (" .. nodes .. " of 100 nodes)")

        -- a second packet may be a short one (the rest of a small answer): it still tells that he went on
        from = Start(1606)
        Packets(1606, from, 1)
        for k = 1, 3 do S22Other(1606, "Ahead" .. k .. "-Realm", 8) end
        for k = 1, 3 do S22Other(1606, "Ahead" .. k .. "-Realm", 1) end
        messages = Rest(1606, from)
        assert(messages == 2, "no echo, three went on with a short second packet: " .. messages .. " packets, want 2")
        -- ... but a single node from somebody who never answered is a harvest
        from = Start(1607)
        Packets(1607, from, 1)
        for _ = 1, 2 do for k = 1, 3 do S22Other(1607, "Ahead" .. k .. "-Realm", 1) end end
        messages, nodes = Rest(1607, from)
        assert(nodes == 100, "no echo, three players with two harvests each stopped us (" .. nodes .. " of 100 nodes)")

        -- they go on later, when we are in the middle: we stop then
        from = Start(1608)
        Packets(1608, from, 1)
        for k = 1, 3 do S22Other(1608, "Ahead" .. k .. "-Realm", 8) end
        Packets(1608, from, 5)
        for k = 1, 3 do S22Other(1608, "Ahead" .. k .. "-Realm", 8) end
        messages = Rest(1608, from)
        assert(messages >= 5 and messages <= 6, "no echo, three went on after our fifth packet: " .. messages .. " packets, want 5 or 6")

        -- the echo comes late, after our second packet: it changes nothing any more
        -- (three first packets were ahead of ours in the channel - their senders may all have stopped)
        from = Start(1609)
        local first = Packets(1609, from, 1)
        for k = 1, 3 do S22Other(1609, "Ahead" .. k .. "-Realm", 8) end
        Packets(1609, from, 2)
        S22Msg(first, me)
        messages, nodes = Rest(1609, from)
        assert(nodes == 100, "a late echo with three first packets ahead stopped us (" .. nodes .. " of 100 nodes)")
        -- ... and a late echo does not put us out of reach of the rule either
        from = Start(1610)
        first = Packets(1610, from, 1)
        Packets(1610, from, 2)
        S22Msg(first, me)
        for _ = 1, 2 do for k = 1, 3 do S22Other(1610, "Ahead" .. k .. "-Realm", 8) end end
        messages = Rest(1610, from)
        assert(messages >= 2 and messages <= 3, "a late echo, then three who went on come first by name: " .. messages .. " packets, want 2 or 3")

        -- with the echo in time everything is as it was: our place in the channel counts, names do not
        from = Start(1611)
        first = Packets(1611, from, 1)
        for k = 1, 2 do S22Other(1611, "Ahead" .. k .. "-Realm", 8) end
        S22Msg(first, me)
        for _ = 1, 3 do for k = 1, 6 do S22Other(1611, "Ahead" .. k .. "-Realm", 8) end end
        messages, nodes = Rest(1611, from)
        assert(nodes == 100, "echo in time, two ahead, six who go on behind us: " .. nodes .. " of 100 nodes")
        from = Start(1612)
        first = Packets(1612, from, 1)
        for k = 1, 3 do S22Other(1612, "Zed" .. k .. "-Realm", 8) end
        S22Msg(first, me)
        advance(1.5)
        for k = 1, 3 do S22Other(1612, "Zed" .. k .. "-Realm", 8) end
        messages = Rest(1612, from)
        assert(messages == 1, "echo in time, three ahead (names after ours) who go on: " .. messages .. " packets, want 1")

        -- three were ahead when our packet came back, but they do not go on (each may have counted
        -- three ahead of himself - the echo came later than the others' packets): we waited, now we go on
        from = Start(1613)
        first = Packets(1613, from, 1)
        for k = 1, 3 do S22Other(1613, "Ahead" .. k .. "-Realm", 8) end
        S22Msg(first, me)
        advance(3)
        assert(S22Sent(1613, from) == 1, "three were ahead: we did not wait to see whether they go on")
        advance(3)
        assert(S22Sent(1613, from) > 1, "three were ahead and none went on: 6 s later we still wait (the wait is 4 s)")
        messages, nodes = Rest(1613, from)
        assert(nodes == 100, ("three were ahead and none went on: we sent %d packets with %d of 100 nodes"):format(messages, nodes))
        -- ... two of the three go on: still fewer than three answers, so ours is wanted
        from = Start(1614)
        first = Packets(1614, from, 1)
        for k = 1, 3 do S22Other(1614, "Ahead" .. k .. "-Realm", 8) end
        S22Msg(first, me)
        advance(1.5)
        for k = 1, 2 do S22Other(1614, "Ahead" .. k .. "-Realm", 8) end
        messages, nodes = Rest(1614, from)
        assert(nodes == 100, "three were ahead, two went on: " .. nodes .. " of 100 nodes")
        -- ... and when the third goes on after all while we are at it, the names decide: he comes first
        from = Start(1615)
        first = Packets(1615, from, 1)
        for k = 1, 3 do S22Other(1615, "Ahead" .. k .. "-Realm", 8) end
        S22Msg(first, me)
        advance(1.5)
        for k = 1, 2 do S22Other(1615, "Ahead" .. k .. "-Realm", 8) end
        Packets(1615, from, 4)
        S22Other(1615, "Ahead3-Realm", 8)
        messages = Rest(1615, from)
        assert(messages >= 4 and messages <= 5, "three before us by name went on in the end: " .. messages .. " packets, want 4 or 5")
        -- while an answer waits, a harvest goes out at once, and a second question for the zone starts nothing
        from = Start(1616)
        first = Packets(1616, from, 1)
        for k = 1, 3 do S22Other(1616, "Ahead" .. k .. "-Realm", 8) end
        S22Msg(first, me)
        advance(1.3)
        S22Msg("Q:1616:0", "Asker Three-Realm")
        local harvest = { id = "o1619", name = "Silverleaf", type = "herb", x = 0.32, y = 0.61, count = 1, last = time() }
        table.insert(ns.db.nodes[1412], harvest)
        local mark = #sentMessages
        ns.SyncShare(1412, harvest)
        advance(1.3)
        local out = false
        for i = mark + 1, #sentMessages do if sentMessages[i]:find("^N:1412;o1619,") then out = true end end
        for i, n in ipairs(ns.db.nodes[1412]) do if n == harvest then table.remove(ns.db.nodes[1412], i) break end end
        assert(out and S22Sent(1616, from) == 1, "while an answer waited, the own harvest waited behind it (or the answer went on)")
        messages, nodes = Rest(1616, from)
        assert(nodes == 100, "after the wait the answer has " .. nodes .. " of 100 nodes (a second question started another, or it was lost)")

        -- /gcr perf tells whether our own messages come back at all (for the live test)
        local function Echo()
            local mark = #log
            slash("perf")
            for i = mark + 1, #log do
                local back, sent = log[i]:match("own messages heard back (%d+) of (%d+) send attempts")
                if back then return tonumber(back), tonumber(sent) end
            end
            error("/gcr perf does not say how many own messages were heard back", 0)
        end
        local back0, sent0 = Echo()
        local node = { id = "o1619", name = "Silverleaf", type = "herb", x = 0.31, y = 0.62, count = 1, last = time() }
        table.insert(ns.db.nodes[1412], node)
        local before = #sentMessages
        ns.SyncShare(1412, node)
        advance(5)
        for i, n in ipairs(ns.db.nodes[1412]) do if n == node then table.remove(ns.db.nodes[1412], i) break end end
        local out = #sentMessages - before
        assert(out >= 1, "test setup: the harvest was not sent")
        local back1, sent1 = Echo()
        assert(sent1 == sent0 + out and back1 == back0, ("a harvest sent, nothing back: heard back %d of %d, before %d of %d"):format(back1, sent1, back0, sent0))
        S22Msg(sentMessages[#sentMessages], me)
        local back2, sent2 = Echo()
        assert(back2 == back0 + 1 and sent2 == sent1, ("our message came back: heard back %d of %d"):format(back2, sent2))
        -- somebody else's message is not ours
        S22Other(1699, "Stranger-Realm", 1)
        assert(Echo() == back2, "a stranger's message was counted as ours coming back")
    end)
    for _, mapID in ipairs(zones) do ns.db.nodes[mapID] = nil end
    ns.NotifyNodesChanged()
    if not saved then slash("sync off") end
    advance(120)
    if not ok then error(err, 0) end
end)
step("Sharing: the chat line turned off and on again within seconds - the line that waited is gone at once (v0.1.22 R1 S-N1)", function()
    -- Codex, 13.11.2026 (S-N1): turning the line off did not drop the line
    -- on its way - its timer only asked the switch when its time had come. Off
    -- after 5 s and on again a second later: the old line came. Now the
    -- switch itself throws the waiting line away.
    local db = ns.db.sync
    local saved = { on = db.announceOn, off = db.announceOff, enabled = db.enabled }
    local win = _G.GathercraftOptions
    local wasOpen = win:IsShown()
    slash("sync on")
    local zone = ns.GetZoneName(1412)
    local function Lines(count)
        local n, text = 0, (ns.L["%d spots shared by other players added (%s)."]):format(count, zone)
        for _, l in ipairs(log) do if l:find(text, 1, true) then n = n + 1 end end
        return n
    end
    local function Any()
        local n = 0
        for k = 1, 9 do n = n + Lines(k) end
        return n
    end
    local spot = 0
    local function Arrive()
        spot = spot + 1
        local before = select(2, ns.SyncSummary())
        fire("CHAT_MSG_ADDON", "Gathercraft", ("N:1412;o1622,h,%d,%d,2450"):format(2300 + spot * 47, 7300 + spot * 29), "GUILD", "Guildie Ten")
        assert(select(2, ns.SyncSummary()) > before, "test setup: the spot was not taken")
    end
    local ok, err = pcall(function()
        if not wasOpen then ns.ToggleOptions() end
        ns.ShowOptionsSection("sync")
        local label
        for _, f in ipairs(allFrames) do
            if f.__kind == "FontString" and f.__text == ns.L["Tell me in chat when spots of other players arrive"] then label = f end
        end
        local box = label and ((label.__pts.TOPLEFT and label.__pts.TOPLEFT[1]) or (label.__pts.LEFT and label.__pts.LEFT[1]))
        assert(box and box.__kind == "CheckButton" and box.__scripts.OnClick, "test setup: the option's switch")
        local function Switch(on) box:SetChecked(on) box.__scripts.OnClick(box) end
        advance(400)
        Switch(true)
        assert(db.announceOn == true, "test setup: the line is on")

        -- two spots, off after 5 s, on again a second later: nothing is said, however long we wait
        local n0 = Any()
        Arrive() Arrive()
        advance(5)
        Switch(false)
        advance(1)
        Switch(true)
        advance(400)
        assert(Any() == n0, "off and on again within a second: the line that waited came anyway")

        -- ... and a spot that arrives after it was turned on again gets a line of its own, at its own time
        Arrive() Arrive() Arrive()
        advance(5)
        Switch(false)
        advance(1)
        Switch(true)
        advance(1)
        local one = Lines(1)
        Arrive()            -- 7 s after the three: the old line would be due 13 s from here
        advance(15)
        assert(Any() == n0, "the new spot was said at the old line's time")
        advance(7)
        assert(Lines(1) == one + 1 and Any() == n0 + 1, "after off and on the next spot is said as one spot, once - not with the old ones")

        -- turned off and left off: nothing comes
        Arrive()
        advance(5)
        Switch(false)
        advance(400)
        assert(Any() == n0 + 1, "turned off: the line came")
    end)
    db.announceOn, db.announceOff, db.enabled = saved.on, saved.off, saved.enabled
    if not wasOpen then ns.ToggleOptions() end
    advance(400)
    if not ok then error(err, 0) end
end)
step("/gcr perf: the words say what is counted - send attempts, nodes announced before any check, time in the two handlers (v0.1.22 R1 S-N2)", function()
    -- Codex, 13.11.2026 (S-N2): "sync code" is not all the work of sharing
    -- (packing an answer runs in a timer of its own), "out" counts attempts,
    -- not deliveries, and "nodes read" counts what a message announces before
    -- any of it is checked. The line says so now. English only, as before.
    local db = ns.db.sync
    local saved = { enabled = db.enabled, pending = db.pending, counts = db.counts, send = C_ChatInfo.SendAddonMessage }
    db.pending, db.counts = {}, nil
    slash("sync on")
    advance(700)
    local function Perf()
        local mark = #log
        slash("perf")
        for i = mark + 1, #log do if log[i]:find("^PRINT") and log[i]:find("perf (", 1, true) then return log[i] end end
        error("/gcr perf printed nothing", 0)
    end
    local function Number(line, pattern)
        local v = line:match(pattern)
        assert(v, "not in the line (" .. pattern .. "): " .. line)
        return tonumber(v)
    end
    local ok, err = pcall(function()
        advance(60 - GetTime() % 60 + 1)
        -- three entries that are no nodes at all, and two real ones: five were announced
        fire("CHAT_MSG_ADDON", "Gathercraft", "N:1412;rubbish;more,rubbish;;o9611,h,1000,2000,2447;o9612,h,1100,2100,2447", "CHANNEL", "Stranger-Realm", nil, nil, nil, "GathercraftSync")
        -- a send the client refuses is an attempt all the same
        local tries = 0
        C_ChatInfo.SendAddonMessage = function() tries = tries + 1 error("refused") end
        local node = { id = "o1619", name = "Silverleaf", type = "herb", x = 0.36, y = 0.63, count = 1, last = time() }
        table.insert(ns.db.nodes[1412], node)
        ns.SyncShare(1412, node)
        advance(10)
        for i, n in ipairs(ns.db.nodes[1412]) do if n == node then table.remove(ns.db.nodes[1412], i) break end end
        C_ChatInfo.SendAddonMessage = saved.send
        assert(tries > 0, "test setup: nothing was tried")
        advance(60 - GetTime() % 60 + 1)
        local line = Perf()
        assert(Number(line, "sync messages received (%d+)") == 1, "received: " .. line)
        assert(Number(line, "send attempts (%d+)") == tries, "send attempts, want " .. tries .. ": " .. line)
        assert(Number(line, "nodes announced (%d+) %(before any check%)") == 5, "nodes announced, want 5: " .. line)
        assert(Number(line, "time in the receive and send handlers ([%d.]+) ms") >= 0, "time: " .. line)
        assert(line:find("own messages heard back %d+ of %d+ send attempts since login"), "heard back: " .. line)
        -- the old words, which said more than is measured, are gone
        for _, old in ipairs({ "sync code", "nodes read", "messages in ", ", out " }) do
            assert(not line:find(old, 1, true), "the line still says \"" .. old .. "\": " .. line)
        end
    end)
    C_ChatInfo.SendAddonMessage = saved.send
    db.pending, db.counts = saved.pending, saved.counts
    if not saved.enabled then slash("sync off") end
    advance(120)
    if not ok then error(err, 0) end
end)
step("/gcr perf: after minutes in which nothing at all ran, the last full minute is a quiet one - not the busy one again (v0.1.22 R1, S3)", function()
    -- Codex, 13.11.2026: the branch for "the minute before was skipped" can be
    -- reached outside the game after all - the clock goes on 125 s while not
    -- even the send ticker runs (a loading screen, a frozen client). The step
    -- of S3 could not show it: there the ticker touches the counters every
    -- 1.2 s, so no minute is ever skipped.
    local db = ns.db.sync
    local saved = { enabled = db.enabled, pending = db.pending, counts = db.counts, clock = GetTime }
    db.pending, db.counts = {}, nil
    slash("sync on")
    advance(700)
    local function Perf()
        local mark = #log
        slash("perf")
        for i = mark + 1, #log do if log[i]:find("^PRINT") and log[i]:find("perf (", 1, true) then return log[i] end end
        error("/gcr perf printed nothing", 0)
    end
    local function Received(line) return tonumber(line:match("sync messages received (%d+)")) end
    local ok, err = pcall(function()
        -- to the start of a minute, then five messages in it
        advance(60 - GetTime() % 60 + 1)
        for k = 1, 5 do
            fire("CHAT_MSG_ADDON", "Gathercraft", ("N:1698;o95%d,h,%d,%d,2447"):format(1000 + k, 1000 + k * 7, 2000 + k * 5), "CHANNEL", "Stranger" .. k .. "-Realm", nil, nil, nil, "GathercraftSync")
        end
        advance(2)
        -- the clock jumps on by 125 s, nothing ran in between
        local jump = 125
        GetTime = function() return saved.clock() + jump end
        local line = Perf()
        assert(line:find("last full minute", 1, true), "not the last full minute: " .. line)
        assert(Received(line) == 0, "125 s later, nothing ran in between: the busy minute is shown again: " .. line)
        -- one minute on exactly, nothing ran: the minute before is the busy one, and it is shown
        GetTime = saved.clock
        advance(60 - GetTime() % 60 + 1)
        for k = 1, 3 do
            fire("CHAT_MSG_ADDON", "Gathercraft", ("N:1698;o95%d,h,%d,%d,2447"):format(2000 + k, 1100 + k * 7, 2100 + k * 5), "CHANNEL", "Other" .. k .. "-Realm", nil, nil, nil, "GathercraftSync")
        end
        jump = 60
        GetTime = function() return saved.clock() + jump end
        line = Perf()
        assert(Received(line) == 3, "one minute later the minute before is not shown: " .. line)
    end)
    GetTime = saved.clock
    db.pending, db.counts = saved.pending, saved.counts
    if not saved.enabled then slash("sync off") end
    advance(180)
    if not ok then error(err, 0) end
end)
step("Settings: no game setting is changed in combat - the gathering help and the bobber settings follow at the end of the fight (v0.1.22 R1, combat)", function()
    -- Sven, 13.11.2026 (live, 0.1.22 a62cefe): the questing mode switched on
    -- in a fight - "[ADDON_ACTION_BLOCKED] AddOn 'Gathercraft' tried to call
    -- the protected function 'SetCVar()'". The client refuses SetCVar in
    -- combat, and pcall does not catch that: it is no Lua error, the call is
    -- just not done and the game shows the message. So in combat nothing is
    -- set and nothing is put back; what is wanted at the end of the fight is
    -- done then, once.
    local saved = { get = GetCVar, set = SetCVar, set2 = SetOverrideBinding, clear = ClearOverrideBindings, combat = InCombatLockdown,
        mark = ns.db.gatherMark, key = ns.db.gatherKey, cvars = ns.db.fishingCVars, bobber = ns.db.fishMarkBobber, loud = ns.db.fishLoudSplash,
        map = player.map, x = player.x, y = player.y }
    local YOURS = { SoftTargetInteract = "0", SoftTargetInteractRange = "10", SoftTargetInteractArc = "0", SoftTargetIconGameObject = "0" }
    local OURS = { SoftTargetInteract = "3", SoftTargetInteractRange = "30", SoftTargetInteractArc = "2", SoftTargetIconGameObject = "1" }
    local store = {}
    local fighting = false
    local calls, blocked = 0, 0
    local function Is(want)
        for k, v in pairs(want) do if tonumber(store[k]) ~= tonumber(v) then return false, k .. " is " .. tostring(store[k]) end end
        return true
    end
    local function Fight(on)
        fighting = on
        if not on then fire("PLAYER_REGEN_ENABLED") advance(0.1) end
        calls = 0
    end
    local function Quiet(what)
        assert(blocked == 0, what .. ": SetCVar was called in combat (" .. blocked .. " times) - the game blocks that")
    end
    local function Cast() fire("UNIT_SPELLCAST_CHANNEL_START", "player", "r1c", 7620) end
    local function Reel() fire("UNIT_SPELLCAST_CHANNEL_STOP", "player", "r1c", 7620) advance(1) end
    local ok, err = pcall(function()
        for k, v in pairs(YOURS) do store[k] = v end
        GetCVar = function(k) return store[k] end
        -- as the client: in combat the call is not done, and it is counted
        -- (ADDON_ACTION_BLOCKED); no Lua error
        SetCVar = function(k, v)
            if fighting then blocked = blocked + 1 return end
            calls = calls + 1
            store[k] = tostring(v)
            return true
        end
        SetOverrideBinding = function() end
        ClearOverrideBindings = function() end
        InCombatLockdown = function() return fighting end
        ns.db.fishingCVars, ns.db.fishMarkBobber, ns.db.fishLoudSplash = nil, true, nil
        ns.db.gatherMark, ns.db.gatherKey = true, nil
        player.map, player.x, player.y = 1412, 0.45, 0.72
        if ns.run then ns.StopRun(true) end
        ns.SetQuestMode(false) advance(1)
        assert(Is(YOURS) and ns.db.fishingCVars == nil, "before anything: settings are changed")

        -- (1) the questing mode on in a fight (Sven's find): nothing in the fight, the mark after it
        Fight(true)
        ns.SetQuestMode(true) advance(1)
        Quiet("questing mode on in a fight")
        assert(Is(YOURS), "questing mode on in a fight: a setting changed")
        advance(30) -- (the questing mode's own looks in the fight: nothing either)
        Quiet("the questing mode's looks in a fight")
        Fight(false)
        local fine, why = Is(OURS)
        assert(fine, "after the fight the node is not marked: " .. tostring(why))
        advance(5)
        assert(calls == 0, "after the fight the settings were set again later (" .. calls .. " calls)")

        -- (2) off in a fight: nothing in the fight, everything back after it
        Fight(true)
        ns.SetQuestMode(false) advance(1)
        Quiet("questing mode off in a fight")
        assert(Is(OURS), "questing mode off in a fight: a setting changed")
        Fight(false)
        fine, why = Is(YOURS)
        assert(fine and ns.db.fishingCVars == nil, "after the fight your settings are not back: " .. tostring(why))

        -- (3) on, off, on in one fight: on after it, set once
        Fight(true)
        ns.SetQuestMode(true) advance(1)
        ns.SetQuestMode(false) advance(1)
        ns.SetQuestMode(true) advance(1)
        Quiet("on, off, on in a fight")
        fighting = false
        calls = 0
        fire("PLAYER_REGEN_ENABLED") advance(0.1)
        assert(Is(OURS), "on, off, on in a fight: not on after it")
        assert(calls == 4, "on, off, on in a fight: " .. calls .. " settings set after it, want 4 (each once)")
        advance(5)
        assert(calls == 4, "on, off, on in a fight: set again later")

        -- (4) it was on; off, on, off in one fight: off after it, everything back, each once
        Fight(true)
        ns.SetQuestMode(false) advance(1)
        ns.SetQuestMode(true) advance(1)
        ns.SetQuestMode(false) advance(1)
        Quiet("off, on, off in a fight")
        fighting = false
        calls = 0
        fire("PLAYER_REGEN_ENABLED") advance(0.1)
        assert(Is(YOURS) and ns.db.fishingCVars == nil, "off, on, off in a fight: your settings are not back after it")
        assert(calls == 4, "off, on, off in a fight: " .. calls .. " settings put back, want 4 (each once)")

        -- (5) it was off; on, off in one fight: nothing at all after it
        Fight(true)
        ns.SetQuestMode(true) advance(1)
        ns.SetQuestMode(false) advance(1)
        Quiet("on, off in a fight")
        fighting = false
        calls = 0
        fire("PLAYER_REGEN_ENABLED") advance(0.1)
        assert(calls == 0 and Is(YOURS) and ns.db.fishingCVars == nil, "on, off in a fight: " .. calls .. " settings touched after it")

        -- (6) a setting you changed yourself during the fight stays yours
        ns.SetQuestMode(true) advance(1)
        assert(Is(OURS), "questing mode on outside a fight: not marked")
        Fight(true)
        ns.SetQuestMode(false) advance(1)
        store.SoftTargetInteractRange = "45" -- (the player, in the options)
        Fight(false)
        assert(store.SoftTargetInteractRange == "45", "your own value was overwritten after the fight: " .. tostring(store.SoftTargetInteractRange))
        assert(store.SoftTargetInteract == "0" and ns.db.fishingCVars == nil, "the other settings are not back after the fight")
        store.SoftTargetInteractRange = "10"

        -- (7) a cast in a fight: no setting, no error; the line still out after the fight: the bobber is in reach then
        Fight(true)
        Cast() advance(1)
        Quiet("a cast in a fight")
        assert(Is(YOURS), "a cast in a fight: a setting changed")
        Fight(false)
        assert(Is(OURS), "the line is still out after the fight: the bobber is not in reach")
        Reel()
        assert(Is(YOURS) and ns.db.fishingCVars == nil, "after reeling in your settings are not back")
        -- ... cast and reeled in within the fight: nothing after it
        Fight(true)
        Cast() advance(1)
        Reel()
        Quiet("a cast and its end in a fight")
        fighting = false
        calls = 0
        fire("PLAYER_REGEN_ENABLED") advance(0.1)
        assert(calls == 0 and Is(YOURS), "a cast and its end in a fight: " .. calls .. " settings touched after it")
        -- ... the line out before the fight, in during it: back after it
        Cast() advance(1)
        assert(Is(OURS), "a cast outside a fight: the bobber is not in reach")
        Fight(true)
        Reel()
        Quiet("reeling in during a fight")
        assert(Is(OURS), "reeling in during a fight: a setting changed")
        Fight(false)
        assert(Is(YOURS) and ns.db.fishingCVars == nil, "reeled in during a fight: your settings are not back after it")

        -- (8) the louder splash the same
        ns.db.fishLoudSplash = true
        store.Sound_SFXVolume, store.Sound_MusicVolume, store.Sound_AmbienceVolume = "0.5", "0.4", "0.6"
        Fight(true)
        Cast() advance(1)
        Quiet("a cast with the louder splash in a fight")
        assert(store.Sound_SFXVolume == "0.5" and store.Sound_MusicVolume == "0.4", "the volume changed in a fight")
        Fight(false)
        assert(tonumber(store.Sound_SFXVolume) == 1 and tonumber(store.Sound_MusicVolume) == 0.1, "the splash is not louder after the fight")
        Fight(true)
        Reel()
        Quiet("reeling in with the louder splash in a fight")
        Fight(false)
        assert(store.Sound_SFXVolume == "0.5" and store.Sound_MusicVolume == "0.4" and store.Sound_AmbienceVolume == "0.6",
            "the volume is not back after the fight")
        ns.db.fishLoudSplash = nil

        -- (9) a /reload in a fight with the mark on: nothing is set; the list
        -- is kept, so the settings go back after the fight or at the next login
        ns.SetQuestMode(true) advance(1)
        assert(Is(OURS), "questing mode on: not marked")
        Fight(true)
        local fishFrame
        for f in pairs(eventFrames["PLAYER_LOGOUT"] or {}) do
            if eventFrames["UNIT_SPELLCAST_CHANNEL_STOP"] and eventFrames["UNIT_SPELLCAST_CHANNEL_STOP"][f] then fishFrame = f end
        end
        assert(fishFrame, "the fishing code does not listen to PLAYER_LOGOUT")
        fishFrame.__scripts.OnEvent(fishFrame, "PLAYER_LOGOUT")
        Quiet("a /reload in a fight")
        assert(ns.db.fishingCVars and ns.db.fishingCVars.SoftTargetInteract, "a /reload in a fight: the list of what to put back is gone")
        ns.SetQuestMode(false) advance(1)
        Fight(false)
        assert(Is(YOURS) and ns.db.fishingCVars == nil, "after that fight your settings are not back")
        assert(blocked == 0, "SetCVar was called in combat " .. blocked .. " times")
    end)
    fighting = false
    ns.SetQuestMode(false)
    fire("PLAYER_REGEN_ENABLED") advance(1)
    GetCVar, SetCVar, SetOverrideBinding, ClearOverrideBindings, InCombatLockdown = saved.get, saved.set, saved.set2, saved.clear, saved.combat
    ns.db.gatherMark, ns.db.gatherKey, ns.db.fishingCVars, ns.db.fishMarkBobber, ns.db.fishLoudSplash = saved.mark, saved.key, saved.cvars, saved.bobber, saved.loud
    if ns.StopFishing then ns.StopFishing() end
    player.map, player.x, player.y = saved.map, saved.x, saved.y
    if not ok then error(err, 0) end
end)
step("Crafting: \"Alchimie\" is Alchemy - in the skill list, the skill plan and the profession window (v0.1.22 R2, German client)", function()
    -- CurseForge, 14.11.2026 (Belgeron, German client): the skill plan never
    -- found the Alchemy skill and kept asking to open the profession window.
    -- The game says "Alchimie" in the skill list and the profession window;
    -- Gathercraft knew "Alchemie" and the name of the spell 2259 (here, as in
    -- the German mock: "Alchemie"). Cooking and First Aid were fine - they are
    -- found by their own names (Skills.lua), not through ProfKey.
    local keep = { gp = GetProfessions, gn = GetNumSkillLines, gi = GetSkillLineInfo, debug = ns.db.debug,
        line = GetTradeSkillLine, num = GetNumTradeSkills, info = GetTradeSkillInfo, link = GetTradeSkillItemLink,
        nr = GetTradeSkillNumReagents, ri = GetTradeSkillReagentInfo, rl = GetTradeSkillReagentItemLink, made = GetTradeSkillNumMade }
    local mine = ns.db.recipes[next(ns.db.recipes)]
    local function Copy(x) if type(x) ~= "table" then return x end local c = {} for k, v in pairs(x) do c[k] = Copy(v) end return c end
    local keepAlchemy, keepDB = mine.Alchemy, Copy(ns.db.recipeDB and ns.db.recipeDB.Alchemy)
    local lines = {}
    local function Texts(text)
        for _, o in ipairs(allFrames) do
            local t = o.GetText and o:GetText()
            if type(t) == "string" and o.IsShown and o:IsShown() and t:find(text, 1, true) then return t end
        end
    end
    local function Said(text, from)
        local n = 0
        for i = from or 1, #log do if log[i]:find(text, 1, true) then n = n + 1 end end
        return n
    end
    local ok, err = pcall(function()
        mine.Alchemy = nil -- no profession window seen yet: only the skill list can tell
        GetProfessions = nil
        GetNumSkillLines = function() return #lines end
        GetSkillLineInfo = function(i) return unpack(lines[i]) end
        lines = {
            { "Berufe", true, true }, { "Alchimie", false, nil, 120, 0, 0, 150 }, { "Kräuterkunde", false, nil, 130, 0, 0, 150 },
            { "Sekundäre Fertigkeiten", true, true }, { "Kochkunst", false, nil, 75, 0, 0, 75 },
            { "Waffenfertigkeiten", true, true }, { "Schwerter", false, nil, 300, 0, 0, 300 },
        }
        -- (1) the skill list
        local rank, maxRank = ns.ProfessionRank("Alchemy")
        assert(rank == 120 and maxRank == 150, ("skill line \"Alchimie\": Alchemy at %s/%s, want 120/150"):format(tostring(rank), tostring(maxRank)))
        lines[2][1] = "Alchemie" -- (the spelling known before stays known)
        rank = ns.ProfessionRank("Alchemy")
        assert(rank == 120, "skill line \"Alchemie\": Alchemy at " .. tostring(rank))
        lines[2][1] = "Alchimie"
        -- (2) the skill plan shows it, instead of "open your profession window once"
        ns.ShowSkillPlan("Alchemy") advance(1)
        assert(Texts((ns.L["Your skill: %d / %d"]):format(120, 150)), "the skill plan does not show 120 / 150 for \"Alchimie\"")
        assert(not Texts(ns.L["Your skill: ? (open your profession window once)"]), "the skill plan still asks to open the profession window")
        if _G.GathercraftSkillPlan then _G.GathercraftSkillPlan:Hide() end
        -- (3) the profession window says "Alchimie": its recipes are Alchemy's
        GetTradeSkillLine = function() return "Alchimie", 77, 150 end
        GetNumTradeSkills = function() return 1 end
        GetTradeSkillInfo = function() return "Test Potion R2", "optimal" end
        GetTradeSkillItemLink = function() return "|Hitem:118::|h" end
        GetTradeSkillNumMade = function() return 1, 1 end
        GetTradeSkillNumReagents = function() return 1 end
        GetTradeSkillReagentInfo = function() return "Reagent", 134400, 1, 0 end
        GetTradeSkillReagentItemLink = function() return "|Hitem:2447::|h" end
        fire("TRADE_SKILL_SHOW") advance(1)
        assert(mine.Alchemy and mine.Alchemy.rank == 77, "window \"Alchimie\": not stored as Alchemy (rank " .. tostring(mine.Alchemy and mine.Alchemy.rank) .. ")")
        local n = 0
        for _ in pairs(mine.Alchemy.list or {}) do n = n + 1 end
        assert(n == 1, "window \"Alchimie\": " .. n .. " recipes under Alchemy, want 1")
        assert(not mine.Alchimie and not (ns.db.recipeDB and ns.db.recipeDB.Alchimie), "a profession \"Alchimie\" was stored beside Alchemy")
        lines = {}
        assert(ns.ProfessionRank("Alchemy") == 77, "no skill list: the window's 77 is not the Alchemy skill")
        -- (4) with /gcr debug: a line that looks like a profession but is none
        -- of them is named once per session; nothing without debug
        lines = {
            { "Berufe", true, true }, { "Alchimistik", false, nil, 20, 0, 0, 75 }, { "Kräuterkunde", false, nil, 130, 0, 0, 150 },
            { "Waffenfertigkeiten", true, true }, { "Schwerter", false, nil, 300, 0, 0, 300 },
        }
        local mark = #log
        ns.db.debug = nil
        ns.ProfessionRank("Alchemy")
        assert(Said("profession name not recognised", mark + 1) == 0, "a debug line without debug")
        ns.db.debug = true
        ns.ProfessionRank("Alchemy") ns.ProfessionRank("Tailoring")
        assert(Said("profession name not recognised: Alchimistik", mark + 1) == 1, "the unknown profession line is not named once: "
            .. Said("profession name not recognised: Alchimistik", mark + 1))
        assert(Said("Schwerter", mark + 1) == 0, "a weapon skill named as a profession")
        assert(Said("Kräuterkunde", mark + 1) == 0, "Herbalism named as not recognised")
        lines[2][1] = "Alchimie"
        ns.ProfessionRank("Alchemy")
        assert(Said("profession name not recognised: Alchimie", mark + 1) == 0, "\"Alchimie\" named as not recognised")
        -- (5) /gcr crafttest says what each line of the skill list is read as (to send us)
        lines = {
            { "Berufe", true, true }, { "Alchimie", false, nil, 120, 0, 0, 150 }, { "Alchimistik", false, nil, 20, 0, 0, 75 },
            { "Kräuterkunde", false, nil, 130, 0, 0, 150 }, { "Sekundäre Fertigkeiten", true, true }, { "Kochkunst", false, nil, 75, 0, 0, 75 },
        }
        mark = #log
        slash("crafttest")
        assert(Said("Alchimie 120/150 = Alchemy", mark + 1) == 1, "crafttest: no line \"Alchimie 120/150 = Alchemy\"")
        assert(Said("Alchimistik 20/75 = not recognised", mark + 1) == 1, "crafttest: the unknown line is not marked")
        assert(Said("Kräuterkunde 130/150 = Herbalism", mark + 1) == 1 and Said("Kochkunst 75/75 = Cooking", mark + 1) == 1, "crafttest: gathering or cooking line")
    end)
    GetProfessions, GetNumSkillLines, GetSkillLineInfo, ns.db.debug = keep.gp, keep.gn, keep.gi, keep.debug
    GetTradeSkillLine, GetNumTradeSkills, GetTradeSkillInfo, GetTradeSkillItemLink = keep.line, keep.num, keep.info, keep.link
    GetTradeSkillNumReagents, GetTradeSkillReagentInfo, GetTradeSkillReagentItemLink, GetTradeSkillNumMade = keep.nr, keep.ri, keep.rl, keep.made
    mine.Alchemy, mine.Alchimie = keepAlchemy, nil
    if ns.db.recipeDB then ns.db.recipeDB.Alchimie, ns.db.recipeDB.Alchemy = nil, keepDB end
    if _G.GathercraftSkillPlan then _G.GathercraftSkillPlan:Hide() end
    if not ok then error(err, 0) end
end)
-- (end of the v0.1.22 steps)
step("Gathering help: mark the node you walk towards, put back like fishing (v0.1.19 Q6 A)", function()
    local saved = { get = GetCVar, set = SetCVar, mark = ns.db.gatherMark, bobber = ns.db.fishMarkBobber, loud = ns.db.fishLoudSplash,
        cvars = ns.db.fishingCVars, map = player.map, x = player.x, y = player.y }
    local store
    local ORIG = { SoftTargetInteract = "1", SoftTargetInteractRange = "10", SoftTargetInteractArc = "0", SoftTargetIconGameObject = "0",
        Sound_SFXVolume = "0.5", Sound_MusicVolume = "0.8", Sound_AmbienceVolume = "0.8" }
    local function Reset()
        store = {}
        for k, v in pairs(ORIG) do store[k] = v end
    end
    local function Is(want, what)
        for k, v in pairs(want) do
            assert(store[k] == v, ("%s: %s = %s, want %s"):format(what, k, tostring(store[k]), v))
        end
    end
    local MARKED = { SoftTargetInteract = "3", SoftTargetInteractRange = "30", SoftTargetInteractArc = "2", SoftTargetIconGameObject = "1" }
    local function Untouched(what)
        Is(ORIG, what)
        assert(ns.db.fishingCVars == nil, what .. ": an entry is left in the saved list")
    end
    local fishFrame = next(eventFrames["UNIT_SPELLCAST_CHANNEL_STOP"])
    local function Cast() fire("UNIT_SPELLCAST_CHANNEL_START", "player", "q6fish", 7620) end
    local function Reel() fire("UNIT_SPELLCAST_CHANNEL_STOP", "player", "q6fish", 7620) advance(1) end
    local ok, err = pcall(function()
        GetCVar = function(k) if store[k] ~= nil then return store[k] end return saved.get(k) end
        SetCVar = function(k, v) store[k] = tostring(v) return true end
        ns.db.fishingCVars, ns.db.fishMarkBobber, ns.db.fishLoudSplash = nil, false, true
        player.map, player.x, player.y = 1412, 0.45, 0.72
        ns.SetQuestMode(false)
        if ns.run then ns.StopRun(true) end
        -- (1) off (the default): runs and the questing mode change nothing
        ns.db.gatherMark = nil
        Reset()
        slash("run herb") advance(2)
        assert(ns.run, "test setup: no run")
        Untouched("option off, during a run")
        ns.StopRun(true) advance(1)
        ns.SetQuestMode(true) advance(1)
        Untouched("option off, questing mode")
        ns.SetQuestMode(false) advance(1)
        Untouched("option off, after")
        -- (2) on: during the questing mode the four settings, after it yours again
        ns.db.gatherMark = true
        Reset()
        ns.UpdateGatherHelp("test")
        Untouched("option on, nothing going on")
        ns.SetQuestMode(true) advance(1)
        Is(MARKED, "questing mode")
        assert(ns.db.fishingCVars and ns.db.fishingCVars.SoftTargetInteractRange.orig == "10", "not in the saved list")
        ns.SetQuestMode(false) advance(1)
        Untouched("questing mode off")
        -- (3) a farm run the same
        slash("run herb") advance(2)
        Is(MARKED, "farm run")
        slash("stop") advance(1)
        Untouched("run stopped")
        -- (4) you change one during the run: it stays as you set it
        slash("run herb") advance(2)
        store.SoftTargetInteractRange = "50"
        slash("stop") advance(1)
        Is({ SoftTargetInteract = "1", SoftTargetInteractRange = "50", SoftTargetInteractArc = "0", SoftTargetIconGameObject = "0" }, "changed by you during the run")
        assert(ns.db.fishingCVars == nil, "changed by you: an entry is left")
        -- (5) fishing during a run: fishing takes over, the run keeps its mark
        Reset()
        slash("run herb") advance(2)
        Cast()
        Is(MARKED, "line out during a run")
        Is({ Sound_SFXVolume = "1", Sound_MusicVolume = "0.1" }, "line out: the splash settings")
        Reel()
        Is(MARKED, "line in, the run goes on")
        Is({ Sound_SFXVolume = "0.5", Sound_MusicVolume = "0.8", Sound_AmbienceVolume = "0.8" }, "line in: the splash settings came back")
        slash("stop") advance(1)
        Untouched("run stopped after fishing")
        -- the other way round: a run starts while the line is out
        Reset()
        Cast()
        slash("run herb") advance(2)
        Reel()
        Is(MARKED, "run started with the line out, line in")
        slash("stop") advance(1)
        Untouched("run stopped, the line came in first")
        Reset()
        Cast()
        slash("run herb") advance(2)
        slash("stop") advance(1)
        Is({ SoftTargetInteractRange = "30", Sound_SFXVolume = "1" }, "run stopped, the line still out: fishing keeps its settings")
        Reel()
        Untouched("line in after the run")
        -- (6) the option switched off and on during a run
        slash("run herb") advance(2)
        Is(MARKED, "run")
        ns.db.gatherMark = nil
        ns.UpdateGatherHelp("option")
        Untouched("option switched off during the run")
        ns.db.gatherMark = true
        ns.UpdateGatherHelp("option")
        Is(MARKED, "option switched on again during the run")
        -- (7) /reload or logout during the run: back before the game saves
        fishFrame.__scripts.OnEvent(fishFrame, "PLAYER_LOGOUT")
        Untouched("logout during a run")
        -- the reloaded addon, the run going on: marked again after login
        fishFrame.__scripts.OnEvent(fishFrame, "PLAYER_LOGIN")
        advance(2)
        Is(MARKED, "login, the run going on")
        -- (8) the run ended without its stop (a crash, a disconnect), but the
        -- list was saved before it (a /reload or logout during the run): the
        -- settings are still ours, the next login (no run going on now) puts
        -- them back from the saved list
        assert(ns.db.fishingCVars and ns.db.fishingCVars.SoftTargetInteractRange, "test setup: the list during the run")
        local crashed = ns.run
        ns.run = nil -- gone with the crash, without its stop
        fishFrame.__scripts.OnEvent(fishFrame, "PLAYER_LOGIN")
        advance(2)
        Untouched("login after a crash, the list saved before it")
        ns.run = crashed
        ns.StopRun(true)
        Untouched("the old run's stop after the crash login")
        -- the limit (Codex 09.11., B4): a crash before the game ever saved
        -- the list - the settings are still ours, nothing says what they
        -- were. The login leaves them as they are: nothing is guessed, no
        -- default is forced, no list is invented
        for k, v in pairs(MARKED) do store[k] = v end
        ns.db.fishingCVars = nil
        fishFrame.__scripts.OnEvent(fishFrame, "PLAYER_LOGIN")
        advance(2)
        Is(MARKED, "login after a crash without a saved list: a value was guessed")
        assert(ns.db.fishingCVars == nil, "login after a crash without a saved list: a list was invented")
        Reset()
        -- (9) the option text says honestly what it does
        local found
        for _, o in ipairs(allFrames) do
            if o.__kind == "FontString" and o:GetText() == ns.L["Mark the node you walk towards (one at a time)"] then found = o end
        end
        assert(found, "no option \"Mark the node you walk towards (one at a time)\"")
    end)
    GetCVar, SetCVar = saved.get, saved.set
    if ns.run then ns.StopRun(true) end
    ns.SetQuestMode(false)
    ns.db.gatherMark, ns.db.fishMarkBobber, ns.db.fishLoudSplash, ns.db.fishingCVars = saved.mark, saved.bobber, saved.loud, saved.cvars
    if ns.StopFishing then ns.StopFishing() end
    player.map, player.x, player.y = saved.map, saved.x, saved.y
    if not ok then error(err, 0) end
end)
step("Gathering help: the Fish key gathers during a run or the questing mode, never in combat (v0.1.19 Q6 B)", function()
    local saved = { get = GetCVar, set = SetCVar, set2 = SetOverrideBinding, clear = ClearOverrideBindings, combat = InCombatLockdown,
        bind = GetBindingKey, mark = ns.db.gatherMark, key = ns.db.gatherKey, cvars = ns.db.fishingCVars, bobber = ns.db.fishMarkBobber,
        map = player.map, x = player.x, y = player.y, guid = UnitGUID }
    -- (since 0.1.21, T4: in the questing mode the key gathers only while a
    -- node is marked - its own step. Here a Peacebloom is marked throughout.)
    UnitGUID = function(u) if u == "softinteract" then return "GameObject-0-1-0-1-1618-00001A2B3C" end return saved.guid(u) end
    local store = {}
    local binds = {} -- owner -> key -> command
    local fighting = false
    local bound = "F" -- the key bound to Fish (nil: none)
    local function Gathers()
        for _, keys in pairs(binds) do if keys.F == "INTERACTTARGET" then return true end end
        return false
    end
    local function Owners()
        local n = 0
        for _, keys in pairs(binds) do if next(keys) then n = n + 1 end end
        return n
    end
    local function Cast() fire("UNIT_SPELLCAST_CHANNEL_START", "player", "q6b", 7620) end
    local function Reel() fire("UNIT_SPELLCAST_CHANNEL_STOP", "player", "q6b", 7620) advance(1) end
    local L = ns.L
    local ok, err = pcall(function()
        GetCVar = function(k) return store[k] or "0" end
        SetCVar = function(k, v) store[k] = tostring(v) return true end
        SetOverrideBinding = function(owner, _, key, cmd) binds[owner] = binds[owner] or {} binds[owner][key] = cmd end
        ClearOverrideBindings = function(owner) binds[owner] = nil end
        InCombatLockdown = function() return fighting end
        GetBindingKey = function(cmd) if cmd == ns.FishBinding then return bound end return saved.bind(cmd) end
        ns.db.fishingCVars, ns.db.fishMarkBobber = nil, false
        player.map, player.x, player.y = 1412, 0.45, 0.72
        ns.SetQuestMode(false)
        if ns.run then ns.StopRun(true) end
        -- (1) off: the Fish key stays the Fish key
        ns.db.gatherMark, ns.db.gatherKey = nil, nil
        slash("run herb") advance(2)
        assert(ns.run and not Gathers(), "option off: the Fish key gathers during a run")
        slash("stop") advance(1)
        -- (2) the switch turns the mark on too; the mark off turns it off
        local keyBox, markBox
        for _, o in ipairs(allFrames) do
            if o.__kind == "FontString" and o.__pts and o.__pts.LEFT then
                if o:GetText() == L["Fish key gathers the marked node"] then keyBox = o.__pts.LEFT[1] end
                if o:GetText() == L["Mark the node you walk towards (one at a time)"] then markBox = o.__pts.LEFT[1] end
            end
        end
        assert(keyBox and markBox and keyBox.get and markBox.get, "no switches under Farm runs")
        keyBox:SetChecked(true) keyBox.__scripts.OnClick(keyBox)
        assert(ns.db.gatherKey and ns.db.gatherMark and markBox.get(), "the key switch did not turn the mark on")
        markBox:SetChecked(false) markBox.__scripts.OnClick(markBox)
        assert(not ns.db.gatherKey and not ns.db.gatherMark, "the mark off left the key on")
        keyBox:SetChecked(true) keyBox.__scripts.OnClick(keyBox)
        assert(not Gathers(), "the key gathers with nothing going on")
        -- (3) a run: the Fish key gathers, and the node is marked; after the run: fishing again
        slash("run herb") advance(2)
        assert(Gathers() and store.SoftTargetInteract == "3", "during the run: the key does not gather, or nothing marked")
        slash("stop") advance(1)
        assert(not Gathers() and Owners() == 0, "after the run the key still gathers")
        assert(ns.db.fishingCVars == nil, "after the run settings are left")
        -- (4) the questing mode the same
        ns.SetQuestMode(true) advance(1)
        assert(Gathers(), "questing mode: the key does not gather")
        ns.SetQuestMode(false) advance(1)
        assert(not Gathers(), "questing mode off: the key still gathers")
        -- (5) combat: nothing is changed in the fight, it follows at its end
        fighting = true
        slash("run herb") advance(2)
        assert(ns.run and not Gathers(), "a key changed in combat (run start)")
        fighting = false
        fire("PLAYER_REGEN_ENABLED") advance(1)
        assert(Gathers(), "after the fight the key does not gather")
        fighting = true
        slash("stop") advance(1)
        assert(Gathers(), "a key changed in combat (run stop)")
        fighting = false
        fire("PLAYER_REGEN_ENABLED") advance(1)
        assert(not Gathers() and Owners() == 0, "after the fight the key still gathers")
        -- (6) fishing during a run: reeling in ends the line, not the gathering key
        slash("run herb") advance(2)
        Cast()
        assert(Gathers(), "line out during a run")
        Reel()
        assert(Gathers(), "line in: the run's gathering key went")
        slash("stop") advance(1)
        assert(not Gathers() and Owners() == 0, "after the run and fishing a key is left")
        -- (7) the option off during the run
        slash("run herb") advance(2)
        keyBox:SetChecked(false) keyBox.__scripts.OnClick(keyBox)
        assert(not Gathers(), "the switch off: the key still gathers")
        slash("stop") advance(1)
        -- (8) the key saved on, the mark saved off (settings of another
        -- version): the key still brings the mark with it
        ns.db.gatherKey, ns.db.gatherMark = true, nil
        slash("run herb") advance(2)
        assert(Gathers() and store.SoftTargetInteract == "3", "the key without a saved mark: nothing marked")
        slash("stop") advance(1)
        assert(not Gathers() and ns.db.fishingCVars == nil, "the key without a saved mark: left after the run")
        ns.db.gatherKey = nil
        -- (9) you rebind the Fish key while it gathers (Codex 09.11., B2): the
        -- old key is yours again, the new one gathers; none bound, none
        -- overridden; in combat it waits for the end of the fight
        local function KeyGathers(key)
            for _, keys in pairs(binds) do if keys[key] == "INTERACTTARGET" then return true end end
            return false
        end
        ns.db.gatherKey, ns.db.gatherMark = true, true
        slash("run herb") advance(2)
        assert(KeyGathers("F"), "test setup: F does not gather")
        bound = "G"
        fire("UPDATE_BINDINGS")
        assert(not KeyGathers("F"), "F rebound to another action: still overridden")
        assert(KeyGathers("G"), "the new Fish key G does not gather")
        bound = nil
        fire("UPDATE_BINDINGS")
        assert(not KeyGathers("F") and not KeyGathers("G") and Owners() == 0, "no Fish key bound: an override is left")
        bound = "F"
        fighting = true
        fire("UPDATE_BINDINGS")
        assert(Owners() == 0, "a key changed in combat (rebind)")
        fighting = false
        fire("PLAYER_REGEN_ENABLED") advance(1)
        assert(KeyGathers("F"), "after the fight the rebound key does not gather")
        fighting = true
        bound = "G"
        fire("UPDATE_BINDINGS")
        assert(KeyGathers("F") and not KeyGathers("G"), "a key changed in combat (F to G)")
        fighting = false
        fire("PLAYER_REGEN_ENABLED") advance(1)
        assert(KeyGathers("G") and not KeyGathers("F"), "after the fight: G should gather, F be free")
        slash("stop") advance(1)
        assert(Owners() == 0, "after the run an override of a rebound key is left")
        bound = "F"
    end)
    GetBindingKey = saved.bind
    GetCVar, SetCVar, SetOverrideBinding, ClearOverrideBindings, InCombatLockdown = saved.get, saved.set, saved.set2, saved.clear, saved.combat
    UnitGUID = saved.guid
    if ns.run then ns.StopRun(true) end
    ns.SetQuestMode(false)
    ns.db.gatherMark, ns.db.gatherKey, ns.db.fishingCVars, ns.db.fishMarkBobber = saved.mark, saved.key, saved.cvars, saved.bobber
    if ns.UpdateGatherHelp then ns.UpdateGatherHelp("test end") end
    if ns.StopFishing then ns.StopFishing() end
    player.map, player.x, player.y = saved.map, saved.x, saved.y
    if not ok then error(err, 0) end
end)
step("Skinning log: one entry per skinned beast, needed skill from the client's message, local only (v0.1.19 Q7)", function()
    local L = ns.L
    local saved = { guid = UnitGUID, name = UnitName, isPlayer = UnitIsPlayer, skill = ns.GetSkill, secret = issecretvalue,
        log = ns.db.skinLog, needs = ns.db.skinNeeds, off = ns.db.skinLogOff, err = _G.ERR_USE_LOCKED_WITH_SPELL_KNOWN_SI,
        unclear = ns.db.skinUnclear, map = player.map, x = player.x, y = player.y }
    local units = {}
    local SECRET = newproxy(true)
    local CORPSE = "Creature-0-1-1-1-3035-0000AA0001"
    -- opts.target == false: no target and nothing under the mouse at the cast
    local function Skin(guid, items, opts)
        opts = opts or {}
        units.target = opts.target ~= false and guid or nil
        if not opts.noCast then fire("UNIT_SPELLCAST_SUCCEEDED", "player", "Cast-skin-" .. tostring(guid), opts.spell or 8613) end
        if opts.wait then advance(opts.wait) end
        loot = {}
        for _, it in ipairs(items) do loot[#loot + 1] = { guid = opts.source or guid, item = it[1], qty = it[2] } end
        for _, e in ipairs(opts.events or { "LOOT_READY", "LOOT_OPENED", "LOOT_READY", "LOOT_CLOSED", "LOOT_CLOSED" }) do fire(e) end
        loot = {}
        advance(1)
    end
    local ok, err = pcall(function()
        UnitGUID = function(u) return units[u] end
        UnitName = function(u) if u == "player" then return "Test Player" end return units[u] and "Plainstrider" or nil end
        UnitIsPlayer = function() return false end
        ns.GetSkill = function(t) if t == "skin" then return 50, 75, 50 end return saved.skill(t) end
        ns.db.skinLog, ns.db.skinNeeds, ns.db.skinLogOff, ns.db.skinUnclear = {}, {}, nil, nil
        player.map, player.x, player.y = 1412, 0.4567, 0.7123
        local nodesBefore = #(ns.db.nodes[1412] or {})
        -- a normal skinning; the loot window seen twice is one entry
        Skin(CORPSE, { { 2318, 2 }, { 2934, 1 } })
        assert(#ns.db.skinLog == 1, "entries after one skinning: " .. #ns.db.skinLog)
        local e = ns.db.skinLog[1]
        assert(e.npc == 3035 and e.name == "Plainstrider" and e.map == 1412, ("npc %s, name %s, map %s"):format(tostring(e.npc), tostring(e.name), tostring(e.map)))
        assert(e.x == 0.46 and e.y == 0.71, ("a rough position, not the exact one: %s %s"):format(tostring(e.x), tostring(e.y)))
        assert(e.skill == 50 and e.build == 70450 and e.t, "skill, build or time")
        assert(e.items[2318] == 2 and e.items[2934] == 1, "the items and amounts")
        assert(#(ns.db.nodes[1412] or {}) == nodesBefore, "the herb and ore recorder took the skinning as a node")
        -- the same corpse again (a late loot event): nothing more
        Skin(CORPSE, { { 2318, 2 } }, { noCast = true })
        assert(#ns.db.skinLog == 1, "the same corpse counted twice")
        -- looting a corpse without skinning it: nothing
        Skin("Creature-0-1-1-1-3035-0000AA0002", { { 4865, 1 } }, { noCast = true })
        assert(#ns.db.skinLog == 1, "a normal corpse loot counted as skinning")
        -- a cast that was broken off (no success), then the normal loot: nothing
        units.target = "Creature-0-1-1-1-3035-0000AA0003"
        fire("UNIT_SPELLCAST_START", "player", "Cast-abort", 8613)
        fire("UNIT_SPELLCAST_INTERRUPTED", "player", "Cast-abort", 8613)
        Skin("Creature-0-1-1-1-3035-0000AA0003", { { 4865, 1 } }, { noCast = true })
        assert(#ns.db.skinLog == 1, "an interrupted skinning counted")
        -- another spell (Herbalism) before a loot: nothing
        Skin("Creature-0-1-1-1-3035-0000AA0004", { { 2318, 1 } }, { spell = 2366 })
        assert(#ns.db.skinLog == 1, "a herb spell made a skinning")
        -- the loot of a chest or a herb right after a skinning cast: nothing
        Skin("Creature-0-1-1-1-3035-0000AA0005", { { 2447, 1 } }, { source = "GameObject-0-1-1-1-1617-0000BB0001" })
        Skin("Creature-0-1-1-1-3035-0000AA0006", { { 858, 1 } }, { source = "GameObject-0-1-1-1-106318-0000BB0002" })
        assert(#ns.db.skinLog == 1, "a chest or herb loot counted as skinning")
        -- Codex' probe (09.11., B3): no target and nothing under the mouse at
        -- the cast, then the loot of another beast within 5 s: no find for
        -- it; kept apart as unclear, not dropped in silence
        local OTHER = "Creature-0-1-1-1-9999-0000DD0001"
        Skin(OTHER, { { 4865, 1 } }, { target = false })
        assert(#ns.db.skinLog == 1, "a beast's loot without a beast at the cast counted as a find")
        assert(ns.db.skinUnclear and #ns.db.skinUnclear == 1, "the unclear loot was dropped in silence")
        assert(ns.db.skinUnclear[1].npc == 9999 and ns.db.skinUnclear[1].items[4865] == 1 and ns.db.skinUnclear[1].name == nil, "the unclear entry")
        -- the same corpse again: still one unclear
        Skin(OTHER, { { 4865, 1 } }, { target = false, noCast = true })
        assert(#ns.db.skinUnclear == 1, "the same unclear corpse kept twice")
        -- Codex' control: your own corpse is clear, another beast's loot comes
        -- first - it is not the skinning (no find, not unclear), your leather
        -- after it is one entry
        local MINE = "Creature-0-1-1-1-3035-0000AA0020"
        Skin(MINE, { { 4865, 1 } }, { source = "Creature-0-1-1-1-9999-0000DD0002" })
        assert(#ns.db.skinLog == 1 and #ns.db.skinUnclear == 1, "another beast's loot with your own corpse clear")
        Skin(MINE, { { 2318, 1 } }, { noCast = true })
        Skin(MINE, { { 2318, 1 } }, { noCast = true })
        assert(#ns.db.skinLog == 2 and ns.db.skinLog[2].npc == 3035 and ns.db.skinLog[2].items[2318] == 1, "your own leather after another beast's loot")
        table.remove(ns.db.skinLog, 2)
        -- a loot long after the cast: nothing
        Skin("Creature-0-1-1-1-3035-0000AA0007", { { 2318, 1 } }, { wait = 6 })
        assert(#ns.db.skinLog == 1, "a loot 6 s after the cast counted")
        -- a second skinning cast on the corpse already skinned, its loot again: still one
        Skin(CORPSE, { { 2318, 2 } })
        assert(#ns.db.skinLog == 1, "the same corpse counted again after a second cast")
        -- no beast to tell (no target, no mouseover): a chest after a skinning cast is still no entry
        units.target, units.mouseover = nil, nil
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", "Cast-nt", 8613)
        loot = { { guid = "GameObject-0-1-1-1-106318-0000BB0003", item = 858, qty = 1 } }
        fire("LOOT_READY") loot = {} advance(1)
        assert(#ns.db.skinLog == 1, "a chest counted as skinning when no beast was targeted")
        -- hidden values: nothing compared or kept
        issecretvalue = function(v) return rawequal(v, SECRET) end
        Skin("Creature-0-1-1-1-3035-0000AA0008", { { 2318, 1 } }, { source = SECRET })
        assert(#ns.db.skinLog == 1, "a hidden loot source counted")
        loot = {}
        units.target = "Creature-0-1-1-1-3035-0000AA0009"
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", "Cast-s9", 8613)
        loot = { { guid = "Creature-0-1-1-1-3035-0000AA0009", item = 2318, qty = SECRET } }
        fire("LOOT_READY") loot = {} advance(1)
        assert(#ns.db.skinLog == 1, "a hidden amount counted")
        ns.GetSkill = function(t) if t == "skin" then return SECRET end return saved.skill(t) end
        Skin("Creature-0-1-1-1-3035-0000AA0010", { { 2318, 1 } })
        assert(#ns.db.skinLog == 2 and ns.db.skinLog[2].skill == nil, "a hidden skill: kept, or the entry missing")
        ns.GetSkill = function(t) if t == "skin" then return 50, 75, 50 end return saved.skill(t) end
        issecretvalue = saved.secret
        -- "Requires Skinning N": the client's own text, the client's name of Skinning
        local skin = C_Spell.GetSpellName(8613)
        _G.ERR_USE_LOCKED_WITH_SPELL_KNOWN_SI = "Requires %s %d"
        units.target, units.mouseover = "Creature-0-1-1-1-2956-0000CC0001", nil
        fire("UI_ERROR_MESSAGE", 51, "Requires " .. skin .. " 100")
        assert(ns.db.skinNeeds[2956] == 100, "the needed skill is not kept: " .. tostring(ns.db.skinNeeds[2956]))
        -- the older form (message only)
        units.target = "Creature-0-1-1-1-2957-0000CC0002"
        fire("UI_ERROR_MESSAGE", "Requires " .. skin .. " 85")
        assert(ns.db.skinNeeds[2957] == 85, "the older message form")
        -- a client whose text puts the number first (numbered places)
        _G.ERR_USE_LOCKED_WITH_SPELL_KNOWN_SI = "%2$d %1$s benötigt"
        units.target = "Creature-0-1-1-1-2958-0000CC0003"
        fire("UI_ERROR_MESSAGE", 51, "120 " .. skin .. " benötigt")
        assert(ns.db.skinNeeds[2958] == 120, "a text with the number first")
        _G.ERR_USE_LOCKED_WITH_SPELL_KNOWN_SI = "Requires %s %d"
        -- another skill (Lockpicking), or two beasts at once: nothing
        units.target = "Creature-0-1-1-1-2959-0000CC0004"
        fire("UI_ERROR_MESSAGE", 51, "Requires Lockpicking 100")
        units.target, units.mouseover = "Creature-0-1-1-1-2960-0000CC0005", "Creature-0-1-1-1-2961-0000CC0006"
        fire("UI_ERROR_MESSAGE", 51, "Requires " .. skin .. " 100")
        assert(not ns.db.skinNeeds[2959] and not ns.db.skinNeeds[2960] and not ns.db.skinNeeds[2961], "kept although not clear")
        units.mouseover = nil
        -- no text in the client: nothing is guessed
        _G.ERR_USE_LOCKED_WITH_SPELL_KNOWN_SI = nil
        units.target = "Creature-0-1-1-1-2962-0000CC0007"
        fire("UI_ERROR_MESSAGE", 51, "Requires " .. skin .. " 100")
        assert(not ns.db.skinNeeds[2962], "a needed skill without the client's text")
        _G.ERR_USE_LOCKED_WITH_SPELL_KNOWN_SI = saved.err
        -- /gcr skinlog
        local mark = #log
        slash("skinlog")
        local text = table.concat(log, "\n", mark + 1)
        assert(text:find((L["Skinning log: %d skinned, %d kinds of beasts (kept on this computer, never shared)."]):format(2, 1), 1, true), "/gcr skinlog: " .. text)
        assert(text:find("Plainstrider", 1, true) and text:find((L["  Your skill while skinning: %d-%d"]):format(50, 50), 1, true), "/gcr skinlog: beasts or skill")
        assert(text:find((L["  %d unclear: no beast could be told at the cast (not counted)"]):format(1), 1, true), "/gcr skinlog: the unclear count")
        assert(not text:find("9999", 1, true), "/gcr skinlog: the unclear beast listed as a find")
        -- off: nothing
        ns.db.skinLogOff = true
        Skin("Creature-0-1-1-1-3035-0000AA0011", { { 2318, 1 } })
        assert(#ns.db.skinLog == 2, "recorded although turned off")
        ns.db.skinLogOff = nil
        -- the newest 5000
        local full = {}
        for i = 1, 5000 do full[i] = { t = i, npc = 1, items = {} } end
        ns.db.skinLog = full
        Skin("Creature-0-1-1-1-3035-0000AA0012", { { 2318, 1 } })
        assert(#ns.db.skinLog == 5000 and ns.db.skinLog[1].t == 2 and ns.db.skinLog[5000].npc == 3035, "not kept at 5000")
        -- clear
        slash("skinlog clear")
        assert(#ns.db.skinLog == 0 and not next(ns.db.skinNeeds) and #ns.db.skinUnclear == 0, "/gcr skinlog clear")
        -- never in what is shared: no sync message carries it
        for _, m in ipairs(sentMessages) do assert(not m:find("3035", 1, true) or m:find("^N:"), "a skinning in a sync message: " .. m) end
        for _, m in ipairs(sentMessages) do assert(not m:find("9999", 1, true) or m:find("^N:"), "an unclear skinning in a sync message: " .. m) end
        -- the option under General
        local found
        for _, o in ipairs(allFrames) do
            if o.__kind == "FontString" and o:GetText() == L["Record skinning (helps build skinning areas)"] then
                local p = o.__parent
                while p and not p.key do p = p.__parent end
                found = p and p.key
            end
        end
        assert(found == "general", "the option is not under General: " .. tostring(found))
    end)
    UnitGUID, UnitName, UnitIsPlayer, ns.GetSkill, issecretvalue = saved.guid, saved.name, saved.isPlayer, saved.skill, saved.secret
    ns.db.skinLog, ns.db.skinNeeds, ns.db.skinLogOff, _G.ERR_USE_LOCKED_WITH_SPELL_KNOWN_SI = saved.log, saved.needs, saved.off, saved.err
    ns.db.skinUnclear = saved.unclear
    player.map, player.x, player.y = saved.map, saved.x, saved.y
    loot = {}
    if not ok then error(err, 0) end
end)
step("Options: the herbs/minerals switch is under General, every page fits (v0.1.19)", function()
    -- Sven (08.11.): Map & minimap makes room for the questing mode
    local function PageOf(text)
        for _, o in ipairs(allFrames) do
            if o.GetText and o:GetText() == text then
                local p = o.__parent
                while p and not p.key do p = p.__parent end
                if p then return p.key end
            end
        end
    end
    assert(PageOf(ns.L["Herbs / minerals switch button"]) == "general", "the switch is not under General: " .. tostring(PageOf(ns.L["Herbs / minerals switch button"])))
    assert(PageOf(ns.L["Put it on an action bar"]) == "general", "its macro button is not under General")
    assert(PageOf(ns.L["Next to the minimap, when you know both: one click switches your tracking."]) == "general", "its hint is not under General")
    -- every page that does not flow ends above the footer, also inside the
    -- main window (its options page is 6 px lower than the standalone window)
    local used = ns.OptionsUsedHeight and ns.OptionsUsedHeight()
    assert(used and used.map and used.general, "test setup: how far the pages go")
    local ROOM = 640 - 112 - 18 - 4 - 66 -- main window body, minus the options' top and footer
    for key, h in pairs(used) do
        if key ~= "level" then -- Leveling flows (own step)
            assert(h <= ROOM, ("Options %s: %d px of %d"):format(key, h, ROOM))
        end
    end
end)
step("Herbs / minerals switch button: on the edge of a round and a square minimap, above its frame (v0.1.20 K1)", function()
    -- Sven (09.11.): with a square minimap (Ellesmere UI) the button was
    -- never seen. It sat on a circle around the centre, whatever the shape.
    local btn = GathercraftTrackButton
    assert(btn, "no switch button")
    local saved = { shape = _G.GetMinimapShape, w = Minimap.GetWidth, h = Minimap.GetHeight, angle = ns.db.trackButtonAngle, combat = InCombatLockdown }
    -- places the button (older code: only its login event does)
    local function Place()
        if ns.PlaceTrackButton then ns.PlaceTrackButton() return end
        local f = next(eventFrames["MINIMAP_UPDATE_TRACKING"])
        f.__scripts.OnEvent(f, "PLAYER_LOGIN")
    end
    local function Pos()
        local p = btn.__pts and btn.__pts.CENTER
        assert(p and p[1] == Minimap and p[2] == "CENTER", "the button is not anchored to the minimap's centre")
        return p[3], p[4]
    end
    local function Near(a, b) return math.abs(a - b) < 0.5 end
    local ok, err = pcall(function()
        Minimap.GetWidth = function() return 140 end
        Minimap.GetHeight = function() return 140 end
        -- round (no shape function, as the game's own minimap): a circle of 75
        _G.GetMinimapShape = nil
        ns.db.trackButtonAngle = 250
        Place()
        local x, y = Pos()
        assert(Near(math.sqrt(x * x + y * y), 75), ("round: %.1f from the centre, want 75"):format(math.sqrt(x * x + y * y)))
        assert(Near(x, math.cos(math.rad(250)) * 75) and Near(y, math.sin(math.rad(250)) * 75), "round: not at the saved angle")
        -- a UI addon says ROUND: the same
        _G.GetMinimapShape = function() return "ROUND" end
        Place()
        local x2, y2 = Pos()
        assert(Near(x, x2) and Near(y, y2), "ROUND from the shape function placed differently")
        -- SQUARE: on the rectangle's edge, 5 px outside, in the same direction
        _G.GetMinimapShape = function() return "SQUARE" end
        Place()
        x, y = Pos()
        assert(Near(y, -75), ("square at 250 degrees: y %.1f, want -75 (the bottom edge)"):format(y))
        assert(Near(x / y, math.cos(math.rad(250)) / math.sin(math.rad(250))), "square: not in the direction of the angle")
        assert(math.abs(x) < 75, "square: outside the rectangle's width")
        -- at 0 degrees: the right edge
        ns.db.trackButtonAngle = 0
        Place()
        x, y = Pos()
        assert(Near(x, 75) and Near(y, 0), ("square at 0 degrees: %.1f, %.1f"):format(x, y))
        -- at 45 degrees on a square: the corner
        ns.db.trackButtonAngle = 45
        Place()
        x, y = Pos()
        assert(Near(x, 75) and Near(y, 75), ("square at 45 degrees: %.1f, %.1f"):format(x, y))
        -- a wider than tall minimap: the edge is the rectangle's, not a circle's
        Minimap.GetWidth = function() return 200 end
        ns.db.trackButtonAngle = 90
        Place()
        x, y = Pos()
        assert(Near(x, 0) and Near(y, 75), ("wide minimap at 90 degrees: %.1f, %.1f"):format(x, y))
        Minimap.GetWidth = function() return 140 end
        -- a corner shape or an odd value: not round, so the rectangle; an
        -- erroring or non-string answer: round
        _G.GetMinimapShape = function() return "CORNER-TOPLEFT" end
        ns.db.trackButtonAngle = 0
        Place()
        assert(Near((Pos()), 75), "a corner shape: not on the rectangle's edge")
        _G.GetMinimapShape = function() error("no") end
        ns.db.trackButtonAngle = 45
        Place()
        x, y = Pos()
        assert(Near(math.sqrt(x * x + y * y), 75), "an erroring shape function: not round")
        _G.GetMinimapShape = function() return 42 end
        Place()
        x, y = Pos()
        assert(Near(math.sqrt(x * x + y * y), 75), "a non-string shape: not round")
        -- above the minimap: strata MEDIUM, level above the minimap's
        assert(btn:GetFrameStrata() == "MEDIUM", "strata: " .. tostring(btn:GetFrameStrata()))
        assert(btn:GetFrameLevel() == Minimap:GetFrameLevel() + 8, "frame level")
        -- in combat nothing moves (a protected frame): the old place stays
        _G.GetMinimapShape = function() return "SQUARE" end
        InCombatLockdown = function() return true end
        Place()
        x, y = Pos()
        assert(Near(math.sqrt(x * x + y * y), 75), "moved in combat")
        InCombatLockdown = saved.combat
        -- after the fight the update places it again
        ns.UpdateTrackButton()
        x, y = Pos()
        assert(Near(x, 75) and Near(y, 75), "not placed after the fight")
    end)
    _G.GetMinimapShape, Minimap.GetWidth, Minimap.GetHeight, ns.db.trackButtonAngle, InCombatLockdown = saved.shape, saved.w, saved.h, saved.angle, saved.combat
    Place()
    if not ok then error(err, 0) end
end)
step("Herbs / minerals switch button", function()
    local btn = GathercraftTrackButton
    assert(btn, "no switch button")
    -- only one of the two known: no button
    ns.UpdateTrackButton()
    assert(not btn:IsShown(), "button shown without both tracking spells")
    local realKnown = IsPlayerSpell
    IsPlayerSpell = function(id) return id == 2383 or id == 2580 or realKnown(id) end
    ns.UpdateTrackButton()
    assert(btn:IsShown(), "button not shown with both tracking spells")
    -- every click switches to the other one
    local first = btn:GetAttribute("spell")
    assert(btn:GetAttribute("type") == "spell" and first, "no spell on the button")
    btn.__scripts.PreClick(btn) btn.__scripts.PostClick(btn) advance(1)
    local second = btn:GetAttribute("spell")
    assert(second and second ~= first, "click did not switch: " .. tostring(first) .. " / " .. tostring(second))
    btn.__scripts.PreClick(btn) btn.__scripts.PostClick(btn) advance(1)
    assert(btn:GetAttribute("spell") == first, "second click did not switch back")
    assert(pcall(btn.__scripts.OnEnter, btn), "tooltip")
    -- shift-drag moves it along the minimap's edge
    local realShift, realCursor = IsShiftKeyDown, GetCursorPosition
    IsShiftKeyDown = function() return true end
    GetCursorPosition = function() return 400, 300 end
    btn.__scripts.OnDragStart(btn)
    assert(btn.__scripts.OnUpdate, "dragging does not follow the cursor")
    assert(pcall(btn.__scripts.OnUpdate, btn, 0.1), "drag update")
    btn.__scripts.OnDragStop(btn)
    assert(not btn.__scripts.OnUpdate and ns.db.trackButtonAngle, "drag did not end or save the angle")
    IsShiftKeyDown, GetCursorPosition = realShift, realCursor
    ns.db.trackButtonAngle = nil
    -- option off: hidden
    ns.db.trackButtonHidden = true
    ns.UpdateTrackButton()
    assert(not btn:IsShown(), "option off, button still shown")
    ns.db.trackButtonHidden = nil
    -- the macro for the action bar: made once, then reused, on the cursor
    local macros, picked = {}, nil
    GetMacroIndexByName = function(n) for i, m in ipairs(macros) do if m.name == n then return i end end return 0 end
    GetNumMacros = function() return #macros, 0 end
    CreateMacro = function(n, icon, body) macros[#macros + 1] = { name = n, body = body } return #macros end
    EditMacro = function(i, n, icon, body) macros[i].body = body return i end
    PickupMacro = function(i) picked = i end
    ns.TrackMacro()
    assert(#macros == 1 and macros[1].body == "/click GathercraftTrackButton" and picked == 1, "macro not made")
    ns.TrackMacro()
    assert(#macros == 1, "macro made twice")
    InCombatLockdown = function() return true end
    picked = nil
    ns.TrackMacro()
    assert(picked == nil, "macro touched in combat")
    InCombatLockdown = function() return false end
    GetMacroIndexByName, GetNumMacros, CreateMacro, EditMacro, PickupMacro = nil, nil, nil, nil, nil
    IsPlayerSpell = realKnown
    ns.UpdateTrackButton()
end)
