step("Crafting: sort by a column, both ways, remembered (v0.1.17)", function()
    local function R(name, req, profit, value, cost, can, extra)
        local r = { name = name, prof = "Tailoring", req = req, profit = profit, value = value, valueSource = "AH scan",
            cost = cost, costUnknown = 0, reagents = { {} }, canMake = can, missing = false, enchant = false }
        for k, v in pairs(extra or {}) do r[k] = v end
        return r
    end
    local function Rows()
        return { R("Bolt", 50, 100, 300, 200, 3), R("Shirt", 10, 500, 900, 400, 0), R("Gloves", 75, -50, 100, 150, 9),
            R("Cloak", nil, 20, 120, 100, 1), R("Robe", 30, 0, 0, 0, 2, { missing = true, valueSource = nil, costUnknown = 1 }) }
    end
    local function Order(key, desc)
        local names = {}
        for _, r in ipairs(ns.CraftSortRows(Rows(), key, desc)) do names[#names + 1] = r.name end
        return table.concat(names, " ")
    end
    local want = {
        { "skill", false, "Shirt Robe Bolt Gloves Cloak" }, { "skill", true, "Gloves Bolt Robe Shirt Cloak" },
        { "profit", true, "Shirt Bolt Cloak Gloves Robe" }, { "profit", false, "Gloves Cloak Bolt Shirt Robe" },
        { "value", true, "Shirt Bolt Cloak Gloves Robe" }, { "cost", false, "Cloak Gloves Bolt Shirt Robe" },
        { "can", true, "Gloves Bolt Robe Cloak Shirt" }, { "name", false, "Bolt Cloak Gloves Robe Shirt" },
        { "name", true, "Shirt Robe Gloves Cloak Bolt" },
    }
    local bad = {}
    for _, w in ipairs(want) do
        local got = Order(w[1], w[2])
        if got ~= w[3] then bad[#bad + 1] = ("%s %s: %s"):format(w[1], tostring(w[2]), got) end
    end
    assert(#bad == 0, #bad .. " wrong: " .. table.concat(bad, " | "))

    -- the page: skill, low first, by default; a click sorts, a second click turns it round
    ns.db.craftSort, ns.db.craftSortDesc = nil, nil
    ns.ToggleMain("craft") advance(1)
    local titles = {}
    for _, f in ipairs(allFrames) do
        if f.__kind == "Button" and f.label and f.text and f.__scripts.OnClick then titles[f.label] = f end
    end
    for _, label in ipairs({ "Item", "Skill", "Profit", "Sells for", "Costs", "Can make" }) do
        assert(titles[label], "no clickable column title " .. label)
    end
    assert(titles.Skill.text.__text:find("Arrow-Up", 1, true), "skill is not the default sort: " .. tostring(titles.Skill.text.__text))
    titles.Profit.__scripts.OnClick(titles.Profit)
    assert(ns.db.craftSort == "profit" and ns.db.craftSortDesc == true, "profit click: " .. tostring(ns.db.craftSort))
    assert(titles.Profit.text.__text:find("Arrow-Down", 1, true), "profit: no arrow")
    assert(not titles.Skill.text.__text:find("Arrow", 1, true), "skill still marked")
    titles.Profit.__scripts.OnClick(titles.Profit)
    assert(ns.db.craftSort == "profit" and ns.db.craftSortDesc == false, "second click did not turn it round")
    ns.HideMain()
    ns.db.craftSort, ns.db.craftSortDesc = nil, nil
end)
step("Crafting: the skill in its own column, never 0, unknown ones last (v0.1.17)", function()
    -- Sven's find (08.11.): learned cooking recipes had no number and stood
    -- first when sorted by skill, the number sat in brackets after the name
    local keepDB = ns.db.recipeDB
    ns.db.recipeDB = { Cooking = {
        -- read from the profession window: no skill there (0)
        ["Brilliant Smallfish"] = "6290:1:1:0|6291:1",
        ["Smoked Desert Dumplings"] = "20452:1:1:0|3713:1,20424:1",
        -- seen at a trainer
        ["Herb Baked Egg"] = "6888:1:1:40|2678:1,6889:1",
    } }
    local shipped = GathercraftRecipeData.professions.Cooking
    assert(shipped["Brilliant Smallfish"]:match("^%d+:%d+:%d+:(%d+)") == "1", "test setup: shipped Brilliant Smallfish")
    local rows = ns.CraftAdvice("Cooking")
    local byName, zero = {}, 0
    for _, r in ipairs(rows) do
        byName[r.key] = r
        if r.req == 0 then zero = zero + 1 end
    end
    assert(zero == 0, zero .. " recipes with skill 0")
    assert(byName["Brilliant Smallfish"] and byName["Brilliant Smallfish"].req == 1, "own 0 hid the shipped skill: " .. tostring(byName["Brilliant Smallfish"] and byName["Brilliant Smallfish"].req))
    assert(byName["Herb Baked Egg"] and byName["Herb Baked Egg"].req == 40, "the skill seen at a trainer was not used")
    assert(byName["Smoked Desert Dumplings"] and byName["Smoked Desert Dumplings"].req == nil, "an unknown skill is not unknown")
    -- low first: the ones without a skill come last
    local sorted = ns.CraftSortRows(rows, "skill", false)
    local seenUnknown, bad = false, nil
    for i, r in ipairs(sorted) do
        if r.req == nil then seenUnknown = true elseif seenUnknown then bad = r.key end
        if i > 1 and r.req and sorted[i - 1].req and r.req < sorted[i - 1].req then bad = r.key end
    end
    assert(not bad, "skill low first is out of order at " .. tostring(bad))
    assert(sorted[#sorted].req == nil and sorted[1].req, "unknown skills are not last")
    -- Codex N1: costs a fraction of a copper apart still have one order
    local function C(name, cost) return { name = name, prof = "Cooking", cost = cost, costUnknown = 0, reagents = { {} } } end
    for _, desc in ipairs({ false, true }) do
        local list = ns.CraftSortRows({ C("A", 100.8), C("B", 100.4), C("C", 100.0) }, "cost", desc)
        local got = list[1].name .. list[2].name .. list[3].name
        assert(got == (desc and "ABC" or "CBA"), ("costs 100.8/100.4/100.0, %s: %s"):format(desc and "high first" or "low first", got))
    end
    -- the page: a skill column, names cut before it, no number in brackets
    ns.db.craftSort, ns.db.craftSortDesc = nil, nil
    ns.ToggleMain("craft") advance(1)
    local shown = 0
    for _, f in ipairs(allFrames) do
        if f.name and f.profit and f.icon and f.__shown and type(f.data) == "table" and f.data.reagents then
            shown = shown + 1
            assert(f.skill, "no skill column in the recipe rows")
            local nx, sx = f.name.__pts.LEFT[1], f.skill.__pts.LEFT[1]
            assert(nx + f.name.__w < sx, ("the name (%d + %d) runs into the skill column at %d"):format(nx, f.name.__w, sx))
            assert(f.name.__wrap == false, "a long name can wrap")
            assert(not tostring(f.name.__text):find("%(~?%d+%)"), "the skill still sits in brackets after the name: " .. tostring(f.name.__text))
            local want = f.data.req and tostring(f.data.req) or "?"
            assert(tostring(f.skill.__text):find(want, 1, true), ("skill column says %s, want %s"):format(tostring(f.skill.__text), want))
        end
    end
    assert(shown > 0, "test setup: no recipe rows on the page")
    ns.HideMain()
    ns.db.recipeDB = keepDB
end)
step("Minimap pins only near you: on within 400 yd, off beyond 450 yd, kept right while you walk (v0.1.23 P1)", function()
    -- Sven, 13.11.2026, Stranglethorn, walking: Gathercraft up to 20 % of the
    -- addon time, 5 % with "Show nodes on the minimap" off. Every node of the
    -- zone had a minimap pin, and HereBeDragons places every registered pin
    -- again on each frame you move. Now only the nodes near you are
    -- registered. The mock's zone is 5000 x 3333 yd: 1 yd = 0.0002 x.
    local ZONE, YD = 1434, 1 / 5000
    local pins = LibStub("HereBeDragons-Pins-2.0")
    local keepAdd, keepRem = pins.AddMinimapIconMap, pins.RemoveMinimapIcon
    local active, adds = {}, 0
    pins.AddMinimapIconMap = function(self, ref, icon, ...)
        if ref == "Gathercraft" then active[icon] = icon.node adds = adds + 1 end
        return keepAdd(self, ref, icon, ...)
    end
    pins.RemoveMinimapIcon = function(self, ref, icon, ...)
        if ref == "Gathercraft" then active[icon] = nil end
        return keepRem(self, ref, icon, ...)
    end
    local saved = { map = player.map, x = player.x, y = player.y, world = ns.db.worldPinsHidden, mini = ns.db.miniPinsHidden,
        follow = ns.db.mapFollowsZones, grey = ns.db.hideGreyNodes }
    local mine = {}
    local function Own(x, y, name)
        local n = { id = "o1618", name = name or "Peacebloom", type = "herb", x = x, y = y, count = 1, last = time(), item = 2447 }
        table.insert(ns.db.nodes[ZONE], n)
        mine[n] = true
        return n
    end
    local function Go(mapID, x, y)
        player.map, player.x, player.y = mapID, x or player.x, y or player.y
        fire("ZONE_CHANGED_NEW_AREA") advance(1)
    end
    local function Walk(yards) player.x = player.x + yards * YD end
    local function Dist(n) return ns.Distance(ZONE, player.x, player.y, n.x, n.y) end
    local function On(n) for _, node in pairs(active) do if node == n then return true end end return false end
    local function Count() local c = 0 for _ in pairs(active) do c = c + 1 end return c end
    -- every minimap pin frame that stands for a node, registered or not
    local function InZone()
        local c = 0
        for _, f in ipairs(allFrames) do if f.isMini and f.node and not f.isTarget and f.mapID == ZONE then c = c + 1 end end
        return c
    end
    local function PerfLine()
        local mark = #log
        slash("perf")
        for i = mark + 1, #log do if log[i]:find("^PRINT") and log[i]:find("perf (", 1, true) then return log[i] end end
        error("/gcr perf printed no line")
    end
    local ok, err = pcall(function()
        ns.db.worldPinsHidden, ns.db.miniPinsHidden, ns.db.mapFollowsZones, ns.db.hideGreyNodes = nil, nil, nil, nil
        ns.db.nodes[ZONE] = ns.db.nodes[ZONE] or {}
        ns.ImportQuestieZone(ZONE, true)
        local known = #ns.db.nodes[ZONE]
        assert(known > 300, "test setup: the known spawn points of Stranglethorn are not there (" .. known .. ")")
        -- 300 nodes of your own all over the zone, and markers east of where you stand
        local seed = 7
        local function Rand() seed = (seed * 1103515245 + 12345) % 2147483648 return seed / 2147483648 end
        for _ = 1, 300 do Own(0.02 + Rand() * 0.96, 0.02 + Rand() * 0.96) end
        local X, Y = 0.5, 0.5
        local m390, m420, m445, m520 = Own(X + 390 * YD, Y, "M390"), Own(X + 420 * YD, Y, "M420"), Own(X + 445 * YD, Y, "M445"), Own(X + 520 * YD, Y, "M520")
        local m490 = Own(X + 490 * YD, Y, "M490")
        ns.NotifyNodesChanged()
        Go(ZONE, X, Y)
        ns.TogglePins() ns.TogglePins() advance(4)

        -- 1. only what is near is registered, and all of that
        local near, all = Count(), InZone()
        assert(all >= 304, ("test setup: %d minimap pins for the zone"):format(all))
        assert(near < all / 2, ("%d of the zone's %d minimap pins are registered: not only the near ones"):format(near, all))
        for _, n in pairs(active) do
            assert(Dist(n) <= 400.5, ("a minimap pin %d yd away is registered"):format(Dist(n)))
        end
        for n in pairs(mine) do
            assert(On(n) == (Dist(n) <= 400), ("%s, %d yd away: registered %s"):format(n.name, Dist(n), tostring(On(n))))
        end
        assert(On(m390) and not On(m420) and not On(m445) and not On(m520), "the markers at 390 / 420 / 445 / 520 yd")
        -- (a pin that is not registered is not on the screen either)
        for _, f in ipairs(allFrames) do
            if f.isMini and f.node and not f.isTarget and f.mapID == ZONE and not active[f] then
                assert(not f:IsShown(), "a minimap pin that is not registered is shown")
            end
        end

        -- 2. /gcr perf says both numbers
        local line = PerfLine()
        local pn, pm = line:match("minimap pins: (%d+) near / (%d+) in zone")
        assert(pn, "/gcr perf does not say the minimap pins: " .. line)
        assert(tonumber(pn) == near and tonumber(pm) == all, ("/gcr perf says %s near / %s in zone, registered are %d of %d"):format(pn, pm, near, all))

        -- 3. on at 400 yd, off only beyond 450 yd: a pin at the edge does not flicker
        Walk(-35) advance(3) -- M390 is 425 yd away now
        assert(On(m390), "a pin 425 yd away that was on went off (it stays to 450 yd)")
        assert(not On(m420), "M420")
        Walk(-30) advance(3) -- 455 yd
        assert(not On(m390), "a pin 455 yd away is still registered")
        Walk(30) advance(3) -- 425 yd again
        assert(not On(m390), "a pin 425 yd away that was off came on (only from 400 yd)")
        Walk(30) advance(3) -- 395 yd
        assert(On(m390), "a pin 395 yd away is not registered")
        Walk(5) advance(3) -- where we began

        -- 4. while you walk: after 50 yd at once, else every 2 s at the latest
        Walk(60) advance(0.6) -- M420 is 360 yd away, M445 385 yd
        assert(On(m420) and On(m445), "60 yd walked: the pins that came into reach are not there within a moment")
        assert(not On(m520) and not On(m490), "M490 is 430 yd away, M520 460 yd")
        Walk(40) advance(0.6) -- M490 390 yd: in reach, but 40 yd since the last look, and that was a moment ago
        assert(not On(m490), "40 yd after a look, within 2 s: looked again (a look is due after 50 yd or 2 s)")
        advance(2)
        assert(On(m490), "a pin in reach is not there 2 s later")
        Walk(70) advance(0.6) -- M520 350 yd
        assert(On(m520), "M520")
        -- standing still: nothing is registered or taken off
        local before = adds
        advance(30)
        assert(adds == before, "pins were registered while you stood still")
        -- every pin that is on is in reach, every node of yours in 400 yd is on
        for _, n in pairs(active) do assert(Dist(n) <= 450.5, ("after walking: a pin %d yd away"):format(Dist(n))) end
        for n in pairs(mine) do if Dist(n) <= 400 then assert(On(n), ("after walking: %s, %d yd away, has no pin"):format(n.name, Dist(n))) end end

        -- 5. a node you find where you stand has its pin at once; one that comes from far away has none
        local found = Own(player.x + 5 * YD, player.y, "Found")
        ns.NotifyNodesChanged("add", ZONE, found)
        assert(On(found), "the node you just found has no minimap pin")
        local far = Own(player.x - 1200 * YD, player.y, "Far")
        ns.NotifyNodesChanged("add", ZONE, far)
        assert(not On(far), "a new node 1200 yd away has a minimap pin")
        assert(InZone() == all + 2, "the two new nodes are not counted in the zone")
        -- ... and it is there when you get to it
        local hereX = player.x
        player.x = far.x + 100 * YD advance(3)
        assert(On(far) and not On(found), "1100 yd further: the pins did not follow")
        player.x = hereX advance(3)
        assert(On(found) and not On(far), "back again: the pins did not follow")

        -- 6. another zone and back, another continent and back: near ones only
        Go(1433) Go(ZONE)
        for _, n in pairs(active) do assert(Dist(n) <= 450.5, "after a zone change: a far pin") end
        assert(On(found) and On(m520) and not On(far), "after a zone change: the near pins are not there")
        Go(1412) Go(ZONE) advance(4)
        for _, n in pairs(active) do assert(Dist(n) <= 450.5, "after a continent change: a far pin") end
        assert(On(found) and On(m520) and not On(far), "after a continent change: the near pins are not there")
        local nearNow = Count()

        -- 7. without world map pins the minimap pin holds the kinds of a shared spot: also for a spot you walk to
        local copper = { id = "o1731", name = "Copper Vein", type = "ore", x = player.x - 900 * YD, y = player.y, count = 0, last = 0, source = "questie" }
        local tin = { id = "o1732", name = "Tin Vein", type = "ore", x = copper.x, y = copper.y, count = 0, last = 0, source = "questie" }
        table.insert(ns.db.nodes[ZONE], copper) table.insert(ns.db.nodes[ZONE], tin)
        mine[copper], mine[tin] = true, true
        ns.db.worldPinsHidden = true
        ns.NotifyNodesChanged() advance(4)
        assert(Count() == nearNow, ("without world map pins %d minimap pins are registered, with them %d"):format(Count(), nearNow))
        assert(not On(copper) and not On(tin), "the far shared spot has a pin")
        player.x = copper.x + 50 * YD advance(3)
        local spot
        for icon, n in pairs(active) do if n == copper or n == tin then spot = icon end end
        assert(spot and spot.others and #spot.others == 1, "the shared spot you walked to: no pin with both kinds")
        player.x = hereX advance(3)
        ns.db.worldPinsHidden = nil

        -- 8. "Show nodes on the minimap" off: none, also while walking
        ns.db.miniPinsHidden = true
        ns.NotifyNodesChanged() advance(4)
        assert(Count() == 0, "minimap pins off: " .. Count() .. " are registered")
        Walk(200) advance(5) Walk(-200) advance(5)
        assert(Count() == 0, "minimap pins off: walking registered some")
        local off = PerfLine()
        assert(off:find("minimap pins: 0 near / 0 in zone", 1, true), "/gcr perf with minimap pins off: " .. off)
        ns.db.miniPinsHidden = nil
        ns.NotifyNodesChanged() advance(4)
        assert(Count() == nearNow, ("minimap pins on again: %d registered, before %d"):format(Count(), nearNow))

        -- 9. what it costs (the mock's clock, a rough bound): HereBeDragons works
        -- through every registered pin on each frame you move - the same work
        -- per pin here (offset, distance, in the circle or not)
        -- (drawMinimapPin of HereBeDragons-Pins-2.0, round minimap, 233 yd, not rotating)
        local function Frame(list)
            local px, py, radius, half = player.x * 5000, player.y * 3333, 233, 70
            for i = 1, #list do
                local pin = list[i]
                local xDist, yDist = px - pin.node.x * 5000, py - pin.node.y * 3333
                local diffX, diffY = xDist / radius, yDist / radius
                local dist = (diffX * diffX + diffY * diffY) / 0.9 ^ 2
                if dist <= 1 then
                    pin:Show()
                    pin:ClearAllPoints()
                    pin:SetPoint("CENTER", UIParent, "CENTER", diffX * half, -diffY * half)
                else
                    pin:Hide()
                end
            end
        end
        local zonePins, nearPins = {}, {}
        for _, f in ipairs(allFrames) do if f.isMini and f.node and not f.isTarget and f.mapID == ZONE then zonePins[#zonePins + 1] = f end end
        for icon in pairs(active) do nearPins[#nearPins + 1] = icon end
        local function Ms(fn, times)
            local t0 = os.clock()
            for _ = 1, times do fn() end
            return (os.clock() - t0) * 1000 / times
        end
        local inZone = InZone()
        local was, now = Ms(function() Frame(zonePins) end, 300), Ms(function() Frame(nearPins) end, 300)
        for _, f in ipairs(zonePins) do if not active[f] then f:Hide() end end
        -- one look of ours while walking: 60 yd on, look, 60 yd back, look
        local look = Ms(function() Walk(60) ns.MiniPinLook() Walk(-60) ns.MiniPinLook() end, 300) / 2
        for _, n in pairs(active) do assert(Dist(n) <= 450.5, "after the looks of the measurement: a far pin") end
        note(("MEASURE P1 minimap pins registered: %d of the zone's %d"):format(nearNow, inZone))
        note(("MEASURE P1 work per frame while moving (model of the library's loop): %.4f ms -> %.4f ms"):format(was, now))
        note(("MEASURE P1 one look of ours while walking (at most every 0.5 s): %.3f ms"):format(look))
        assert(nearNow * 3 < inZone, ("%d of %d pins registered in a full zone"):format(nearNow, inZone))
        assert(now * 5 < was, ("the work per frame went from %.4f ms to %.4f ms only"):format(was, now))
        assert(look < 5, ("one look while walking takes %.2f ms"):format(look))
    end)
    for i = #ns.db.nodes[ZONE], 1, -1 do if mine[ns.db.nodes[ZONE][i]] then table.remove(ns.db.nodes[ZONE], i) end end
    ns.db.worldPinsHidden, ns.db.miniPinsHidden, ns.db.mapFollowsZones, ns.db.hideGreyNodes = saved.world, saved.mini, saved.follow, saved.grey
    pins.AddMinimapIconMap, pins.RemoveMinimapIcon = keepAdd, keepRem
    ns.NotifyNodesChanged()
    Go(saved.map, saved.x, saved.y) advance(4)
    assert(ok, err)
end)
step("Sync: a node that is sent again is found by its exact place - same result, less time in the handlers (v0.1.23 P2)", function()
    -- Sven, 13.11.2026, /gcr perf: 580 messages and 4,460 nodes a minute,
    -- 380 ms a minute in the handlers. Most of the nodes were sent again and
    -- again: six or seven players of 0.1.21 answer one zone question with the
    -- same nodes. Every one of them went through the search by distance -
    -- the known nodes of its kind in the zone, then the waiting reports.
    -- Now an entry with the same kind and the same numbers as one seen
    -- before is looked up by them. What happens with it is the same.
    local db = ns.db.sync
    local ZONES = { 1434, 1433, 1431, 1437, 1436 }
    local saved = { enabled = db.enabled, public = db.public, pending = db.pending, counts = db.counts, blocked = db.blocked,
        announce = db.announceOn, debug = ns.db.debug, clock = debugprofilestop, nodes = {}, off = ns.SyncExactOff }
    for _, z in ipairs(ZONES) do saved.nodes[z] = ns.db.nodes[z] end
    -- a clock finer than os.clock (1 ms on Windows), where the runner has one
    local okFfi, ffi = pcall(require, "ffi")
    if okFfi then
        local okDef = pcall(ffi.cdef, "int QueryPerformanceCounter(int64_t *c); int QueryPerformanceFrequency(int64_t *f);")
        local c, f = ffi.new("int64_t[1]"), ffi.new("int64_t[1]")
        if okDef and pcall(function() return ffi.C.QueryPerformanceFrequency(f) end) and tonumber(f[0]) > 0 then
            local freq = tonumber(f[0])
            debugprofilestop = function() ffi.C.QueryPerformanceCounter(c) return tonumber(c[0]) * 1000 / freq end
        end
    end
    local function msg(text, who) fire("CHAT_MSG_ADDON", "Gathercraft", text, "CHANNEL", who, nil, nil, nil, "GathercraftSync") end
    local seed = 11
    local function Rand() seed = (seed * 1103515245 + 12345) % 2147483648 return seed / 2147483648 end
    local KINDS = { "o1731", "o1732", "o1735", "o1617", "o1618", "o1619", "o1620", "o2045" }
    local CODE = { o1731 = "o", o1732 = "o", o1735 = "o", o1617 = "h", o1618 = "h", o1619 = "h", o1620 = "h", o2045 = "h" }
    -- what the players of a zone know: 150 spots, far from each other (a grid of 15 x 10)
    local sets = {}
    for zi, z in ipairs(ZONES) do
        local set = {}
        for i = 0, 149 do
            local id = KINDS[(i + zi) % #KINDS + 1]
            set[#set + 1] = { id = id, code = CODE[id], xs = 500 + (i % 15) * 600 + math.floor(Rand() * 200), ys = 700 + math.floor(i / 15) * 880 + math.floor(Rand() * 300) }
        end
        sets[z] = set
    end
    -- what you have: the zone's known spawn points, and every second spot of the 150 as a node of your own
    local function Fresh()
        for _, z in ipairs(ZONES) do
            local list = {}
            for _, n in ipairs(saved.nodes[z] or {}) do list[#list + 1] = n end
            for i, e in ipairs(sets[z]) do
                if i % 2 == 0 then
                    list[#list + 1] = { id = e.id, name = "Node", type = e.code == "h" and "herb" or "ore", x = e.xs / 10000, y = e.ys / 10000, count = 1, last = 1, item = 2447 }
                end
            end
            ns.db.nodes[z] = list
        end
        db.pending, db.counts = {}, nil
        ns.NotifyNodesChanged()
        advance(70) -- (the limit per player counts over a minute)
    end
    -- every node as it is afterwards, and every report that still waits
    local function State()
        local out = {}
        local function Names(t)
            local l = {}
            for k in pairs(t or {}) do l[#l + 1] = tostring(k) end
            table.sort(l)
            return table.concat(l, "+")
        end
        for _, z in ipairs(ZONES) do
            for i, n in ipairs(ns.db.nodes[z]) do
                if n.source ~= "questie" or n.heard then
                    out[#out + 1] = ("%d#%d %s %.4f %.4f %s h%s [%s] c%s p%s"):format(z, i, tostring(n.id), n.x, n.y, tostring(n.source), tostring(n.heard), Names(n.heardBy), tostring(n.count), tostring(n.parked and 1))
                end
            end
            for i, p in ipairs(db.pending[z] or {}) do
                out[#out + 1] = ("%d pending#%d %s %.4f %.4f rc%d by %s [%s]"):format(z, i, tostring(p.id), p.x, p.y, p.rc, tostring(p.by), Names(p.reporters))
            end
        end
        local c = db.counts or {}
        out[#out + 1] = ("counts %s %s %s %s %s"):format(tostring(c.received), tostring(c.new), tostring(c.trusted), tostring(c.public), tostring(c.confirmed))
        return out
    end
    local function Same(a, b, what)
        assert(#a == #b, ("%s: %d lines without the lookup, %d with it"):format(what, #a, #b))
        for i = 1, #a do assert(a[i] == b[i], ("%s: without the lookup '%s', with it '%s'"):format(what, a[i], b[i])) end
    end
    -- the handler time /gcr perf counted for the last full minute
    local function HandlerMs()
        local mark = #log
        slash("perf")
        for i = mark + 1, #log do
            local ms = log[i]:match("time in the receive and send handlers ([%d%.]+) ms")
            if ms and log[i]:find("last full minute", 1, true) then return tonumber(ms) end
        end
        error("/gcr perf: no handler time of the last full minute")
    end
    local function Minute(send)
        advance(60 - GetTime() % 60 + 0.5)
        local count = 0
        send(function(text, who)
            msg(text, who)
            count = count + 1
            if count % 40 == 0 then advance(1) end -- (40 messages a second are read)
        end)
        advance(60 - GetTime() % 60 + 0.5)
        return HandlerMs()
    end
    -- answers: six players send the 150 spots of each zone, eight to a message,
    -- turn by turn; every fifth entry of a player is his own reading of the
    -- place (up to 1.5 yd off), the others are the numbers everybody has
    local function Answers(deliver)
        for zi, z in ipairs(ZONES) do
            local texts = {}
            for r = 1, 6 do
                texts[r] = {}
                local parts = {}
                for i, e in ipairs(sets[z]) do
                    local xs, ys = e.xs, e.ys
                    if (i + r) % 5 == 0 then xs, ys = xs + r % 3 + 1, ys + r % 2 end
                    parts[#parts + 1] = ("%s,%s,%d,%d,2447"):format(e.id, e.code, xs, ys)
                    if #parts == 8 or i == #sets[z] then
                        texts[r][#texts[r] + 1] = "N:" .. z .. ";" .. table.concat(parts, ";")
                        parts = {}
                    end
                end
            end
            for m = 1, #texts[1] do
                for r = 1, 6 do deliver(texts[r][m], ("Answer%d%d-Realm"):format(zi, r)) end
            end
        end
    end
    -- an evening without questions: 300 harvests of 60 players, one node a
    -- message, each at its own place; half of them where you know a node
    local function Harvests(deliver)
        local s = 99
        local function R() s = (s * 1103515245 + 12345) % 2147483648 return s / 2147483648 end
        for k = 1, 300 do
            local z = ZONES[k % #ZONES + 1]
            local e = sets[z][math.floor(R() * 150) + 1]
            local xs, ys = e.xs + math.floor(R() * 7) - 3, e.ys + math.floor(R() * 7) - 3
            if k % 2 == 0 then xs, ys = math.floor(R() * 9000) + 500, math.floor(R() * 9000) + 500 end
            deliver(("N:%d;%s,%s,%d,%d,2447"):format(z, e.id, e.code, xs, ys), ("Farmer%d-Realm"):format(k % 60))
        end
    end
    local function Run(send, off)
        ns.SyncExactOff = off or nil
        Fresh()
        local ms = Minute(send)
        return ms, State()
    end
    -- the same once more, a good minute later: by then you know every one of the nodes
    local function RunAgain(send, off)
        ns.SyncExactOff = off or nil
        Fresh()
        Minute(send)
        advance(70)
        local ms = Minute(send)
        return ms, State()
    end
    local ok, err = pcall(function()
        db.enabled, db.public, db.blocked, db.announceOn, ns.db.debug = true, true, {}, nil, nil
        for _, z in ipairs(ZONES) do ns.ImportQuestieZone(z, true) saved.nodes[z] = ns.db.nodes[z] end
        ns.SyncExactOff = nil

        -- The time in the handlers, on the mock's clock: a fixed number of
        -- minutes, by turns without and with the lookup (ABAB..., the same
        -- number each way, the garbage collected before every one), and the
        -- median of each way compared. Measured all of one way first, the
        -- way measured second came out slower (about 10 %, the other way
        -- round as much faster) - that is the order, not the lookup.
        -- And the same result, node by node and report by report: what the
        -- last minute of each way left behind.
        local TURNS = 5
        local series = {}
        local function Median(t)
            local s = {}
            for i, v in ipairs(t) do s[i] = v end
            table.sort(s)
            return s[(#s + 1) / 2]
        end
        local function Pair(run, send, what)
            local off, on, offState, onState = {}, {}, nil, nil
            for _ = 1, TURNS do
                collectgarbage("collect")
                local ms, left = run(send, true)
                off[#off + 1], offState = ms, left
                collectgarbage("collect")
                ms, left = run(send, false)
                on[#on + 1], onState = ms, left
            end
            series[#series + 1] = { what = what, off = off, on = on }
            return Median(off), Median(on), offState, onState
        end
        -- three kinds of minute, 570 messages / 4500 nodes each where it is answers:
        --   again: answers for nodes you all know by now (what Sven's minute mostly was)
        --   first: answers you hear for the first time - half of the nodes are new and become nodes of yours
        --   harvests: an evening without questions, 300 messages with a node each
        local rOff, rOn, without3, with3 = Pair(RunAgain, Answers, "again")
        local aOff, aOn, without, with = Pair(Run, Answers, "first")
        local hOff, hOn, without2, with2 = Pair(Run, Harvests, "harvests")
        for _, s in ipairs(series) do
            local function List(t) local o = {} for i, v in ipairs(t) do o[i] = ("%.1f"):format(v) end return table.concat(o, " ") end
            note(("MEASURE P2 series %s (%d each way, by turns): without %s | with %s"):format(s.what, TURNS, List(s.off), List(s.on)))
        end
        Same(without, with, "answers")
        Same(without2, with2, "harvests")
        Same(without3, with3, "the answers again")
        assert(#with == 751, "test setup: the answers left " .. #with .. " lines (150 nodes in each of 5 zones, and the counts)")
        local function Less(off, on) return off > 0 and (1 - on / off) * 100 or 0 end
        note(("MEASURE P2 answers for nodes you know: handlers %.1f ms -> %.1f ms a minute (%d %% less)"):format(rOff, rOn, Less(rOff, rOn)))
        note(("MEASURE P2 answers heard for the first time (375 new nodes): handlers %.1f ms -> %.1f ms (%d %% less)"):format(aOff, aOn, Less(aOff, aOn)))
        note(("MEASURE P2 harvests, 300 messages with a node each: handlers %.1f ms -> %.1f ms"):format(hOff, hOn))
        assert(rOff > 2, ("test setup: the answers take %.1f ms in the handlers - too little to compare"):format(rOff))
        assert(rOn <= rOff * 0.6, ("answers for nodes you know: %.1f ms in the handlers without the lookup, %.1f ms with it - not 40 %% less"):format(rOff, rOn))
        assert(aOn <= aOff * 1.1 + 0.5, ("answers heard for the first time: %.1f ms without the lookup, %.1f ms with it - worse"):format(aOff, aOn))
        assert(hOn <= hOff * 1.25 + 0.3, ("harvests: %.1f ms without the lookup, %.1f ms with it - worse"):format(hOff, hOn))
    end)
    ns.SyncExactOff = saved.off
    debugprofilestop = saved.clock
    for _, z in ipairs(ZONES) do ns.db.nodes[z] = saved.nodes[z] end
    db.enabled, db.public, db.pending, db.counts, db.blocked, db.announceOn, ns.db.debug = saved.enabled, saved.public, saved.pending, saved.counts, saved.blocked, saved.announce, saved.debug
    ns.NotifyNodesChanged()
    advance(70)
    assert(ok, err)
end)
step("Sync: the lookup by exact place stays right when nodes and reports change under it (v0.1.23 P2)", function()
    -- What the lookup remembers has to go the moment it is not true any
    -- more: a node that moved, went or came, a report that was dropped. The
    -- same story is played with the lookup and without it, and after every
    -- change the same entry is sent again: both ends have to agree.
    local db = ns.db.sync
    local Z = 1434
    local saved = { enabled = db.enabled, public = db.public, pending = db.pending, counts = db.counts, blocked = db.blocked,
        announce = db.announceOn, nodes = ns.db.nodes[Z], off = ns.SyncExactOff }
    local function msg(text, who, chan) fire("CHAT_MSG_ADDON", "Gathercraft", text, chan or "CHANNEL", who, nil, nil, nil, "GathercraftSync") end
    local function Story(off)
        ns.SyncExactOff = off or nil
        local lines = {}
        local list = {}
        local function Node(xs, ys, extra)
            local n = { id = "o1731", name = "Copper Vein", type = "ore", x = xs / 10000, y = ys / 10000, count = 1, last = 1, item = 2770 }
            for k, v in pairs(extra or {}) do n[k] = v end
            list[#list + 1] = n
            return n
        end
        local a = Node(3000, 3000)
        local b = Node(5000, 5000)
        local parked = Node(7000, 7000, { source = "sync", parked = 1, heard = 1, heardBy = { Old = true } })
        ns.db.nodes[Z] = list
        db.pending, db.counts = {}, nil
        ns.NotifyNodesChanged()
        advance(70)
        local n = 0
        local function Say(xs, ys, who, chan)
            n = n + 1
            msg(("N:%d;o1731,o,%d,%d,2770"):format(Z, xs, ys), who or ("P" .. n .. "-Realm"), chan)
            if n % 30 == 0 then advance(1) end
        end
        local function Mark(what)
            local function Names(t) local l = {} for k in pairs(t or {}) do l[#l + 1] = tostring(k) end table.sort(l) return table.concat(l, "+") end
            local out = { what }
            for i, x in ipairs(ns.db.nodes[Z]) do
                out[#out + 1] = ("n%d %.4f %.4f %s h%s [%s] p%s"):format(i, x.x, x.y, tostring(x.source), tostring(x.heard), Names(x.heardBy), tostring(x.parked and 1))
            end
            for i, p in ipairs(db.pending[Z] or {}) do
                out[#out + 1] = ("w%d %.4f %.4f rc%d %s [%s]"):format(i, p.x, p.y, p.rc, tostring(p.by), Names(p.reporters))
            end
            lines[#lines + 1] = table.concat(out, " | ")
        end
        -- a known node, said twice by its exact place
        Say(3000, 3000) Say(3000, 3000) Mark("known twice")
        -- it moves 40 yd (a harvest shifted it): the same numbers are a new report now
        a.x = a.x + 0.008
        ns.NotifyNodesChanged("update", Z, a)
        Say(3000, 3000) Mark("after the node moved away")
        -- ... and back: known again, the report it left stays where it is
        a.x = a.x - 0.008
        ns.NotifyNodesChanged("update", Z, a)
        Say(3000, 3000) Mark("after the node moved back")
        -- the node is deleted: unknown again
        Say(5000, 5000) Say(5000, 5000)
        for i = #list, 1, -1 do if list[i] == b then table.remove(list, i) end end
        ns.NotifyNodesChanged()
        Say(5000, 5000) Mark("after the node was deleted")
        -- an unknown place said twice, then a node of yours appears 4 yd from it: the third goes to the node
        Say(6000, 2000) Say(6000, 2000)
        local c = Node(6008, 2000)
        ns.NotifyNodesChanged("add", Z, c)
        Say(6000, 2000) Mark("a node appeared next to a waiting report")
        -- a nearer node appears next to a place that was answered by a farther one
        local far = Node(2000, 6000)
        ns.NotifyNodesChanged("add", Z, far)
        Say(2015, 6000) Say(2015, 6000)
        local nearer = Node(2018, 6000)
        ns.NotifyNodesChanged("add", Z, nearer)
        Say(2015, 6000) Mark("a nearer node appeared")
        -- three strangers: the third makes it a node, the fourth and fifth only know it
        Say(8000, 3000) Say(8000, 3000) Say(8000, 3000) Say(8000, 3000) Say(8001, 3000) Mark("imported at the third, known after")
        -- a parked node comes back when somebody new names it, by exact place
        Say(7000, 7000) Mark("the parked node")
        -- the same player again and again: counted once
        Say(4000, 8000, "Echo-Realm") Say(4000, 8000, "Echo-Realm") Say(4000, 8000, "Echo-Realm") Mark("one player three times")
        -- more reports than a zone keeps (300): the oldest go, and what was dropped is new when it is said again
        advance(70)
        for k = 1, 310 do
            msg(("N:%d;o1735,o,%d,%d,2772"):format(Z, 100 + (k % 31) * 300, 200 + math.floor(k / 31) * 700), ("Flood%d-Realm"):format(k % 20))
            if k % 30 == 0 then advance(1) end
        end
        Mark("310 reports")
        advance(70)
        msg(("N:%d;o1735,o,%d,%d,2772"):format(Z, 100 + 1 * 300, 200), "Late-Realm")
        msg(("N:%d;o1735,o,%d,%d,2772"):format(Z, 100 + 1 * 300, 200), "Later-Realm")
        Mark("the first of them again")
        -- old reports are dropped (a week): said again they start from one
        Say(1000, 9000) Say(1000, 9000)
        for _, p in ipairs(db.pending[Z]) do if p.x == 0.1 and p.y == 0.9 then p.first = time() - 30 * 24 * 3600 end end
        ns.DropOldPending()
        Say(1000, 9000) Mark("after old reports were dropped")
        -- /gcr sync clear and the guild: taken at once, then known
        Say(9000, 9000) Say(9000, 9000, "Mate-Realm", "GUILD") Say(9000, 9000) Mark("a guild mate")
        -- the reports are replaced as a whole (a login does that): nothing is remembered from the old list
        Say(1500, 1500)
        db.pending = {}
        Say(1500, 1500) Mark("a new list of reports")
        return lines
    end
    local ok, err = pcall(function()
        db.enabled, db.public, db.blocked, db.announceOn = true, true, {}, nil
        local without = Story(true)
        local with = Story(false)
        assert(#without == #with and #with >= 14, "test setup: the two stories differ in length")
        for i = 1, #with do
            assert(without[i] == with[i], ("%s - without the lookup: %s ### with it: %s"):format(with[i]:match("^[^|]*"), without[i]:sub(1, 600), with[i]:sub(1, 600)))
        end
        -- (the story does what it says: these are the ends it has to reach)
        local function Has(i, text) assert(with[i]:find(text, 1, true), ("test setup, '%s': no '%s' in %s"):format(with[i]:match("^[^|]*"), text, with[i]:sub(1, 400))) end
        Has(1, "h2 [P1-Realm+P2-Realm]") Has(2, "w1 0.3000 0.3000 rc1 P3-Realm") Has(3, "h3 [P1-Realm+P2-Realm+P4-Realm]")
        Has(4, "w2 0.5000 0.5000 rc1 P7-Realm") Has(5, "w3 0.6000 0.2000 rc2 P8-Realm [P8-Realm+P9-Realm]")
        Has(8, "0.7000 0.7000 sync h2 [Old+P19-Realm] pnil") Has(9, "w4 0.4000 0.8000 rc1 Echo-Realm [Echo-Realm]")
        Has(11, "rc2 Late-Realm [Late-Realm+Later-Realm]") Has(12, "0.1000 0.9000 rc1 P25-Realm")
        Has(13, "sync h3 [Mate-Realm+P26-Realm+P28-Realm]") Has(14, "w1 0.1500 0.1500 rc1 P30-Realm")
    end)
    ns.SyncExactOff = saved.off
    ns.db.nodes[Z] = saved.nodes
    db.enabled, db.public, db.pending, db.counts, db.blocked, db.announceOn = saved.enabled, saved.public, saved.pending, saved.counts, saved.blocked, saved.announce
    ns.NotifyNodesChanged()
    advance(70)
    assert(ok, err)
end)
step("Options: a page of its own for fishing - four switches with a line each, the same saved values (v0.1.23 P4)", function()
    -- A player on Discord did not find "Hide the fishing window": the four
    -- fishing switches stood at the end of General, under "Other". They have
    -- a page now, each with a line that says what it does.
    local opts = _G.GathercraftOptions
    local LABELS = {
        "Fish key applies a lure when the pole has none",
        "Hide the fishing window",
        "Mark my bobber",
        "Louder bobber splash while fishing",
    }
    local HINTS = {
        "One press puts a lure from your bags on the pole, the next one casts.",
        "The small window with your catch and gold per hour while you fish. The catch is counted all the same.",
        "The game's own icon above your bobber while your line is out. Afterwards your setting is back.",
        "Sound effects at full volume, music and ambience quiet, while your line is out. Afterwards your volumes are back.",
    }
    local DESC = "The fish key, the fishing window and your bobber."
    local function Find(key)
        local found
        for _, f in ipairs(allFrames) do
            if f.__kind == "FontString" and f.__text == ns.L[key] then
                local p = f.__parent
                while p and not p.key do p = p.__parent end
                if p then found = f end
            end
        end
        return found
    end
    local function PageOf(f)
        local p = f and f.__parent
        while p and not p.key do p = p.__parent end
        return p and p.key
    end
    local saved = { lang = ns.db.language, section = ns.db.optionsSection, lure = ns.db.fishLure, panel = ns.db.fishPanelHidden,
        mark = ns.db.fishMarkBobber, loud = ns.db.fishLoudSplash, height = methods.GetStringHeight }
    local ok, err = pcall(function()
        -- the page, its switches and their lines
        local page
        for i, label in ipairs(LABELS) do
            local fs = Find(label)
            assert(fs, "no switch '" .. label .. "'")
            assert(PageOf(fs) == "fishing", ("'%s' is on the page %s"):format(label, tostring(PageOf(fs))))
            page = page or fs.__parent
            local hint = Find(HINTS[i])
            assert(hint and PageOf(hint) == "fishing", ("no line under '%s' on the fishing page"):format(label))
        end
        assert(Find(DESC) and PageOf(Find(DESC)) == "fishing", "the page does not say what it is about")
        -- (General has them no more. The mock logs in many times, and each
        -- login builds the pages: so every copy is looked at.)
        for _, label in ipairs(LABELS) do
            for _, f in ipairs(allFrames) do
                if f.__kind == "FontString" and f.__text == ns.L[label] and PageOf(f) then
                    assert(PageOf(f) == "fishing", ("'%s' is also on the page %s"):format(label, PageOf(f)))
                end
            end
        end
        -- the list on the left has it, and choosing it shows the page and is remembered
        ns.ShowOptionsSection("fishing")
        assert(page.__shown and ns.db.optionsSection == "fishing", "choosing Fishing does not show its page")
        local navText
        for _, f in ipairs(allFrames) do
            if f.__kind == "FontString" and f.__text == ns.L["Fishing"] and f.__parent and f.__parent.__scripts and f.__parent.__scripts.OnClick and f.__parent.icon then navText = f end
        end
        assert(navText, "no entry 'Fishing' in the list of pages")
        ns.ShowOptionsSection("general")
        assert(not page.__shown, "the fishing page stays over General")
        navText.__parent.__scripts.OnClick(navText.__parent)
        assert(page.__shown, "a click on Fishing does not show its page")

        -- the same saved values as before, switch by switch
        local function Box(label)
            local box = Find(label).__pts.TOPLEFT[1]
            assert(box and box.__kind == "CheckButton", "'" .. label .. "' has no box")
            return box
        end
        local function Click(label, on)
            local box = Box(label)
            box:SetChecked(on)
            box.__scripts.OnClick(box)
        end
        ns.db.fishLure, ns.db.fishPanelHidden, ns.db.fishMarkBobber, ns.db.fishLoudSplash = nil, nil, nil, nil
        opts:Refresh()
        assert(Box(LABELS[1]):GetChecked() and not Box(LABELS[2]):GetChecked() and Box(LABELS[3]):GetChecked() and not Box(LABELS[4]):GetChecked(),
            "never touched: lure and mark are on, hide and louder are off")
        Click(LABELS[1], false) assert(ns.db.fishLure == false, "lure off is saved as " .. tostring(ns.db.fishLure))
        Click(LABELS[1], true) assert(ns.db.fishLure == true, "lure on is saved as " .. tostring(ns.db.fishLure))
        Click(LABELS[2], true) assert(ns.db.fishPanelHidden == true, "hide on is saved as " .. tostring(ns.db.fishPanelHidden))
        Click(LABELS[2], false) assert(ns.db.fishPanelHidden == nil, "hide off is saved as " .. tostring(ns.db.fishPanelHidden))
        Click(LABELS[3], false) assert(ns.db.fishMarkBobber == false, "mark off is saved as " .. tostring(ns.db.fishMarkBobber))
        Click(LABELS[3], true) assert(ns.db.fishMarkBobber == true, "mark on is saved as " .. tostring(ns.db.fishMarkBobber))
        Click(LABELS[4], true) assert(ns.db.fishLoudSplash == true, "louder on is saved as " .. tostring(ns.db.fishLoudSplash))
        Click(LABELS[4], false) assert(ns.db.fishLoudSplash == nil, "louder off is saved as " .. tostring(ns.db.fishLoudSplash))

        -- every language has the new texts
        for lang, d in pairs(ns.Locales) do
            for _, text in ipairs({ DESC, HINTS[1], HINTS[2], HINTS[3], HINTS[4] }) do
                assert(d[text] and d[text] ~= text, lang .. ": not translated: " .. text)
            end
        end

        -- nothing is cut, in every language: the rows wrap and stay above the
        -- footer, the name fits the list. Mock text layout: 6 px a Latin
        -- letter, 11 px a CJK sign, 12 px a line - no real font metrics.
        local function Px(text)
            local px = 0
            for ch in (text or ""):gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", ""):gmatch("[%z\1-\127\194-\244][\128-\191]*") do px = px + (#ch >= 3 and 11 or 6) end
            return px
        end
        local WIDTH = 470
        methods.GetStringHeight = function(self)
            local w = (self.__parent and self.__parent.__w or WIDTH) - 34
            return 12 * math.max(1, math.ceil(Px(self.__text) / w))
        end
        page.__w = WIDTH
        local ROOM = 640 - 112 - 18 - 4 - 66
        local wrapped = 0
        for _, lang in ipairs(ns.LANGUAGES) do
            if lang.code ~= "auto" then
                ns.db.language = lang.code ns.ApplyLanguage() opts:Refresh()
                ns.ShowOptionsSection("fishing")
                local y, bottom = nil, 0
                for i, label in ipairs(LABELS) do
                    local fs, hint = Find(label), Find(HINTS[i])
                    assert(fs and hint, lang.code .. ": '" .. label .. "' or its line is not there")
                    local box = fs.__pts.TOPLEFT[1]
                    local top = box.__pts.TOPLEFT[2]
                    assert(not y or top <= y, ("%s: '%s' starts at %s, the row above ends at %s"):format(lang.code, label, top, tostring(y)))
                    local labelEnd = top - 5 - fs:GetStringHeight()
                    local hintTop = hint.__pts.TOPLEFT[2]
                    assert(hintTop <= labelEnd + 2, ("%s: the line under '%s' starts at %s, the label ends at %s"):format(lang.code, label, hintTop, labelEnd))
                    y = hintTop - hint:GetStringHeight()
                    bottom = -y
                    if hint:GetStringHeight() > 12 then wrapped = wrapped + 1 end
                    assert(fs.__pts.RIGHT and fs.__pts.RIGHT[1] == page and hint.__pts.RIGHT and hint.__pts.RIGHT[1] == page, lang.code .. ": a text is not held to the page width")
                end
                assert(bottom <= ROOM, ("%s: the fishing page goes down to %d px of %d"):format(lang.code, bottom, ROOM))
                assert(Px(ns.L["Fishing"]) <= 160 - 8 - 18 - 7 - 4, ("%s: '%s' is too wide for the list of pages"):format(lang.code, ns.L["Fishing"]))
            end
        end
        assert(wrapped > 0, "test setup: no line wrapped in any language")
        methods.GetStringHeight = saved.height
        page.__w = nil
        ns.db.language = saved.lang ns.ApplyLanguage() opts:Refresh()

        -- General has its rows back (one of the four went to the ping switch
        -- right away: P3), and every page that does not flow still ends above the footer
        local used = ns.OptionsUsedHeight()
        assert(used.general <= ROOM - 3 * 26, ("General still goes down to %d px"):format(used.general))
        for key, h in pairs(used) do
            if key ~= "level" and key ~= "fishing" then assert(h <= ROOM, ("Options %s: %d px of %d"):format(key, h, ROOM)) end
        end
    end)
    methods.GetStringHeight = saved.height
    ns.db.fishLure, ns.db.fishPanelHidden, ns.db.fishMarkBobber, ns.db.fishLoudSplash = saved.lure, saved.panel, saved.mark, saved.loud
    ns.db.language = saved.lang ns.ApplyLanguage()
    ns.ShowOptionsSection(saved.section)
    opts:Refresh()
    assert(ok, err)
end)
step("Run: the ping at a route point has a switch, on unless you turn it off (v0.1.23 P3)", function()
    -- Sven, and a player on CurseForge ("Is there an option to disable the
    -- ping sound?"): every point of a run you reach plays the map ping, and
    -- nothing turned it off. Mulgore in the mock: 1 yd = 0.0002 map x.
    local LABEL = "Ping when I reach a route point"
    local PING = 3175
    local keep = { nodes = ns.db.nodes[1412], arrive = ns.db.arriveDist, map = player.map, x = player.x, y = player.y,
        kit = SOUNDKIT.MAP_PING, off = ns.db.routePingOff }
    local function Node(name, id, item, xYd)
        return { id = "o" .. id, name = name, type = "herb", item = item, x = 0.5 + xYd / 5000, y = 0.5, count = 1, last = 1 }
    end
    local function At(xYd) player.map, player.x, player.y = 1412, 0.5 + xYd / 5000, 0.5 end
    local function Wait(s) for _ = 1, s * 2 do advance(0.5) end end
    -- a run to a first point 200 yd away; returns the pings on reaching it and what the run did
    local function Arrive()
        local first, far = Node("Earthroot", 1619, 2449, 0), Node("Peacebloom", 1618, 2447, 2500)
        ns.db.nodes[1412] = { first, far }
        ns.NotifyNodesChanged() advance(1)
        At(-200)
        ns.StartRun("herb", 1412) Wait(1)
        assert(ns.run and ns.run.target == first, "test setup: the run does not go for the first point")
        local mark = #log
        At(-19) Wait(1) -- reached (19 yd, the radius is 20)
        local pings = 0
        for i = mark + 1, #log do if log[i] == "SOUND " .. PING then pings = pings + 1 end end
        local done, target = ns.run and ns.run.done, ns.run and ns.run.target
        ns.StopRun(true)
        return pings, done, target == far
    end
    local ok, err = pcall(function()
        SOUNDKIT.MAP_PING = PING
        ns.db.arriveDist = 20
        -- never touched: the ping is there
        ns.db.routePingOff = nil
        local pings, done, onward = Arrive()
        assert(pings == 1, ("never touched: %d pings at the point"):format(pings))
        assert(done == 1 and onward, "test setup: the point was not reached")
        -- the switch: on a page of the options, ticked
        local label
        for _, f in ipairs(allFrames) do if f.__kind == "FontString" and f.__text == ns.L[LABEL] then label = f end end
        assert(label, "no switch '" .. LABEL .. "' in the options")
        local box = (label.__pts.TOPLEFT and label.__pts.TOPLEFT[1]) or (label.__pts.LEFT and label.__pts.LEFT[1])
        assert(box and box.__kind == "CheckButton" and box.get and box.__scripts.OnClick, "test setup: the switch has no box")
        assert(box.get() == true, "never touched, and the box is empty")
        -- off: no sound, and the run does what it did
        box:SetChecked(false) box.__scripts.OnClick(box)
        assert(ns.db.routePingOff == true and box.get() == false, "unticked is saved as " .. tostring(ns.db.routePingOff))
        local pings2, done2, onward2 = Arrive()
        assert(pings2 == 0, ("unticked: %d pings at the point"):format(pings2))
        assert(done2 == done and onward2 == onward, "unticked: the run does not count the point or does not go on")
        -- on again: nothing is left in the saved data
        box:SetChecked(true) box.__scripts.OnClick(box)
        assert(ns.db.routePingOff == nil and box.get() == true, "ticked again is saved as " .. tostring(ns.db.routePingOff))
        assert(Arrive() == 1, "ticked again: no ping at the point")
        -- every language, and the page still ends above the footer
        for lang, d in pairs(ns.Locales) do assert(d[LABEL] and d[LABEL] ~= LABEL, lang .. ": not translated") end
        local page = label.__parent
        while page and not page.key do page = page.__parent end
        assert(page, "the switch is on no page")
        local used = ns.OptionsUsedHeight()
        assert(used[page.key] <= 640 - 112 - 18 - 4 - 66, ("Options %s: %d px, too long"):format(page.key, used[page.key]))
    end)
    if ns.run then ns.StopRun(true) end
    SOUNDKIT.MAP_PING, ns.db.routePingOff, ns.db.arriveDist = keep.kit, keep.off, keep.arrive
    ns.db.nodes[1412] = keep.nodes
    player.map, player.x, player.y = keep.map, keep.x, keep.y
    ns.NotifyNodesChanged() advance(1)
    GathercraftOptions:Refresh()
    assert(ok, err)
end)
step("Auction house: opening it starts the scan by itself - quiet when it cannot, with a switch (v0.1.23 P5)", function()
    -- Sven, 14.11.2026: the scan is to start when the auction house opens -
    -- opening it is what the player does. The server's 15 minutes count as
    -- before. Live (21:37): ReplicateItems can be called from a timer, the
    -- answer had 313,401 auctions.
    local LABEL = "Scan the auction house automatically when I open it"
    local AHX = C_AuctionHouse
    ns.GetPrice(2447) -- (the price store of this realm is made when it is first asked)
    local p = ns.db.prices[next(ns.db.prices)]
    local keep = { rep = AHX.ReplicateItems, num = AHX.GetNumReplicateItems, info = AHX.GetReplicateItemInfo, off = ns.db.autoScanOff,
        last = p.lastScanStart, scanned = p.scanned, items = p.items, qty = p.qty, seen = p.seen, history = p.history, debug = ns.db.debug,
        after = C_Timer.After }
    keep.history = {}
    for id, text in pairs(p.history) do keep.history[id] = text end -- (the scans below write into it)
    local calls, auctions = 0, {}
    for i = 1, 400 do auctions[i] = { id = ({ 2447, 765, 2449, 2770 })[i % 4 + 1], count = i % 5 + 1, unit = 100 + i % 7 } end
    local function Mock()
        AHX.ReplicateItems = function() calls = calls + 1 end
        AHX.GetNumReplicateItems = function() return #auctions end
        AHX.GetReplicateItemInfo = function(i)
            local a = auctions[i + 1]
            if not a then return nil end
            return "Item", 1, a.count, 1, true, 1, 0, 0, 0, a.unit * a.count, 0, false, nil, "Seller", nil, 0, a.id, true
        end
    end
    -- what was said in chat since the mark (debug lines are not chat lines of the addon)
    local function Said(mark)
        local out = {}
        for i = mark + 1, #log do if log[i]:find("^PRINT") then out[#out + 1] = log[i] end end
        return out
    end
    local function Free() p.lastScanStart = 0 end -- the 15 minutes are over
    local function Close() fire("AUCTION_HOUSE_CLOSED") advance(1) end
    local ok, err = pcall(function()
        Mock()
        AuctionHouseFrame = AuctionHouseFrame or CreateFrame("Frame", "AuctionHouseFrame", UIParent)
        ns.db.autoScanOff, ns.db.debug = nil, nil
        Close()

        -- 1. never touched: the scan starts a moment after the window opened, and its result is said once
        Free()
        calls = 0
        local mark = #log
        fire("AUCTION_HOUSE_SHOW")
        advance(0.2)
        assert(calls == 0, "the scan started before the button was built")
        advance(0.3)
        assert(calls == 1, ("the window is open: %d scans started"):format(calls))
        assert(#Said(mark) == 0, "a scan that started by itself says so in chat: " .. tostring(Said(mark)[1]))
        p.scanned = 0
        fire("REPLICATE_ITEM_LIST_UPDATE") advance(2)
        assert(p.scanned and p.scanned > 0 and p.items[2447], "the answer was not read")
        local said = Said(mark)
        assert(#said == 1 and said[1]:find((ns.L["Auction house scanned: %d auctions, prices for %d items."]):format(400, 4), 1, true),
            ("after the scan chat has %d lines: %s"):format(#said, tostring(said[1])))

        -- 2. again within the 15 minutes: nothing starts, nothing is said
        Close()
        mark = #log
        fire("AUCTION_HOUSE_SHOW") advance(2)
        assert(calls == 1, "opened again within 15 minutes: a scan started")
        assert(#Said(mark) == 0, "opened again within 15 minutes: " .. tostring(Said(mark)[1]))
        -- ... the button still says it: a click names the wait, as before
        mark = #log
        slash("scan")
        assert(#Said(mark) == 1 and Said(mark)[1]:find("15", 1, true), "a click within the 15 minutes says nothing")
        Close()

        -- 3. no answer (another addon used up the server's scan): quiet, and a late answer is still read
        Free()
        mark = #log
        fire("AUCTION_HOUSE_SHOW") advance(1)
        assert(calls == 2, "the 15 minutes are over: no scan started")
        advance(120)
        assert(#Said(mark) == 0, "no answer to a scan that started by itself: " .. tostring(Said(mark)[1]))
        p.scanned = 0
        fire("REPLICATE_ITEM_LIST_UPDATE") advance(2)
        assert(p.scanned > 0, "the late answer was not read")
        Close()

        -- 4. the window closed while the scan waits: quiet
        Free()
        mark = #log
        fire("AUCTION_HOUSE_SHOW") advance(1)
        assert(calls == 3, "test setup: no scan")
        fire("AUCTION_HOUSE_CLOSED") advance(1)
        assert(#Said(mark) == 0, "closed during a scan that started by itself: " .. tostring(Said(mark)[1]))

        -- 5. closed again before the moment is over: nothing starts
        Free()
        fire("AUCTION_HOUSE_SHOW") fire("AUCTION_HOUSE_CLOSED") advance(2)
        assert(calls == 3, "opened and closed at once: a scan started")

        -- 6. a click while it runs says "already running" (the click's own words stay)
        Free()
        fire("AUCTION_HOUSE_SHOW") advance(1)
        assert(calls == 4, "test setup: no scan")
        mark = #log
        slash("scan")
        assert(#Said(mark) == 1 and Said(mark)[1]:find(ns.L["Scan is already running..."], 1, true), "a click during the scan: " .. tostring(Said(mark)[1]))
        fire("REPLICATE_ITEM_LIST_UPDATE") advance(2)
        Close()
        -- ... and a scan you click yourself says what it always said
        Free()
        ns.db.autoScanOff = true
        fire("AUCTION_HOUSE_SHOW") advance(1)
        mark = #log
        slash("scan")
        assert(calls == 5 and Said(mark)[1] and Said(mark)[1]:find(ns.L["Scanning the auction house... (this takes a few seconds)"], 1, true), "a clicked scan does not say that it scans")
        advance(120)
        local late = Said(mark)
        assert(#late == 3 and late[2]:find(ns.L["The auction house didn't answer. Try again later."], 1, true), "a clicked scan without an answer: " .. #late .. " lines")
        Close()

        -- 7. the switch: off, nothing starts by itself
        Free()
        fire("AUCTION_HOUSE_SHOW") advance(2)
        assert(calls == 5, "the option is off: a scan started")
        Close()
        local label
        for _, f in ipairs(allFrames) do if f.__kind == "FontString" and f.__text == ns.L[LABEL] then label = f end end
        assert(label, "no switch '" .. LABEL .. "' in the options")
        local box = (label.__pts.TOPLEFT and label.__pts.TOPLEFT[1]) or (label.__pts.LEFT and label.__pts.LEFT[1])
        assert(box and box.__kind == "CheckButton" and box.get, "test setup: the switch has no box")
        local page = label.__parent
        while page and not page.key do page = page.__parent end
        assert(page and page.key == "alerts", "the switch is on the page " .. tostring(page and page.key))
        assert(box.get() == false, "off, and the box is ticked")
        box:SetChecked(true) box.__scripts.OnClick(box)
        assert(ns.db.autoScanOff == nil and box.get() == true, "ticked is saved as " .. tostring(ns.db.autoScanOff))
        box:SetChecked(false) box.__scripts.OnClick(box)
        assert(ns.db.autoScanOff == true, "unticked is saved as " .. tostring(ns.db.autoScanOff))
        ns.db.autoScanOff = nil
        for lang, d in pairs(ns.Locales) do assert(d[LABEL] and d[LABEL] ~= LABEL, lang .. ": not translated") end
        local used = ns.OptionsUsedHeight()
        assert(used.alerts <= 640 - 112 - 18 - 4 - 66, ("Options alerts: %d px, too long"):format(used.alerts))

        -- 8. a client without the full scan: quiet
        AHX.ReplicateItems = nil
        Free()
        mark = #log
        fire("AUCTION_HOUSE_SHOW") advance(2)
        assert(#Said(mark) == 0, "no full scan in this client, said on opening: " .. tostring(Said(mark)[1]))
        Close()
        Mock()

        -- 8b. every auction is read and only the prices are being worked out:
        -- closing the window then does not cancel the scan (a clock that jumps
        -- makes every step as short as it can be, so there are steps to close in)
        do
            local keepClock, tick, reads, closed = debugprofilestop, 0, 0, false
            debugprofilestop = function() tick = tick + 100 return tick end
            local many = {}
            for i = 1, 300 do many[i] = { id = 200000 + i, count = 1, unit = 50 + i } end
            AHX.GetNumReplicateItems = function() return #many end
            AHX.GetReplicateItemInfo = function(i)
                local a = many[i + 1]
                if not a then return nil end
                reads = reads + 1
                return "Item", 1, a.count, 1, true, 1, 0, 0, 0, a.unit, 0, false, nil, "Seller", nil, 0, a.id, true
            end
            Free()
            fire("AUCTION_HOUSE_SHOW") advance(1)
            mark = #log
            p.scanned = 0
            C_Timer.After = function(s, fn)
                keep.after(s, function()
                    -- (the first step after the last auction was read: the window closes right before it)
                    if s == 0 and not closed and reads >= #many + 1 then
                        closed = true
                        fire("AUCTION_HOUSE_CLOSED")
                    end
                    fn()
                end)
            end
            fire("REPLICATE_ITEM_LIST_UPDATE") advance(5)
            C_Timer.After, debugprofilestop = keep.after, keepClock
            assert(closed, "test setup: the window was never closed between the steps (" .. reads .. " auctions read)")
            assert(p.scanned > 0 and p.items[200300] == 350, "closed while the prices were worked out: the scan was thrown away")
            local lines = Said(mark)
            assert(#lines == 1 and lines[1]:find((ns.L["Auction house scanned: %d auctions, prices for %d items."]):format(300, 300), 1, true),
                ("closed while the prices were worked out: %d lines, %s"):format(#lines, tostring(lines[1])))
            Close()
            Mock()
        end

        -- 9. 300,000 auctions of 20,000 items (live: 313,401): no step of the
        -- reading holds the game for long. The mock's clock, on a faster Lua
        -- than the game's: it shows that the work is cut into steps of one
        -- size, not how long a step takes in the game.
        local okFfi, ffi = pcall(require, "ffi")
        local clock = function() return os.clock() * 1000 end
        if okFfi then
            pcall(ffi.cdef, "int QueryPerformanceCounter(int64_t *c); int QueryPerformanceFrequency(int64_t *f);")
            local c, f = ffi.new("int64_t[1]"), ffi.new("int64_t[1]")
            if pcall(function() return ffi.C.QueryPerformanceFrequency(f) end) and tonumber(f[0]) > 0 then
                local freq = tonumber(f[0])
                clock = function() ffi.C.QueryPerformanceCounter(c) return tonumber(c[0]) * 1000 / freq end
            end
        end
        local N, ITEMS = 300000, 20000
        AHX.GetNumReplicateItems = function() return N end
        AHX.GetReplicateItemInfo = function(i)
            if i >= N then return nil end
            local count = i % 20 + 1
            return "Item", 1, count, 1, true, 1, 0, 0, 0, (100 + i % 37) * count, 0, false, nil, "Seller", nil, 0, 100000 + (i * 7919) % ITEMS, true
        end
        local function Scan()
            Free()
            fire("AUCTION_HOUSE_SHOW") advance(1)
            local steps, worst, total = 0, 0, 0
            local function Timed(fn)
                local t0 = clock()
                fn()
                local ms = clock() - t0
                steps, total = steps + 1, total + ms
                if ms > worst then worst = ms end
            end
            -- (the scan's steps follow each other with no wait; other timers of the addon are not its steps)
            C_Timer.After = function(s, fn) if s == 0 then keep.after(s, function() Timed(fn) end) else keep.after(s, fn) end end
            p.scanned = 0
            Timed(function() fire("REPLICATE_ITEM_LIST_UPDATE") end)
            advance(60)
            C_Timer.After = keep.after
            assert(p.scanned > 0, "the 300,000 auctions were not read to the end")
            local count = 0
            for _ in pairs(p.items) do count = count + 1 end
            assert(count == ITEMS, ("prices for %d of %d items"):format(count, ITEMS))
            Close()
            return worst, steps, total
        end
        local worst, steps, total = Scan()
        for _ = 1, 2 do
            local w, s, t = Scan()
            if w < worst then worst, steps, total = w, s, t end
        end
        note(("MEASURE P5 scan of 300000 auctions / 20000 items: %d steps, %.0f ms in all, the longest step %.1f ms"):format(steps, total, worst))
        assert(steps >= 200, ("300,000 auctions were read in %d steps"):format(steps))
        assert(worst < 16, ("the longest step of the scan takes %.1f ms"):format(worst))
    end)
    C_Timer.After = keep.after
    fire("AUCTION_HOUSE_CLOSED") advance(1)
    AHX.ReplicateItems, AHX.GetNumReplicateItems, AHX.GetReplicateItemInfo = keep.rep, keep.num, keep.info
    ns.db.autoScanOff, ns.db.debug = keep.off, keep.debug
    p.lastScanStart, p.scanned, p.items, p.qty, p.seen, p.history = keep.last, keep.scanned, keep.items, keep.qty, keep.seen, keep.history
    assert(ok, err)
end)
step("Professions: read from the game's list by their number, every place of it - no profession window, no skill list (v0.1.23 P6)", function()
    -- Sven, 14.11.2026, Forever client: there is no GetNumSkillLines, and
    -- GetProfessions gives 7 values (Herbalism 270/300 is line 182, Mining
    -- 225/300 line 186, First Aid 129, Fishing 356, Cooking 185). The skill
    -- plan knew a crafting skill only after its window had been open, and
    -- the gathering skills were looked for in the first six places only.
    local keep = { gp = GetProfessions, gi = GetProfessionInfo, gn = GetNumSkillLines, gs = GetSkillLineInfo, secret = issecretvalue,
        recipes = ns.db.recipes, locale = GetLocale }
    local SECRET = {}
    -- the client's own names, as a German client says them: they must not matter
    local LINES = {
        [11] = { "Alchimie", 120, 150, 171 }, [12] = { "Kräuterkunde", 270, 300, 182 }, [14] = { "Angeln", 127, 150, 356 },
        [15] = { "Kochkunst", 141, 150, 185 }, [16] = { "Erste Hilfe", 144, 225, 129 }, [17] = { "Bergbau", 225, 300, 186 },
    }
    local function Seven() return 11, 12, nil, 14, 15, 16, 17 end
    local function Info(i)
        local l = LINES[i]
        if not l then return nil end
        return l[1], 134400, l[2], l[3], 0, 0, l[4], 0
    end
    local function Said(mark, text)
        for i = mark + 1, #log do if log[i]:find(text, 1, true) then return log[i] end end
    end
    local ok, err = pcall(function()
        -- a character that never opened a profession window, in a client without the old skill list
        ns.db.recipes = nil
        GetNumSkillLines, GetSkillLineInfo = nil, nil
        GetProfessions, GetProfessionInfo = Seven, Info
        fire("SKILL_LINES_CHANGED") advance(2)

        -- 1. the seventh place counts: Mining stands there
        local rank, maxRank = ns.GetSkill("ore")
        assert(rank == 225 and maxRank == 300, ("Mining in the seventh place: %s/%s"):format(tostring(rank), tostring(maxRank)))
        assert(ns.GetSkill("herb") == 270 and ns.GetSkill("fish") == 127, "the places before it are read as before")

        -- 2. the skill plan's question, for a crafting profession whose window was never open
        local r, m = ns.ProfessionRank("Alchemy")
        assert(r == 120 and m == 150, ("Alchemy without its window: %s/%s"):format(tostring(r), tostring(m)))
        for prof, want in pairs({ Herbalism = 270, Fishing = 127, Cooking = 141, ["First Aid"] = 144, Mining = 225 }) do
            assert(ns.ProfessionRank(prof) == want, ("%s: %s, want %d"):format(prof, tostring(ns.ProfessionRank(prof)), want))
        end
        assert(ns.ProfessionRank("Tailoring") == nil, "a profession you do not have has a skill")
        -- ... each of the twelve by its number, whatever the client calls it
        local IDS = { Alchemy = 171, Blacksmithing = 164, Enchanting = 333, Engineering = 202, Leatherworking = 165, Tailoring = 197,
            Mining = 186, Herbalism = 182, Skinning = 393, Fishing = 356, Cooking = 185, ["First Aid"] = 129 }
        for prof, id in pairs(IDS) do
            LINES[20] = { "???", 77, 150, id }
            GetProfessions = function() return nil, 20 end
            local got, gotMax = ns.ProfessionRank(prof)
            assert(got == 77 and gotMax == 150, ("%s (line %d): %s/%s"):format(prof, id, tostring(got), tostring(gotMax)))
            for other in pairs(IDS) do
                if other ~= prof then assert(ns.ProfessionRank(other) == nil, ("line %d is also read as %s"):format(id, other)) end
            end
        end
        GetProfessions = Seven

        -- 3. hidden values are never compared: no error, and nothing made up
        issecretvalue = function(v) return v == SECRET end
        GetProfessions = function() return SECRET, 12, nil, 14, 15, 16, 17 end
        assert(ns.ProfessionRank("Alchemy") == nil, "a hidden place is read as a profession")
        assert(ns.ProfessionRank("Mining") == 225, "a hidden place hides the others")
        GetProfessions = Seven
        GetProfessionInfo = function(i)
            if i == 11 then return "Alchimie", 134400, 120, 150, 0, 0, SECRET, 0 end
            return Info(i)
        end
        assert(ns.ProfessionRank("Alchemy") == nil and ns.ProfessionRank("Mining") == 225, "a hidden line number")
        do
            -- the place with the hidden number is left out and said to be unclear
            local slots, unclear = ns.ProfessionSlots()
            assert(unclear == true, "a hidden line number is not said to be unclear")
            assert(#slots == 5, ("a hidden line number: %d places read, want the 5 others"):format(#slots))
            for _, slot in ipairs(slots) do assert(slot.line ~= SECRET, "the hidden line number is handed on") end
        end
        GetProfessionInfo = function(i)
            if i == 11 then return "Alchimie", 134400, SECRET, SECRET, 0, 0, 171, 0 end
            return Info(i)
        end
        assert(ns.ProfessionRank("Alchemy") == nil, "a hidden skill is given out")
        GetProfessionInfo = Info
        issecretvalue = keep.secret

        -- 4. /gcr crafttest names them: place, name, skill, number, and what it is read as
        local mark = #log
        slash("crafttest")
        local line = Said(mark, "professions (GetProfessions, 7 places)")
        assert(line, "/gcr crafttest does not list the professions of the game's list")
        for _, part in ipairs({ "1: Alchimie 120/150 line 171 = Alchemy", "2: Kräuterkunde 270/300 line 182 = Herbalism", "7: Bergbau 225/300 line 186 = Mining",
            "4: Angeln 127/150 line 356 = Fishing", "5: Kochkunst 141/150 line 185 = Cooking", "6: Erste Hilfe 144/225 line 129 = First Aid" }) do
            assert(line:find(part, 1, true), ("/gcr crafttest: no '%s' in: %s"):format(part, line))
        end
        assert(Said(mark, "skill list: not in this client"), "/gcr crafttest does not say that this client has no skill list")
        -- a line number we do not know is shown as it is
        LINES[11][4] = 999
        mark = #log
        slash("crafttest")
        assert(Said(mark, "1: Alchimie 120/150 line 999 = not recognised"), "an unknown line number is not shown as that")
        LINES[11][4] = 171
        -- a client without the list says so
        GetProfessions, GetProfessionInfo = nil, nil
        mark = #log
        slash("crafttest")
        assert(Said(mark, "professions (GetProfessions): not in this client"), "/gcr crafttest without GetProfessions")
        assert(ns.ProfessionRank("Alchemy") == nil, "no list, no window: a skill from nowhere")
        GetProfessions, GetProfessionInfo = Seven, Info

        -- 5. the game's list comes first: what the window showed last is only what is left without it
        ns.db.recipes = nil
        GetProfessions = function() return nil, 12 end
        assert(ns.ProfessionRank("Alchemy") == nil, "test setup")
        GetProfessions = Seven
        assert(ns.ProfessionRank("Alchemy") == 120, "the list is not asked first")
    end)
    issecretvalue = keep.secret
    GetProfessions, GetProfessionInfo, GetNumSkillLines, GetSkillLineInfo, GetLocale = keep.gp, keep.gi, keep.gn, keep.gs, keep.locale
    ns.db.recipes = keep.recipes
    fire("SKILL_LINES_CHANGED") advance(7)
    assert(ok, err)
end)
step("Auction house: the prices are worked out in short steps however the auctions are spread, and are the same as before (v0.1.23 R1-M1)", function()
    -- Codex, round 1 (M1): 300,000 auctions spread evenly over 20,000 items
    -- were read in steps of 8 ms - but 100 items, or 80 % of the auctions on
    -- five items, held the game for 48-63 ms in one step: the prices of 50
    -- items were worked out before the clock was looked at, and all offers
    -- of one item were copied and sorted in one go.
    local AHX = C_AuctionHouse
    ns.GetPrice(2447) -- (the price store of this realm is made when it is first asked)
    local p = ns.db.prices[next(ns.db.prices)]
    local keep = { rep = AHX.ReplicateItems, num = AHX.GetNumReplicateItems, info = AHX.GetReplicateItemInfo, off = ns.db.autoScanOff,
        last = p.lastScanStart, scanned = p.scanned, items = p.items, qty = p.qty, seen = p.seen, history = {}, debug = ns.db.debug,
        after = C_Timer.After, clock = debugprofilestop, instant = C_Item.GetItemInfoInstant }
    for id, text in pairs(p.history) do keep.history[id] = text end -- (the scans below write into it)
    -- the test items (100000 and up) are trade goods: those have a price history
    C_Item.GetItemInfoInstant = function(id, ...)
        if type(id) == "number" and id >= 100000 then return id, "Trade Goods", "", "", 134400, 7, 0 end
        return keep.instant(id, ...)
    end

    -- MarketPrice as it was in 4d93718, word for word: what the new one is compared with
    local f = assert(io.open(ROOT .. "/Prices.lua"))
    local src = f:read("*a") f:close()
    local MARKET_MIN, MARKET_SHARE = tonumber(src:match("\nlocal MARKET_MIN = ([%d%.]+)")), tonumber(src:match("\nlocal MARKET_SHARE = ([%d%.]+)"))
    local HISTORY_DAYS = tonumber(src:match("\nlocal HISTORY_DAYS = (%d+)"))
    assert(MARKET_MIN and MARKET_SHARE and HISTORY_DAYS, "test setup: the numbers of the market price are not found in Prices.lua")
    local function OldMarketPrice(list)
        -- list = { unitPrice, count, unitPrice, count, ... }
        local entries, total = {}, 0
        for i = 1, #list, 2 do
            entries[#entries + 1] = { list[i], list[i + 1] }
            total = total + list[i + 1]
        end
        table.sort(entries, function(a, b) return a[1] < b[1] end)
        -- with less stock than that, what is there counts: the loop runs out
        local want, seen = math.max(MARKET_MIN, total * MARKET_SHARE), 0
        for _, e in ipairs(entries) do
            seen = seen + e[2]
            if seen >= want then return math.floor(e[1] + 0.5), total end
        end
        return math.floor(entries[#entries][1] + 0.5), total
    end

    local okFfi, ffi = pcall(require, "ffi")
    local clock = function() return os.clock() * 1000 end
    if okFfi then
        pcall(ffi.cdef, "int QueryPerformanceCounter(int64_t *c); int QueryPerformanceFrequency(int64_t *f);")
        local c, fr = ffi.new("int64_t[1]"), ffi.new("int64_t[1]")
        if pcall(function() return ffi.C.QueryPerformanceFrequency(fr) end) and tonumber(fr[0]) > 0 then
            local freq = tonumber(fr[0])
            clock = function() ffi.C.QueryPerformanceCounter(c) return tonumber(c[0]) * 1000 / freq end
        end
    end
    local function Said(mark)
        local out = {}
        for i = mark + 1, #log do if log[i]:find("^PRINT") then out[#out + 1] = log[i] end end
        return out
    end
    local function Free() p.lastScanStart = 0 end -- the 15 minutes are over
    local function Close() fire("AUCTION_HOUSE_CLOSED") advance(1) end
    -- (the step takes about 20 minutes of the mock's clock and compares the
    -- history of one UTC day: in a long run - on dev-0.2 many steps come
    -- before it - the clock can stand just before a midnight here. Then it is
    -- moved past it first, so the whole step lies within one day.)
    local toMidnight = 86400 - time() % 86400
    if toMidnight < 3600 then advance(toMidnight + 60) end
    local day = math.floor(time() / 86400)

    -- an auction house: Info(i) gives id, count, buyout of auction i (from 0),
    -- or what the game gives for an auction that has no id, count or buyout
    local function House(n, Info)
        AHX.ReplicateItems = function() end
        AHX.GetNumReplicateItems = function() return n end
        AHX.GetReplicateItemInfo = function(i)
            if i >= n then return nil end
            local id, count, buyout, broken = Info(i)
            if broken then error("no such auction") end
            return "Item", 1, count, 1, true, 1, 0, 0, 0, buyout, 0, false, nil, "Seller", nil, 0, id, true
        end
    end
    -- what 4d93718 made of it: price and stock of every item, from the old MarketPrice
    local function Expected(n, Info)
        local acc, out, items = {}, {}, 0
        for i = 0, n - 1 do
            local id, count, buyout, broken = Info(i)
            if not broken and id and count and count > 0 and buyout and buyout > 0 then
                local list = acc[id]
                if not list then list = {} acc[id] = list items = items + 1 end
                list[#list + 1] = buyout / count
                list[#list + 1] = count
            end
        end
        for id, list in pairs(acc) do
            local price, total = OldMarketPrice(list)
            out[id] = { price, total }
        end
        return out, items
    end
    -- the history an item has after a scan today (HistoryWith of 4d93718: the
    -- days kept, today's price last)
    local function ExpectedHistory(before, price)
        local kept = {}
        for d, v in (before or ""):gmatch("(%d+):(%d+)") do
            if tonumber(d) ~= day and tonumber(d) > day - HISTORY_DAYS then kept[#kept + 1] = d .. ":" .. v end
        end
        kept[#kept + 1] = day .. ":" .. price
        return table.concat(kept, ";")
    end
    local function SamePrices(what, want, wantItems, historyBefore)
        local got = 0
        for id, price in pairs(p.items) do
            got = got + 1
            local w = want[id]
            assert(w, ("%s: a price for item %d that has no auction"):format(what, id))
            assert(price == w[1], ("%s: item %d has the price %s, it was %s"):format(what, id, tostring(price), tostring(w[1])))
            assert(p.qty[id] == w[2], ("%s: item %d has the stock %s, it was %s"):format(what, id, tostring(p.qty[id]), tostring(w[2])))
            assert(p.seen[id] and p.seen[id] > 0, ("%s: item %d was not seen"):format(what, id))
            local h = ExpectedHistory(historyBefore and historyBefore[id], w[1])
            assert(p.history[id] == h, ("%s: item %d has the history %s, it was %s"):format(what, id, tostring(p.history[id]), h))
        end
        assert(got == wantItems, ("%s: prices for %d of %d items"):format(what, got, wantItems))
    end

    -- one scan of the house, every step of it timed: the event with the list,
    -- and every timer with no wait that follows
    local function Scan(n, incomplete)
        Free()
        fire("AUCTION_HOUSE_SHOW") advance(1)
        local steps, worst, total, peak = 0, 0, 0, 0
        local function Timed(fn)
            local t0 = clock()
            fn()
            local ms = clock() - t0
            steps, total = steps + 1, total + ms
            if ms > worst then worst = ms end
            local kb = collectgarbage("count")
            if kb > peak then peak = kb end
        end
        C_Timer.After = function(s, fn) if s == 0 then keep.after(s, function() Timed(fn) end) else keep.after(s, fn) end end
        p.scanned = 0
        Timed(function() fire("REPLICATE_ITEM_LIST_UPDATE") end)
        advance(60)
        C_Timer.After = keep.after
        -- (a scan with an auction that could not be read is no full scan: it leaves no time of a scan)
        assert((p.scanned > 0) == not incomplete, ("the scan of %d auctions: scanned at %s"):format(n, tostring(p.scanned)))
        return worst, steps, total, peak
    end

    local ok, err = pcall(function()
        AuctionHouseFrame = AuctionHouseFrame or CreateFrame("Frame", "AuctionHouseFrame", UIParent)
        ns.db.autoScanOff, ns.db.debug = nil, nil
        Close()
        local N = 300000
        local CASES = {
            -- Codex's three: the same 300,000 auctions (count, unit price), spread differently
            { "20,000 items, evenly", function(i)
                local count = i % 20 + 1
                return 100000 + (i * 7919) % 20000, count, (100 + i % 37) * count
            end },
            { "100 items, evenly", function(i)
                local count = i % 20 + 1
                return 100000 + (i * 7919) % 100, count, (100 + i % 37) * count
            end },
            { "20,000 items, 80 % of the auctions on five", function(i)
                local count = i % 20 + 1
                local id = i < 240000 and (100000 + i % 5) or (100005 + i % 19995)
                return id, count, (100 + i % 37) * count
            end },
            -- and the worst there is for one item: every auction is of one item, and no two have the same unit price
            { "one item, 300,000 different prices", function(i)
                return 100000, 1, 100 + (i * 7919) % N
            end },
        }
        for c, case in ipairs(CASES) do
            local what, Info = case[1], case[2]
            House(N, Info)
            local want, wantItems = Expected(N, Info)
            -- an item with a history: an old day falls out, yesterday's stays
            local before = { [100000] = (day - 20) .. ":55;" .. (day - 1) .. ":77", [100003] = (day - 2) .. ":66" }
            p.history = {}
            for id, text in pairs(before) do p.history[id] = text end
            collectgarbage() collectgarbage()
            local base = collectgarbage("count")
            local worst, steps, total, peak = Scan(N)
            SamePrices(what, want, wantItems, before)
            Close()
            for _ = 1, 2 do
                local w, s, t, k = Scan(N)
                if w < worst then worst, steps, total, peak = w, s, t, k end
                Close()
            end
            SamePrices(what .. " (scanned again)", want, wantItems, before)
            note(("MEASURE M1 %s: %d steps, %.0f ms in all, the longest step %.1f ms, %.1f MiB more at most between the steps"):format(
                what, steps, total, worst, (peak - base) / 1024))
            assert(worst < 16, ("%s: the longest step of the scan takes %.1f ms"):format(what, worst))
            if c == 1 then assert(steps >= 200, ("300,000 auctions were read in %d steps"):format(steps)) end
        end

        -- what is left out and what cannot be read counts as before: auctions
        -- without an id, a count or a buyout are not offers, and one that
        -- cannot be read makes the scan incomplete (the other old prices stay)
        do
            local M = 30000
            local function Info(i)
                if i == 17 then return nil, nil, nil, true end
                if i % 1000 == 3 then return nil, 2, 500 end
                if i % 1000 == 5 then return 100001, 0, 500 end
                if i % 1000 == 7 then return 100002, 2, 0 end
                local count = i % 9 + 1
                return 100000 + (i * 31) % 40, count, (200 + (i * 13) % 501) * count + i % count
            end
            House(M, Info)
            local want, wantItems = Expected(M, Info)
            p.items, p.qty, p.seen, p.history = { [2447] = 123 }, { [2447] = 9 }, { [2447] = 1 }, {}
            ns.db.debug = true
            local mark = #log
            Scan(M, true)
            ns.db.debug = nil
            assert(p.items[2447] == 123 and p.qty[2447] == 9, "a scan with an auction that could not be read threw an old price away")
            p.items[2447], p.qty[2447], p.seen[2447] = nil, nil, nil
            SamePrices("auctions left out, one unreadable", want, wantItems)
            local line
            for i = mark + 1, #log do if log[i]:find("SCAN read 30000 of 30000", 1, true) then line = log[i] end end
            assert(line and line:find(("%d items, skipped 30 without itemID, 30 with count 0, 30 with buyout 0, 1 could not be read"):format(wantItems), 1, true),
                "the count of what was left out: " .. tostring(line))
            local said = Said(mark)
            assert(#said == 1 and said[1]:find((ns.L["Scan incomplete: %d auctions could not be read, old prices kept (%d updated)."]):format(1, wantItems), 1, true),
                ("the incomplete scan said %d lines: %s"):format(#said, tostring(said[1])))
            Close()
        end

        -- a clock that goes on by 1 ms each time it is looked at: no step looks
        -- at it more often than a step is long (and once more to see that it is
        -- over) - the last step of the reading and the first of the prices are
        -- not one long step, and one item with many offers is not one step.
        -- This does not hang on how fast the machine of the test is.
        local function Stepped(M, Info, closeAt)
            House(M, Info)
            local want, wantItems = Expected(M, Info)
            p.history = {}
            Free()
            fire("AUCTION_HOUSE_SHOW") advance(1)
            local tick, worst, pricing, closed = 0, 0, 0, false
            debugprofilestop = function() tick = tick + 1 return tick end
            local reads, readNum = 0, AHX.GetReplicateItemInfo
            AHX.GetReplicateItemInfo = function(i) reads = reads + 1 return readNum(i) end
            local function Timed(fn)
                local t0 = tick
                -- (every auction is read: this step works out prices)
                if reads >= M + 1 then
                    pricing = pricing + 1
                    if pricing == closeAt then closed = true fire("AUCTION_HOUSE_CLOSED") end
                end
                fn()
                if tick - t0 > worst then worst = tick - t0 end
            end
            C_Timer.After = function(s, fn) if s == 0 then keep.after(s, function() Timed(fn) end) else keep.after(s, fn) end end
            p.scanned = 0
            local mark = #log
            Timed(function() fire("REPLICATE_ITEM_LIST_UPDATE") end)
            advance(120)
            C_Timer.After, debugprofilestop, AHX.GetReplicateItemInfo = keep.after, keep.clock, readNum
            assert(p.scanned > 0, "the scan with the stepping clock did not end")
            -- 8 ms a step: the clock is seen at 8 at the latest, and a look or two follow (the end of the reading, the debug line)
            assert(worst <= 12, ("a step looked at the clock %d times: longer than a step is to be"):format(worst))
            return pricing, closed, want, wantItems, Said(mark)
        end
        do
            -- one item with 40,000 offers at 40,000 prices and 500 more items;
            -- the window closes while the prices of the big item are being
            -- worked out: every auction is read, the scan goes on to its end
            local M = 60000
            local pricing, closed, want, wantItems, said = Stepped(M, function(i)
                if i < 40000 then return 100000, 1, 100 + (i * 7919) % 40000 end
                return 100001 + i % 500, 1, 300 + i % 91
            end, 3)
            assert(closed, ("test setup: the window was never closed while the prices were worked out (%d such steps)"):format(pricing))
            assert(pricing >= 300, ("one item with 40,000 prices and 500 more items: the prices were worked out in %d steps"):format(pricing))
            SamePrices("closed while the prices were worked out", want, wantItems)
            assert(#said == 1 and said[1]:find((ns.L["Auction house scanned: %d auctions, prices for %d items."]):format(M, wantItems), 1, true),
                ("closed while the prices were worked out: %d lines, %s"):format(#said, tostring(said[1])))
            Close()
            -- 5,000 items with three offers each: the clock is looked at after every item
            pricing, closed, want, wantItems = Stepped(15000, function(i) return 100000 + i % 5000, 1, 300 + i % 91 end)
            assert(pricing >= 600, ("5,000 items: the prices were worked out in %d steps"):format(pricing))
            SamePrices("5,000 items", want, wantItems)
            Close()
            -- one item with 40,000 offers at one price: putting them together is not one step either
            pricing, closed, want, wantItems = Stepped(40000, function(i) return 100000, i % 3 + 1, 250 * (i % 3 + 1) end)
            assert(pricing >= 15, ("one item with 40,000 offers at one price: its price was worked out in %d steps"):format(pricing))
            SamePrices("40,000 offers at one price", want, wantItems)
            Close()
        end

        -- a search (not the full scan) uses the same market price, at once
        do
            local list, results = {}, {}
            for i = 1, 500 do
                results[i] = { unitPrice = 1000 + (i * 37) % 211, quantity = i % 7 + 1 }
                list[#list + 1], list[#list + 2] = results[i].unitPrice, results[i].quantity
            end
            local keepN, keepI, keepF = AHX.GetNumCommoditySearchResults, AHX.GetCommoditySearchResultInfo, AHX.HasFullCommoditySearchResults
            AHX.GetNumCommoditySearchResults = function() return #results end
            AHX.GetCommoditySearchResultInfo = function(_, i) return results[i] end
            AHX.HasFullCommoditySearchResults = function() return true end
            fire("AUCTION_HOUSE_SHOW") advance(1)
            fire("COMMODITY_SEARCH_RESULTS_UPDATED", 100777)
            AHX.GetNumCommoditySearchResults, AHX.GetCommoditySearchResultInfo, AHX.HasFullCommoditySearchResults = keepN, keepI, keepF
            local price, total = OldMarketPrice(list)
            assert(p.items[100777] == price and p.qty[100777] == total,
                ("a search of 500 results: price %s and stock %s, it was %s and %s"):format(tostring(p.items[100777]), tostring(p.qty[100777]), price, total))
            Close()
        end
    end)
    C_Timer.After, debugprofilestop, C_Item.GetItemInfoInstant = keep.after, keep.clock, keep.instant
    fire("AUCTION_HOUSE_CLOSED") advance(1)
    AHX.ReplicateItems, AHX.GetNumReplicateItems, AHX.GetReplicateItemInfo = keep.rep, keep.num, keep.info
    ns.db.autoScanOff, ns.db.debug = keep.off, keep.debug
    p.lastScanStart, p.scanned, p.items, p.qty, p.seen, p.history = keep.last, keep.scanned, keep.items, keep.qty, keep.seen, keep.history
    assert(ok, err)
end)
step("Auction house: an answer that comes after the timeout belongs to the scan it was for - quiet after opening, said after a click (v0.1.23 R1-N1)", function()
    -- Codex, round 1 (N1): the scan started by opening the window got no
    -- answer in time (quiet), the answer came late and was read as a new
    -- scan - one that did not know it had started by itself. The window
    -- closed while it was read, and chat said "Auction house closed, scan
    -- cancelled." for a scan nobody had asked for.
    local AHX = C_AuctionHouse
    ns.GetPrice(2447) -- (the price store of this realm is made when it is first asked)
    local p = ns.db.prices[next(ns.db.prices)]
    local keep = { rep = AHX.ReplicateItems, num = AHX.GetNumReplicateItems, info = AHX.GetReplicateItemInfo, off = ns.db.autoScanOff,
        last = p.lastScanStart, scanned = p.scanned, items = p.items, qty = p.qty, seen = p.seen, history = {}, debug = ns.db.debug }
    for id, text in pairs(p.history) do keep.history[id] = text end
    local N, calls = 3000, 0 -- (more than one step of reading: 1,500 auctions a step at most)
    local function Said(mark)
        local out = {}
        for i = mark + 1, #log do if log[i]:find("^PRINT") then out[#out + 1] = log[i] end end
        return out
    end
    local function Free() p.lastScanStart = 0 end -- the 15 minutes are over
    local function Close() fire("AUCTION_HOUSE_CLOSED") advance(1) end
    local ok, err = pcall(function()
        AHX.ReplicateItems = function() calls = calls + 1 end
        AHX.GetNumReplicateItems = function() return N end
        AHX.GetReplicateItemInfo = function(i)
            if i >= N then return nil end
            return "Item", 1, 2, 1, true, 1, 0, 0, 0, (100 + i % 7) * 2, 0, false, nil, "Seller", nil, 0, 100000 + i % 30, true
        end
        AuctionHouseFrame = AuctionHouseFrame or CreateFrame("Frame", "AuctionHouseFrame", UIParent)
        ns.db.autoScanOff, ns.db.debug = nil, nil
        Close()
        advance(140) -- (what the addon has to say once after a login is said by now: not a line of the scan)

        -- 1. started by opening the window: no answer, then the answer, then
        -- the window closes while it is read - nothing of it in chat
        Free()
        calls = 0
        local mark = #log
        fire("AUCTION_HOUSE_SHOW") advance(1)
        assert(calls == 1, "test setup: opening the window started " .. calls .. " scans")
        advance(130) -- no answer: the scan gives up (quietly)
        assert(#Said(mark) == 0, "no answer after opening, said in chat: " .. tostring(Said(mark)[1]))
        p.scanned = 0
        fire("REPLICATE_ITEM_LIST_UPDATE") -- the late answer: the first 1,500 are read at once
        fire("AUCTION_HOUSE_CLOSED") advance(2)
        assert(p.scanned == 0, "test setup: the window closed while the late answer was read, and the scan went on")
        local said = Said(mark)
        assert(#said == 0, ("the late answer of a scan that started by itself, window closed: %d lines in chat, %s"):format(#said, tostring(said[1])))

        -- 2. the same after a click (here: /gcr scan): everything is said, as before
        ns.db.autoScanOff = true
        Free()
        calls = 0
        fire("AUCTION_HOUSE_SHOW") advance(1)
        assert(calls == 0, "test setup: the switch is off and opening the window started a scan")
        mark = #log
        slash("scan")
        assert(calls == 1, "test setup: /gcr scan started " .. calls .. " scans")
        advance(130)
        local function Has(lines, text)
            for _, l in ipairs(lines) do if l:find(text, 1, true) then return true end end
        end
        assert(Has(Said(mark), ns.L["The auction house didn't answer. Try again later."]), "no answer after /gcr scan: not said in chat")
        mark = #log
        fire("REPLICATE_ITEM_LIST_UPDATE")
        fire("AUCTION_HOUSE_CLOSED") advance(2)
        assert(Has(Said(mark), ns.L["Auction house closed, scan cancelled."]), "the late answer of /gcr scan, window closed: not said in chat")
        ns.db.autoScanOff = nil

        -- 3. a late answer that is read to the end says its result once, whoever started the scan
        Free()
        calls = 0
        mark = #log
        fire("AUCTION_HOUSE_SHOW") advance(1)
        advance(130)
        p.scanned = 0
        fire("REPLICATE_ITEM_LIST_UPDATE") advance(5)
        said = Said(mark)
        assert(p.scanned > 0 and #said == 1 and said[1]:find((ns.L["Auction house scanned: %d auctions, prices for %d items."]):format(N, 30), 1, true),
            ("the late answer read to the end: %d lines, %s"):format(#said, tostring(said[1])))
        Close()

        -- 4. the next scan is its own: a click after a quiet one that gave up
        -- is a click (its late answer, closed while read, is said)
        Free()
        fire("AUCTION_HOUSE_SHOW") advance(1) -- starts by itself
        advance(130)                          -- gives up quietly
        Close()                               -- (closing ends the wait for the late answer)
        ns.db.autoScanOff = true
        Free()
        fire("AUCTION_HOUSE_SHOW") advance(1)
        slash("scan")
        advance(130)
        mark = #log
        fire("REPLICATE_ITEM_LIST_UPDATE")
        fire("AUCTION_HOUSE_CLOSED") advance(2)
        assert(Has(Said(mark), ns.L["Auction house closed, scan cancelled."]), "a click after a quiet scan: its late answer is treated as quiet")
        ns.db.autoScanOff = nil
    end)
    fire("AUCTION_HOUSE_CLOSED") advance(1)
    AHX.ReplicateItems, AHX.GetNumReplicateItems, AHX.GetReplicateItemInfo = keep.rep, keep.num, keep.info
    ns.db.autoScanOff, ns.db.debug = keep.off, keep.debug
    p.lastScanStart, p.scanned, p.items, p.qty, p.seen, p.history = keep.last, keep.scanned, keep.items, keep.qty, keep.seen, keep.history
    assert(ok, err)
end)
step("Professions: every place of the game's list is asked whether it is hidden before anything else is done with it (v0.1.23 R1-N2)", function()
    -- Codex, round 1 (N2): a place of GetProfessions was compared with nil
    -- first and asked whether it is hidden second. The line's number and the
    -- skill were asked first already; the place follows the same pattern.
    -- (Lua tells nobody about a comparison with nil, so the test cannot
    -- count that one: it counts that the game is asked about every place,
    -- the empty one too - which only happens when the asking comes first -
    -- and reads the order in the source.)
    local keep = { gp = GetProfessions, gi = GetProfessionInfo, secret = issecretvalue }
    local SECRET = {}
    local LINES = {
        [11] = { "Alchimie", 120, 150, 171 }, [12] = { "Kräuterkunde", 270, 300, 182 }, [14] = { "Angeln", 127, 150, 356 },
        [15] = { "Kochkunst", 141, 150, 185 }, [16] = { "Erste Hilfe", 144, 225, 129 }, [17] = { "Bergbau", 225, 300, 186 },
    }
    local ok, err = pcall(function()
        local asked, infos = {}, 0
        -- (what is asked: the value, and how many values were looked up in the game's list before)
        issecretvalue = function(...)
            assert(select("#", ...) == 1, "issecretvalue was asked about " .. select("#", ...) .. " values")
            local v = ...
            asked[#asked + 1] = { v = v, infos = infos }
            return rawequal(v, SECRET)
        end
        GetProfessionInfo = function(i)
            assert(not rawequal(i, SECRET), "the game was asked for the profession at a hidden place")
            infos = infos + 1
            local l = LINES[i]
            if not l then return nil end
            return l[1], 134400, l[2], l[3], 0, 0, l[4], 0
        end
        local function Places(...)
            local n, list = select("#", ...), { ... }
            GetProfessions = function() return unpack(list, 1, n) end
            asked, infos = {}, 0
            local slots, unclear, places = ns.ProfessionSlots()
            assert(places == n, ("test setup: %s places, the list has %d"):format(tostring(places), n))
            return slots, unclear, n, list
        end
        -- 1. seven places, the third empty: the game is asked about all seven
        local function AskedAbout(list, n)
            local count, empty = 0, 0
            for i = 1, n do
                local v, found = list[i], false
                for _, a in ipairs(asked) do
                    if rawequal(a.v, v) then found = true break end
                end
                if found then count = count + 1 end
                if v == nil and found then empty = empty + 1 end
            end
            return count, empty
        end
        local slots, unclear, n, list = Places(11, 12, nil, 14, 15, 16, 17)
        local count, empty = AskedAbout(list, n)
        assert(count == 7 and empty == 1, ("seven places, one empty: asked whether hidden about %d of them (the empty one: %d)"):format(count, empty))
        assert(#slots == 6 and unclear == false, ("seven places, one empty: %d read, unclear %s"):format(#slots, tostring(unclear)))
        assert(slots[3].place == 4 and slots[3].line == 356 and slots[6].place == 7 and slots[6].line == 186, "the places after the empty one are not read as before")
        -- 2. a hidden place: asked about, never looked up, the others are read
        slots, unclear, n, list = Places(SECRET, 12, nil, 14, 15, 16, 17)
        count = AskedAbout(list, n)
        assert(count == 7, ("a hidden place: asked whether hidden about %d of 7"):format(count))
        assert(#slots == 5 and unclear == true and slots[1].place == 2, ("a hidden place: %d read, unclear %s"):format(#slots, tostring(unclear)))
        -- 3. the first thing asked is the first place - before any profession is looked up
        assert(asked[1] and rawequal(asked[1].v, SECRET) and asked[1].infos == 0, "the first place is not what is asked first")
        -- 4. all places empty (a character without professions): nothing read, nothing unclear, no error
        slots, unclear = Places(nil, nil, nil, nil, nil, nil)
        assert(#slots == 0 and unclear == false, "no professions: " .. #slots .. " read, unclear " .. tostring(unclear))
        assert(#asked == 6, ("six empty places: asked whether hidden %d times"):format(#asked))
        -- 5. the order in the source: asked first, compared with nil after
        local f = assert(io.open(ROOT .. "/Skills.lua"))
        local src = f:read("*a") f:close()
        local body = src:match("local function ProfessionSlots%(%)(.-)\nend\n")
        assert(body, "test setup: ProfessionSlots is not found in Skills.lua")
        local askAt = body:find('ns.AnySecret("skills", index)', 1, true)
        local nilAt = body:find("index ~= nil", 1, true) or body:find("index == nil", 1, true)
        assert(askAt and nilAt and askAt < nilAt, "Skills.lua: the place is compared with nil before it is asked whether it is hidden")
    end)
    GetProfessions, GetProfessionInfo, issecretvalue = keep.gp, keep.gi, keep.secret
    assert(ok, err)
end)
step("Prices: every price carries its kind and whether the quantity is its own, as one number an item; history and alerts only see 14 days (v0.2 B2 C1)", function()
    -- Concept item tooltip 4.1-4.3 (Codex M5, R2-M1; Sven S4, 12.11.2026).
    -- What is shown about a price later must be true: which kind of price
    -- it is, a quantity only when it was seen with this very price, and
    -- "the last 14 days" also when nothing was scanned for weeks.
    ns.GetPrice(785) -- (the price data of this realm is made with the first look)
    local p = ns.db.prices[next(ns.db.prices)]
    local AHX = C_AuctionHouse
    local ID, GEAR = 785, 9002 -- Mageroyal (a trade good, a herb), and an item that is none
    local keep = { time = time, atr = Auctionator, tsm = TSM_API, buyout = GetAuctionBuyout, info = GetItemInfo, alerts = ns.db.priceAlerts, alerted = ns.db.alerted,
        browse = AHX.GetBrowseResults, num = AHX.GetNumCommoditySearchResults, row = AHX.GetCommoditySearchResultInfo, full = AHX.HasFullCommoditySearchResults,
        numRep = AHX.GetNumReplicateItems, rep = AHX.GetReplicateItemInfo, replicate = AHX.ReplicateItems,
        items = p.items, qty = p.qty, seen = p.seen, meta = p.meta, scanned = p.scanned, lastScanStart = p.lastScanStart, history = p.history[ID] }
    local clock = keep.time()
    time = function() return clock end
    local fails = {}
    local function Check(ok, text) if not ok then fails[#fails + 1] = text end end
    local function Forget(id)
        p.items[id], p.qty[id], p.seen[id], p.meta[id], p.history[id] = nil, nil, nil, nil, nil
    end
    local function Commodity(price, total, full)
        AHX.GetNumCommoditySearchResults = function() return 1 end
        AHX.GetCommoditySearchResultInfo = function() return { unitPrice = price, quantity = total } end
        AHX.HasFullCommoditySearchResults = function() return full end
        fire("COMMODITY_SEARCH_RESULTS_UPDATED", ID)
    end
    local function Browse(rows)
        AHX.GetBrowseResults = function() return rows end
        fire("AUCTION_HOUSE_BROWSE_RESULTS_UPDATED")
    end
    local ok, err = pcall(function()
        assert(type(ns.PriceInfo) == "function" and type(ns.PriceRev) == "function" and type(ns.PriceHistoryWindow) == "function", "no PriceInfo / PriceRev / PriceHistoryWindow")
        -- one number an item (Sven, 13.11.): 1 = market with its quantity,
        -- 2 = market without, 3 = lowest offer with, 4 = lowest offer
        -- without; none = an entry from before, not known
        assert(type(p.meta) == "table", "the price data has no meta table")
        assert(p.kind == nil and p.qtyOk == nil, "the price data still has the two tables kind / qtyOk")
        Auctionator, TSM_API, GetAuctionBuyout = nil, nil, nil
        fire("AUCTION_HOUSE_SHOW") advance(1)

        -- ---- an entry from before: kind not known, quantity not shown
        Forget(ID)
        p.items[ID], p.qty[ID], p.seen[ID] = 295, 1143, clock - 3600
        local i = ns.PriceInfo(ID)
        Check(i.own == 295 and i.kind == nil and i.qty == nil and i.ownAge == 3600, "old entry: kind " .. tostring(i.kind) .. ", qty " .. tostring(i.qty))

        -- ---- a search with all results: market price, its quantity
        local rev = ns.PriceRev()
        Commodity(500, 240, true)
        i = ns.PriceInfo(ID)
        Check(i.own == 500 and i.kind == "market" and i.qty == 240 and p.meta[ID] == 1, "full search: " .. tostring(i.kind) .. " " .. tostring(i.qty) .. ", meta " .. tostring(p.meta[ID]))
        Check(ns.PriceRev() > rev, "a stored price did not count the revision up")
        -- ---- the same second, a search without all results: the price is new, the 240 are not its own
        Commodity(510, 3, false)
        i = ns.PriceInfo(ID)
        Check(i.own == 510 and i.qty == nil and i.kind == "market" and p.meta[ID] == 2, "same second, then a price without a quantity: qty " .. tostring(i.qty) .. ", meta " .. tostring(p.meta[ID]))
        Check(p.seen[ID] == clock, "test setup: not the same second")
        -- ---- and the other way round: the new quantity shows
        Commodity(520, 77, true)
        i = ns.PriceInfo(ID)
        Check(i.own == 520 and i.qty == 77 and p.meta[ID] == 1, "same second, then a price with a quantity: qty " .. tostring(i.qty) .. ", meta " .. tostring(p.meta[ID]))
        -- an hour later, again without all results
        clock = clock + 3600
        Commodity(530, 5, false)
        Check(ns.PriceInfo(ID).qty == nil and p.meta[ID] == 2, "a quantity of an older look shown with a newer price")

        -- ---- browse: the lowest offer; without totalQuantity the quantity is unknown, not 0
        Forget(ID)
        Browse({ { itemKey = { itemID = ID }, minPrice = 187 } })
        i = ns.PriceInfo(ID)
        Check(i.own == 187 and i.kind == "lowest", "browse: kind " .. tostring(i.kind))
        Check(i.qty == nil and p.qty[ID] == nil and p.meta[ID] == 4, "browse without totalQuantity: stored qty " .. tostring(p.qty[ID]) .. ", meta " .. tostring(p.meta[ID]))
        -- one of two entries without it: unknown for the item
        Forget(ID)
        Browse({ { itemKey = { itemID = ID }, minPrice = 187, totalQuantity = 40 }, { itemKey = { itemID = ID }, minPrice = 190 } })
        Check(ns.PriceInfo(ID).qty == nil and p.meta[ID] == 4, "browse, one entry without totalQuantity: qty " .. tostring(ns.PriceInfo(ID).qty) .. ", meta " .. tostring(p.meta[ID]))
        Forget(ID)
        Browse({ { itemKey = { itemID = ID }, minPrice = 187, totalQuantity = "many" } })
        Check(ns.PriceInfo(ID).qty == nil and p.qty[ID] == nil, "browse, totalQuantity is no number: qty " .. tostring(p.qty[ID]))
        Forget(ID)
        Browse({ { itemKey = { itemID = ID }, minPrice = 187, totalQuantity = 40 }, { itemKey = { itemID = ID }, minPrice = 190, totalQuantity = 2 } })
        i = ns.PriceInfo(ID)
        Check(i.qty == 42 and i.kind == "lowest" and i.own == 187 and p.meta[ID] == 3, "browse with quantities: " .. tostring(i.qty) .. ", meta " .. tostring(p.meta[ID]))
        -- a real 0 is a number
        Forget(ID)
        Browse({ { itemKey = { itemID = ID }, minPrice = 187, totalQuantity = 0 } })
        Check(ns.PriceInfo(ID).qty == 0, "browse, 0 listed told by the game: " .. tostring(ns.PriceInfo(ID).qty))

        -- ---- what each number means, and what is no number of ours: not known, no quantity
        for _, c in ipairs({ { 1, "market", 9 }, { 2, "market" }, { 3, "lowest", 9 }, { 4, "lowest" }, { 0 }, { 5 }, { 1.5 }, { "market" }, { true } }) do
            Forget(ID)
            p.items[ID], p.qty[ID], p.seen[ID], p.meta[ID] = 187, 9, clock, c[1]
            i = ns.PriceInfo(ID)
            Check(i.own == 187 and i.kind == c[2] and i.qty == c[3], "meta " .. tostring(c[1]) .. ": kind " .. tostring(i.kind) .. ", qty " .. tostring(i.qty))
        end
        -- price, time and the number are one step: after a look none of the three is the one before
        Forget(ID)
        p.items[ID], p.qty[ID], p.seen[ID], p.meta[ID] = 187, 9, clock - 50, 3
        Commodity(500, 240, false)
        Check(p.items[ID] == 500 and p.seen[ID] == clock and p.meta[ID] == 2, "a look: price " .. tostring(p.items[ID]) .. ", seen " .. tostring(p.seen[ID] == clock) .. ", meta " .. tostring(p.meta[ID]))

        -- ---- a full scan: market, quantity there again, and the tables replaced
        p.meta[GEAR], p.items[GEAR], p.seen[GEAR] = 3, 5, clock
        Forget(ID)
        Browse({ { itemKey = { itemID = ID }, minPrice = 187 } })
        Check(ns.PriceInfo(ID).qty == nil, "test setup: browse without quantity")
        local function Scan(list, broken)
            fire("AUCTION_HOUSE_CLOSED") fire("AUCTION_HOUSE_SHOW") advance(1)
            p.lastScanStart = nil
            AHX.ReplicateItems = function() end
            AHX.GetNumReplicateItems = function() return #list end
            AHX.GetReplicateItemInfo = function(n)
                local a = list[n + 1]
                if not a then return nil end
                if broken and n + 1 == broken then error("unreadable") end
                return "Item", 1, a.count, 1, true, 1, 0, 0, 0, a.buyout, 0, false, nil, "Seller", nil, 0, a.id, true
            end
            slash("scan") advance(1)
            fire("REPLICATE_ITEM_LIST_UPDATE") advance(2)
        end
        rev = ns.PriceRev()
        Scan({ { id = ID, count = 20, buyout = 20 * 300 }, { id = ID, count = 10, buyout = 10 * 310 } })
        i = ns.PriceInfo(ID)
        Check(i.kind == "market" and i.qty == 30 and i.own == 300 and p.meta[ID] == 1, "full scan: " .. tostring(i.kind) .. " " .. tostring(i.qty) .. " " .. tostring(i.own) .. ", meta " .. tostring(p.meta[ID]))
        Check(p.meta[GEAR] == nil and p.items[GEAR] == nil, "full scan: an item no longer listed kept its kind or quantity state")
        Check(ns.PriceRev() > rev, "a scan did not count the revision up")
        -- a scan with unreadable auctions: what was read is market with its quantity, the rest stays
        clock = clock + 1000
        p.items[GEAR], p.seen[GEAR], p.meta[GEAR], p.qty[GEAR] = 5, clock, 3, 9
        p.meta[ID] = nil
        Scan({ { id = ID, count = 50, buyout = 50 * 320 }, { id = 2447, count = 1, buyout = 30 } }, 2)
        i = ns.PriceInfo(ID)
        Check(i.kind == "market" and i.qty == 50 and i.own == 320 and p.meta[ID] == 1, "incomplete scan: " .. tostring(i.kind) .. " " .. tostring(i.qty) .. " " .. tostring(i.own) .. ", meta " .. tostring(p.meta[ID]))
        Check(p.meta[GEAR] == 3 and p.items[GEAR] == 5, "incomplete scan: took another item's state away")
        Check(p.kind == nil and p.qtyOk == nil, "looks and scans made the two tables kind / qtyOk again")
        Forget(GEAR)

        -- ---- PriceInfo names the source GetPrice names, in every state; an unknown age stays unknown
        local function Own(hours)
            p.items[ID], p.qty[ID], p.seen[ID], p.meta[ID] = 295, 1143, clock - hours * 3600, 1
        end
        local function Atr(price, hasAge, days, breaks)
            local api = { GetAuctionPriceByItemID = function(_, id) return id == ID and price or nil end }
            if hasAge then api.GetAuctionAgeByItemID = function() if breaks then error("broken") end return days end end
            Auctionator = { API = { v1 = api } }
        end
        local states = 0
        local function Same(what, wantSource, wantAge)
            local price, source = ns.GetPrice(ID)
            local info = ns.PriceInfo(ID)
            states = states + 1
            Check(info.source == source and info.used == price, ("%s: PriceInfo %s %s, GetPrice %s %s"):format(what, tostring(info.used), tostring(info.source), tostring(price), tostring(source)))
            if wantSource then Check(source == wantSource, what .. ": source " .. tostring(source) .. ", want " .. wantSource) end
            if wantAge ~= false then Check(info.age == wantAge, what .. ": age " .. tostring(info.age) .. ", want " .. tostring(wantAge)) end
            Check(ns.PriceAgeOf(ID) == info.age, what .. ": PriceAgeOf says " .. tostring(ns.PriceAgeOf(ID)) .. ", PriceInfo " .. tostring(info.age))
        end
        Auctionator = nil
        Own(5) Same("own, 5 h", "AH scan", 5 * 3600)
        Check(not ns.PriceInfo(ID).old and not ns.PriceInfo(ID).tooOld, "5 h: old")
        -- the borders: 5 h 59 min, 6 h, 6 days 23 h, 7 days
        Own(5 + 59 / 60) i = ns.PriceInfo(ID) Check(not i.old and not i.tooOld, "5 h 59 min: old")
        Own(6) i = ns.PriceInfo(ID) Check(i.old and not i.tooOld, "6 h: not old")
        Own(6 * 24 + 23) i = ns.PriceInfo(ID) Check(i.old and not i.tooOld and i.source == "AH scan", "6 days 23 h: " .. tostring(i.source))
        Own(7 * 24) i = ns.PriceInfo(ID)
        Check(i.old and i.tooOld and i.own == 295 and i.source == "vendor" and i.used == 10 and i.age == nil, "7 days: " .. tostring(i.source) .. " " .. tostring(i.used))
        Same("own, 7 days, alone", "vendor", nil)
        -- Auctionator's age: nil (no function / it breaks), math.huge (no number), 0, 3
        Own(21)
        Atr(187) Same("Auctionator, no age function", "Auctionator", nil)
        Atr(187, true, nil, true) Same("Auctionator, the age function breaks", "Auctionator", nil)
        Atr(187, true, 0) Same("Auctionator, today", "Auctionator", 0)
        Own(24 * 4)
        Atr(187, true, 3) Same("Auctionator, 3 days", "Auctionator", 3 * 86400)
        Own(24 * 8)
        Atr(187, true, "old") Same("Auctionator, age no number", "Auctionator", math.huge)
        Own(24)
        Atr(187, true, 3) Same("Auctionator older than our own", "AH scan", 24 * 3600)
        Atr(nil) Same("Auctionator without a price", "AH scan", 24 * 3600)
        -- nothing of our own: Auctionator, TSM (missing / breaks / 0 / there), another addon, the vendor, nothing
        Forget(ID)
        Atr(187, true, 2) Same("no own price, Auctionator", "Auctionator", 2 * 86400)
        Auctionator = nil
        TSM_API = { GetCustomPriceValue = function() error("broken") end } Same("TSM breaks", "vendor", nil)
        TSM_API = { GetCustomPriceValue = function() return 0 end } Same("TSM says 0", "vendor", nil)
        TSM_API = { GetCustomPriceValue = function(what, item) return what == "dbmarket" and item == "i:" .. ID and 444 or nil end } Same("TSM", "TSM", nil)
        TSM_API = nil
        GetAuctionBuyout = function() return 333 end Same("another auction addon", "auction", nil)
        GetAuctionBuyout = nil
        Same("the vendor", "vendor", nil)
        GetItemInfo = function() return "Item" end
        Same("nothing at all", nil, nil)
        Check(ns.PriceInfo(ID).used == nil and ns.PriceInfo(ID).own == nil, "nothing at all: a price")
        GetItemInfo = keep.info
        Check(states >= 16, "only " .. states .. " states compared")
        -- no item: nothing, no error
        Check(ns.PriceInfo(nil).used == nil and ns.PriceAgeOf(nil) == nil, "no item: a price")

        -- ---- the history: only today and the 13 days before, whatever is stored
        local day = math.floor(clock / 86400)
        local function Days(list) local t = {} for _, h in ipairs(list) do t[#t + 1] = h[1] - day .. ":" .. h[2] end return table.concat(t, " ") end
        local function Usual() local u = ns.UsualPrice(ID) return u end
        p.history[ID] = ("%d:90;%d:95;%d:100;%d:110;%d:120"):format(day - 30, day - 14, day - 13, day - 1, day)
        Check(Days(ns.PriceHistoryWindow(ID)) == "-13:100 -1:110 0:120", "window: " .. Days(ns.PriceHistoryWindow(ID)))
        Check(#ns.PriceHistory(ID) == 5, "PriceHistory changed for the others: " .. #ns.PriceHistory(ID))
        Check(Days(ns.PriceHistoryWindow(ID, day + 1)) == "-1:110 0:120", "window, a day later: " .. Days(ns.PriceHistoryWindow(ID, day + 1)))
        Check(#ns.PriceHistoryWindow(GEAR) == 0 and #ns.PriceHistoryWindow(ID, day + 14) == 0, "window: empty cases")
        -- a history of 30 days ago and no scan since: nothing usual, no alert
        local old = {}
        for d = 34, 30, -1 do old[#old + 1] = (day - d) .. ":100" end
        p.history[ID] = table.concat(old, ";") .. ";" .. day .. ":500"
        p.items[ID], p.seen[ID] = 500, clock
        Check(Usual() == nil, "usual price from days outside the window: " .. tostring(Usual()))
        local function Hot() for _, h in ipairs(ns.HotItems()) do if h.id == ID then return h end end end
        Check(not Hot(), "hot item from days outside the window")
        ns.db.priceAlerts, ns.db.alerted = true, {}
        local function Alerted()
            local mark = #log
            Commodity(500, 10, true)
            advance(3)
            for n = mark + 1, #log do if log[n]:find("Item" .. ID, 1, true) and log[n]:find("PRINT", 1, true) then return true end end
        end
        p.history[ID] = table.concat(old, ";")
        Check(not Alerted(), "a price alert from days outside the window")
        -- two days inside the window: still not; three: usual again, and the alert
        p.history[ID] = table.concat(old, ";") .. (";%d:100;%d:100;%d:500"):format(day - 2, day - 1, day)
        Check(Usual() == nil and not Hot(), "usual price from two days: " .. tostring(Usual()))
        p.history[ID] = table.concat(old, ";") .. (";%d:100;%d:110;%d:90;%d:500"):format(day - 13, day - 2, day - 1, day)
        Check(Usual() == 100, "usual price from three days in the window: " .. tostring(Usual()))
        Check(Hot() and Hot().usual == 100, "no hot item with three days in the window")
        ns.db.alerted = {}
        p.history[ID] = table.concat(old, ";") .. (";%d:100;%d:110;%d:90"):format(day - 13, day - 2, day - 1)
        Check(Alerted(), "no price alert with three days in the window")
        -- over midnight (UTC) without a scan: the oldest day falls out, the three are two
        p.history[ID] = ("%d:100;%d:110;%d:120"):format(day - 12, day - 11, day - 10)
        clock = (day + 1) * 86400 + 60
        Check(Usual() == 110, "the day after: " .. tostring(Usual()))
        clock = (day + 2) * 86400 + 60
        Check(Usual() == nil, "two days later, no scan: still a usual price " .. tostring(Usual()))
    end)
    fire("AUCTION_HOUSE_CLOSED")
    time, Auctionator, TSM_API, GetAuctionBuyout, GetItemInfo = keep.time, keep.atr, keep.tsm, keep.buyout, keep.info
    ns.db.priceAlerts, ns.db.alerted = keep.alerts, keep.alerted
    AHX.GetBrowseResults, AHX.GetNumCommoditySearchResults, AHX.GetCommoditySearchResultInfo, AHX.HasFullCommoditySearchResults = keep.browse, keep.num, keep.row, keep.full
    AHX.GetNumReplicateItems, AHX.GetReplicateItemInfo, AHX.ReplicateItems = keep.numRep, keep.rep, keep.replicate
    p.items, p.qty, p.seen, p.meta, p.scanned, p.lastScanStart = keep.items, keep.qty, keep.seen, keep.meta, keep.scanned, keep.lastScanStart
    Forget(ID)
    p.history[ID] = keep.history
    advance(5)
    if not ok then error(err, 0) end
    assert(#fails == 0, #fails .. " wrong: " .. table.concat(fails, " | "))
end)
step("Crafting: a hidden tooltip line is left out and no recipe is learned from it; the recipe book counts its changes (v0.2 B2 C2)", function()
    -- Concept item tooltip 4.5 and 4.8 (Codex's answer 3). The two places
    -- that read tooltip lines to learn recipes looked at every text with
    -- "or" before any check. Now the list and every text are checked first;
    -- a tooltip with a hole teaches nothing. And the "used in" index of the
    -- item tooltip needs to know when the recipe book changed.
    assert(type(ns.RecipeRev) == "function", "no ns.RecipeRev")
    local saved = { secret = issecretvalue, tip = C_TooltipInfo, name = C_Item.GetItemNameByID, num = GetMerchantNumItems, info = GetMerchantItemInfo,
        link = GetMerchantItemLink, debug = ns.db.debug, pending = ns.db.recipePending }
    -- a hidden value: whoever looks into it is counted
    local touched = 0
    local SECRET = setmetatable({}, { __index = function() touched = touched + 1 error("a secret value was read") end,
        __concat = function() touched = touched + 1 error("a secret value was joined") end })
    local function Lines(name, dust, hide)
        local lines = {}
        for i, x in ipairs({ "Formula: " .. name, "Use: Teaches you how to permanently enchant a piece of chest armor.",
            "Strange Dust (" .. dust .. ")", "Requires Enchanting (20)", "Sells for 1 silver" }) do
            lines[#lines + 1] = { leftText = x }
            if hide == i then lines[i].leftText = SECRET end
            if hide == -i then lines[i] = SECRET end
        end
        return { lines = lines }
    end
    local function Book(name) return ns.db.recipeDB and ns.db.recipeDB.Enchanting and ns.db.recipeDB.Enchanting[name] end
    local function Pending(name) return ns.db.recipePending and ns.db.recipePending.Enchanting and ns.db.recipePending.Enchanting[name] end
    local ok, err = pcall(function()
        issecretvalue = function(v) return rawequal(v, SECRET) end
        ns.db.debug = true
        ns.NoteItemName("Strange Dust", 10940)
        local before = #errors

        -- ---- hovering an item (the client's tooltip data): Crafting.lua with the hook
        local hook
        local ns2 = ReloadCrafting(function() return true end, {
            TooltipDataProcessor = { AddTooltipPostCall = function(kind, fn) assert(kind == 7, "hook for another kind of tooltip") hook = fn end },
            Enum = { TooltipDataType = { Item = 7 } } })
        assert(hook, "test setup: no tooltip hook registered")
        local tip = {}
        hook(tip, nil)
        hook(tip, {})
        hook(tip, { lines = SECRET })
        hook(tip, SECRET)
        assert(touched == 0 and #errors == before, "a hidden tooltip or list was looked into (" .. touched .. ")")
        -- every single line hidden once, as text and as a whole: nothing learned, nothing waits
        for i = 1, 5 do
            for _, hide in ipairs({ i, -i }) do
                local name = "Enchant Chest - Test " .. i .. (hide < 0 and "b" or "a")
                hook(tip, Lines(name, 2, hide))
                assert(touched == 0, "line " .. i .. " hidden: it was read (" .. touched .. ")")
                assert(not Book(name) and not Pending(name), "line " .. i .. " hidden: a recipe was learned from the rest")
            end
        end
        assert(#errors == before, "an error: " .. tostring(errors[#errors]))
        local told
        for _, l in ipairs(log) do if l:find("secret value skipped in recipe tooltip", 1, true) then told = true end end
        assert(told, "/gcr debug does not tell that a hidden value was skipped")
        -- all lines readable: learned as before
        local rev = ns2.RecipeRev()
        hook(tip, Lines("Enchant Chest - Test Whole", 2))
        assert(Book("Enchant Chest - Test Whole") == "0:1:1:20|10940:2", "a readable tooltip: " .. tostring(Book("Enchant Chest - Test Whole")))
        assert(ns2.RecipeRev() == rev + 1, "a new recipe did not count the revision up: " .. rev .. " -> " .. ns2.RecipeRev())
        -- the same again changes nothing, a changed one counts
        hook(tip, Lines("Enchant Chest - Test Whole", 2))
        assert(ns2.RecipeRev() == rev + 1, "the same recipe again counted the revision up")

        -- ---- a recipe at a vendor (read by item ID): the same two rules
        local shown
        C_TooltipInfo = { GetItemByID = function(id) return id == 6343 and shown or nil end }
        GetMerchantNumItems = function() return 1 end
        GetMerchantItemInfo = function() return "Formula: Enchant Chest - Test Vendor", 134400, 300, 1, 1, true, false, nil end
        GetMerchantItemLink = function() return "|Hitem:6343::|h" end
        for _, hide in ipairs({ 1, 3, -4, 5 }) do
            shown = Lines("Enchant Chest - Test Vendor", 3, hide)
            fire("MERCHANT_SHOW") advance(2)
            assert(touched == 0 and #errors == before, "vendor, line " .. hide .. " hidden: read or an error (" .. tostring(errors[#errors]) .. ")")
            assert(not Book("Enchant Chest - Test Vendor") and not Pending("Enchant Chest - Test Vendor"), "vendor, line " .. hide .. " hidden: learned")
        end
        shown = { lines = SECRET }
        fire("MERCHANT_SHOW") advance(2)
        shown = SECRET
        fire("MERCHANT_SHOW") advance(2)
        assert(touched == 0 and #errors == before, "vendor, the whole tooltip hidden: read or an error")
        rev = ns.RecipeRev()
        shown = Lines("Enchant Chest - Test Vendor", 3)
        fire("MERCHANT_SHOW") advance(2)
        assert(Book("Enchant Chest - Test Vendor") == "0:1:1:20|10940:3", "vendor, readable: " .. tostring(Book("Enchant Chest - Test Vendor")))
        assert(ns.RecipeRev() == rev + 1, "vendor: the revision " .. rev .. " -> " .. ns.RecipeRev())
        fire("MERCHANT_SHOW") advance(2)
        assert(ns.RecipeRev() == rev + 1, "vendor: the same recipe again counted")

        -- ---- the saved recipe book is looked through once a session. Data in
        -- order - every login but the first after an old version - is the same
        -- book: no count, so the "used in" index is not built a second time
        ReloadCrafting(function() return true end).CraftAdvice("Enchanting") -- (in order from here on)
        local function Shape()
            local parts = {}
            for prof, list in pairs(ns.db.recipeDB) do
                for name, packed in pairs(list) do parts[#parts + 1] = prof .. "/" .. name .. "=" .. packed end
            end
            table.sort(parts)
            return table.concat(parts, "\n")
        end
        local shape = Shape()
        local ns3 = ReloadCrafting(function() return true end)
        local r3 = ns3.RecipeRev()
        ns3.CraftAdvice("Enchanting")
        assert(Shape() == shape, "test setup: the recipe book was not in order")
        assert(ns3.RecipeRev() == r3, "looking through a recipe book in order counted as a change: " .. r3 .. " -> " .. ns3.RecipeRev())
        -- a profession saved under another spelling is moved: that is a change, once
        ns.db.recipeDB.enchanting = { ["Enchant Chest - Test Moved"] = "0:1:1:20|10940:2" }
        local ns4 = ReloadCrafting(function() return true end)
        local r4 = ns4.RecipeRev()
        ns4.CraftAdvice("Enchanting")
        assert(ns.db.recipeDB.enchanting == nil and Book("Enchant Chest - Test Moved") == "0:1:1:20|10940:2", "the profession under another spelling was not moved")
        assert(ns4.RecipeRev() == r4 + 1, "moving saved recipes did not count: " .. r4 .. " -> " .. ns4.RecipeRev())
        ns4.CraftAdvice("Enchanting")
        assert(ns4.RecipeRev() == r4 + 1, "moving counted twice")
        -- a shipped recipe saved under another spelling of its name: moved, a change
        local shippedName
        for name in pairs(GathercraftRecipeData.professions.Enchanting) do
            if not Book(name) and name:lower() ~= name and (not shippedName or name < shippedName) then shippedName = name end
        end
        assert(shippedName, "test setup: no shipped Enchanting recipe free")
        ns.db.recipeDB.Enchanting[shippedName:lower()] = GathercraftRecipeData.professions.Enchanting[shippedName]
        local ns5 = ReloadCrafting(function() return true end)
        local r5 = ns5.RecipeRev()
        ns5.CraftAdvice("Enchanting")
        assert(Book(shippedName) and not Book(shippedName:lower()), "the recipe under another spelling was not moved")
        assert(ns5.RecipeRev() == r5 + 1, "moving one recipe did not count: " .. r5 .. " -> " .. ns5.RecipeRev())
        ns.db.recipeDB.Enchanting[shippedName] = nil
    end)
    if ns.db.recipeDB then ns.db.recipeDB.enchanting = nil end
    issecretvalue, C_TooltipInfo, C_Item.GetItemNameByID = saved.secret, saved.tip, saved.name
    GetMerchantNumItems, GetMerchantItemInfo, GetMerchantItemLink = saved.num, saved.info, saved.link
    ns.db.debug, ns.db.recipePending = saved.debug, saved.pending
    for name in pairs(ns.db.recipeDB and ns.db.recipeDB.Enchanting or {}) do
        if name:find("Enchant Chest - Test", 1, true) then ns.db.recipeDB.Enchanting[name] = nil end
    end
    if not ok then error(err, 0) end
end)
step("Spawn points of an item per zone: places are counted once, your own only where Questie has none (v0.2 B2 C3)", function()
    -- Concept item tooltip 4.4 (Codex M4), Sven S2 of 12.11.2026. The same
    -- place stands under several object IDs of one item: a sum counts it
    -- twice. Own points count only when they are no Questie place of the
    -- item; sync, starter data and minimap sightings never.
    assert(type(ns.SpawnCounts) == "function" and type(ns.SpawnCountsStart) == "function" and type(ns.SpawnCountsStop) == "function"
        and type(ns.SpawnCountsState) == "function", "no ns.SpawnCounts / Start / Stop / State")
    local data = GathercraftQuestieData
    local ZONE = 99999 -- a zone of this test, with places of this test
    local saved = { zone = data.zones[ZONE], nodes = ns.db.nodes[ZONE], tooltip = ns.db.tooltipPrices }
    local toc = assert(io.open(ROOT .. "/Gathercraft.toc")):read("*a")
    assert(toc:find("\nSpawnCounts.lua", 1, true), "SpawnCounts.lua is not in the TOC")
    -- (the item tooltip uses the counts too: it is off while this step counts)
    if ns.ItemTooltipSetEnabled then ns.ItemTooltipSetEnabled(false) end
    local function Zone(itemID, mapID)
        local list = ns.SpawnCounts(itemID)
        for _, z in ipairs(list or {}) do if z.mapID == mapID then return z end end
    end
    local function Total(itemID, mapID) local z = Zone(itemID, mapID) return z and z.total or (ns.SpawnCounts(itemID) and 0 or nil) end
    local ok, err = pcall(function()
        assert(ns.SpawnCountsState() == "off", "the counts are built although nobody uses them: " .. tostring(ns.SpawnCountsState()))
        assert(ns.SpawnCounts(765) == nil, "numbers without a build")

        -- ---- loaded before the data files: no look at them, no error
        local keepData = GathercraftQuestieData
        GathercraftQuestieData = nil
        local ns2 = setmetatable({ nodeListeners = {} }, { __index = ns })
        local chunkOk, chunkErr = pcall(assert(loadfile(ROOT .. "/SpawnCounts.lua")), "Gathercraft", ns2)
        GathercraftQuestieData = keepData
        assert(chunkOk, "loading SpawnCounts.lua without the data: " .. tostring(chunkErr))
        assert(ns2.SpawnCountsState() == "off" and #ns2.nodeListeners == 1, "the copy built something or does not listen")

        -- ---- the places of this test: two object IDs of one item
        local ids = {}
        for id, kind in pairs(data.kinds) do
            if kind[2] == 3340 and (kind[1] == "o" or kind[1] == "h") then ids[#ids + 1] = tonumber(id:sub(2)) end
        end
        table.sort(ids)
        assert(#ids >= 2, "test setup: Incendicite has " .. #ids .. " node kinds, want two or more")
        local A, B = ids[1], ids[2]
        local ITEM, OTHER = 3340, 765
        local CHEST
        for id, kind in pairs(data.kinds) do if kind[1] == "c" then CHEST = id break end end
        assert(CHEST, "test setup: no chest kind in the data")
        -- (the map of the harness is 5000 x 3333 yards: 0.0010 of its width is 5 yards)
        data.zones[ZONE] = table.concat({
            A .. ",1000,5000", B .. ",1000,5000",      -- one place under both IDs
            A .. ",1010,5000",                          -- 5 yards beside it: another place
            A .. ",3000,5000",                          -- a place only A has
            B .. ",6000,5000",                          -- a place only B has
        }, ",")
        local function Own(x, extra)
            local n = { id = "o" .. A, name = "Incendicite Mineral Vein", type = "ore", x = x, y = 0.5, count = 1, last = time() }
            for k, v in pairs(extra or {}) do n[k] = v end
            return n
        end
        local sync = Own(0.8000, { source = "sync" })
        ns.db.nodes[ZONE] = {
            Own(0.3020),                              -- 10 yards beside A's own place: that place
            Own(0.6020),                              -- 10 yards beside a place only the OTHER ID has: that place
            Own(0.3040, { id = "o" .. B }),           -- 20 yards beside: a point of your own
            Own(0.4000), Own(0.4024),                 -- two neighbours 12 yards apart, far from every place: two
            sync,                                     -- from sync
            Own(0.8200, { source = "starter" }),      -- starter data
            Own(0.8400, { seenOnly = true }),         -- only seen on the minimap
            Own(0.8600, { source = "questie" }),      -- the spawn data itself
            Own(0.8800, { id = "o999999" }),          -- a kind the spawn data does not know
            { id = CHEST, type = "chest", x = 0.9, y = 0.5 }, -- not a herb or an ore
        }

        -- ---- built in steps after Start, nothing before it is done
        ns.SpawnCountsStart("test")
        assert(ns.SpawnCountsState() == "building" and ns.SpawnCounts(ITEM) == nil, "numbers while building")
        advance(10)
        assert(ns.SpawnCountsState() == "ready", "not ready 10 s after the start: " .. tostring(ns.SpawnCountsState()))

        -- ---- Questie: the union. Codex's three numbers, counted here again
        local function Entries(itemID, mapID)
            local n, places, seen = 0, 0, {}
            for id, x, y in data.zones[mapID]:gmatch("(%d+),(%d+),(%d+)") do
                local kind = data.kinds["o" .. id]
                if kind and kind[2] == itemID and (kind[1] == "o" or kind[1] == "h") then
                    n = n + 1
                    if not seen[x .. ":" .. y] then seen[x .. ":" .. y] = true places = places + 1 end
                end
            end
            return n, places
        end
        local e1, p1 = Entries(3340, 1437)
        assert(e1 == 58 and p1 == 29, ("Incendicite in 1437: the data has %d entries at %d places (Codex: 58, 29)"):format(e1, p1))
        assert(Zone(3340, 1437) and Zone(3340, 1437).questie == 29, "Incendicite in 1437: " .. tostring(Zone(3340, 1437) and Zone(3340, 1437).questie) .. ", want 29 (58 would be the sum)")
        local e2, p2 = Entries(10620, 1423)
        assert(e2 == 174 and p2 == 87 and Zone(10620, 1423).questie == 87, ("Thorium in 1423: %d entries, %d places, counted %s"):format(e2, p2, tostring(Zone(10620, 1423).questie)))
        local e3, p3 = Entries(765, 1413)
        assert(e3 == 118 and p3 == 104 and Zone(765, 1413).questie == 104, ("Silverleaf in 1413: %d entries, %d places, counted %s"):format(e3, p3, tostring(Zone(765, 1413).questie)))
        -- every item and zone of the data against this second count
        local checked = 0
        for itemID in pairs({ [3340] = 1, [10620] = 1, [765] = 1, [2447] = 1, [2770] = 1, [2771] = 1, [785] = 1, [3356] = 1 }) do
            for mapID in pairs(data.zones) do
                if mapID ~= ZONE then
                    local _, places = Entries(itemID, mapID)
                    local z = Zone(itemID, mapID)
                    assert((z and z.questie or 0) == places, ("item %d in %d: counted %s, the data has %d places"):format(itemID, mapID, tostring(z and z.questie), places))
                    checked = checked + 1
                end
            end
        end
        assert(checked > 200, "only " .. checked .. " item-zone pairs checked")
        -- close places stay apart: (1000) under both IDs is one, (1010) another, (3000), (6000)
        local z = Zone(ITEM, ZONE)
        assert(z and z.questie == 4, "the test zone: " .. tostring(z and z.questie) .. " Questie places, want 4")

        -- ---- your own points
        assert(z.own == 3 and z.total == 7, ("own points: %d (total %d), want 3: one 20 yards beside a place, two neighbours"):format(z.own, z.total))
        -- most places first, the same order every time
        local list = ns.SpawnCounts(ITEM)
        for i = 2, #list do
            assert(list[i - 1].total > list[i].total or (list[i - 1].total == list[i].total and list[i - 1].mapID < list[i].mapID), "the zones are not in order at " .. i)
        end
        -- an item nobody gathers from a node: an empty list, not "not ready"
        assert(type(ns.SpawnCounts(2589)) == "table" and #ns.SpawnCounts(2589) == 0, "linen cloth: " .. tostring(ns.SpawnCounts(2589)))

        -- ---- a synced node you gathered yourself is yours; until the recount there is no number
        sync.source = nil
        ns.NotifyNodesChanged("update", ZONE, sync)
        assert(ns.SpawnCounts(ITEM) == nil, "an old number right after a node changed")
        assert(ns.SpawnCounts(OTHER) ~= nil, "another item lost its numbers through one node")
        advance(1)
        assert(ns.SpawnCounts(ITEM) == nil, "counted again at once, not bundled")
        advance(5)
        assert(Total(ITEM, ZONE) == 8, "after the recount: " .. tostring(Total(ITEM, ZONE)) .. ", want 8")
        -- a new own node far from everything
        local new = Own(0.7000)
        table.insert(ns.db.nodes[ZONE], new)
        ns.NotifyNodesChanged("add", ZONE, new)
        advance(5)
        assert(Total(ITEM, ZONE) == 9, "a new node of your own: " .. tostring(Total(ITEM, ZONE)) .. ", want 9")
        -- a chest changes no count and takes no number away
        ns.NotifyNodesChanged("update", ZONE, ns.db.nodes[ZONE][11])
        assert(ns.SpawnCounts(ITEM) ~= nil, "a chest took the numbers away")
        -- a change nobody names (delete, import): everything waits, every zone is counted again
        table.remove(ns.db.nodes[ZONE]) -- the new node
        ns.NotifyNodesChanged()
        assert(ns.SpawnCounts(ITEM) == nil and ns.SpawnCounts(OTHER) == nil, "an old number after a change without a name")
        advance(10)
        assert(Total(ITEM, ZONE) == 8, "after the full recount: " .. tostring(Total(ITEM, ZONE)) .. ", want 8")
        -- the last own points of a zone gone: the zone keeps its Questie places
        ns.db.nodes[ZONE] = nil
        ns.NotifyNodesChanged()
        advance(10)
        assert(Total(ITEM, ZONE) == 4 and Zone(ITEM, ZONE).own == 0, "without own points: " .. tostring(Total(ITEM, ZONE)))
        -- a zone without spawn data: only your own points of known kinds
        ns.db.nodes[ZONE + 1] = { Own(0.5), Own(0.6, { id = "o999999" }) }
        ns.NotifyNodesChanged("add", ZONE + 1, ns.db.nodes[ZONE + 1][1])
        advance(5)
        z = Zone(ITEM, ZONE + 1)
        assert(z and z.questie == 0 and z.own == 1 and z.total == 1, "a zone without spawn data: " .. tostring(z and z.total))
        ns.db.nodes[ZONE + 1] = nil

        -- ---- users: the counts stay while one of them wants them
        ns.SpawnCountsStart("second")
        ns.SpawnCountsStop("test")
        assert(ns.SpawnCountsState() == "ready" and ns.SpawnCounts(OTHER), "stopped although a user is left")
        ns.SpawnCountsStop("second")
        assert(ns.SpawnCountsState() == "off" and ns.SpawnCounts(OTHER) == nil, "numbers without a user")
        -- stopped in the middle of the build: it ends, no error, nothing built
        local before = #errors
        ns.SpawnCountsStart("test")
        advance(0.1)
        assert(ns.SpawnCountsState() == "building", "test setup: the build was done after 0.1 s")
        ns.SpawnCountsStop("test")
        advance(10)
        assert(ns.SpawnCountsState() == "off" and ns.SpawnCounts(OTHER) == nil and #errors == before, "a build went on after the stop")
        -- node changes while nobody uses the counts cost nothing and break nothing
        ns.NotifyNodesChanged()
        advance(5)
        assert(ns.SpawnCountsState() == "off" and #errors == before, "a node change woke the counts")
    end)
    ns.SpawnCountsStop("test") ns.SpawnCountsStop("second")
    data.zones[ZONE], ns.db.nodes[ZONE], ns.db.nodes[ZONE + 1] = saved.zone, saved.nodes, nil
    ns.NotifyNodesChanged()
    advance(5)
    if ns.ItemTooltipSetEnabled then ns.ItemTooltipSetEnabled(saved.tooltip ~= false) end
    if not ok then error(err, 0) end
end)
-- The item tooltip in a fixture of its own (0.2 B2 C4): ItemTooltip.lua
-- loaded into its own namespace with the tooltip APIs a test names, before
-- its first load - the copy the whole run loaded once says nothing about
-- how often something registers (Codex's answer 4).
local TT = {}
-- a tooltip like the client's: lines, scripts, a count of its lines;
-- with canClear it has OnTooltipCleared
function TT.Tip(canClear)
    local tip = { lines = {}, scripts = {}, shows = 0, hooks = 0 }
    function tip:AddLine(t) self.lines[#self.lines + 1] = t end
    function tip:AddDoubleLine(l, r) self.lines[#self.lines + 1] = l .. " = " .. r end
    function tip:NumLines() return #self.lines end
    function tip:HasScript(name) return name == "OnTooltipSetItem" or (canClear and name == "OnTooltipCleared") or false end
    function tip:HookScript(name, fn)
        assert(self:HasScript(name), "HookScript for a script this tooltip does not have: " .. tostring(name))
        local old = self.scripts[name]
        self.scripts[name] = function(...) if old then old(...) end fn(...) end
        self.hooks = self.hooks + 1
    end
    function tip:GetItem() return "Item", self.link end
    function tip:Show() self.shows = self.shows + 1 end
    function tip:Clear()
        self.lines = {}
        if self.scripts.OnTooltipCleared then self.scripts.OnTooltipCleared(self) end
    end
    return tip
end
-- way: "tdp" (the client's tooltip data) or "script" (OnTooltipSetItem).
-- ns2: load into this namespace again (the same file loaded twice).
function TT.Load(way, canClear, ns2)
    local fx = { posts = {}, game = TT.Tip(canClear), ref = TT.Tip(canClear), way = way }
    local keep = { tdp = TooltipDataProcessor, enum = Enum, game = GameTooltip, ref = ItemRefTooltip }
    if way == "tdp" then
        TooltipDataProcessor = { AddTooltipPostCall = function(kind, fn)
            assert(kind == 7, "a post call for another kind of tooltip: " .. tostring(kind))
            fx.posts[#fx.posts + 1] = fn
        end }
        Enum = setmetatable({ TooltipDataType = { Item = 7 } }, { __index = keep.enum })
    else
        TooltipDataProcessor = nil
    end
    GameTooltip, ItemRefTooltip = fx.game, fx.ref
    fx.ns = ns2 or setmetatable({ itemTooltipHooked = false, languageListeners = {},
        SpawnCountsStart = function() fx.spawnStarts = (fx.spawnStarts or 0) + 1 end, SpawnCountsStop = function() fx.spawnStops = (fx.spawnStops or 0) + 1 end }, { __index = ns })
    local before = #allFrames
    local ok, err = pcall(assert(loadfile(ROOT .. "/ItemTooltip.lua")), "Gathercraft", fx.ns)
    TooltipDataProcessor, Enum, GameTooltip, ItemRefTooltip = keep.tdp, keep.enum, keep.game, keep.ref
    for i = before + 1, #allFrames do
        local f = allFrames[i]
        if eventFrames.PLAYER_LOGIN and eventFrames.PLAYER_LOGIN[f] then fx.frame = f end
        for _, list in pairs(eventFrames) do list[f] = nil end
    end
    assert(ok, "loading ItemTooltip.lua: " .. tostring(err))
    -- one build of a tooltip, as the client does it: cleared, its own lines,
    -- then `calls` rounds of the item hook. keepLines: no new build, only more rounds.
    function fx.Hover(tip, itemID, calls, keepLines)
        if not keepLines then
            tip:Clear()
            tip.lines = { "Item" .. tostring(itemID), "Item Level 1" }
        end
        tip.link = type(itemID) == "number" and ("|Hitem:" .. itemID .. "::|h") or itemID
        for _ = 1, calls or 1 do
            if way == "tdp" then
                for _, fn in ipairs(fx.posts) do fn(tip, { id = itemID, lines = {} }) end
            elseif tip.scripts.OnTooltipSetItem then
                tip.scripts.OnTooltipSetItem(tip)
            end
        end
        return tip.lines
    end
    function fx.Event(event) fx.frame.__scripts.OnEvent(fx.frame, event) end
    function fx.State() return fx.ns.ItemTooltipState().state end
    return fx
end
function TT.Count(lines, text)
    local n = 0
    for _, l in ipairs(lines) do if l:find(text, 1, true) then n = n + 1 end end
    return n
end
function TT.Line(lines, text)
    for _, l in ipairs(lines) do if l:find(text, 1, true) then return l end end
end
-- text as the player reads it: without colour codes
function TT.Plain(text) return (text:gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", "")) end

step("Item tooltip: one hook, and our lines once for every build of a tooltip - both hook ways (v0.2 B2 C4)", function()
    -- Concept item tooltip 4.7, 5.4, 6 (Codex M8, answer 4).
    ns.GetPrice(785)
    local p = ns.db.prices[next(ns.db.prices)]
    local HERB, GEAR = 785, 9003
    local saved = { option = ns.db.tooltipPrices, shift = IsShiftKeyDown, secret = issecretvalue, time = time }
    local function Forget(id) p.items[id], p.qty[id], p.seen[id], p.meta[id], p.history[id] = nil, nil, nil, nil, nil end
    local touched = 0
    local SECRET = setmetatable({}, { __index = function() touched = touched + 1 error("a secret value was read") end })
    local clock = saved.time()
    time = function() return clock end
    local before = #errors
    local ok, err = pcall(function()
        ns.db.tooltipPrices = true
        Forget(HERB) Forget(GEAR)
        p.items[HERB], p.seen[HERB], p.meta[HERB], p.qty[HERB] = 295, clock - 3600, 1, 240
        p.items[GEAR], p.seen[GEAR], p.meta[GEAR], p.qty[GEAR] = 77700, clock - 3600, 3, 3
        local OURS = "Gathercraft"
        for _, way in ipairs({ "tdp", "script" }) do
            for _, canClear in ipairs({ true, false }) do
                local what = way .. (canClear and ", OnTooltipCleared" or ", no OnTooltipCleared") .. ": "
                local fx = TT.Load(way, canClear)
                -- ---- registered one way only
                if way == "tdp" then
                    assert(#fx.posts == 1 and fx.game.hooks == 0 and fx.ref.hooks == 0, what .. #fx.posts .. " post calls, " .. fx.game.hooks .. " script hooks")
                else
                    assert(#fx.posts == 0 and fx.game.hooks == 1 and fx.ref.hooks == 1, what .. fx.game.hooks .. " + " .. fx.ref.hooks .. " script hooks")
                end
                assert(fx.ns.ItemTooltipState().way == (way == "tdp" and "TooltipDataProcessor" or "OnTooltipSetItem"), what .. "the way named: " .. fx.ns.ItemTooltipState().way)
                -- ---- the file loaded a second time registers nothing, and a build still has our lines once
                do
                    local first = TT.Load(way, canClear)
                    local again = TT.Load(way, canClear, first.ns)
                    assert(#again.posts == 0 and again.game.hooks == 0 and again.ref.hooks == 0, what .. "a second load registered again")
                    local twice = first.Hover(first.game, GEAR, 2)
                    assert(TT.Count(twice, OURS) == 1 and #twice == 3, what .. "loaded twice: " .. table.concat(twice, " / "))
                end
                -- ---- nothing is built before the login, and nothing while the file loads
                assert(fx.State() == "off" and not fx.spawnStarts, what .. "built before the login")
                fx.ns.ItemTooltipSetEnabled(true) -- (the saved switch is on anyway; saying so again starts nothing before the login)
                assert(fx.State() == "off" and not fx.spawnStarts, what .. "switching the option on built before the login")
                fx.Event("PLAYER_LOGIN")
                assert(fx.State() == "off", what .. "built in the login event itself")
                advance(5)
                assert(fx.State() == "ready" and fx.spawnStarts == 1, what .. "not ready 5 s after the login: " .. fx.State())
                local tip = fx.game
                -- ---- a normal build: one block
                local lines = fx.Hover(tip, HERB)
                assert(TT.Count(lines, OURS) == 1 and #lines == 5, what .. "a build: " .. TT.Count(lines, OURS) .. " blocks, " .. #lines .. " lines")
                assert(TT.Line(lines, ns.Money(295)), what .. "the price is not in the block")
                -- ---- the hook called again for the same build: nothing more
                fx.Hover(tip, HERB, 3, true)
                assert(#tip.lines == 5, what .. "more rounds for one build: " .. #tip.lines .. " lines, want 5")
                -- ---- the same item built anew: its block again, once
                lines = fx.Hover(tip, HERB, 2)
                assert(TT.Count(lines, OURS) == 1 and #lines == 5, what .. "built anew: " .. TT.Count(lines, OURS) .. " blocks, " .. #lines .. " lines")
                -- ---- another item: its line, nothing of the one before
                lines = fx.Hover(tip, GEAR, 2)
                assert(TT.Count(lines, OURS) == 1 and #lines == 3 and TT.Line(lines, ns.Money(77700)) and not TT.Line(lines, ns.Money(295)),
                    what .. "another item: " .. table.concat(lines, " / "))
                -- ---- Shift: built anew by the client - one block with the details, not two
                IsShiftKeyDown = function() return true end
                lines = fx.Hover(tip, HERB, 2)
                assert(TT.Count(lines, OURS) == 1 and TT.Count(lines, ns.L["AH price"]) == 1 and TT.Count(lines, ns.L["14 days"]) == 1,
                    what .. "with Shift: " .. table.concat(lines, " / "))
                assert(TT.Line(lines, ns.L["Used in"]), what .. "with Shift: no details")
                local withShift = #lines
                IsShiftKeyDown = function() return false end
                lines = fx.Hover(tip, HERB, 2)
                assert(#lines == 5 and TT.Count(lines, OURS) == 1, what .. "Shift let go: " .. #lines .. " lines")
                assert(withShift > 5, what .. "Shift showed nothing more")
                -- ---- the other tooltip (a chat link) has its own state
                lines = fx.Hover(fx.ref, HERB, 2)
                assert(TT.Count(lines, OURS) == 1 and #lines == 5 and #tip.lines == 5, what .. "the second tooltip: " .. #lines .. " lines")
                -- ---- other addons' lines: ours once, theirs untouched - whoever is called how often
                tip:Clear()
                tip.lines = { "Item", "Auctionator  12s" }
                fx.Hover(tip, HERB, 1, true)
                table.insert(tip.lines, "TSM  13s")
                fx.Hover(tip, HERB, 2, true)
                assert(TT.Count(tip.lines, OURS) == 1 and #tip.lines == 6 and tip.lines[1] == "Item" and tip.lines[2] == "Auctionator  12s" and tip.lines[6] == "TSM  13s",
                    what .. "with other addons' lines: " .. table.concat(tip.lines, " / "))
                -- ---- another item whose own tooltip is as long as the one before with our lines: it gets its line all the same
                -- (matters where a cleared tooltip cannot tell us: the mark is the item, not the length alone)
                fx.Hover(tip, HERB)
                tip:Clear()
                tip.lines = { "Item" .. GEAR, "Item Level 1", "Binds when equipped", "Chest", "12 Armor", "Durability 60 / 60" }
                fx.Hover(tip, GEAR, 2, true)
                assert(TT.Count(tip.lines, OURS) == 1 and #tip.lines == 7 and TT.Line(tip.lines, ns.Money(77700)), what .. "a longer tooltip of another item: " .. table.concat(tip.lines, " / "))
                -- ---- OnTooltipSetItem: the tooltip is told to lay itself out again when lines came, the other way needs none
                if way == "script" then assert(tip.shows > 0, what .. "Show() not called after adding lines") else assert(tip.shows == 0, what .. "Show() called") end
                -- ---- a hidden item ID or link: no line, nothing read
                issecretvalue = function(v) return rawequal(v, SECRET) end
                local n = #fx.Hover(tip, SECRET, 2)
                assert(n == 2 and touched == 0, what .. "a hidden item: " .. n .. " lines, read " .. touched .. " times")
                -- (a hidden value can look like any other: a number, a text - only issecretvalue tells)
                issecretvalue = function(v) return v == GEAR or v == "|Hitem:" .. GEAR .. "::|h" end
                n = #fx.Hover(tip, GEAR, 2)
                assert(n == 2, what .. "a hidden item ID that looks like a number: " .. (n - 2) .. " lines of ours")
                issecretvalue = function(v) return rawequal(v, SECRET) end
                if way == "tdp" then
                    fx.posts[1](tip, SECRET)
                    fx.posts[1](SECRET, { id = HERB })
                    fx.posts[1](tip, nil)
                    fx.posts[1](tip, { id = "785" })
                    assert(#tip.lines == 2 and touched == 0, what .. "hidden tooltip data: " .. #tip.lines .. " lines, read " .. touched .. " times")
                end
                issecretvalue = saved.secret
                -- ---- the option off: no line, the indexes gone; on again: built again
                fx.ns.ItemTooltipSetEnabled(false)
                assert(fx.State() == "off" and fx.spawnStops == 1, what .. "off: " .. fx.State())
                assert(#fx.Hover(tip, HERB, 2) == 2, what .. "off: lines")
                advance(5)
                assert(fx.State() == "off", what .. "off: built all the same")
                fx.ns.ItemTooltipSetEnabled(true)
                assert(fx.State() == "building" and fx.spawnStarts == 2, what .. "on again: " .. fx.State())
                -- hovering while the recipes are read: the lines that are done, "used in" not yet, no error
                IsShiftKeyDown = function() return true end
                lines = fx.Hover(tip, HERB, 2)
                IsShiftKeyDown = function() return false end
                assert(TT.Count(lines, OURS) == 1 and TT.Line(lines, ns.Money(295)) and not TT.Line(lines, ns.L["Used in"]), what .. "while building: " .. table.concat(lines, " / "))
                -- off in the middle of the build: it ends, no error
                advance(0.11)
                assert(fx.State() == "building", what .. "test setup: built within 0.11 s")
                fx.ns.ItemTooltipSetEnabled(false)
                advance(5)
                assert(fx.State() == "off" and #errors == before, what .. "off while building: " .. fx.State() .. ", " .. tostring(errors[#errors]))
                fx.ns.ItemTooltipSetEnabled(true)
                advance(5)
                lines = fx.Hover(tip, HERB)
                assert(fx.State() == "ready" and #lines == 5, what .. "on again: " .. fx.State() .. ", " .. #lines .. " lines")
                assert(#errors == before, what .. "an error: " .. tostring(errors[#errors]))
            end
        end
        -- ---- loaded before the data files: no look at them, no error (they come later in the TOC)
        local keepQ, keepR = GathercraftQuestieData, GathercraftRecipeData
        GathercraftQuestieData, GathercraftRecipeData = nil, nil
        local early = TT.Load("tdp", true)
        GathercraftQuestieData, GathercraftRecipeData = keepQ, keepR
        assert(early.State() == "off", "loaded before the data: " .. early.State())
        local toc = assert(io.open(ROOT .. "/Gathercraft.toc")):read("*a")
        assert(toc:find("\nItemTooltip.lua", 1, true), "ItemTooltip.lua is not in the TOC")
        -- ---- the old price line is gone from Prices.lua: one module shows, not two
        local src = assert(io.open(ROOT .. "/Prices.lua")):read("*a")
        assert(not src:find("TooltipDataProcessor", 1, true) and not src:find("OnTooltipSetItem", 1, true), "Prices.lua still hooks the item tooltip")
    end)
    IsShiftKeyDown, issecretvalue, time = saved.shift, saved.secret, saved.time
    ns.db.tooltipPrices = saved.option
    Forget(HERB) Forget(GEAR)
    if not ok then error(err, 0) end
end)
step("Item tooltip: the price line says what kind of price, how old, how many - and what is not known (v0.2 B2 C4)", function()
    -- Concept item tooltip 3, 4.1-4.3, 5.1, 5.2, 5.9; Sven's decisions 3, 5
    -- and S3. The price is asked for with every hover, so the borders and
    -- a change in Auctionator show without a scan.
    ns.GetPrice(785)
    local p = ns.db.prices[next(ns.db.prices)]
    local L = ns.L
    local HERB, GEAR, GOOD, ROCK = 785, 9003, 9005, 3340 -- a herb; gear; a trade good nobody gathers or crafts with; a mineral that is no trade good here
    local saved = { option = ns.db.tooltipPrices, time = time, atr = Auctionator, tsm = TSM_API, buyout = GetAuctionBuyout, info = GetItemInfo,
        instant = C_Item.GetItemInfoInstant, shift = IsShiftKeyDown }
    local function Forget(id) p.items[id], p.qty[id], p.seen[id], p.meta[id], p.history[id] = nil, nil, nil, nil, nil end
    local clock = saved.time()
    time = function() return clock end
    local fails = {}
    local function Check(ok, text) if not ok then fails[#fails + 1] = text end end
    local ok, err = pcall(function()
        ns.db.tooltipPrices = true
        Auctionator, TSM_API, GetAuctionBuyout = nil, nil, nil
        C_Item.GetItemInfoInstant = function(id)
            if id == GOOD then return id, nil, nil, nil, nil, 7, 9 end
            return saved.instant(id)
        end
        for _, id in ipairs({ HERB, GEAR, GOOD, ROCK }) do Forget(id) end
        local fx = TT.Load("tdp", true)
        fx.Event("PLAYER_LOGIN") advance(5)
        assert(fx.State() == "ready", "test setup: " .. fx.State())
        local tip = fx.game
        local function Own(id, hours, kind, qty)
            p.items[id], p.seen[id] = 295, clock - hours * 3600
            p.meta[id] = kind and (kind == "market" and 1 or 3) + (qty == nil and 1 or 0) or nil
            if qty ~= nil then p.qty[id] = qty end
        end
        local function Atr(price, hasAge, days, breaks)
            local api = { GetAuctionPriceByItemID = function(_, id) return id == HERB and price or nil end }
            if hasAge then api.GetAuctionAgeByItemID = function() if breaks then error("broken") end return days end end
            Auctionator = { API = { v1 = api } }
        end
        -- the AH line and the line under it ("uses ..."), without colours; and the colour of the bracket
        local function Tip(id)
            local lines = fx.Hover(tip, id)
            local ah, uses, orange
            for i, l in ipairs(lines) do
                if l:find("  " .. L["AH price"] .. " = ", 1, true) or l:find(L["|cffffd060Gathercraft|r AH"], 1, true) then
                    ah, orange = TT.Plain(l), l:find("|cffff8040(", 1, true) ~= nil
                    if lines[i + 1] and lines[i + 1]:find("^%s%s%s%s") then uses = TT.Plain(lines[i + 1]):gsub("^%s+", "") end
                end
            end
            -- every look: the tooltip names the price GetPrice gives
            local _, source = ns.GetPrice(id)
            Check(ns.PriceInfo(id).source == source, "PriceInfo and GetPrice differ for " .. id)
            return ah or "", uses, orange, lines
        end
        local function Has(text, part) return text:find(part, 1, true) ~= nil end
        local UNKNOWN = L["unknown – scan at the auction house"]
        local AGELESS = L["age unknown"]

        -- ---- nothing known at all
        GetItemInfo = function() return "Item" end
        local ah, uses = Tip(HERB)
        Check(Has(ah, UNKNOWN) and uses == nil, "nothing known: " .. ah .. " / " .. tostring(uses))
        -- ---- no own price, another source: named; a number only where no line of the other addon shows one (S3)
        GetItemInfo = saved.info
        ah, uses = Tip(HERB)
        Check(Has(ah, UNKNOWN) and uses == TT.Plain(L["uses vendor price: %s"]:format(ns.Money(10))), "vendor only: " .. ah .. " / " .. tostring(uses))
        GetAuctionBuyout = function() return 333 end
        ah, uses = Tip(HERB)
        Check(Has(ah, UNKNOWN) and uses == TT.Plain(L["uses auction addon price: %s (age unknown)"]:format(ns.Money(333))), "auction addon: " .. tostring(uses))
        TSM_API = { GetCustomPriceValue = function() return 444 end }
        ah, uses = Tip(HERB)
        Check(uses == L["uses TSM DBMarket price (external, age unknown)"], "TSM: " .. tostring(uses))
        Check(not Has(ah .. uses, TT.Plain(ns.Money(444))), "TSM: its price repeated")
        TSM_API = { GetCustomPriceValue = function() error("broken") end }
        ah, uses = Tip(HERB)
        Check(Has(uses or "", TT.Plain(ns.Money(333))), "TSM breaks: " .. tostring(uses))
        TSM_API = { GetCustomPriceValue = function() return 0 end }
        ah, uses = Tip(HERB)
        Check(Has(uses or "", TT.Plain(ns.Money(333))), "TSM says 0: " .. tostring(uses))
        TSM_API, GetAuctionBuyout = nil, nil
        Atr(187, true, 2)
        ah, uses = Tip(HERB)
        Check(Has(ah, UNKNOWN) and uses == L["uses Auctionator price (%s)"]:format(L["%d days"]:format(2)), "Auctionator only: " .. tostring(uses))
        Check(not Has(ah .. uses, TT.Plain(ns.Money(187))), "Auctionator: its price repeated")
        Auctionator = nil

        -- ---- our own price: the kind, the age, the quantity
        local orange
        Own(HERB, 3, "market", 240)
        ah, uses, orange = Tip(HERB)
        Check(Has(ah, TT.Plain(ns.Money(295))) and Has(ah, "(" .. L["own scan"] .. ", 3" .. L[" h ago"] .. ", " .. L["%s listed"]:format("240") .. ")") and not uses and not orange,
            "own scan: " .. ah .. " / " .. tostring(uses))
        Own(HERB, 3, "lowest", 240)
        ah = Tip(HERB)
        Check(Has(ah, "(" .. L["lowest offer"] .. ", ") and not Has(ah, L["own scan"]), "lowest offer: " .. ah)
        Own(HERB, 3, nil, 240)
        ah = Tip(HERB)
        Check(Has(ah, "(" .. L["own data"] .. ", ") and not Has(ah, L["own scan"]), "an entry from before: " .. ah)
        -- a quantity that is not this price's: not said at all (0.2 live test
        -- N4: "? listed" left out), never 0 and never the old number
        p.qty[HERB] = 240
        Own(HERB, 3, "market", nil)
        ah = Tip(HERB)
        Check(Has(ah, "(" .. L["own scan"] .. ", 3" .. L[" h ago"] .. ")") and not Has(ah, L["%s listed"]:format("?")) and not Has(ah, "240")
            and not Has(ah, L["%s listed"]:format("0")), "unknown quantity: " .. ah)
        Own(HERB, 3, "market", 0)
        ah = Tip(HERB)
        Check(Has(ah, L["%s listed"]:format("0")), "0 listed, told by the game: " .. ah)

        -- ---- the borders: 5 h 59 min, 6 h, 6 days 23 h, 7 days
        local TOO_OLD = L["too old, not used"]
        Own(HERB, 5 + 59 / 60, "market", 240)
        ah, uses, orange = Tip(HERB)
        Check(not orange and not uses and not Has(ah, TOO_OLD), "5 h 59 min: " .. ah)
        Own(HERB, 6, "market", 240)
        ah, uses, orange = Tip(HERB)
        Check(orange and not uses and not Has(ah, TOO_OLD), "6 h: " .. ah)
        Own(HERB, 6 * 24 + 23, "market", 240)
        ah, uses, orange = Tip(HERB)
        Check(orange and not uses and not Has(ah, TOO_OLD), "6 days 23 h: " .. ah .. " / " .. tostring(uses))
        Own(HERB, 7 * 24, "market", 240)
        ah, uses, orange = Tip(HERB)
        Check(orange and Has(ah, TOO_OLD) and Has(ah, TT.Plain(ns.Money(295))) and not Has(ah, L["%s listed"]:format("240"))
            and uses == TT.Plain(L["uses vendor price: %s"]:format(ns.Money(10))), "7 days: " .. ah .. " / " .. tostring(uses))
        -- ---- the same tooltip over the borders, no scan in between: only the clock moves
        local rev = ns.PriceRev()
        Own(HERB, 5 + 59 / 60, "market", 240)
        ah, uses, orange = Tip(HERB)
        Check(not orange, "before the 6 hours: orange")
        clock = clock + 120
        ah, uses, orange = Tip(HERB)
        Check(orange and not uses, "past the 6 hours without a scan: not marked old")
        Own(HERB, 6 * 24 + 23 + 59 / 60, "market", 240)
        ah, uses = Tip(HERB)
        Check(not Has(ah, TOO_OLD) and not uses, "before the 7 days: " .. ah)
        clock = clock + 120
        ah, uses = Tip(HERB)
        Check(Has(ah, TOO_OLD) and uses ~= nil, "past the 7 days without a scan: " .. ah .. " / " .. tostring(uses))
        Check(ns.PriceRev() == rev, "test setup: a price was stored in between")

        -- ---- Auctionator changes, we scan nothing: the next hover shows it
        Own(HERB, 21, "market", 240)
        ah, uses = Tip(HERB)
        Check(not uses, "old and alone: " .. tostring(uses))
        local function Uses(age) return L["uses Auctionator price (%s)"]:format(age) end
        Atr(187)
        ah, uses = Tip(HERB)
        Check(uses == Uses(AGELESS), "Auctionator without an age function: " .. tostring(uses))
        Atr(187, true, nil, true)
        ah, uses = Tip(HERB)
        Check(uses == Uses(AGELESS), "Auctionator's age function breaks: " .. tostring(uses))
        Atr(187, true, 0)
        ah, uses = Tip(HERB)
        Check(uses == Uses(L["today"]), "Auctionator, seen today: " .. tostring(uses))
        Own(HERB, 2 * 24, "market", 240)
        Atr(187, true, 1)
        ah, uses = Tip(HERB)
        Check(uses == Uses(L["1 day"]), "Auctionator, 1 day: " .. tostring(uses))
        Own(HERB, 4 * 24, "market", 240)
        Atr(187, true, 3)
        ah, uses = Tip(HERB)
        Check(uses == Uses(L["%d days"]:format(3)), "Auctionator, 3 days: " .. tostring(uses))
        Own(HERB, 8 * 24, "market", 240)
        Atr(187, true, "old")
        ah, uses = Tip(HERB)
        Check(uses == Uses(AGELESS) and Has(ah, TOO_OLD), "Auctionator, an age that is no number: " .. tostring(uses))
        Check(not Has(ah .. (uses or ""), TT.Plain(ns.Money(187))), "Auctionator's price repeated")
        -- our own is fresher than Auctionator's: ours is used, no line under it
        Own(HERB, 24, "market", 240)
        Atr(187, true, 3)
        ah, uses = Tip(HERB)
        Check(not uses, "our own is fresher: " .. tostring(uses))
        Auctionator = nil

        -- ---- every other item: one line, and only with a price of our own
        local lines
        ah, uses, orange, lines = Tip(GEAR)
        Check(#lines == 2, "gear without a price of ours: " .. (#lines - 2) .. " lines of ours (the vendor price alone is no reason)")
        Own(GEAR, 3, "lowest", nil)
        ah, uses, orange, lines = Tip(GEAR)
        Check(#lines == 3 and Has(ah, TT.Plain(L["|cffffd060Gathercraft|r AH"])) and Has(ah, "(" .. L["lowest offer"] .. ", 3" .. L[" h ago"] .. ")")
            and not Has(ah, L["%s listed"]:format("?")), "gear: " .. ah)
        Own(GEAR, 8 * 24, "market", 5)
        ah, uses, orange, lines = Tip(GEAR)
        Check(#lines == 4 and Has(ah, TOO_OLD) and uses == TT.Plain(L["uses vendor price: %s"]:format(ns.Money(10))), "gear, too old: " .. ah .. " / " .. tostring(uses))
        -- no block for it, also not with Shift
        IsShiftKeyDown = function() return true end
        ah, uses, orange, lines = Tip(GEAR)
        Check(#lines == 4 and not TT.Line(lines, L["14 days"]) and not TT.Line(lines, L["Most spawn points"]), "gear with Shift: " .. table.concat(lines, " / "))
        IsShiftKeyDown = function() return false end

        -- ---- "usually" for such an item: from the days inside the window only
        local day = math.floor(clock / 86400)
        local USUALLY = L["    usually"]
        local function Usually(history)
            Own(GOOD, 1, "market", 5)
            p.items[GOOD], p.history[GOOD] = 150, history
            fx.ns.languageListeners[1]() -- (the texts are made anew, as after a scan)
            local _, _, _, l = Tip(GOOD)
            return TT.Plain(TT.Line(l, USUALLY) or "")
        end
        local usually = Usually(("%d:100;%d:100;%d:100;%d:150"):format(day - 3, day - 2, day - 1, day))
        Check(Has(usually, "+50%") and Has(usually, TT.Plain(ns.Money(100))), "usually: " .. usually)
        usually = Usually(("%d:100;%d:100;%d:100;%d:150"):format(day - 30, day - 29, day - 28, day))
        Check(usually == "", "usually from days outside the window: " .. usually)
        usually = Usually(("%d:140;%d:150;%d:160;%d:150"):format(day - 3, day - 2, day - 1, day))
        Check(usually == "", "usually although the price is as usual: " .. usually)
        usually = Usually(("%d:300;%d:300;%d:300;%d:150"):format(day - 3, day - 2, day - 1, day))
        Check(Has(usually, "-50%"), "usually, cheaper than usual: " .. usually)
        -- a price too old to be used is not held against the usual one
        p.seen[GOOD] = clock - 8 * 86400
        fx.ns.languageListeners[1]()
        ah, uses, orange, lines = Tip(GOOD)
        Check(Has(ah, TOO_OLD) and not TT.Line(lines, USUALLY), "too old, yet compared with the usual price: " .. table.concat(lines, " / "))

        -- ---- the 14 days of the block
        local function Days(id)
            fx.ns.languageListeners[1]()
            local l = fx.Hover(tip, id)
            return TT.Plain(TT.Line(l, L["14 days"]) or ""), TT.Plain(TT.Line(l, L["Last 7 days"]) or ""), l
        end
        local function Stats(low, usual, high, days)
            return TT.Plain(L["low %s · usual %s · high %s"]:format(ns.Money(low), usual and ns.Money(usual) or "?", ns.Money(high)))
                .. "  (" .. (days == 1 and L["1 day with data"] or L["%d days with data"]:format(days)) .. ")"
        end
        IsShiftKeyDown = function() return true end
        Own(HERB, 1, "market", 240)
        p.history[HERB] = nil
        local d14, d7 = Days(HERB)
        Check(Has(d14, L["unknown (no price in the last 14 days)"]) and d7 == "", "no day: " .. d14 .. " / " .. d7)
        d14 = Days(ROCK)
        Check(Has(d14, L["unknown (only trade goods are tracked)"]), "no trade good: " .. d14)
        p.history[HERB] = day .. ":295"
        d14, d7 = Days(HERB)
        Check(Has(d14, Stats(295, nil, 295, 1)), "one day: " .. d14)
        Check(Has(d7, "– · – · – · – · – · – · " .. TT.Plain(ns.Money(295, true))), "one day, the last 7: " .. d7)
        p.history[HERB] = ("%d:200;%d:295"):format(day - 1, day)
        d14 = Days(HERB)
        Check(Has(d14, Stats(200, nil, 295, 2)), "two days: " .. d14)
        p.history[HERB] = ("%d:200;%d:100;%d:295"):format(day - 2, day - 1, day)
        d14 = Days(HERB)
        Check(Has(d14, Stats(100, nil, 295, 3)), "three days (two before today): " .. d14)
        p.history[HERB] = ("%d:300;%d:200;%d:100;%d:295"):format(day - 3, day - 2, day - 1, day)
        d14, d7 = Days(HERB)
        Check(Has(d14, Stats(100, 200, 300, 4)), "four days (three before today): " .. d14)
        Check(Has(d7, ("– · – · – · %s · %s · %s · %s"):format(TT.Plain(ns.Money(300, true)), TT.Plain(ns.Money(200, true)), TT.Plain(ns.Money(100, true)),
            TT.Plain(ns.Money(295, true)))), "four days, the last 7: " .. d7)
        -- gaps
        p.history[HERB] = ("%d:400;%d:300;%d:100;%d:295"):format(day - 12, day - 5, day - 2, day)
        d14, d7 = Days(HERB)
        Check(Has(d14, Stats(100, 300, 400, 4)), "gaps: " .. d14)
        Check(Has(d7, ("– · %s · – · – · %s · – · %s"):format(TT.Plain(ns.Money(300, true)), TT.Plain(ns.Money(100, true)), TT.Plain(ns.Money(295, true)))), "gaps, the last 7: " .. d7)
        -- all 14 days
        local all = {}
        for d = 13, 0, -1 do all[#all + 1] = (day - d) .. ":" .. (100 + d) end
        p.history[HERB] = table.concat(all, ";")
        d14 = Days(HERB)
        Check(Has(d14, Stats(100, 107, 113, 14)), "14 days: " .. d14)
        -- a history of 30 days ago, nothing since: nothing of it shows
        local old = {}
        for d = 34, 20, -1 do old[#old + 1] = (day - d) .. ":900" end
        p.history[HERB] = table.concat(old, ";")
        d14, d7 = Days(HERB)
        Check(Has(d14, L["unknown (no price in the last 14 days)"]) and d7 == "" and not Has(d14, "9"), "a history of long ago: " .. d14 .. " / " .. d7)
        p.history[HERB] = table.concat(old, ";") .. (";%d:200;%d:295"):format(day - 13, day)
        d14 = Days(HERB)
        Check(Has(d14, Stats(200, nil, 295, 2)), "long ago plus two days in the window: " .. d14)
        -- over midnight (UTC) with the game open and no scan: the window moves on by itself
        clock = (day + 1) * 86400 + 60
        local l = fx.Hover(tip, HERB)
        d14, d7 = TT.Plain(TT.Line(l, L["14 days"]) or ""), TT.Plain(TT.Line(l, L["Last 7 days"]) or "")
        Check(Has(d14, Stats(295, nil, 295, 1)), "the day after, no scan: " .. d14)
        Check(Has(d7, "– · – · – · – · – · " .. TT.Plain(ns.Money(295, true)) .. " · –"), "the day after, the last 7: " .. d7)
        -- where the history is from stands under the row
        Check(TT.Line(l, L["UTC days; own data, scans and lowest offers"]), "the last 7 days do not say where they are from")
        -- a price is stored (a search at the auction house): the same tooltip shows the new numbers at once
        local AHX = C_AuctionHouse
        local keepAH = { AHX.GetNumCommoditySearchResults, AHX.GetCommoditySearchResultInfo, AHX.HasFullCommoditySearchResults }
        AHX.GetNumCommoditySearchResults = function() return 1 end
        AHX.GetCommoditySearchResultInfo = function() return { unitPrice = 777, quantity = 12 } end
        AHX.HasFullCommoditySearchResults = function() return true end
        fire("COMMODITY_SEARCH_RESULTS_UPDATED", HERB)
        AHX.GetNumCommoditySearchResults, AHX.GetCommoditySearchResultInfo, AHX.HasFullCommoditySearchResults = keepAH[1], keepAH[2], keepAH[3]
        advance(3)
        l = fx.Hover(tip, HERB)
        d14 = TT.Plain(TT.Line(l, L["14 days"]) or "")
        Check(Has(d14, Stats(295, nil, 777, 2)), "after a search stored a price: " .. d14)
        Check(Has(TT.Plain(TT.Line(l, "  " .. L["AH price"] .. " = ") or ""), L["%s listed"]:format("12")), "after a search: the AH line")
    end)
    time, Auctionator, TSM_API, GetAuctionBuyout, GetItemInfo, IsShiftKeyDown = saved.time, saved.atr, saved.tsm, saved.buyout, saved.info, saved.shift
    C_Item.GetItemInfoInstant = saved.instant
    ns.db.tooltipPrices = saved.option
    for _, id in ipairs({ HERB, GEAR, GOOD, ROCK }) do Forget(id) end
    if not ok then error(err, 0) end
    assert(#fails == 0, #fails .. " wrong: " .. table.concat(fails, " | "))
end)
step("Item tooltip with Shift: the zone with the most known spawn points, and the professions that use the item (v0.2 B2 C4)", function()
    -- Concept item tooltip 4.4, 4.5, 5.9, 5.10; Sven's decisions 6, 7, S1, S2.
    local L = ns.L
    local data = GathercraftQuestieData
    local ZONE = 99998 -- a zone of this test
    local saved = { option = ns.db.tooltipPrices, shift = IsShiftKeyDown, map = player.map, recipeDB = ns.db.recipeDB, pending = ns.db.recipePending,
        nodes = ns.db.nodes[ZONE], language = ns.db.language, names = {} }
    for k, v in pairs(ns.db.itemNames or {}) do saved.names[k] = v end
    local before = #errors
    local ok, err = pcall(function()
        ns.db.tooltipPrices = true
        ns.db.recipeDB = {} -- the shipped recipes alone first
        IsShiftKeyDown = function() return true end
        ns.SpawnCountsStart("test")
        local fx = TT.Load("tdp", true)
        fx.Event("PLAYER_LOGIN") advance(10)
        assert(fx.State() == "ready" and ns.SpawnCountsState() == "ready", "test setup: " .. fx.State() .. ", " .. tostring(ns.SpawnCountsState()))
        local tip = fx.game
        local function Zone(id) return TT.Plain(TT.Line(fx.Hover(tip, id), L["Most spawn points"]) or "") end
        local function Used(id) return TT.Plain(TT.Line(fx.Hover(tip, id), L["Used in"]) or "") end
        local function Has(text, part) return text:find(part, 1, true) ~= nil end

        -- ---- the shipped data: 2262 recipes, 570 different reagents (counted by the index itself)
        local st = fx.ns.ItemTooltipState()
        assert(st.recipes == 2262 and st.reagents == 570, ("the index read %d recipes with %d reagents; the shipped data has 2262 and 570"):format(st.recipes, st.reagents))
        -- Peacebloom: ten alchemy recipes, one for cooking, one for first aid
        local d = ns.CraftData
        local want = ("%s 10 · %s 1 · %s 1  (%s)"):format(d.ProfLabel("Alchemy"), d.ProfLabel("Cooking"), d.ProfLabel("First Aid"), L["recipe data"])
        if d.ProfLabel("Cooking") > d.ProfLabel("First Aid") then -- (the same number: by name, in the client's language)
            want = ("%s 10 · %s 1 · %s 1  (%s)"):format(d.ProfLabel("Alchemy"), d.ProfLabel("First Aid"), d.ProfLabel("Cooking"), L["recipe data"])
        end
        assert(Has(Used(2447), want), "Peacebloom: " .. Used(2447) .. " - want " .. want)
        if LOCALE == "enUS" then assert(Has(Used(2447), "Alchemy 10 · Cooking 1 · First Aid 1  (recipe data)"), "Peacebloom in English: " .. Used(2447)) end
        -- ore is smelted: "Smelting", also in the English client (where the profession is called Mining)
        local ore = Used(2770)
        assert(Has(ore, L["Smelting"] .. " 1") and not Has(ore, "Mining"), "copper ore: " .. ore)
        -- an item no recipe needs has no such line - also no "not used"
        assert(Used(3340) == "" and Zone(3340) ~= "", "Incendicite: " .. Used(3340))

        -- ---- the zone line: places counted once, where they are from always named
        local incendicite = Zone(3340)
        assert(Has(incendicite, L["%s (%d known: Questie data)"]:format(ns.GetZoneName(1437), 29)), "Incendicite: " .. incendicite .. " - want 29 in " .. ns.GetZoneName(1437))
        -- a reagent nobody gathers from a node: no zone line (0.2 live test N4)
        local linen = Zone(2589)
        assert(linen == "", "linen cloth has a zone line: " .. linen)
        assert(Used(2589) ~= "", "linen cloth is in no recipe?")

        -- ---- your continent first: the zone with the most places there, else the most anywhere
        local here = ns.GetContinent(player.map)
        local function Best(itemID, continent)
            local list = ns.SpawnCounts(itemID)
            for _, z in ipairs(list) do if ns.GetContinent(z.mapID) == continent then return z end end
            return list[1]
        end
        -- an item whose best zone is on another continent than its best zone here
        local ITEM, there
        for itemID in pairs({ [765] = 1, [2447] = 1, [785] = 1, [2449] = 1, [2770] = 1, [2771] = 1, [2772] = 1, [3356] = 1, [3355] = 1, [2450] = 1 }) do
            local list = ns.SpawnCounts(itemID)
            if list and list[1] then
                local other = ns.GetContinent(list[1].mapID) == here and nil or ns.GetContinent(list[1].mapID)
                if not other then
                    for _, z in ipairs(list) do if ns.GetContinent(z.mapID) ~= here then other = ns.GetContinent(z.mapID) break end end
                end
                if other and Best(itemID, here).mapID ~= Best(itemID, other).mapID then ITEM, there = itemID, other break end
            end
        end
        assert(ITEM, "test setup: no item with zones on two continents")
        local function Text(z)
            if z.own > 0 and z.questie > 0 then return L["%s (%d known: Questie data, %d yours)"]:format(ns.GetZoneName(z.mapID), z.total, z.own) end
            if z.own > 0 then return L["%s (%d known: yours)"]:format(ns.GetZoneName(z.mapID), z.total) end
            return L["%s (%d known: Questie data)"]:format(ns.GetZoneName(z.mapID), z.total)
        end
        assert(Has(Zone(ITEM), Text(Best(ITEM, here))), "on your continent: " .. Zone(ITEM) .. " - want " .. Text(Best(ITEM, here)))
        -- you travel to the other continent: the line is chosen anew
        local elsewhere
        for mapID in pairs(data.zones) do if ns.GetContinent(mapID) == there then elsewhere = mapID break end end
        player.map = elsewhere
        fx.Event("ZONE_CHANGED_NEW_AREA")
        assert(Has(Zone(ITEM), Text(Best(ITEM, there))), "on the other continent: " .. Zone(ITEM) .. " - want " .. Text(Best(ITEM, there)))
        assert(Text(Best(ITEM, here)) ~= Text(Best(ITEM, there)), "test setup: the same zone on both")
        player.map = saved.map
        fx.Event("ZONE_CHANGED_NEW_AREA")
        assert(Has(Zone(ITEM), Text(Best(ITEM, here))), "back again: " .. Zone(ITEM))

        -- ---- your own points: named; until they are counted there is no line - never an old number
        local kindID
        for id, kind in pairs(data.kinds) do if kind[2] == 3340 and kind[1] == "o" then kindID = id break end end
        local mine = {}
        for i = 1, 40 do mine[i] = { id = kindID, name = "Incendicite Mineral Vein", type = "ore", x = 0.1 + i * 0.01, y = 0.5, count = 1, last = time() } end
        ns.db.nodes[ZONE] = mine
        ns.NotifyNodesChanged("add", ZONE, mine[1])
        assert(Zone(3340) == "", "an old number right after a node changed: " .. Zone(3340))
        assert(Zone(ITEM) ~= "", "another item lost its line through one node")
        advance(6)
        assert(Has(Zone(3340), L["%s (%d known: yours)"]:format(ns.GetZoneName(ZONE), 40)), "40 own points in a zone without spawn data: " .. Zone(3340))
        -- some of them from sync: not counted - the zone with 29 Questie places leads again
        for i = 1, 20 do mine[i].source = "sync" end
        ns.NotifyNodesChanged()
        assert(Zone(3340) == "" and Zone(ITEM) == "", "an old number after a change without a name")
        advance(12)
        assert(Has(Zone(3340), L["%s (%d known: Questie data)"]:format(ns.GetZoneName(1437), 29)), "20 own, 20 from sync: " .. Zone(3340))
        ns.db.nodes[ZONE] = nil
        ns.NotifyNodesChanged()
        advance(12)

        -- ---- a recipe learned: the index is built anew, meanwhile no line; then the new count
        local dust = Used(10940)
        local n0 = tonumber(dust:match(d.ProfLabel("Enchanting") .. " (%d+)"))
        assert(n0 and n0 > 0, "strange dust: " .. dust)
        ns.NoteItemName("Strange Dust", 10940)
        ns.NoteItemName("Tooltip Test Shard", 990020)
        local rev = ns.RecipeRev()
        ns.RememberRecipe("Enchanting", 20, "Enchant Chest - Tooltip Test", { { "Strange Dust", 2 }, { "Strange Dust", 1 }, { "Tooltip Test Shard", 1 } })
        assert(ns.RecipeRev() > rev, "test setup: the recipe was not learned (" .. tostring(ns.db.recipeDB.Enchanting and ns.db.recipeDB.Enchanting["Enchant Chest - Tooltip Test"]) .. ")")
        assert(Used(10940) == "", "an old number while the recipes are read again: " .. Used(10940))
        assert(fx.State() == "building", "the index is not built anew: " .. fx.State())
        advance(5)
        dust = Used(10940)
        assert(tonumber(dust:match(d.ProfLabel("Enchanting") .. " (%d+)")) == n0 + 1, "strange dust after the new recipe: " .. dust .. " (was " .. n0 .. ")")
        -- an item only your own recipe book knows gets the block too
        local shard = fx.Hover(tip, 990020)
        assert(TT.Line(shard, L["AH price"]) and Has(TT.Plain(TT.Line(shard, L["Used in"]) or ""), d.ProfLabel("Enchanting") .. " 1"), "an item only in your own recipe book: " .. table.concat(shard, " / "))
        assert(not TT.Line(shard, L["Most spawn points"]), "a zone line for an item nobody gathers: " .. table.concat(shard, " / "))
        assert(fx.ns.ItemTooltipState().recipes == 2263, "recipes after one more: " .. fx.ns.ItemTooltipState().recipes)

        -- ---- another language: the texts are made anew
        local english = fx.Hover(tip, 2447)
        local other = LOCALE == "deDE" and "frFR" or "deDE"
        ns.db.language = other
        ns.ApplyLanguage()
        fx.ns.languageListeners[1]()
        advance(12) -- (node names change with the language: the spawn counts are counted again)
        local translated = fx.Hover(tip, 2447)
        local label = ns.Locales[other]["Used in"]
        assert(TT.Line(translated, label) and TT.Line(translated, ns.Locales[other]["recipe data"]) and TT.Line(translated, ns.Locales[other]["14 days"]),
            "after the change to " .. other .. ": " .. table.concat(translated, " / "))
        assert(#translated == #english, "the change of language changed the number of lines")
        ns.db.language = saved.language
        ns.ApplyLanguage()
        fx.ns.languageListeners[1]()
        advance(12)
        assert(TT.Line(fx.Hover(tip, 2447), L["Used in"]), "back to the language before")
        assert(#errors == before, "an error: " .. tostring(errors[#errors]))
    end)
    IsShiftKeyDown, player.map = saved.shift, saved.map
    ns.db.tooltipPrices, ns.db.recipeDB, ns.db.recipePending, ns.db.nodes[ZONE], ns.db.language, ns.db.itemNames = saved.option, saved.recipeDB, saved.pending, saved.nodes, saved.language, saved.names
    ns.ApplyLanguage()
    ns.SpawnCountsStop("test")
    ns.NotifyNodesChanged()
    advance(12)
    if not ok then error(err, 0) end
end)
step("Item tooltip: cheap while hovering, nothing built while it is off, every text of a fixed shape fits - 'Used in' is measured (v0.2 B2 C4, R1-N2)", function()
    -- Concept item tooltip 4.6, 5.7, 5.8, 5.12, 6 ("many hovers", languages).
    ns.GetPrice(785)
    local p = ns.db.prices[next(ns.db.prices)]
    local L = ns.L
    local saved = { option = ns.db.tooltipPrices, shift = IsShiftKeyDown, gmatch = string.gmatch, sort = table.sort, atr = Auctionator, language = ns.db.language }
    local ids, was = {}, {}
    local before = #errors
    local ok, err = pcall(function()
        Auctionator = nil
        -- ---- off before the login: no index, no counts, no line - and the saved switch is all it takes
        ns.db.tooltipPrices = false
        local off = TT.Load("tdp", true)
        off.Event("PLAYER_LOGIN") advance(5)
        assert(off.State() == "off" and not off.spawnStarts, "built although the option is off: " .. off.State() .. ", counts started " .. tostring(off.spawnStarts))
        assert(#off.Hover(off.game, 2447, 2) == 2, "lines although the option is off")
        local st = off.ns.ItemTooltipState()
        assert(st.builds == 0 and st.recipes == 0, "off: " .. st.builds .. " builds, " .. st.recipes .. " recipes read")
        -- the options page switches it: the setter tells the module
        local src = assert(io.open(ROOT .. "/Options.lua")):read("*a")
        assert(src:find("ns.db.tooltipPrices = on", 1, true) and src:find("ns.ItemTooltipSetEnabled(on)", 1, true), "the option does not tell the tooltip module")

        -- ---- on: 50 items, hovered 1000 times
        ns.db.tooltipPrices = true
        local fx = TT.Load("tdp", true)
        fx.Event("PLAYER_LOGIN") advance(10)
        assert(fx.State() == "ready", "test setup: " .. fx.State())
        local day, now = math.floor(time() / 86400), time()
        local kinds = {}
        for _, kind in pairs(GathercraftQuestieData.kinds) do if (kind[1] == "h" or kind[1] == "o") and kind[2] > 0 then kinds[#kinds + 1] = kind[2] end end
        table.sort(kinds)
        for i = 1, 50 do
            local id = i <= 30 and kinds[i] or (990100 + i) -- 30 gathered items, 20 others
            assert(id, "test setup: fewer than 30 gathered items")
            ids[i] = id
            was[id] = { p.items[id], p.qty[id], p.seen[id], p.meta[id], p.history[id] }
            p.items[id], p.qty[id], p.seen[id], p.meta[id], p.history[id] = nil, nil, nil, nil, nil
            if i % 5 ~= 0 then
                p.items[id], p.seen[id], p.meta[id], p.qty[id] = 100 + i, now - i * 600, 1, i
                p.history[id] = ("%d:%d;%d:%d;%d:%d;%d:%d"):format(day - 3, 90 + i, day - 2, 95 + i, day - 1, 99 + i, day, 100 + i)
            end
        end
        local tip = fx.game
        IsShiftKeyDown = function() return true end
        -- a few times around: the caches fill, the game's string table grows to
        -- its size (measured 13.11.2026: the first 1000 hovers leave 20-30 KB
        -- once, the next 4000 together 2-6 KB)
        for _ = 1, 21 do
            for _, id in ipairs(ids) do fx.Hover(tip, id) end
        end
        -- from now on a hover parses nothing and sorts nothing
        local parsed, sorted = 0, 0
        string.gmatch = function(...) parsed = parsed + 1 return saved.gmatch(...) end
        table.sort = function(...) sorted = sorted + 1 return saved.sort(...) end
        collectgarbage("collect") collectgarbage("collect")
        local kb0, t0 = collectgarbage("count"), os.clock()
        local lines = 0
        for round = 1, 20 do
            for _, id in ipairs(ids) do lines = lines + #fx.Hover(tip, id, 2) end
        end
        local ms = (os.clock() - t0) * 1000
        string.gmatch, table.sort = saved.gmatch, saved.sort
        collectgarbage("collect") collectgarbage("collect")
        local kb1 = collectgarbage("count")
        note(("item tooltip: 1000 hovers of 50 items with Shift, %d lines: %.0f ms (%.3f ms a hover), memory %+.1f KB"):format(lines, ms, ms / 1000, kb1 - kb0))
        assert(parsed == 0 and sorted == 0, ("a warm hover parsed %d times and sorted %d times"):format(parsed, sorted))
        assert(kb1 - kb0 < 32, ("1000 hovers left %.1f KB behind"):format(kb1 - kb0))
        assert(ms < 2000, ("1000 hovers took %.0f ms"):format(ms))
        assert(lines > 1000 * 4, "test setup: the hovers showed little (" .. lines .. " lines)")
        local hook = fx.ns.ItemTooltipState()
        assert(hook.tooltips == 2050 and hook.calls == 3050, "the counters of /gcr tooltiptest: " .. hook.tooltips .. " builds, " .. hook.calls .. " calls (want 2050, 3050)")
        assert(#errors == before, "an error: " .. tostring(errors[#errors]))

        -- ---- every text, in every language: a key, a translation, the same placeholders, and it fits
        -- (a tooltip line has no fixed width; what we keep to is 80 characters
        -- for label and value together, with the longest values there are:
        -- from 100 gold on a price is shown without silver)
        local money = "99g 99s"
        local zone = "Stranglethorn Vale" -- 18 characters: a long zone name
        local function Width(text) -- characters as the player sees them; East Asian ones are twice as wide
            local n = 0
            for ch in saved.gmatch(text, "[%z\1-\127\194-\244][\128-\191]*") do n = n + ((#ch >= 3) and 2 or 1) end
            return n
        end
        local KEYS = { "Gathercraft info in item tooltips", "Prices, the last 14 days, spawn points and recipes. Hold Shift for more.", "AH price", "14 days", "Last 7 days",
            "Most spawn points", "Used in", "own scan", "lowest offer", "own data", "%s listed", "too old, not used", "unknown – scan at the auction house",
            "uses Auctionator price (%s)", "age unknown", "today", "1 day", "%d days", "uses TSM DBMarket price (external, age unknown)",
            "uses auction addon price: %s (age unknown)", "uses vendor price: %s", "low %s · usual %s · high %s", "1 day with data", "%d days with data",
            "unknown (only trade goods are tracked)", "unknown (no price in the last 14 days)", "UTC days; own data, scans and lowest offers",
            "%s (%d known: Questie data, %d yours)", "%s (%d known: yours)", "%s (%d known: Questie data)", "recipe data" }
        local code = assert(io.open(ROOT .. "/ItemTooltip.lua")):read("*a") .. assert(io.open(ROOT .. "/Options.lua")):read("*a")
        local function Placeholders(s) local t = {} for ph in saved.gmatch(s, "%%[%-+ 0#]*%d*%.?%d*[a-zA-Z]") do t[#t + 1] = ph end return table.concat(t, " ") end
        local tooWide = {}
        for _, lang in ipairs({ "enUS", "deDE", "esES", "frFR", "itIT", "koKR", "ptBR", "ruRU", "zhCN", "zhTW" }) do
            local T = {}
            for _, key in ipairs(KEYS) do
                assert(code:find(key, 1, true), "the text is not in the code: " .. key)
                local tr = lang == "enUS" and key or ns.Locales[lang][key]
                assert(type(tr) == "string" and tr ~= "" and (lang == "enUS" or tr ~= key), ("no %s translation of %q"):format(lang, key))
                assert(Placeholders(tr) == Placeholders(key), ("%s: other placeholders in %q: %s"):format(lang, key, tr))
                T[key] = tr
            end
            local days = T["%d days"]:format(13)
            local rows = {
                T["AH price"] .. "  " .. money .. "  (" .. T["lowest offer"] .. ", 23" .. (lang == "enUS" and " h ago" or ns.Locales[lang][" h ago"]) .. ", " .. T["%s listed"]:format("99999") .. ")",
                T["AH price"] .. "  " .. money .. "  (" .. T["lowest offer"] .. ", 13" .. (lang == "enUS" and " days ago" or ns.Locales[lang][" days ago"]) .. " – " .. T["too old, not used"] .. ")",
                T["AH price"] .. "  " .. T["unknown – scan at the auction house"],
                "      " .. T["uses Auctionator price (%s)"]:format(T["age unknown"]),
                "      " .. T["uses Auctionator price (%s)"]:format(days),
                "      " .. T["uses TSM DBMarket price (external, age unknown)"],
                "      " .. T["uses auction addon price: %s (age unknown)"]:format(money),
                "      " .. T["uses vendor price: %s"]:format(money),
                T["14 days"] .. "  " .. T["low %s · usual %s · high %s"]:format(money, money, money) .. "  (" .. T["%d days with data"]:format(14) .. ")",
                T["14 days"] .. "  " .. T["unknown (only trade goods are tracked)"],
                T["14 days"] .. "  " .. T["unknown (no price in the last 14 days)"],
                T["Last 7 days"] .. "  " .. ("999g · 999g · 999g · 999g · 999g · 999g · 999g"),
                "      " .. T["UTC days; own data, scans and lowest offers"],
                T["Most spawn points"] .. "  " .. T["%s (%d known: Questie data, %d yours)"]:format(zone, 999, 99),
            }
            for i, row in ipairs(rows) do
                if Width(row) > 80 then tooWide[#tooWide + 1] = ("%s row %d: %d: %s"):format(lang, i, Width(row), row) end
            end
        end
        assert(#tooWide == 0, #tooWide .. " lines wider than 80 characters: " .. table.concat(tooWide, " | "))
        -- ---- what that check covers, and what it does not (Codex review of block 2, N2)
        -- The rows above are the lines with a fixed shape. Every labelled line
        -- of the block must be among them - or be named here as a line without
        -- a bound, and then it is measured with the real recipe data instead
        -- of promised: "Used in" lists every profession with a recipe for the
        -- item, and for a few reagents that is far more than 80 characters.
        -- Whether the client then only draws a wider tooltip is a live point.
        local CHECKED = { ["AH price"] = true, ["14 days"] = true, ["Last 7 days"] = true, ["Most spawn points"] = true }
        local UNBOUNDED = { ["Used in"] = true }
        local tipCode = assert(io.open(ROOT .. "/ItemTooltip.lua")):read("*a")
        local labels = 0
        for key in saved.gmatch(tipCode, 'Label%(L%["(.-)"%]%)') do
            labels = labels + 1
            assert(CHECKED[key] or UNBOUNDED[key], ("the line %q of the tooltip block is not in the width check and not named as a line without a bound"):format(key))
            assert(not (CHECKED[key] and UNBOUNDED[key]), "checked and without a bound at once: " .. key)
        end
        assert(labels == 5, "test setup: " .. labels .. " labelled lines found in ItemTooltip.lua, want 5")
        for key in pairs(UNBOUNDED) do
            -- the widest line there is with the recipe data of this build, and Codex's two items
            for _, lang in ipairs({ "enUS", "deDE" }) do
                ns.db.language = lang
                ns.ApplyLanguage()
                fx.ns.languageListeners[1]()
                local label = lang == "enUS" and key or ns.Locales[lang][key]
                local function Used(id)
                    local line = TT.Line(fx.Hover(tip, id), label .. " = ")
                    if not line then return end
                    local plain = TT.Plain(line)
                    local at = plain:find(" = ", 1, true)
                    -- (label, two spaces, value - as the rows above and as Codex counted; the profession names are the game client's, so the client's language counts too)
                    return Width(label .. "  " .. plain:sub(at + 3)), plain:sub(at + 3)
                end
                local widest, widestID, over, with = 0, nil, 0, 0
                for id = 1, 25000 do
                    local w = Used(id)
                    if w then
                        with = with + 1
                        if w > 80 then over = over + 1 end
                        if w > widest then widest, widestID = w, id end
                    end
                end
                assert(with > 300, "test setup: only " .. with .. " items with a \"Used in\" line")
                local w1, w2 = Used(7080), Used(8170)
                assert(w1 and w2, "test setup: no \"Used in\" line for 7080 or 8170")
                note(("MEASURE N2 client %s, language %s \"%s\": %d items have the line, %d of them wider than 80 characters; widest %d (item %d); item 7080: %d, item 8170: %d"):format(
                    GetLocale(), lang, key, with, over, widest, widestID, w1, w2))
            end
        end
        -- nothing English built in: every word of a line comes from a key above (the money and the numbers aside)
        ns.db.language = "deDE"
        ns.ApplyLanguage()
        fx.ns.languageListeners[1]()
        for _, id in ipairs({ ids[1], ids[5], ids[31], ids[35] }) do
            for _, line in ipairs(fx.Hover(tip, id)) do
                local plain = TT.Plain(line)
                for _, word in ipairs({ "listed", "ago", "known", "yours", "unknown", "uses ", "usual", "days", "recipe" }) do
                    assert(not plain:find(word, 1, true), "English in a German tooltip: " .. plain)
                end
            end
        end
    end)
    string.gmatch, table.sort = saved.gmatch, saved.sort
    IsShiftKeyDown, Auctionator = saved.shift, saved.atr
    ns.db.tooltipPrices, ns.db.language = saved.option, saved.language
    ns.ApplyLanguage()
    for _, id in ipairs(ids) do
        local w = was[id] or {}
        p.items[id], p.qty[id], p.seen[id], p.meta[id], p.history[id] = w[1], w[2], w[3], w[4], w[5]
    end
    if not ok then error(err, 0) end
end)
step("/gcr tooltiptest: what the client offers for item tooltips and how our lines are doing - it only prints (v0.2 B2 C5)", function()
    -- Concept item tooltip 7: what cannot be known outside the game is
    -- asked there, with one command whose output Sven copies.
    local saved = { option = ns.db.tooltipPrices, atr = Auctionator, tsm = TSM_API, instant = C_Item.GetItemInfoInstant, size = C_Map.GetMapWorldSize,
        secret = issecretvalue, game = GameTooltip, ref = ItemRefTooltip, tip = C_TooltipInfo }
    local before = #errors
    local function Output(fn)
        local mark = #log
        fn()
        local out = {}
        for i = mark + 1, #log do out[#out + 1] = log[i] end
        return table.concat(out, "\n"), #out
    end
    local function Has(text, part) return text:find(part, 1, true) ~= nil end
    local ok, err = pcall(function()
        ns.db.tooltipPrices = true
        Auctionator, TSM_API = nil, nil
        -- ---- the command of the game's copy: there, prints, changes nothing
        local s0 = ns.ItemTooltipState()
        local calls, state = s0.calls, s0.state
        local text, n = Output(function() slash("tooltiptest") end)
        assert(n >= 14, "/gcr tooltiptest printed " .. n .. " lines")
        assert(Has(text, "Item tooltip check") and Has(text, "Hook in use: OnTooltipSetItem"), "no heading or no hook named: " .. text)
        assert(Has(text, "Auctionator.GetAuctionAgeByItemID: not there"), "without Auctionator: " .. text)
        local s1 = ns.ItemTooltipState()
        assert(s1.calls == calls and s1.state == state and #errors == before, "the command changed something")

        -- ---- a copy with the client's tooltip data, a few hovers, then the command
        local fx = TT.Load("tdp", true)
        fx.Event("PLAYER_LOGIN") advance(10)
        fx.Hover(fx.game, 2447, 2) fx.Hover(fx.game, 2770, 3) fx.Hover(fx.ref, 2447, 1)
        Auctionator = { API = { v1 = { GetAuctionPriceByItemID = function() return 5 end, GetAuctionAgeByItemID = function(_, id) return id == 2447 and 3 or nil end } } }
        TSM_API = { GetCustomPriceValue = function() return 7 end }
        GameTooltip, ItemRefTooltip = fx.game, nil
        text = Output(fx.ns.TooltipTest)
        GameTooltip, ItemRefTooltip = saved.game, saved.ref
        for _, want in ipairs({
            "Option \"Gathercraft info in item tooltips\": on",
            "Hook in use: TooltipDataProcessor",
            "GameTooltip: OnTooltipSetItem yes, OnTooltipCleared yes",
            "ItemRefTooltip: OnTooltipSetItem no such tooltip",
            "Auctionator.GetAuctionAgeByItemID(Peacebloom): number 3",
            "Item class of Peacebloom (2447): 7 / 9",
            "Item class of Copper Ore (2770): 7 / 9",
            "C_Map.GetMapWorldSize(" .. player.map .. "): 5000 x 3333",
            "Index of gathered items and recipes: ready, built 1 times",
            "Spawn point counts: ready",
            "Hook calls: 6 for 3 tooltip builds",
            "Calls per build, the last 3: 2 3 1",
            "(3 builds, ",
        }) do
            assert(Has(text, want), "not in the output: " .. want .. "\n" .. text)
        end
        assert(text:find("%d+ recipes, %d+ different reagents") and text:find("Cost of our lines: %d+%.%d%d%d ms a build on average"), "numbers missing: " .. text)
        -- it printed only: no call counted, nothing built
        local s2 = fx.ns.ItemTooltipState()
        assert(s2.calls == 6 and s2.tooltips == 3 and s2.builds == 1, "the command counted itself or built something")

        -- ---- a client that has little of all that: no error, said plainly
        Auctionator = { API = { v1 = { GetAuctionAgeByItemID = function() error("no such item") end } } }
        C_Item.GetItemInfoInstant, C_Map.GetMapWorldSize = nil, nil
        GameTooltip, ItemRefTooltip = {}, nil
        fx.ns.ItemTooltipSetEnabled(false)
        text = Output(fx.ns.TooltipTest)
        GameTooltip, ItemRefTooltip = saved.game, saved.ref
        for _, want in ipairs({ "\": off", "GameTooltip: OnTooltipSetItem no such tooltip", "GetAuctionAgeByItemID(Peacebloom): error:", "no C_Item.GetItemInfoInstant",
            "C_Map.GetMapWorldSize: no zone or no function", "Index of gathered items and recipes: off" }) do
            assert(Has(text, want), "a poor client, not in the output: " .. want .. "\n" .. text)
        end
        assert(fx.State() == "off" and #errors == before, "the command built something while the option is off, or an error: " .. tostring(errors[#errors]))
        -- the command is English in every language: it is copied and sent to us
        local src = assert(io.open(ROOT .. "/ItemTooltip.lua")):read("*a")
        local body = src:sub(src:find("ns.TooltipTest = function()", 1, true))
        assert(not body:find('L%["'), "/gcr tooltiptest uses translated texts")
    end)
    Auctionator, TSM_API, C_Item.GetItemInfoInstant, C_Map.GetMapWorldSize, issecretvalue = saved.atr, saved.tsm, saved.instant, saved.size, saved.secret
    GameTooltip, ItemRefTooltip, C_TooltipInfo = saved.game, saved.ref, saved.tip
    ns.db.tooltipPrices = saved.option
    if not ok then error(err, 0) end
end)
step("Waypoints: a client without one of the waypoint functions gets no Lua error, and is told once (v0.2 B2 Z1)", function()
    -- Static check of 12.11.2026, question 1: six calls for the game's
    -- waypoint were made without asking whether the client has them.
    local L = ns.L
    local saved = { can = C_Map.CanSetUserWaypointOnMap, set = C_Map.SetUserWaypoint, clear = C_Map.ClearUserWaypoint, point = UiMapPoint, track = C_SuperTrack,
        wp = USER_WP, sets = WP_SETS, clears = WP_CLEARS, arrow = ns.db.arrowHidden }
    local MISSING = L["Waypoints are not available in this client."]
    local function Restore()
        C_Map.CanSetUserWaypointOnMap, C_Map.SetUserWaypoint, C_Map.ClearUserWaypoint, UiMapPoint, C_SuperTrack = saved.can, saved.set, saved.clear, saved.point, saved.track
    end
    local function Told(mark, text)
        local n = 0
        for i = mark + 1, #log do if log[i]:find(text, 1, true) then n = n + 1 end end
        return n
    end
    local before = #errors
    local ok, err = pcall(function()
        assert(type(ns.ClearWaypoint) == "function", "no ns.ClearWaypoint")
        assert(UiMapPoint and UiMapPoint.CreateFromCoordinates and C_SuperTrack and C_SuperTrack.SetSuperTrackedUserWaypoint, "test setup: the harness has no waypoint functions")
        -- ---- everything there: as before
        USER_WP, WP_SETS, WP_CLEARS = nil, 0, 0
        local mark = #log
        assert(ns.SetWaypoint(1412, 0.5, 0.5) == true and WP_SETS == 1 and USER_WP, "with all functions: no waypoint set")
        assert(ns.ClearWaypoint() == true and WP_CLEARS == 1 and USER_WP == nil, "with all functions: not cleared")
        slash("clear")
        assert(WP_CLEARS == 2 and Told(mark, L["Waypoint cleared."]) == 1, "/gcr clear with all functions")
        assert(Told(mark, MISSING) == 0, "told that there are no waypoints although there are")

        -- ---- one function missing at a time: no Lua error, no waypoint, "set" is not claimed -
        -- and in the whole session the player is told once
        local cases = {
            { "C_Map.CanSetUserWaypointOnMap", function() C_Map.CanSetUserWaypointOnMap = nil end },
            { "C_Map.SetUserWaypoint", function() C_Map.SetUserWaypoint = nil end },
            { "UiMapPoint", function() UiMapPoint = nil end },
            { "UiMapPoint.CreateFromCoordinates", function() UiMapPoint = {} end },
            { "C_SuperTrack", function() C_SuperTrack = nil end },
            { "C_SuperTrack.SetSuperTrackedUserWaypoint", function() C_SuperTrack = {} end },
        }
        mark = #log
        for i, case in ipairs(cases) do
            case[2]()
            USER_WP, WP_SETS, WP_CLEARS = nil, 0, 0
            local okSet, set1 = pcall(ns.SetWaypoint, 1412, 0.5, 0.5)
            local okSet2, set2 = pcall(ns.SetWaypoint, 1412, 0.6, 0.6)
            Restore()
            assert(okSet and okSet2, "without " .. case[1] .. ": a Lua error: " .. tostring(set1) .. " " .. tostring(set2))
            assert(set1 == false and set2 == false and WP_SETS == 0 and USER_WP == nil, "without " .. case[1] .. ": a waypoint was set, or success claimed")
            assert(Told(mark, MISSING) == 1, "without " .. case[1] .. " (case " .. i .. "): told " .. Told(mark, MISSING) .. " times this session, want once")
        end
        -- ---- no ClearUserWaypoint: /gcr clear and the end of a run make no error, and "cleared" is not claimed
        C_Map.ClearUserWaypoint = nil
        local mark2 = #log
        local okClear, cleared = pcall(ns.ClearWaypoint)
        local okSlash, whySlash = pcall(slash, "clear")
        -- a farm run with the game's waypoint (our arrow off) that ends: Route.lua clears the same way
        ns.db.arrowHidden = true
        local okRun, whyRun = pcall(function() slash("run herb") advance(2) slash("stop") advance(1) end)
        ns.db.arrowHidden = saved.arrow
        Restore()
        assert(okClear and cleared == false, "without ClearUserWaypoint: " .. tostring(cleared))
        assert(okSlash and okRun, "without ClearUserWaypoint: " .. tostring(whySlash) .. " / " .. tostring(whyRun))
        assert(Told(mark2, L["Waypoint cleared."]) == 0, "without ClearUserWaypoint: \"cleared\" claimed")
        assert(Told(mark, MISSING) == 1, "told " .. Told(mark, MISSING) .. " times in one session, want once")
        -- the route's own clearing goes the same way (Route.lua)
        local src = assert(io.open(ROOT .. "/Route.lua")):read("*a")
        assert(not src:find("C_Map.ClearUserWaypoint()", 1, true) and src:find("ns.ClearWaypoint()", 1, true), "Route.lua still calls C_Map.ClearUserWaypoint itself")
        src = assert(io.open(ROOT .. "/Core.lua")):read("*a")
        local _, direct = src:gsub("C_Map%.ClearUserWaypoint%(%)", "")
        assert(direct == 1, "Core.lua calls C_Map.ClearUserWaypoint in " .. direct .. " places, want the one guarded place")
        -- the text in every language
        for _, code in ipairs({ "deDE", "esES", "frFR", "itIT", "koKR", "ptBR", "ruRU", "zhCN", "zhTW" }) do
            local tr = ns.Locales[code]["Waypoints are not available in this client."]
            assert(type(tr) == "string" and tr ~= "" and tr ~= "Waypoints are not available in this client.", "no " .. code .. " translation")
        end
        assert(#errors == before, "an error: " .. tostring(errors[#errors]))
    end)
    Restore()
    USER_WP, WP_SETS, WP_CLEARS = saved.wp, saved.sets, saved.clears
    if not ok then error(err, 0) end
end)
step("Item tooltip in combat: the lines stay as they are, nothing is worked out or built until the fight is over (v0.2 B2 C7)", function()
    -- Concept item tooltip 6, "Secret/Kampf": under InCombatLockdown the
    -- lines stay the same; with an empty cache nothing is built.
    ns.GetPrice(785)
    local p = ns.db.prices[next(ns.db.prices)]
    local L = ns.L
    local HERB = 2447
    local saved = { option = ns.db.tooltipPrices, shift = IsShiftKeyDown, combat = InCombatLockdown, gmatch = string.gmatch, sort = table.sort,
        price = { p.items[HERB], p.qty[HERB], p.seen[HERB], p.meta[HERB], p.history[HERB] }, zones = ns.db.disabledZones }
    local before = #errors
    local ok, err = pcall(function()
        ns.db.tooltipPrices = true
        IsShiftKeyDown = function() return true end
        local day = math.floor(time() / 86400)
        p.items[HERB], p.seen[HERB], p.meta[HERB], p.qty[HERB] = 295, time() - 3600, 1, 240
        p.history[HERB] = ("%d:300;%d:200;%d:100;%d:295"):format(day - 3, day - 2, day - 1, day)
        ns.SpawnCountsStart("test")
        local fx = TT.Load("tdp", true)
        fx.Event("PLAYER_LOGIN") advance(10)
        assert(fx.State() == "ready" and ns.SpawnCountsState() == "ready", "test setup: " .. fx.State())
        local tip = fx.game
        local function Text() return table.concat(fx.Hover(tip, HERB), "\n") end
        local calm = Text()
        for _, label in ipairs({ "AH price", "14 days", "Last 7 days", "Most spawn points", "Used in" }) do
            assert(calm:find(L[label], 1, true), "test setup: no line \"" .. label .. "\" out of combat")
        end

        -- ---- in combat with everything worked out before: the same lines
        InCombatLockdown = function() return true end
        assert(Text() == calm, "the lines changed in combat:\n" .. Text() .. "\n--- out of combat:\n" .. calm)

        -- ---- in combat with nothing worked out: the price (it is asked for anew anyway), nothing else - and no parsing, no sorting
        fx.ns.languageListeners[1]() -- (every text has to be made anew)
        local parsed, sorted = 0, 0
        string.gmatch = function(...) parsed = parsed + 1 return saved.gmatch(...) end
        table.sort = function(...) sorted = sorted + 1 return saved.sort(...) end
        local fight = Text()
        string.gmatch, table.sort = saved.gmatch, saved.sort
        assert(parsed == 0 and sorted == 0, ("in combat with empty caches: parsed %d times, sorted %d times"):format(parsed, sorted))
        assert(fight:find(L["AH price"], 1, true) and fight:find(L["own scan"], 1, true), "in combat: the price line is gone:\n" .. fight)
        for _, label in ipairs({ "14 days", "Last 7 days", "Most spawn points", "Used in" }) do
            assert(not fight:find("  " .. L[label] .. " = ", 1, true), "in combat with empty caches: the line \"" .. label .. "\" was worked out:\n" .. fight)
        end
        -- the fight is over: everything again
        InCombatLockdown = function() return false end
        assert(Text() == calm, "after the fight:\n" .. Text())

        -- ---- the indexes are not built in combat: they wait, and go on after it
        InCombatLockdown = function() return true end
        fx.ns.ItemTooltipSetEnabled(false)
        fx.ns.ItemTooltipSetEnabled(true)
        advance(20)
        local st = fx.ns.ItemTooltipState()
        assert(st.state == "building" and st.builds == 1, "the recipe index was built in combat: " .. st.state .. ", " .. st.builds .. " builds")
        ns.SpawnCountsStop("test")
        if ns.ItemTooltipSetEnabled then ns.ItemTooltipSetEnabled(false) end -- (the game's own copy uses the counts too)
        ns.db.tooltipPrices = true -- (the switch itself stays on for the copy of this step)
        assert(ns.SpawnCountsState() == "off", "test setup: the spawn counts are still in use")
        ns.SpawnCountsStart("test")
        advance(20)
        assert(ns.SpawnCountsState() == "building" and ns.SpawnCounts(HERB) == nil, "the spawn points were counted in combat: " .. tostring(ns.SpawnCountsState()))
        InCombatLockdown = function() return false end
        advance(15)
        assert(fx.State() == "ready" and fx.ns.ItemTooltipState().builds == 2, "after the fight the recipe index is not built: " .. fx.State())
        assert(ns.SpawnCountsState() == "ready" and ns.SpawnCounts(HERB), "after the fight the spawn points are not counted")
        -- a recount after a node change waits too
        InCombatLockdown = function() return true end
        ns.NotifyNodesChanged()
        advance(20)
        assert(ns.SpawnCounts(HERB) == nil, "a recount ran in combat")
        InCombatLockdown = function() return false end
        advance(15)
        assert(ns.SpawnCounts(HERB), "after the fight the recount did not finish")
        assert(Text() == calm, "after all that:\n" .. Text())

        -- ---- zones you switched off for farming do not change the line: it shows what is known, not where you farm
        local zoneLine = TT.Line(fx.Hover(tip, HERB), L["Most spawn points"])
        local best = ns.SpawnCounts(HERB)[1].mapID
        ns.db.disabledZones = setmetatable({ [best] = true }, { __index = function() return true end })
        ns.NotifyNodesChanged()
        advance(15)
        assert(TT.Line(fx.Hover(tip, HERB), L["Most spawn points"]) == zoneLine, "switched-off zones changed the zone line")
        assert(#errors == before, "an error: " .. tostring(errors[#errors]))
    end)
    string.gmatch, table.sort = saved.gmatch, saved.sort
    IsShiftKeyDown, InCombatLockdown = saved.shift, saved.combat
    ns.db.disabledZones = saved.zones
    ns.db.tooltipPrices = saved.option
    p.items[HERB], p.qty[HERB], p.seen[HERB], p.meta[HERB], p.history[HERB] = saved.price[1], saved.price[2], saved.price[3], saved.price[4], saved.price[5]
    ns.SpawnCountsStop("test")
    if ns.ItemTooltipSetEnabled then ns.ItemTooltipSetEnabled(saved.option ~= false) end
    ns.NotifyNodesChanged()
    advance(15)
    if not ok then error(err, 0) end
end)
step("Spawn points: two recounts that overlap after a fight - no number before the last of them is done (v0.2 B2 R1-N1)", function()
    -- Codex review of block 2, N1: a recount has counted its zone and waits
    -- in combat for its last step; a second node change starts a second
    -- recount, which waits too. After the fight the first one must not hand
    -- out numbers while the second has not counted its zone yet.
    local data = GathercraftQuestieData
    local ZA, ZB, ITEM = 99997, 99998, 3340
    local saved = { a = ns.db.nodes[ZA], b = ns.db.nodes[ZB], tooltip = ns.db.tooltipPrices, combat = InCombatLockdown, za = data.zones[ZA], zb = data.zones[ZB] }
    if ns.ItemTooltipSetEnabled then ns.ItemTooltipSetEnabled(false) end
    local A
    for id, kind in pairs(data.kinds) do
        if kind[2] == ITEM and kind[1] == "o" and (not A or id < A) then A = id end
    end
    assert(A, "test setup: no node kind for Incendicite")
    local function Own(x)
        return { id = A, name = "Incendicite Mineral Vein", type = "ore", x = x, y = 0.5, count = 1, last = time() }
    end
    local function Zones()
        local list = ns.SpawnCounts(ITEM)
        if not list then return nil end
        local a, b = 0, 0
        for _, z in ipairs(list) do
            if z.mapID == ZA then a = z.total elseif z.mapID == ZB then b = z.total end
        end
        return a, b
    end
    local fighting = false
    local ok, err = pcall(function()
        data.zones[ZA], data.zones[ZB], ns.db.nodes[ZA], ns.db.nodes[ZB] = nil, nil, nil, nil
        InCombatLockdown = function() return fighting end
        ns.SpawnCountsStart("test")
        advance(15)
        assert(ns.SpawnCountsState() == "ready", "test setup: not ready")
        local a, b = Zones()
        assert(a == 0 and b == 0, "test setup: the test zones are not empty")

        -- the first change: its recount starts 3 s later and counts the zone ...
        ns.db.nodes[ZA] = { Own(0.3) }
        ns.NotifyNodesChanged("add", ZA, ns.db.nodes[ZA][1])
        advance(3.02)
        -- ... then the fight begins: its last step waits
        fighting = true
        advance(0.08)
        assert(Zones() == nil, "numbers although the recount is not done")
        -- the second change, in another zone: its recount starts in the fight and waits
        ns.db.nodes[ZB] = { Own(0.4) }
        ns.NotifyNodesChanged("add", ZB, ns.db.nodes[ZB][1])
        advance(3.4)
        assert(Zones() == nil, "numbers in the fight, with two recounts waiting")
        -- the fight is over: whatever is handed out from now on has both zones
        fighting = false
        local shown = 0
        for _ = 1, 400 do
            advance(0.01)
            a, b = Zones()
            if a then
                shown = shown + 1
                assert(a == 1 and b == 1, ("after the fight a list with %d and %d places in the two zones, want 1 and 1 - the first recount gave the numbers free"):format(a, b))
            end
        end
        assert(shown > 0, "no numbers 4 s after the fight")

        -- three in a row, the fight ending between their steps: the same rule
        fighting = true
        for i, zone in ipairs({ ZA, ZB, ZA }) do
            table.insert(ns.db.nodes[zone], Own(0.5 + i * 0.05))
            ns.NotifyNodesChanged("add", zone, ns.db.nodes[zone][#ns.db.nodes[zone]])
            advance(3.31)
        end
        fighting = false
        shown = 0
        for _ = 1, 500 do
            advance(0.01)
            a, b = Zones()
            if a then
                shown = shown + 1
                assert(a == 3 and b == 2, ("three recounts: a list with %d and %d places, want 3 and 2"):format(a, b))
            end
        end
        assert(shown > 0, "no numbers 5 s after three recounts")
        -- and a single change afterwards still comes through (nothing stays locked)
        table.insert(ns.db.nodes[ZB], Own(0.9))
        ns.NotifyNodesChanged("add", ZB, ns.db.nodes[ZB][3])
        advance(5)
        a, b = Zones()
        assert(a == 3 and b == 3, "a change after the overlap: " .. tostring(a) .. " and " .. tostring(b) .. ", want 3 and 3")
        -- a stop in the middle of two recounts and a new start: ready again, with numbers
        fighting = true
        table.insert(ns.db.nodes[ZA], Own(0.95))
        ns.NotifyNodesChanged("add", ZA, ns.db.nodes[ZA][4])
        advance(3.1)
        ns.SpawnCountsStop("test")
        fighting = false
        ns.SpawnCountsStart("test")
        advance(15)
        a, b = Zones()
        assert(a == 4 and b == 3, "after stop and start: " .. tostring(a) .. " and " .. tostring(b) .. ", want 4 and 3")
    end)
    InCombatLockdown = saved.combat
    ns.SpawnCountsStop("test")
    ns.db.nodes[ZA], ns.db.nodes[ZB], data.zones[ZA], data.zones[ZB] = saved.a, saved.b, saved.za, saved.zb
    ns.NotifyNodesChanged()
    advance(5)
    if ns.ItemTooltipSetEnabled then ns.ItemTooltipSetEnabled(saved.tooltip ~= false) end
    if not ok then error(err, 0) end
end)
step("Item tooltip: the first hover of an item does a little work, the next ones none; switched on in a fight nothing is built before it ends (v0.2 B2 R1-N3)", function()
    -- Codex review of block 2, N3: "no gmatch while hovering" is true for a
    -- warm hover only. Said exactly: the FIRST hover of an item after a
    -- login, a price change or a new UTC day reads that item's own 14 days
    -- (at most two passes over one history string) and sorts two short
    -- lists (the days, the professions); no index is built and nothing
    -- large is sorted. Every later hover of it parses and sorts nothing.
    -- And: switching the option on in a fight must not walk the node kinds
    -- either - that small index waits like the rest.
    ns.GetPrice(785)
    local p = ns.db.prices[next(ns.db.prices)]
    local HERB = 765
    local saved = { option = ns.db.tooltipPrices, shift = IsShiftKeyDown, combat = InCombatLockdown, gmatch = string.gmatch, sort = table.sort, pairs = pairs, atr = Auctionator,
        price = { p.items[HERB], p.qty[HERB], p.seen[HERB], p.meta[HERB], p.history[HERB] } }
    local before = #errors
    local ok, err = pcall(function()
        Auctionator = nil
        ns.db.tooltipPrices = true
        IsShiftKeyDown = function() return true end
        local day, now = math.floor(time() / 86400), time()
        p.items[HERB], p.seen[HERB], p.meta[HERB], p.qty[HERB] = 120, now - 600, 1, 7
        p.history[HERB] = ("%d:%d;%d:%d;%d:%d;%d:%d"):format(day - 3, 90, day - 2, 95, day - 1, 99, day, 120)

        -- ---- cold and warm
        local fx = TT.Load("tdp", true)
        fx.Event("PLAYER_LOGIN") advance(10)
        assert(fx.State() == "ready", "test setup: " .. fx.State())
        local tip = fx.game
        local parsed, sorted, longest, longestText = 0, 0, 0, 0
        string.gmatch = function(s, ...)
            parsed = parsed + 1
            if #s > longestText then longestText = #s end
            return saved.gmatch(s, ...)
        end
        table.sort = function(t, ...)
            sorted = sorted + 1
            if #t > longest then longest = #t end
            return saved.sort(t, ...)
        end
        local gmatchCounted, sortCounted = string.gmatch, table.sort
        local function Count(fn)
            parsed, sorted, longest, longestText = 0, 0, 0, 0
            local lines = fn()
            return parsed, sorted, lines
        end
        local function Cold(what)
            local g, s, lines = Count(function() return fx.Hover(tip, HERB) end)
            assert(TT.Line(lines, "14") and #lines >= 5, what .. ": test setup, the block is not there (" .. #lines .. " lines)")
            assert(g >= 1, what .. ": test setup, this hover read no history - it was not a first hover")
            assert(g <= 2 and s <= 2, ("%s: the first hover parsed %d times and sorted %d times, want at most 2 and 2"):format(what, g, s))
            assert(longestText == #p.history[HERB], ("%s: the first hover parsed a text of %d bytes - not only the item's own history (%d bytes)"):format(what, longestText, #p.history[HERB]))
            assert(longest <= 14, what .. ": the first hover sorted a list of " .. longest .. " entries")
            note(("MEASURE N3 %s: first hover %d gmatch, %d sorts (longest list %d)"):format(what, g, s, longest))
            for i = 1, 3 do
                local g2, s2, lines2 = Count(function() return fx.Hover(tip, HERB) end)
                assert(g2 == 0 and s2 == 0, ("%s: hover %d of the same item parsed %d times and sorted %d times, want 0 and 0"):format(what, i + 1, g2, s2))
                assert(#lines2 == #lines, what .. ": the warm hover shows other lines")
            end
        end
        Cold("after the login")
        -- a new price: the caches are old, one hover works them out again
        local rev = ns.PriceRev()
        local ah = { n = C_AuctionHouse.GetNumCommoditySearchResults, full = C_AuctionHouse.HasFullCommoditySearchResults, info = C_AuctionHouse.GetCommoditySearchResultInfo }
        C_AuctionHouse.GetNumCommoditySearchResults = function() return 2 end
        C_AuctionHouse.HasFullCommoditySearchResults = function() return true end
        C_AuctionHouse.GetCommoditySearchResultInfo = function(_, i) return ({ { unitPrice = 131, quantity = 10 }, { unitPrice = 140, quantity = 30 } })[i] end
        string.gmatch, table.sort = saved.gmatch, saved.sort
        fire("COMMODITY_SEARCH_RESULTS_UPDATED", HERB)
        string.gmatch, table.sort = gmatchCounted, sortCounted
        C_AuctionHouse.GetNumCommoditySearchResults, C_AuctionHouse.HasFullCommoditySearchResults, C_AuctionHouse.GetCommoditySearchResultInfo = ah.n, ah.full, ah.info
        assert(ns.PriceRev() ~= rev, "test setup: the search result changed no price")
        Cold("after a price change")
        string.gmatch, table.sort = saved.gmatch, saved.sort

        -- ---- switched on in a fight: nothing is walked or built until it is over
        local kinds, walked = GathercraftQuestieData.kinds, 0
        pairs = function(t, ...)
            if t == kinds then walked = walked + 1 end
            return saved.pairs(t, ...)
        end
        ns.db.tooltipPrices = false
        local late = TT.Load("tdp", true)
        late.Event("PLAYER_LOGIN") advance(5)
        assert(late.State() == "off", "test setup: built although the option is off")
        local fighting = true
        InCombatLockdown = function() return fighting end
        walked = 0
        late.ns.ItemTooltipSetEnabled(true)
        advance(10)
        assert(walked == 0, "switched on in a fight: the node kinds were walked " .. walked .. " time(s) before the fight was over")
        assert(late.State() == "building", "switched on in a fight: state " .. late.State() .. ", want building")
        local st = late.ns.ItemTooltipState()
        assert(st.recipes == 0 and st.builds == 0, "switched on in a fight: " .. st.recipes .. " recipes read")
        -- (a hover in the fight: no error, and no block that would need the index)
        local n = #late.Hover(late.game, HERB)
        assert(#errors == before, "an error while hovering in the fight: " .. tostring(errors[#errors]))
        fighting = false
        advance(10)
        assert(late.State() == "ready" and walked == 1, "after the fight: state " .. late.State() .. ", node kinds walked " .. walked .. " time(s), want ready and 1")
        assert(#late.Hover(late.game, HERB) > n and TT.Line(late.game.lines, "14"), "after the fight the block is not there")
        -- outside a fight nothing changed: the block for a gathered item is there before the recipes are read
        ns.db.tooltipPrices = false
        local early = TT.Load("tdp", true)
        early.Event("PLAYER_LOGIN") advance(5)
        walked = 0
        early.ns.ItemTooltipSetEnabled(true)
        assert(walked == 1 and early.State() == "building", "switched on outside a fight: walked " .. walked .. ", state " .. early.State())
        assert(TT.Line(early.Hover(early.game, HERB), "14"), "outside a fight the block waits for the recipe index")
        assert(#errors == before, "an error: " .. tostring(errors[#errors]))
    end)
    string.gmatch, table.sort, pairs = saved.gmatch, saved.sort, saved.pairs
    IsShiftKeyDown, InCombatLockdown, Auctionator = saved.shift, saved.combat, saved.atr
    ns.db.tooltipPrices = saved.option
    p.items[HERB], p.qty[HERB], p.seen[HERB], p.meta[HERB], p.history[HERB] = saved.price[1], saved.price[2], saved.price[3], saved.price[4], saved.price[5]
    if not ok then error(err, 0) end
end)
-- (end of the item tooltip steps, v0.2 building block 2)
-- "Farm for plan", the shopping list of the skill plan on the map (v0.2 building block 3)
step("Farm for plan: a material's node kinds come from the spawn data alone; your own loot is only 'seen', counted from 20 gathers and 5 finds on (v0.2 B3 T1)", function()
    -- Concept shopping list 4.4 (Codex M3, P2-P4), tests 1 and 15; Sven V8.
    assert(type(ns.PlanBaseKinds) == "function" and type(ns.PlanBaseItem) == "function" and type(ns.PlanNodeMatches) == "function"
        and type(ns.PlanSeen) == "function" and type(ns.PlanSeenLimits) == "function", "no ns.PlanBaseKinds / PlanBaseItem / PlanNodeMatches / PlanSeen / PlanSeenLimits")
    local toc = assert(io.open(ROOT .. "/Gathercraft.toc")):read("*a")
    assert(toc:find("\nPlanFarm.lua", 1, true), "PlanFarm.lua is not in the TOC")
    local data = GathercraftQuestieData
    local COPPER, STONE, SEED, LINEN = 2770, 2835, 17034, 2589
    local VEIN = "o1731"
    local saved = { loot = ns.db.kindLoot, listeners = #ns.gatherListeners }
    local W = IdentityWorld()
    local before = #errors
    local ok, err = pcall(function()
        -- ---- base: the kinds whose main item it is, counted here again from the data
        local want = {}
        for key, kind in pairs(data.kinds) do
            if (kind[1] == "h" or kind[1] == "o") and kind[2] == COPPER then want[#want + 1] = key end
        end
        table.sort(want)
        assert(#want >= 1 and data.kinds[VEIN] and data.kinds[VEIN][2] == COPPER, "test setup: the copper vein o1731 is not in the spawn data")
        local got = ns.PlanBaseKinds(COPPER)
        assert(got and table.concat(got, " ") == table.concat(want, " "), "copper ore: kinds " .. table.concat(got or {}, " ") .. ", want " .. table.concat(want, " "))
        assert(ns.PlanBaseItem(VEIN) == COPPER, "the copper vein's main item: " .. tostring(ns.PlanBaseItem(VEIN)))
        -- every kind of the data: herbs and ores with an item have it as their base, nothing else has one
        local checked = 0
        for key, kind in pairs(data.kinds) do
            local isBase = (kind[1] == "h" or kind[1] == "o") and kind[2] > 0
            assert(ns.PlanBaseItem(key) == (isBase and kind[2] or nil), "the base item of " .. key .. ": " .. tostring(ns.PlanBaseItem(key)))
            if isBase then
                local found = false
                for _, k in ipairs(ns.PlanBaseKinds(kind[2])) do if k == key then found = true end end
                assert(found, key .. " is not among the kinds of its item " .. kind[2])
            end
            checked = checked + 1
        end
        assert(checked >= 80, "test setup: only " .. checked .. " kinds")
        -- a variant passes through its own kind (several kinds, one item)
        local several
        for key, kind in pairs(data.kinds) do
            if (kind[1] == "h" or kind[1] == "o") and kind[2] > 0 and #ns.PlanBaseKinds(kind[2]) >= 2 then several = kind[2] break end
        end
        assert(several, "test setup: no item with two node kinds")
        for _, key in ipairs(ns.PlanBaseKinds(several)) do
            assert(ns.PlanNodeMatches({ id = key, type = "ore" }, { [several] = true }), "a variant kind of item " .. several .. " does not match: " .. key)
        end
        -- no base: rough stone (a by-product), linen (cloth), a chest, things that are no kind
        local CHEST
        for key, kind in pairs(data.kinds) do if kind[1] == "c" then CHEST = key break end end
        assert(CHEST, "test setup: no chest kind")
        assert(ns.PlanBaseKinds(STONE) == nil and ns.PlanBaseKinds(LINEN) == nil and ns.PlanBaseKinds(0) == nil, "a base for rough stone, linen or item 0")
        assert(ns.PlanBaseItem(CHEST) == nil and ns.PlanBaseItem("o999999") == nil and ns.PlanBaseItem(nil) == nil and ns.PlanBaseItem(1731) == nil, "a base item for a chest or for no kind")

        -- ---- the match asks the kind, never what the node says it gave
        local set = { [COPPER] = true }
        assert(ns.PlanNodeMatches({ id = VEIN, type = "ore" }, set), "a copper vein does not match copper ore")
        assert(ns.PlanNodeMatches({ id = VEIN, type = "ore", item = STONE }, set), "a copper vein whose own loot said rough stone does not match copper ore")
        assert(not ns.PlanNodeMatches({ id = VEIN, type = "ore", item = STONE }, { [STONE] = true }), "n.item made a node a target for rough stone")
        assert(not ns.PlanNodeMatches({ id = "o999999", type = "ore", item = COPPER }, set), "a kind the spawn data does not know matched through n.item")
        assert(not ns.PlanNodeMatches({ id = "o999999", type = "ore", item = COPPER, source = "sync" }, set), "a node from sync matched through its item")
        assert(not ns.PlanNodeMatches({ id = CHEST, type = "chest", item = COPPER }, set), "a chest matched")
        assert(not ns.PlanNodeMatches({ type = "ore", name = "Copper Vein", item = COPPER }, set), "a node without an ID matched")
        assert(not ns.PlanNodeMatches({ id = VEIN }, {}) and not ns.PlanNodeMatches({ id = VEIN }, nil) and not ns.PlanNodeMatches(nil, set), "a match without a wanted item")

        -- ---- seen: counted by the listener, from real gathers
        local minGathers, minItem, maxItems = ns.PlanSeenLimits()
        assert(minGathers == 20 and minItem == 5 and maxItems == 50, ("the thresholds: %s, %s, %s - want 20, 5, 50"):format(tostring(minGathers), tostring(minItem), tostring(maxItems)))
        ns.db.kindLoot = nil
        -- asking does not make the table: only the listener writes
        assert(ns.PlanSeen(STONE) == nil and ns.PlanBaseKinds(COPPER) and ns.db.kindLoot == nil, "ns.db.kindLoot made by a question")
        local v = W.Node(VEIN, "Copper Vein", 0, { type = "ore", item = COPPER })
        W.Set({ v })
        W.At(0)
        local tagNo = 0
        local function Mine(items, tag)
            if not tag then tagNo = tagNo + 1 tag = ("T1%04d"):format(tagNo) end
            local c = W.Cast("Copper Vein", 2575) W.Wait(2) W.Done(c, 2575)
            loot = {}
            for i, item in ipairs(items) do loot[i] = { guid = ("GameObject-0-1-1-1-1731-%s"):format(tag), item = item, qty = 3 } end
            fire("LOOT_READY")
            loot = {}
            W.Wait(3)
            return tag
        end
        local function Entry() return ns.db.kindLoot and ns.db.kindLoot[VEIN] end
        Mine({ COPPER, STONE })
        local e = Entry()
        assert(e and e.n == 1 and e.items[STONE] == 1, "one gather with copper and stone: " .. tostring(e and e.n) .. " gathers, stone " .. tostring(e and e.items[STONE]))
        assert(e.items[COPPER] == nil, "the main item of the kind is kept as a by-product")
        -- the same item in two slots: one find, one gather
        Mine({ COPPER, STONE, STONE })
        assert(e.n == 2 and e.items[STONE] == 2, ("stone in two slots: %d gathers, stone %d - want 2 and 2"):format(e.n, e.items[STONE]))
        -- the same spawn again (a vein mined a second time): not counted
        local tag = Mine({ COPPER, STONE })
        assert(e.n == 3 and e.items[STONE] == 3, "test setup: the third gather")
        Mine({ COPPER, STONE }, tag)
        Mine({ COPPER, STONE, SEED }, tag)
        assert(e.n == 3 and e.items[STONE] == 3 and e.items[SEED] == nil, ("the same spawn again was counted: %d gathers, stone %d"):format(e.n, e.items[STONE]))
        -- only the main item: a gather, no find
        Mine({ COPPER })
        assert(e.n == 4 and e.items[STONE] == 3, "a gather with copper only: " .. e.n .. " gathers, stone " .. e.items[STONE])
        -- no quantities anywhere: two numbers and counts of gathers, nothing else
        for k, val in pairs(e) do assert((k == "n" and type(val) == "number") or (k == "items" and type(val) == "table"), "the entry keeps more than n and items: " .. tostring(k)) end
        for id, c in pairs(e.items) do assert(type(id) == "number" and type(c) == "number" and c <= e.n, "a count above the number of gathers (a quantity?): " .. tostring(c)) end
        -- under the thresholds nothing is shown: 19 gathers with 4 finds, 19 with 5, then 20 with 5
        assert(ns.PlanSeen(STONE) == nil, "seen with 4 gathers")
        Mine({ COPPER, STONE })                                  -- 5 gathers, 4 finds
        for _ = 1, 14 do Mine({ COPPER }) end                    -- 19 gathers, 4 finds
        assert(e.n == 19 and e.items[STONE] == 4 and ns.PlanSeen(STONE) == nil, ("19 gathers and 4 finds: %d, %d, shown: %s"):format(e.n, e.items[STONE], tostring(ns.PlanSeen(STONE) ~= nil)))
        -- (the 20th gather without stone: 20 and 4 - still nothing)
        Mine({ COPPER })
        assert(e.n == 20 and ns.PlanSeen(STONE) == nil, "shown with 20 gathers and 4 finds")
        Mine({ COPPER, STONE })
        local seen = ns.PlanSeen(STONE)
        assert(seen and #seen == 1 and seen[1].id == VEIN and seen[1].seen == 5 and seen[1].n == 21,
            ("21 gathers and 5 finds: %s"):format(seen and ("%s %s of %s"):format(tostring(seen[1].id), tostring(seen[1].seen), tostring(seen[1].n)) or "nothing"))
        -- seen is no base and makes no node a target
        assert(ns.PlanBaseKinds(STONE) == nil and not ns.PlanNodeMatches(v, { [STONE] = true }), "seen became a base")
        assert(ns.PlanSeen(COPPER) == nil and ns.PlanSeen(SEED) == nil, "seen for the main item or for an item never found")
        -- 5 finds in 19 gathers of another kind: under the gather threshold, nothing
        local listen = ns.gatherListeners
        local function Tell(node, p) for _, f in ipairs(listen) do f(node, p) end end
        local OTHER = "o1732"
        for i = 1, 19 do Tell({ id = OTHER, type = "ore", name = "Tin Vein" }, { items = { { id = 2771, qty = 1 }, i <= 5 and { id = SEED, qty = 1 } or nil } }) end
        assert(ns.db.kindLoot[OTHER].n == 19 and ns.db.kindLoot[OTHER].items[SEED] == 5 and ns.PlanSeen(SEED) == nil, "shown with 19 gathers and 5 finds")
        Tell({ id = OTHER, type = "ore", name = "Tin Vein" }, { items = { { id = 2771, qty = 1 } } })
        seen = ns.PlanSeen(SEED)
        assert(seen and seen[1].id == OTHER and seen[1].seen == 5 and seen[1].n == 20, "20 gathers and 5 finds are not shown")

        -- ---- what is no observation
        local n0 = e.n
        local function Keys() local c = 0 for _ in pairs(ns.db.kindLoot) do c = c + 1 end return c end
        local keys0 = Keys()
        Tell({ type = "ore", name = "Copper Vein" }, { items = { { id = STONE, qty = 1 } } })                 -- no object ID
        Tell({ id = VEIN, type = "ore" }, { value = 5 })                                                      -- loot nobody read
        Tell({ id = VEIN, type = "ore" }, { items = {} })
        Tell({ id = CHEST, type = "chest" }, { items = { { id = STONE, qty = 1 } } })                         -- a chest
        Tell({ id = "f123", type = "fish" }, { items = { { id = STONE, qty = 1 } } })                         -- a fishing spot
        Tell({ id = VEIN, type = "ore" }, nil)
        assert(e.n == n0 and Keys() == keys0 and ns.db.kindLoot[CHEST] == nil and ns.db.kindLoot["f123"] == nil, "something that is no readable herb or ore gather was counted")
        -- a new kind the spawn data does not know: no base, but it can be seen
        for i = 1, 20 do Tell({ id = "o999999", type = "herb", name = "New Herb" }, { items = { { id = 990001, qty = 1 }, i <= 6 and { id = 990002, qty = 2 } or nil } }) end
        assert(ns.PlanBaseItem("o999999") == nil and ns.PlanBaseKinds(990001) == nil, "a new kind got a base from its loot")
        seen = ns.PlanSeen(990002)
        assert(seen and seen[1].id == "o999999" and seen[1].seen == 6 and seen[1].n == 20, "a new kind's loot is not seen")
        assert(ns.PlanSeen(990001)[1].seen == 20, "the first item of a kind without a base is not counted like any other")

        -- ---- at most 50 items a kind: the rarest makes room, what was found often stays
        local BIG = "o1733"
        for i = 1, 30 do Tell({ id = BIG, type = "ore" }, { items = { { id = 980000, qty = 1 } } }) end
        for i = 1, 70 do Tell({ id = BIG, type = "ore" }, { items = { { id = 980000 + i, qty = 1 } } }) end
        local kept = 0
        for _ in pairs(ns.db.kindLoot[BIG].items) do kept = kept + 1 end
        assert(kept == 50, kept .. " items kept for one kind, want 50")
        assert(ns.db.kindLoot[BIG].items[980000] == 30 and ns.db.kindLoot[BIG].items[980070] == 1 and ns.db.kindLoot[BIG].n == 100, "the item found 30 times or the newest one is gone")

        -- ---- an error in this listener stops no other listener, and nothing gets out
        local called = 0
        table.insert(listen, function() called = called + 1 end)
        ns.db.kindLoot[VEIN] = "broken"
        ns.db.kindLoot.o1734 = { n = "x", items = 7 }
        local fine, why = pcall(Tell, { id = VEIN, type = "ore" }, { items = { { id = STONE, qty = 1 } } })
        Tell({ id = "o1734", type = "ore" }, { items = { { id = STONE, qty = 1 }, "junk", { id = "text" }, { id = -3 } } })
        local keep = ns.db.kindLoot
        ns.db.kindLoot = 5
        local fine2 = pcall(Tell, { id = VEIN, type = "ore" }, { items = { { id = STONE, qty = 1 } } })
        assert(type(ns.db.kindLoot) == "table", "a broken saved table was not replaced")
        ns.db.kindLoot = keep
        table.remove(listen)
        assert(fine and fine2 and called == 3, "broken saved data: error " .. tostring(why) .. ", the listener behind was called " .. called .. " times (want 3)")
        assert(type(ns.db.kindLoot[VEIN]) == "table" and ns.db.kindLoot[VEIN].n == 1 and ns.db.kindLoot.o1734.n == 1 and ns.db.kindLoot.o1734.items[STONE] == 1, "a broken entry was not begun anew")
        local junk = 0
        for _ in pairs(ns.db.kindLoot.o1734.items) do junk = junk + 1 end
        assert(junk == 1, "something that is no item ID was kept")
        -- a listener that throws on its own: the source keeps its own errors (a pcall around the count)
        local src = assert(io.open(ROOT .. "/PlanFarm.lua")):read("*a")
        assert(src:find("pcall(CountGather, node, p)", 1, true), "the listener does not keep its errors to itself")
        assert(#errors == before, "an error: " .. tostring(errors[#errors]))
    end)
    while #ns.gatherListeners > saved.listeners do table.remove(ns.gatherListeners) end
    W.Restore()
    ns.db.kindLoot = saved.loot
    if not ok then error(err, 0) end
end)
step("Farm for plan: the run - its filter, what it routes to, when it waits, ends once or is blocked, and after a reload (v0.2 B3 T2)", function()
    -- Concept shopping list 4.2, 4.3, 4.5, 4.6, 4.8; tests 3, 5, 7, 8, 12, 14, 17;
    -- Sven V4, V5, V7, V9; the order's extra tests (preview, updating, the
    -- second reader of the plan).
    assert(type(ns.PlanFilter) == "function" and type(ns.PlanFilterParse) == "function" and type(ns.PlanRunState) == "function"
        and type(ns.PlanRunLastEnd) == "function" and type(ns.PlanRunResume) == "function" and type(ns.SkillPlanFor) == "function",
        "no ns.PlanFilter / PlanFilterParse / PlanRunState / PlanRunLastEnd / PlanRunResume / SkillPlanFor")
    local L, d, core = ns.L, ns.CraftData, ns.PlanCore
    local COPPER, TIN, VEIN = 2770, 2771, "o1731"
    local TINVEIN
    for key, kind in pairs(GathercraftQuestieData.kinds) do
        if kind[1] == "o" and kind[2] == TIN and (not TINVEIN or key < TINVEIN) then TINVEIN = key end
    end
    assert(TINVEIN, "test setup: no tin vein in the spawn data")
    local saved = { rank = ns.ProfessionRank, have = d.Have, known = d.Known, skill = ns.GetSkill, planFor = ns.SkillPlanFor, shown = ns.SkillPlanShown,
        compute = core.Compute, enabled = ns.IsNodeEnabled, parked = ns.IsParked, targets = ns.db.planTargets, listeners = ns.skillPlanListeners,
        other = ns.db.nodes[1413], run = ns.db.activeRun, summaryOff = ns.db.summaryOff, loot = ns.db.kindLoot }
    local W = IdentityWorld()
    local before = #errors
    local win = _G.GathercraftSkillPlan
    if win then win:Hide() end
    local ok, err = pcall(function()
        local profSkill, gatherSkill, stock = 1, 100, {}
        ns.ProfessionRank = function(p) if p == "Mining" then return profSkill, 75 end end
        d.Known = function() return {} end
        d.Have = function(id)
            local v = stock[id]
            if v == "?" then return nil end
            return v or 0
        end
        ns.GetSkill = function(t) if t == "ore" and gatherSkill then return gatherSkill, 300, gatherSkill end end
        local computes = 0
        core.Compute = function(...) computes = computes + 1 return saved.compute(...) end
        local published = 0
        local function Count() published = published + 1 end
        table.insert(ns.skillPlanListeners, Count)
        saved.count = Count
        local mark = #log
        local function Said(text)
            for i = mark + 1, #log do if log[i]:find(text, 1, true) then return true end end
            return false
        end
        local function Bags(n) for _ = 1, n or 1 do fire("BAG_UPDATE_DELAYED") end end
        local function State() local s = ns.PlanRunState() return s and s.state, s end
        local function Row(item)
            local s = ns.PlanRunState()
            for _, r in ipairs((s and s.rows) or {}) do if r.item == item then return r end end
        end
        local function Ends() local _, n = ns.PlanRunLastEnd() return n end
        local function Last() return (ns.PlanRunLastEnd()) end
        local summary = function() local f = _G.GathercraftRunSummary return f and f:IsShown() or false end
        local hintShown = function() local f = _G.GathercraftPlanHint return (f and f.shown) or 0 end
        local function Veins(extra)
            local list = { W.Node(VEIN, "Copper Vein", 100, { type = "ore" }), W.Node(VEIN, "Copper Vein", 200, { type = "ore" }),
                W.Node(VEIN, "Copper Vein", 300, { type = "ore", item = 2835 }) } -- (the third says it gave rough stone)
            for _, n in ipairs(extra or {}) do list[#list + 1] = n end
            W.Set(list)
            W.At(0)
        end
        local function Tin(x) return W.Node(TINVEIN, "Tin Vein", x or 400, { type = "ore" }) end

        -- ---- the filter (test 17)
        local F30 = ns.PlanFilter("Mining", 30)
        assert(F30 == "plan:v1:mining:30" and F30:lower() == F30, "the filter of Mining to 30: " .. tostring(F30))
        assert(ns.PlanFilter("First Aid", 75) == "plan:v1:first_aid:75", "the filter of First Aid: " .. tostring(ns.PlanFilter("First Aid", 75)))
        local prof, target = ns.PlanFilterParse("plan:v1:first_aid:75")
        assert(prof == "First Aid" and target == 75, "plan:v1:first_aid:75 read back: " .. tostring(prof) .. " " .. tostring(target))
        prof, target = ns.PlanFilterParse("plan:v1:mining:150")
        assert(prof == "Mining" and target == 150, "plan:v1:mining:150 read back: " .. tostring(prof) .. " " .. tostring(target))
        for _, p in ipairs(d.Professions) do
            local f = ns.PlanFilter(p.name, 150)
            local back, t = ns.PlanFilterParse(f)
            assert(f and f == f:lower() and back == p.name and t == 150, "the filter of " .. p.name .. " does not come back: " .. tostring(f))
        end
        for _, bad in ipairs({ "plan:v2:mining:150", "plan:mining:150", "plan:v1:bergbau:150", "plan:v1:smelting:150", "plan:v1:mining:0", "plan:v1:mining:301",
            "plan:v1:mining:15x", "plan:v1:mining:", "plan:v1:mining", "plan:v1::150", "plan:v1:Mining:150", "plan:v1:mining:150 ", "plan:", "plan:v1:mining:1.5", "item:2770" }) do
            assert(ns.PlanFilterParse(bad) == nil, "read as a plan run: " .. bad)
        end
        assert(ns.PlanFilter("Bergbau", 150) == nil and ns.PlanFilter("Smelting", 150) == nil and ns.PlanFilter("Mining", 150.5) == nil
            and ns.PlanFilter("Mining", 0) == nil and ns.PlanFilter("Mining", 301) == nil and ns.PlanFilter(nil, 150) == nil, "a filter for something that is no plan")

        -- ---- an unknown format is no run: not by hand, not by its name, and the run before stays
        Veins({ W.Node("o1731", "plan:v2:mining:150", 500, { type = "ore" }) }) -- (a node whose NAME is the filter: the old name search would take it)
        ns.StartRun("ore", 1412) W.Wait(1)
        local oreRun = ns.run
        assert(oreRun and oreRun.filter == "ore", "test setup: no ore run")
        for _, bad in ipairs({ "plan:v2:mining:150", "plan:mining:150", "PLAN:V1:BERGBAU:150", "plan:v1:mining:999" }) do
            mark = #log
            slash("run " .. bad)
            W.Wait(1)
            assert(ns.run == oreRun and ns.db.activeRun and ns.db.activeRun.filter == "ore", "a plan filter of an unknown format changed the run: " .. bad)
            assert(Said(L["That is no plan run Gathercraft knows (unknown format). Start it from the skill plan."]), "no word about the unknown format: " .. bad)
        end
        ns.StopRun(true)
        slash("run plan:v2:mining:150") W.Wait(1)
        assert(ns.run == nil and ns.db.activeRun == nil, "a run from a plan filter of an unknown format (the name search?)")
        -- no preview: that would be a "show on map" without a run
        mark = #log
        slash("route " .. F30) W.Wait(1)
        assert(Said(L["A plan run has no route preview. Start it from the skill plan."]) and ns.run == nil, "a route preview for a plan")

        -- ---- nothing is worked out without the window and without a plan run
        Veins({ Tin() })
        computes = 0
        stock[COPPER] = 3 Bags(3) W.Wait(2)
        assert(computes == 0, "the plan was worked out " .. computes .. " time(s) with the window closed and no plan run")
        local r, why = ns.SkillPlanFor("Mining", 30)
        assert(r == nil and why == "off" and computes == 0, "the plan for a run that is not there: " .. tostring(why))

        -- ---- start: one zone, the plan's materials through their kinds, your own count
        stock[COPPER] = 0
        mark = #log
        ns.StartRun(F30, 1412) W.Wait(1)
        local run = ns.run
        assert(run and run.plan and run.filter == F30 and run.zone == 1412 and not run.quick and not run.loopMode, "no plan run in the zone asked for")
        assert(ns.db.activeRun and ns.db.activeRun.filter == F30 and ns.db.activeRun.zone == 1412 and ns.db.activeRun.quick == nil, "the saved run is not the plan run")
        assert(State() == "active", "the state after the start: " .. tostring(State()))
        assert(computes >= 1, "the plan run did not work the plan out (the second reader)")
        assert(#run.points == 3, "the route has " .. #run.points .. " nodes, want the 3 copper veins (the tin vein is not in the plan to 30)")
        for _, p in ipairs(run.points) do assert(p.node.id == VEIN, "a node of another kind in the route: " .. tostring(p.node.id)) end
        assert(run.goal == "plan" and run.target and run.path and #run.path > 0, "the plan run steers to nothing")
        for key, w in pairs(run.weights) do assert(w == 1 or w == 0, "the weight of " .. tostring(key) .. " is " .. tostring(w) .. ": a plan run knows 1 (you can gather it) and 0") end
        assert(Said((L["Route goal: %s."]):format(L["Plan"])), "the start line does not name the plan as the goal")
        local row = Row(COPPER)
        assert(row and row.need == 30 and row.have == 0 and row.ok == false, "copper ore at the start: " .. tostring(row and row.have) .. " / " .. tostring(row and row.need))

        -- typed by hand without a zone: the zone you stand in, nothing else
        ns.StopRun(true)
        slash("run " .. F30) W.Wait(1)
        run = ns.run
        assert(run and run.plan and run.zone == 1412 and ns.db.activeRun.zone == 1412 and #run.points == 3, "/gcr run with a plan filter: not a run in the zone you stand in")

        -- ---- loot never counts: only what the plan says you have (tests 3, 12)
        W.At(100)
        local c = W.Cast("Copper Vein", 2575) W.Wait(2) W.Done(c, 2575) W.Loot(1731, COPPER, "T2A001") fire("LOOT_CLOSED") W.Wait(4)
        row = Row(COPPER)
        assert(row.have == 0 and State() == "active", "a gather counted without the bags: " .. tostring(row.have))
        local pub0 = published
        stock[COPPER] = 12 Bags(3) W.Wait(1) Bags(1) W.Wait(1)
        row = Row(COPPER)
        assert(row.have == 12 and row.ok == false, "after the bags changed: " .. tostring(row.have) .. ", want 12")
        assert(published == pub0 + 1, "4 bag events for one change gave " .. (published - pub0) .. " plans, want 1")

        -- ---- the last material: no end while the loot is on its way (waiting), then one end, silent
        local ends0 = Ends()
        mark = #log
        fire("LOOT_OPENED")
        stock[COPPER] = 30 Bags(1) W.Wait(0.5)
        assert(ns.run and State() == "waiting" and Ends() == ends0, "ended (or decided) with the loot window open: " .. tostring(State()))
        fire("LOOT_CLOSED") W.Wait(1)
        assert(ns.run and State() == "waiting", "decided 1 s after the loot window closed, without a bag update: " .. tostring(State()))
        W.Wait(2)
        assert(ns.run == nil and ns.db.activeRun == nil, "not ended 3 s after the loot window closed with everything gathered")
        local last = Last()
        assert(Ends() == ends0 + 1 and last.kind == "success" and last.prof == "Mining" and last.target == 30 and last.zone == 1412, "the end: " .. tostring(last and last.kind))
        assert(last.rows[1].item == COPPER and last.rows[1].ok and last.rows[1].have == 30, "the end does not say what was gathered")
        assert(not Said(L["Run stopped."]) and not summary() and hintShown() == 0, "the end of a plan run said \"Run stopped.\", showed the run summary or the blocked window")
        assert(ns.PlanRunState() == nil and select(2, ns.SkillPlanFor("Mining", 30)) == "off", "something of the plan run is left after its end")
        -- later events find no run: no second end, and nothing starts again when the count falls
        Bags(2) fire("LOOT_CLOSED") fire("SKILL_LINES_CHANGED") W.Wait(4)
        stock[COPPER] = 5 Bags(1) W.Wait(4)
        assert(Ends() == ends0 + 1 and ns.run == nil, "a second end, or a run that started by itself")
        -- asked for with everything gathered: no run, a word
        stock[COPPER] = 30
        mark = #log
        ns.StartRun(F30, 1412) W.Wait(1)
        assert(ns.run == nil and Ends() == ends0 + 1 and Said(L["Everything from the map is gathered for your plan."]), "a run although everything is gathered")
        -- the bag update right after the loot window: decided at once
        stock[COPPER] = 29
        ns.StartRun(F30, 1412) W.Wait(1)
        assert(State() == "active", "test setup: no run with 29 of 30")
        fire("LOOT_OPENED") fire("LOOT_CLOSED") stock[COPPER] = 30 Bags(1) W.Wait(0.5)
        assert(ns.run == nil and Ends() == ends0 + 2, "loot window closed, then the bags: not ended at once")
        -- a skill point before the bags: waiting, decided with the bags (test 14)
        stock[COPPER] = 29
        ns.StartRun(F30, 1412) W.Wait(1)
        stock[COPPER] = 30
        fire("SKILL_LINES_CHANGED") W.Wait(0.5)
        assert(ns.run and State() == "waiting" and Ends() == ends0 + 2, "decided on a skill change before the bags: " .. tostring(State()))
        Bags(2) W.Wait(0.5)
        assert(ns.run == nil and Ends() == ends0 + 3, "not ended with the bags after the skill change")
        -- a skill change that no bag update follows (a trainer): 2 s, then decided
        stock[COPPER] = 29
        ns.StartRun(F30, 1412) W.Wait(1)
        stock[COPPER] = 30
        fire("SKILL_LINES_CHANGED") W.Wait(1.5)
        assert(ns.run, "decided 1.5 s after a skill change")
        W.Wait(1.5)
        assert(ns.run == nil and Ends() == ends0 + 4, "a skill change without a bag update keeps the run waiting")

        -- ---- stopped by the player: as any run, and nothing of the plan stays
        stock[COPPER] = 0
        ns.StartRun(F30, 1412) W.Wait(1)
        mark = #log
        local endsS = Ends()
        ns.StopRun()
        assert(Said(L["Run stopped."]) and ns.run == nil and ns.PlanRunState() == nil and Ends() == endsS, "a stop by the player is not a plain stop")
        computes = 0
        stock[COPPER] = 7 Bags(2) W.Wait(2)
        assert(computes == 0, "the plan is worked out after the plan run was stopped")

        -- ---- blocked (tests 8, 14): what is left cannot be farmed here - no success, a small window, once
        -- the plan to 75 needs copper (120) and tin (10); the copper is there
        local F75 = ns.PlanFilter("Mining", 75)
        stock[COPPER], stock[TIN] = 120, 0
        Veins({ Tin() })
        -- asked for without the skill for tin: no run, why
        gatherSkill = 10
        mark = #log
        local endsB, hints0 = Ends(), hintShown()
        ns.StartRun(F75, 1412) W.Wait(1)
        assert(ns.run == nil and Ends() == endsB, "a run for tin without the skill for it")
        assert(Said(ns.ItemName(TIN) or "x") and Said(L["can't gather yet"]), "no word why there is no run (can't gather yet)")
        local check = ns.PlanRunCheck("Mining", 75, 1412)
        assert(check.state == "blocked" and #check.reasons == 1 and check.reasons[1].item == TIN and check.reasons[1].reason == "no_skill", "the check of the zone: " .. tostring(check.state))
        -- with the skill it runs - to the tin vein only (the copper is covered)
        gatherSkill = 100
        ns.StartRun(F75, 1412) W.Wait(1)
        run = ns.run
        assert(run and State() == "active" and #run.points == 1 and run.points[1].node.id == TINVEIN, "the run for tin: " .. tostring(State()) .. ", " .. tostring(run and #run.points) .. " nodes")
        assert(Row(COPPER).ok and not Row(TIN).ok, "copper is not ticked or tin is")
        -- the skill is gone in the middle of the run (gloves off): blocked, not success
        gatherSkill = 10
        mark = #log
        W.Wait(40) Bags(1) W.Wait(2)
        last = Last()
        assert(ns.run == nil and Ends() == endsB + 1 and last.kind == "blocked", "the run without anything to gather left did not end as blocked")
        assert(#last.reasons == 1 and last.reasons[1].item == TIN and last.reasons[1].reason == "no_skill", "the reason of the blocked end")
        assert(hintShown() == hints0 + 1 and _G.GathercraftPlanHint:IsShown(), "the blocked end shows no window (or more than one)")
        assert(not Said(L["Run stopped."]) and not summary() and not Said(L["You can't gather any of these nodes yet (skill too low or profession not learned)."]),
            "the blocked end went the route's own way out")
        Bags(2) W.Wait(4)
        assert(hintShown() == hints0 + 1 and Ends() == endsB + 1, "a second window after the blocked end")
        _G.GathercraftPlanHint:Hide()
        gatherSkill = 100
        -- only in another zone: blocked with "not in this zone", and the run never changes its zone
        Veins()
        ns.db.nodes[1413] = { Tin(0) }
        ns.NotifyNodesChanged() advance(1)
        check = ns.PlanRunCheck("Mining", 75, 1412)
        assert(check.state == "blocked" and check.reasons[1].reason == "not_in_zone", "tin only in another zone: " .. tostring(check.state) .. " " .. tostring(check.reasons and check.reasons[1] and check.reasons[1].reason))
        mark = #log
        ns.StartRun(F75, 1412) W.Wait(1)
        assert(ns.run == nil and Said(L["not in this zone"]), "a run (in another zone?) although nothing is here")
        ns.db.nodes[1413] = saved.other
        -- switched off in the Zones tab, parked by reports
        Veins({ Tin() })
        ns.IsNodeEnabled = function(n, mapID) if n.id == TINVEIN then return false end return saved.enabled(n, mapID) end
        check = ns.PlanRunCheck("Mining", 75, 1412)
        assert(check.state == "blocked" and check.reasons[1].reason == "kinds_off", "tin switched off: " .. tostring(check.reasons and check.reasons[1] and check.reasons[1].reason))
        ns.IsNodeEnabled = saved.enabled
        ns.IsParked = function(n) return n.id == TINVEIN end
        ns.NotifyNodesChanged() advance(1)
        check = ns.PlanRunCheck("Mining", 75, 1412)
        assert(check.state == "blocked" and check.reasons[1].reason == "parked", "tin parked: " .. tostring(check.reasons and check.reasons[1] and check.reasons[1].reason))
        ns.IsParked = saved.parked
        ns.NotifyNodesChanged() advance(1)
        -- no gathering profession can be read: not filtered, as every run - no success, not blocked
        gatherSkill = nil
        check = ns.PlanRunCheck("Mining", 75, 1412)
        assert(check.state == "active", "no gathering skill readable: " .. tostring(check.state))
        gatherSkill = 100
        -- a count that is not known: "?", no tick, never an end
        stock[COPPER], stock[TIN] = "?", 10
        ns.StartRun(F75, 1412) W.Wait(1)
        row = Row(COPPER)
        assert(ns.run and State() == "active" and row.have == nil and row.ok == false and Row(TIN).ok, "an unknown count: " .. tostring(State()) .. ", copper " .. tostring(row and row.have))
        Bags(2) W.Wait(4)
        assert(ns.run and Ends() == endsB + 1, "ended with a count that is not known")
        ns.StopRun(true)

        -- ---- the plan itself (the order's extra tests; test 14): told through what the plan run is given
        Veins({ Tin() })
        stock[COPPER], stock[TIN] = 0, 0
        ns.StartRun(F75, 1412) W.Wait(1)
        assert(State() == "active" and #ns.run.points == 4, "test setup: the run for copper and tin")
        local endsP = Ends()
        local given
        ns.SkillPlanFor = function() if type(given) == "table" then return given end return nil, given end
        local function Result(items, more)
            local res = { prof = "Mining", from = 1, target = 75, status = "ok", valid = true, complete = true, reliable = true, revision = 9000, items = {} }
            for id, m in pairs(items) do res.items[id] = { need = m[1], have = m[2], haveKnown = m[2] ~= nil, missing = math.max(0, m[1] - (m[2] or 0)) } end
            for k, v in pairs(more or {}) do res[k] = v end
            return res
        end
        local ALL = { [COPPER] = { 120, 120 }, [TIN] = { 10, 10 } }
        local function Look() Bags(1) W.Wait(1) end
        -- a preview (the skill was only seen last) with everything covered: no end, no tick taken from it
        given = Result(ALL, { reliable = false, status = "preview", complete = false })
        Look()
        local st, s = State()
        assert(ns.run and st == "invalid" and s.why == "preview" and s.frozen and Ends() == endsP, "a preview with everything covered: " .. tostring(st))
        assert(s.rows and #s.rows == 2 and s.rows[1].have == 0, "the rows read last are gone while the plan is not known")
        assert(ns.run.target and #ns.run.points == 4, "the route did not go on with the materials read last")
        -- a plan that is being worked out anew: waiting
        given = Result(ALL, { updating = true })
        Look()
        assert(ns.run and State() == "waiting" and Ends() == endsP, "a plan marked as being updated ended the run: " .. tostring(State()))
        given = "working" Look()
        assert(ns.run and State() == "waiting", "a plan on its way: " .. tostring(State()))
        -- no plan to go by
        for _, w in ipairs({ "window", "skill", "broke" }) do
            given = w Look()
            st, s = State()
            assert(ns.run and st == "invalid" and s.why == w and Ends() == endsP, "no plan (" .. w .. "): " .. tostring(st))
        end
        given = Result(ALL, { valid = false, complete = false, status = "invalid" })
        Look()
        assert(ns.run and State() == "invalid" and Ends() == endsP, "an invalid plan with everything covered ended the run")
        -- an empty route never ends a plan run: no nodes at all and no plan
        given = "skill"
        W.Set({}) W.At(0)
        mark = #log
        Look() W.Wait(40)
        assert(ns.run and State() == "invalid" and Ends() == endsP and ns.run.target == nil, "a plan run without nodes and without a plan ended (from the empty route?)")
        assert(not Said(L["No matching nodes in "]) and not Said(L["Run stopped."]), "the empty route's own way out")
        -- an incomplete plan with all it lists covered: blocked, never success
        Veins({ Tin() })
        given = Result(ALL, { complete = false, status = "incomplete" })
        Look()
        last = Last()
        assert(ns.run == nil and Ends() == endsP + 1 and last.kind == "blocked" and last.reasons[1].reason == "plan_incomplete", "an incomplete plan with everything covered: " .. tostring(last and last.kind))
        _G.GathercraftPlanHint:Hide()
        -- the target is reached, or the plan needs nothing from the map: success, also with nothing at all in K
        for i, res in ipairs({ Result({}, { status = "done" }), Result({ [2840] = { 8, 0 } }), Result({ [COPPER] = { 0, 0 }, [TIN] = { 0, 5 } }) }) do
            given = Result({ [COPPER] = { 120, 0 }, [TIN] = { 10, 0 } })
            ns.StartRun(F75, 1412) W.Wait(1)
            assert(State() == "active", "test setup: the run before case " .. i)
            given = res
            local e0 = Ends()
            Look()
            last = Last()
            assert(ns.run == nil and Ends() == e0 + 1 and last.kind == "success", "nothing left from the map (case " .. i .. "): " .. tostring(last and last.kind))
            assert(#last.rows == 0 and (i ~= 2 or (#last.offMap == 1 and last.offMap[1].item == 2840 and not last.offMap[1].ok)), "the end does not name what is not on the map (case " .. i .. ")")
        end
        -- asked for: target reached / no plan
        mark = #log
        given = Result({}, { status = "done" })
        ns.StartRun(F75, 1412) W.Wait(1)
        assert(ns.run == nil and Said(L["Target reached: nothing left to farm for your plan."]), "a run although the target is reached")
        for w, text in pairs({ window = "the skill plan shows another profession", skill = "your skill can't be read", preview = "the plan is only a preview (skill last seen)" }) do
            mark = #log
            given = w == "preview" and Result(ALL, { reliable = false, status = "preview" }) or w
            ns.StartRun(F75, 1412) W.Wait(1)
            assert(ns.run == nil and Said((L["No plan run: %s."]):format(L[text])), "a run without a plan to go by (" .. w .. ")")
        end

        -- ---- the target is changed in the open window: the same profession is followed, another one is not (Sven V7)
        given = Result({ [COPPER] = { 120, 0 }, [TIN] = { 10, 0 } })
        ns.StartRun(F75, 1412) W.Wait(1)
        ns.SkillPlanShown = function() return "Tailoring", 150 end
        Look()
        assert(ns.run and ns.run.filter == F75 and ns.db.activeRun.filter == F75, "the run followed another profession")
        ns.SkillPlanShown = function() return "Mining", 65 end
        Look()
        local F65 = ns.PlanFilter("Mining", 65)
        s = ns.PlanRunState()
        assert(ns.run and ns.run.filter == F65 and ns.db.activeRun.filter == F65 and s.target == 65, "the run did not follow the new target: " .. tostring(ns.run and ns.run.filter))
        ns.SkillPlanShown = saved.shown
        ns.StopRun(true)
        ns.SkillPlanFor = saved.planFor

        -- ---- after a reload (test 5): the same run goes on; a format this version does not know is dropped and said
        stock[COPPER], stock[TIN] = 5, 0
        Veins({ Tin() })
        ns.StartRun(F75, 1412) W.Wait(1)
        local keep = { filter = ns.db.activeRun.filter, zone = ns.db.activeRun.zone }
        ns.StopRun(true)
        ns.db.activeRun = { filter = keep.filter, zone = keep.zone }
        assert(ns.PlanRunResume(ns.db.activeRun) and ns.run, "the saved plan run was not taken up")
        W.Wait(1)
        row = Row(COPPER)
        assert(ns.run.filter == F75 and ns.run.zone == 1412 and State() == "active" and row.have == 5 and row.need == 120, "the run after the reload: " .. tostring(State()))
        -- everything covered when it is taken up: one end
        ns.StopRun(true)
        stock[COPPER], stock[TIN] = 120, 10
        ns.db.activeRun = { filter = keep.filter, zone = keep.zone }
        local endsR = Ends()
        ns.PlanRunResume(ns.db.activeRun) W.Wait(2)
        assert(ns.run == nil and ns.db.activeRun == nil and Ends() == endsR + 1 and Last().kind == "success", "taken up with everything gathered: not one end")
        Bags(1) W.Wait(3)
        assert(ns.run == nil and Ends() == endsR + 1, "something happened after the end")
        -- formats of another version, a missing zone
        for _, bad in ipairs({ { filter = "plan:v2:mining:75", zone = 1412 }, { filter = "plan:mining:75", zone = 1412 }, { filter = "plan:v1:bergbau:75", zone = 1412 },
            { filter = "plan:v1:mining:75" } }) do
            mark = #log
            ns.db.activeRun = bad
            assert(ns.PlanRunResume(bad) == false, "a saved run of an unknown format was taken up: " .. bad.filter)
            W.Wait(1)
            assert(ns.run == nil and ns.db.activeRun == nil, "an unknown format left a run or a saved run behind: " .. bad.filter)
            assert(Said(L["Your saved plan run can't be resumed (unknown format). Start it again from the skill plan."]), "no word about the saved run: " .. bad.filter)
        end
        local coreSrc = assert(io.open(ROOT .. "/Core.lua")):read("*a")
        assert(coreSrc:find("ns.PlanRunResume(saved)", 1, true), "Core.lua does not hand a saved plan run to PlanFarm.lua")

        -- ---- the open window decides what is planned: one calculation for both readers
        stock[COPPER], stock[TIN] = 5, 0
        ns.db.planTargets = nil -- (the window's target for skill 1 is the next rank: 75)
        Veins({ Tin() })
        ns.StartRun(F75, 1412) W.Wait(1)
        assert(State() == "active" and Row(COPPER).have == 5, "test setup: the run before the window opens")
        ns.ShowSkillPlan("Mining") W.Wait(1)
        win = _G.GathercraftSkillPlan
        assert(win and win:IsShown() and State() == "active", "the window open on the run's plan: " .. tostring(State()))
        local c0, p0 = computes, published
        stock[COPPER] = 6 Bags(2) W.Wait(1)
        assert(Row(COPPER).have == 6, "the run did not get the plan the window worked out: " .. tostring(Row(COPPER).have))
        assert(computes == c0 + 1 and published == p0 + 1, ("one change with window and run: worked out %d times, %d plans - want 1 and 1"):format(computes - c0, published - p0))
        -- the window shows another profession: the run knows nothing new and decides nothing
        ns.ShowSkillPlan("Tailoring") W.Wait(1)
        stock[COPPER], stock[TIN] = 120, 10
        Bags(1) W.Wait(3)
        st, s = State()
        assert(ns.run and st == "invalid" and s.why == "window" and s.frozen, "the window on another profession: " .. tostring(st) .. " " .. tostring(s and s.why))
        assert(s.rows and Row(COPPER).have == 6, "the rows read last are gone while the window shows another profession")
        -- closed again: the run reads the plan itself - and ends, everything is there
        local endsW = Ends()
        win:Hide()
        Bags(1) W.Wait(1)
        assert(ns.run == nil and Ends() == endsW + 1 and Last().kind == "success", "after the window closed the run did not read the plan")

        -- ---- the single "Farm" run of one material goes by the node's own item as before
        Veins()
        ns.StartRun("item:2835", 1412) W.Wait(1)
        assert(ns.run and #ns.run.points == 1 and ns.run.points[1].node.item == 2835, "an item: run changed: " .. tostring(ns.run and #ns.run.points))
        ns.StopRun(true)
        assert(#errors == before, "an error: " .. tostring(errors[#errors]))
    end)
    ns.SkillPlanFor, ns.SkillPlanShown = saved.planFor, saved.shown
    if ns.run then ns.StopRun(true) end
    ns.ProfessionRank, d.Have, d.Known, ns.GetSkill, core.Compute = saved.rank, saved.have, saved.known, saved.skill, saved.compute
    ns.IsNodeEnabled, ns.IsParked, ns.db.planTargets = saved.enabled, saved.parked, saved.targets
    for i = #ns.skillPlanListeners, 1, -1 do
        if ns.skillPlanListeners[i] == saved.count then table.remove(ns.skillPlanListeners, i) end
    end
    if win then win:Hide() end
    ns.db.nodes[1413], ns.db.activeRun, ns.db.kindLoot = saved.other, saved.run, saved.loot
    if _G.GathercraftPlanHint then _G.GathercraftPlanHint:Hide() end
    if _G.GathercraftPlanZones then _G.GathercraftPlanZones:Hide() end
    if _G.GathercraftRunSummary then _G.GathercraftRunSummary:Hide() end
    W.Restore()
    if not ok then error(err, 0) end
end)
step("Farm for plan: one zone - the one you stand in or the one you click in the list of known spots; never another one by itself (v0.2 B3 T3)", function()
    -- Concept shopping list 4.7, test 13; Sven E6/E9, V11, V12; the order's
    -- extra test (the list counts without the tooltip option).
    assert(type(ns.PlanFarmStart) == "function" and type(ns.PlanZoneListShow) == "function" and type(ns.PlanZoneListGo) == "function"
        and type(ns.PlanZoneListState) == "function", "no ns.PlanFarmStart / PlanZoneListShow / PlanZoneListGo / PlanZoneListState")
    local L, data = ns.L, GathercraftQuestieData
    local COPPER, TIN, INCEND, VEIN = 2770, 2771, 3340, "o1731"
    local function KindsOf(item)
        local list = {}
        for key, kind in pairs(data.kinds) do if kind[1] == "o" and kind[2] == item then list[#list + 1] = key end end
        table.sort(list)
        return list
    end
    local TINVEIN, INC = KindsOf(TIN)[1], KindsOf(INCEND)
    assert(TINVEIN and #INC >= 2, "test setup: no tin vein, or Incendicite has fewer than two node kinds")
    local CITY
    for city, zone in pairs(ns.CITY_ZONE) do if zone == 1412 then CITY = city end end
    assert(CITY, "test setup: no capital that counts as Mulgore")
    local WETLANDS, BARRENS = 1437, 1413
    assert(ns.GetContinent(1412) == ns.GetContinent(BARRENS) and ns.GetContinent(WETLANDS) and ns.GetContinent(WETLANDS) ~= ns.GetContinent(1412), "test setup: the continents of the test zones")
    local saved = { planFor = ns.SkillPlanFor, skill = ns.GetSkill, here = ns.StartHereRun, candidates = ns.PlanRouteCandidates, tooltip = ns.db.tooltipPrices,
        barrens = ns.db.nodes[BARRENS], wetlands = ns.db.nodes[WETLANDS], run = ns.db.activeRun, zones = ns.db.disabledZones, counts = ns.SpawnCounts, extra = {},
        spawnZones = ns.db.spawnZones }
    local W = IdentityWorld()
    local before = #errors
    -- (this step is about the zones with nodes: every zone with shipped spawn
    -- points counts as loaded here, so the list knows only the nodes this
    -- step sets. The zones not loaded yet: R1-M5, its own step.)
    ns.db.spawnZones = {}
    for mapID in pairs(GathercraftQuestieData.zones) do ns.db.spawnZones[mapID] = true end
    local ok, err = pcall(function()
        ns.GetSkill = function(t) if t == "ore" then return 300, 300, 300 end end
        local given, revision = nil, 100
        ns.SkillPlanFor = function() if type(given) == "table" then return given end return nil, given end
        local function Plan(items, more)
            revision = revision + 1
            local res = { prof = "Mining", from = 1, target = 75, status = "ok", valid = true, complete = true, reliable = true, revision = revision, items = {} }
            for id, m in pairs(items) do res.items[id] = { need = m[1], have = m[2], haveKnown = m[2] ~= nil, missing = math.max(0, m[1] - (m[2] or 0)) } end
            for k, v in pairs(more or {}) do res[k] = v end
            given = res
            return res
        end
        local function NewPlan(items, more)
            local res = Plan(items, more)
            for _, f in ipairs(ns.skillPlanListeners) do f(res) end
            advance(1)
        end
        local hereCalls = 0
        ns.StartHereRun = function(...) hereCalls = hereCalls + 1 return saved.here(...) end
        -- (the other zones' nodes are out of the way for this step)
        for mapID, nodes in pairs(ns.db.nodes) do
            if type(mapID) == "number" and mapID ~= 1412 and mapID ~= BARRENS and mapID ~= WETLANDS then saved.extra[mapID] = { nodes } end
        end
        for mapID in pairs(saved.extra) do ns.db.nodes[mapID] = nil end
        local F = ns.PlanFilter("Mining", 75)
        local function Ore(id, name, x) return W.Node(id, name, x, { type = "ore" }) end
        local function ListData() return (ns.PlanZoneListState()) end
        local function Builds() return (select(2, ns.PlanZoneListState())) end
        local function Win() return _G.GathercraftPlanZones end
        local function Open() return Win() ~= nil and Win():IsShown() end
        local function Close() if Open() then Win():Hide() end end
        local function ZoneRow(mapID)
            for i, z in ipairs((ListData() or {}).zones or {}) do if z.mapID == mapID then return z, i end end
        end
        local function Places(zone, item)
            for _, it in ipairs((zone or {}).items or {}) do if it.item == item then return it.places, it.candidates end end
        end
        local function Clear()
            if ns.run then ns.StopRun(true) end
            Close()
        end
        local mark = #log
        local function Said(text)
            for i = mark + 1, #log do if log[i]:find(text, 1, true) then return true end end
            return false
        end

        Clear()
        -- ---- a click where there is something to go to: a run in exactly this zone
        -- copper in Mulgore (where you stand) and more of it in the Barrens next door
        W.Set({ Ore(VEIN, "Copper Vein", 100), Ore(VEIN, "Copper Vein", 200) })
        ns.db.nodes[BARRENS] = {}
        for i = 1, 12 do ns.db.nodes[BARRENS][i] = { id = VEIN, name = "Copper Vein", type = "ore", x = 0.2 + i * 0.01, y = 0.5, count = 1, last = 1 } end
        ns.NotifyNodesChanged() advance(1)
        W.At(0)
        Plan({ [COPPER] = { 60, 0 } })
        assert(ns.PlanFarmStart("Mining", 75) == true, "no run where there is copper")
        W.Wait(1)
        local run = ns.run
        assert(run and run.plan and run.zone == 1412 and run.filter == F and not run.quick and not run.groupZones and not run.groupDone, "the run is not a run in the zone you stand in")
        assert(#run.points == 2, "the route has " .. #run.points .. " nodes, want the 2 of this zone (12 more are next door)")
        for _, p in ipairs(run.points) do assert(p.mapID == 1412, "a node of another zone in the route: " .. tostring(p.mapID)) end
        assert(not Open() and hereCalls == 0, "the list opened, or the run went through the search for a zone")
        -- 1 node is enough (not the 8 a run where you are asks for)
        Clear()
        W.Set({ Ore(VEIN, "Copper Vein", 100) }) W.At(0)
        assert(ns.PlanFarmStart("Mining", 75) and ns.run.zone == 1412 and #ns.run.points == 1, "one node to go to is not enough for a run")
        -- a capital counts as its zone
        Clear()
        player.map = CITY
        assert(ns.PlanFarmStart("Mining", 75) and ns.run.zone == 1412, "from the capital: " .. tostring(ns.run and ns.run.zone))
        Clear()
        W.At(0)

        -- ---- a click with nothing to go to here: no run, no other zone - the list opens
        W.Set({}) W.At(0)
        mark = #log
        hereCalls = 0
        assert(ns.PlanFarmStart("Mining", 75) == false, "a run without a node in this zone")
        W.Wait(1)
        assert(ns.run == nil and ns.db.activeRun == nil and hereCalls == 0, "a run started somewhere else (the search of a run where you are?)")
        assert(Open() and Said(L["not in this zone"]), "the list of zones did not open, or no word why")
        local z = ZoneRow(BARRENS)
        local names = {}
        for i, zz in ipairs(ListData().zones) do names[i] = zz.mapID .. ":" .. zz.candidates end
        assert(z and #ListData().zones == 1 and not z.here, "the list: " .. #ListData().zones .. " zones (" .. table.concat(names, " ") .. "), want the Barrens")
        -- the list starts nothing; a turn of the wheel and time work nothing out
        advance(20) -- (the known spots are counted: the list is worked out once more when they are)
        assert(not ListData().counting, "the list is still counting after 20 s")
        local b0 = Builds()
        Win().__scripts.OnMouseWheel(Win(), -1) Win().__scripts.OnMouseWheel(Win(), 1)
        fire("BAG_UPDATE_DELAYED") W.Wait(30)
        assert(ns.run == nil and Open(), "the list started a run by itself")
        assert(Builds() == b0, "the list was worked out again without a new plan: " .. (Builds() - b0) .. " time(s)")
        -- a new plan (revision): worked out once
        NewPlan({ [COPPER] = { 60, 0 }, [TIN] = { 10, 0 } })
        assert(Builds() == b0 + 1, "a new plan: the list was worked out " .. (Builds() - b0) .. " time(s), want 1")
        -- "Go": exactly this zone
        hereCalls = 0
        assert(ns.PlanZoneListGo(BARRENS) == true, "Go did not start the run")
        W.Wait(1)
        run = ns.run
        assert(run and run.plan and run.zone == BARRENS and ns.db.activeRun.zone == BARRENS and #run.points == 12 and hereCalls == 0 and not Open(), "Go: not a run in the zone clicked")
        for _, p in ipairs(run.points) do assert(p.mapID == BARRENS, "Go: a node of another zone") end
        -- in the run: what is left is only in another zone - blocked, the zone never changes, the window offers the list
        local _, ends0 = ns.PlanRunLastEnd()
        NewPlan({ [COPPER] = { 60, 60 }, [TIN] = { 10, 0 } })
        ns.db.nodes[1412] = { Ore(TINVEIN, "Tin Vein", 0), W.Node("o1618", "Peacebloom", 2500, { item = 2447 }) }
        ns.NotifyNodesChanged() advance(2)
        fire("BAG_UPDATE_DELAYED") W.Wait(2)
        local last, ends = ns.PlanRunLastEnd()
        assert(ns.run == nil and ends == ends0 + 1 and last.kind == "blocked" and last.zone == BARRENS and last.reasons[1].item == TIN and last.reasons[1].reason == "not_in_zone",
            "tin only in another zone: " .. tostring(last and last.kind))
        local hint = _G.GathercraftPlanHint
        assert(hint and hint:IsShown() and not Open(), "the blocked end: no window, or the list opened by itself")
        hint.zones.__scripts.OnClick(hint.zones)
        assert(Open() and not hint:IsShown() and ns.run == nil, "the window's button does not open the list")
        z = ZoneRow(1412)
        assert(z and z.here and #ListData().zones == 1 and Places(z, TIN) ~= nil or ListData().counting, "the list after the blocked end: not Mulgore with tin")
        Clear()

        -- ---- the list: your continent only, places counted as the item tooltip counts them, most first, your zone marked
        ns.db.tooltipPrices = false
        if ns.ItemTooltipSetEnabled then ns.ItemTooltipSetEnabled(false) end
        assert(ns.SpawnCountsState() == "off", "test setup: the spawn counts are on although nobody uses them")
        -- Incendicite: two node kinds at the SAME place in the Wetlands (another continent), and in the Barrens
        local function Twin(mapID, x)
            return { id = INC[1], name = "Incendicite Mineral Vein", type = "ore", x = x, y = 0.5, count = 1, last = 1, source = "questie" },
                { id = INC[2], name = "Incendicite Mineral Vein", type = "ore", x = x, y = 0.5, count = 1, last = 1, source = "questie" }
        end
        local a1, a2 = Twin(WETLANDS, 0.3)
        ns.db.nodes[WETLANDS] = { a1, a2 }
        local b1, b2 = Twin(BARRENS, 0.6)
        -- (your own nodes there: the shipped spawn data has no Incendicite in the
        -- Barrens, so as "questie" nodes they would be 0 known places - and a
        -- material with 0 known places is not listed, 0.2 live test N3)
        b1.source, b2.source = nil, nil
        ns.db.nodes[BARRENS] = { b1, b2 }
        for i = 1, 3 do ns.db.nodes[BARRENS][#ns.db.nodes[BARRENS] + 1] = { id = VEIN, name = "Copper Vein", type = "ore", x = 0.2 + i * 0.01, y = 0.5, count = 1, last = 1 } end
        W.Set({ Ore(VEIN, "Copper Vein", 100), Ore(VEIN, "Copper Vein", 200), Ore(VEIN, "Copper Vein", 300), Ore(VEIN, "Copper Vein", 400), Ore(VEIN, "Copper Vein", 500) })
        W.At(0)
        Plan({ [COPPER] = { 60, 0 }, [INCEND] = { 5, 0 }, [2840] = { 8, 0 } })
        assert(ns.PlanZoneListShow("Mining", 75) and Open(), "the list did not open")
        assert(ns.run == nil, "opening the list started a run")
        advance(20) -- (the counts are built for the list's own user)
        assert(ns.SpawnCountsState() == "ready", "the list did not get the spawn counts without the tooltip option: " .. tostring(ns.SpawnCountsState()))
        local d = ListData()
        assert(d and d.state == "ok" and not d.counting, "the list is not counted: " .. tostring(d and d.state))
        assert(#d.zones == 2 and ZoneRow(1412) and ZoneRow(BARRENS) and not ZoneRow(WETLANDS), "the list has " .. #d.zones .. " zones, want Mulgore and the Barrens (the Wetlands are another continent)")
        -- places, not entries: counted here again from the spawn data and the own nodes
        local function CountPlaces(item, mapID)
            local seen, n = {}, 0
            for id, x, y in (data.zones[mapID] or ""):gmatch("(%d+),(%d+),(%d+)") do
                local kind = data.kinds["o" .. id]
                if kind and kind[2] == item and (kind[1] == "o" or kind[1] == "h") and not seen[x .. ":" .. y] then seen[x .. ":" .. y] = true n = n + 1 end
            end
            return n
        end
        local function Total(item, mapID)
            for _, zc in ipairs(ns.SpawnCounts(item) or {}) do if zc.mapID == mapID then return zc.total end end
            return 0
        end
        local zb, zm = ZoneRow(BARRENS), ZoneRow(1412)
        local incPlaces, incCandidates = Places(zb, INCEND)
        assert(incCandidates == 2, "test setup: the two Incendicite nodes of the Barrens are not both candidates")
        assert(incPlaces == Total(INCEND, BARRENS) and incPlaces >= CountPlaces(INCEND, BARRENS), "Incendicite in the Barrens: " .. tostring(incPlaces) .. " places, the counts say " .. Total(INCEND, BARRENS))
        assert(Places(zb, COPPER) == Total(COPPER, BARRENS) and Places(zm, COPPER) == Total(COPPER, 1412), "copper: not the number of known places")
        assert(Places(zb, 2840) == nil and Places(zm, INCEND) == nil, "a material without a node to go to in the zone is listed")
        assert(zb.places == Places(zb, INCEND) + Places(zb, COPPER) and zm.places == Places(zm, COPPER), "a zone's number is not the sum of its materials' places")
        for i = 2, #d.zones do assert(d.zones[i - 1].places >= d.zones[i].places, "the zones are not in order, most places first") end
        assert(zm.here and not zb.here, "your zone is not the one marked")
        -- (0.2 live test N3) the rows as they are drawn: your zone with the short
        -- mark "(here)" (the long one cut the materials off); as many materials as
        -- fit the line, the rest "+N more" - none cut off in the middle
        local function Plain(s) return ((s or ""):gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", "")) end
        local MARK_HERE = L["(here)"]
        local function RowOf(mapID)
            for _, r in ipairs(Win().rows) do if r:IsShown() and r.zone and r.zone.mapID == mapID then return r end end
        end
        local rm, rb = RowOf(1412), RowOf(BARRENS)
        assert(rm and rb, "test setup: the two rows are not shown")
        assert(Plain(rm.items:GetText()):sub(1, #MARK_HERE + 1) == MARK_HERE .. " " and not Plain(rm.items:GetText()):find(L["you are here"], 1, true),
            "your zone's row: " .. Plain(rm.items:GetText()))
        assert(not Plain(rb.items:GetText()):find(MARK_HERE, 1, true), "another zone with the mark: " .. Plain(rb.items:GetText()))
        local keepWidth, keepString = rb.items.GetWidth, rb.items.GetStringWidth
        rb.items.GetStringWidth = function(self) return #Plain(self:GetText()) * 6 end
        rb.items.GetWidth = function() return 60 end
        Close()
        assert(ns.PlanZoneListShow("Mining", 75)) advance(20)
        local narrow = Plain(rb.items:GetText())
        local shownItems = select(2, narrow:gsub(" · ", "")) + 1 - (narrow:find((L["+%d more"]):format(1), 1, true) and 1 or 0)
        assert(shownItems == 1 and narrow:find((L["+%d more"]):format(#zb.items - 1), 1, true), "a narrow row: " .. narrow)
        rb.items.GetWidth = function() return 400 end
        Close()
        assert(ns.PlanZoneListShow("Mining", 75)) advance(20)
        local wide = Plain(rb.items:GetText())
        assert(not wide:find((L["+%d more"]):format(1), 1, true) and select(2, wide:gsub(" · ", "")) == #zb.items - 1, "a wide row: " .. wide)
        rb.items.GetWidth, rb.items.GetStringWidth = keepWidth, keepString
        -- (0.2 live test N3) a material with no known place in a zone is not
        -- listed there ("Silverleaf 0"), and a zone with none of them not at all
        local counts = ns.SpawnCounts
        local drop = { [COPPER] = true }
        ns.SpawnCounts = function(item)
            local list = counts(item)
            if not (list and drop[item]) then return list end
            local out = {}
            for _, zc in ipairs(list) do if zc.mapID ~= BARRENS then out[#out + 1] = zc end end
            return out
        end
        Close()
        assert(ns.PlanZoneListShow("Mining", 75)) advance(20)
        local zb0 = ZoneRow(BARRENS)
        assert(zb0 and Places(zb0, COPPER) == nil and Places(zb0, INCEND) == Places(zb, INCEND), "a material with 0 known places is listed: " .. tostring(zb0 and Places(zb0, COPPER)))
        drop[INCEND] = true
        Close()
        assert(ns.PlanZoneListShow("Mining", 75)) advance(20)
        assert(ZoneRow(BARRENS) == nil and ZoneRow(1412), "a zone without one known place is listed")
        ns.SpawnCounts = counts
        Close()
        assert(ns.PlanZoneListShow("Mining", 75)) advance(20)
        d = ListData()
        zb, zm = ZoneRow(BARRENS), ZoneRow(1412)
        -- the same place under two node kinds is one place
        local twoKinds = CountPlaces(INCEND, WETLANDS)
        local entries = 0
        for id in (data.zones[WETLANDS] or ""):gmatch("(%d+),%d+,%d+") do
            local kind = data.kinds["o" .. id]
            if kind and kind[2] == INCEND then entries = entries + 1 end
        end
        assert(entries > twoKinds, "test setup: Incendicite in the Wetlands has no place under two kinds (" .. entries .. " entries, " .. twoKinds .. " places)")
        Close()
        assert(ns.SpawnCountsState() == "off", "the list closed and the spawn counts stay on")
        W.Set({}) player.map, player.x, player.y = WETLANDS, 0.3, 0.5
        Plan({ [INCEND] = { 5, 0 } })
        assert(ns.PlanZoneListShow("Mining", 75)) advance(20)
        d = ListData()
        local zw = ZoneRow(WETLANDS)
        assert(zw and #d.zones == 1 and zw.here, "in the Wetlands: " .. #d.zones .. " zones")
        local p, c = Places(zw, INCEND)
        assert(c == 2 and p == Total(INCEND, WETLANDS) and p == twoKinds and p < entries, ("Incendicite in the Wetlands: %s places (candidates %s) - want %d, not the %d entries"):format(tostring(p), tostring(c), twoKinds, entries))
        Close()
        W.At(0)

        -- ---- what the window shows: nothing, and every zone of the continent
        Plan({ [COPPER] = { 60, 0 } })
        ns.db.nodes[BARRENS], ns.db.nodes[WETLANDS] = nil, nil
        W.Set({})
        assert(ns.PlanZoneListShow("Mining", 75)) advance(1)
        local win = Win()
        assert(#ListData().zones == 0 and win.note:GetText() == L["No known spots for the missing materials yet."] and not win.rows[1]:IsShown(), "the empty list: " .. tostring(win.note:GetText()))
        assert(win.title:GetText() == L["Where to farm for your plan"] and win.sub:GetText() == L["Known spots for what you still need"], "the list's title")
        Close()
        local twenty = {}
        for mapID = 1400, 1470 do
            if mapID ~= 1412 and ns.GetContinent(mapID) == ns.GetContinent(1412) then twenty[#twenty + 1] = mapID end
        end
        assert(#twenty >= 12, "test setup: only " .. #twenty .. " other zones on the continent")
        local N = #twenty + 1 -- (with Mulgore: more zones than the window shows at once)
        for i, mapID in ipairs(twenty) do
            saved.extra[mapID] = saved.extra[mapID] or { nil }
            ns.db.nodes[mapID] = {}
            for k = 1, i do ns.db.nodes[mapID][k] = { id = VEIN, name = "Copper Vein", type = "ore", x = 0.2 + k * 0.01, y = 0.5, count = 1, last = 1 } end
        end
        W.Set({ Ore(VEIN, "Copper Vein", 100) }) W.At(0)
        assert(ns.PlanZoneListShow("Mining", 75)) advance(25)
        d = ListData()
        assert(#d.zones == N and not d.counting, "the list has " .. #d.zones .. " zones, want " .. N)
        local shown = 0
        for _, row in ipairs(win.rows) do if row:IsShown() then shown = shown + 1 end end
        assert(shown == 10 and win.rows[1].zone == d.zones[1] and win.note:GetText() == (L["Zones %d-%d of %d (mouse wheel)"]):format(1, 10, N), "many zones: " .. shown .. " rows, note " .. tostring(win.note:GetText()))
        for _ = 1, 30 do win.__scripts.OnMouseWheel(win, -1) end
        assert(win.rows[10].zone == d.zones[N] and win.rows[1].zone == d.zones[N - 9], "the wheel does not reach the last zone")
        for _ = 1, 30 do win.__scripts.OnMouseWheel(win, 1) end
        assert(win.rows[1].zone == d.zones[1], "the wheel does not come back to the first zone")
        -- every row: the zone's name, its materials with their places, a Go button that starts that zone
        local row = win.rows[1]
        assert(row.name:GetText():find(d.zones[1].name, 1, true) and row.items:GetText():find(ns.ItemName(COPPER) or "?", 1, true) and row.go:GetText() == L["Go"], "a row: " .. tostring(row.name:GetText()) .. " / " .. tostring(row.items:GetText()))
        row.go.__scripts.OnClick(row.go)
        W.Wait(1)
        assert(ns.run and ns.run.zone == d.zones[1].mapID and not Open(), "the Go button of the first row")
        Clear()
        -- no plan to go by, a plan on its way: said, no zones
        given = "skill"
        assert(ns.PlanZoneListShow("Mining", 75)) advance(1)
        assert(#ListData().zones == 0 and win.note:GetText() == (L["No plan to go by: %s."]):format(L["your skill can't be read"]), "the list without a plan: " .. tostring(win.note:GetText()))
        Close()
        given = "working"
        assert(ns.PlanZoneListShow("Mining", 75)) advance(1)
        assert(win.note:GetText() == L["Working out the plan ..."], "the list while the plan is worked out: " .. tostring(win.note:GetText()))
        Plan({ [COPPER] = { 60, 0 } })
        ns.PlanRunLook() advance(1)
        assert(#ListData().zones == N, "the list did not take the plan when it was there")
        Close()
        -- asked for something that is no plan
        assert(ns.PlanZoneListShow("Bergbau", 75) == false and ns.PlanFarmStart("Bergbau", 75) == false and not Open() and ns.run == nil, "a list or a run for something that is no plan")
        assert(#errors == before, "an error: " .. tostring(errors[#errors]))
    end)
    ns.SkillPlanFor, ns.GetSkill, ns.StartHereRun, ns.PlanRouteCandidates, ns.SpawnCounts = saved.planFor, saved.skill, saved.here, saved.candidates, saved.counts
    if ns.run then ns.StopRun(true) end
    for _, name in ipairs({ "GathercraftPlanZones", "GathercraftPlanHint" }) do if _G[name] then _G[name]:Hide() end end
    for mapID, keep in pairs(saved.extra) do ns.db.nodes[mapID] = keep[1] end
    ns.db.nodes[BARRENS], ns.db.nodes[WETLANDS], ns.db.activeRun, ns.db.tooltipPrices = saved.barrens, saved.wetlands, saved.run, saved.tooltip
    ns.db.spawnZones = saved.spawnZones
    W.Restore()
    if ns.ItemTooltipSetEnabled then ns.ItemTooltipSetEnabled(saved.tooltip ~= false) end
    advance(15)
    if not ok then error(err, 0) end
end)
step("Farm for plan: the plan's nodes glow and the rest steps back - a factor worked out at the pin every time, gone with the run (v0.2 B3 T4)", function()
    -- Concept shopping list 4.9, tests 11 and 16; Sven E2, E7; the order's
    -- extra test (pins that come and go while the run goes).
    assert(type(ns.PlanGlowFor) == "function" and type(ns.PlanPinsChanged) == "function" and type(ns.PinHiddenGrey) == "function",
        "no ns.PlanGlowFor / PlanPinsChanged / PinHiddenGrey")
    local data = GathercraftQuestieData
    local COPPER, TIN, STONE, VEIN = 2770, 2771, 2835, "o1731"
    local TINVEIN
    for key, kind in pairs(data.kinds) do
        if kind[1] == "o" and kind[2] == TIN and (not TINVEIN or key < TINVEIN) then TINVEIN = key end
    end
    local Z = 1412
    local saved = { planFor = ns.SkillPlanFor, skill = ns.GetSkill, loot = ns.db.kindLoot, grey = ns.db.hideGreyNodes, world = ns.db.worldPinsHidden, mini = ns.db.miniPinsHidden,
        alpha = ns.db.miniPinAlpha, run = ns.db.activeRun, glow = ns.PlanGlowFor, base = ns.PlanBaseKinds, seen = ns.PlanSeen, herb = PROFS[1][2], ore = PROFS[2][2], oreMax = PROFS[2][3] }
    local W = IdentityWorld()
    local hbd = LibStub("HereBeDragons-Pins-2.0")
    local addWorld, addMini = hbd.AddWorldMapIconMap, hbd.AddMinimapIconMap
    local worldPin, miniPin = {}, {}
    hbd.AddWorldMapIconMap = function(self, ref, frame, mapID, ...)
        if ref == "Gathercraft" and mapID == Z and frame.node then worldPin[frame.node] = frame end
        return addWorld(self, ref, frame, mapID, ...)
    end
    hbd.AddMinimapIconMap = function(self, ref, frame, mapID, ...)
        if ref == "Gathercraft" and mapID == Z and frame.node then miniPin[frame.node] = frame end
        return addMini(self, ref, frame, mapID, ...)
    end
    local before = #errors
    local ok, err = pcall(function()
        PROFS[2][2], PROFS[2][3] = 70, 300 -- Mining 70: copper and tin can be gathered, nothing is grey
        ns.GetSkill = saved.skill
        ns.db.hideGreyNodes, ns.db.worldPinsHidden, ns.db.miniPinsHidden, ns.db.miniPinAlpha = false, false, false, 1
        local given
        ns.SkillPlanFor = function() if type(given) == "table" then return given end return nil, given end
        local revision = 500
        local function Plan(items)
            revision = revision + 1
            local res = { prof = "Mining", from = 1, target = 75, status = "ok", valid = true, complete = true, reliable = true, revision = revision, items = {} }
            for id, m in pairs(items) do res.items[id] = { need = m[1], have = m[2], haveKnown = m[2] ~= nil, missing = math.max(0, m[1] - (m[2] or 0)) } end
            given = res
        end
        local function Look() fire("BAG_UPDATE_DELAYED") W.Wait(1) end
        local F = ns.PlanFilter("Mining", 75)
        -- the nodes: two copper veins of your own, a tin vein, a herb, a known spot two kinds share
        -- (copper and tin from the spawn data at one place), a herb on cooldown
        local function N(id, name, x, kind, extra)
            local n = W.Node(id, name, x, { type = kind })
            for k, v in pairs(extra or {}) do n[k] = v end
            return n
        end
        local copper1, copper2 = N(VEIN, "Copper Vein", 100, "ore"), N(VEIN, "Copper Vein", 200, "ore")
        local tin = N(TINVEIN, "Tin Vein", 300, "ore")
        local herb = N("o1618", "Peacebloom", 400, "herb")
        local cold = N("o1617", "Silverleaf", 500, "herb", { emptyUntil = time() + 600 })
        local sharedC = N(VEIN, "Copper Vein", 600, "ore", { source = "questie" })
        local sharedT = N(TINVEIN, "Tin Vein", 600, "ore", { source = "questie" })
        -- (since 0.1.23 a minimap pin exists only for a node within 400 yd of
        -- you: you stand among the nodes, the farthest is 350 yd away)
        local function Set(list)
            for k in pairs(worldPin) do worldPin[k] = nil end
            for k in pairs(miniPin) do miniPin[k] = nil end
            W.Set(list)
            W.At(250)
            advance(4)
        end
        local ALL = { copper1, copper2, tin, herb, cold, sharedC, sharedT }
        Set({ copper1, copper2, tin, herb, cold, sharedC, sharedT })
        local function Pins()
            local list = {}
            for node, pin in pairs(worldPin) do if pin.node == node then list[#list + 1] = pin end end
            for node, pin in pairs(miniPin) do if pin.node == node then list[#list + 1] = pin end end
            return list
        end
        local function Alphas()
            local t = {}
            for _, pin in ipairs(Pins()) do t[pin] = pin:GetAlpha() end
            return t
        end
        local function Ring(pin) local c = pin.ring.__color or { 1, 1, 1 } return ("%s %.2f %.2f %.2f"):format(pin.ring.__tex or "?", c[1], c[2], c[3]) end
        local function Rings()
            local t = {}
            for _, pin in ipairs(Pins()) do t[pin] = Ring(pin) end
            return t
        end
        local function Same(a, b, what)
            for pin, v in pairs(a) do
                if pin.node and b[pin] ~= nil then
                    local same = type(v) == "number" and math.abs(v - b[pin]) < 1e-6 or v == b[pin]
                    assert(same, ("%s: the pin of %s (%s) is %s, was %s"):format(what, tostring(pin.node.name), pin.isMini and "minimap" or "world map", tostring(b[pin]), tostring(v)))
                end
            end
        end
        local shared = worldPin[sharedC] or worldPin[sharedT]
        assert(worldPin[copper1] and worldPin[tin] and worldPin[herb] and shared and miniPin[copper1], "test setup: the pins are not there")
        assert(shared.others and #shared.others == 1, "test setup: the known copper and tin at one place are not one pin")
        local alpha0, ring0 = Alphas(), Rings()
        assert(#Pins() >= 10, "test setup: only " .. #Pins() .. " pins")
        assert(ns.PlanGlowFor(copper1) == nil, "a glow without a plan run")

        -- ---- the run: copper is the plan's material
        local GOLD = "1.00 0.82 0.10"
        Plan({ [COPPER] = { 60, 0 } })
        ns.StartRun(F, Z) W.Wait(1)
        assert(ns.run and ns.run.plan, "test setup: no plan run")
        local target = ns.run.target
        local function Check(what, glows, weak)
            local n = 0
            for _, pin in ipairs(Pins()) do
                local node, a0 = pin.node, alpha0[pin]
                if a0 then
                    local want
                    if node == ns.run.target or node == target then
                        want = 0 -- the run's target: its normal pins step aside for the target pin
                    elseif glows[node] or (pin.others and glows[pin.others[1]]) then
                        want = a0
                        assert(not pin.ring:IsShown() or Ring(pin):find(GOLD, 1, true), what .. ": the ring of a plan node (" .. node.name .. ") is not gold: " .. Ring(pin))
                    elseif weak and weak[node.id] then
                        want = a0 * 0.65
                    else
                        want = a0 * 0.35
                        assert(Ring(pin) == ring0[pin], what .. ": the ring of a node that is not of the plan changed (" .. node.name .. ", x " .. tostring(node.x) .. ", " .. (pin.isMini and "minimap" or "world map") .. "): " .. Ring(pin) .. ", was " .. tostring(ring0[pin]))
                    end
                    assert(math.abs(pin:GetAlpha() - want) < 1e-6, ("%s: %s (%s) has alpha %.3f, want %.3f (%.3f before the run)"):format(what, node.name, pin.isMini and "minimap" or "world map", pin:GetAlpha(), want, a0))
                    n = n + 1
                end
            end
            assert(n >= 10, what .. ": only " .. n .. " pins checked")
        end
        -- (the shared spot glows through its copper, whichever of the two kinds the pin shows)
        Check("copper", { [copper1] = true, [copper2] = true, [sharedC] = true, [sharedT] = true })
        assert(ns.PlanGlowFor(copper1) == 1 and ns.PlanGlowFor(tin) == 0 and ns.PlanGlowFor(herb) == 0, "the glow of single nodes")
        -- nothing of it is kept at a pin
        for _, pin in ipairs(Pins()) do
            for k in pairs(pin) do
                assert(not tostring(k):lower():find("plan") and not tostring(k):lower():find("glow"), "something of the plan is kept at a pin: " .. tostring(k))
            end
        end
        -- the plan needs tin instead: the glow moves, at once
        Plan({ [COPPER] = { 60, 60 }, [TIN] = { 10, 0 } })
        Look()
        target = ns.run.target
        Check("tin", { [tin] = true, [sharedC] = true, [sharedT] = true })
        -- a shared spot where only the SECOND kind is the plan's: it glows all the same
        local primary = shared.node
        assert((primary == sharedC and shared.others[1] == sharedT) or (primary == sharedT and shared.others[1] == sharedC), "test setup: the shared pin")
        Plan({ [COPPER] = { 60, primary == sharedC and 60 or 0 }, [TIN] = { 10, primary == sharedT and 10 or 0 } })
        Look()
        target = ns.run.target
        assert(ns.PlanGlowFor(primary) == 0 and ns.PlanGlowFor(shared.others[1]) == 1, "test setup: only the second kind of the spot is wanted")
        if shared.node ~= target and shared.others[1] ~= target then
            assert(math.abs(shared:GetAlpha() - alpha0[shared]) < 1e-6, "a shared spot whose second kind is the plan's is dimmed: " .. shared:GetAlpha())
        end

        -- ---- seen: a kind a wanted material without a base was found at glows weaker and is no target
        ns.PlanSeen = function(item) if item == STONE then return { { id = "o1618", seen = 7, n = 23 } } end return saved.seen(item) end
        Plan({ [COPPER] = { 60, 0 }, [STONE] = { 20, 0 } })
        Look()
        target = ns.run.target
        Check("seen", { [copper1] = true, [copper2] = true, [sharedC] = true, [sharedT] = true }, { o1618 = true }) -- (every Peacebloom: the kind was seen, not one node)
        assert(ns.PlanGlowFor(herb) == 2, "the glow of a kind a material was seen at: " .. tostring(ns.PlanGlowFor(herb)))
        for _, p in ipairs(ns.run.points) do assert(p.node ~= herb, "a node that was only seen is in the route") end
        -- the stone is there now: the weaker glow goes - the pins are told at once (not with their next round)
        local told, keepTold = 0, ns.PlanPinsChanged
        ns.PlanPinsChanged = function(...) told = told + 1 return keepTold(...) end
        Plan({ [COPPER] = { 60, 0 }, [STONE] = { 20, 20 } })
        Look()
        ns.PlanPinsChanged = keepTold
        assert(told == 1, "what was seen changed and the pins were told " .. told .. " time(s), want 1")
        target = ns.run.target
        Check("seen, covered", { [copper1] = true, [copper2] = true, [sharedC] = true, [sharedT] = true })
        ns.PlanSeen = saved.seen

        -- ---- pins that come and go while the run goes: the right factor at once, nothing left behind
        local late = N(TINVEIN, "Tin Vein", 700, "ore")
        local lateCopper = N(VEIN, "Copper Vein", 800, "ore")
        table.insert(ns.db.nodes[Z], late)
        table.insert(ns.db.nodes[Z], lateCopper)
        ns.NotifyNodesChanged("add", Z, late) ns.NotifyNodesChanged("add", Z, lateCopper)
        advance(4)
        assert(worldPin[late] and worldPin[late].node == late and worldPin[lateCopper], "test setup: no pins for the nodes that came")
        local plain = worldPin[copper1]:GetAlpha() -- (an own node, not on cooldown, of the plan: as without a run)
        if lateCopper ~= ns.run.target then
            assert(math.abs(worldPin[lateCopper]:GetAlpha() - 1) < 1e-6 and Ring(worldPin[lateCopper]):find(GOLD, 1, true), "a plan node that came during the run does not glow: " .. worldPin[lateCopper]:GetAlpha())
        end
        assert(math.abs(worldPin[late]:GetAlpha() - 0.35) < 1e-6, "a node that came during the run and is not of the plan: alpha " .. worldPin[late]:GetAlpha() .. ", want 0.35")
        -- the pin of a node that went is used again for another node: no old factor on it
        local usedPin = worldPin[late]
        for i = #ns.db.nodes[Z], 1, -1 do if ns.db.nodes[Z][i] == late then table.remove(ns.db.nodes[Z], i) end end
        ns.NotifyNodesChanged() advance(4)
        local reused
        for node, pin in pairs(worldPin) do if pin == usedPin and pin.node == node and node ~= late then reused = node end end
        local now = Alphas()
        for _, pin in ipairs(Pins()) do
            local node = pin.node
            if node ~= ns.run.target and node.id == VEIN and not node.source and not pin.others then
                assert(math.abs(pin:GetAlpha() - (pin.isMini and 1 or 1)) < 1e-6, "after the pins were built anew a copper vein is dimmed: " .. pin:GetAlpha())
            end
        end
        ns.StopRun(true)
        advance(1)

        -- ---- the minimap pins of 0.1.23 come and go as you walk (only within 400 yd):
        -- a pin made or taken away during the run has the factor of now, nothing stays
        Set({ copper1, copper2, tin, herb })
        Plan({ [COPPER] = { 60, 0 } })
        ns.StartRun(F, Z) W.Wait(1)
        assert(ns.run and ns.run.plan, "test setup: no plan run")
        local function Mini(n) local pin = miniPin[n] return pin and pin.node == n and pin or nil end
        local function Shown(n)
            local pin = Mini(n)
            return pin and pin.__registered ~= false and pin or nil
        end
        assert(Mini(copper1) and Mini(tin), "test setup: no minimap pins near you")
        -- walk away: their minimap pins go
        for k in pairs(miniPin) do miniPin[k] = nil end
        local hbdKeepRem = hbd.RemoveMinimapIcon
        local removed = {}
        hbd.RemoveMinimapIcon = function(self, ref, icon, ...)
            if ref == "Gathercraft" and icon.node then removed[icon.node] = icon end
            return hbdKeepRem(self, ref, icon, ...)
        end
        W.At(1500) advance(4)
        assert(removed[copper1] and removed[tin], "test setup: the minimap pins did not go when you walked 1,250 yd away")
        -- the plan changes while you are away: now tin is wanted, copper is not
        Plan({ [COPPER] = { 60, 60 }, [TIN] = { 10, 0 } })
        fire("BAG_UPDATE_DELAYED") W.Wait(1)
        -- back: new minimap pins (from the pool: maybe the very frames that went) - with the factor of NOW
        W.At(250) advance(4)
        hbd.RemoveMinimapIcon = hbdKeepRem
        local mc, mt, mh = Mini(copper1), Mini(tin), Mini(herb)
        assert(mc and mt and mh, "the minimap pins did not come back when you came back")
        local miniAlpha = ns.db.miniPinAlpha or 1
        if tin ~= ns.run.target then
            assert(math.abs(mt:GetAlpha() - miniAlpha) < 1e-6, "a minimap pin made during the run for the plan's tin is dimmed: " .. mt:GetAlpha())
        end
        if copper1 ~= ns.run.target then
            assert(math.abs(mc:GetAlpha() - 0.35 * miniAlpha) < 1e-6, "a minimap pin made during the run for copper (no longer wanted) has alpha " .. mc:GetAlpha() .. ", want 0.35")
        end
        assert(math.abs(mh:GetAlpha() - 0.35 * miniAlpha) < 1e-6, "a minimap pin made during the run for a herb has alpha " .. mh:GetAlpha() .. ", want 0.35")
        -- and nothing of it is at the new pins
        for _, pin in ipairs({ mc, mt, mh }) do
            for k in pairs(pin) do
                assert(not tostring(k):lower():find("plan") and not tostring(k):lower():find("glow"), "something of the plan is kept at a new minimap pin: " .. tostring(k))
            end
        end
        -- the run ends: the same frames have their alpha without a factor at once
        ns.StopRun(true) advance(1)
        assert(math.abs(mh:GetAlpha() - miniAlpha) < 1e-6 and (Mini(tin) == mt and math.abs(mt:GetAlpha() - miniAlpha) < 1e-6), "after the run a minimap pin made during it keeps a factor")
        -- walk away and back once more without a run: no factor on any pin that comes
        W.At(1500) advance(4)
        W.At(250) advance(4)
        for _, n in ipairs({ copper1, tin, herb }) do
            local pin = Mini(n)
            assert(pin and math.abs(pin:GetAlpha() - miniAlpha) < 1e-6, "without a run a minimap pin that came has alpha " .. tostring(pin and pin:GetAlpha()) .. " (" .. n.name .. ")")
        end

        -- ---- gone with the run, however it ends: every pin as before
        for k in pairs(worldPin) do worldPin[k] = nil end
        for k in pairs(miniPin) do miniPin[k] = nil end
        Set({ copper1, copper2, tin, herb, cold, sharedC, sharedT })
        alpha0, ring0 = Alphas(), Rings()
        local function Dimmed()
            for _, pin in ipairs(Pins()) do
                if pin.node == tin and math.abs(pin:GetAlpha() - (alpha0[pin] or 1) * 0.35) < 1e-6 then return true end
            end
            return false
        end
        local function Started(what)
            Plan({ [COPPER] = { 60, 0 } })
            ns.StartRun(F, Z) W.Wait(1)
            assert(ns.run and ns.run.plan and Dimmed(), what .. ": test setup, the run does not dim")
        end
        local function Clean(what)
            assert(ns.PlanGlowFor(copper1) == nil, what .. ": a glow is left")
            Same(alpha0, Alphas(), what)
            Same(ring0, Rings(), what)
        end
        Started("stop") ns.StopRun() Clean("after a stop by the player")
        if _G.GathercraftRunSummary then _G.GathercraftRunSummary:Hide() end
        Started("success") Plan({ [COPPER] = { 60, 60 } }) Look() assert(ns.run == nil, "test setup: no end") Clean("after the end with everything gathered")
        Started("blocked") PROFS[2][2] = 1 Plan({ [COPPER] = { 60, 60 }, [TIN] = { 10, 0 } }) W.Wait(40) Look()
        assert(ns.run == nil and (ns.PlanRunLastEnd()).kind == "blocked", "test setup: no blocked end")
        PROFS[2][2] = 70 advance(4)
        if _G.GathercraftPlanHint then _G.GathercraftPlanHint:Hide() end
        Clean("after a blocked end")
        Started("new run") ns.StartRun("herb", Z) W.Wait(1)
        assert(ns.run and not ns.run.plan and ns.PlanGlowFor(copper1) == nil, "another run started and the plan's glow stays")
        for _, pin in ipairs(Pins()) do
            if pin.node == tin and alpha0[pin] then assert(math.abs(pin:GetAlpha() - alpha0[pin]) < 1e-6, "another run started: the tin vein is still dimmed") end
        end
        ns.StopRun(true) advance(1)
        Clean("after another run")
        -- a reload: the pins are built anew, the saved run is taken up - the glow is there, and gone with its end
        Started("reload")
        local keep = { filter = ns.db.activeRun.filter, zone = ns.db.activeRun.zone }
        ns.StopRun(true)
        ns.NotifyNodesChanged() advance(4)
        alpha0, ring0 = Alphas(), Rings()
        ns.db.activeRun = keep
        assert(ns.PlanRunResume(keep), "test setup: the run was not taken up")
        W.Wait(1)
        assert(Dimmed(), "after the reload the run does not dim")
        ns.StopRun(true)
        Clean("after the run taken up again was stopped")
        -- a change of zone: the minimap pins are another zone's - no factor without a run, the factor with one
        Started("zone")
        player.map = 1413 fire("ZONE_CHANGED_NEW_AREA") advance(4)
        player.map = Z fire("ZONE_CHANGED_NEW_AREA") W.At(250) advance(4)
        assert(Dimmed(), "after a change of zone and back the run does not dim")
        ns.StopRun(true) advance(4)
        for _, pin in ipairs(Pins()) do
            if pin.node == tin or pin.node == herb then assert(pin:GetAlpha() > 0.36, "after a change of zone and a stop a pin is still dimmed: " .. pin.node.name .. " " .. pin:GetAlpha()) end
        end

        -- ---- the run's target and what is switched off stay as they are
        Set({ copper1, copper2, tin, herb, cold, sharedC, sharedT })
        Started("target")
        local t = ns.run.target
        assert(t and worldPin[t] and worldPin[t]:GetAlpha() == 0, "the normal pin of the run's target is not hidden under the target pin")
        ns.StopRun(true)
        -- "Hide grey nodes": a grey node of the plan stays off the map, and the run says how many
        PROFS[2][2], PROFS[2][3] = 200, 300 -- copper is grey with Mining 200
        ns.db.hideGreyNodes = true
        Set({ copper1, copper2, tin, herb })
        assert(not worldPin[copper1] and ns.PinHiddenGrey(copper1) and not ns.PinHiddenGrey(herb), "test setup: the grey copper veins are not hidden")
        Plan({ [COPPER] = { 60, 0 } })
        ns.StartRun(F, Z) W.Wait(1)
        local s = ns.PlanRunState()
        assert(s and s.hidden == 2, "plan nodes hidden: " .. tostring(s and s.hidden) .. ", want 2")
        ns.NotifyNodesChanged() advance(6) -- (the pins are built anew during the run)
        assert(not (worldPin[copper1] and worldPin[copper1].node == copper1), "the plan run put a hidden grey node on the map")
        assert(ns.db.hideGreyNodes == true, "the plan run changed the option")
        ns.StopRun(true)
        ns.db.hideGreyNodes = false
        PROFS[2][2] = 70
        -- pins switched off: the plan run switches nothing on
        ns.db.worldPinsHidden, ns.db.miniPinsHidden = true, true
        Set({ copper1, copper2, tin, herb })
        assert(not worldPin[copper1] and not miniPin[copper1], "test setup: pins although they are off")
        Plan({ [COPPER] = { 60, 0 } })
        ns.StartRun(F, Z) W.Wait(4)
        assert(not worldPin[copper1] and not miniPin[copper1] and ns.db.worldPinsHidden == true and ns.db.miniPinsHidden == true, "the plan run switched pins on")
        ns.StopRun(true)
        ns.db.worldPinsHidden, ns.db.miniPinsHidden = false, false

        -- ---- load (test 11): a round over every pin with the factor; the sets behind it are not built per pin
        local many = {}
        for i = 1, 1500 do
            many[i] = { id = (i % 3 == 0) and TINVEIN or (i % 3 == 1) and VEIN or "o1618", name = "Node", type = (i % 3 == 2) and "herb" or "ore",
                x = 0.05 + (i % 50) * 0.018, y = 0.05 + math.floor(i / 50) * 0.03, count = 1, last = 1 }
        end
        Set(many)
        local function Round(n)
            local t0 = debugprofilestop()
            for _ = 1, n do ns.PlanPinsChanged() end
            return (debugprofilestop() - t0) / n
        end
        local function Median(list)
            local s = {}
            for i, v in ipairs(list) do s[i] = v end
            table.sort(s)
            return s[(#s + 1) / 2]
        end
        Plan({ [COPPER] = { 60, 0 }, [STONE] = { 20, 0 } })
        ns.StartRun(F, Z) W.Wait(1)
        local builds = 0
        ns.PlanBaseKinds = function(...) builds = builds + 1 return saved.base(...) end
        ns.PlanSeen = function(...) builds = builds + 1 return saved.seen(...) end
        -- the same pins by turns without the factor (what the pins are asked
        -- says "no plan run") and with it, nine times each: the medians are
        -- compared. Never one after the other, never again until it fits.
        -- (Nine, not five: next to other work a round is now and then held
        -- up for 40 ms - seen 16.11.2026 with 20 test runs at once.)
        local glowFor = ns.PlanGlowFor
        local function NoRun() return nil end
        Round(3)
        local offs, ons = {}, {}
        for i = 1, 9 do
            collectgarbage("collect")
            ns.PlanGlowFor = NoRun
            offs[i] = Round(5)
            collectgarbage("collect")
            ns.PlanGlowFor = glowFor
            ons[i] = Round(5)
        end
        local without, with = Median(offs), Median(ons)
        assert(builds == 0, "the plan's sets were asked for " .. builds .. " time(s) while the pins were drawn - built per pin?")
        ns.PlanBaseKinds, ns.PlanSeen = saved.base, saved.seen
        local pinCount = 0
        for _ in pairs(worldPin) do pinCount = pinCount + 1 end
        note(("MEASURE T4 a round over %d world pins (and the minimap's), 9 by turns each way: without the factor %s ms | with it %s ms; medians %.2f and %.2f ms"):format(
            pinCount, table.concat((function() local s = {} for i, v in ipairs(offs) do s[i] = ("%.1f"):format(v) end return s end)(), " "),
            table.concat((function() local s = {} for i, v in ipairs(ons) do s[i] = ("%.1f"):format(v) end return s end)(), " "), without, with))
        assert(pinCount >= 1400, "test setup: only " .. pinCount .. " pins")
        assert(with <= without * 3 + 2, ("a round over the pins with a plan run takes %.2f ms, without %.2f ms"):format(with, without))
        ns.StopRun(true)
        assert(#errors == before, "an error: " .. tostring(errors[#errors]))
    end)
    hbd.AddWorldMapIconMap, hbd.AddMinimapIconMap = addWorld, addMini
    ns.SkillPlanFor, ns.GetSkill, ns.PlanGlowFor, ns.PlanBaseKinds, ns.PlanSeen = saved.planFor, saved.skill, saved.glow, saved.base, saved.seen
    if ns.run then ns.StopRun(true) end
    for _, name in ipairs({ "GathercraftPlanZones", "GathercraftPlanHint", "GathercraftRunSummary" }) do if _G[name] then _G[name]:Hide() end end
    PROFS[1][2], PROFS[2][2], PROFS[2][3] = saved.herb, saved.ore, saved.oreMax
    ns.db.kindLoot, ns.db.hideGreyNodes, ns.db.worldPinsHidden, ns.db.miniPinsHidden, ns.db.miniPinAlpha, ns.db.activeRun = saved.loot, saved.grey, saved.world, saved.mini, saved.alpha, saved.run
    player.map = Z
    W.Restore()
    advance(5)
    if not ok then error(err, 0) end
end)
step("Farm for plan: what you see - have / need under the run window, the window when everything is gathered, the buttons in the skill plan (v0.2 B3 T5)", function()
    -- Concept shopping list 3, 4.3, 4.8, tests 2, 4, 10, 12; Sven E8, V6.
    assert(type(ns.PlanPanelLines) == "function" and type(ns.PlanPanelUpdate) == "function" and type(ns.PlanRunGathered) == "function"
        and type(ns.PlanButtonInfo) == "function" and type(ns.PlanButtonTooltip) == "function" and type(ns.PlanRunLabel) == "function",
        "no ns.PlanPanelLines / PlanPanelUpdate / PlanRunGathered / PlanButtonInfo / PlanButtonTooltip / PlanRunLabel")
    local L, d = ns.L, ns.CraftData
    local COPPER, TIN, SILVER, STONE, COAL, VEIN = 2770, 2771, 2775, 2835, 3857, "o1731"
    local TINVEIN
    for key, kind in pairs(GathercraftQuestieData.kinds) do
        if kind[1] == "o" and kind[2] == TIN and (not TINVEIN or key < TINVEIN) then TINVEIN = key end
    end
    local Z = 1412
    local saved = { planFor = ns.SkillPlanFor, skill = ns.GetSkill, seen = ns.PlanSeen, show = ns.ShowSkillPlan, compact = ns.db.panelCompact, hidden = ns.db.runPanelHidden,
        run = ns.db.activeRun, rank = ns.ProfessionRank, have = d.Have, known = d.Known, targets = ns.db.planTargets, farm = ns.PlanFarmStart, zones = ns.PlanZoneListShow,
        summaryOff = ns.db.summaryOff, grey = ns.db.hideGreyNodes }
    local W = IdentityWorld()
    local before = #errors
    local panel = _G.GathercraftPanel
    local ok, err = pcall(function()
        ns.GetSkill = function(t) if t == "ore" then return 100, 300, 100 end end
        ns.db.panelCompact, ns.db.runPanelHidden, ns.db.hideGreyNodes = nil, nil, false
        local given
        ns.SkillPlanFor = function() if type(given) == "table" then return given end return nil, given end
        local revision = 700
        local function Plan(items, more)
            revision = revision + 1
            local res = { prof = "Mining", from = 1, target = 75, status = "ok", valid = true, complete = true, reliable = true, revision = revision, items = {} }
            for id, m in pairs(items) do res.items[id] = { need = m[1], have = m[2], haveKnown = m[2] ~= nil, missing = math.max(0, m[1] - (m[2] or 0)) } end
            for k, v in pairs(more or {}) do res[k] = v end
            given = res
        end
        local function Look() fire("BAG_UPDATE_DELAYED") W.Wait(1) end
        local F = ns.PlanFilter("Mining", 75)
        local function Ore(id, name, x) return W.Node(id, name, x, { type = "ore" }) end
        W.Set({ Ore(VEIN, "Copper Vein", 100), Ore(VEIN, "Copper Vein", 200), Ore(TINVEIN, "Tin Vein", 300) })
        W.At(0)
        local function Lines() return ns.PlanPanelLines() end
        local function Kind(data, kind)
            local list = {}
            for _, l in ipairs(data.lines) do if l.kind == kind then list[#list + 1] = l end end
            return list
        end
        local function Line(data, item)
            for _, l in ipairs(data.lines) do if l.item == item then return l end end
        end
        local function Rows() -- the rows the window shows now
            local list = {}
            local f = _G.GathercraftPlanPanel
            if f and f:IsShown() then
                for _, row in ipairs(f.rows) do if row:IsShown() then list[#list + 1] = row end end
            end
            return list
        end
        local function Update() advance(1.5) end -- (the run window draws itself a few times a second)
        assert(Lines() == nil, "lines of a plan run without one")
        assert(ns.PlanRunLabel(F) == (L["Plan: %s %d"]):format(d.ProfLabel("Mining"), 75) and ns.PlanRunLabel("item:2770") == nil and ns.PlanRunLabel("plan:v2:mining:75") == nil,
            "the label of a plan run: " .. tostring(ns.PlanRunLabel(F)))
        assert(ns.RunFilterLabel(F) == ns.PlanRunLabel(F) and ns.RunFilterLabel("item:2770") == (ns.ItemName(2770) or "item:2770"), "the run window's label")

        -- ---- have / need, the bar, the tick, "?" (test 2)
        ns.PlanSeen = function(item) if item == STONE then return { { id = VEIN, seen = 7, n = 23 } } end return nil end
        Plan({ [COPPER] = { 60, 32 }, [TIN] = { 10, nil }, [STONE] = { 20, 5 }, [COAL] = { 8, 8 }, [2840] = { 0, 0 } })
        ns.StartRun(F, Z) W.Wait(1) Update()
        assert(ns.run and ns.run.plan, "test setup: no plan run")
        local data = Lines()
        assert(data, "no lines: state " .. tostring(ns.PlanRunState()) .. ", run " .. tostring(ns.run) .. ", errors " .. tostring(errors[#errors]))
        local copper, tin, stone, coal = Line(data, COPPER), Line(data, TIN), Line(data, STONE), Line(data, COAL)
        assert(copper and copper.kind == "row" and copper.count == "32 / 60" and not copper.ok and not copper.unknown and math.abs(copper.bar - 32 / 60) < 1e-9, "copper: " .. tostring(copper and copper.count))
        assert(tin and tin.kind == "row" and tin.count == "? / 10" and tin.unknown and not tin.ok and tin.bar == 0 and tin.have == nil, "a count that is not known: " .. tostring(tin and tin.count))
        assert(stone and stone.kind == "off" and stone.count == "5 / 20" and stone.source == (L["seen in %d of %d recorded gathers"]):format(7, 23), "rough stone: " .. tostring(stone and stone.source))
        assert(coal and coal.kind == "off" and coal.ok and coal.source == nil, "coal (covered, never seen): " .. tostring(coal and coal.count))
        assert(Line(data, 2840) == nil, "a material the plan needs 0 of has a line")
        assert(#Kind(data, "head") == 1 and Kind(data, "head")[1].text == L["Not on the map"] and #Kind(data, "more") == 0 and #Kind(data, "note") == 0, "the head, more and note lines")
        -- (0.2 live test N2) a character that surely has no Mining: each open ore
        -- line says so, in a line of its own; the run goes on and shows the
        -- spots. Not known for sure (right after login): nothing is said.
        do
            local gp = ns.GatherProfessions
            ns.GatherProfessions = function() return true, false, true end
            fire("BAG_UPDATE_DELAYED") W.Wait(1) Update()
            local n2 = Lines()
            local c2 = Line(n2, COPPER)
            local sub
            for i, l in ipairs(n2.lines) do if l == c2 then sub = n2.lines[i + 1] end end
            assert(c2 and c2.reason == L["needs Mining"] and sub and sub.kind == "sub" and sub.text == L["needs Mining"], "copper without Mining: " .. tostring(c2 and c2.reason))
            assert(Line(n2, TIN).reason == L["needs Mining"], "tin without Mining: " .. tostring(Line(n2, TIN).reason))
            assert(ns.run and ns.run.plan, "the run ended because the character has no Mining")
            ns.GatherProfessions = function() return true, false, nil end
            fire("BAG_UPDATE_DELAYED") W.Wait(1) Update()
            assert(Line(Lines(), COPPER).reason ~= L["needs Mining"], "Mining not known for sure, and still \"needs Mining\"")
            ns.GatherProfessions = gp
            fire("BAG_UPDATE_DELAYED") W.Wait(1) Update()
        end
        assert(data.total == 2 and data.done == 0 and data.compact == (L["Plan %d/%d"]):format(0, 2), "the slim line: " .. tostring(data.compact))
        -- no chance, no amount, no promise in what is said about a seen item
        for _, word in ipairs({ "%%", "chance", "per hour", "guarant", "cheap" }) do
            assert(not stone.source:lower():find(word), "the seen line promises something: " .. stone.source)
        end
        -- the window: under the run window, one row a line
        local f = _G.GathercraftPlanPanel
        assert(f and f:IsShown() and panel:IsShown() and #Rows() == #data.lines, "the plan is not shown under the run window (" .. #Rows() .. " rows, " .. #data.lines .. " lines)")
        local row1 = Rows()[1]
        assert(row1.line.item == COPPER and row1.name:GetText() == ns.ItemName(COPPER) and row1.count:GetText() == "32 / 60" and row1.bar:IsShown(), "the first row: " .. tostring(row1.name:GetText()) .. " " .. tostring(row1.count:GetText()))
        assert(math.abs(row1.bar:GetWidth() - 60 * 32 / 60) < 0.01, "the bar of 32 / 60 is " .. tostring(row1.bar:GetWidth()) .. " wide, want 32 of 60")
        assert(panel.title:GetText():find(ns.PlanRunLabel(F), 1, true), "the run window's title does not name the plan: " .. tostring(panel.title:GetText()))
        -- exactly reached, and more than needed: a tick, the bar full
        -- (a material of the test with a node kind: 990501)
        local keepBase = ns.PlanBaseKinds
        ns.PlanBaseKinds = function(item) if item >= 990501 and item <= 990515 then return { VEIN } end return keepBase(item) end
        Plan({ [COPPER] = { 60, 60 }, [990501] = { 10, 25 }, [TIN] = { 10, 3 }, [SILVER] = { 5, 0 } })
        Look() Update()
        data = Lines()
        assert(data, "test setup: the run ended")
        copper = Line(data, COPPER)
        local over = Line(data, 990501)
        assert(copper.ok and copper.bar == 1 and over.ok and over.bar == 1 and over.count == "25 / 10", "reached or more: no tick or no full bar")
        assert(data.lines[1].item == TIN and data.lines[2].item == SILVER and not data.lines[1].ok and not data.lines[2].ok and data.lines[3].kind == "sub" and data.lines[4].ok, "what is still open does not come first")
        assert(Line(data, SILVER).reason == L["not in this zone"] and Line(data, TIN).reason == nil, "why silver has no node here: " .. tostring(Line(data, SILVER).reason))
        assert(data.done == 2 and data.total == 4 and data.compact == (L["Plan %d/%d"]):format(2, 4), "the slim line: " .. tostring(data.compact))
        local tick = false
        for _, row in ipairs(Rows()) do
            if row.line.item == COPPER then tick = row.count:GetText():find("ReadyCheck-Ready", 1, true) ~= nil end
            if row.line.item == SILVER then assert(not row.bar:IsShown(), "the row of silver has a bar although nothing of it is there") end
        end
        local under
        for i, row in ipairs(Rows()) do
            if row.line.item == SILVER then under = Rows()[i + 1] end
        end
        assert(under and under.line.kind == "sub" and under.name:GetText():find(L["not in this zone"], 1, true), "no line under silver that says why it has no node here")
        assert(tick, "a covered material has no tick in its row")
        -- what the plan makes itself is no count: only have and need are shown
        for _, l in ipairs(data.lines) do assert(l.kind ~= "row" or l.have == nil or l.count == (tostring(l.have) .. " / " .. l.need), "a count that is not have / need") end

        -- ---- the slim window: "Plan 2/3"; the run window hidden: nothing of it
        ns.db.panelCompact = true
        ns.PanelLayout() Update()
        assert(not f:IsShown() and panel.title:GetText() == data.compact, "the slim window: " .. tostring(panel.title:GetText()))
        ns.db.panelCompact = nil
        ns.PanelLayout() Update()
        assert(f:IsShown(), "back to the whole window: the plan is not there")
        ns.db.runPanelHidden = true
        Update()
        assert(not panel:IsShown() and not f:IsShown(), "\"Hide the run window\": the plan's rows are shown")
        ns.db.runPanelHidden = nil
        Update()

        -- ---- many materials: 6 rows, then "+N more" (Sven E8)
        local many = {}
        for i = 1, 14 do many[#many + 1] = 990500 + i end
        local items = { [COPPER] = { 60, 0 } } -- (copper keeps the run going: it has nodes here)
        for i, id in ipairs(many) do items[id] = { 10 * i, i } end
        Plan(items)
        Look() Update()
        data = Lines()
        assert(#Kind(data, "row") == 6 and #Kind(data, "more") == 1 and Kind(data, "more")[1].n == 9 and Kind(data, "more")[1].text == (L["+%d more"]):format(9), "15 materials: " .. #Kind(data, "row") .. " rows")
        assert(data.total == 15 and #Rows() == 6 + #Kind(data, "sub") + 1 and #Kind(data, "sub") == 5,
            "15 materials: " .. #Rows() .. " rows in the window, want 6, a line under the 5 that have no node here, and the \"more\" line")
        -- 6 of the map and some that are not: the cap holds for all together
        items = { [COPPER] = { 60, 0 } }
        for i = 1, 3 do items[many[i]] = { 10, 0 } end
        for i = 1, 5 do items[990600 + i] = { 10, 0 } end
        Plan(items)
        Look() Update()
        data = Lines()
        assert(#Kind(data, "row") == 4 and #Kind(data, "off") == 2 and #Kind(data, "head") == 1 and Kind(data, "more")[1].n == 3, "4 and 5 materials: " .. #Kind(data, "row") .. " + " .. #Kind(data, "off"))
        -- one material, nothing that is not on the map: no head
        Plan({ [COPPER] = { 60, 0 } })
        Look() Update()
        data = Lines()
        assert(#data.lines == 1 and data.lines[1].kind == "row", "one material: " .. #data.lines .. " lines")
        ns.PlanBaseKinds = keepBase

        -- ---- the plan is not known right now: the rows read last with "?", a line that says so
        Plan({ [COPPER] = { 60, 32 }, [TIN] = { 10, 4 } })
        Look() Update()
        given = "window"
        Look() Update()
        data = Lines()
        copper = Line(data, COPPER)
        assert(data.frozen and copper and copper.count == "? / 60" and copper.unknown and not copper.ok and copper.bar == 0, "the plan is not known: " .. tostring(copper and copper.count))
        assert(Kind(data, "note")[1] and Kind(data, "note")[1].text == L["plan unknown right now"] and data.done == 0, "no line that the plan is not known")
        -- hidden grey nodes of the plan: said
        Plan({ [COPPER] = { 60, 32 }, [TIN] = { 10, 4 } })
        ns.db.hideGreyNodes = true
        local keepGrey = ns.PinHiddenGrey
        ns.PinHiddenGrey = function(n) return n.id == VEIN end
        Plan({ [COPPER] = { 60, 33 }, [TIN] = { 10, 4 } })
        Look() Update()
        data = Lines()
        ns.PinHiddenGrey = keepGrey
        ns.db.hideGreyNodes = false
        assert(Kind(data, "note")[1] and Kind(data, "note")[1].text == (L["%d plan nodes hidden"]):format(2), "no line about the hidden plan nodes: " .. tostring(Kind(data, "note")[1] and Kind(data, "note")[1].text))

        -- ---- everything gathered: once the window, also with the run window hidden; no run numbers (Sven V6)
        ns.db.runPanelHidden = true
        ns.db.summaryOff = nil
        local shownSkill
        ns.ShowSkillPlan = function(prof) shownSkill = prof end
        local g0 = (_G.GathercraftPlanGathered and _G.GathercraftPlanGathered.shown) or 0
        W.Wait(200) -- (long enough for the run summary of an ordinary run)
        local summaries, keepSummary = 0, ns.ShowRunSummary
        ns.ShowRunSummary = function(...) summaries = summaries + 1 return keepSummary(...) end
        Plan({ [COPPER] = { 60, 60 }, [TIN] = { 10, 12 }, [STONE] = { 20, 5 }, [COAL] = { 8, 8 } })
        Look()
        ns.ShowRunSummary = keepSummary
        assert(summaries == 0, "the end of the plan run asked for the run summary")
        local g = _G.GathercraftPlanGathered
        assert(ns.run == nil and g and g:IsShown() and g.shown == g0 + 1, "the window \"Gathered for your plan\" did not come once")
        local text = g.body:GetText()
        assert(g.title:GetText() == L["Gathered for your plan"] and text:find(ns.ItemName(COPPER) .. "  60 / 60", 1, true) and text:find(ns.ItemName(TIN) .. "  12 / 10", 1, true), "the window does not say what was gathered: " .. text)
        assert(text:find(L["Still open, not routable:"], 1, true) and text:find((ns.ItemName(STONE) or "?") .. "  5 / 20", 1, true)
            and text:find((L["seen in %d of %d recorded gathers"]):format(7, 23), 1, true), "the window does not name what is open and not routable: " .. text)
        assert(not text:find(ns.ItemName(COAL) or "Coal", 1, true), "a covered material that is not on the map is named as open")
        for _, word in ipairs({ L["per hour"], L["worth"], "/ h" }) do assert(not text:find(word, 1, true), "run numbers in the window: " .. word) end
        local summary = _G.GathercraftRunSummary
        assert(not (summary and summary:IsShown()), "the run summary came with the plan's window")
        fire("BAG_UPDATE_DELAYED") W.Wait(3)
        assert(g.shown == g0 + 1, "the window came a second time")
        g.back.__scripts.OnClick(g.back)
        assert(shownSkill == "Mining" and not g:IsShown(), "\"Back to skill plan\" does not open the plan of the run's profession: " .. tostring(shownSkill))
        assert(g.back:GetText() == L["Back to skill plan"], "the button's text")
        ns.ShowSkillPlan = saved.show
        ns.db.runPanelHidden = nil
        -- nothing from the map at all: said
        Plan({ [COPPER] = { 60, 0 } })
        ns.StartRun(F, Z) W.Wait(1)
        Plan({ [COAL] = { 8, 0 } })
        Look()
        assert(g:IsShown() and g.shown == g0 + 2 and g.body:GetText():find(L["Your plan needs nothing from the map."], 1, true), "nothing from the map: " .. g.body:GetText())
        g:Hide()
        -- a blocked end shows the small window, not this one
        Plan({ [COPPER] = { 60, 0 } })
        ns.StartRun(F, Z) W.Wait(1)
        Plan({ [SILVER] = { 5, 0 } })
        Look()
        assert(ns.run == nil and not g:IsShown() and g.shown == g0 + 2 and _G.GathercraftPlanHint:IsShown(), "a blocked end showed the window of a good end")
        _G.GathercraftPlanHint:Hide()
        ns.PlanSeen = saved.seen
        ns.SkillPlanFor = saved.planFor

        -- ---- the skill plan: "Farm for plan" and "Where to farm" while a material of the map is open
        local profSkill, stock = 1, {}
        ns.ProfessionRank = function(p) if p == "Mining" then return profSkill, 75 end end
        d.Known = function() return {} end
        d.Have = function(id) return stock[id] or 0 end
        ns.db.planTargets = nil
        stock[COPPER], stock[TIN] = 20, 0
        ns.ShowSkillPlan("Mining") W.Wait(1)
        local win = _G.GathercraftSkillPlan
        local buttons = _G.GathercraftSkillPlanFarm
        assert(win and win:IsShown() and buttons and buttons:IsShown(), "no \"Farm for plan\" in the skill plan although copper and tin are open")
        assert(buttons.farm:GetText() == L["Farm for plan"] and buttons.zones:GetText() == L["Where to farm"], "the buttons' texts")
        assert(buttons.prof == "Mining" and buttons.target == 75, "the buttons are for " .. tostring(buttons.prof) .. " " .. tostring(buttons.target))
        -- the tooltip: what is on the map here, what is not here right now, what is not on the map
        local info = buttons.info
        assert(info.show and #info.onMap == 2 and info.onMap[1].item == COPPER and #info.blocked == 0, "what the button knows: " .. #info.onMap .. " on the map")
        local tipLines = {}
        for _, l in ipairs(ns.PlanButtonTooltip(info)) do tipLines[#tipLines + 1] = l[1] end
        local tip = table.concat(tipLines, "\n")
        assert(tip:find(L["On the map here:"], 1, true) and tip:find(ns.ItemName(COPPER) .. "  20 / 120", 1, true) and tip:find(L["Not on the map"], 1, true), "the tooltip: " .. tip)
        ns.GetSkill = function(t) if t == "ore" then return 10, 300, 10 end end -- tin cannot be gathered
        fire("BAG_UPDATE_DELAYED") W.Wait(1)
        stock[COPPER] = 21 fire("BAG_UPDATE_DELAYED") W.Wait(1)
        info = buttons.info
        assert(#info.onMap == 1 and #info.blocked == 1 and info.blocked[1].item == TIN and info.blocked[1].reason == "no_skill", "tin without the skill: not under \"not here right now\"")
        tipLines = {}
        for _, l in ipairs(ns.PlanButtonTooltip(info)) do tipLines[#tipLines + 1] = l[1] end
        assert(table.concat(tipLines, "\n"):find(L["Not here right now:"], 1, true) and table.concat(tipLines, "\n"):find(L["can't gather yet"], 1, true), "the tooltip does not say why tin is not here")
        -- (0.2 live test N2) no Mining for sure: the button's tooltip says it for each ore
        do
            local gp = ns.GatherProfessions
            ns.GatherProfessions = function() return true, false, true end
            stock[COPPER] = 22 fire("BAG_UPDATE_DELAYED") W.Wait(1)
            info = buttons.info
            assert(#info.blocked == 2 and info.blocked[1].reason == "no_mining" and info.blocked[2].reason == "no_mining", "without Mining: " .. #info.blocked .. " lines with a reason")
            tipLines = {}
            for _, l in ipairs(ns.PlanButtonTooltip(info)) do tipLines[#tipLines + 1] = l[1] end
            assert(select(2, table.concat(tipLines, "\n"):gsub(L["needs Mining"], "", 1e9)) == 2, "the tooltip does not say \"needs Mining\" for both ores: " .. table.concat(tipLines, " / "))
            ns.GatherProfessions = gp
            stock[COPPER] = 21 fire("BAG_UPDATE_DELAYED") W.Wait(1)
        end
        ns.GetSkill = function(t) if t == "ore" then return 100, 300, 100 end end
        -- the clicks
        local asked = {}
        ns.PlanFarmStart = function(prof, target) asked[#asked + 1] = "farm " .. tostring(prof) .. " " .. tostring(target) end
        ns.PlanZoneListShow = function(prof, target) asked[#asked + 1] = "zones " .. tostring(prof) .. " " .. tostring(target) end
        buttons.farm.__scripts.OnClick(buttons.farm)
        buttons.zones.__scripts.OnClick(buttons.zones)
        assert(asked[1] == "farm Mining 75" and asked[2] == "zones Mining 75" and #asked == 2, "the buttons' clicks: " .. table.concat(asked, ", "))
        ns.PlanFarmStart, ns.PlanZoneListShow = saved.farm, saved.zones
        -- pointing at a button works nothing out
        local checks, keepCheck = 0, ns.PlanRunCheck
        ns.PlanRunCheck = function(...) checks = checks + 1 return keepCheck(...) end
        buttons.farm.__scripts.OnEnter(buttons.farm)
        buttons.zones.__scripts.OnEnter(buttons.zones)
        assert(checks == 0, "pointing at the buttons worked the plan's zone out " .. checks .. " time(s)")
        ns.PlanRunCheck = keepCheck
        -- everything of the map is there: no button
        stock[COPPER], stock[TIN] = 500, 500
        fire("BAG_UPDATE_DELAYED") W.Wait(1)
        assert(not buttons:IsShown(), "\"Farm for plan\" although nothing of the map is open")
        -- a real click from the skill plan: the run, its rows, and nothing else changed
        stock[COPPER], stock[TIN] = 20, 0
        fire("BAG_UPDATE_DELAYED") W.Wait(1)
        assert(buttons:IsShown(), "test setup: the buttons are not back")
        buttons.farm.__scripts.OnClick(buttons.farm) W.Wait(1) Update()
        assert(ns.run and ns.run.plan and ns.run.zone == Z and ns.run.filter == F, "the click on \"Farm for plan\" started no plan run here")
        data = Lines()
        assert(Line(data, COPPER).count == "20 / 120" and Line(data, TIN).count == "0 / 10", "the run window after the click: " .. tostring(Line(data, COPPER).count))
        ns.StopRun(true)
        win:Hide()
        assert(#errors == before, "an error: " .. tostring(errors[#errors]))
    end)
    ns.SkillPlanFor, ns.GetSkill, ns.PlanSeen, ns.ShowSkillPlan, ns.PlanFarmStart, ns.PlanZoneListShow = saved.planFor, saved.skill, saved.seen, saved.show, saved.farm, saved.zones
    ns.ProfessionRank, d.Have, d.Known, ns.db.planTargets = saved.rank, saved.have, saved.known, saved.targets
    if ns.run then ns.StopRun(true) end
    for _, name in ipairs({ "GathercraftPlanZones", "GathercraftPlanHint", "GathercraftRunSummary", "GathercraftPlanGathered", "GathercraftSkillPlan" }) do if _G[name] then _G[name]:Hide() end end
    ns.db.panelCompact, ns.db.runPanelHidden, ns.db.activeRun, ns.db.summaryOff, ns.db.hideGreyNodes = saved.compact, saved.hidden, saved.run, saved.summaryOff, saved.grey
    if ns.PanelLayout then ns.PanelLayout() end
    W.Restore()
    if not ok then error(err, 0) end
end)
step("Farm for plan: every text in nine languages with the same placeholders, the lines keep to their widths, the release 0.2.0 names it (v0.2 B3 T6)", function()
    -- The order's part 6; concept test 10 (long names in all 11 language
    -- codes). Since the release 0.2.0 the changelog and "What's new" name it.
    local toc = assert(io.open(ROOT .. "/Gathercraft.toc")):read("*a")
    assert(toc:match("## Version: ([%w%.%-]+)") == "0.2.3-a3", "TOC version: " .. tostring(toc:match("## Version: ([%w%.%-]+)"))) -- (0.2.2)
    local function Read(name) return assert(io.open(ROOT .. "/" .. name)):read("*a") end
    local farm = Read("PlanFarm.lua")
    -- ---- the texts: every L["..."] of PlanFarm.lua, the reasons it looks up, and the three in Route.lua and UI.lua
    local keys, order = {}, {}
    local function Key(k) if not keys[k] then keys[k] = true order[#order + 1] = k end end
    for key in farm:gmatch('L%["(.-)"%]') do Key(key) end
    local looked = 0
    for block in farm:gmatch("local [RI][EN][AV][SA][OL][NI]D?_TEXT = (%b{})") do
        for text in block:gmatch('= "(.-)"') do Key(text) looked = looked + 1 end
    end
    assert(looked == 13, "test setup: " .. looked .. " reasons found in PlanFarm.lua, want 13 (with needs Herbalism / Mining, 0.2 live test N2)")
    local others = { ["Plan"] = "Route.lua", ["A plan run has no route preview. Start it from the skill plan."] = "Route.lua", ["Waiting for your plan ..."] = "UI.lua" }
    for key, file in pairs(others) do
        assert(Read(file):find('L["' .. key .. '"]', 1, true), "the text is not in " .. file .. ": " .. key)
        Key(key)
    end
    assert(#order >= 45, "test setup: only " .. #order .. " texts")
    local function Codes(s)
        local list = {}
        for code in s:gmatch("%%[%d%$]*[sd]") do list[#list + 1] = code end
        return table.concat(list, " ")
    end
    -- (words that are the same in a language: no translation to tell apart)
    local SAME = { ["Plan"] = true, ["Plan: %s %d"] = true, ["Plan %d/%d"] = true }
    local LANGS = { "deDE", "esES", "frFR", "itIT", "koKR", "ptBR", "ruRU", "zhCN", "zhTW" }
    local T = { enUS = {} }
    for _, key in ipairs(order) do T.enUS[key] = key end
    for _, lang in ipairs(LANGS) do
        T[lang] = {}
        for _, key in ipairs(order) do
            local tr = ns.Locales[lang] and ns.Locales[lang][key]
            assert(type(tr) == "string" and tr ~= "", ("no %s translation of %q"):format(lang, key))
            assert(Codes(tr) == Codes(key), ("%s: other placeholders (or another order) in %q: %s"):format(lang, key, tr))
            assert(tr ~= key or SAME[key] or lang == "frFR" and key == "Go", ("%s: %q is not translated"):format(lang, key))
            assert(not tr:find("^%s") and not tr:find("%s$"), ("%s: blanks around %q"):format(lang, tr))
            T[lang][key] = tr
        end
    end
    -- esMX reads the Spanish texts
    local esMX = ns.Locales.esMX or ns.Locales.esES
    assert(esMX and esMX["Farm for plan"] == ns.Locales.esES["Farm for plan"], "esMX does not read the Spanish texts")
    -- no promise in any language: no chance, no "best", no "guaranteed", no time
    for lang, texts in pairs(T) do
        for key, tr in pairs(texts) do
            local low = tr:lower()
            for _, word in ipairs({ "guarant", "garant", "cheapest", "best ", "beste", "mejor", "meilleur", "miglior", "melhor", "лучш", "最佳", "保证", "保證", "chance", "wahrscheinlich", "probab", "вероятн", "概率", "機率", "확률", "% " }) do
                assert(not low:find(word, 1, true), ("%s: %q promises something (%s)"):format(lang, tr, word))
            end
        end
    end

    -- ---- widths, as characters the player sees (East Asian ones count twice), with the longest values there are
    local function Width(text)
        local n = 0
        for ch in text:gmatch("[%z\1-\127\194-\244][\128-\191]*") do n = n + ((#ch >= 3) and 2 or 1) end
        return n
    end
    local BUTTON, TITLE, LINE, SLIM, MARK = 24, 44, 56, 12, 18
    local wide = {}
    local function Fits(lang, what, text, budget)
        if Width(text) > budget then wide[#wide + 1] = ("%s %s: %d > %d: %s"):format(lang, what, Width(text), budget, text) end
    end
    for lang, t in pairs(T) do
        for _, key in ipairs({ "Farm for plan", "Where to farm", "Back to skill plan", "Close", "Go" }) do Fits(lang, "button", t[key], BUTTON) end
        for _, key in ipairs({ "Where to farm for your plan", "Gathered for your plan" }) do Fits(lang, "title", t[key], TITLE) end
        Fits(lang, "the window of a blocked end", t["Nothing left to farm for your plan here"], 60)
        -- the lines under the run window
        for _, key in ipairs({ "can't gather yet", "not in this zone", "node types switched off", "parked", "needs Herbalism", "needs Mining" }) do Fits(lang, "reason line", "   " .. t[key], LINE) end
        Fits(lang, "seen line", "   " .. t["seen in %d of %d recorded gathers"]:format(999, 9999), LINE)
        Fits(lang, "head", t["Not on the map"], LINE)
        Fits(lang, "more", t["+%d more"]:format(99), LINE)
        Fits(lang, "note", t["plan unknown right now"], LINE)
        Fits(lang, "note", t["%d plan nodes hidden"]:format(9999), LINE)
        Fits(lang, "slim window", t["Plan %d/%d"]:format(12, 15), SLIM)
        Fits(lang, "next line", t["Waiting for your plan ..."], 40)
        -- the list of zones
        Fits(lang, "list sub title", t["Known spots for what you still need"], 60)
        Fits(lang, "list mark", t["(here)"], MARK)
        -- (0.2 live test N3) the materials of a row, at worst: the mark, one long name, "+N more" -
        -- the list shows fewer materials when they don't fit, but never less than one
        Fits(lang, "list row", t["(here)"] .. " " .. ("W"):rep(20) .. " 999 · " .. t["+%d more"]:format(99), 50)
        for _, key in ipairs({ "No known spots for the missing materials yet.", "Counting the known spots ...", "Working out the plan ..." }) do Fits(lang, "list note", t[key], 70) end
        Fits(lang, "list note", t["Zones %d-%d of %d (mouse wheel)"]:format(11, 20, 20), 60)
        -- the tooltip's heads and the end window's
        for _, key in ipairs({ "On the map here:", "Not here right now:", "Still open, not routable:", "Your plan needs nothing from the map." }) do Fits(lang, "head", t[key], LINE) end
    end
    assert(#wide == 0, #wide .. " texts wider than their place: " .. table.concat(wide, " | "))

    -- ---- under the run window: a reason and what was seen get a line of their own, in the client's language
    local saved = { planFor = ns.SkillPlanFor, skill = ns.GetSkill, seen = ns.PlanSeen, run = ns.db.activeRun, compact = ns.db.panelCompact, hidden = ns.db.runPanelHidden }
    local W = IdentityWorld()
    local ok, err = pcall(function()
        ns.db.panelCompact, ns.db.runPanelHidden = nil, nil
        ns.GetSkill = function(t) if t == "ore" then return 100, 300, 100 end end
        ns.PlanSeen = function(item) if item == 2835 then return { { id = "o1731", seen = 7, n = 23 } } end return nil end
        ns.SkillPlanFor = function()
            return { prof = "Mining", from = 1, target = 75, status = "ok", valid = true, complete = true, reliable = true, revision = 9100, items = {
                [2770] = { need = 60, have = 3, haveKnown = true, missing = 57 }, [2775] = { need = 5, have = 0, haveKnown = true, missing = 5 },
                [2835] = { need = 20, have = 1, haveKnown = true, missing = 19 } } }
        end
        W.Set({ W.Node("o1731", "Copper Vein", 100, { type = "ore" }) }) W.At(0)
        ns.StartRun(ns.PlanFilter("Mining", 75), 1412) W.Wait(1) advance(1.5)
        assert(ns.run and ns.run.plan, "test setup: no plan run")
        local data = ns.PlanPanelLines()
        local kinds = {}
        for i, l in ipairs(data.lines) do kinds[i] = l.kind end
        assert(table.concat(kinds, " ") == "row row sub head off sub", "the lines: " .. table.concat(kinds, " "))
        local L = ns.L
        assert(data.lines[3].text == L["not in this zone"] and data.lines[6].text == (L["seen in %d of %d recorded gathers"]):format(7, 23), "the lines under a row: " .. tostring(data.lines[3].text) .. " / " .. tostring(data.lines[6].text))
        local f = _G.GathercraftPlanPanel
        assert(f and f:IsShown(), "test setup: the plan is not under the run window")
        local shown = {}
        for _, row in ipairs(f.rows) do if row:IsShown() then shown[#shown + 1] = row end end
        assert(#shown == 6 and shown[3].name:GetText():find(L["not in this zone"], 1, true) and shown[6].name:GetText():find((L["seen in %d of %d recorded gathers"]):format(7, 23), 1, true),
            "the window's lines under a row: " .. tostring(shown[3] and shown[3].name:GetText()))
        assert(not shown[3].bar:IsShown() and not shown[3].barBack:IsShown() and shown[3].count:GetText() == "", "a line under a row has a bar or a count")
        -- every line the window shows now fits (the client's language)
        for i, row in ipairs(shown) do
            local l = row.line
            if l.kind ~= "row" and l.kind ~= "off" then
                assert(Width((row.name:GetText():gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", ""))) <= LINE, "line " .. i .. " is wider than its place: " .. row.name:GetText())
            end
        end
        ns.StopRun(true)
    end)
    ns.SkillPlanFor, ns.GetSkill, ns.PlanSeen = saved.planFor, saved.skill, saved.seen
    if ns.run then ns.StopRun(true) end
    for _, name in ipairs({ "GathercraftPlanZones", "GathercraftPlanHint", "GathercraftRunSummary", "GathercraftPlanGathered" }) do if _G[name] then _G[name]:Hide() end end
    ns.db.activeRun, ns.db.panelCompact, ns.db.runPanelHidden = saved.run, saved.compact, saved.hidden
    W.Restore()
    if not ok then error(err, 0) end

    -- ---- published with 0.2.0: its "What's new" names it. (The changelog
    -- holds the current version only: since 0.2.1 the 0.2.0 section is in
    -- the history, tag v0.2.0.)
    local entry = Read("Welcome.lua"):match('%["0%.2%.0"%] = "([^"]+)"')
    assert(entry and entry:find("Farm for plan", 1, true), "the \"What's new\" of 0.2.0 does not name the shopping list")
end)
step("Farm for plan: no setting is touched, the count follows your real stock both ways, a hidden value is never used (v0.2 B3 T7)", function()
    -- Concept shopping list 5 (3, 4, 11), tests 6 and 9: a plan run from
    -- its start to every kind of end changes no option, no CVar and no
    -- tracking; only the saved run (while it goes) and the gather counts
    -- (through the listener) are its own.
    local d = ns.CraftData
    local COPPER, TIN, VEIN = 2770, 2771, "o1731"
    local TINVEIN
    for key, kind in pairs(GathercraftQuestieData.kinds) do
        if kind[1] == "o" and kind[2] == TIN and (not TINVEIN or key < TINVEIN) then TINVEIN = key end
    end
    local Z = 1412
    local saved = { rank = ns.ProfessionRank, have = d.Have, known = d.Known, skill = ns.GetSkill, targets = ns.db.planTargets, run = ns.db.activeRun,
        loot = ns.db.kindLoot, secret = issecretvalue, setCVar = SetCVar, tracking = C_Minimap and C_Minimap.SetTracking, summaryOff = ns.db.summaryOff }
    local W = IdentityWorld()
    local before = #errors
    local win = _G.GathercraftSkillPlan
    if win then win:Hide() end
    local ok, err = pcall(function()
        local stock = {}
        ns.ProfessionRank = function(p) if p == "Mining" then return 1, 75 end end
        d.Known = function() return {} end
        d.Have = function(id)
            if stock[id] == "?" then return nil end
            return stock[id] or 0
        end
        ns.GetSkill = function(t) if t == "ore" then return 100, 300, 100 end end
        -- CVars: the gathering help of ANY run may set some while the run goes
        -- and takes them back with its end. So a plan run is held against an
        -- ordinary run: the same CVars while it goes, none of them left after.
        local cvar, trackings = {}, 0
        SetCVar = function(k, v, ...) cvar[tostring(k)] = tostring(v) return saved.setCVar(k, v, ...) end
        local function CVars()
            local keys = {}
            for k in pairs(cvar) do keys[#keys + 1] = k end
            table.sort(keys)
            local parts = {}
            for _, k in ipairs(keys) do parts[#parts + 1] = k .. "=" .. cvar[k] end
            return table.concat(parts, " ")
        end
        local cvarsInRun, cvarsAfter
        if C_Minimap and C_Minimap.SetTracking then C_Minimap.SetTracking = function(...) trackings = trackings + 1 return saved.tracking(...) end end
        local function Bags() fire("BAG_UPDATE_DELAYED") W.Wait(1) end
        local function Row(item)
            local s = ns.PlanRunState()
            for _, r in ipairs((s and s.rows) or {}) do if r.item == item then return r end end
        end
        local F = ns.PlanFilter("Mining", 75)
        W.Set({ W.Node(VEIN, "Copper Vein", 100, { type = "ore" }), W.Node(VEIN, "Copper Vein", 200, { type = "ore" }), W.Node(TINVEIN, "Tin Vein", 300, { type = "ore" }) })
        W.At(0)

        -- ---- the settings (test 9): the same before and after everything a plan run can do
        local SETTINGS = { "miniPinAlpha", "hideGreyNodes", "worldPinsHidden", "miniPinsHidden", "routeGoal", "disabledZones", "disabledKinds", "disabledContinents",
            "mapFollowsZones", "chestsHidden", "routeLineHidden", "routeLineMiniHidden", "panelCompact", "runPanelHidden", "advisorMode", "routeMode", "tooltipPrices",
            "summaryOff", "arriveDist", "pinSize", "language", "planTargets" }
        local function Flat(v, depth)
            if type(v) ~= "table" then return tostring(v) end
            local keys = {}
            for k in pairs(v) do keys[#keys + 1] = tostring(k) end
            table.sort(keys)
            local parts = {}
            for _, k in ipairs(keys) do
                local val = v[k]
                if val == nil then val = v[tonumber(k)] end
                parts[#parts + 1] = k .. "=" .. ((depth or 0) < 3 and Flat(val, (depth or 0) + 1) or "...")
            end
            return "{" .. table.concat(parts, ",") .. "}"
        end
        local function Settings()
            local t = {}
            for _, key in ipairs(SETTINGS) do t[key] = Flat(ns.db[key]) end
            return t
        end
        -- (every key of the saved data that is not a list of nodes or one of the run's own two: nothing new appears)
        local function Keys()
            local t = {}
            for k in pairs(ns.db) do t[#t + 1] = tostring(k) end
            table.sort(t)
            return table.concat(t, " ")
        end
        stock[COPPER], stock[TIN] = 10, 0
        ns.db.kindLoot = ns.db.kindLoot or {}
        -- (an ordinary run with one gather first: what every run and the recorder write is there then)
        ns.StartRun("ore", Z) W.Wait(1)
        cvarsInRun = CVars()
        W.At(200)
        local c0 = W.Cast("Copper Vein", 2575) W.Wait(2) W.Done(c0, 2575) W.Loot(1731, COPPER, "T7A000") fire("LOOT_CLOSED") W.Wait(4)
        ns.StopRun(true) advance(1)
        cvarsAfter = CVars()
        W.At(0)
        local set0, keys0 = Settings(), Keys()
        local function Unchanged(what)
            local now = Settings()
            for _, key in ipairs(SETTINGS) do
                assert(now[key] == set0[key], ("%s: the setting %s changed from %s to %s"):format(what, key, set0[key], now[key]))
            end
            assert(trackings == 0, ("%s: tracking set %d time(s)"):format(what, trackings))
            if ns.run then
                assert(what ~= "after the start" or CVars() == cvarsInRun, ("%s: the CVars are not those of an ordinary run: %s | ordinary: %s"):format(what, CVars(), cvarsInRun))
            else
                assert(CVars() == cvarsAfter, ("%s: the CVars are not as after an ordinary run: %s | ordinary: %s"):format(what, CVars(), cvarsAfter))
            end
        end
        -- start, run, a gather, the window of the run, the list of zones
        ns.StartRun(F, Z) W.Wait(1) advance(2)
        assert(ns.run and ns.run.plan, "test setup: no plan run")
        Unchanged("after the start")
        assert(ns.db.activeRun and ns.db.activeRun.filter == F, "the saved run while it goes")
        W.At(100)
        local c = W.Cast("Copper Vein", 2575) W.Wait(2) W.Done(c, 2575) W.Loot(1731, COPPER, "T7A001") fire("LOOT_CLOSED") W.Wait(4)
        stock[COPPER] = 12 Bags()
        ns.PlanZoneListShow("Mining", 75) advance(20)
        _G.GathercraftPlanZones:Hide()
        Unchanged("during the run")
        -- a stop by the player
        ns.StopRun() advance(1)
        Unchanged("after a stop")
        assert(ns.db.activeRun == nil, "a saved run after the stop")
        -- taken up after a reload, then the end with everything gathered
        ns.StartRun(F, Z) W.Wait(1)
        local keep = { filter = ns.db.activeRun.filter, zone = ns.db.activeRun.zone }
        ns.StopRun(true)
        ns.db.activeRun = keep
        ns.PlanRunResume(keep) W.Wait(1)
        Unchanged("after the reload")
        stock[COPPER], stock[TIN] = 500, 500 Bags()
        assert(ns.run == nil and ns.db.activeRun == nil, "test setup: no end")
        Unchanged("after the end with everything gathered")
        -- a blocked end
        stock[COPPER], stock[TIN] = 500, 0
        ns.StartRun(F, Z) W.Wait(1)
        assert(ns.run, "test setup: no run for tin")
        ns.GetSkill = function(t) if t == "ore" then return 10, 300, 10 end end
        W.Wait(40) Bags()
        assert(ns.run == nil and (ns.PlanRunLastEnd()).kind == "blocked", "test setup: no blocked end")
        ns.GetSkill = function(t) if t == "ore" then return 100, 300, 100 end end
        Unchanged("after a blocked end")
        -- an unknown format, by hand and saved
        slash("run plan:v2:mining:75")
        ns.db.activeRun = { filter = "plan:mining:75", zone = Z }
        ns.PlanRunResume(ns.db.activeRun)
        Unchanged("after an unknown format")
        assert(Keys() == keys0, "the saved data has other keys than before: " .. Keys() .. " | before: " .. keys0)
        for _, name in ipairs({ "GathercraftPlanZones", "GathercraftPlanHint", "GathercraftRunSummary", "GathercraftPlanGathered" }) do if _G[name] then _G[name]:Hide() end end

        -- ---- the count follows what you really have, up and down (test 6)
        stock[COPPER], stock[TIN] = 100, 0
        ns.StartRun(F, Z) W.Wait(1)
        local run = ns.run
        assert(run and Row(COPPER).have == 100 and not Row(COPPER).ok, "test setup: 100 of 120 copper")
        -- more of it without a gather (the mailbox, a trade): counted, ticked, out of the route
        stock[COPPER] = 130 Bags()
        assert(Row(COPPER).have == 130 and Row(COPPER).ok, "copper from the mailbox: " .. tostring(Row(COPPER).have))
        for _, p in ipairs(ns.run.points) do assert(p.node.id ~= VEIN, "a copper vein is in the route although the copper is there") end
        assert(ns.PlanGlowFor({ id = VEIN, type = "ore" }) == 0, "a copper vein glows although the copper is there")
        -- sold or thrown away: the tick goes, it is farmed again
        stock[COPPER] = 40 Bags()
        assert(ns.run and Row(COPPER).have == 40 and not Row(COPPER).ok, "copper sold: " .. tostring(Row(COPPER).have) .. ", ticked " .. tostring(Row(COPPER).ok))
        local back = false
        for _, p in ipairs(ns.run.points) do if p.node.id == VEIN then back = true end end
        assert(back and ns.PlanGlowFor({ id = VEIN, type = "ore" }) == 1, "the copper veins are not back in the route after the copper was sold")
        -- the same sum (bank in, bank out: the count is the whole of it): nothing moves, no new plan
        local published = 0
        local function Count() published = published + 1 end
        table.insert(ns.skillPlanListeners, Count)
        fire("BANKFRAME_OPENED") fire("PLAYERBANKSLOTS_CHANGED") Bags() fire("BANKFRAME_CLOSED") W.Wait(1)
        for i = #ns.skillPlanListeners, 1, -1 do if ns.skillPlanListeners[i] == Count then table.remove(ns.skillPlanListeners, i) end end
        assert(published == 0 and Row(COPPER).have == 40, "bank events with the same counts made " .. published .. " new plan(s)")
        -- a count that cannot be read (a bank never opened): "?", never 0, never an end
        stock[COPPER], stock[TIN] = "?", 500
        Bags()
        assert(ns.run and Row(COPPER).have == nil and not Row(COPPER).ok, "a count that cannot be read: " .. tostring(Row(COPPER).have))
        ns.StopRun(true)

        -- ---- a hidden value is never looked at (contract 11): not as a node's ID, not as an item of the loot
        local SECRET = setmetatable({}, { __eq = function() error("a hidden value was compared", 2) end, __lt = function() error("a hidden value was compared", 2) end,
            __le = function() error("a hidden value was compared", 2) end, __tostring = function() error("a hidden value was made a text", 2) end,
            __concat = function() error("a hidden value was put into a text", 2) end })
        issecretvalue = function(v) return rawequal(v, SECRET) end
        local loot0 = Flat(ns.db.kindLoot)
        -- (the listener of the gather counts alone: the recorder never hands a hidden item on, the other listeners need not expect one)
        local counter
        for _, f in ipairs(ns.gatherListeners) do
            ns.db.kindLoot.oT7probe = nil
            pcall(f, { id = "oT7probe", type = "ore", name = "Probe" }, { items = { { id = 990900, qty = 1 } } })
            if ns.db.kindLoot.oT7probe then counter = f end
        end
        ns.db.kindLoot.oT7probe = nil
        assert(counter, "test setup: the listener of the gather counts was not found")
        local function Tell(node, p) counter(node, p) end
        local n0 = ns.db.kindLoot[VEIN] and ns.db.kindLoot[VEIN].n or 0
        Tell({ id = VEIN, type = "ore", name = "Copper Vein" }, { items = { { id = SECRET, qty = 1 }, { id = 2835, qty = SECRET } } })
        local e = ns.db.kindLoot[VEIN]
        assert(e and e.n == n0 + 1 and e.items[2835] and not rawget(e.items, SECRET), "a hidden item ID was kept, or the readable one was not")
        for id in pairs(e.items) do assert(type(id) == "number", "something that is no number is kept as an item") end
        assert(ns.PlanNodeMatches({ id = SECRET, type = "ore" }, { [COPPER] = true }) == false and ns.PlanBaseItem(SECRET) == nil, "a hidden node ID was used")
        assert(ns.PlanGlowFor({ id = SECRET, type = "ore" }) == nil, "test setup: a glow without a run")
        assert(#errors == before, "an error: " .. tostring(errors[#errors]))
    end)
    issecretvalue, SetCVar = saved.secret, saved.setCVar
    if C_Minimap and saved.tracking then C_Minimap.SetTracking = saved.tracking end
    if ns.run then ns.StopRun(true) end
    ns.ProfessionRank, d.Have, d.Known, ns.GetSkill, ns.db.planTargets = saved.rank, saved.have, saved.known, saved.skill, saved.targets
    ns.db.activeRun, ns.db.kindLoot, ns.db.summaryOff = saved.run, saved.loot, saved.summaryOff
    for _, name in ipairs({ "GathercraftPlanZones", "GathercraftPlanHint", "GathercraftRunSummary", "GathercraftPlanGathered", "GathercraftSkillPlan" }) do if _G[name] then _G[name]:Hide() end end
    W.Restore()
    if not ok then error(err, 0) end
end)
step("Farm for plan: a big plan is worked out in parts for the run too - it waits, decides nothing, then goes on with the same plan (v0.2 B3 T8)", function()
    -- The harness' clock for the plan calculation stands still, so every
    -- other step gets its plan in one part. In the game a big plan takes
    -- several frames (Codex round 2, R2-M4): the plan run and the list of
    -- zones must wait for it - the second reader of concept 4.1.
    local d, core = ns.CraftData, ns.PlanCore
    local saved = { clock = ns.SkillPlanClock, rank = ns.ProfessionRank, have = d.Have, known = d.Known, skill = ns.GetSkill, compute = core.Compute,
        targets = ns.db.planTargets, run = ns.db.activeRun }
    local W = IdentityWorld()
    local before = #errors
    local win = _G.GathercraftSkillPlan
    if win then win:Hide() end
    local published = 0
    local function Count() published = published + 1 end
    table.insert(ns.skillPlanListeners, Count)
    local ok, err = pcall(function()
        local bonus = 0
        ns.ProfessionRank = function(p) if p == "Alchemy" then return 1, 300 end end
        d.Known = function() return {} end
        d.Have = function() return bonus end
        ns.GetSkill = function(t) if t == "herb" or t == "ore" then return 300, 300, 300 end end
        ns.db.planTargets = nil
        local starts, rests = 0, 0
        core.Compute = function(input, pause)
            starts = starts + 1
            if not pause then return saved.compute(input) end
            return saved.compute(input, function() rests = rests + 1 pause() end)
        end
        -- the plan in one go: what it needs from the map
        local whole = core.Result(saved.compute(ns.SkillPlanSnapshot("Alchemy", 1, 300)))
        local first
        local ids = {}
        for id in pairs(whole.items) do ids[#ids + 1] = id end
        table.sort(ids)
        for _, id in ipairs(ids) do
            if whole.items[id].need > 0 and ns.PlanBaseKinds(id) and not first then first = id end
        end
        assert(whole.status == "ok" and first, "test setup: the Alchemy plan to 300 needs nothing from the map")
        local kind = ns.PlanBaseKinds(first)[1]
        W.Set({ W.Node(kind, "Herb", 100, { type = "herb" }), W.Node(kind, "Herb", 200, { type = "herb" }) })
        W.At(0)
        local F = ns.PlanFilter("Alchemy", 300)
        -- a clock that goes on: a part ends after about 400 resting places
        local now = 0
        ns.SkillPlanClock = function() now = now + 0.01 return now end

        -- ---- start: the plan is not there yet - the run waits, steers to nothing, ends nothing
        starts, rests = 0, 0
        local pub0 = published
        local _, ends0 = ns.PlanRunLastEnd()
        ns.StartRun(F, 1412)
        local run = ns.run
        assert(run and run.plan and ns.SkillPlanBusy() and starts == 1, "the run did not start with the plan on its way (worked out in one go? starts " .. starts .. ")")
        local firstPart = rests
        assert(firstPart > 100 and firstPart < 2000, "the first part went over " .. firstPart .. " resting places")
        local s = ns.PlanRunState()
        assert(s.state == "waiting" and run.target == nil and run.held and published == pub0, "while the plan is worked out: state " .. tostring(s.state) .. ", " .. (published - pub0) .. " plan(s) given out")
        assert(select(2, ns.PlanRunLastEnd()) == ends0 and ns.db.activeRun and ns.db.activeRun.filter == F, "the run ended or is not saved while it waits for its plan")
        -- the frames after it: part by part, then the run has its plan and goes
        advance(2)
        assert(not ns.SkillPlanBusy() and starts == 1 and rests > firstPart * 3, ("the rest was not worked out in parts (%d resting places, %d in the first)"):format(rests, firstPart))
        s = ns.PlanRunState()
        assert(ns.run == run and s.state == "active" and run.target and not run.held and published == pub0 + 1, "with the finished plan: state " .. tostring(s.state) .. ", " .. (published - pub0) .. " plan(s)")
        -- it is the plan the calculation in one go gives: the same materials, need and have
        local rows = 0
        for _, row in ipairs(s.rows) do
            local m = whole.items[row.item]
            assert(m and m.need == row.need and row.have == 0, "the run's row of item " .. row.item .. " is not the plan's: " .. tostring(row.need) .. " / " .. tostring(m and m.need))
            rows = rows + 1
        end
        local want = 0
        for _, id in ipairs(ids) do if whole.items[id].need > 0 and ns.PlanBaseKinds(id) then want = want + 1 end end
        assert(rows == want and rows >= 5, "the run has " .. rows .. " materials of the map, the plan in one go " .. want)

        -- ---- a new state while the run goes: the run keeps going with what it read, then takes the new plan
        starts = 0
        bonus = 3
        fire("BAG_UPDATE_DELAYED")
        advance(0.3)
        assert(ns.SkillPlanBusy() and starts == 1, "the new state did not begin a new calculation in parts")
        s = ns.PlanRunState()
        assert(s.state == "waiting" and ns.run == run and run.target and s.rows[1].have == 0, "while the new plan is worked out: state " .. tostring(s.state) .. " (the route should go on with the rows read last)")
        advance(2)
        s = ns.PlanRunState()
        assert(not ns.SkillPlanBusy() and s.state == "active" and s.rows[1].have == 3, "the new plan did not reach the run: have " .. tostring(s.rows[1].have))

        -- ---- stopped while a plan is worked out: nothing goes on, nothing is given out
        starts = 0
        bonus = 4
        fire("BAG_UPDATE_DELAYED")
        advance(0.3)
        assert(ns.SkillPlanBusy(), "test setup: no calculation on its way")
        local pub1 = published
        ns.StopRun(true)
        local restsAtStop = rests
        advance(3)
        assert(not ns.SkillPlanBusy() and published == pub1, "the calculation went on after the run was stopped (" .. (published - pub1) .. " plan(s) given out)")
        assert(rests - restsAtStop < firstPart * 2, "after the stop the calculation went over " .. (rests - restsAtStop) .. " more resting places")

        -- ---- the list of zones waits for the plan in the same way
        bonus = 5
        assert(ns.PlanZoneListShow("Alchemy", 300), "the list did not open")
        local data = (ns.PlanZoneListState())
        local list = _G.GathercraftPlanZones
        assert(ns.SkillPlanBusy() and data.state == "waiting" and list.note:GetText() == ns.L["Working out the plan ..."] and ns.run == nil, "the list while the plan is worked out: " .. tostring(data.state))
        advance(3)
        data = (ns.PlanZoneListState())
        local mulgore = false
        for _, zone in ipairs(data.zones) do if zone.mapID == 1412 and zone.here and zone.candidates >= 1 then mulgore = true end end
        -- (other zones of the continent may have nodes of the herb from steps before this one)
        assert(not ns.SkillPlanBusy() and data.state == "ok" and mulgore, "the list did not take the finished plan: " .. tostring(data.state) .. ", " .. #data.zones .. " zones")
        -- closed while a plan is worked out: nothing goes on
        list:Hide()
        bonus = 6
        assert(ns.PlanZoneListShow("Alchemy", 300) and ns.SkillPlanBusy(), "test setup: the list opened again and no plan is on its way")
        list:Hide()
        local pub2 = published
        advance(3)
        assert(not ns.SkillPlanBusy() and published == pub2, "a calculation went on for the closed list")
        assert(#errors == before, "an error: " .. tostring(errors[#errors]))
    end)
    for i = #ns.skillPlanListeners, 1, -1 do if ns.skillPlanListeners[i] == Count then table.remove(ns.skillPlanListeners, i) end end
    ns.SkillPlanClock, ns.ProfessionRank, d.Have, d.Known, ns.GetSkill, core.Compute = saved.clock, saved.rank, saved.have, saved.known, saved.skill, saved.compute
    if ns.run then ns.StopRun(true) end
    for _, name in ipairs({ "GathercraftPlanZones", "GathercraftPlanHint", "GathercraftRunSummary", "GathercraftPlanGathered" }) do if _G[name] then _G[name]:Hide() end end
    ns.db.planTargets, ns.db.activeRun = saved.targets, saved.run
    W.Restore()
    advance(2)
    if not ok then error(err, 0) end
end)
step("Skill plan 2.0: the skill comes from the game's own list by its number - a German client, no skill list, no profession window (v0.2 on 0.1.23)", function()
    -- Sven, 16.11.2026: since 0.1.23 the professions are read with
    -- GetProfessions by the number of their skill line. Skill plan 2.0 must
    -- get the skill that way too: the German client names Alchemy
    -- "Alchimie", there is no skill list in the Forever client, and no
    -- profession window was opened. The numbers are the ones Sven saw live:
    -- Alchemy 171, Herbalism 182, Mining 186, First Aid 129, Fishing 356,
    -- Cooking 185, Leatherworking 165, Skinning 393.
    local L = ns.L
    local keep = { gp = GetProfessions, gi = GetProfessionInfo, gn = GetNumSkillLines, gl = GetSkillLineInfo, skill = ns.GetSkill }
    local mine = ns.db.recipes[next(ns.db.recipes)]
    local saved = { alchemy = mine.Alchemy, leather = mine.Leatherworking, cooking = mine.Cooking, aid = mine["First Aid"], targets = ns.db.planTargets }
    local function Texts(text)
        for _, o in ipairs(allFrames) do
            local t = o.GetText and o:GetText()
            if type(t) == "string" and o.IsShown and o:IsShown() and t:find(text, 1, true) then return t end
        end
    end
    local ok, err = pcall(function()
        -- the German client's list: names as the game gives them, the numbers of the lines
        local slots = {
            { "Alchimie", 120, 150, 171 }, { "Kräuterkunde", 130, 150, 182 }, nil, { "Angeln", 200, 225, 356 },
            { "Kochkunst", 80, 150, 185 }, { "Erste Hilfe", 90, 150, 129 }, { "Lederverarbeitung", 140, 150, 165 },
        }
        GetProfessions = function() return 1, 2, nil, 4, 5, 6, 7 end
        GetProfessionInfo = function(i)
            local s = slots[i]
            if s then return s[1], 0, s[2], s[3], 0, 0, s[4], 0 end
        end
        GetNumSkillLines, GetSkillLineInfo = nil, nil -- (the Forever client has no skill list)
        ns.GetSkill = function() return nil end      -- (and nothing else knows a skill)
        mine.Alchemy, mine.Leatherworking, mine.Cooking, mine["First Aid"] = nil, nil, nil, nil -- no profession window seen
        -- every profession of the list, by its number: the skill read NOW
        for prof, want in pairs({ Alchemy = 120, Cooking = 80, ["First Aid"] = 90, Leatherworking = 140 }) do
            local state, rank, maxRank, _, source = ns.SkillPlanSkillState(prof)
            assert(state == "learned" and rank == want and maxRank == 150 and source == "current",
                ("%s: %s %s/%s (%s), want learned %d/150, read now"):format(prof, tostring(state), tostring(rank), tostring(maxRank), tostring(source), want))
        end
        -- a profession that is not in the list: never a skill NOW out of nothing
        -- (one seen last in a step before this one may be there: said to be that)
        local state, _, _, _, source = ns.SkillPlanSkillState("Tailoring")
        assert(not (state == "learned" and source == "current"), "Tailoring is not in the list but has a skill now: " .. tostring(state) .. " " .. tostring(source))
        -- the window: the plan of "Alchimie" with its skill, not "open your profession window once"
        ns.db.planTargets = nil
        ns.ShowSkillPlan("Alchemy") advance(1)
        assert(Texts((L["Your skill: %d / %d"]):format(120, 150)), "the skill plan does not show 120 / 150 for \"Alchimie\" from the game's list")
        assert(not Texts(L["Your skill: ? (open your profession window once)"]), "the skill plan still asks to open the profession window")
        local result = ns.SkillPlanResult()
        assert(result and result.prof == "Alchemy" and result.from == 120 and result.reliable and result.skillSource == "current",
            "the plan is not from the skill read now: " .. tostring(result and result.from) .. " " .. tostring(result and result.skillSource))
        if _G.GathercraftSkillPlan then _G.GathercraftSkillPlan:Hide() end
        -- what was read is kept as the skill seen last: with the list gone the plan is a preview of it, never "current"
        mine.Alchemy = { list = {}, rank = nil }
        ns.SkillPlanSkillState("Alchemy") -- (reads the list again: keeps 120 as seen last)
        assert(mine.Alchemy.rank == 120, "the skill read by its number is not kept as the one seen last: " .. tostring(mine.Alchemy.rank))
        GetProfessions = function() return nil, nil, nil, nil, nil, nil, nil end
        local s2, r2, _, _, src2 = ns.SkillPlanSkillState("Alchemy")
        assert(s2 == "learned" and r2 == 120 and src2 == "lastSeen", "without the list: " .. tostring(s2) .. " " .. tostring(r2) .. " " .. tostring(src2) .. ", want the skill seen last")
        -- a hidden value in the list is never taken
        local SECRET = setmetatable({}, { __eq = function() error("a hidden value was compared") end })
        local keepSecret = issecretvalue
        issecretvalue = function(v) return rawequal(v, SECRET) end
        GetProfessions = function() return 1 end
        GetProfessionInfo = function() return "Alchimie", 0, SECRET, 150, 0, 0, 171, 0 end
        local okS, s3, r3, _, _, src3 = pcall(ns.SkillPlanSkillState, "Alchemy")
        issecretvalue = keepSecret
        assert(okS and not (s3 == "learned" and src3 == "current"), "a hidden skill in the list was taken as the skill now: " .. tostring(s3) .. " " .. tostring(src3))
    end)
    GetProfessions, GetProfessionInfo, GetNumSkillLines, GetSkillLineInfo, ns.GetSkill = keep.gp, keep.gi, keep.gn, keep.gl, keep.skill
    mine.Alchemy, mine.Leatherworking, mine.Cooking, mine["First Aid"], ns.db.planTargets = saved.alchemy, saved.leather, saved.cooking, saved.aid, saved.targets
    if _G.GathercraftSkillPlan then _G.GathercraftSkillPlan:Hide() end
    if not ok then error(err, 0) end
end)
step("Item tooltip: the auction house scan that starts on opening (0.1.23) gives the tooltip its price - kind, age, quantity, the 14 days (v0.2 on 0.1.23)", function()
    -- Sven, 16.11.2026: the item tooltip of 0.2 and the scan that starts
    -- when the auction house opens (0.1.23 P5, in short steps R1-M1) must go
    -- together: the scan's prices are market prices with their quantity,
    -- the tooltip shows them at once - its caches know a new price by the
    -- price revision - and its 14 days count the scan's day.
    local L, AHX = ns.L, C_AuctionHouse
    ns.GetPrice(2447)
    local p = ns.db.prices[next(ns.db.prices)]
    local HERB, ORE = 2447, 2770
    local keep = { rep = AHX.ReplicateItems, num = AHX.GetNumReplicateItems, info = AHX.GetReplicateItemInfo, off = ns.db.autoScanOff,
        last = p.lastScanStart, scanned = p.scanned, items = p.items, qty = p.qty, seen = p.seen, meta = p.meta, option = ns.db.tooltipPrices,
        shift = IsShiftKeyDown, atr = Auctionator, tsm = TSM_API }
    keep.history = {}
    for id, text in pairs(p.history) do keep.history[id] = text end
    local before = #errors
    local ok, err = pcall(function()
        Auctionator, TSM_API = nil, nil -- (our own price only: no other addon's price in the line)
        ns.db.tooltipPrices, ns.db.autoScanOff = true, nil
        IsShiftKeyDown = function() return false end
        local fx = TT.Load("tdp", true)
        fx.Event("PLAYER_LOGIN") advance(10)
        assert(fx.State() == "ready", "test setup: the tooltip is not ready: " .. fx.State())
        local tip = fx.game
        local function Line()
            local lines = fx.Hover(tip, HERB)
            for _, l in ipairs(lines) do
                local plain = TT.Plain(l)
                if plain:find(L["AH price"], 1, true) then return plain end
            end
        end
        -- before: no price of our own for Peacebloom
        p.items[HERB], p.qty[HERB], p.seen[HERB], p.meta[HERB], p.history[HERB] = nil, nil, nil, nil, nil
        local first = Line()
        assert(first and first:find(L["unknown – scan at the auction house"], 1, true), "test setup: Peacebloom has a price before the scan: " .. tostring(first))
        local rev0 = ns.PriceRev()
        -- the auction house opens; the scan starts by itself and is answered: 300 auctions of Peacebloom, 100 of copper ore
        local auctions = {}
        for i = 1, 400 do auctions[i] = { id = i <= 300 and HERB or ORE, count = i % 5 + 1, unit = i <= 300 and (40 + i % 3) or 90 } end
        local calls = 0
        AHX.ReplicateItems = function() calls = calls + 1 end
        AHX.GetNumReplicateItems = function() return #auctions end
        AHX.GetReplicateItemInfo = function(i)
            local a = auctions[i + 1]
            if not a then return nil end
            return "Item", 1, a.count, 1, true, 1, 0, 0, 0, a.unit * a.count, 0, false, nil, "Seller", nil, 0, a.id, true
        end
        AuctionHouseFrame = AuctionHouseFrame or CreateFrame("Frame", "AuctionHouseFrame", UIParent)
        fire("AUCTION_HOUSE_CLOSED") advance(1)
        p.lastScanStart = 0
        fire("AUCTION_HOUSE_SHOW") advance(1)
        assert(calls == 1, "the scan did not start when the window opened")
        p.scanned = 0
        fire("REPLICATE_ITEM_LIST_UPDATE") advance(3)
        assert(p.scanned and p.scanned > 0 and p.items[HERB], "the scan's answer was not read")
        assert(ns.PriceRev() ~= rev0, "the scan's prices did not count up the price revision - the tooltip would keep its old lines")
        -- the scan's price is a market price with its quantity
        local info = ns.PriceInfo(HERB)
        local listed = 0
        for i = 1, 300 do listed = listed + auctions[i].count end
        assert(info and info.own and info.kind == "market" and info.qty == listed and info.age and info.age < 60,
            ("the scan's price: kind %s, quantity %s (want %d), age %s"):format(tostring(info and info.kind), tostring(info and info.qty), listed, tostring(info and info.age)))
        -- the tooltip shows it at once: own scan, just now, how many - without the old "unknown"
        local line = Line()
        assert(line and line:find(TT.Plain(ns.Money(p.items[HERB])), 1, true) and line:find(L["own scan"], 1, true), "the tooltip after the scan: " .. tostring(line))
        assert(line:find((L["%s listed"]):format(tostring(listed)), 1, true) or line:find(tostring(listed), 1, true), "the tooltip does not say how many were listed: " .. tostring(line))
        assert(not line:find(L["unknown – scan at the auction house"], 1, true), "the tooltip still says to scan: " .. tostring(line))
        -- the 14 days count the scan's day
        local today = math.floor(time() / 86400)
        local window = ns.PriceHistoryWindow(HERB, today)
        assert(#window >= 1 and window[#window][1] == today and window[#window][2] == p.items[HERB], "the scan's day is not in the 14 days")
        local lines14
        for _, l in ipairs(fx.Hover(tip, HERB)) do if TT.Plain(l):find(L["14 days"], 1, true) then lines14 = TT.Plain(l) end end
        assert(lines14 and lines14:find(L["1 day with data"], 1, true), "the tooltip's 14 days after the first scan: " .. tostring(lines14))
        -- the window closes before the next scan: the price stays, the tooltip says nothing else
        fire("AUCTION_HOUSE_CLOSED") advance(1)
        assert(Line() == line, "the tooltip changed when the window closed: " .. tostring(Line()))
        assert(#errors == before, "an error: " .. tostring(errors[#errors]))
    end)
    AHX.ReplicateItems, AHX.GetNumReplicateItems, AHX.GetReplicateItemInfo = keep.rep, keep.num, keep.info
    ns.db.autoScanOff, p.lastScanStart, p.scanned, p.items, p.qty, p.seen, p.meta = keep.off, keep.last, keep.scanned, keep.items, keep.qty, keep.seen, keep.meta
    for id in pairs(p.history) do p.history[id] = nil end
    for id, text in pairs(keep.history) do p.history[id] = text end
    ns.db.tooltipPrices, IsShiftKeyDown, Auctionator, TSM_API = keep.option, keep.shift, keep.atr, keep.tsm
    fire("AUCTION_HOUSE_CLOSED") advance(1)
    if not ok then error(err, 0) end
end)
step("Farm for plan: a plan run and the list of zones of another profession do not set each other off (v0.2 B3 R1-M1)", function()
    -- Codex round 1 of block 3, M1: a Mining run and the list of zones of
    -- Alchemy, the skill plan closed - every plan the one gave out began the
    -- other's again (15-30 calculations in 3 s with nothing changed). Now a
    -- reader is set off only by its own plan; the plans it has are kept, one
    -- for each profession and target.
    local d, core = ns.CraftData, ns.PlanCore
    local saved = { clock = ns.SkillPlanClock, rank = ns.ProfessionRank, have = d.Have, known = d.Known, skill = ns.GetSkill, compute = core.Compute,
        targets = ns.db.planTargets, run = ns.db.activeRun }
    local W = IdentityWorld()
    local before = #errors
    local win = _G.GathercraftSkillPlan
    if win then win:Hide() end
    local ok, err = pcall(function()
        local stock = {}
        ns.ProfessionRank = function(p) if p == "Mining" then return 1, 75 elseif p == "Alchemy" then return 1, 300 end end
        d.Known = function() return {} end
        d.Have = function(id) return stock[id] or 0 end
        ns.GetSkill = function(t) if t == "herb" or t == "ore" then return 300, 300, 300 end end
        ns.db.planTargets = nil
        local starts = {}
        core.Compute = function(input, pause)
            starts[#starts + 1] = input.prof
            return saved.compute(input, pause)
        end
        local function Count(prof) local n = 0 for _, p in ipairs(starts) do if prof == nil or p == prof then n = n + 1 end end return n end
        -- an herb of the Alchemy plan and the copper veins of the Mining plan, here
        local whole = core.Result(saved.compute(ns.SkillPlanSnapshot("Alchemy", 1, 300)))
        local herb
        for id, m in pairs(whole.items) do if m.need > 0 and ns.PlanBaseKinds(id) and (not herb or id < herb) then herb = id end end
        assert(herb, "test setup: the Alchemy plan needs nothing from the map")
        W.Set({ W.Node("o1731", "Copper Vein", 100, { type = "ore" }), W.Node(ns.PlanBaseKinds(herb)[1], "Herb", 200, { type = "herb" }) })
        W.At(0)
        local now = 0
        ns.SkillPlanClock = function() now = now + 0.01 return now end -- (a clock that goes on: big plans in parts)
        -- the Mining run, then the list of Alchemy - the skill plan stays closed
        ns.StartRun(ns.PlanFilter("Mining", 75), 1412)
        assert(ns.run and ns.run.plan, "test setup: no Mining run")
        assert(ns.PlanZoneListShow("Alchemy", 300), "test setup: the list of Alchemy did not open")
        advance(5)
        local settled = Count()
        -- 3 s with nothing changed: nothing is worked out again
        starts = {}
        advance(3)
        note(("MEASURE M1 a Mining run and the list of Alchemy: %d calculations to settle, then %d in 3 s with nothing changed (%d Mining, %d Alchemy)"):format(
            settled, Count(), Count("Mining"), Count("Alchemy")))
        assert(Count() == 0, ("3 s with nothing changed: %d calculations (%d Mining, %d Alchemy) - the two set each other off"):format(Count(), Count("Mining"), Count("Alchemy")))
        assert(not ns.SkillPlanBusy() and ns.PlanRunState().state == "active" and (ns.PlanZoneListState()).state == "ok",
            ("the run is %s, the list %s, still working out: %s"):format(tostring(ns.PlanRunState().state), tostring((ns.PlanZoneListState()).state), tostring(ns.SkillPlanBusy())))
        -- the bags change (copper ore: only the run's plan uses it): the run's plan is worked
        -- out once more - and then it is quiet again; the list of Alchemy is not built anew for
        -- the run's new plan (Codex: "the list renews its own job on every plan given out")
        local builds0 = select(2, ns.PlanZoneListState())
        stock[2770] = 5
        fire("BAG_UPDATE_DELAYED") advance(3)
        local builds = select(2, ns.PlanZoneListState()) - builds0
        assert(builds == 0, ("after a change that is not the list's the list was built %d times, want 0"):format(builds))
        local afterBags = Count()
        assert(afterBags >= 1 and afterBags <= 2 and Count("Mining") <= 1 and Count("Alchemy") <= 1,
            ("after one change of the bags: %d calculations (%d Mining, %d Alchemy), want at most one each"):format(afterBags, Count("Mining"), Count("Alchemy")))
        assert(ns.PlanRunState().rows[1].have == 5, "the run did not get the new count")
        starts = {}
        builds0 = select(2, ns.PlanZoneListState())
        advance(3)
        assert(Count() == 0, "after the change it did not get quiet again: " .. Count() .. " calculations in 3 s")
        assert(select(2, ns.PlanZoneListState()) == builds0, "the list was built anew with nothing changed")
        -- the control: both read the same plan - one calculation, nothing set off
        _G.GathercraftPlanZones:Hide()
        assert(ns.PlanZoneListShow("Mining", 75), "test setup: the list of Mining did not open")
        advance(3)
        starts = {}
        advance(3)
        assert(Count() == 0, "the run and the list of the same plan: " .. Count() .. " calculations in 3 s")
        assert(#errors == before, "an error: " .. tostring(errors[#errors]))
    end)
    ns.SkillPlanClock, ns.ProfessionRank, d.Have, d.Known, ns.GetSkill, core.Compute = saved.clock, saved.rank, saved.have, saved.known, saved.skill, saved.compute
    if ns.run then ns.StopRun(true) end
    for _, name in ipairs({ "GathercraftPlanZones", "GathercraftPlanHint", "GathercraftRunSummary", "GathercraftPlanGathered" }) do if _G[name] then _G[name]:Hide() end end
    ns.db.planTargets, ns.db.activeRun = saved.targets, saved.run
    W.Restore()
    advance(2)
    if not ok then error(err, 0) end
end)
step("Farm for plan: frozen while the skill plan shows another profession - and free again when it closes or shows the run's own, with no bag event (v0.2 B3 R1-M2)", function()
    -- Codex round 1 of block 3, M2: a Mining run, Alchemy in the skill plan
    -- (the run freezes, as Sven decided on 16.11.), three copper ore come in;
    -- the window closes and you stand still - the run stayed "invalid" with
    -- 0 instead of 3 for 40 s. Now closing the window, or showing the run's
    -- own profession again, lets the run read its plan at once.
    local d = ns.CraftData
    local saved = { rank = ns.ProfessionRank, have = d.Have, known = d.Known, skill = ns.GetSkill, targets = ns.db.planTargets, run = ns.db.activeRun }
    local W = IdentityWorld()
    local before = #errors
    local win = _G.GathercraftSkillPlan
    if win then win:Hide() end
    local ok, err = pcall(function()
        local stock = {}
        ns.ProfessionRank = function(p) if p == "Mining" then return 1, 75 elseif p == "Alchemy" then return 1, 300 end end
        d.Known = function() return {} end
        d.Have = function(id) return stock[id] or 0 end
        ns.GetSkill = function(t) if t == "herb" or t == "ore" then return 300, 300, 300 end end
        ns.db.planTargets = nil
        W.Set({ W.Node("o1731", "Copper Vein", 100, { type = "ore" }), W.Node("o1731", "Copper Vein", 200, { type = "ore" }) })
        W.At(0)
        local function Copper()
            local s = ns.PlanRunState()
            for _, r in ipairs((s and s.rows) or {}) do if r.item == 2770 then return r end end
        end
        ns.StartRun(ns.PlanFilter("Mining", 75), 1412) W.Wait(1)
        assert(ns.run and ns.PlanRunState().state == "active" and Copper().have == 0, "test setup: no Mining run with 0 copper")
        -- Alchemy in the skill plan: the run freezes; three copper ore come in meanwhile
        ns.ShowSkillPlan("Alchemy") advance(1)
        win = _G.GathercraftSkillPlan
        stock[2770] = 3
        fire("BAG_UPDATE_DELAYED") advance(1)
        local s = ns.PlanRunState()
        assert(s.state == "invalid" and s.why == "window" and s.frozen, "test setup: the run is not frozen: " .. tostring(s.state) .. " " .. tostring(s.why))
        -- the window closes - and nothing else happens: no bag event, no step
        win:Hide()
        advance(2)
        s = ns.PlanRunState()
        assert(s.state == "active" and Copper().have == 3, ("2 s after the window closed, with no bag event: the run is %s with %s copper - want active with 3"):format(tostring(s.state), tostring(Copper() and Copper().have)))
        -- the same with the window left open: back to the run's own profession
        ns.ShowSkillPlan("Alchemy") advance(1)
        stock[2770] = 7
        fire("BAG_UPDATE_DELAYED") advance(1)
        assert(ns.PlanRunState().state == "invalid", "test setup: not frozen again")
        ns.ShowSkillPlan("Mining")
        advance(2)
        s = ns.PlanRunState()
        assert(win:IsShown() and s.state == "active" and Copper().have == 7, ("2 s after the window showed Mining again: the run is %s with %s copper - want active with 7"):format(tostring(s.state), tostring(Copper() and Copper().have)))
        -- the run's own profession in the window, closed: nothing breaks, nothing changes
        win:Hide() advance(2)
        assert(ns.PlanRunState().state == "active" and Copper().have == 7, "closing the window on the run's own profession changed the run")
        -- and the list of zones of a profession the window shows otherwise: free again too
        ns.ShowSkillPlan("Alchemy") advance(1)
        assert(ns.PlanZoneListShow("Mining", 75), "test setup: the list did not open")
        advance(1)
        local data = (ns.PlanZoneListState())
        assert(data.state == "invalid" and data.why == "window", "test setup: the list is not held by the window: " .. tostring(data.state))
        win:Hide() advance(2)
        data = (ns.PlanZoneListState())
        assert(data.state == "ok", "2 s after the window closed the list still says: " .. tostring(data.state) .. " " .. tostring(data.why))
        assert(#errors == before, "an error: " .. tostring(errors[#errors]))
    end)
    ns.ProfessionRank, d.Have, d.Known, ns.GetSkill = saved.rank, saved.have, saved.known, saved.skill
    if ns.run then ns.StopRun(true) end
    for _, name in ipairs({ "GathercraftPlanZones", "GathercraftPlanHint", "GathercraftRunSummary", "GathercraftPlanGathered", "GathercraftSkillPlan" }) do if _G[name] then _G[name]:Hide() end end
    ns.db.planTargets, ns.db.activeRun = saved.targets, saved.run
    W.Restore()
    if not ok then error(err, 0) end
end)
step("Farm for plan: while the run waits for the bags no tick is shown - the numbers stay, the mark of the end comes with the end (v0.2 B3 R1-M3)", function()
    -- Codex round 1 of block 3, M3: 60 copper ore needed, 0 there; the loot
    -- window opens and the next look already has 60 - the run rightly
    -- waits, but the window showed "Plan 1/1" with the tick. Checked here is
    -- what is SHOWN, not only the state.
    local given
    local saved = { planFor = ns.SkillPlanFor, skill = ns.GetSkill, run = ns.db.activeRun, compact = ns.db.panelCompact, hidden = ns.db.runPanelHidden }
    local W = IdentityWorld()
    local before = #errors
    local ok, err = pcall(function()
        ns.db.panelCompact, ns.db.runPanelHidden = nil, nil
        ns.GetSkill = function(t) if t == "ore" then return 100, 300, 100 end end
        local function Plan(have)
            given = { prof = "Mining", from = 1, target = 75, status = "ok", valid = true, complete = true, reliable = true, revision = 9300 + have,
                items = { [2770] = { need = 60, have = have, haveKnown = true, missing = math.max(0, 60 - have) } } }
        end
        ns.SkillPlanFor = function() return given end
        W.Set({ W.Node("o1731", "Copper Vein", 100, { type = "ore" }), W.Node("o1731", "Copper Vein", 200, { type = "ore" }) })
        W.At(0)
        Plan(0)
        ns.StartRun(ns.PlanFilter("Mining", 75), 1412) W.Wait(1) advance(1.5)
        assert(ns.run and ns.PlanRunState().state == "active", "test setup: no run")
        local panel = _G.GathercraftPanel
        local TICK = "ReadyCheck-Ready"
        local function Shown()
            -- everything the run window and the rows under it show now
            local texts = { panel.title:GetText() or "" }
            local f = _G.GathercraftPlanPanel
            if f and f:IsShown() then
                for _, row in ipairs(f.rows) do
                    if row:IsShown() then texts[#texts + 1] = (row.name:GetText() or "") .. " " .. (row.count:GetText() or "") end
                end
            end
            return table.concat(texts, " | ")
        end
        local _, ends0 = ns.PlanRunLastEnd()
        -- the loot window opens; the next look already has all 60
        fire("LOOT_OPENED")
        Plan(60)
        fire("BAG_UPDATE_DELAYED") W.Wait(0.5) advance(1)
        assert(ns.run and ns.PlanRunState().state == "waiting", "test setup: the run does not wait: " .. tostring(ns.PlanRunState() and ns.PlanRunState().state))
        local data = ns.PlanPanelLines()
        local row = data.lines[1]
        -- the numbers and the bar of what was read stay ...
        assert(row.count == "60 / 60" and row.bar == 1, "while waiting the numbers are gone: " .. tostring(row.count) .. ", bar " .. tostring(row.bar))
        -- ... but nothing says "done": no tick in a row, none in the slim line, the count of done ones is the one confirmed
        assert(not row.ok, "while waiting a row is marked as done")
        assert(not data.compact:find(TICK, 1, true), "while waiting the slim line has the tick: " .. data.compact)
        assert(not Shown():find(TICK, 1, true), "while waiting the run window shows a tick: " .. Shown())
        ns.db.panelCompact = true
        ns.PanelLayout() advance(1.5)
        assert(not panel.title:GetText():find(TICK, 1, true), "while waiting the slim window shows a tick: " .. tostring(panel.title:GetText()))
        assert(panel.title:GetText() == (ns.L["Plan %d/%d"]):format(0, 1), "while waiting the slim window says " .. tostring(panel.title:GetText()) .. ", want Plan 0/1 (the one confirmed)")
        ns.db.panelCompact = nil
        ns.PanelLayout() advance(0.5)
        -- the plan is not known for a moment: no tick either
        given = nil
        ns.SkillPlanFor = function() return nil, "window" end
        fire("BAG_UPDATE_DELAYED") advance(1)
        assert(not ns.PlanPanelLines().compact:find(TICK, 1, true) and not Shown():find(TICK, 1, true), "while the plan is not known a tick is shown")
        ns.SkillPlanFor = function() return given end
        Plan(60)
        -- the loot window closes: the end, once, silent - and its window says it
        local g = _G.GathercraftPlanGathered
        local shown0 = g and g.shown or 0
        fire("LOOT_CLOSED") W.Wait(3)
        local last, ends = ns.PlanRunLastEnd()
        assert(ns.run == nil and ends == ends0 + 1 and last.kind == "success", "the end did not come once: " .. tostring(last and last.kind) .. ", " .. (ends - ends0) .. " end(s)")
        g = _G.GathercraftPlanGathered
        assert(g and g:IsShown() and g.shown == shown0 + 1 and g.body:GetText():find(TICK, 1, true), "the end window with the tick did not come once")
        -- an active run with a material covered and one open: that row is ticked (a confirmed state)
        g:Hide()
        given = { prof = "Mining", from = 1, target = 75, status = "ok", valid = true, complete = true, reliable = true, revision = 9400,
            items = { [2770] = { need = 60, have = 60, haveKnown = true, missing = 0 }, [2771] = { need = 10, have = 0, haveKnown = true, missing = 10 } } }
        W.Set({ W.Node("o1731", "Copper Vein", 100, { type = "ore" }), W.Node("o1732", "Tin Vein", 200, { type = "ore" }) })
        ns.StartRun(ns.PlanFilter("Mining", 75), 1412) W.Wait(1) advance(1.5)
        assert(ns.PlanRunState().state == "active", "test setup: no active run for tin")
        data = ns.PlanPanelLines()
        local copper
        for _, l in ipairs(data.lines) do if l.item == 2770 then copper = l end end
        assert(copper and copper.ok and Shown():find(TICK, 1, true) and data.done == 1 and data.compact == (ns.L["Plan %d/%d"]):format(1, 2),
            "an active run does not tick the covered copper: " .. Shown())
        ns.StopRun(true)
        assert(#errors == before, "an error: " .. tostring(errors[#errors]))
    end)
    ns.SkillPlanFor, ns.GetSkill = saved.planFor, saved.skill
    if ns.run then ns.StopRun(true) end
    for _, name in ipairs({ "GathercraftPlanZones", "GathercraftPlanHint", "GathercraftRunSummary", "GathercraftPlanGathered" }) do if _G[name] then _G[name]:Hide() end end
    ns.db.activeRun, ns.db.panelCompact, ns.db.runPanelHidden = saved.run, saved.compact, saved.hidden
    if ns.PanelLayout then ns.PanelLayout() end
    W.Restore()
    if not ok then error(err, 0) end
end)
step("Farm for plan: an incomplete plan farms on while something of the map is open, and ends blocked - once, with why - when all of it is there (v0.2 B3 R1-M4)", function()
    -- Codex round 1 of block 3, M4 - Sven's decision of 16.11.2026, 23:10:
    -- leave it as built. A plan that is incomplete (complete = false, e.g.
    -- a recipe is missing) with every material of the map covered ends
    -- "blocked" with the small window and the reason, and where the plan
    -- says why, that too. With something of the map still open it is no
    -- end: the run farms on.
    local L, d = ns.L, ns.CraftData
    local given
    local saved = { planFor = ns.SkillPlanFor, skill = ns.GetSkill, run = ns.db.activeRun, rank = ns.ProfessionRank, have = d.Have, known = d.Known, targets = ns.db.planTargets }
    local W = IdentityWorld()
    local before = #errors
    local ok, err = pcall(function()
        ns.GetSkill = function(t) if t == "ore" then return 100, 300, 100 end end
        local function Plan(copper, tin, why)
            given = { prof = "Mining", from = 1, target = 75, status = "incomplete", valid = true, complete = false, reliable = true, revision = 9500 + copper + tin,
                items = { [2770] = { need = 60, have = copper, haveKnown = true, missing = math.max(0, 60 - copper) },
                    [2771] = { need = 10, have = tin, haveKnown = true, missing = math.max(0, 10 - tin) } },
                why = why }
        end
        ns.SkillPlanFor = function() return given end
        W.Set({ W.Node("o1731", "Copper Vein", 100, { type = "ore" }), W.Node("o1732", "Tin Vein", 200, { type = "ore" }) })
        W.At(0)
        local _, ends0 = ns.PlanRunLastEnd()
        local hint = _G.GathercraftPlanHint
        local hints0 = hint and hint.shown or 0
        -- incomplete, copper covered, tin open: the run starts and farms the tin - no end
        Plan(60, 0)
        ns.StartRun(ns.PlanFilter("Mining", 75), 1412) W.Wait(1)
        local s = ns.PlanRunState()
        assert(ns.run and s.state == "active" and #ns.run.points == 1 and ns.run.points[1].node.id == "o1732",
            "an incomplete plan with tin still open: the run is " .. tostring(s and s.state) .. " (want active, to the tin vein)")
        fire("BAG_UPDATE_DELAYED") W.Wait(40) fire("BAG_UPDATE_DELAYED") W.Wait(2)
        assert(ns.run and ns.PlanRunState().state == "active" and select(2, ns.PlanRunLastEnd()) == ends0, "an incomplete plan with tin open ended")
        -- the tin is there too: blocked, once, the reason and why the plan is incomplete
        Plan(60, 10, { { code = "stuck", skill = 65 } })
        fire("BAG_UPDATE_DELAYED") W.Wait(2)
        local last, ends = ns.PlanRunLastEnd()
        assert(ns.run == nil and ends == ends0 + 1 and last.kind == "blocked" and last.reasons[1].reason == "plan_incomplete",
            "an incomplete plan with all of the map covered: " .. tostring(last and last.kind))
        hint = _G.GathercraftPlanHint
        assert(hint and hint:IsShown() and hint.shown == hints0 + 1, "the small window did not come once")
        local body = hint.body:GetText()
        assert(body:find(L["the plan is incomplete - see the skill plan"], 1, true), "the window does not say the plan is incomplete: " .. body)
        -- (a Mining plan gets stuck where mining veins is the way on: the skill plan's own words for it)
        assert(body:find((L["From %d on: mine veins to go up (farm run for ore)."]):format(65), 1, true), "the window does not say why: " .. body:gsub("\n", " // "))
        fire("BAG_UPDATE_DELAYED") W.Wait(3)
        assert(hint.shown == hints0 + 1 and select(2, ns.PlanRunLastEnd()) == ends0 + 1, "a second end or window")
        hint:Hide()
        -- asked for with all of it there: no run, the reason in chat - no success
        local mark = #log
        ns.StartRun(ns.PlanFilter("Mining", 75), 1412) W.Wait(1)
        assert(ns.run == nil and select(2, ns.PlanRunLastEnd()) == ends0 + 1, "a run, or an end, for an incomplete plan with everything there")
        local said = false
        for i = mark + 1, #log do if log[i]:find(L["the plan is incomplete - see the skill plan"], 1, true) then said = true end end
        assert(said, "no word that the plan is incomplete")
        -- without a why: the reason alone
        Plan(60, 0)
        ns.StartRun(ns.PlanFilter("Mining", 75), 1412) W.Wait(1)
        Plan(60, 10)
        fire("BAG_UPDATE_DELAYED") W.Wait(2)
        assert(ns.run == nil and hint:IsShown() and hint.body:GetText() == L["the plan is incomplete - see the skill plan"], "without a why: " .. tostring(hint.body:GetText()))
        hint:Hide()
        ns.SkillPlanFor = saved.planFor
        -- the skill plan gives the why with its result: a real plan that gets stuck
        ns.ProfessionRank = function() return 1, 300 end
        d.Known = function() return {} end
        d.Have = function() return 0 end
        local stuck, seen = nil, {}
        for _, prof in ipairs({ "Mining", "Leatherworking", "Cooking", "First Aid", "Alchemy", "Tailoring" }) do
            local plan = ns.SkillPlanCalculate(prof, 1, 300)
            seen[#seen + 1] = prof .. " " .. tostring(plan.status)
            for _, diag in ipairs(plan.diagnostics or {}) do if diag.code == "stuck" and not stuck then stuck = diag end end
            if stuck then break end
        end
        assert(stuck, "test setup: no plan to 300 gets stuck: " .. table.concat(seen, ", "))
        local r = ns.SkillPlanResult()
        local found
        for _, w in ipairs(r.why or {}) do if w.code == "stuck" and w.skill == stuck.skill then found = true end end
        assert(found, "the plan's result does not say where it got stuck")
        assert(#errors == before, "an error: " .. tostring(errors[#errors]))
    end)
    ns.SkillPlanFor, ns.GetSkill, ns.ProfessionRank, d.Have, d.Known, ns.db.planTargets = saved.planFor, saved.skill, saved.rank, saved.have, saved.known, saved.targets
    if ns.run then ns.StopRun(true) end
    for _, name in ipairs({ "GathercraftPlanZones", "GathercraftPlanHint", "GathercraftRunSummary", "GathercraftPlanGathered" }) do if _G[name] then _G[name]:Hide() end end
    ns.db.activeRun = saved.run
    W.Restore()
    if not ok then error(err, 0) end
end)
step("Farm for plan: the list of zones knows the zones with shipped spawn points that are not loaded yet; Go loads one and farms there (v0.2 B3 R1-M5)", function()
    -- Codex round 1 of block 3, M5: only Mulgore loaded, copper needed - the
    -- Barrens with 53 known places were not in the list until they were
    -- loaded. The candidates of a zone not loaded yet come from the spawn
    -- points shipped with the addon (the same data the counts use), with the
    -- same rules: what you can gather, your continent, zones switched off;
    -- places counted once. No world scan, nothing is loaded before "Go".
    local data = GathercraftQuestieData
    local COPPER = 2770
    local given
    local saved = { planFor = ns.SkillPlanFor, skill = ns.GetSkill, run = ns.db.activeRun, tooltip = ns.db.tooltipPrices, zones = ns.db.disabledZones }
    local W = IdentityWorld()
    local before = #errors
    -- a zone of Mulgore's continent with shipped copper places that is not loaded: no nodes, not imported
    local function HasCopper(mapID)
        for id in (data.zones[mapID] or ""):gmatch("(%d+),%d+,%d+") do
            if ns.PlanBaseItem("o" .. id) == COPPER then return true end
        end
    end
    -- two zones of Mulgore's continent with shipped copper places, made "not loaded" for this
    -- step (steps before may have loaded every zone: their nodes and their mark are put aside)
    local target, other
    for mapID in pairs(data.zones) do
        if type(mapID) == "number" and mapID ~= 1412 and ns.GetContinent(mapID) == ns.GetContinent(1412) and HasCopper(mapID) then
            if not target or mapID < target then other, target = target, mapID elseif not other or mapID < other then other = mapID end
        end
    end
    local keepNodes, keepMarks, keepImport = {}, {}, ns.ImportQuestieZone
    local imported = {}
    local ok, err = pcall(function()
        assert(target and other, "test setup: no two zones of Kalimdor with shipped copper places")
        ns.db.spawnZones = ns.db.spawnZones or {}
        for _, z in ipairs({ target, other }) do keepMarks[z] = ns.db.spawnZones[z] ns.db.spawnZones[z] = nil end
        -- (the importer loads a zone once a session: one loaded by a step before gives its nodes
        -- back here, as the import would have)
        ns.ImportQuestieZone = function(mapID, quiet)
            imported[#imported + 1] = mapID
            local n = keepImport(mapID, quiet)
            if n == 0 and keepNodes[mapID] and #keepNodes[mapID] > 0 then
                ns.db.nodes[mapID], ns.db.spawnZones[mapID] = keepNodes[mapID], true
                ns.NotifyNodesChanged()
                n = #keepNodes[mapID]
            end
            return n
        end
        ns.GetSkill = function(t) if t == "ore" then return 300, 300, 300 end end
        ns.SkillPlanFor = function() return given end
        given = { prof = "Mining", from = 1, target = 75, status = "ok", valid = true, complete = true, reliable = true, revision = 9600,
            items = { [COPPER] = { need = 60, have = 0, haveKnown = true, missing = 60 } } }
        W.Set({}) W.At(0) -- (Mulgore: nothing of copper here)
        -- the other zones' nodes out of the way: only Mulgore is loaded
        for mapID, nodes in pairs(ns.db.nodes) do
            if type(mapID) == "number" and mapID ~= 1412 then keepNodes[mapID] = nodes end
        end
        for mapID in pairs(keepNodes) do ns.db.nodes[mapID] = nil end
        ns.NotifyNodesChanged() advance(1)
        ns.db.tooltipPrices = false
        if ns.ItemTooltipSetEnabled then ns.ItemTooltipSetEnabled(false) end
        assert(ns.PlanZoneListShow("Mining", 75), "the list did not open")
        advance(20)
        local list = (ns.PlanZoneListState())
        local row
        for _, z in ipairs(list.zones) do if z.mapID == target then row = z end end
        assert(row, ("the list has %d zones and not %s (%d), whose copper is shipped but not loaded"):format(#list.zones, ns.GetZoneName(target), target))
        -- its number: the different known places, as the counts say - not a sum over the kinds
        local places
        for _, zc in ipairs(ns.SpawnCounts(COPPER) or {}) do if zc.mapID == target then places = zc.total end end
        local copperPlaces
        for _, it in ipairs(row.items) do if it.item == COPPER then copperPlaces = it.places end end
        assert(places and places > 0 and copperPlaces == places, ("%s: %s places in the list, the counts say %s"):format(ns.GetZoneName(target), tostring(copperPlaces), tostring(places)))
        -- nothing was loaded to find it
        assert(not ns.db.nodes[target] or #ns.db.nodes[target] == 0, "the list loaded the zone")
        assert(not (ns.db.spawnZones and ns.db.spawnZones[target]), "the list marked the zone as loaded")
        -- what you cannot gather is no candidate there either: Mining not learned (Herbalism is)
        ns.GetSkill = function(t) if t == "herb" then return 300, 300, 300 end end
        _G.GathercraftPlanZones:Hide()
        given.revision = 9601
        assert(ns.PlanZoneListShow("Mining", 75)) advance(20)
        list = (ns.PlanZoneListState())
        for _, z in ipairs(list.zones) do assert(z.mapID ~= target, "a zone whose copper you cannot gather is listed") end
        ns.GetSkill = function(t) if t == "ore" then return 300, 300, 300 end end
        _G.GathercraftPlanZones:Hide()
        given.revision = 9602
        assert(ns.PlanZoneListShow("Mining", 75)) advance(20)
        -- Go: the zone is loaded as a run there would load it, and the run farms exactly there
        imported = {}
        assert(ns.PlanZoneListGo(target), "Go did not start the run")
        assert(#imported == 1 and imported[1] == target, "Go did not load exactly the zone it starts: " .. table.concat(imported, " "))
        W.Wait(1)
        assert(ns.run and ns.run.plan and ns.run.zone == target and ns.db.activeRun.zone == target, "Go: the run is not in " .. ns.GetZoneName(target))
        assert(ns.db.nodes[target] and #ns.db.nodes[target] > 0, "Go did not load the zone")
        assert(#ns.run.points > 0, "Go: the run has no node to go to")
        for _, p in ipairs(ns.run.points) do assert(p.mapID == target, "Go: a node of another zone in the route") end
        assert(not (ns.db.nodes[other] and #ns.db.nodes[other] > 0), "Go loaded another zone too")
        ns.StopRun(true)
        -- the time it takes to open the list with every zone of the continent shipped and none loaded
        _G.GathercraftPlanZones:Hide()
        ns.db.nodes[target] = nil
        if ns.db.spawnZones then ns.db.spawnZones[target] = nil end
        local t0 = debugprofilestop()
        given.revision = 9603
        assert(ns.PlanZoneListShow("Mining", 75))
        local ms = debugprofilestop() - t0
        advance(20)
        list = (ns.PlanZoneListState())
        note(("MEASURE M5 the list opened with %d zones of the continent from the shipped data: %.1f ms (the mock, not the game)"):format(#list.zones, ms))
        assert(#errors == before, "an error: " .. tostring(errors[#errors]))
    end)
    ns.SkillPlanFor, ns.GetSkill, ns.ImportQuestieZone = saved.planFor, saved.skill, keepImport
    if ns.run then ns.StopRun(true) end
    for _, name in ipairs({ "GathercraftPlanZones", "GathercraftPlanHint", "GathercraftRunSummary", "GathercraftPlanGathered" }) do if _G[name] then _G[name]:Hide() end end
    for mapID, nodes in pairs(keepNodes) do ns.db.nodes[mapID] = nodes end
    if target then ns.db.nodes[target] = keepNodes[target] end
    for z, mark in pairs(keepMarks) do ns.db.spawnZones[z] = mark end
    ns.db.activeRun, ns.db.tooltipPrices = saved.run, saved.tooltip
    W.Restore()
    if ns.ItemTooltipSetEnabled then ns.ItemTooltipSetEnabled(saved.tooltip ~= false) end
    advance(15)
    if not ok then error(err, 0) end
end)
step("Farm for plan: a run and the list of zones that both need a new, big plan take turns - neither drops the other's calculation, both get theirs, then it is quiet (v0.2 B3 R2-M1)", function()
    -- Codex round 2 of block 3, R2-M1: a run and the list of zones that both
    -- need a new plan worked out in parts (no kept plan fits either, after a
    -- change of the bags): each began its calculation anew over the other's -
    -- 50 starts in 5 s, run and list "waiting" for good; the same with one
    -- profession and two targets. Now one calculation runs at a time and
    -- belongs to its plan; another plan waits its turn (once, however often
    -- it asks); a finished plan goes to its own plan before the next begins.
    local d, core = ns.CraftData, ns.PlanCore
    local saved = { clock = ns.SkillPlanClock, rank = ns.ProfessionRank, have = d.Have, known = d.Known, skill = ns.GetSkill, compute = core.Compute,
        targets = ns.db.planTargets, run = ns.db.activeRun, all = d.AllRecipes }
    local W = IdentityWorld()
    local before = #errors
    local win = _G.GathercraftSkillPlan
    if win then win:Hide() end
    local ok, err = pcall(function()
        local base = 0
        local changed = 0 -- (the Alchemy recipes read anew with other numbers: a new state of the Alchemy plans only)
        d.AllRecipes = function(p)
            local out = {}
            for k, v in pairs(saved.all(p)) do out[k] = v end
            if p == "Alchemy" and changed > 0 then
                local keys = {}
                for k in pairs(out) do keys[#keys + 1] = k end
                table.sort(keys)
                for i = 1, changed do out[keys[i]] = out[keys[i]]:gsub(":1:", ":2:", 1) end
            end
            return out
        end
        ns.ProfessionRank = function(p) if p == "Alchemy" or p == "Tailoring" then return 1, 300 end end
        d.Known = function() return {} end
        d.Have = function() return base end
        ns.GetSkill = function(t) if t == "herb" or t == "ore" then return 300, 300, 300 end end
        ns.db.planTargets = nil
        -- the herbs of the Alchemy plans, here
        local nodes, seen = {}, {}
        for _, target in ipairs({ 250, 300 }) do
            local whole = core.Result(saved.compute(ns.SkillPlanSnapshot("Alchemy", 1, target)))
            for id, m in pairs(whole.items) do
                local kinds = m.need > 0 and ns.PlanBaseKinds(id)
                if kinds and not seen[id] then
                    seen[id] = true
                    nodes[#nodes + 1] = W.Node(kinds[1], "Herb " .. id, 100 + 50 * #nodes, { type = "herb" })
                end
            end
        end
        assert(#nodes > 0, "test setup: the Alchemy plans need nothing from the map")
        W.Set(nodes)
        W.At(0)
        local starts = {}
        core.Compute = function(input, pause)
            starts[#starts + 1] = input.prof .. " " .. tostring(input.target)
            return saved.compute(input, pause)
        end
        local function Count(key) local n = 0 for _, k in ipairs(starts) do if k == key then n = n + 1 end end return n end
        local now = 0
        ns.SkillPlanClock = function() now = now + 0.05 return now end -- (a clock that goes on: big plans in many parts)
        local function Wait(s) for _ = 1, math.floor(s / 0.5 + 0.5) do advance(0.5) end end
        local function Waiting() return ns.SkillPlanWaiting and ns.SkillPlanWaiting() or 0 end
        local function Reset()
            if ns.run then ns.StopRun(true) end
            if _G.GathercraftPlanZones then _G.GathercraftPlanZones:Hide() end
            Wait(2)
        end
        local function Quiet(what, listOpen)
            starts = {}
            Wait(5)
            local list = (ns.PlanZoneListState())
            local s = ns.PlanRunState()
            note(("MEASURE R2-M1 %s: %d calculations in 5 s at rest, run %s, list %s, still working out: %s"):format(what, #starts,
                tostring(s and s.state), tostring(listOpen and list and list.state or "closed"), tostring(ns.SkillPlanBusy())))
            assert(#starts == 0, ("%s: %d calculations in 5 s with nothing changed (%s) - want 0"):format(what, #starts, table.concat(starts, ", ")))
            assert(s and s.state == "active", ("%s: the run is %s, want active"):format(what, tostring(s and s.state)))
            for _, row in ipairs(s.rows) do
                assert(row.have == base, ("%s: the run shows %s of %d, the bags hold %d - not the plan of now"):format(what, tostring(row.have), row.item, base))
            end
            if listOpen then
                assert(list and list.state == "ok", ("%s: the list is %s, want ok"):format(what, tostring(list and list.state)))
            end
            assert(not ns.SkillPlanBusy(), what .. ": still working out a plan")
        end
        -- both readers need a new plan worked out in parts, at the same time
        local function Both(runProf, runTarget, listProf, listTarget, what, first)
            Reset()
            ns.StartRun(ns.PlanFilter(runProf, runTarget), 1412)
            assert(ns.run, "test setup: no run of " .. runProf)
            Wait(5)
            assert(ns.PlanZoneListShow(listProf, listTarget), "test setup: the list did not open")
            Wait(20)
            -- the bags change: neither kept plan fits any more; the list is opened anew
            local runKey, listKey = runProf .. " " .. runTarget, listProf .. " " .. listTarget
            starts = {}
            base = base + 1
            fire("BAG_UPDATE_DELAYED")
            _G.GathercraftPlanZones:Hide()
            assert(ns.PlanZoneListShow(listProf, listTarget), "test setup: the list did not open again")
            assert(ns.SkillPlanBusy() and Count(listKey) == 1, "test setup: the list's plan is not worked out in parts")
            -- the run asks again and again while the list's plan is worked out: it
            -- waits its turn, once, and the list's calculation goes on
            for _ = 1, 5 do assert(ns.SkillPlanFor(runProf, runTarget) == nil, "test setup: the run had its new plan at once") end
            assert(Count(listKey) == 1 and Count(runKey) == 0,
                ("%s: the run asked 5 times - %d calculations of %s and %d of %s, want 1 and 0 (the run's asking drops the list's)"):format(what, Count(listKey), listKey, Count(runKey), runKey))
            assert(Waiting() == 1, ("%s: the run asked 5 times and waits %d times, want once"):format(what, Waiting()))
            -- the run's own plan changes while it waits (its recipes read anew): it
            -- still waits once, with the newer state (two professions: the list's
            -- plan does not read the run's recipes)
            if runProf ~= listProf then
                changed = changed + 1
                assert(ns.SkillPlanFor(runProf, runTarget) == nil, "test setup: the run had its new plan at once")
                assert(Waiting() == 1 and Count(runKey) == 0, ("%s: the run's state changed while it waited - %d plans wait, want 1"):format(what, Waiting()))
            end
            -- the list's calculation finishes before anyone looks
            advance(0.01)
            if first == "list" then
                -- the list takes its plan: then the run's turn comes by itself
                local listPlan = ns.SkillPlanFor(listProf, listTarget)
                assert(listPlan and listPlan.target == listTarget and Count(listKey) == 1, what .. ": the list did not get its finished plan")
                advance(0.01)
                assert(Count(runKey) == 1 and Waiting() == 0, ("%s: after the list's plan was given out the run's turn did not come (%d calculations of %s, %d waiting)"):format(what, Count(runKey), runKey, Waiting()))
            else
                -- the run looks first: the finished plan goes to the list, then the run's turn
                assert(ns.SkillPlanFor(runProf, runTarget) == nil, "test setup: the run had its new plan before its turn")
                local listPlan = ns.SkillPlanFor(listProf, listTarget)
                assert(listPlan and listPlan.prof == listProf and listPlan.target == listTarget and Count(listKey) == 1,
                    ("%s: the list's finished plan did not go to the list when the run looked first (%d calculations of %s)"):format(what, Count(listKey), listKey))
            end
            Wait(20)
            note(("MEASURE R2-M1 %s: %d calculations to settle (%d %s, %d %s)"):format(what, #starts, Count(runKey), runKey, Count(listKey), listKey))
            assert(Count(runKey) == 1 and Count(listKey) == 1,
                ("%s: %d calculations of %s and %d of %s after one change, want one each"):format(what, Count(runKey), runKey, Count(listKey), listKey))
            Quiet(what, true)
        end
        -- 1. Codex's case: Alchemy 300 for the run, Tailoring 300 for the list
        Both("Alchemy", 300, "Tailoring", 300, "two professions", "list")
        -- 2. one profession, two targets: Alchemy 300 for the run, 250 for the list
        Both("Alchemy", 300, "Alchemy", 250, "one profession, two targets", "run")
        -- 3. the run's plan is kept and fits, the list's is not there yet: only the list's is worked out
        Reset()
        starts = {}
        ns.StartRun(ns.PlanFilter("Alchemy", 300), 1412)
        assert(ns.run, "test setup: no run of Alchemy")
        assert(ns.PlanZoneListShow("Tailoring", 275), "test setup: the list did not open")
        Wait(20)
        assert(Count("Alchemy 300") == 0 and Count("Tailoring 275") == 1,
            ("one plan kept, one not there: %d of Alchemy 300 and %d of Tailoring 275 - want 0 and 1"):format(Count("Alchemy 300"), Count("Tailoring 275")))
        Quiet("one plan kept, one new", true)
        -- 4. the control: the list closes while both are worked out - the run gets its plan
        Reset()
        ns.StartRun(ns.PlanFilter("Alchemy", 300), 1412)
        Wait(5)
        assert(ns.PlanZoneListShow("Tailoring", 300), "test setup: the list did not open")
        Wait(20)
        base = base + 1
        fire("BAG_UPDATE_DELAYED")
        _G.GathercraftPlanZones:Hide()
        assert(ns.PlanZoneListShow("Tailoring", 300), "test setup: the list did not open again")
        Wait(1)
        _G.GathercraftPlanZones:Hide()
        Wait(20)
        Quiet("the list closed while both were worked out", false)
        -- 5. the run's own plan goes out of date while it is worked out: begun
        -- anew for the same plan, and what is given out is the plan of now -
        -- the run looks itself, or the list looks first
        Reset()
        ns.StartRun(ns.PlanFilter("Alchemy", 300), 1412)
        Wait(10)
        assert(ns.PlanZoneListShow("Tailoring", 300), "test setup: the list did not open")
        Wait(10)
        local given = {}
        local function Heard(result)
            if result and result.prof == "Alchemy" and result.target == 300 then
                local _, m = next(result.items)
                given[#given + 1] = m and m.have
            end
        end
        table.insert(ns.skillPlanListeners, Heard)
        local okInner, errInner = pcall(function()
            for _, first in ipairs({ "run", "list" }) do
                base = base + 1
                fire("BAG_UPDATE_DELAYED")
                starts = {}
                advance(0.3)
                assert(ns.SkillPlanBusy() and Count("Alchemy 300") == 1, "test setup: the run's plan is not on its way")
                -- the bags change again before the run took its plan
                base = base + 1
                given = {}
                if first == "run" then fire("BAG_UPDATE_DELAYED") else ns.SkillPlanFor("Tailoring", 300) end
                Wait(20)
                assert(Count("Alchemy 300") == 2, ("a plan out of date before it was taken (%s looks first): %d calculations, want 2 (begun once anew)"):format(first, Count("Alchemy 300")))
                for _, have in ipairs(given) do
                    assert(have == base, ("%s looks first: a plan of before was given out after the bags changed (%s, the bags hold %d)"):format(first, tostring(have), base))
                end
                assert(#given >= 1, first .. " looks first: the plan of now was not given out")
                Quiet("the run's plan out of date, " .. first .. " looks first", true)
            end
        end)
        tDeleteItem(ns.skillPlanListeners, Heard)
        if not okInner then error(errInner, 0) end
        -- 6. the window comes first - and the list's calculation is put aside, not
        -- dropped: half done, or done and not taken yet; it goes on when the window closes
        for _, how in ipairs({ "half done", "done" }) do
            Reset()
            ns.StartRun(ns.PlanFilter("Alchemy", 300), 1412)
            Wait(5)
            assert(ns.PlanZoneListShow("Tailoring", 300), "test setup: the list did not open")
            Wait(20)
            starts = {}
            base = base + 1
            _G.GathercraftPlanZones:Hide()
            assert(ns.PlanZoneListShow("Tailoring", 300), "test setup: the list did not open again")
            assert(ns.SkillPlanBusy() and Count("Tailoring 300") == 1, "test setup: the list's plan is not worked out in parts")
            if how == "done" then advance(0.01) end
            ns.ShowSkillPlan("Alchemy")
            win = _G.GathercraftSkillPlan
            assert(win and win:IsShown() and #starts == Count("Tailoring 300") + 1, "test setup: the window did not work out its plan (" .. table.concat(starts, ", ") .. ")")
            Wait(2)
            win:Hide()
            Wait(20)
            assert(Count("Tailoring 300") == 1, ("the window came first while the list's plan was %s: %d calculations of the list's plan, want 1 (put aside, not dropped)"):format(how, Count("Tailoring 300")))
            Quiet("the window came first, the list's plan " .. how, true)
        end
        assert(#errors == before, "an error: " .. tostring(errors[#errors]))
    end)
    ns.SkillPlanClock, ns.ProfessionRank, d.Have, d.Known, ns.GetSkill, core.Compute = saved.clock, saved.rank, saved.have, saved.known, saved.skill, saved.compute
    d.AllRecipes = saved.all
    if ns.run then ns.StopRun(true) end
    for _, name in ipairs({ "GathercraftPlanZones", "GathercraftPlanHint", "GathercraftRunSummary", "GathercraftPlanGathered", "GathercraftSkillPlan" }) do if _G[name] then _G[name]:Hide() end end
    ns.db.planTargets, ns.db.activeRun = saved.targets, saved.run
    W.Restore()
    advance(2)
    if not ok then error(err, 0) end
end)
step("Farm for plan: while the run waits, \"Plan x/y\" is the whole count of the last decided state - both numbers; a new count comes with the next decision (v0.2 B3 R2-N1)", function()
    -- Codex round 2 of block 3, R2-N1: an active plan with two materials,
    -- one covered - "Plan 1/2". The loot window opens and the plan read next
    -- has only one material: while the run waits the window said "Plan 1/1"
    -- (the done ones kept, the number of all from the rows not decided yet).
    local given
    local saved = { planFor = ns.SkillPlanFor, skill = ns.GetSkill, run = ns.db.activeRun, compact = ns.db.panelCompact, hidden = ns.db.runPanelHidden }
    local W = IdentityWorld()
    local before = #errors
    local ok, err = pcall(function()
        ns.db.panelCompact, ns.db.runPanelHidden = nil, nil
        ns.GetSkill = function(t) if t == "ore" then return 300, 300, 300 end end
        local revision = 9500
        local function Plan(items)
            revision = revision + 1
            given = { prof = "Mining", from = 1, target = 75, status = "ok", valid = true, complete = true, reliable = true, revision = revision, items = {} }
            for item, m in pairs(items) do
                given.items[item] = { need = m[1], have = m[2], haveKnown = true, missing = math.max(0, m[1] - m[2]) }
            end
        end
        ns.SkillPlanFor = function() return given end
        W.Set({ W.Node("o1731", "Copper Vein", 100, { type = "ore" }), W.Node("o1732", "Tin Vein", 200, { type = "ore" }),
            W.Node("o1735", "Iron Deposit", 300, { type = "ore" }) })
        W.At(0)
        local TICK = "ReadyCheck-Ready"
        local PLAN = ns.L["Plan %d/%d"]
        -- active: copper covered, tin open
        Plan({ [2770] = { 60, 60 }, [2771] = { 10, 0 } })
        ns.StartRun(ns.PlanFilter("Mining", 75), 1412) W.Wait(1) advance(1.5)
        local a = ns.PlanPanelLines()
        assert(ns.run and ns.PlanRunState().state == "active" and a.done == 1 and a.total == 2, "test setup: not an active run at Plan 1/2: " .. tostring(a and a.compact))
        -- the loot window opens; the plan read next has only the copper
        fire("LOOT_OPENED")
        Plan({ [2770] = { 60, 60 } })
        fire("BAG_UPDATE_DELAYED") W.Wait(0.5) advance(1)
        assert(ns.run and ns.PlanRunState().state == "waiting", "test setup: the run does not wait: " .. tostring(ns.PlanRunState() and ns.PlanRunState().state))
        local b = ns.PlanPanelLines()
        assert(b.done == 1 and b.total == 2 and b.compact == PLAN:format(1, 2),
            ("while waiting the count is %d/%d (%s) - want the last decided one, 1/2"):format(b.done, b.total, b.compact))
        assert(not b.compact:find(TICK, 1, true), "while waiting the slim line has the tick: " .. b.compact)
        ns.db.panelCompact = true
        ns.PanelLayout() advance(1.5)
        local panel = _G.GathercraftPanel
        assert(panel.title:GetText() == PLAN:format(1, 2), "while waiting the slim window says " .. tostring(panel.title:GetText()) .. ", want Plan 1/2")
        ns.db.panelCompact = nil
        ns.PanelLayout() advance(0.5)
        -- still waiting, the plan read now has three materials: still 1/2
        Plan({ [2770] = { 60, 60 }, [2771] = { 10, 0 }, [2772] = { 5, 0 } })
        fire("BAG_UPDATE_DELAYED") W.Wait(0.5) advance(1)
        assert(ns.PlanRunState().state == "waiting", "test setup: the run no longer waits")
        b = ns.PlanPanelLines()
        assert(b.done == 1 and b.total == 2, ("still waiting, three materials read: %d/%d, want 1/2"):format(b.done, b.total))
        -- the loot window closes: decided - the new count
        fire("LOOT_CLOSED") W.Wait(3)
        local c = ns.PlanPanelLines()
        assert(ns.run and ns.PlanRunState().state == "active" and c.done == 1 and c.total == 3 and c.compact == PLAN:format(1, 3),
            ("decided again: %s, want active at Plan 1/3"):format(tostring(c and c.compact)))
        ns.StopRun(true)
        assert(#errors == before, "an error: " .. tostring(errors[#errors]))
    end)
    ns.SkillPlanFor, ns.GetSkill = saved.planFor, saved.skill
    if ns.run then ns.StopRun(true) end
    for _, name in ipairs({ "GathercraftPlanZones", "GathercraftPlanHint", "GathercraftRunSummary", "GathercraftPlanGathered" }) do if _G[name] then _G[name]:Hide() end end
    ns.db.activeRun, ns.db.panelCompact, ns.db.runPanelHidden = saved.run, saved.compact, saved.hidden
    if ns.PanelLayout then ns.PanelLayout() end
    W.Restore()
    if not ok then error(err, 0) end
end)
step("Skill plan: a finished plan another reader settles first is looked at with the skill as it is now - its rank, where it was read, whether it can be read (v0.2 B3 R3 A-N1)", function()
    -- Codex round 3 of block 3, A-N1: Alchemy was worked out from skill 1 for
    -- the run; the skill rose to 2, and the list of another plan looked first.
    -- The fresh look saw the change, but what was begun anew was begun with
    -- the skill of before, and given out "from 1". Now the fresh look and
    -- what is begun anew take the skill as it is now: its rank, whether it is
    -- read now or only seen last, and - not read at all - nothing.
    local d, core = ns.CraftData, ns.PlanCore
    local saved = { rank = ns.ProfessionRank, have = d.Have, known = d.Known, compute = core.Compute, look = ns.PlanRunLook, lines = GetNumSkillLines }
    local published = {}
    local skill = { rank = 1, source = nil, readable = true }
    local function Heard(r)
        if r.prof == "Alchemy" then
            published[#published + 1] = { from = r.from, source = r.skillSource, rank = skill.rank, now = skill.source or "current", readable = skill.readable }
        end
    end
    local ok, err = pcall(function()
        ns.ProfessionRank = function(p)
            if p == "Alchemy" then
                if not skill.readable then return nil end -- (no skill given, and the list cannot be read: below)
                if skill.source then return skill.rank, nil, "lastSeen", time() - 60 end
                return skill.rank, 300
            end
            if p == "Tailoring" then return 1, 300 end
        end
        -- (a skill seen last, or none: the list of skills cannot be read either)
        GetNumSkillLines = function() if skill.source or not skill.readable then return 0 end return saved.lines() end
        d.Have = function() return 0 end
        d.Known = function() return {} end
        core.Compute = function(input, pause)
            if pause then coroutine.yield() end -- (two parts: finished in the frame after the first)
            return saved.compute(input)
        end
        ns.PlanRunLook = function() end -- (the run does not look by itself: the list looks first)
        table.insert(ns.skillPlanListeners, Heard)
        ns.SkillPlanRunner(true)
        local function Settled(rank, change)
            skill.rank, skill.source, skill.readable = rank, nil, true
            published = {}
            ns.SkillPlanFor("Alchemy", 75)
            advance(0.01) -- (finished, not taken)
            change()
            for _ = 1, 8 do ns.SkillPlanFor("Tailoring", 75) advance(0.02) end
            return published
        end
        -- (1) Codex's case: from 1, the skill 2 meanwhile - given out from 2
        local list = Settled(1, function() skill.rank = 2 end)
        assert(#list > 0, "test setup: nothing given out")
        for _, p in ipairs(list) do
            assert(p.from == p.rank, ("given out from the skill of before: from %s, the skill is %s"):format(tostring(p.from), tostring(p.rank)))
        end
        -- (2) read when it was begun, only seen last now: given out as a plan from the skill seen last
        list = Settled(3, function() skill.source = "lastSeen" end)
        assert(#list > 0, "test setup: nothing given out (seen last)")
        for _, p in ipairs(list) do
            assert(p.source == p.now and p.from == p.rank, ("given out as a skill %s, it is %s now"):format(tostring(p.source), tostring(p.now)))
        end
        -- (3) it cannot be read now: nothing given out from the skill of before, nothing left over
        list = Settled(4, function() skill.readable = false end)
        for _, p in ipairs(list) do
            assert(p.readable, "given out from skill " .. tostring(p.from) .. " while it cannot be read")
        end
        assert(not ns.SkillPlanBusy(), "a skill that cannot be read: something is still worked out or waits")
        -- read again: its own reader gets its plan from the skill now
        skill.readable, published = true, {}
        for _ = 1, 4 do ns.SkillPlanFor("Alchemy", 75) advance(0.02) end
        assert(#published > 0 and published[#published].from == 4, "read again: no plan from the skill now")
    end)
    ns.SkillPlanRunner(false)
    tDeleteItem(ns.skillPlanListeners, Heard)
    ns.ProfessionRank, d.Have, d.Known, core.Compute, ns.PlanRunLook, GetNumSkillLines = saved.rank, saved.have, saved.known, saved.compute, saved.look, saved.lines
    if not ok then error(err, 0) end
end)
-- (end of the "Farm for plan" steps, v0.2 building block 3)
-- 0.3, disenchanting step 1 (concept "Entzauberungswerte" 4.1/4.2, gate G1,
-- order 17.11.2026): the diagnosis /gcr detest. It prints what the client
-- tells about a disenchant; it does nothing in the game and keeps nothing.
local function DetestLines(from) -- what /gcr detest printed after log line from, without its "detest "
    local out = {}
    for i = from + 1, #log do
        local text = log[i]:match("^PRINT detest (.*)$")
        if text then out[#out + 1] = text end
    end
    return out
end
local function DetestEvents() -- the events its frame is registered for, sorted
    local list, frame = {}, _G.GathercraftDisenchantTest
    for e, frames in pairs(eventFrames) do if frame and frames[frame] then list[#list + 1] = e end end
    table.sort(list)
    return list
end
local function DetestCopy(v, depth)
    if type(v) ~= "table" then return v end
    depth = (depth or 0) + 1
    assert(depth < 40, "the saved data is nested too deep to copy")
    local c = {}
    for k, x in pairs(v) do c[k] = DetestCopy(x, depth) end
    return c
end
-- the first place where a and b differ (deep, both ways), or nil
local function DetestDiff(a, b, path)
    if type(a) ~= type(b) then return ("%s: %s, now %s"):format(path, type(a), type(b)) end
    if type(a) ~= "table" then
        if a ~= b and not (a ~= a and b ~= b) then return ("%s: %s, now %s"):format(path, tostring(a), tostring(b)) end
        return nil
    end
    for k, x in pairs(a) do
        local d = DetestDiff(x, b[k], path .. "." .. tostring(k))
        if d then return d end
    end
    for k in pairs(b) do if a[k] == nil then return path .. "." .. tostring(k) .. ": new" end end
end
local DETEST_EVENTS = { "BAG_UPDATE_DELAYED", "ITEM_LOCK_CHANGED", "LOOT_CLOSED", "LOOT_OPENED", "LOOT_READY", "LOOT_SLOT_CLEARED",
    "UNIT_SPELLCAST_FAILED", "UNIT_SPELLCAST_FAILED_QUIET", "UNIT_SPELLCAST_INTERRUPTED", "UNIT_SPELLCAST_SENT",
    "UNIT_SPELLCAST_START", "UNIT_SPELLCAST_STOP", "UNIT_SPELLCAST_SUCCEEDED" }
-- what would act in the game: none of it may be called while it is on
local DETEST_ACTIONS = { "CastSpellByName", "CastSpellByID", "CastSpell", "SpellTargetItem", "SpellStopTargeting", "UseContainerItem",
    "PickupContainerItem", "UseItemByName", "LootSlot", "ConfirmLootSlot", "CloseLoot", "SetCVar", "StaticPopup_Show", "TargetUnit",
    "ClearTarget", "RunMacroText", "SendChatMessage", "UseAction", "DeleteCursorItem", "ClearCursor" }
step("Disenchant test: /gcr detest on for the session and off - the API part once, its events only while on, nothing saved, nothing done (0.3 B5 step 1, part 1)", function()
    -- The order's parts 1 and 2, concept test 12. On or off is a local: the
    -- saved data stays the same (a deep compare, while on and after), and at
    -- load nothing is registered - after /reload it is off. A function the
    -- client lacks is a "no", an event it lacks is named: no error.
    local frame = _G.GathercraftDisenchantTest
    assert(frame, "no frame GathercraftDisenchantTest")
    assert(#DetestEvents() == 0, "registered before it was turned on: " .. table.concat(DetestEvents(), ", "))
    local function Listeners() local n = 0 for _, frames in pairs(eventFrames) do for _ in pairs(frames) do n = n + 1 end end return n end
    local function Has(lines, want) for _, l in ipairs(lines) do if l == want then return true end end return false end
    local function With(base, extra) local t = {} for k, v in pairs(base or {}) do t[k] = v end for k, v in pairs(extra) do t[k] = v end return t end
    local saved = { g = {}, item = C_Item, container = C_Container, friends = C_FriendList, reg = methods.RegisterEvent, unit = methods.RegisterUnitEvent }
    local globals = { "IsFishingLoot", "ItemLocation", "issecretvalue" }
    for _, k in ipairs(globals) do saved.g[k] = _G[k] end
    for _, k in ipairs(DETEST_ACTIONS) do saved.g[k] = _G[k] end
    local acts = {}
    local ok, err = pcall(function()
        -- the client as this test wants it: some functions there, some not
        IsFishingLoot = function() return false end
        ItemLocation = { CreateFromBagAndSlot = function(_, b, s) return { b = b, s = s } end } -- (no CreateFromEquipmentSlot)
        issecretvalue = nil
        C_Item = With(saved.item, { GetItemGUID = function() end, DoesItemExist = function() return true end })
        C_Item.IsLocked = nil
        C_Container = With(saved.container, { GetContainerItemInfo = function(b, s) if b == 0 and s == 1 then return { itemID = 6256, isLocked = false } end end })
        C_FriendList = With(saved.friends, { GetFriendInfoByIndex = function() end })
        C_FriendList.GetNumFriends = nil
        for _, k in ipairs(DETEST_ACTIONS) do
            local orig = saved.g[k]
            _G[k] = function(...) acts[#acts + 1] = k if orig then return orig(...) end end
        end
        C_Container.UseContainerItem = function() acts[#acts + 1] = "C_Container.UseContainerItem" end
        C_Container.PickupContainerItem = function() acts[#acts + 1] = "C_Container.PickupContainerItem" end
        -- a client without UNIT_SPELLCAST_FAILED_QUIET: registering it is an error there
        local function Register(f, e, ...)
            if e == "UNIT_SPELLCAST_FAILED_QUIET" then error('Attempt to register unknown event "' .. e .. '"') end
            return saved.reg(f, e, ...)
        end
        methods.RegisterEvent, methods.RegisterUnitEvent = Register, Register
        local db, before = DetestCopy(ns.db), Listeners()
        -- something else than on or off: how to use it, nothing turned on
        local mark = #log
        slash("detest what")
        local lines = DetestLines(mark)
        assert(#lines == 1 and lines[1]:find("/gcr detest off", 1, true), "an unknown word: " .. table.concat(lines, " / "))
        assert(#DetestEvents() == 0, "an unknown word turned it on")
        -- on
        mark = #log
        slash("detest")
        lines = DetestLines(mark)
        local all = table.concat(lines, "\n")
        assert(lines[1] and lines[1]:find("^on: ") and lines[1]:find("nothing is saved", 1, true) and lines[1]:find("/gcr detest off", 1, true), "the first line: " .. tostring(lines[1]))
        for _, want in ipairs({ "GetBuildInfo: (4) 1.60.1, 70450, Oct, 16001",
            "API GetLootSourceInfo: yes", "API IsFishingLoot: yes", "API C_Item.GetItemGUID: yes", "API ItemLocation: yes",
            "API ItemLocation:CreateFromBagAndSlot: yes", "API ItemLocation:CreateFromEquipmentSlot: no", "API C_Item.DoesItemExist: yes",
            "API C_Item.IsLocked: no", "API C_Container.GetContainerItemInfo: yes", "API C_Item.GetItemInfoInstant: yes", "API GetItemInfo: yes",
            "API issecretvalue: no", "API C_FriendList.GetNumFriends: no", "API C_FriendList.GetFriendInfoByIndex: yes",
            "GetContainerItemInfo: a table, isLocked false (bag 0 slot 1)", "spell 13262: name Spell13262, IsPlayerSpell false",
            "event not available: UNIT_SPELLCAST_FAILED_QUIET", "listening to 12 of 13 events" }) do
            assert(Has(lines, want), "not printed: " .. want .. "\n" .. all)
        end
        local want = {}
        for _, e in ipairs(DETEST_EVENTS) do if e ~= "UNIT_SPELLCAST_FAILED_QUIET" then want[#want + 1] = e end end
        assert(table.concat(DetestEvents(), ",") == table.concat(want, ","), "registered: " .. table.concat(DetestEvents(), ", "))
        assert(Listeners() == before + 12, ("listeners of all frames: %d, before %d"):format(Listeners(), before))
        local diff = DetestDiff(db, ns.db, "ns.db")
        assert(not diff, "turned on, the saved data changed: " .. tostring(diff))
        -- on again: said so, the API part not again, nothing registered twice
        mark = #log
        slash("detest on")
        lines = DetestLines(mark)
        assert(#lines == 1 and lines[1]:find("already on", 1, true), "on again: " .. table.concat(lines, " / "))
        assert(Listeners() == before + 12, "on again: listeners " .. Listeners())
        -- off: none of its events left, the saved data as before
        mark = #log
        slash("detest off")
        lines = DetestLines(mark)
        assert(#lines == 1 and lines[1] == "off", "off: " .. table.concat(lines, " / "))
        assert(#DetestEvents() == 0, "off, still registered: " .. table.concat(DetestEvents(), ", "))
        assert(Listeners() == before, ("off: listeners of all frames %d, before %d"):format(Listeners(), before))
        mark = #log
        slash("detest off")
        lines = DetestLines(mark)
        assert(#lines == 1 and lines[1]:find("already off", 1, true), "off again: " .. table.concat(lines, " / "))
        diff = DetestDiff(db, ns.db, "ns.db")
        assert(not diff, "after a session, the saved data changed: " .. tostring(diff))
        assert(#acts == 0, "it acted in the game: " .. table.concat(acts, ", "))
    end)
    methods.RegisterEvent, methods.RegisterUnitEvent = saved.reg, saved.unit
    C_Item, C_Container, C_FriendList = saved.item, saved.container, saved.friends
    for _, k in ipairs(globals) do _G[k] = saved.g[k] end
    for _, k in ipairs(DETEST_ACTIONS) do _G[k] = saved.g[k] end
    if not ok then pcall(slash, "detest off") end
    if not ok then error(err, 0) end
end)
step("Disenchant test: a disenchant's events with their time and every value, the loot's source against the locked item, <secret>, 40 lines a loot window (0.3 B5 step 1, part 2)", function()
    -- The order's parts 1 and 2, concept 4.2 and test 12. The mock flow of a
    -- disenchant - SENT, the lock, SUCCEEDED, LOOT_READY with the item's
    -- GUID as the loot's source - shows "source matches locked item"; of two
    -- swords alike, the one cast on is named. A cast broken off leaves its
    -- sword in the bag. Hidden values print as <secret> and are never
    -- compared; a loot window shows at most 40 lines, then "... N more".
    local SWORD = "|cff1eff00|Hitem:15210::::::::12:::::::|h[Raider Shortsword]|h|r"
    local G1, G2, G3 = "Item-5826-0-4000000000000001", "Item-5826-0-4000000000000002", "Item-5826-0-4000000000000003"
    local bag = { [0] = {
        [1] = { id = 6256, guid = G1, link = "|cffffffff|Hitem:6256::::::::12:::::::|h[Fishing Pole]|h|r" },
        [2] = { id = 15210, guid = G2, link = SWORD },
        [3] = { id = 15210, guid = G3, link = SWORD },
    } }
    local function At(b, s) return bag[b] and bag[b][s] end
    local function With(base, extra) local t = {} for k, v in pairs(base or {}) do t[k] = v end for k, v in pairs(extra) do t[k] = v end return t end
    local SECRET = newproxy(true)
    local meta = getmetatable(SECRET)
    for _, k in ipairs({ "__index", "__newindex", "__concat", "__lt", "__le", "__eq", "__add", "__sub", "__mul",
        "__div", "__mod", "__unm", "__len", "__call", "__tostring" }) do
        meta[k] = function() error("attempt to use a secret value", 2) end
    end
    local saved = { item = C_Item, container = C_Container, g = {} }
    local globals = { "IsFishingLoot", "ItemLocation", "issecretvalue", "GetLootSourceInfo", "GetLootSlotInfo", "GetNumLootItems",
        "GetInventoryItemID", "GetInventoryItemLink" }
    for _, k in ipairs(globals) do saved.g[k] = _G[k] end
    for _, k in ipairs(DETEST_ACTIONS) do saved.g[k] = _G[k] end
    local keepLoot, acts = loot, {}
    -- the lines since mark, the time in front cut off (and checked: two decimals)
    local function Lines(mark)
        local out = {}
        for _, l in ipairs(DetestLines(mark)) do
            local t, rest = l:match("^(%d+%.%d%d) (.*)$")
            if t then
                assert(not l:match("^%d+%.%d%d%d"), "a time with more than two decimals: " .. l)
                out[#out + 1] = rest
            else
                assert(not l:match("^%d"), "a time not with two decimals: " .. l)
                out[#out + 1] = l
            end
        end
        return out
    end
    local function Same(got, want, what)
        for i = 1, math.max(#got, #want) do
            assert(got[i] == want[i], ("%s, line %d:\n  got  %s\n  want %s"):format(what, i, tostring(got[i]), tostring(want[i])))
        end
    end
    local function Loot(list) -- { item, qty, sources... }
        loot = {}
        for i, l in ipairs(list) do loot[i] = { item = l[1], qty = l[2], sources = { n = #l - 2, unpack(l, 3) } } end
    end
    local ok, err = pcall(function()
        IsFishingLoot = function() return false end
        ItemLocation = { CreateFromBagAndSlot = function(_, b, s) return { b = b, s = s } end }
        issecretvalue = function(v) return rawequal(v, SECRET) end
        C_Item = With(saved.item, {
            GetItemGUID = function(loc) local it = At(loc.b, loc.s) return it and it.guid end,
            DoesItemExist = function(loc) return At(loc.b, loc.s) ~= nil end,
            IsLocked = function(loc) local it = At(loc.b, loc.s) return it and it.locked or false end })
        C_Container = With(saved.container, {
            GetContainerNumSlots = function(b) return b == 0 and 16 or 0 end,
            GetContainerItemID = function(b, s) local it = At(b, s) return it and it.id end,
            GetContainerItemLink = function(b, s) local it = At(b, s) return it and it.link end,
            GetContainerItemInfo = function(b, s) local it = At(b, s) if it then return { itemID = it.id, hyperlink = it.link, isLocked = it.locked or false, stackCount = 1 } end end })
        GetLootSourceInfo = function(i) local l = loot[i] if l then return unpack(l.sources, 1, l.sources.n) end end
        GetLootSlotInfo = function(i) return 134400, "Item", loot[i] and loot[i].qty or 0 end
        -- an empty equipment slot, set here (steps before this one leave their own fishing pole in it)
        GetInventoryItemID, GetInventoryItemLink = function() return nil end, nil
        for _, k in ipairs(DETEST_ACTIONS) do
            local orig = saved.g[k]
            _G[k] = function(...) acts[#acts + 1] = k if orig then return orig(...) end end
        end
        local db = DetestCopy(ns.db)
        slash("detest")
        advance(0.37)
        -- (1) a cast at the first sword, broken off: its lock comes and goes, the sword stays
        local mark = #log
        local CAST1, CAST2 = "Cast-3-5826-0-1-13262-0000A0B0C1", "Cast-3-5826-0-1-13262-0000A0B0C2"
        fire("UNIT_SPELLCAST_SENT", "player", "Raider Shortsword", CAST1, 13262)
        bag[0][2].locked = true
        fire("ITEM_LOCK_CHANGED", 0, 2)
        fire("UNIT_SPELLCAST_START", "player", CAST1, 13262)
        fire("UNIT_SPELLCAST_INTERRUPTED", "player", CAST1, 13262)
        fire("UNIT_SPELLCAST_STOP", "player", CAST1, 13262)
        bag[0][2].locked = nil
        fire("ITEM_LOCK_CHANGED", 0, 2)
        fire("BAG_UPDATE_DELAYED")
        -- another player's cast (a unit that is not you): not shown
        fire("UNIT_SPELLCAST_SUCCEEDED", "party1", "Cast-3-5826-0-1-13262-0000FFFFFF", 13262)
        -- an equipment slot's lock (no bag slot): named, read with what the client has, not kept
        fire("ITEM_LOCK_CHANGED", 16)
        Same(Lines(mark), {
            "UNIT_SPELLCAST_SENT (4) player, Raider Shortsword, " .. CAST1 .. ", 13262 - Spell13262",
            "ITEM_LOCK_CHANGED (2) 0, 2 | bag 0 slot 2: link " .. SWORD .. ", id 15210, guid " .. G2 .. ", exists true, locked true, info.isLocked true",
            "UNIT_SPELLCAST_START (3) player, " .. CAST1 .. ", 13262 - Spell13262",
            "UNIT_SPELLCAST_INTERRUPTED (3) player, " .. CAST1 .. ", 13262 - Spell13262",
            "UNIT_SPELLCAST_STOP (3) player, " .. CAST1 .. ", 13262 - Spell13262",
            "ITEM_LOCK_CHANGED (2) 0, 2 | bag 0 slot 2: link " .. SWORD .. ", id 15210, guid " .. G2 .. ", exists true, locked false, info.isLocked false",
            "BAG_UPDATE_DELAYED (0)",
            "ITEM_LOCK_CHANGED (1) 16 | equipment slot 16: link no API, id nil, guid no API, exists no API, locked no API, info.isLocked -",
        }, "a cast broken off")
        -- (2) the second sword is disenchanted: its GUID is the loot's source
        mark = #log
        local t0 = GetTime()
        fire("UNIT_SPELLCAST_SENT", "player", "Raider Shortsword", CAST2, 13262)
        bag[0][3].locked = true
        fire("ITEM_LOCK_CHANGED", 0, 3)
        fire("UNIT_SPELLCAST_START", "player", CAST2, 13262)
        advance(1.5)
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", CAST2, 13262)
        fire("UNIT_SPELLCAST_STOP", "player", CAST2, 13262)
        Loot({ { 10940, 2, G3, 1 }, { 10938, 1, G3, 1 } })
        fire("LOOT_READY", false)
        fire("LOOT_OPENED", false)
        bag[0][3] = nil
        fire("ITEM_LOCK_CHANGED", 0, 3)
        fire("LOOT_SLOT_CLEARED", 1)
        fire("LOOT_SLOT_CLEARED", 2)
        fire("BAG_UPDATE_DELAYED")
        fire("LOOT_CLOSED")
        loot = {}
        local window = {
            "  loot: 2 slots, IsFishingLoot false",
            "  locked item bag 0 slot 2 " .. SWORD .. " " .. G2 .. ": still in its slot (same GUID)",
            "  locked item bag 0 slot 3 " .. SWORD .. " " .. G3 .. ": still in its slot (same GUID)",
            "  slot 1: link |Hitem:10940::|h | GetLootSlotInfo (3) 134400, Item, 2 | GetLootSourceInfo (2) " .. G3 .. ", 1",
            "  slot 1: source matches locked item bag 0 slot 3 " .. SWORD,
            "  slot 2: link |Hitem:10938::|h | GetLootSlotInfo (3) 134400, Item, 1 | GetLootSourceInfo (2) " .. G3 .. ", 1",
            "  slot 2: source matches locked item bag 0 slot 3 " .. SWORD,
            "  sources: 1 different, 1 of them a locked or gone item",
        }
        local want = {
            "UNIT_SPELLCAST_SENT (4) player, Raider Shortsword, " .. CAST2 .. ", 13262 - Spell13262",
            "ITEM_LOCK_CHANGED (2) 0, 3 | bag 0 slot 3: link " .. SWORD .. ", id 15210, guid " .. G3 .. ", exists true, locked true, info.isLocked true",
            "UNIT_SPELLCAST_START (3) player, " .. CAST2 .. ", 13262 - Spell13262",
            "UNIT_SPELLCAST_SUCCEEDED (3) player, " .. CAST2 .. ", 13262 - Spell13262",
            "UNIT_SPELLCAST_STOP (3) player, " .. CAST2 .. ", 13262 - Spell13262",
            "LOOT_READY (1) false",
        }
        for _, l in ipairs(window) do want[#want + 1] = l end
        want[#want + 1] = "LOOT_OPENED (1) false"
        for _, l in ipairs(window) do want[#want + 1] = l end
        for _, l in ipairs({
            "ITEM_LOCK_CHANGED (2) 0, 3 | bag 0 slot 3: link nil, id nil, guid -, exists false, locked -, info.isLocked nil",
            "LOOT_SLOT_CLEARED (1) 1",
            "LOOT_SLOT_CLEARED (1) 2",
            "BAG_UPDATE_DELAYED (0) | gone from bag 0 slot 3: " .. SWORD .. ", id 15210, guid " .. G3,
            "LOOT_CLOSED (0)",
        }) do want[#want + 1] = l end
        Same(Lines(mark), want, "a disenchant")
        -- the times: GetTime with two decimals, 1.5 s from the start to the success
        local times = {}
        for _, l in ipairs(DetestLines(mark)) do local t = l:match("^(%d+%.%d%d) UNIT_SPELLCAST_") if t then times[#times + 1] = tonumber(t) end end
        assert(#times == 4 and math.abs(times[1] - t0) < 0.006 and math.abs(times[3] - times[1] - 1.5) < 0.006, "the times: " .. table.concat(times, " "))
        -- (3) a late loot of the sword that is gone, and a beast's loot: the gone one is named, the beast is no item
        mark = #log
        Loot({ { 10940, 1, G3, 1 } })
        fire("LOOT_READY", true)
        fire("LOOT_CLOSED")
        Loot({ { 2318, 1, "Creature-0-1-1-1-3035-0000AA0001", 1 } })
        fire("LOOT_READY", true)
        fire("LOOT_CLOSED")
        loot = {}
        Same(Lines(mark), {
            "LOOT_READY (1) true",
            "  loot: 1 slots, IsFishingLoot false",
            "  locked item bag 0 slot 2 " .. SWORD .. " " .. G2 .. ": still in its slot (same GUID)",
            "  slot 1: link |Hitem:10940::|h | GetLootSlotInfo (3) 134400, Item, 1 | GetLootSourceInfo (2) " .. G3 .. ", 1",
            "  slot 1: source matches gone item bag 0 slot 3 " .. SWORD,
            "  sources: 1 different, 1 of them a locked or gone item",
            "LOOT_CLOSED (0)",
            "LOOT_READY (1) true",
            "  loot: 1 slots, IsFishingLoot false",
            "  locked item bag 0 slot 2 " .. SWORD .. " " .. G2 .. ": still in its slot (same GUID)",
            "  slot 1: link |Hitem:2318::|h | GetLootSlotInfo (3) 134400, Item, 1 | GetLootSourceInfo (2) Creature-0-1-1-1-3035-0000AA0001, 1",
            "  sources: 1 different, 0 of them a locked or gone item",
            "LOOT_CLOSED (0)",
        }, "a late loot and a beast's")
        -- (4) hidden values (a dungeon, a fight): <secret>, never compared -
        -- the fishing pole's GUID and the loot's source are the same hidden
        -- value, and still no "matches"
        mark = #log
        bag[0][1].guid, bag[0][1].locked = SECRET, true
        fire("UNIT_SPELLCAST_SENT", "player", SECRET, SECRET, 13262)
        fire("ITEM_LOCK_CHANGED", 0, 1)
        fire("ITEM_LOCK_CHANGED", SECRET, 1)
        Loot({ { 10940, SECRET, SECRET, SECRET } })
        fire("LOOT_READY", SECRET)
        fire("LOOT_CLOSED")
        GetNumLootItems = function() return SECRET end
        fire("LOOT_READY", false)
        fire("LOOT_CLOSED")
        GetNumLootItems = saved.g.GetNumLootItems
        loot = {}
        Same(Lines(mark), {
            "UNIT_SPELLCAST_SENT (4) player, <secret>, <secret>, 13262 - Spell13262",
            "ITEM_LOCK_CHANGED (2) 0, 1 | bag 0 slot 1: link |cffffffff|Hitem:6256::::::::12:::::::|h[Fishing Pole]|h|r, id 6256, guid <secret>, exists true, locked true, info.isLocked true",
            "ITEM_LOCK_CHANGED (2) <secret>, 1 | bag <secret> slot 1: link nil, id nil, guid -, exists false, locked -, info.isLocked nil",
            "LOOT_READY (1) <secret>",
            "  loot: 1 slots, IsFishingLoot false",
            "  locked item bag 0 slot 2 " .. SWORD .. " " .. G2 .. ": still in its slot (same GUID)",
            "  locked item bag 0 slot 1 |cffffffff|Hitem:6256::::::::12:::::::|h[Fishing Pole]|h|r <secret>: still in its slot (same item id)",
            "  slot 1: link |Hitem:10940::|h | GetLootSlotInfo (3) 134400, Item, <secret> | GetLootSourceInfo (2) <secret>, <secret>",
            "  slot 1: 2 hidden source values, not compared",
            "  sources: 0 different, 0 of them a locked or gone item",
            "LOOT_CLOSED (0)",
            "LOOT_READY (1) false",
            "  loot: <secret> slots, IsFishingLoot false",
            "  locked item bag 0 slot 2 " .. SWORD .. " " .. G2 .. ": still in its slot (same GUID)",
            "  locked item bag 0 slot 1 |cffffffff|Hitem:6256::::::::12:::::::|h[Fishing Pole]|h|r <secret>: still in its slot (same item id)",
            "LOOT_CLOSED (0)",
        }, "hidden values")
        bag[0][1].guid, bag[0][1].locked = G1, nil
        -- (5) a loot window of 50 slots: 40 lines, then how many more; the
        -- next window has its own 40 (off and on again: nothing kept)
        slash("detest off")
        slash("detest")
        local many = {}
        for i = 1, 50 do many[i] = { 2318, 1, ("Creature-0-1-1-1-3035-0000BB%04d"):format(i), 1 } end
        Loot(many)
        mark = #log
        fire("LOOT_READY", false)
        local lines = Lines(mark)
        assert(#lines == 40, "lines of a loot window: " .. #lines)
        assert(lines[1] == "LOOT_READY (1) false" and lines[40]:find("^  slot 38: "), "the 40 lines: " .. lines[1] .. " ... " .. lines[40])
        fire("LOOT_OPENED", false)
        assert(#Lines(mark) == 40, "the window's second event got past the 40: " .. #Lines(mark))
        fire("LOOT_CLOSED")
        lines = Lines(mark)
        -- (53 lines a READY or OPENED: the event, the count, 50 slots, the sources)
        assert(#lines == 42 and lines[41] == "... 66 more" and lines[42] == "LOOT_CLOSED (0)", "the end of the window: " .. tostring(lines[41]) .. " / " .. tostring(lines[42]))
        Loot({ { 2318, 1, "Creature-0-1-1-1-3035-0000BB0001", 1 } })
        mark = #log
        fire("LOOT_READY", true)
        fire("LOOT_CLOSED")
        loot = {}
        Same(Lines(mark), {
            "LOOT_READY (1) true",
            "  loot: 1 slots, IsFishingLoot false",
            "  slot 1: link |Hitem:2318::|h | GetLootSlotInfo (3) 134400, Item, 1 | GetLootSourceInfo (2) Creature-0-1-1-1-3035-0000BB0001, 1",
            "  sources: 1 different, 0 of them a locked or gone item",
            "LOOT_CLOSED (0)",
        }, "the next window")
        -- (6) off: none of its events say anything
        slash("detest off")
        mark = #log
        bag[0][2].locked = true
        fire("UNIT_SPELLCAST_SENT", "player", "Raider Shortsword", CAST1, 13262)
        fire("ITEM_LOCK_CHANGED", 0, 2)
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", CAST1, 13262)
        Loot({ { 10940, 1, G2, 1 } })
        fire("LOOT_READY", false)
        fire("LOOT_CLOSED")
        fire("BAG_UPDATE_DELAYED")
        loot = {}
        assert(#DetestLines(mark) == 0, "off, and still printed: " .. table.concat(DetestLines(mark), " / "))
        local diff = DetestDiff(db, ns.db, "ns.db")
        assert(not diff, "after the session, the saved data changed: " .. tostring(diff))
        assert(#acts == 0, "it acted in the game: " .. table.concat(acts, ", "))
    end)
    C_Item, C_Container, loot = saved.item, saved.container, keepLoot
    for _, k in ipairs(globals) do _G[k] = saved.g[k] end
    for _, k in ipairs(DETEST_ACTIONS) do _G[k] = saved.g[k] end
    if not ok then pcall(slash, "detest off") end
    if not ok then error(err, 0) end
end)
step("Disenchant test: a bag info table the client hides is not opened, one that cannot be read is no error, an API part that breaks still listens (0.3 B5 step 1, R1 M1)", function()
    -- Codex detest round 1, M1: GetContainerItemInfo's table was read before
    -- any hidden-value check. Now, where the client has issecretvalue, the
    -- table itself is checked first (<secret>, not opened); without it a
    -- normal table stays readable, and a field that cannot be read ends as
    -- "unreadable", not as a Lua error - when turning it on and at
    -- ITEM_LOCK_CHANGED. An error in the API part does not leave it on
    -- without listeners: it says so and still registers.
    local SECRET = newproxy(true)
    local meta = getmetatable(SECRET)
    for _, k in ipairs({ "__index", "__newindex", "__concat", "__lt", "__le", "__eq", "__add", "__sub", "__mul",
        "__div", "__mod", "__unm", "__len", "__call", "__tostring" }) do
        meta[k] = function() error("attempt to use a secret value", 2) end
    end
    local HIDDEN = setmetatable({}, { __index = function() error("SECRET TABLE INDEX") end })
    local saved = { info = C_Container.GetContainerItemInfo, slots = C_Container.GetContainerNumSlots, id = C_Container.GetContainerItemID,
        link = C_Container.GetContainerItemLink, secret = issecretvalue, friends = C_FriendList }
    local current -- what GetContainerItemInfo hands out
    local function Lines(mark)
        local out = {}
        for _, l in ipairs(DetestLines(mark)) do out[#out + 1] = l:gsub("^%d+%.%d%d ", "") end
        return out
    end
    local function Has(lines, want) for _, l in ipairs(lines) do if l == want then return true end end return false end
    local ok, err = pcall(function()
        local db = DetestCopy(ns.db)
        C_Container.GetContainerNumSlots = function(b) return b == 0 and 1 or 0 end
        C_Container.GetContainerItemID = function(b, s) if b == 0 and s == 1 then return 15210 end end
        C_Container.GetContainerItemLink = function(b, s) if b == 0 and s == 1 then return "SWORD" end end
        C_Container.GetContainerItemInfo = function() return current end
        local function Case(what, value, hiddenValues, atOn, atLock)
            current = value
            issecretvalue = hiddenValues and function(v)
                for _, h in ipairs(hiddenValues) do if rawequal(v, h) then return true end end
                return false
            end or nil
            local mark = #log
            slash("detest")
            local lines = Lines(mark)
            assert(Has(lines, "GetContainerItemInfo: " .. atOn), what .. ", turned on: " .. table.concat(lines, " / "))
            assert(lines[#lines] == "listening to 13 of 13 events" and #DetestEvents() == 13, what .. ": listening to " .. #DetestEvents())
            mark = #log
            fire("ITEM_LOCK_CHANGED", 0, 1)
            lines = Lines(mark)
            local tail = ", info.isLocked " .. atLock
            assert(#lines == 1 and lines[1]:sub(-#tail) == tail, what .. ", ITEM_LOCK_CHANGED: " .. table.concat(lines, " / "))
            slash("detest off")
            assert(#DetestEvents() == 0, what .. ": still listening after off")
        end
        Case("a normal table, no issecretvalue", { isLocked = true, itemID = 15210 }, nil, "a table, isLocked true (bag 0 slot 1)", "true")
        Case("a hidden field", { isLocked = SECRET, itemID = 15210 }, { SECRET }, "a table, isLocked <secret> (bag 0 slot 1)", "<secret>")
        Case("the whole table hidden", HIDDEN, { HIDDEN }, "<secret> (bag 0 slot 1)", "<secret>")
        Case("a table that cannot be read, no issecretvalue", HIDDEN, nil, "a table that cannot be read (bag 0 slot 1)", "unreadable")
        Case("a table that cannot be read, issecretvalue says no", HIDDEN, {}, "a table that cannot be read (bag 0 slot 1)", "unreadable")
        -- an error in the API part (a client table that throws when looked into): said, and it still listens
        current, issecretvalue = { isLocked = false }, nil
        C_FriendList = setmetatable({}, { __index = function() error("FRIENDS INDEX") end })
        local mark = #log
        slash("detest")
        C_FriendList = saved.friends
        local lines = Lines(mark)
        local told = false
        for _, l in ipairs(lines) do if l:find("^API part stopped by an error: ") and l:find("FRIENDS INDEX", 1, true) then told = true end end
        assert(told, "the API part's error is not said: " .. table.concat(lines, " / "))
        assert(lines[#lines] == "listening to 13 of 13 events" and #DetestEvents() == 13,
            "after the API part's error: " .. tostring(lines[#lines]) .. ", " .. #DetestEvents() .. " events")
        mark = #log
        slash("detest")
        lines = Lines(mark)
        assert(#lines == 1 and lines[1]:find("already on", 1, true), "on after the API part's error, then on again: " .. table.concat(lines, " / "))
        slash("detest off")
        assert(#DetestEvents() == 0, "off after the API part's error: still listening")
        local diff = DetestDiff(db, ns.db, "ns.db")
        assert(not diff, "the saved data changed: " .. tostring(diff))
    end)
    C_Container.GetContainerItemInfo, C_Container.GetContainerNumSlots, C_Container.GetContainerItemID = saved.info, saved.slots, saved.id
    C_Container.GetContainerItemLink, issecretvalue, C_FriendList = saved.link, saved.secret, saved.friends
    if not ok then pcall(slash, "detest off") end
    if not ok then error(err, 0) end
end)
step("Disenchant test: outside a loot window at most 20 lines in 2 s, then how many were skipped; a disenchant's casts and a loot window still show (0.3 B5 step 1, R1 M2)", function()
    -- Codex detest round 1, M2: outside a loot window there was no limit -
    -- 200 lock changes made 200 lines. Now at most 20 lines in 2 s there,
    -- then "... N lines skipped" once the 2 s are over (or a loot window
    -- begins, or it is turned off). A disenchant's cast events have 10 lines
    -- of their own in those 2 s; a loot window keeps its own 40. The API part
    -- and the answers to the command are not limited.
    local saved = { id = C_Container.GetContainerItemID, link = C_Container.GetContainerItemLink }
    local keepLoot = loot
    local LOCK = "ITEM_LOCK_CHANGED (2) 0, 1 | "
    local function Count(lines, text) local n = 0 for _, l in ipairs(lines) do if l:find(text, 1, true) then n = n + 1 end end return n end
    local ok, err = pcall(function()
        -- (empty bags: a lock change keeps nothing to compare with)
        C_Container.GetContainerItemID = function() return nil end
        C_Container.GetContainerItemLink = function() return nil end
        slash("detest")
        advance(3)
        -- Codex' probe: 200 lock changes, the time standing still
        local mark = #log
        for _ = 1, 200 do fire("ITEM_LOCK_CHANGED", 0, 1) end
        local lines = DetestLines(mark)
        assert(#lines == 20 and Count(lines, LOCK) == 20, "200 lock changes: " .. #lines .. " lines")
        advance(2.1)
        lines = DetestLines(mark)
        assert(#lines == 21 and lines[21] == "... 180 lines skipped", "after the 2 s: " .. #lines .. " lines, the last " .. tostring(lines[#lines]))
        -- BAG_UPDATE_DELAYED in a burst
        mark = #log
        for _ = 1, 50 do fire("BAG_UPDATE_DELAYED") end
        advance(2.1)
        lines = DetestLines(mark)
        assert(#lines == 21 and Count(lines, "BAG_UPDATE_DELAYED (0)") == 20 and lines[21] == "... 30 lines skipped",
            "50 bag updates: " .. #lines .. " lines, the last " .. tostring(lines[#lines]))
        -- in the middle of a burst: a disenchant's casts show, another spell's cast is skipped with the rest;
        -- a loot window that begins says first how many were skipped, then shows with its own 40
        mark = #log
        for _ = 1, 100 do fire("ITEM_LOCK_CHANGED", 0, 1) end
        fire("UNIT_SPELLCAST_SENT", "player", "Raider Shortsword", "Cast-DE-1", 13262)
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", "Cast-DE-1", 13262)
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", "Cast-FB-1", 133)
        fire("UNIT_SPELLCAST_INTERRUPTED", "player", "Cast-DE-2", 13262)
        fire("UNIT_SPELLCAST_FAILED", "player", "Cast-DE-2", 13262)
        loot = { { guid = "Creature-0-1-1-1-3035-0000AA0099", item = 2318, qty = 1 } }
        fire("LOOT_READY", false)
        fire("LOOT_CLOSED")
        loot = {}
        lines = DetestLines(mark)
        assert(Count(lines, LOCK) == 20, "lock lines in the burst: " .. Count(lines, LOCK))
        for i, want in ipairs({ "UNIT_SPELLCAST_SENT (4) player, Raider Shortsword, Cast-DE-1, 13262 - Spell13262",
            "UNIT_SPELLCAST_SUCCEEDED (3) player, Cast-DE-1, 13262 - Spell13262", "UNIT_SPELLCAST_INTERRUPTED (3) player, Cast-DE-2, 13262 - Spell13262",
            "UNIT_SPELLCAST_FAILED (3) player, Cast-DE-2, 13262 - Spell13262" }) do
            local l = lines[20 + i] or ""
            assert(l:gsub("^%d+%.%d%d ", "") == want, ("the disenchant's line %d: %s"):format(i, l))
        end
        assert(Count(lines, "Cast-FB-1") == 0, "another spell's cast got past the limit")
        assert(lines[25] == "... 81 lines skipped", "before the loot window: " .. tostring(lines[25]))
        assert((lines[26] or ""):find("^%d+%.%d%d LOOT_READY %(1%) false$") and (lines[#lines] or ""):find("^%d+%.%d%d LOOT_CLOSED %(0%)$"),
            "the loot window: " .. tostring(lines[26]) .. " ... " .. tostring(lines[#lines]))
        -- a disenchant's casts have 10 lines of their own in 2 s
        advance(2.1)
        mark = #log
        for i = 1, 12 do fire("UNIT_SPELLCAST_SUCCEEDED", "player", "Cast-DE-x" .. i, 13262) end
        advance(2.1)
        lines = DetestLines(mark)
        assert(#lines == 11 and Count(lines, "Cast-DE-x") == 10 and lines[11] == "... 2 lines skipped", "12 disenchant casts: " .. #lines .. " lines, the last " .. tostring(lines[#lines]))
        -- the next 2 s have their own 20; turned off, what was skipped is said first
        mark = #log
        for _ = 1, 25 do fire("ITEM_LOCK_CHANGED", 0, 1) end
        slash("detest off")
        lines = DetestLines(mark)
        assert(#lines == 22 and Count(lines, LOCK) == 20 and lines[21] == "... 5 lines skipped" and lines[22] == "off",
            "25 lock changes, then off: " .. #lines .. " lines, " .. tostring(lines[21]) .. " / " .. tostring(lines[22]))
        -- (the timer of those 2 s, after off: nothing more)
        mark = #log
        advance(2.1)
        assert(#DetestLines(mark) == 0, "after off: " .. table.concat(DetestLines(mark), " / "))
        -- (ns.db is compared in parts 1 and 2 and in M1; here the seconds that go
        -- by let the sync write its own query times into it)
    end)
    C_Container.GetContainerItemID, C_Container.GetContainerItemLink, loot = saved.id, saved.link, keepLoot
    if not ok then pcall(slash, "detest off") end
    if not ok then error(err, 0) end
end)
step("Disenchant test: an equipment slot's lock is shown with its item, not kept to compare with (0.3 B5 step 1, R1 N1)", function()
    -- Codex detest round 1, N1 (decided: shown only): equipment is not
    -- disenchanted, and the 8 kept items stay for bag items. Codex' case: a
    -- fishing pole in slot 16, its lock changes, then a loot window - no
    -- "locked item equipment slot 16" in it.
    local saved = { id = GetInventoryItemID, link = GetInventoryItemLink }
    local keepLoot = loot
    local ok, err = pcall(function()
        GetInventoryItemID = function(_, s) if s == 16 then return 6256 end end
        GetInventoryItemLink = function(_, s) if s == 16 then return "POLE" end end
        slash("detest")
        local mark = #log
        fire("ITEM_LOCK_CHANGED", 16)
        loot = { { guid = "Creature-0-1-1-1-3035-0000AA0077", item = 2318, qty = 1 } }
        fire("LOOT_READY", false)
        fire("BAG_UPDATE_DELAYED")
        fire("LOOT_CLOSED")
        loot = {}
        local lines = DetestLines(mark)
        assert((lines[1] or ""):find("ITEM_LOCK_CHANGED (1) 16 | equipment slot 16: link POLE, id 6256, guid ", 1, true), "shown: " .. tostring(lines[1]))
        for _, l in ipairs(lines) do
            assert(not l:find("locked item", 1, true) and not l:find("gone from", 1, true), "kept to compare with: " .. l)
        end
        slash("detest off")
    end)
    GetInventoryItemID, GetInventoryItemLink, loot = saved.id, saved.link, keepLoot
    if not ok then pcall(slash, "detest off") end
    if not ok then error(err, 0) end
end)
step("Saved run: only the character that saved it takes it up again - a plan run and a normal run; another character leaves it as it is (0.2 live test N1)", function()
    -- Sven's live test 18.11.: the saved data is the same for every character
    -- of the account. A plan run of the shaman went on on the druid; a normal
    -- run of the druid (Burning Steppes) was taken up on the shaman
    -- (Kalimdor): no nodes there, StopRun - and the saved run was gone, for
    -- the druid too. Now a saved run notes its character (the player's GUID)
    -- and only that character takes it up; another one leaves it as it is
    -- (no message), and its StopRun does not remove it.
    local saved = { guid = UnitGUID, run = ns.db.activeRun, start = ns.StartRun, resume = ns.PlanRunResume, debug = ns.db.debug }
    local SHAMAN, DRUID = "Player-5826-0A1B2C3D", "Player-5826-0F0E0D0C"
    local me = SHAMAN
    local calls = {}
    local function Login()
        calls = {}
        fire("PLAYER_LOGIN")
        advance(3)
    end
    local ok, err = pcall(function()
        UnitGUID = function(u) if u == "player" then return me end return saved.guid(u) end
        if ns.run then ns.StopRun(true) end
        -- a run notes whose it is
        player.map, player.x, player.y = 1412, 0.45, 0.72
        ns.StartRun("herb", 1412)
        assert(ns.run and ns.db.activeRun and ns.db.activeRun.owner == SHAMAN, "the saved run does not note its character: " .. tostring(ns.db.activeRun and ns.db.activeRun.owner))
        ns.StopRun(true)
        assert(ns.db.activeRun == nil, "your own StopRun leaves your saved run")
        -- what is taken up: watched, not done
        ns.StartRun = function(...) calls[#calls + 1] = { "run", ... } end
        ns.PlanRunResume = function(s) calls[#calls + 1] = { "plan", s } return true end
        local PLAN = { filter = "plan:v1:alchemy:75:1", zone = 1412, owner = SHAMAN }
        local NORMAL = { filter = "herb", zone = 1416, owner = DRUID }
        for _, case in ipairs({ { PLAN, SHAMAN, DRUID, "plan" }, { NORMAL, DRUID, SHAMAN, "run" } }) do
            local entry, owner, other, kind = case[1], case[2], case[3], case[4]
            -- the same character: taken up
            ns.db.activeRun, me = entry, owner
            Login()
            assert(#calls == 1 and calls[1][1] == kind, kind .. " run, the same character: not taken up")
            -- another character: not taken up, the saved run stays as it was
            ns.db.activeRun, me = entry, other
            Login()
            assert(#calls == 0, kind .. " run of another character taken up")
            assert(ns.db.activeRun == entry and entry.owner == owner, kind .. " run of another character: not left as it was")
            -- its stop (the stop command with no run of its own) leaves it too
            ns.StopRun()
            assert(ns.db.activeRun == entry, kind .. " run: another character's StopRun removed it")
            -- back to its character: taken up
            me = owner
            Login()
            assert(#calls == 1 and calls[1][1] == kind, kind .. " run, back to its character: not taken up")
        end
        -- the player's GUID cannot be read (nil or a hidden value): nothing taken up, nothing removed
        local SECRET = newproxy(true)
        local keepSecret = issecretvalue
        for _, unreadable in ipairs({ false, true }) do
            ns.db.activeRun = NORMAL
            me = unreadable and SECRET or nil
            issecretvalue = function(v) return rawequal(v, SECRET) end
            Login()
            issecretvalue = keepSecret
            assert(#calls == 0 and ns.db.activeRun == NORMAL, "the GUID can't be read: taken up or removed")
        end
        -- a run saved by a version before (no character): whose it is can't be told -
        -- it is not taken up (it might be another character's) and goes
        me = SHAMAN
        ns.db.activeRun = { filter = "herb", zone = 1412 }
        Login()
        assert(#calls == 0 and ns.db.activeRun == nil, "a saved run without its character: taken up or kept")
        -- the whole way, a normal run: the druid's run stays while the shaman plays, the druid gets it back
        ns.StartRun, ns.PlanRunResume = saved.start, saved.resume
        me = DRUID
        ns.StartRun("herb", 1412)
        local druidRun = ns.db.activeRun
        me = SHAMAN
        ns.run = nil -- (logged out: no run in memory, the saved one only)
        Login()
        assert(ns.run == nil and ns.db.activeRun == druidRun, "the druid's run on the shaman: taken up or gone")
        me = DRUID
        Login()
        assert(ns.run and ns.run.filter == "herb" and ns.db.activeRun and ns.db.activeRun.owner == DRUID, "the druid did not get its run back")
        ns.StopRun(true)
        -- another character starts its own run: that one is saved (the one saved before is replaced)
        ns.db.activeRun, me = druidRun, SHAMAN
        ns.StartRun("herb", 1412)
        assert(ns.db.activeRun and ns.db.activeRun.owner == SHAMAN and ns.db.activeRun ~= druidRun, "the shaman's own run was not saved")
        ns.StopRun(true)
    end)
    UnitGUID, ns.StartRun, ns.PlanRunResume, ns.db.debug = saved.guid, saved.start, saved.resume, saved.debug
    if ns.run then pcall(ns.StopRun, true) end
    ns.db.activeRun = saved.run
    if not ok then error(err, 0) end
end)
-- 0.2.0, data (Sven, 20.11.2026): starter spots for the new Forever zones from
-- the gathers of Gathercraft players (own finds and confirmed shares; no
-- minimap guesses, no unconfirmed reports, no chests), the way the Zephras
-- spots came in (tools/export_starter.py's format, Starter.lua imports them).
local FOREVER_ZONES = { [2548] = "Riverglades", [2482] = "Mount Hyjal", [2521] = "Zephras Isle" }
-- objects the spawn data does not know, with the kind's name they ship under
local FOREVER_KINDS = { o562111 = "Poor Copper Vein", o656160 = "Wilted Peacebloom", o656161 = "Stunted Silverleaf",
    o566786 = "Mountain Silversage", o566788 = "Dreamfoil", o566779 = "Thorium Ore", o626718 = "Dented Chest", o626752 = "Dented Chest" }
local function StarterHash(zones) -- the rows as text in file order, h = (h * 31 + byte) % 2147483647
    local h, n = 0, 0
    local ids = {}
    for z in pairs(GathercraftStarterData.nodes) do if not zones or zones[z] then ids[#ids + 1] = z end end
    table.sort(ids)
    for _, z in ipairs(ids) do
        for _, e in ipairs(GathercraftStarterData.nodes[z]) do
            local text = ("%s,%s,%d,%d,%d,%d,%s;"):format(e[1], e[2], e[3], e[4], e[5], e[6], e[7])
            for i = 1, #text do h = (h * 31 + text:byte(i)) % 2147483647 end
            n = n + 1
        end
    end
    return h, n
end
-- 0.2.2 P1 point 5 (Fahrplan: before every release the starter data are
-- refreshed from the newest saved data, never losing a spot): built by
-- tools/export_starter.py --refresh from a copy of Sven's saved data of
-- 21.11.2026. Every row shipped before stays (tools/starter_shipped.txt
-- lists every row ever shipped); new rows only in Riverglades, Mount Hyjal
-- and Zephras Isle, from real gathers (own and confirmed by sync, herbs and
-- ores, no quest objects); a shipped spot other players confirmed live
-- counts 1 + their number as its reporters. No player names. Shen'dralas
-- stays out (10 spots).
step("Starter data 0.2.2: every spot shipped before stays; new spots in Riverglades, Mount Hyjal and Zephras Isle; confirmed spots count their reporters; kind names only (0.2.2 P1 point 5)", function()
    local data = GathercraftStarterData
    assert(data and data.version == "forever-2026-11-21", "starter data version " .. tostring(data and data.version))
    -- rows per zone and type
    local want = { [1411] = { o = 1 }, [1412] = { h = 24, o = 30 }, [2482] = { h = 81, o = 59 }, [2521] = { h = 285, o = 151, c = 4 },
        [2548] = { h = 125, o = 137 } }
    for z, list in pairs(data.nodes) do
        assert(want[z], "a zone that should not be in the starter data: " .. tostring(z))
        local got = {}
        for _, e in ipairs(list) do got[e[2]] = (got[e[2]] or 0) + 1 end
        for t, n in pairs(want[z]) do assert(got[t] == n, ("zone %d type %s: %s rows, want %d"):format(z, t, tostring(got[t]), n)) end
        for t, n in pairs(got) do assert(want[z][t], ("zone %d: %d rows of type %s"):format(z, n, t)) end
    end
    for z in pairs(want) do assert(data.nodes[z], "zone missing: " .. z) end
    assert(not data.nodes[2652], "Shen'dralas has starter rows (left out: too few spots)")
    -- every row ever shipped is in it: object, type, place and item as shipped
    local f = assert(io.open(ROOT .. "/tools/starter_shipped.txt"), "no tools/starter_shipped.txt")
    local ledger = f:read("*a") f:close()
    local have = {}
    for z, list in pairs(data.nodes) do
        for _, e in ipairs(list) do have[("%d,%s,%s,%d,%d,%d"):format(z, e[1], e[2], e[3], e[4], e[5])] = true end
    end
    local rows, lost = 0, {}
    for line in ledger:gmatch("[^\n]+") do
        if not line:match("^#") then
            rows = rows + 1
            if not have[line] then lost[#lost + 1] = line end
        end
    end
    assert(rows >= 897 and #lost == 0, ("%d of the %d rows ever shipped are missing, e.g. %s"):format(#lost, rows, tostring(lost[1])))
    -- the zones of the beta data (only their counts changed), and the whole file as built (fingerprints)
    local h, n = StarterHash({ [1411] = true, [1412] = true })
    assert(h == 1776672293 and n == 55, ("Durotar and Mulgore changed: %d (%d rows)"):format(h, n))
    h, n = StarterHash()
    assert(h == 75843913 and n == 897, ("the starter data are not the ones built: %d (%d rows)"):format(h, n))
    -- every row: a game object, its type, a place on the map, a count of 1 or
    -- more (1 + the players who confirmed it), and the name of its kind
    local kinds, counted = GathercraftQuestieData.kinds, 0
    for z, list in pairs(data.nodes) do
        for _, e in ipairs(list) do
            local id, t, x, y, item, reporters, name = unpack(e)
            assert(#e == 7 and id:match("^o%d+$") and (t == "h" or t == "o" or t == "c"), ("zone %d: a row of another shape: %s"):format(z, tostring(id)))
            assert(x >= 0 and x <= 10000 and y >= 0 and y <= 10000 and item >= 0 and reporters >= 1 and reporters <= 9, ("zone %d %s: place, item or count"):format(z, id))
            if reporters > 1 then counted = counted + 1 end
            local k = kinds[id]
            local kindName = k and k[3] or FOREVER_KINDS[id]
            assert(kindName and name == kindName, ("zone %d: %s named %q, its kind is %s"):format(z, id, name, tostring(kindName)))
            assert(not k or k[1] == t, ("zone %d: %s is a %s, the row says %s"):format(z, id, tostring(k and k[1]), t))
            assert(t ~= "c" or z == 2521, ("zone %d: a chest (only herbs and ores come in)"):format(z))
        end
    end
    assert(counted == 53, ("%d rows count more than one reporter, 53 were confirmed live"):format(counted))
end)
step("Starter data 0.2.0: a fresh profile gets every spot of the new zones; an old profile only what it lacks, once; pins and routes use them; never shared (0.2.0 data)", function()
    local data = GathercraftStarterData
    local saved = { nodes = ns.db.nodes, version = ns.db.starterVersion, map = player.map, x = player.x, y = player.y,
        herb = PROFS[1][2], ore = PROFS[2][2] }
    local loader
    for f in pairs(eventFrames["PLAYER_LOGOUT"] or {}) do
        if eventFrames["PLAYER_LOGIN"][f] and not (eventFrames["UNIT_SPELLCAST_CHANNEL_STOP"] or {})[f] then loader = f end
    end
    assert(loader, "test setup: starter loader not found")
    local function Login() loader.__scripts.OnEvent(loader, "PLAYER_LOGIN") end
    local function Count(z)
        local c = 0
        for _, n in ipairs(ns.db.nodes[z] or {}) do if n.source == "starter" then c = c + 1 end end
        return c
    end
    local ok, err = pcall(function()
        -- a fresh profile: every row of the new zones comes in, marked as starter data
        ns.db.nodes, ns.db.starterVersion = {}, nil
        ns.ForgetSeenKinds() ns.NotifyNodesChanged() -- (a new node table: the zone indexes go)
        Login()
        assert(ns.db.starterVersion == data.version, "version not remembered: " .. tostring(ns.db.starterVersion))
        for z, name in pairs(FOREVER_ZONES) do
            assert(Count(z) == #data.nodes[z], ("%s: %d of %d spots imported"):format(name, Count(z), #data.nodes[z]))
        end
        -- an old profile (beta data of 23.10. imported) that knows some spots already: only the others come in, once
        local some = {}
        for i = 1, 20 do
            local e = data.nodes[2548][i]
            some[#some + 1] = { id = e[1], type = e[2] == "h" and "herb" or "ore", name = e[7], x = e[3] / 10000, y = e[4] / 10000, count = 2, last = 1 }
        end
        ns.db.nodes, ns.db.starterVersion = { [2548] = some }, "beta-2026-10-23"
        ns.ForgetSeenKinds() ns.NotifyNodesChanged()
        local mark = #log
        Login()
        assert(Count(2548) == #data.nodes[2548] - 20 and #ns.db.nodes[2548] == #data.nodes[2548], ("an old profile in Riverglades: %d starter spots, %d in all"):format(Count(2548), #ns.db.nodes[2548]))
        assert(ns.db.starterVersion == data.version, "an old profile: version not taken")
        Login()
        assert(#ns.db.nodes[2548] == #data.nodes[2548] and Count(2482) == #data.nodes[2482], "a second login imported again")
        -- pins in Riverglades
        player.map, player.x, player.y = 2548, data.nodes[2548][1][3] / 10000, data.nodes[2548][1][4] / 10000
        ns.NotifyNodesChanged() advance(2)
        local pinned = 0
        for _, f in ipairs(allFrames) do
            if f.node and f.node.source == "starter" then -- (a pin frame of the node, as the beta data step looks for them)
                for _, n in ipairs(ns.db.nodes[2548]) do if n == f.node then pinned = pinned + 1 break end end
            end
        end
        assert(pinned > 0, "no pin for a starter spot of Riverglades")
        -- routes: herbs and ores of Riverglades, with skill for all of them
        PROFS[1][2], PROFS[2][2] = 300, 300
        for _, filter in ipairs({ "herb", "ore" }) do
            ns.StartRun(filter, 2548) advance(1)
            assert(ns.run and ns.run.path and #ns.run.path > 0, "no " .. filter .. " route in Riverglades")
            local starter = 0
            for _, p in ipairs(ns.run.path) do
                assert(p.mapID == 2548, "a route point outside Riverglades: " .. tostring(p.mapID))
                if p.node.source == "starter" then starter = starter + 1 end
            end
            assert(starter >= 10, ("%s route in Riverglades: %d starter spots of %d points"):format(filter, starter, #ns.run.path))
            ns.StopRun() advance(1)
        end
        -- never shared as if we had found them
        ns.db.sync = ns.db.sync or {}
        local sent = #sentMessages
        for _, n in ipairs(ns.db.nodes[2548]) do if n.source == "starter" then ns.SyncShare(2548, n) end end
        advance(3)
        for i = sent + 1, #sentMessages do
            assert(sentMessages[i]:sub(1, 2) == "Q:", "a starter spot of Riverglades was shared: " .. sentMessages[i])
        end
    end)
    if ns.run then ns.StopRun() end
    ns.db.nodes, ns.db.starterVersion = saved.nodes, saved.version
    player.map, player.x, player.y = saved.map, saved.x, saved.y
    PROFS[1][2], PROFS[2][2] = saved.herb, saved.ore
    ns.ForgetSeenKinds() ns.NotifyNodesChanged() advance(1)
    if not ok then error(err, 0) end
end)
-- 0.2.1 (Sven, 21.11.2026): the 0.2.0 notes said a shipped spot nobody
-- harvests, shares or sees on the minimap within 21 days leaves your map
-- again. The changelog of 0.2.1 sets that right: the clock ran from the
-- import, also in zones never visited (the first spots on 11 December), and
-- it is gone (A1). It does not say starter spots are parked: the sync
-- self-healing parks spots that came by sync only, never a starter spot.
step("Starter data 0.2.2: the changelog says where the new spots are, that every spot shipped before stays, no promise and nothing of parking (0.2.2)", function()
    -- 0.2.2 P1 point 5: the starter data refreshed from the saved data of
    -- 21.11.2026, 797 -> 897 rows, none lost (tools/starter_shipped.txt). What
    -- 0.2.1 said about the 21 days is in the history (tag v0.2.1).
    local f = assert(io.open(ROOT .. "/CHANGELOG.md"))
    local changelog = f:read("*a") f:close()
    local changed = changelog:match("\n### Changed\n(.-)\n### ")
    assert(changed, "CHANGELOG: no Changed")
    local point = changed:match("%- %*%*Starter data refreshed:%*%*[^\n]*")
    assert(point, "CHANGELOG, Changed: no point about the starter data")
    for _, said in ipairs({ "new herb and ore spots", "Mount Hyjal, Riverglades and Zephras Isle", "gathered and shared up to 21 November",
        "every spot shipped before stays" }) do
        assert(point:find(said, 1, true), "CHANGELOG, starter data: nothing about \"" .. said .. "\"")
    end
    -- the data it speaks of: the version of the shipped file is of that day
    assert(GathercraftStarterData and GathercraftStarterData.version == "forever-2026-11-21", "test setup: the starter data are not those of 21.11.2026")
    -- no promise of completeness, not parked: no word of it, nor of the self-healing
    local low = changelog:lower()
    for _, said in ipairs({ "complete", "all spots", "every spot in", "park", "self-heal", "self heal", "selfheal" }) do
        assert(not low:find(said, 1, true), "CHANGELOG says \"" .. said .. "\"")
    end
end)
-- 0.2.1 A1 (Sven, 20.11.2026; Codex, 0.2.0 starter spots round 1 §5): a
-- starter spot no longer leaves the map because time went by. Up to 0.2.0
-- every unconfirmed one went 21 days after the import - also in a zone you
-- never entered (the spots of 0.2.0 from 11.12.2026 on). Now they stay until
-- you harvest them (then they are yours) - the old beta spots as well; a spot
-- found empty learns it as before (it rests, its chance drops).
step("Starter data 0.2.1: spots stay without a visit - after 30 days, the ones 0.2.0 imported too, the old beta spots as well; a harvest still makes one yours (0.2.1 A1)", function()
    local data = GathercraftStarterData
    local saved = { nodes = ns.db.nodes, version = ns.db.starterVersion, map = player.map, x = player.x, y = player.y }
    local loader
    for f in pairs(eventFrames["PLAYER_LOGOUT"] or {}) do
        if eventFrames["PLAYER_LOGIN"][f] and not (eventFrames["UNIT_SPELLCAST_CHANNEL_STOP"] or {})[f] then loader = f end
    end
    assert(loader, "test setup: starter loader not found")
    local function Login() loader.__scripts.OnEvent(loader, "PLAYER_LOGIN") end
    local function Count(z)
        local c = 0
        for _, n in ipairs(ns.db.nodes[z] or {}) do if n.source == "starter" then c = c + 1 end end
        return c
    end
    local function All()
        local c = 0
        for z in pairs(data.nodes) do c = c + Count(z) end
        return c
    end
    local DAY = 86400
    local shifted = 0
    local function Days(d) -- the clock goes on (running timers along, as the self-healing step does it)
        NOW = NOW + d * DAY
        for _, t in ipairs(timers) do t.at = t.at + d * DAY end
        shifted = shifted + d
    end
    local rows = 0
    for _, list in pairs(data.nodes) do rows = rows + #list end
    local ok, err = pcall(function()
        -- (1) imported as 0.2.0 does it, then 30 days without going there: every spot is still there, nothing comes twice
        ns.db.nodes, ns.db.starterVersion = {}, nil
        ns.ForgetSeenKinds() ns.NotifyNodesChanged()
        Login()
        assert(All() == rows, ("a fresh profile: %d of %d spots imported"):format(All(), rows))
        assert(ns.db.starterVersion == data.version, "the data version is not remembered: " .. tostring(ns.db.starterVersion))
        local mark = #log
        Days(30)
        Login()
        assert(All() == rows, ("30 days later, never in Riverglades or Mount Hyjal: %d of %d spots left (Riverglades %d of %d, Mount Hyjal %d of %d)"):format(
            All(), rows, Count(2548), #data.nodes[2548], Count(2482), #data.nodes[2482]))
        Days(30)
        Login()
        assert(All() == rows, ("60 days later: %d of %d spots left"):format(All(), rows))
        for i = mark + 1, #log do
            assert(not log[i]:find("nobody confirmed", 1, true), "a spot was removed for its age: " .. log[i])
            assert(not log[i]:find(data.version, 1, true), "a later login imported the starter data again: " .. log[i])
        end
        -- (2) a profile 0.2.0 filled 30 days ago (the data version known, every spot "added" then): kept, not imported again
        local filled = {}
        for z, list in pairs(data.nodes) do
            filled[z] = {}
            for _, e in ipairs(list) do
                filled[z][#filled[z] + 1] = { id = e[1], type = ({ h = "herb", o = "ore", c = "chest" })[e[2]], name = e[7], x = e[3] / 10000, y = e[4] / 10000,
                    count = 1, source = "starter", added = time() - 30 * DAY, last = time() - 30 * DAY }
            end
        end
        ns.db.nodes, ns.db.starterVersion = filled, data.version
        ns.ForgetSeenKinds() ns.NotifyNodesChanged()
        mark = #log
        Login()
        assert(All() == rows, ("a profile 0.2.0 filled 30 days ago: %d of %d spots left"):format(All(), rows))
        for z, list in pairs(data.nodes) do
            assert(#ns.db.nodes[z] == #list, ("zone %d: %d nodes, want %d (nothing imported again)"):format(z, #ns.db.nodes[z], #list))
        end
        for i = mark + 1, #log do
            assert(not log[i]:find(data.version, 1, true), "the same data version was imported again: " .. log[i])
        end
        -- (3) an old beta spot (imported with the beta data of 23.10., 40 days ago), never seen or heard of: kept as well
        local beta = data.nodes[1412][1]
        ns.db.nodes = { [1412] = { { id = beta[1], type = ({ h = "herb", o = "ore" })[beta[2]], name = beta[7], x = beta[3] / 10000, y = beta[4] / 10000,
            count = 1, source = "starter", added = time() - 40 * DAY, last = time() - 40 * DAY } } }
        ns.db.starterVersion = data.version
        ns.ForgetSeenKinds() ns.NotifyNodesChanged()
        Login()
        assert(Count(1412) == 1, "an old beta spot nobody confirmed was removed")
        -- (4) a harvest still makes a spot yours, as before (30 days on, in Riverglades)
        ns.db.nodes, ns.db.starterVersion = {}, nil
        ns.ForgetSeenKinds() ns.NotifyNodesChanged()
        Login()
        Days(30)
        Login()
        local e = data.nodes[2548][1]
        local spell = e[2] == "h" and 2366 or 2575
        player.map, player.x, player.y = 2548, e[3] / 10000, e[4] / 10000
        fire("UNIT_SPELLCAST_SENT", "player", e[7], "a1cast", spell)
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", "a1cast", spell)
        loot = { { guid = "GameObject-0-1-1-1-" .. e[1]:sub(2) .. "-00A1A1", item = e[5], qty = 1 } }
        fire("LOOT_READY") fire("LOOT_OPENED")
        advance(3)
        loot = {}
        local mine
        for _, n in ipairs(ns.db.nodes[2548]) do
            if n.id == e[1] and math.abs(n.x - e[3] / 10000) < 0.002 and math.abs(n.y - e[4] / 10000) < 0.002 then mine = n end
        end
        assert(mine and mine.source == nil, "the harvested starter spot is not yours: " .. tostring(mine and mine.source))
        assert(Count(2548) == #data.nodes[2548] - 1, ("Riverglades after one harvest: %d starter spots, want %d"):format(Count(2548), #data.nodes[2548] - 1))
    end)
    if shifted ~= 0 then Days(-shifted) end
    loot = {}
    ns.db.nodes, ns.db.starterVersion = saved.nodes, saved.version
    player.map, player.x, player.y = saved.map, saved.x, saved.y
    ns.ForgetSeenKinds() ns.NotifyNodesChanged() advance(1)
    if not ok then error(err, 0) end
end)
-- 0.2.1 A2 (Sven, 20.11.2026): the starter data are live data now (0.2.0:
-- the spots of the new Forever zones). The chat line of the import and the
-- tooltip of a starter spot said "beta"; they say "starter data" now, in
-- every language. The tooltip line is no wider than a line of the run
-- window (56, East Asian characters count twice).
step("Starter data 0.2.1: the chat line and the tooltip say starter data, not beta - in every language, the tooltip line fits (0.2.1 A2)", function()
    local CHAT = "Starter data %s: %d nodes added, %d already known."
    local TIP = "Gathercraft starter data (not harvested by you yet)"
    local OLD = { "Beta data %s: %d nodes added, %d already known.", "From the beta database (not confirmed yet)" }
    local function Read(name) local f = assert(io.open(ROOT .. "/" .. name)) local s = f:read("*a") f:close() return s end
    local starter, pins = Read("Starter.lua"), Read("Pins.lua")
    assert(starter:find('L["' .. CHAT .. '"]', 1, true), "Starter.lua: the chat line of the import is not " .. CHAT)
    assert(pins:find('L["' .. TIP .. '"]', 1, true), "Pins.lua: the tooltip line of a starter spot is not " .. TIP)
    for name, src in pairs({ ["Starter.lua"] = starter, ["Pins.lua"] = pins }) do
        for key in src:gmatch('L%["(.-)"%]') do
            assert(not key:lower():find("beta", 1, true), name .. ": a text still says beta: " .. key)
        end
    end
    local function Codes(s)
        local list = {}
        for code in s:gmatch("%%[%d%$]*[sd]") do list[#list + 1] = code end
        return table.concat(list, " ")
    end
    local function Width(text)
        local n = 0
        for ch in text:gmatch("[%z\1-\127\194-\244][\128-\191]*") do n = n + ((#ch >= 3) and 2 or 1) end
        return n
    end
    -- (lower() of Lua knows only A-Z: the capital forms of other scripts are listed too)
    local BETA = { "beta", "bêta", "бета", "Бета", "БЕТА", "베타", "测试", "測試" }
    local function SaysBeta(s)
        local low = s:lower()
        for _, word in ipairs(BETA) do
            if s:find(word, 1, true) or low:find(word, 1, true) then return word end
        end
        return nil
    end
    local LANGS = { "deDE", "esES", "frFR", "itIT", "koKR", "ptBR", "ruRU", "zhCN", "zhTW" }
    local wide = {}
    if Width(TIP) > 56 then wide[#wide + 1] = ("enUS %d: %s"):format(Width(TIP), TIP) end
    for _, lang in ipairs(LANGS) do
        local t = ns.Locales[lang]
        for _, key in ipairs({ CHAT, TIP }) do
            local tr = t and t[key]
            assert(type(tr) == "string" and tr ~= "" and tr ~= key, ("no %s translation of %q"):format(lang, key))
            assert(Codes(tr) == Codes(key), ("%s: other placeholders (or another order) in %q: %s"):format(lang, key, tr))
            assert(not tr:find("^%s") and not tr:find("%s$"), ("%s: blanks around %q"):format(lang, tr))
            local beta = SaysBeta(tr)
            assert(not beta, ("%s: %q still says beta (%s)"):format(lang, tr, tostring(beta)))
        end
        if Width(t[TIP]) > 56 then wide[#wide + 1] = ("%s %d: %s"):format(lang, Width(t[TIP]), t[TIP]) end
        for _, key in ipairs(OLD) do assert(t[key] == nil, ("%s: the old text is still there: %q"):format(lang, key)) end
    end
    assert(#wide == 0, "the tooltip line is too wide: " .. table.concat(wide, " | "))
    local esMX = ns.Locales.esMX or ns.Locales.esES
    assert(esMX[TIP] == ns.Locales.esES[TIP], "esMX does not read the Spanish tooltip line")

    -- in the game, in this language: a fresh import says it in the chat, the pin of a starter spot in its tooltip
    local data = GathercraftStarterData
    local saved = { nodes = ns.db.nodes, version = ns.db.starterVersion, map = player.map, x = player.x, y = player.y }
    local loader
    for f in pairs(eventFrames["PLAYER_LOGOUT"] or {}) do
        if eventFrames["PLAYER_LOGIN"][f] and not (eventFrames["UNIT_SPELLCAST_CHANNEL_STOP"] or {})[f] then loader = f end
    end
    assert(loader, "test setup: starter loader not found")
    local ok, err = pcall(function()
        local rows = 0
        for _, list in pairs(data.nodes) do rows = rows + #list end
        ns.db.nodes, ns.db.starterVersion = {}, nil
        ns.ForgetSeenKinds() ns.NotifyNodesChanged()
        local mark = #log
        loader.__scripts.OnEvent(loader, "PLAYER_LOGIN")
        local said = (ns.L[CHAT]):format(data.version, rows, 0)
        local chat = false
        for i = mark + 1, #log do
            if log[i]:find("PRINT", 1, true) == 1 or log[i]:find("CHAT", 1, true) == 1 then -- (the mock's print, a chat frame)
                if log[i]:find(said, 1, true) then chat = true end
                assert(not SaysBeta(log[i]), "the chat says beta: " .. log[i])
            end
        end
        assert(chat, "the import did not say: " .. said)
        -- the tooltip of a pin of a starter spot (Riverglades, where we stand)
        local e = data.nodes[2548][1]
        player.map, player.x, player.y = 2548, e[3] / 10000, e[4] / 10000
        ns.NotifyNodesChanged() advance(2)
        mark = #log
        local entered = 0
        for _, f in ipairs(allFrames) do
            if f.node and f.node.source == "starter" and f.__scripts.OnEnter and entered < 6 then
                f.__scripts.OnEnter(f)
                if f.__scripts.OnLeave then f.__scripts.OnLeave(f) end
                entered = entered + 1
            end
        end
        assert(entered > 0, "test setup: no pin of a starter spot")
        local tip = false
        for i = mark + 1, #log do
            if log[i] == "TT " .. ns.L[TIP] then tip = true end
            if log[i]:find("TT", 1, true) == 1 then
                assert(not SaysBeta(log[i]), "a tooltip line says beta: " .. log[i])
            end
        end
        assert(tip, "no tooltip line " .. ns.L[TIP] .. " on a starter spot")
    end)
    ns.db.nodes, ns.db.starterVersion = saved.nodes, saved.version
    player.map, player.x, player.y = saved.map, saved.x, saved.y
    ns.ForgetSeenKinds() ns.NotifyNodesChanged() advance(1)
    if not ok then error(err, 0) end
end)
-- 0.2.1 A3 (Sven, 20.11.2026; the 0.2.0 starter spots report): Riverglades
-- has quest objects ("Wildflower", "Rock Pile") that come up in the herb and
-- ore search. Up to 0.2.0 the recorder booked every gather with Herb
-- Gathering or Mining whose loot came from the object, and sync shared it.
-- Now the loot tells: an object the spawn data does not know whose loot is
-- quest items only (item class Quest, 12) is no gather - not booked, not
-- shared. Herbs, ores and stone are trade goods: a new Forever herb or vein
-- never falls out. An item whose class can't be read (secret, no API) is
-- booked as before. Sync drops a report whose item is a quest item; a report
-- without an item comes in as before. A quest node an older version booked
-- is no longer shared.
step("Quest objects 0.2.1: loot of quest items only is no gather - not booked, not shared, not taken from others; new Forever herbs, mixed loot, unreadable items and known herbs as before (0.2.1 A3)", function()
    local Z = 2548
    local QUEST, QUEST2, HERB, UNREAD = 990001, 990002, 990010, 990020
    local SECRET = newproxy(true)
    local saved = { nodes = ns.db.nodes, map = player.map, x = player.x, y = player.y, instant = C_Item.GetItemInfoInstant,
        secret = issecretvalue, pending = ns.db.sync and ns.db.sync.pending and ns.db.sync.pending[Z], enabled = ns.db.sync and ns.db.sync.enabled }
    local instantCalls = 0
    local ok, err = pcall(function()
        if not ns.db.sync.enabled then slash("sync on") end
        C_Item.GetItemInfoInstant = function(id, ...)
            instantCalls = instantCalls + 1
            if id == QUEST or id == QUEST2 then return id, "Quest", "Quest", "", 134400, 12, 0 end
            if id == HERB then return id, "Trade Goods", "Herb", "", 134400, 7, 9 end
            if id == UNREAD then return id, SECRET, SECRET, SECRET, SECRET, SECRET, SECRET end
            return saved.instant(id, ...)
        end
        issecretvalue = function(v) return rawequal(v, SECRET) end
        ns.db.nodes = { [Z] = {} }
        ns.db.sync.pending[Z] = nil
        ns.ForgetSeenKinds() ns.NotifyNodesChanged()
        local n = 0
        local function Gather(name, spell, objectID, items, x)
            n = n + 1
            player.map, player.x, player.y = Z, x, 0.5
            local cast = "a3cast" .. n
            fire("UNIT_SPELLCAST_SENT", "player", name, cast, spell)
            fire("UNIT_SPELLCAST_SUCCEEDED", "player", cast, spell)
            loot = {}
            for _, it in ipairs(items) do
                loot[#loot + 1] = { guid = "GameObject-0-1-1-1-" .. objectID .. "-00A3A3" .. n, item = it, qty = 1 }
            end
            fire("LOOT_READY") fire("LOOT_OPENED")
            advance(3)
            loot = {}
        end
        local function Node(oid)
            for _, x in ipairs(ns.db.nodes[Z] or {}) do if x.id == oid then return x end end
        end
        local sent = #sentMessages
        local function Sent(oid)
            for i = sent + 1, #sentMessages do
                if sentMessages[i]:find("N:", 1, true) == 1 and sentMessages[i]:find(";" .. oid .. ",", 1, true) then return true end
            end
            return false
        end
        -- quest objects with the herb and the ore search: nothing booked, nothing shared
        Gather("Wildflower", 2366, 600001, { QUEST }, 0.30)
        Gather("Rock Pile", 2575, 600002, { QUEST2, QUEST }, 0.35)
        assert(not Node("o600001"), "a Wildflower (quest items only) was booked as a herb")
        assert(not Node("o600002"), "a Rock Pile (quest items only) was booked as an ore")
        -- a new Forever herb (trade goods), the same with a quest item in front, an item the client can't tell, a known herb with a quest item
        Gather("Riverbloom", 2366, 600010, { HERB }, 0.40)
        Gather("Riverbloom", 2366, 600011, { QUEST, HERB }, 0.45)
        Gather("Mistleaf", 2366, 600012, { UNREAD }, 0.50)
        Gather("Peacebloom", 2366, 1618, { QUEST }, 0.55)
        local h1, h2, u1, k1 = Node("o600010"), Node("o600011"), Node("o600012"), Node("o1618")
        assert(h1 and h1.type == "herb" and h1.item == HERB, "a new Forever herb was not booked (or not with its herb): " .. tostring(h1 and h1.item))
        assert(h2 and h2.type == "herb" and h2.item == HERB, "a herb with a quest item in its loot: booked with " .. tostring(h2 and h2.item) .. ", want its herb")
        assert(u1 and u1.type == "herb" and u1.item == UNREAD, "a gather whose item can't be read was not booked as before")
        assert(k1 and k1.type == "herb", "a known Peacebloom with a quest item in its loot was not booked")
        assert(instantCalls > 0, "test setup: the item class was never asked")
        advance(10)
        assert(Sent("o600010") and Sent("o600011"), "the new Forever herbs were not shared (the test would say nothing)")
        assert(not Sent("o600001") and not Sent("o600002"), "a quest object was shared")
        -- a quest node an older version booked (in this profile already): kept, but never shared - no push, no answer
        local old = { id = "o600005", type = "herb", name = "Wildflower", x = 0.60, y = 0.5, item = QUEST, count = 1, last = time() }
        -- and one that came in by sync before 0.2.1 and was confirmed: sync nodes go into answers too
        local oldSync = { id = "o600006", type = "ore", name = "Rock Pile", x = 0.65, y = 0.5, item = QUEST2, count = 1, last = time(),
            source = "sync", heard = 3 }
        table.insert(ns.db.nodes[Z], old)
        table.insert(ns.db.nodes[Z], oldSync)
        ns.NotifyNodesChanged()
        sent = #sentMessages
        ns.SyncShare(Z, old)
        advance(3)
        fire("CHAT_MSG_ADDON", "Gathercraft", "Q:" .. Z .. ":0", "CHANNEL", "Curious Player", nil, nil, nil, "GathercraftSync")
        advance(15)
        assert(not Sent("o600005"), "an old quest node was shared")
        assert(not Sent("o600006"), "an old quest node from sync was in an answer")
        assert(Sent("o600010"), "the answer to a question did not hold the real herb (the test would say nothing)")
        -- reports from others (guild: taken at once): a quest item - dropped; a trade good, or no item at all - as before
        fire("CHAT_MSG_ADDON", "Gathercraft", "N:" .. Z .. ";o600003,h,6500,5000," .. QUEST .. ";o600013,h,7000,5000," .. HERB .. ";o600014,h,7500,5000,0", "GUILD", "Guildie A3")
        fire("CHAT_MSG_ADDON", "Gathercraft", "N:" .. Z .. ";o600004,o,6500,6000," .. QUEST2, "CHANNEL", "Stranger A3", nil, nil, nil, "GathercraftSync")
        advance(2)
        assert(not Node("o600003"), "a guild report of a quest item became a node")
        assert(Node("o600013") and Node("o600014"), "a guild report of a herb, or one without an item, was not taken as before")
        for _, p in ipairs(ns.db.sync.pending[Z] or {}) do
            assert(p.id ~= "o600004" and p.id ~= "o600003", "a report of a quest item is waiting for confirmations: " .. p.id)
        end
    end)
    C_Item.GetItemInfoInstant, issecretvalue = saved.instant, saved.secret
    loot = {}
    ns.db.nodes = saved.nodes
    ns.db.sync.pending[Z] = saved.pending
    player.map, player.x, player.y = saved.map, saved.x, saved.y
    ns.ForgetSeenKinds() ns.NotifyNodesChanged() advance(1)
    if not ok then error(err, 0) end
end)
-- 0.2.1 A4 (Sven, live 20.11.2026): the skill plan of Cooking was open, a
-- hearthstone to Moonglade - after the loading screen it was closed (no run
-- going). The cause: our windows close with Escape, so they are in
-- UISpecialFrames, and the game closes every window of that list after each
-- loading screen as well (UIParent, PLAYER_ENTERING_WORLD: CloseAllWindows(1),
-- which calls CloseSpecialWindows). Not meant: a window that was open when
-- the loading screen began is open again after it. Escape still closes it;
-- one you closed before stays closed.
step("Windows 0.2.1: the skill plan and the main window stay open over a loading screen; Escape still closes them, a closed one stays closed (0.2.1 A4)", function()
    -- what the game does with Escape and after a loading screen: every frame of UISpecialFrames is hidden
    local function CloseSpecial()
        for _, name in ipairs(UISpecialFrames) do
            local f = _G[name]
            if f and f.IsShown and f:IsShown() then f:Hide() end
        end
    end
    -- a loading screen (a hearthstone); first: the game's handler before ours, then: after ours (the same
    -- event); noEnd: a client without LOADING_SCREEN_DISABLED
    local function Loading(gameFirst, noEnd)
        fire("PLAYER_LEAVING_WORLD")
        if not noEnd then fire("LOADING_SCREEN_ENABLED") end
        if gameFirst then CloseSpecial() end
        fire("PLAYER_ENTERING_WORLD", false, false)
        if not gameFirst then CloseSpecial() end
        if not noEnd then fire("LOADING_SCREEN_DISABLED") end
        advance(1)
    end
    local function Plan() return _G.GathercraftSkillPlan end
    local function Main() return _G.GathercraftMain end
    local ok, err = pcall(function()
        ns.ShowSkillPlan("Cooking") advance(1)
        assert(Plan() and Plan():IsShown(), "test setup: the skill plan of Cooking did not open")
        local listed = false
        for _, name in ipairs(UISpecialFrames) do if name == "GathercraftSkillPlan" then listed = true end end
        assert(listed, "test setup: the skill plan is not in UISpecialFrames (Escape would not close it)")
        for _, case in ipairs({ { true }, { false }, { true, true }, { false, true } }) do
            local gameFirst, noEnd = case[1], case[2]
            local how = (gameFirst and "the game's handler first" or "ours first") .. (noEnd and ", a client without LOADING_SCREEN_DISABLED" or "")
            Loading(gameFirst, noEnd)
            assert(Plan():IsShown(), "the skill plan is closed after a loading screen (" .. how .. ")")
            advance(5)
            assert(Plan():IsShown(), "the skill plan closed a moment after a loading screen (" .. how .. ")")
        end
        -- the main window as well; and a window closed before the loading screen stays closed
        if not Main():IsShown() then ns.ToggleMain() end
        advance(1)
        assert(Main():IsShown(), "test setup: the main window did not open")
        Plan():Hide()
        Loading(true)
        assert(Main():IsShown(), "the main window is closed after a loading screen")
        assert(not Plan():IsShown(), "the skill plan, closed before the loading screen, opened again")
        -- Escape (no loading screen): closes them, and they stay closed
        ns.ShowSkillPlan("Cooking") advance(1)
        CloseSpecial()
        advance(5)
        assert(not Plan():IsShown() and not Main():IsShown(), "Escape: a window opened again")
        -- one loading screen after Escape: nothing comes back that was closed
        Loading(true)
        assert(not Plan():IsShown() and not Main():IsShown(), "a window closed with Escape opened again after a loading screen")
    end)
    if Plan() then Plan():Hide() end
    if Main() and Main():IsShown() then Main():Hide() end
    advance(1)
    if not ok then error(err, 0) end
end)
-- 0.2.1 (Sven, 21.11.2026): the release. Part A was tested under the mark
-- 0.2.1-a1; now the TOC says 0.2.1, "What's new" has its entry and the
-- changelog its section. The first login after 0.2.0, after the test build
-- 0.2.1-a1 or after an older version shows the window of 0.2.1, once.
step("Version 0.2.1: the TOC says it, /gcr shows it, the What's new window of 0.2.1 once after 0.2.0, 0.2.1-a1 or 0.1.23 (0.2.1)", function()
    local version = toc:match("## Version: ([%w%.%-]+)")
    -- the TOC says the build's version (own step); the window checked is 0.2.1's
    assert(version == "0.2.3-a3", "TOC version: " .. tostring(version))
    version = "0.2.1"
    local function Read(name) local f = assert(io.open(ROOT .. "/" .. name)) local s = f:read("*a") f:close() return s end
    -- "What's new" has the entry of 0.2.1, none for the test build
    local welcome = Read("Welcome.lua")
    local entry = welcome:match('%["0%.2%.1"%] = "([^"]+)"')
    assert(entry, "Welcome.lua has no What's new entry for 0.2.1")
    assert(not welcome:find('["0.2.1-a1"]', 1, true), "Welcome.lua has a What's new entry for the test build")
    -- the changelog is the next release's: 0.2.1's section is in the history (tag v0.2.1)
    assert(Read("CHANGELOG.md"):match("^(## v[^\r\n]*)") == "## v0.2.2 – 2026-11-23", "the changelog is not 0.2.2's")
    -- /gcr: the main window shows the TOC version ("v" and it)
    assert(Read("Main.lua"):find('version:SetText(v and ("v" .. v) or "")', 1, true), "the main window does not show the TOC version")
    local keep = { meta = C_AddOns.GetAddOnMetadata, last = ns.db.lastVersion, fresh = ns.freshInstall }
    local ok, err = pcall(function()
        C_AddOns.GetAddOnMetadata = function(_, field) if field == "Version" then return version end end
        ns.freshInstall = false
        for _, before in ipairs({ "0.2.0", "0.2.1-a1", "0.1.23" }) do
            local win = _G.GathercraftWhatsNew
            if win then win:Hide() end
            ns.db.lastVersion = before
            ns.WelcomeOnLogin()
            win = _G.GathercraftWhatsNew
            assert(win and win:IsShown() and win.body:GetText() == ns.L[entry], "no What's new window of 0.2.1 after " .. before)
            assert(ns.db.lastVersion == "0.2.1", "after " .. before .. " not remembered: " .. tostring(ns.db.lastVersion))
            win:Hide()
            ns.WelcomeOnLogin()
            assert(not win:IsShown(), "the What's new window again at the next login after " .. before)
        end
    end)
    local win = _G.GathercraftWhatsNew
    if win then win:Hide() end
    C_AddOns.GetAddOnMetadata, ns.db.lastVersion, ns.freshInstall = keep.meta, keep.last, keep.fresh
    if not ok then error(err, 0) end
end)
step("Minimap tooltip: ours below any tooltip the game shows there, never on it (0.2.1 A5)", function()
    -- Sven, 20.11.2026, Cape of Stranglethorn, mouse over Kingsblood: the
    -- game's tooltip listed Kingsblood and a quest ("Mok'thardin's
    -- Enchantment", "- 7/10 Jungle Stalker Feather"); ours lay on it, its
    -- lower edge at the cursor like the game's. Ours went below the game's
    -- tooltip only when that was taken for the minimap's own (owner the
    -- minimap or the screen, lines readable) - else next to our pin under the
    -- cursor, where the game's tooltip is too. Now: below any GameTooltip
    -- shown while the mouse is on the minimap. Only the minimap's own tooltip
    -- is read (short heading, learning), as before.
    local Z = 1466
    local names = GathercraftNodeNames and GathercraftNodeNames[GetLocale()]
    local herbName = names and names[1618] or "Peacebloom"
    local keep = { nodes = ns.db.nodes[Z], map = player.map, x = player.x, y = player.y, foci = GetMouseFoci, focus = GetMouseFocus,
        cursor = GetCursorPosition, cvar = GetCVar, secret = issecretvalue, learnOff = ns.db.minimapLearnOff }
    local mm, gt, texts = {}, {}, {}
    for _, k in ipairs({ "IsMouseOver", "GetCenter", "GetWidth", "GetHeight", "GetZoom", "GetEffectiveScale" }) do mm[k] = rawget(Minimap, k) end
    for _, k in ipairs({ "IsShown", "GetOwner", "NumLines" }) do gt[k] = rawget(GameTooltip, k) end
    local vpin, pinOver, tip, tipAdd = nil, {}, nil, nil
    local ok, err = pcall(function()
        local lines, owner, onPin = {}, UIParent, false
        Minimap.IsMouseOver = function() return true end
        Minimap.GetCenter = function() return 500, 400 end
        Minimap.GetWidth = function() return 140 end
        Minimap.GetHeight = function() return 140 end
        Minimap.GetZoom = function() return 0 end
        Minimap.GetEffectiveScale = function() return 1 end
        GameTooltip.IsShown = function() return #lines > 0 end
        GameTooltip.GetOwner = function() return owner end
        GameTooltip.NumLines = function() return #lines end
        for i = 1, 3 do
            local fs = _G["GameTooltipTextLeft" .. i] or newObject("FontString", "GameTooltipTextLeft" .. i)
            _G["GameTooltipTextLeft" .. i] = fs
            texts[i] = rawget(fs, "GetText")
            fs.GetText = function() return lines[i] end
        end
        GetCursorPosition = function() return 540, 400 end
        GetCVar = function() return "0" end
        GetMouseFoci = function() return { Minimap } end
        ns.db.minimapLearnOff = nil
        player.map, player.x, player.y = Z, 0.5, 0.5
        local mapID, cx, cy = ns.CursorOnMap()
        assert(mapID == Z and cx and cy, "test setup: the cursor on the map")
        -- a herb of ours right under the cursor, its minimap pin there too
        local herb = { id = "o1618", name = herbName, type = "herb", x = cx, y = cy, count = 1, last = 1 }
        ns.db.nodes[Z] = { herb }
        ns.NotifyNodesChanged()
        fire("ZONE_CHANGED_NEW_AREA") advance(1)
        -- the herb's minimap pins (pins are made again and reused): shown, as
        -- HereBeDragons does in range (not the mock), the mouse on them when onPin
        local function HerbPins()
            for _, f in ipairs(allFrames) do
                if f.node == herb and f.isMini and not f.isTarget and not pinOver[f] then
                    pinOver[f] = { rawget(f, "IsMouseOver"), f.__shown }
                    pinOver[#pinOver + 1] = f
                    f.IsMouseOver = function() return onPin end
                end
                if pinOver[f] and f.node == herb then f.__shown = true end
            end
        end
        local function Wait(t)
            for _ = 1, math.floor(t / 0.05 + 0.5) do HerbPins() advance(0.05) end
        end
        HerbPins()
        onPin = true
        vpin = ns.MinimapPinUnderCursor()
        onPin = false
        assert(vpin and vpin.node == herb, ("test setup: no minimap pin for the herb under the cursor (%d made)"):format(#pinOver))
        local got = {}
        -- the mouse away, then onto the pin with the game showing these
        -- lines (owned by ...): what our tooltip does
        local function Point(newLines, newOwner, wait)
            onPin, lines = false, {}
            Wait(0.3)
            assert(not (tip and tip:IsShown()), "test setup: our tooltip still shown with the mouse away")
            got = {}
            onPin, lines, owner = true, newLines, newOwner
            Wait(wait or 0.3)
            if not tip and _G.GathercraftMinimapTooltip then
                tip = _G.GathercraftMinimapTooltip
                tipAdd = rawget(tip, "AddLine")
                tip.AddLine = function(self, t, ...) got[#got + 1] = t if tipAdd then return tipAdd(self, t, ...) end end
                return Point(newLines, newOwner, wait) -- (once: now its lines are seen)
            end
            assert(tip and tip:IsShown() and tip.node == herb, "test setup: our tooltip does not show for the herb")
        end
        -- where ours is: right below the game's tooltip (its top left at the
        -- game's bottom left), or next to our pin (its bottom left at the pin)
        local function Below()
            local p = tip.__pts and tip.__pts.TOPLEFT
            return p ~= nil and p[1] == GameTooltip and p[2] == "BOTTOMLEFT" and not tip.__pts.BOTTOMLEFT
        end
        local function AtPin()
            local p = tip.__pts and tip.__pts.BOTTOMLEFT
            return p ~= nil and type(p[1]) == "table" and p[1].node == herb and p[1].isMini and not tip.__pts.TOPLEFT
        end
        local QUEST = { herbName, "Mok'thardin's Enchantment", "- 7/10 Jungle Stalker Feather" }

        -- as before: the game shows nothing there - ours next to the pin, with its name
        Point({}, UIParent)
        assert(AtPin(), "the game shows nothing: ours is not next to the pin any more")
        assert(got[1] == herbName, "the game shows nothing: ours does not start with the name: " .. tostring(got[1]))
        -- as before: the minimap's own tooltip (WoW Forever: owned by the screen)
        -- names the herb - ours below it, a short heading
        Point({ herbName }, UIParent)
        assert(Below(), "the minimap's own tooltip: ours is not below it")
        assert(got[1] == "Gathercraft", "the minimap's own tooltip names it: ours does not start with the short heading: " .. tostring(got[1]))
        Point(QUEST, Minimap)
        assert(Below(), "the minimap's own tooltip with a quest: ours is not below it")

        -- Sven's case: the game's tooltip by the cursor, its owner none we know
        -- (a frame of another minimap): ours below it, not on it - with the
        -- name (we do not read that tooltip), and nothing learned from it
        onPin, lines = false, {}
        Wait(6) -- (the same name at the same place would count again after 5 s)
        herb.seenAt, herb.upAt = nil, nil
        Point(QUEST, newObject("Frame", "SomeUIMinimapHolder"), 1)
        assert(Below(), "the game's tooltip with an owner we do not know: ours lies on it (next to the pin), not below it")
        assert(got[1] == herbName, "a tooltip we do not read: ours does not start with the name: " .. tostring(got[1]))
        assert(herb.seenAt == nil, "learned from a tooltip whose owner we do not know")
        -- an unnamed owner, no owner at all, another addon's frame: the same
        Point(QUEST, newObject("Frame"))
        assert(Below(), "the game's tooltip owned by a nameless frame: ours is not below it")
        Point({ herbName }, newObject("Button", "OtherAddonButton"))
        assert(Below(), "a tooltip of another addon by the cursor: ours is not below it")
        -- the game's tooltip cannot be read (a hidden line): below it too
        local SECRET = newproxy(true)
        issecretvalue = function(v) return rawequal(v, SECRET) end
        Point({ SECRET }, UIParent)
        assert(Below(), "the game's tooltip with a line we cannot read: ours is not below it")
        assert(got[1] == herbName, "a tooltip we cannot read: ours does not start with the name")
        issecretvalue = keep.secret

        -- the game's tooltip comes after ours, or grows: ours goes / stays below
        Point({}, UIParent)
        assert(AtPin(), "test setup: ours next to the pin")
        lines, owner = QUEST, newObject("Frame", "SomeUIMinimapHolder")
        Wait(0.3)
        assert(Below(), "the game's tooltip came after ours (owner unknown): ours stays next to the pin, on it")
        Point({ herbName }, UIParent)
        assert(Below(), "test setup: ours below the game's")
        lines = QUEST -- the same tooltip, two lines longer
        Wait(0.5)
        assert(Below(), "the game's tooltip grew: ours is not below it any more")
        -- the game's tooltip goes: ours back next to the pin
        lines = {}
        Wait(0.3)
        assert(tip:IsShown() and AtPin(), "the game's tooltip went: ours is not next to the pin again")

        -- as before: a pin of another addon under the mouse - ours not shown
        local other = newObject("Frame", nil, Minimap)
        other:SetSize(16, 16)
        GetMouseFoci = function() return { other } end
        lines, owner = { herbName }, UIParent
        Wait(0.3)
        assert(not tip:IsShown(), "another addon's pin under the mouse: ours shows")
        GetMouseFoci = function() return { Minimap } end
        onPin, lines = false, {}
        Wait(0.3)
    end)
    if tip then tip.AddLine = tipAdd end
    for _, f in ipairs(pinOver) do f.IsMouseOver, f.__shown = pinOver[f][1], pinOver[f][2] end
    GetMouseFoci, GetMouseFocus, GetCursorPosition, GetCVar, issecretvalue = keep.foci, keep.focus, keep.cursor, keep.cvar, keep.secret
    for _, k in ipairs({ "IsMouseOver", "GetCenter", "GetWidth", "GetHeight", "GetZoom", "GetEffectiveScale" }) do Minimap[k] = mm[k] end
    for _, k in ipairs({ "IsShown", "GetOwner", "NumLines" }) do GameTooltip[k] = gt[k] end
    for i = 1, 3 do if _G["GameTooltipTextLeft" .. i] then _G["GameTooltipTextLeft" .. i].GetText = texts[i] end end
    ns.db.nodes[Z], ns.db.minimapLearnOff = keep.nodes, keep.learnOff
    player.map, player.x, player.y = keep.map, keep.x, keep.y
    fire("ZONE_CHANGED_NEW_AREA") advance(1)
    ns.NotifyNodesChanged() advance(1)
    if not ok then error(err, 0) end
end)
-- 0.2.1 B1 (Codex, round 1 of part A, 21.11.2026): a gather whose loot was
-- read before every item link was there (nil, or a hidden value) was taken
-- for quest items only - only the readable quest item was in the list - and
-- dropped for good, although its herb came with it. "Quest items only" now
-- needs every item slot read; a slot without a readable link makes no quest
-- decision: the gather is booked as before (the cautious rule of A3), right
-- away and once. Money and currency slots have no item link and don't count.
step("Quest objects 0.2.1: loot not fully read proves no quest object - the gather is booked once; a money slot does not count (0.2.1 B1)", function()
    local Z = 2548
    local QUEST, QUEST2, HERB = 990001, 990002, 990010
    local SECRET = newproxy(true)
    local saved = { nodes = ns.db.nodes, map = player.map, x = player.x, y = player.y, instant = C_Item.GetItemInfoInstant,
        secret = issecretvalue, link = GetLootSlotLink, slotType = GetLootSlotType }
    local ok, err = pcall(function()
        C_Item.GetItemInfoInstant = function(id, ...)
            if id == QUEST or id == QUEST2 then return id, "Quest", "Quest", "", 134400, 12, 0 end
            if id == HERB then return id, "Trade Goods", "Herb", "", 134400, 7, 9 end
            return saved.instant(id, ...)
        end
        issecretvalue = function(v) return rawequal(v, SECRET) end
        ns.db.nodes = { [Z] = {} }
        ns.ForgetSeenKinds() ns.NotifyNodesChanged()
        local n = 0
        -- a gather at an object the spawn data doesn't know. how: what slot `slot`
        -- gives as its link at LOOT_READY (nil: not there yet, SECRET: hidden;
        -- at LOOT_OPENED it is there), or with always: at both (a money slot);
        -- slotType: GetLootSlotType for it (nil: a client without it)
        local function Gather(name, spell, objectID, items, x, how)
            n = n + 1
            how = how or {}
            player.map, player.x, player.y = Z, x, 0.5
            local cast = "b1cast" .. n
            fire("UNIT_SPELLCAST_SENT", "player", name, cast, spell)
            fire("UNIT_SPELLCAST_SUCCEEDED", "player", cast, spell)
            loot = {}
            for _, it in ipairs(items) do
                loot[#loot + 1] = { guid = "GameObject-0-1-1-1-" .. objectID .. "-00B1B1" .. n, item = it, qty = 1 }
            end
            local function Link(ready)
                return function(slot)
                    if slot == how.slot and (ready or how.always) then return how.link end
                    return saved.link(slot)
                end
            end
            GetLootSlotType = how.slotType
            GetLootSlotLink = Link(true)
            fire("LOOT_READY")
            GetLootSlotLink = Link(false)
            fire("LOOT_OPENED")
            advance(3)
            GetLootSlotLink, GetLootSlotType = saved.link, saved.slotType
            loot = {}
        end
        local function Nodes(oid)
            local found = {}
            for _, x in ipairs(ns.db.nodes[Z] or {}) do if x.id == oid then found[#found + 1] = x end end
            return found
        end
        local function BookedOnce(oid, what)
            local found = Nodes(oid)
            assert(#found == 1, ("%s: %d nodes, want 1"):format(what, #found))
            assert(found[1].type == "herb" and (found[1].count or 1) == 1, ("%s: booked as %s, %s times"):format(what,
                tostring(found[1].type), tostring(found[1].count)))
        end
        -- Codex's cases: the herb's link is not there yet at LOOT_READY - or hidden - the quest item's is
        Gather("NewRiverHerb", 2366, 600099, { QUEST, HERB }, 0.30, { slot = 2, link = nil })
        BookedOnce("o600099", "herb and quest item, the herb's link not there yet at LOOT_READY")
        Gather("NewRiverHerb", 2366, 600098, { QUEST, HERB }, 0.33, { slot = 2, link = SECRET })
        BookedOnce("o600098", "herb and quest item, the herb's link hidden at LOOT_READY")
        -- the quest item's link the one missing: booked as well (its herb is read)
        Gather("NewRiverHerb", 2366, 600097, { QUEST, HERB }, 0.36, { slot = 1, link = nil })
        BookedOnce("o600097", "herb and quest item, the quest item's link not there yet")
        -- a slot without a link whose kind the client can't tell (no GetLootSlotType, or a hidden one): no quest decision
        Gather("Wildflower", 2366, 600096, { QUEST, QUEST2 }, 0.39, { slot = 2, link = nil, always = true })
        BookedOnce("o600096", "quest item and a slot without a link, no slot kind to read")
        Gather("Wildflower", 2366, 600095, { QUEST, QUEST2 }, 0.42,
            { slot = 2, link = nil, always = true, slotType = function() return SECRET end })
        BookedOnce("o600095", "quest item and a slot without a link, its kind hidden")
        -- as A3: quest items only, all read - nothing booked; also next to money (a slot without an item link)
        Gather("Wildflower", 2366, 600094, { QUEST, QUEST2 }, 0.45)
        assert(#Nodes("o600094") == 0, "quest items only, every link read: booked as a herb")
        Gather("Wildflower", 2366, 600093, { QUEST, QUEST2 }, 0.48,
            { slot = 2, link = nil, always = true, slotType = function(slot) return slot == 2 and 2 or 1 end })
        assert(#Nodes("o600093") == 0, "quest items only next to a money slot: booked as a herb (money counted as an item not read)")
        Gather("Wildflower", 2366, 600092, { QUEST, QUEST2 }, 0.51,
            { slot = 2, link = nil, always = true, slotType = function(slot) return slot == 2 and 3 or 1 end })
        assert(#Nodes("o600092") == 0, "quest items only next to a currency slot: booked as a herb")
        -- as A3: herb and quest item, all read - booked once, with the herb
        Gather("NewRiverHerb", 2366, 600091, { QUEST, HERB }, 0.54)
        BookedOnce("o600091", "herb and quest item, every link read")
        assert(Nodes("o600091")[1].item == HERB, "herb and quest item, every link read: not booked with the herb")
    end)
    C_Item.GetItemInfoInstant, issecretvalue = saved.instant, saved.secret
    GetLootSlotLink, GetLootSlotType = saved.link, saved.slotType
    loot = {}
    ns.db.nodes = saved.nodes
    player.map, player.x, player.y = saved.map, saved.x, saved.y
    ns.ForgetSeenKinds() ns.NotifyNodesChanged() advance(1)
    if not ok then error(err, 0) end
end)
-- 0.2.1 B2 (Codex, round 1 of part A, 21.11.2026): A4 showed the windows
-- again a frame after PLAYER_ENTERING_WORLD and again after
-- LOADING_SCREEN_DISABLED, from the same list: a window you closed in
-- between opened again. Now once per loading screen, at the first safe
-- moment after the game closed them (in PLAYER_ENTERING_WORLD):
-- LOADING_SCREEN_DISABLED after it, or one frame later - whichever comes
-- first. After that a window you close stays closed.
step("Windows 0.2.1: shown again once per loading screen - one you close right after it stays closed (0.2.1 B2)", function()
    -- what the game does with Escape and after a loading screen: every frame of UISpecialFrames is hidden
    local function CloseSpecial()
        for _, name in ipairs(UISpecialFrames) do
            local f = _G[name]
            if f and f.IsShown and f:IsShown() then f:Hide() end
        end
    end
    local function Plan() return _G.GathercraftSkillPlan end
    local function Begin(noEvents)
        ns.ShowSkillPlan("Cooking") advance(1)
        assert(Plan() and Plan():IsShown(), "test setup: the skill plan of Cooking did not open")
        fire("PLAYER_LEAVING_WORLD")
        if not noEvents then fire("LOADING_SCREEN_ENABLED") end
    end
    local ok, err = pcall(function()
        -- Codex's close_before_second_end: shown again a frame after
        -- PLAYER_ENTERING_WORLD, you close it, then LOADING_SCREEN_DISABLED
        Begin()
        CloseSpecial() -- the game (its handler before ours)
        fire("PLAYER_ENTERING_WORLD", false, false)
        advance(0.1)
        assert(Plan():IsShown(), "not shown again a frame after PLAYER_ENTERING_WORLD")
        CloseSpecial() -- you: Escape
        fire("LOADING_SCREEN_DISABLED")
        advance(6)
        assert(not Plan():IsShown(), "closed by you between PLAYER_ENTERING_WORLD and LOADING_SCREEN_DISABLED: opened again")
        -- Codex's close_before_timer: LOADING_SCREEN_DISABLED right after
        -- PLAYER_ENTERING_WORLD - the earliest you can close it - before the next frame
        Begin()
        CloseSpecial()
        fire("PLAYER_ENTERING_WORLD", false, false)
        fire("LOADING_SCREEN_DISABLED")
        assert(Plan():IsShown(), "not shown again at LOADING_SCREEN_DISABLED (the earliest you can close it)")
        CloseSpecial()
        advance(6)
        assert(not Plan():IsShown(), "closed by you right after the loading screen, before the next frame: opened again")
        -- the game's handler after ours (the same event): its closing is no
        -- choice of yours - shown again at the end of the loading screen, once
        Begin()
        fire("PLAYER_ENTERING_WORLD", false, false)
        CloseSpecial()
        fire("LOADING_SCREEN_DISABLED")
        assert(Plan():IsShown(), "ours first, then the game: not shown again at the end of the loading screen")
        advance(0.1)
        CloseSpecial()
        advance(6)
        assert(not Plan():IsShown(), "ours first: closed by you after it was shown again, opened again")
        -- LOADING_SCREEN_DISABLED before PLAYER_ENTERING_WORLD (should a client
        -- send them so): shown again after the game's closing, once
        Begin()
        fire("LOADING_SCREEN_DISABLED")
        fire("PLAYER_ENTERING_WORLD", false, false)
        CloseSpecial()
        advance(0.1)
        assert(Plan():IsShown(), "LOADING_SCREEN_DISABLED first: not shown again after the game closed it")
        CloseSpecial()
        advance(6)
        assert(not Plan():IsShown(), "LOADING_SCREEN_DISABLED first: closed by you, opened again")
        -- a client without the LOADING_SCREEN events: a frame later, once
        Begin(true)
        fire("PLAYER_ENTERING_WORLD", false, false)
        CloseSpecial()
        advance(0.1)
        assert(Plan():IsShown(), "a client without LOADING_SCREEN events: not shown again")
        CloseSpecial()
        advance(6)
        assert(not Plan():IsShown(), "a client without LOADING_SCREEN events: closed by you, opened again")
        -- the next loading screen: what you closed stays closed
        fire("PLAYER_LEAVING_WORLD") fire("LOADING_SCREEN_ENABLED")
        CloseSpecial()
        fire("PLAYER_ENTERING_WORLD", false, false)
        fire("LOADING_SCREEN_DISABLED")
        advance(1)
        assert(not Plan():IsShown(), "the next loading screen opened a window closed before it")
    end)
    if Plan() then Plan():Hide() end
    advance(1)
    if not ok then error(err, 0) end
end)
-- 0.2.2 P1 (Sven, 21.11.2026): Map & minimap was full to the last pixel
-- (440 of 440). The questing block - the switch, its radius, the arrow -
-- moved to Leveling, whose rows flow; the tooltip choices of 0.2.2 get its
-- room. A row of buttons on a page that flows hangs on a holder that moves
-- with the rows above it.
step("Options 0.2.2: the questing block is under Leveling - its rows flow in every language; Map & minimap has room for two rows (0.2.2 P1)", function()
    local opts = _G.GathercraftOptions
    local ROOM = 640 - 112 - 18 - 4 - 66
    local saved = { lang = ns.db.language, height = methods.GetStringHeight, section = ns.db.optionsSection }
    local page
    local ok, err = pcall(function()
        local function PageOf(f)
            local p = f and f.__parent
            while p and not p.key do p = p.__parent end
            return p and p.key
        end
        -- the newest copy (every login of the mock builds the pages again)
        local function Label(key)
            local found
            for _, o in ipairs(allFrames) do
                if o.__kind == "FontString" and o.__text == ns.L[key] and o.__pts and o.__pts.TOPLEFT and PageOf(o) then found = o end
            end
            return found
        end
        local QUEST, RADIUS, ARROW = "Questing mode", "Questing radius", "Arrow to the nearest gold ring"
        local REMIND = "Remind me to visit the trainer (5 points before the end of a rank)"
        -- where they are: Leveling, and nowhere on Map & minimap
        for _, key in ipairs({ QUEST, RADIUS, ARROW }) do
            local fs = Label(key)
            assert(fs, "no '" .. key .. "' in the options")
            assert(PageOf(fs) == "level", ("'%s' is on the page %s, not Leveling"):format(key, tostring(PageOf(fs))))
            for _, o in ipairs(allFrames) do
                if o.__kind == "FontString" and o.__text == ns.L[key] then
                    assert(PageOf(o) ~= "map", ("'%s' is still on Map & minimap"):format(key))
                end
            end
        end
        -- Map & minimap: room for the two tooltip rows (30 px each), the
        -- ones there already counted in
        local used, there = ns.OptionsUsedHeight(), 0
        for _, key in ipairs({ "World map tooltip", "Minimap tooltip" }) do
            local fs = Label(key)
            if fs and PageOf(fs) == "map" then there = there + 1 end
        end
        assert(used.map + (2 - there) * 30 <= ROOM, ("Map & minimap goes down to %d px of %d: no room for the %d tooltip rows still to come"):format(used.map, ROOM, 2 - there))
        -- the radius row hangs on a holder: its label and its < button
        local radius = Label(RADIUS)
        local holder = radius.__pts.TOPLEFT[1]
        assert(type(holder) == "table" and holder.__kind == "Frame" and PageOf(holder) == "level", "the radius row does not hang on a holder")
        local minus
        for _, o in ipairs(allFrames) do
            if o.__kind == "Button" and o.__pts and o.__pts.TOPLEFT and o.__pts.TOPLEFT[1] == holder then minus = o end
        end
        assert(minus, "the radius buttons do not hang on the holder")
        page = holder.__parent

        -- every language: the rows lie one below the other, the radius row
        -- moves with them, the page stays above the footer. Mock text layout
        -- as on the fishing page: 6 px a Latin letter, 11 px a CJK sign,
        -- 12 px a line.
        local function Px(text)
            local px = 0
            for ch in (text or ""):gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", ""):gmatch("[%z\1-\127\194-\244][\128-\191]*") do px = px + (#ch >= 3 and 11 or 6) end
            return px
        end
        local WIDTH = 470
        methods.GetStringHeight = function(self)
            local w = (self.__parent and self.__parent.__w or WIDTH) - 34
            return 12 * math.max(1, math.ceil(Px(self.__text) / w))
        end
        page.__w = WIDTH
        local seen, langs = {}, 0
        for _, lang in ipairs(ns.LANGUAGES) do
            if lang.code ~= "auto" then
                langs = langs + 1
                ns.db.language = lang.code ns.ApplyLanguage() opts:Refresh()
                ns.ShowOptionsSection("level")
                local remind, quest, arrow = Label(REMIND), Label(QUEST), Label(ARROW)
                assert(remind and quest and arrow and Label(RADIUS) == radius, lang.code .. ": a row of the block is not there")
                local function Top(fs) return fs.__pts.TOPLEFT[1].__pts.TOPLEFT[2] end
                local function Ends(fs) return Top(fs) - math.max(26, fs:GetStringHeight() + 12) end
                local q, h, a = Top(quest), holder.__pts.TOPLEFT[2], Top(arrow)
                assert(q <= Ends(remind), ("%s: the questing switch starts at %s, the trainer row ends at %s"):format(lang.code, q, Ends(remind)))
                assert(h <= Ends(quest), ("%s: the radius row starts at %s, the questing switch ends at %s"):format(lang.code, h, Ends(quest)))
                assert(a <= h - 30, ("%s: the arrow switch starts at %s, the radius row ends at %s"):format(lang.code, a, h - 30))
                assert(-Ends(arrow) <= ROOM, ("%s: Leveling goes down to %d px of %d"):format(lang.code, -Ends(arrow), ROOM))
                seen[h] = true
            end
        end
        assert(langs == 10, "test setup: " .. langs .. " languages") -- (esMX speaks esES)
        local places = 0
        for _ in pairs(seen) do places = places + 1 end
        assert(places > 1, "the radius row stands at the same place in every language: it does not move with the rows above it")
        -- narrower: the rows wrap more, the radius row goes down with them
        ns.db.language = "deDE" ns.ApplyLanguage() opts:Refresh()
        local wide = holder.__pts.TOPLEFT[2]
        page.__w = 300
        page.__scripts.OnSizeChanged(page, 300, 400)
        assert(holder.__pts.TOPLEFT[2] < wide, ("narrower: the radius row did not move down (%s / %s)"):format(wide, holder.__pts.TOPLEFT[2]))
    end)
    methods.GetStringHeight = saved.height
    if page then page.__w = nil end
    ns.db.language = saved.lang ns.ApplyLanguage()
    ns.ShowOptionsSection(saved.section)
    opts:Refresh()
    assert(ok, err)
end)
-- 0.2.2 P1 point 1 (a CurseForge comment, 21.11.2026): our world map pins
-- lie on quest symbols and take the mouse from them. Options > Map &
-- minimap: "World map tooltip < Always | With Shift >". Always is the
-- default, as before. With Shift: without Shift a world map pin takes no
-- mouse - what lies below it gets it -, with Shift held as before; the run
-- target's pin too. A Shift press switches only the shown pins, from the
-- game's MODIFIER_STATE_CHANGED, which is registered only while "With
-- Shift" is chosen. Minimap pins never take the mouse, either way.
step("World map pins 0.2.2: the tooltip always or only with Shift - without Shift the mouse goes through; Shift as before; the run target too (0.2.2 P1)", function()
    local Z = 1439
    local opts = _G.GathercraftOptions
    local ROOM = 640 - 112 - 18 - 4 - 66
    local keep = { nodes = ns.db.nodes[Z], tip = ns.db.worldPinTip, shift = IsShiftKeyDown, owner = rawget(GameTooltip, "GetOwner"),
        hide = rawget(GameTooltip, "Hide"), section = ns.db.optionsSection }
    local ok, err = pcall(function()
        local function Watching()
            for _ in pairs(eventFrames.MODIFIER_STATE_CHANGED or {}) do return true end
            return false
        end
        local shift = false
        IsShiftKeyDown = function() return shift end
        local function Press(down, key)
            shift = down
            fire("MODIFIER_STATE_CHANGED", key or "LSHIFT", down and 1 or 0)
        end
        ns.db.worldPinTip = nil
        ns.WorldPinTipChanged()
        local herb = { id = "o1617", name = "Silverleaf", type = "herb", x = 0.30, y = 0.40, count = 1, last = 1 }
        local ore = { id = "o1731", name = "Copper Vein", type = "ore", x = 0.60, y = 0.40, count = 1, last = 1 }
        ns.db.nodes[Z] = { herb }
        ns.NotifyNodesChanged() advance(1)
        -- the newest world map pin of a node (pins are made again and reused)
        local function World(n)
            local found
            for _, f in ipairs(allFrames) do
                if f.node == n and f.isWorld and not f.isTarget then found = f end
            end
            return found
        end
        local pin = World(herb)
        assert(pin, "test setup: no world map pin for the herb")
        -- HereBeDragons shows it when the map opens (not the mock)
        pin:Hide() pin:Show()

        -- 1. as before: the pin takes the mouse, nothing watches Shift
        assert(pin:IsMouseEnabled(), "Always: the world map pin takes no mouse")
        assert(not Watching(), "Always: something watches the Shift key (MODIFIER_STATE_CHANGED registered)")
        Press(true) Press(false)
        assert(pin:IsMouseEnabled(), "Always: a Shift press took the mouse from the pin")

        -- 2. the row under Map & minimap: < Always | With Shift >
        ns.ShowOptionsSection("map")
        opts:Refresh()
        local label, value, minus, plus
        for _, o in ipairs(allFrames) do
            if o.__kind == "FontString" and o.__text == ns.L["World map tooltip"] and o.__pts and o.__pts.TOPLEFT then label = o end
        end
        assert(label, "no row 'World map tooltip' in the options")
        local p = label.__parent
        while p and not p.key do p = p.__parent end
        assert(p and p.key == "map", "the row is not under Map & minimap")
        local y = label.__pts.TOPLEFT[2] + 4
        for _, o in ipairs(allFrames) do
            if o.__kind == "Button" and o.__parent == label.__parent and o.__pts and o.__pts.TOPLEFT and o.__pts.TOPLEFT[2] == y then minus = o end
        end
        assert(minus, "test setup: the < button of the row")
        for _, o in ipairs(allFrames) do
            if o.__kind == "FontString" and o.__pts and o.__pts.LEFT and o.__pts.LEFT[1] == minus then value = o end
        end
        for _, o in ipairs(allFrames) do
            if o.__kind == "Button" and value and o.__pts and o.__pts.LEFT and o.__pts.LEFT[1] == value then plus = o end
        end
        assert(value and plus, "test setup: the value and the > button of the row")
        assert(value:GetText() == ns.L["Always"], "the row does not show Always by default: " .. tostring(value:GetText()))
        assert(pcall(minus.__scripts.OnEnter, minus), "the row's tooltip")
        plus.__scripts.OnClick(plus)
        assert(ns.db.worldPinTip == "shift" and value:GetText() == ns.L["With Shift"], "> does not choose With Shift: " .. tostring(ns.db.worldPinTip))
        assert(Watching(), "With Shift: nothing watches the Shift key")

        -- 3. With Shift: the shown pin lets the mouse through ...
        assert(not pin:IsMouseEnabled(), "With Shift, no Shift held: the pin still takes the mouse")
        -- ... Shift held: it takes it, its tooltip shows as before
        Press(true)
        assert(pin:IsMouseEnabled(), "Shift held: the pin takes no mouse")
        local mark = #log
        pin.__scripts.OnEnter(pin)
        local named = false
        for i = mark + 1, #log do if log[i] == "TT " .. herb.name then named = true end end
        assert(named, "Shift held: the pin's tooltip does not name the herb")
        -- ... Shift let go while its tooltip shows: the mouse goes through, the tooltip goes
        local hidden = 0
        GameTooltip.GetOwner = function() return pin end
        GameTooltip.Hide = function() hidden = hidden + 1 end
        Press(false)
        assert(not pin:IsMouseEnabled(), "Shift let go: the pin still takes the mouse")
        assert(hidden >= 1, "Shift let go: the pin's tooltip stays")
        GameTooltip.GetOwner, GameTooltip.Hide = keep.owner, keep.hide
        -- the right Shift too; another key changes nothing
        Press(true, "RSHIFT")
        assert(pin:IsMouseEnabled(), "right Shift held: the pin takes no mouse")
        Press(false, "RSHIFT")
        fire("MODIFIER_STATE_CHANGED", "LCTRL", 1)
        assert(not pin:IsMouseEnabled(), "Ctrl pressed: the pin takes the mouse")

        -- 4. the map opens while Shift is held, or not: each pin as Shift is now
        pin:Hide()
        shift = true
        pin:Show()
        assert(pin:IsMouseEnabled(), "shown while Shift is held: the pin takes no mouse")
        pin:Hide()
        shift = false
        pin:Show()
        assert(not pin:IsMouseEnabled(), "shown without Shift: the pin takes the mouse")
        -- a hidden pin is not touched by a Shift press (only the shown ones are)
        pin:Hide()
        Press(true)
        assert(not pin:IsMouseEnabled(), "a Shift press switched a hidden pin")
        Press(false)
        pin:Show()

        -- 5. a new node's pin, made while With Shift is chosen
        table.insert(ns.db.nodes[Z], ore)
        ns.NotifyNodesChanged("add", Z, ore) advance(1)
        local orePin = World(ore)
        assert(orePin and not orePin:IsMouseEnabled(), "a new pin takes the mouse without Shift")

        -- 6. the run target's pin: the same; its minimap pin never takes the mouse
        ns.SetRouteTarget(Z, herb)
        local tw, tm = ns.RouteTargetPins()
        assert(tw and tm, "test setup: no run target pins")
        -- (right as it is placed, before the map shows it: counter-probe P1e)
        assert(not tw:IsMouseEnabled(), "With Shift: the run target's pin takes the mouse as it is placed")
        tw:Hide() tw:Show()
        assert(not tw:IsMouseEnabled(), "With Shift: the run target's pin takes the mouse without Shift")
        Press(true)
        assert(tw:IsMouseEnabled(), "Shift held: the run target's pin takes no mouse")
        assert(not tm:IsMouseEnabled(), "the run target's minimap pin takes the mouse")
        Press(false)
        assert(not tw:IsMouseEnabled(), "Shift let go: the run target's pin still takes the mouse")

        -- 7. minimap pins never take the mouse, either way
        for _, f in ipairs(allFrames) do
            if (f.node == herb or f.node == ore) and f.isMini then
                assert(not f:IsMouseEnabled(), "a minimap pin takes the mouse")
            end
        end

        -- 8. kept over a /reload: the game forgets every registered event,
        -- the login registers it again while chosen (counter-probe P1h)
        eventFrames.MODIFIER_STATE_CHANGED = nil
        fire("PLAYER_LOGIN") advance(2)
        assert(ns.db.worldPinTip == "shift" and Watching(), "after a login: With Shift is gone, or nothing watches Shift")

        -- 9. back to Always: every pin takes the mouse, the shown, the hidden, the run target's; nothing watches Shift
        ns.ShowOptionsSection("map")
        opts:Refresh()
        for _, o in ipairs(allFrames) do
            if o.__kind == "FontString" and o.__text == ns.L["World map tooltip"] and o.__pts and o.__pts.TOPLEFT then label = o end
        end
        y = label.__pts.TOPLEFT[2] + 4
        for _, o in ipairs(allFrames) do
            if o.__kind == "Button" and o.__parent == label.__parent and o.__pts and o.__pts.TOPLEFT and o.__pts.TOPLEFT[2] == y then minus = o end
        end
        orePin:Hide()
        minus.__scripts.OnClick(minus)
        assert(ns.db.worldPinTip == nil, "< does not go back to Always: " .. tostring(ns.db.worldPinTip))
        assert(pin:IsMouseEnabled() and orePin:IsMouseEnabled() and tw:IsMouseEnabled(), "Always again: a pin takes no mouse")
        assert(not Watching(), "Always again: something still watches the Shift key")

        -- 10. every language has the texts; the page fits
        for lang, d in pairs(ns.Locales) do
            for _, key in ipairs({ "World map tooltip", "Always", "With Shift",
                "With Shift: the pins let the mouse through to what lies below them, such as quest symbols. Hold Shift to point at a pin." }) do
                assert(d[key] and d[key] ~= key, lang .. ": not translated: " .. key)
            end
        end
        local used = ns.OptionsUsedHeight()
        assert(used.map <= ROOM, ("Map & minimap goes down to %d px of %d"):format(used.map, ROOM))
    end)
    if ns.ClearRouteTarget then ns.ClearRouteTarget() end
    IsShiftKeyDown, GameTooltip.GetOwner, GameTooltip.Hide = keep.shift, keep.owner, keep.hide
    ns.db.worldPinTip = keep.tip
    if ns.WorldPinTipChanged then ns.WorldPinTipChanged() end
    ns.db.nodes[Z] = keep.nodes
    ns.NotifyNodesChanged() advance(1)
    ns.ShowOptionsSection(keep.section)
    if not ok then error(err, 0) end
end)
-- 0.2.2 P1 point 2 (a CurseForge user: "any way to hide or change the
-- tooltips"): Options > Map & minimap, "Minimap tooltip < Always | With
-- Shift | Never >". Always is the default (0.2.1 A5 stays). With Shift: ours
-- only while Shift is held; Never: ours never. The learning by pointing
-- ("Learn nodes you point at") goes on with every choice.
-- And Sven's debug line of 21.11.2026 while looting a quest object
-- ("minimap tooltip [LootFrame.ScrollBox.ScrollTarget..., ignored]"): the
-- loot window lay over the minimap, the game's tooltip was the loot item's.
-- Under the mouse is the loot button, not the minimap: ours does not show,
-- nothing is learned - the line only says what was ignored.
step("Minimap tooltip 0.2.2: always, only with Shift or never - learning goes on either way; a loot window over the minimap shows none of ours (0.2.2 P1)", function()
    local Z = 1466
    local opts = _G.GathercraftOptions
    local names = GathercraftNodeNames and GathercraftNodeNames[GetLocale()]
    local herbName = names and names[1618] or "Peacebloom"
    local keep = { nodes = ns.db.nodes[Z], map = player.map, x = player.x, y = player.y, foci = GetMouseFoci, focus = GetMouseFocus,
        cursor = GetCursorPosition, cvar = GetCVar, learnOff = ns.db.minimapLearnOff, tip = ns.db.miniPinTip, shift = IsShiftKeyDown,
        section = ns.db.optionsSection }
    local mm, gt, texts = {}, {}, {}
    for _, k in ipairs({ "IsMouseOver", "GetCenter", "GetWidth", "GetHeight", "GetZoom", "GetEffectiveScale" }) do mm[k] = rawget(Minimap, k) end
    for _, k in ipairs({ "IsShown", "GetOwner", "NumLines" }) do gt[k] = rawget(GameTooltip, k) end
    local pinOver = {}
    local ok, err = pcall(function()
        local lines, owner, onPin, shift = {}, UIParent, false, false
        IsShiftKeyDown = function() return shift end
        Minimap.IsMouseOver = function() return true end
        Minimap.GetCenter = function() return 500, 400 end
        Minimap.GetWidth = function() return 140 end
        Minimap.GetHeight = function() return 140 end
        Minimap.GetZoom = function() return 0 end
        Minimap.GetEffectiveScale = function() return 1 end
        GameTooltip.IsShown = function() return #lines > 0 end
        GameTooltip.GetOwner = function() return owner end
        GameTooltip.NumLines = function() return #lines end
        for i = 1, 3 do
            local fs = _G["GameTooltipTextLeft" .. i] or newObject("FontString", "GameTooltipTextLeft" .. i)
            _G["GameTooltipTextLeft" .. i] = fs
            texts[i] = rawget(fs, "GetText")
            fs.GetText = function() return lines[i] end
        end
        GetCursorPosition = function() return 540, 400 end
        GetCVar = function() return "0" end
        GetMouseFoci = function() return { Minimap } end
        ns.db.minimapLearnOff, ns.db.miniPinTip = nil, nil
        player.map, player.x, player.y = Z, 0.5, 0.5
        local mapID, cx, cy = ns.CursorOnMap()
        assert(mapID == Z and cx and cy, "test setup: the cursor on the map")
        local herb = { id = "o1618", name = herbName, type = "herb", x = cx, y = cy, count = 1, last = 1 }
        ns.db.nodes[Z] = { herb }
        ns.NotifyNodesChanged()
        fire("ZONE_CHANGED_NEW_AREA") advance(1)
        local function HerbPins()
            for _, f in ipairs(allFrames) do
                if f.node == herb and f.isMini and not f.isTarget and not pinOver[f] then
                    pinOver[f] = { rawget(f, "IsMouseOver"), f.__shown }
                    pinOver[#pinOver + 1] = f
                    f.IsMouseOver = function() return onPin end
                end
                if pinOver[f] and f.node == herb then f.__shown = true end
            end
        end
        local function Wait(t)
            for _ = 1, math.floor(t / 0.05 + 0.5) do HerbPins() advance(0.05) end
        end
        local function Tip() return _G.GathercraftMinimapTooltip end
        local function Shows() local t = Tip() return t ~= nil and t:IsShown() and t.node == herb end
        -- the mouse away (long enough that the same name counts again), then
        -- onto the herb with the game showing these lines, owned by ...
        local function Point(newLines, newOwner)
            onPin, lines = false, {}
            Wait(6)
            assert(not Shows(), "test setup: ours still shown with the mouse away")
            herb.seenAt, herb.upAt = nil, nil
            onPin, lines, owner = true, newLines, newOwner
            Wait(1)
        end
        HerbPins()

        -- 1. Always (the default, as before): ours shows; the look is learned
        Point({ herbName }, UIParent)
        assert(Shows(), "Always: ours does not show")
        assert(herb.seenAt, "Always: the look is not learned")

        -- 2. the row under Map & minimap: < Always | With Shift | Never >
        ns.ShowOptionsSection("map")
        opts:Refresh()
        local label, value, minus, plus
        for _, o in ipairs(allFrames) do
            if o.__kind == "FontString" and o.__text == ns.L["Minimap tooltip"] and o.__pts and o.__pts.TOPLEFT then label = o end
        end
        assert(label, "no row 'Minimap tooltip' in the options")
        local p = label.__parent
        while p and not p.key do p = p.__parent end
        assert(p and p.key == "map", "the row is not under Map & minimap")
        local y = label.__pts.TOPLEFT[2] + 4
        for _, o in ipairs(allFrames) do
            if o.__kind == "Button" and o.__parent == label.__parent and o.__pts and o.__pts.TOPLEFT and o.__pts.TOPLEFT[2] == y then minus = o end
        end
        for _, o in ipairs(allFrames) do
            if o.__kind == "FontString" and minus and o.__pts and o.__pts.LEFT and o.__pts.LEFT[1] == minus then value = o end
        end
        for _, o in ipairs(allFrames) do
            if o.__kind == "Button" and value and o.__pts and o.__pts.LEFT and o.__pts.LEFT[1] == value then plus = o end
        end
        assert(minus and value and plus, "test setup: the buttons and the value of the row")
        assert(value:GetText() == ns.L["Always"], "the row does not show Always by default: " .. tostring(value:GetText()))
        assert(pcall(plus.__scripts.OnEnter, plus), "the row's tooltip")
        plus.__scripts.OnClick(plus)
        assert(ns.db.miniPinTip == "shift" and value:GetText() == ns.L["With Shift"], "> does not choose With Shift: " .. tostring(ns.db.miniPinTip))

        -- 3. With Shift: ours not without Shift - the look is learned all the same
        Point({ herbName }, UIParent)
        assert(not Shows(), "With Shift, no Shift held: ours shows")
        assert(herb.seenAt, "With Shift: the look is not learned any more")
        -- Shift held: ours, below the game's as in 0.2.1; let go: gone
        shift = true
        Wait(0.3)
        assert(Shows(), "With Shift, Shift held: ours does not show")
        local at = Tip().__pts and Tip().__pts.TOPLEFT
        assert(at and at[1] == GameTooltip, "Shift held: ours is not below the game's tooltip")
        shift = false
        Wait(0.3)
        assert(not Shows(), "With Shift, Shift let go: ours stays")

        -- 4. Never: not even with Shift - the look is learned all the same
        plus.__scripts.OnClick(plus)
        assert(ns.db.miniPinTip == "never" and value:GetText() == ns.L["Never"], "> does not choose Never: " .. tostring(ns.db.miniPinTip))
        Point({ herbName }, UIParent)
        assert(not Shows(), "Never: ours shows")
        assert(herb.seenAt, "Never: the look is not learned any more")
        shift = true
        Wait(0.3)
        assert(not Shows(), "Never, Shift held: ours shows")
        shift = false
        -- the game shows nothing there: ours not next to the pin either
        Point({}, UIParent)
        assert(not Shows(), "Never, the game shows nothing: ours shows next to the pin")
        -- the switch "Learn nodes you point at" still works on its own
        ns.db.minimapLearnOff = true
        Point({ herbName }, UIParent)
        assert(herb.seenAt == nil, "learning off: the look is learned")
        ns.db.minimapLearnOff = nil

        -- 5. > again: back to Always; kept as Always (nothing saved)
        plus.__scripts.OnClick(plus)
        assert(ns.db.miniPinTip == nil and value:GetText() == ns.L["Always"], "> after Never does not go back to Always: " .. tostring(ns.db.miniPinTip))
        Point({ herbName }, UIParent)
        assert(Shows(), "Always again: ours does not show")
        -- an odd saved value: Always
        ns.db.miniPinTip = "sometimes"
        Point({ herbName }, UIParent)
        assert(Shows(), "an odd saved value: ours does not show")
        ns.db.miniPinTip = nil

        -- 6. Sven's loot window over the minimap: the game's tooltip is the
        -- loot item's, under the mouse the loot button - ours does not show,
        -- nothing is learned (the debug line says "ignored")
        local lootFrame = newObject("Frame", nil, UIParent) -- (a loot window: not a child of the minimap)
        local lootButton = newObject("Button", nil, lootFrame)
        lootButton:SetSize(150, 40)
        Point({}, UIParent)
        herb.seenAt = nil
        GetMouseFoci = function() return { lootButton } end
        lines, owner = { herbName, "Quest Item" }, lootButton
        Wait(1)
        assert(not Shows(), "a loot window over the minimap: ours shows")
        assert(herb.seenAt == nil, "a loot window over the minimap: the loot item's tooltip is learned as a look")
        GetMouseFoci = function() return { Minimap } end
        onPin, lines = false, {}
        Wait(0.3)

        -- 7. every language has the texts; the page fits
        for lang, d in pairs(ns.Locales) do
            for _, key in ipairs({ "Minimap tooltip", "Never",
                "With Shift: Gathercraft's tooltip on the minimap shows only while you hold Shift. Never: it does not show.",
                "Learning the nodes you point at works with every setting." }) do
                assert(d[key] and d[key] ~= key, lang .. ": not translated: " .. key)
            end
        end
        local used = ns.OptionsUsedHeight()
        local ROOM = 640 - 112 - 18 - 4 - 66
        assert(used.map <= ROOM, ("Map & minimap goes down to %d px of %d"):format(used.map, ROOM))
    end)
    for _, f in ipairs(pinOver) do f.IsMouseOver, f.__shown = pinOver[f][1], pinOver[f][2] end
    GetMouseFoci, GetMouseFocus, GetCursorPosition, GetCVar, IsShiftKeyDown = keep.foci, keep.focus, keep.cursor, keep.cvar, keep.shift
    for _, k in ipairs({ "IsMouseOver", "GetCenter", "GetWidth", "GetHeight", "GetZoom", "GetEffectiveScale" }) do Minimap[k] = mm[k] end
    for _, k in ipairs({ "IsShown", "GetOwner", "NumLines" }) do GameTooltip[k] = gt[k] end
    for i = 1, 3 do if _G["GameTooltipTextLeft" .. i] then _G["GameTooltipTextLeft" .. i].GetText = texts[i] end end
    ns.db.nodes[Z], ns.db.minimapLearnOff, ns.db.miniPinTip = keep.nodes, keep.learnOff, keep.tip
    player.map, player.x, player.y = keep.map, keep.x, keep.y
    fire("ZONE_CHANGED_NEW_AREA") advance(1)
    ns.NotifyNodesChanged() advance(1)
    ns.ShowOptionsSection(keep.section)
    if not ok then error(err, 0) end
end)
-- The visit log /gcr visitlog (diagnosis D, Sven 20.11.2026; built on
-- dev-0.2-diag, in the release since 0.2.2 P1 point 3 for the respawn
-- measurement). Its lines are English, like /gcr detest's.
local function VisitLines(from) -- what /gcr visitlog printed after log line from, without its "visitlog "
    local out = {}
    for i = from + 1, #log do
        local text = log[i]:match("^PRINT visitlog (.*)$")
        if text then out[#out + 1] = text end
    end
    return out
end
-- the saved data without the visit log's own keys (deep copy)
local function VisitDbCopy()
    local c = DetestCopy(ns.db)
    c.visitLogOn, c.visitLog, c.visitLogDropped = nil, nil, nil
    return c
end
step("Visit log: /gcr visitlog on|off|status|clear - off unless turned on, kept in the saved data only, at most 10000 entries (0.2.2 P1 point 3, from dev-0.2-diag 1)", function()
    local ok, err = pcall(function()
        -- off unless you turn it on: nothing of it in the saved data
        assert(ns.db.visitLogOn == nil and ns.db.visitLog == nil and ns.db.visitLogDropped == nil, "the visit log is there before it was turned on")
        assert(ns.VisitLogOn and ns.VisitLogOn() == false, "ns.VisitLogOn: not off at the start")
        local db = VisitDbCopy()
        -- something else than on, off, status or clear: how to use it, nothing turned on
        local mark = #log
        slash("visitlog what")
        local lines = VisitLines(mark)
        assert(#lines == 1 and lines[1]:find("/gcr visitlog on|off|status|clear", 1, true), "an unknown word: " .. table.concat(lines, " / "))
        assert(ns.db.visitLogOn == nil, "an unknown word turned it on")
        -- status, off
        mark = #log
        slash("visitlog status")
        lines = VisitLines(mark)
        local version = C_AddOns and C_AddOns.GetAddOnMetadata and C_AddOns.GetAddOnMetadata("Gathercraft", "Version") or GetAddOnMetadata("Gathercraft", "Version")
        assert(#lines == 1 and lines[1] == ("status: off, 0 entries (at most 10000); Gathercraft %s"):format(tostring(version)), "status while off: " .. table.concat(lines, " / "))
        -- writing while off: nothing
        ns.VisitLogAdd("V;1;1;herb;o1;0.1;0.1;1;1;empty;T;-;25")
        assert(ns.db.visitLog == nil, "written while off")
        -- on: kept in the saved data (stays on over /reload), says that nothing is sent
        mark = #log
        slash("visitlog on")
        lines = VisitLines(mark)
        assert(#lines == 1 and lines[1]:find("^on: ") and lines[1]:find("only on this computer", 1, true)
            and lines[1]:find("nothing is sent", 1, true) and lines[1]:find("/gcr visitlog off", 1, true), "on: " .. table.concat(lines, " / "))
        assert(ns.db.visitLogOn == true and ns.VisitLogOn() == true, "not on in the saved data")
        assert(ns.db.visitLog == nil, "turning it on wrote an entry")
        mark = #log
        slash("visitlog on")
        lines = VisitLines(mark)
        assert(#lines == 1 and lines[1]:find("already on", 1, true), "on again: " .. table.concat(lines, " / "))
        -- at most 10000 entries: the oldest go, and how many is counted
        assert(ns.VisitLogMax == 10000, "at most: " .. tostring(ns.VisitLogMax))
        for i = 1, 10005 do ns.VisitLogAdd(("V;%d;1464;ore;o1731;0.5000;0.5000;1.0;1.0;empty;T;-;25"):format(1000000 + i)) end
        assert(#ns.db.visitLog == 10000 and ns.db.visitLogDropped == 5, ("entries %d, dropped %s"):format(#ns.db.visitLog, tostring(ns.db.visitLogDropped)))
        assert(ns.db.visitLog[1]:find("^V;1000006;") and ns.db.visitLog[10000]:find("^V;1010005;"), "not the newest 10000: " .. ns.db.visitLog[1])
        mark = #log
        slash("visitlog status")
        lines = VisitLines(mark)
        local range = (", from %s to %s"):format((date or os.date)("%d.%m. %H:%M", 1000006), (date or os.date)("%d.%m. %H:%M", 1010005))
        assert(#lines == 1 and lines[1] == ("status: on, 10000 entries (at most 10000), 5 older ones dropped%s; Gathercraft %s"):format(range, tostring(version)),
            "status while on: " .. table.concat(lines, " / "))
        mark = #log
        slash("visitlog")
        lines = VisitLines(mark)
        assert(#lines == 2 and lines[1]:find("^status: on, 10000 entries") and lines[2] == "/gcr visitlog on|off|status|clear", "no word: " .. table.concat(lines, " / "))
        -- off: what was written stays, nothing more is written
        mark = #log
        slash("visitlog off")
        lines = VisitLines(mark)
        assert(#lines == 1 and lines[1] == "off: 10000 entries kept (/gcr visitlog clear deletes them)", "off: " .. table.concat(lines, " / "))
        assert(ns.db.visitLogOn == nil and #ns.db.visitLog == 10000, "off: not off, or the entries are gone")
        ns.VisitLogAdd("V;2000000;1464;ore;o1731;0.5000;0.5000;1.0;1.0;empty;T;-;25")
        assert(#ns.db.visitLog == 10000 and ns.db.visitLog[10000]:find("^V;1010005;"), "written while off")
        mark = #log
        slash("visitlog off")
        lines = VisitLines(mark)
        assert(#lines == 1 and lines[1] == "already off", "off again: " .. table.concat(lines, " / "))
        -- clear: all gone
        mark = #log
        slash("visitlog clear")
        lines = VisitLines(mark)
        assert(#lines == 1 and lines[1] == "cleared: 10000 entries deleted", "clear: " .. table.concat(lines, " / "))
        assert(ns.db.visitLog == nil and ns.db.visitLogDropped == nil, "clear left entries")
        -- the rest of the saved data is as it was
        local diff = DetestDiff(db, VisitDbCopy(), "ns.db")
        assert(not diff, "the visit log changed the saved data: " .. tostring(diff))
        assert(ns.db.visitLogOn == nil, "on at the end")
    end)
    if not ok then ns.db.visitLogOn, ns.db.visitLog, ns.db.visitLogDropped = nil, nil, nil end
    if not ok then error(err, 0) end
end)
-- A farm run in Mulgore (1 yd = 0.0002 map x) with one of each kind of
-- visit: a target harvested, a point passed on the way, a target found
-- empty, one while fighting, a gather without own loot, /gcr skip, /gcr
-- unreachable, then two gathers outside a run (a new one, the same spawn
-- again). Returns what each step needs to check; the visit log is as the
-- caller set it. Used by points 2 and 3 (log off and on, the same run).
local function VisitRun()
    local keepNodes, keepArrive, keepMap, keepX, keepY = ns.db.nodes[1412], ns.db.arriveDist, player.map, player.x, player.y
    local OBJ = { Earthroot = { 1619, 2449 }, Peacebloom = { 1618, 2447 } }
    local seq = 0
    local function Node(name, xYd)
        return { id = "o" .. OBJ[name][1], name = name, type = "herb", item = OBJ[name][2], x = 0.5 + xYd / 5000, y = 0.5, count = 1, last = 1 }
    end
    local function At(xYd) player.map, player.x, player.y = 1412, 0.5 + xYd / 5000, 0.5 end
    local function Wait(s) for _ = 1, s * 2 do advance(0.5) end end
    local function Gather(name, spawn, withLoot)
        seq = seq + 1
        local id = "visitlog" .. seq
        fire("UNIT_SPELLCAST_SENT", "player", name, id, 2366)
        fire("UNIT_SPELLCAST_SUCCEEDED", "player", id, 2366)
        if withLoot ~= false then
            loot = { { guid = ("GameObject-0-1-1-1-%d-%s"):format(OBJ[name][1], spawn), item = OBJ[name][2], qty = 2 } }
            fire("LOOT_READY") fire("LOOT_OPENED")
            loot = {}
            fire("LOOT_CLOSED")
        end
    end
    local function aim(node)
        for _, p in ipairs(ns.run.path) do
            if p.node == node then ns.run.target, ns.run.targetPoint, ns.run.targetBest = node, p, nil return end
        end
        error("node not in the path: " .. tostring(node and node.name))
    end
    local A, P, D, C, B, E, F = Node("Earthroot", 0), Node("Earthroot", 150), Node("Earthroot", 300), Node("Earthroot", 450),
        Node("Earthroot", 600), Node("Earthroot", 750), Node("Peacebloom", 2500)
    local out = { A = A, P = P, D = D, C = C, B = B, E = E, F = F, arrive = {}, t0 = time(), g0 = GetTime() }
    local ok, err = pcall(function()
        ns.db.arriveDist = 20
        ns.db.nodes[1412] = { A, P, D, C, B, E, F }
        ns.NotifyNodesChanged() advance(1)
        At(-200)
        ns.StartRun("herb", 1412) Wait(1)
        -- a target, harvested
        aim(A) At(0) out.arrive.A = time() Wait(1)
        Gather("Earthroot", "VL0001")
        Wait(30)
        -- on the way to the next target: a point passed by, then the target, empty
        aim(D) At(150) out.arrive.P = time() Wait(30)
        aim(D) At(300) out.arrive.D = time() Wait(30)
        -- the target, found empty while fighting
        aim(C)
        UnitAffectingCombat = function() return true end
        At(450) out.arrive.C = time() Wait(30)
        UnitAffectingCombat = nil
        -- the target, a gather close by that brings no own loot
        aim(B) At(600) out.arrive.B = time() Wait(1)
        Gather("Earthroot", "VL0002", false)
        Wait(30)
        -- left out: /gcr skip, then /gcr unreachable
        aim(E) out.skipAt, out.skipX, out.skipY = time(), E.x, E.y slash("skip") advance(1)
        aim(F) out.unreachAt = time() slash("unreachable") advance(1)
        ns.StopRun() advance(1)
        -- outside a run: a gather at E's place (a new spawn), then the same spawn once more
        At(752) Wait(1)
        out.outsideAt = time()
        Gather("Earthroot", "VL0003")
        Wait(2)
        out.againAt = time()
        Gather("Earthroot", "VL0003")
        Wait(2)
    end)
    UnitAffectingCombat = nil
    if ns.run then ns.StopRun() end
    out.nodes = ns.db.nodes[1412]
    ns.db.nodes[1412], ns.db.arriveDist, player.map, player.x, player.y = keepNodes, keepArrive, keepMap, keepX, keepY
    ns.NotifyNodesChanged() advance(1)
    if not ok then error(err, 0) end
    return out
end
-- one entry split into its fields
local function VisitFields(text)
    local f = {}
    for v in (text .. ";"):gmatch("([^;]*);") do f[#f + 1] = v end
    return f
end
step("Visit log: every route point checked or left out with time, zone, point, kind and result, every own gather with its place and point (0.2.2 P1 point 3, from dev-0.2-diag 2)", function()
    local ok, err = pcall(function()
        -- off: the same run writes nothing
        assert(not ns.VisitLogOn(), "on at the start")
        VisitRun()
        assert(ns.db.visitLog == nil, "off, and written: " .. tostring(ns.db.visitLog and ns.db.visitLog[1]))
        -- on
        slash("visitlog on")
        local r = VisitRun()
        local list = ns.db.visitLog or {}
        local all = table.concat(list, "\n")
        local function Find(ev, id, result, node)
            for _, text in ipairs(list) do
                local f = VisitFields(text)
                if f[1] == ev and f[10] == result and (not node or f[6] == ("%.4f"):format(node.x)) then return f end
            end
            error(("no %s entry %s for %s at x %s:\n%s"):format(ev, result, tostring(id), node and ("%.4f"):format(node.x) or "-", all), 0)
        end
        local HBD = LibStub("HereBeDragons-2.0")
        local function CheckPoint(f, node, ev, x, y)
            x, y = x or node.x, y or node.y
            assert(f[3] == "1412" and f[4] == "herb" and f[5] == node.id, ev .. ": zone, type or id: " .. table.concat(f, ";"))
            assert(f[6] == ("%.4f"):format(x) and f[7] == ("%.4f"):format(y), ev .. ": the point: " .. table.concat(f, ";"))
            local wx, wy = HBD:GetWorldCoordinatesFromZone(x, y, 1412)
            assert(f[8] == ("%.1f"):format(wx) and f[9] == ("%.1f"):format(wy), ev .. ": world yards: " .. table.concat(f, ";"))
            assert(f[12] == "-", ev .. ": sk of an own point: " .. tostring(f[12]))
        end
        -- route point checks: the time is the arriving, then the result and target or on the way
        local want = { { "A", "harvested", "T" }, { "P", "passed", "W" }, { "D", "empty", "T" }, { "C", "empty", "TC" }, { "B", "unclear", "T" } }
        for _, w in ipairs(want) do
            local node = r[w[1]]
            local f = Find("V", w[1], w[2], node)
            CheckPoint(f, node, "V " .. w[1])
            assert(#f == 13, "V " .. w[1] .. ": fields " .. #f)
            -- the time of arriving: the tick that saw you there (this second or the next)
            local dt = tonumber(f[2]) - r.arrive[w[1]]
            assert(dt == 0 or dt == 1, ("V %s: time %s, arrived %s"):format(w[1], f[2], tostring(r.arrive[w[1]])))
            assert(f[11] == w[3], ("V %s: flags %s, want %s"):format(w[1], f[11], w[3]))
            assert(tonumber(f[13]) and tonumber(f[13]) >= 25 and tonumber(f[13]) <= 31, "V " .. w[1] .. ": seconds to the check " .. f[13])
        end
        -- left out
        local s = Find("S", "E", "skipped", { x = r.skipX })
        CheckPoint(s, r.E, "S skipped", r.skipX, r.skipY)
        assert(tonumber(s[2]) == r.skipAt and s[11] == "T" and s[13] == "300", "S skipped: " .. table.concat(s, ";"))
        local u = Find("S", "F", "unreachable", r.F)
        assert(u[5] == r.F.id and tonumber(u[2]) == r.unreachAt and u[11] == "T" and tonumber(u[13]) > 0, "S unreachable: " .. table.concat(u, ";"))
        -- own gathers: where it started, the point it was booked to, how far, in a run or not
        local gathers = {}
        for _, text in ipairs(list) do
            local f = VisitFields(text)
            if f[1] == "G" then gathers[#gathers + 1] = f end
        end
        assert(#gathers == 3, "own gathers: " .. #gathers .. "\n" .. all) -- (the one without own loot is no gather)
        local g1, g2, g3 = gathers[1], gathers[2], gathers[3]
        assert(#g1 == 17 and g1[10] == "booked" and g1[11] == "R" and g1[5] == "o1619" and g1[17] == "VL0001", "the harvest in the run: " .. table.concat(g1, ";"))
        assert(g1[13] == ("%.4f"):format(r.A.x) and tonumber(g1[15]) < 1, "booked to A: " .. table.concat(g1, ";"))
        assert(g1[6] == ("%.4f"):format(0.5) and g1[7] == ("%.4f"):format(0.5), "where it started: " .. table.concat(g1, ";"))
        assert(g2[10] == "booked" and g2[11] == "-" and g2[17] == "VL0003" and tonumber(g2[2]) >= r.outsideAt, "the gather outside a run: " .. table.concat(g2, ";"))
        assert(g2[6] == ("%.4f"):format(0.5 + 752 / 5000), "outside a run, where it started: " .. table.concat(g2, ";"))
        -- booked to E (750 yd, within 10 yd): E moves to the middle (751 yd), 1 yd from where it started, seen twice now
        assert(g2[5] == r.E.id and g2[13] == ("%.4f"):format(0.5 + 751 / 5000) and g2[15] == "1.0" and g2[16] == "2",
            "outside a run, its point: " .. table.concat(g2, ";"))
        assert(g3[10] == "again" and g3[17] == "VL0003" and tonumber(g3[2]) >= r.againAt, "the same spawn once more: " .. table.concat(g3, ";"))
        -- in the order they happened
        local last = 0
        for _, text in ipairs(list) do
            local tt = tonumber(VisitFields(text)[2])
            assert(tt and tt >= last - 31, "out of order: " .. text)
            last = math.max(last, tt)
        end
        slash("visitlog off") slash("visitlog clear")
    end)
    if not ok then ns.db.visitLogOn, ns.db.visitLog, ns.db.visitLogDropped = nil, nil, nil end
    if not ok then error(err, 0) end
end)
-- Point 3: what a run leaves behind, so that a run with the visit log off
-- and one with it on can be compared. Times are taken relative to the run's
-- start (a whole number within a day after it, and GetTime's seconds with
-- decimals in a line); counters of the saved data as how much they grew;
-- everything else as it is.
local function VisitNorm(v, t0, g0)
    if type(v) == "number" then
        if v == math.floor(v) and v >= t0 - 1 and v <= t0 + 86400 then return "T+" .. (v - t0) end
        return v
    end
    if type(v) == "string" then
        if g0 then
            v = v:gsub("%d+%.%d+", function(d)
                local n = tonumber(d)
                if n and n >= g0 - 1 and n <= g0 + 86400 then return ("G+%.2f"):format(n - g0) end
            end)
        end
        return (v:gsub("%d+", function(d)
            local n = tonumber(d)
            if n and n >= t0 - 1 and n <= t0 + 86400 then return "T+" .. (n - t0) end
        end))
    end
    if type(v) ~= "table" then return v end
    local c = {}
    for k, x in pairs(v) do c[k] = VisitNorm(x, t0, g0) end
    return c
end
-- every leaf of the saved data a run changed: path -> what it became
local function VisitChanges(a, b, t0, path, out)
    out = out or {}
    if type(a) == "table" and type(b) == "table" then
        for k, x in pairs(a) do VisitChanges(x, b[k], t0, path .. "." .. tostring(k), out) end
        for k, x in pairs(b) do if a[k] == nil then VisitChanges(nil, x, t0, path .. "." .. tostring(k), out) end end
        return out
    end
    if a == b then return out end
    if type(a) == "number" and type(b) == "number" and not (b == math.floor(b) and b >= t0 - 1 and b <= t0 + 86400) then
        out[path] = ("grew by %s"):format(tostring(b - a))
    elseif type(b) == "table" then
        for k, x in pairs(b) do VisitChanges(nil, x, t0, path .. "." .. tostring(k), out) end
    else
        out[path] = tostring(VisitNorm(b, t0))
    end
    return out
end
-- the first difference of two such pictures (deep), or nil
local function VisitFirstDiff(a, b, path)
    if type(a) ~= type(b) then return ("%s: %s, now %s"):format(path, tostring(a), tostring(b)) end
    if type(a) ~= "table" then
        if a ~= b and not (a ~= a and b ~= b) then return ("%s: %s, now %s"):format(path, tostring(a), tostring(b)) end
        return nil
    end
    for k, x in pairs(a) do
        local d = VisitFirstDiff(x, b[k], path .. "." .. tostring(k))
        if d then return d end
    end
    for k, x in pairs(b) do if a[k] == nil then return ("%s.%s: new (%s)"):format(path, tostring(k), tostring(x)) end end
end
-- one run of VisitRun with the debug lines on, and what it left behind
local visitHistory -- (0.2.3 P3) the run history every run of a step begins with
local function VisitPicture(logOn)
    local keepDebug = ns.db.debug
    ns.db.debug = true
    ns.db.visitLogOn = logOn or nil
    advance(120) -- (what sync had queued from before goes out first)
    -- (0.2.3 P3: every run begins with the same run history - a run adds one to
    -- its zone, and a full zone list shifts by one: what that changes depends on
    -- what the run before left, not on the visit log)
    if visitHistory then ns.db.runHistory = DetestCopy(visitHistory.v) end
    local before = VisitDbCopy()
    local mark, sent = #log, #sentMessages
    local ok, r = pcall(VisitRun)
    ns.db.debug = keepDebug
    ns.db.visitLogOn = nil
    if not ok then error(r, 0) end
    -- (sync sends go out on a timer: their place among the other lines depends
    -- on what was queued before, so they are compared as a sorted list of their own)
    local lines, msgs = {}, {}
    for i = mark + 1, #log do
        if not log[i]:find("^PRINT visitlog ") and not log[i]:find("sync|r sent", 1, true) then lines[#lines + 1] = VisitNorm(log[i], r.t0, r.g0) end
    end
    for i = sent + 1, #sentMessages do msgs[#msgs + 1] = VisitNorm(sentMessages[i], r.t0, r.g0) end
    table.sort(msgs)
    local nodes = {}
    for i, n in ipairs(r.nodes) do nodes[i] = VisitNorm(DetestCopy(n), r.t0) end
    return { lines = lines, sent = msgs, nodes = nodes, db = VisitChanges(before, VisitDbCopy(), r.t0, "ns.db") }
end
step("Visit log: on only writes - the same run off, on, and on with an error in every entry leaves the same nodes, choices, lines, sync messages and saved data behind (0.2.2 P1 point 3, from dev-0.2-diag 3)", function()
    local realConcat = table.concat
    visitHistory = { v = DetestCopy(ns.db.runHistory) }
    local ok, err = pcall(function()
        assert(not ns.VisitLogOn() and ns.db.visitLog == nil, "the visit log is on or has entries at the start")
        -- (once before, not compared: a first gather of a kind makes its
        -- counts in the saved data, the next ones only count up - without
        -- this the step held only after other steps had gathered the kind;
        -- 0.2.2 P1b, found running it alone)
        VisitPicture(false)
        local off = VisitPicture(false)
        assert(#off.lines > 20 and #off.nodes == 7 and next(off.db), ("the run says too little to compare: %d lines, %d nodes"):format(#off.lines, #off.nodes))
        assert(ns.db.visitLog == nil, "off, and written")
        -- on: the same run, and the visit log has its entries
        local on = VisitPicture(true)
        local entries = ns.db.visitLog and #ns.db.visitLog or 0
        assert(entries == 10, "on: entries " .. entries .. " (want 7 checks and left-outs and 3 gathers)")
        local d = VisitFirstDiff(off, on, "run")
        assert(not d, "on, the run went differently: " .. tostring(d))
        -- on, with an error in every entry: nothing written, no error anywhere, the run the same
        slash("visitlog clear")
        local errorsBefore = #errors
        table.concat = function(t, sep, ...)
            if sep == ";" and type(t) == "table" and (t[1] == "V" or t[1] == "S" or t[1] == "G" or (type(t[1]) == "string" and t[1]:find("^[VSG];"))) then
                error("visit log test: an error in the entry")
            end
            return realConcat(t, sep, ...)
        end
        local broken = VisitPicture(true)
        table.concat = realConcat
        assert(ns.db.visitLog == nil, "with an error in every entry, still written: " .. tostring(ns.db.visitLog and ns.db.visitLog[1]))
        assert(#errors == errorsBefore, "the error in an entry reached the addon: " .. tostring(errors[#errors]))
        d = VisitFirstDiff(off, broken, "run")
        assert(not d, "with an error in every entry, the run went differently: " .. tostring(d))
        -- nothing of it in what sync sent
        for _, m in ipairs(on.sent) do assert(not m:find("V;", 1, true) and not m:find("visit", 1, true), "sent: " .. m) end
        slash("visitlog clear")
    end)
    table.concat = realConcat
    ns.db.visitLogOn, ns.db.visitLog, ns.db.visitLogDropped = nil, nil, nil
    ns.db.runHistory, visitHistory = DetestCopy(visitHistory.v), nil
    if not ok then error(err, 0) end
end)
step("Visit log report: tools/visitlog_report.lua reads what the addon writes, from a SavedVariables copy too, and tells a same-point world from a random-point world (0.2.2 P1 point 3, from dev-0.2-diag 4)", function()
    local chunk = assert(loadfile(ROOT .. "/tools/visitlog_report.lua"), "no tools/visitlog_report.lua")
    local R = chunk("module")
    assert(type(R) == "table" and R.Analyse and R.SelfTest and R.ReadFile, "the report has no module part")
    local ok, err = pcall(function()
        -- the self-test: three seeds of each toy world, each verdict right
        for _, x in ipairs(R.SelfTest()) do
            assert(x.verdict == x.want, ("toy world %s, seed %d: %s, want %s (%s)"):format(x.world, x.seed, x.verdict, x.want, tostring(x.r.why)))
            assert(x.r.later.harvest[2] >= 20 and x.r.later.empty[2] >= 20, "toy world: too few revisits to judge")
        end
        -- the 95 % interval of a share (Wilson): 0 of 0, 5 of 10, 20 of 20
        local p, l, u = R.Wilson(5, 10)
        assert(math.abs(p - 0.5) < 1e-9 and math.abs(l - 0.2366) < 1e-3 and math.abs(u - 0.7634) < 1e-3, ("Wilson 5 of 10: %.4f %.4f %.4f"):format(p, l, u))
        p, l, u = R.Wilson(20, 20)
        assert(p == 1 and math.abs(l - 0.8389) < 1e-3 and u == 1, ("Wilson 20 of 20: %.4f %.4f %.4f"):format(p, l, u))
        -- what the addon writes: the run of point 2 with the log on
        slash("visitlog on")
        VisitRun()
        local entries = ns.db.visitLog or {}
        slash("visitlog off")
        local r = R.Analyse(entries, { min = 15, radius = 12 })
        -- full: the harvest in the run and the gather outside it (not the same spawn once more);
        -- empty: the target found empty (not the one in combat, not the one passed by)
        assert(r.counts.full == 2 and r.counts.empty == 1, ("looks read from the addon's entries: %d full, %d empty"):format(r.counts.full, r.counts.empty))
        assert(r.counts.other == #entries - 3, "other entries: " .. r.counts.other)
        r = R.Analyse(entries, { min = 15, radius = 12, passed = true })
        assert(r.counts.empty == 2, "with passed=1 the point passed by counts as empty: " .. r.counts.empty)
        -- a SavedVariables copy: read as data, nothing of it runs in the game's name
        local dir = os.getenv("TEMP") or os.getenv("TMPDIR") or (ROOT .. "/tools")
        local path = dir .. "/gathercraft_visitlog_test_1.lua"
        local f = assert(io.open(path, "w"))
        f:write("\nGathercraftDB = {\n[\"visitLogOn\"] = true,\n[\"visitLogDropped\"] = 3,\n[\"visitLog\"] = {\n")
        for _, e in ipairs(entries) do f:write(("%q,\n"):format(e)) end
        f:write("},\n}\nWoWFFarmDB = nil\n")
        f:close()
        local keepDB, keepOld = GathercraftDB, WoWFFarmDB
        local blocks = R.ReadFile(path)
        os.remove(path)
        assert(#blocks == 1 and #blocks[1].entries == #entries and blocks[1].dropped == 3, "a SavedVariables copy: " .. #blocks)
        -- read in a table of its own: the game's saved data stay as they are
        assert(GathercraftDB == keepDB and WoWFFarmDB == keepOld and GathercraftDB.visitLogDropped == nil, "reading the copy touched the saved data")
        -- a route_sim file: one block per run
        path = dir .. "/gathercraft_visitlog_test_2.txt"
        f = assert(io.open(path, "w"))
        f:write("# route_sim zone=1412 seed=1\n", entries[1], "\n", entries[2], "\n# route_sim zone=1412 seed=2\n", entries[3], "\n")
        f:close()
        blocks = R.ReadFile(path)
        os.remove(path)
        assert(#blocks == 2 and #blocks[1].entries == 2 and #blocks[2].entries == 1, "a route_sim file: blocks " .. #blocks)
        slash("visitlog clear")
    end)
    ns.db.visitLogOn, ns.db.visitLog, ns.db.visitLogDropped = nil, nil, nil
    if not ok then error(err, 0) end
end)
step("Visit log report: no verdict when the revisits come before the respawn time - a same-point world with 30 minutes to grow and rounds of 15 minutes (0.2.2 P1 point 3, from dev-0.2-diag 4b)", function()
    local R = assert(loadfile(ROOT .. "/tools/visitlog_report.lua"), "no tools/visitlog_report.lua")("module")
    for seed = 1, 3 do
        local r = R.Analyse(R.Toy("same", seed, { respawn = 1800, rounds = { 15, 15, 15, 15, 15, 15 } }), { min = 15, radius = 12 })
        assert(r.later.harvest[2] >= 20 and r.later.empty[2] >= 20, ("seed %d: too few revisits to test the rule (%d, %d)"):format(seed, r.later.harvest[2], r.later.empty[2]))
        assert(r.verdict == "undecided" and r.why:find("before the respawn time", 1, true),
            ("seed %d: %s (%s) - after a harvest %.0f %% full"):format(seed, r.verdict, tostring(r.why), r.afterHarvest[1] * 100))
    end
    -- the worlds it must still tell apart: three seeds each, and the slow one in the self-test
    local slow = 0
    for _, x in ipairs(R.SelfTest()) do
        assert(x.verdict == x.want, ("self-test %s seed %d: %s, want %s"):format(x.world, x.seed, x.verdict, x.want))
        if x.world == "same, slow" then slow = slow + 1 end
    end
    assert(slow == 3, "the self-test has no slow world: " .. slow)
end)
step("Visit log report: after a harvest against after an empty look within each kind - a random-point world with a dense and a sparse kind is no same-point world (0.2.2 P1 point 3, from dev-0.2-diag 4c)", function()
    local R = assert(loadfile(ROOT .. "/tools/visitlog_report.lua"), "no tools/visitlog_report.lua")("module")
    for seed = 1, 3 do
        local r = R.Analyse(R.Toy("pool", seed, { shares = { 0.7, 0.1 } }), { min = 15, radius = 12 })
        assert(r.pooled and r.difference and r.kindsUsed, "no difference within kinds")
        -- over all points the dense kind makes "after a harvest" fuller ...
        assert(r.pooled[1] >= 0.25, ("seed %d: over all %+.0f points - the toy world shows no difference of kinds"):format(seed, r.pooled[1] * 100))
        -- ... within each kind it is not
        assert(r.kindsUsed == 2 and math.abs(r.difference[1]) < 0.12, ("seed %d: within kinds %+.0f points (%d kinds)"):format(seed, r.difference[1] * 100, r.kindsUsed))
        assert(r.verdict == "random free point", ("seed %d: %s (%s)"):format(seed, r.verdict, tostring(r.why)))
    end
    -- "same point" needs a point to come back nearly always: 80 % (lower bound) and 25 points within kinds
    local r = R.Analyse(R.Toy("same", 1), { min = 15, radius = 12 })
    assert(r.verdict == "same point" and r.afterHarvest[2] >= 0.8 and r.difference[2] >= 0.25, "the same-point world: " .. r.verdict)
    for _, x in ipairs(R.SelfTest()) do
        assert(x.verdict == x.want, ("self-test %s seed %d: %s, want %s"):format(x.world, x.seed, x.verdict, x.want))
    end
end)
-- 0.2.2 P1 (Fahrplan ab 0.2.2): the test builds had marks of their own -
-- 0.2.2-a1 for part 1a, 0.2.2-a2 for part 1b, 0.2.2-a3 for P2, 0.2.2-a4 for its R1
-- fixes, 0.2.2-a5 for its R2 fix, 0.2.2-a6 for the route line's world map dots
-- (W5), 0.2.2-a7 for W1-W3, 0.2.2-a8 for W4 - and no What's new window. The
-- release (Sven, 22.11.2026) says 0.2.2, has its What's new and the changelog
-- with the date.
step("Version 0.2.2: the TOC says it, /gcr shows it, the What's new window of 0.2.2 once after 0.2.2-a8, 0.2.2-a7, 0.2.2-a6, 0.2.2-a5, 0.2.2-a4, 0.2.2-a3, 0.2.2-a2, 0.2.2-a1, 0.2.1, 0.2.1-a1, 0.2.0 or 0.1.23 (0.2.2)", function()
    local version = toc:match("## Version: ([%w%.%-]+)")
    -- a 0.2.3 test build: the TOC says its mark (own step); the window checked is 0.2.2's
    assert(version == "0.2.3-a3", "TOC version: " .. tostring(version))
    version = "0.2.2"
    local function Read(name) local f = assert(io.open(ROOT .. "/" .. name)) local s = f:read("*a") f:close() return s end
    -- "What's new" has the entry of 0.2.2, none for a test build
    local welcome = Read("Welcome.lua")
    local entry = welcome:match('%["0%.2%.2"%] = "([^"]+)"')
    assert(entry, "Welcome.lua has no What's new entry for 0.2.2")
    for _, mark in ipairs({ "0.2.2-a8", "0.2.2-a7", "0.2.2-a6", "0.2.2-a5", "0.2.2-a4", "0.2.2-a3", "0.2.2-a2", "0.2.2-a1" }) do
        assert(not welcome:find('["' .. mark .. '"]', 1, true), "Welcome.lua has a What's new entry for the test build " .. mark)
    end
    -- the changelog has its section, with the date
    assert(Read("CHANGELOG.md"):match("^(## v[^\r\n]*)") == "## v0.2.2 – 2026-11-23", "the changelog has no section for 0.2.2")
    -- /gcr: the main window shows the TOC version ("v" and it)
    assert(Read("Main.lua"):find('version:SetText(v and ("v" .. v) or "")', 1, true), "the main window does not show the TOC version")
    local keep = { meta = C_AddOns.GetAddOnMetadata, last = ns.db.lastVersion, fresh = ns.freshInstall }
    local ok, err = pcall(function()
        C_AddOns.GetAddOnMetadata = function(_, field) if field == "Version" then return version end end
        ns.freshInstall = false
        for _, before in ipairs({ "0.2.2-a8", "0.2.2-a7", "0.2.2-a6", "0.2.2-a5", "0.2.2-a4", "0.2.2-a3", "0.2.2-a2", "0.2.2-a1", "0.2.1", "0.2.1-a1", "0.2.0", "0.1.23" }) do
            local win = _G.GathercraftWhatsNew
            if win then win:Hide() end
            ns.db.lastVersion = before
            ns.WelcomeOnLogin()
            win = _G.GathercraftWhatsNew
            assert(win and win:IsShown() and win.body:GetText() == ns.L[entry], "no What's new window of 0.2.2 after " .. before)
            assert(ns.db.lastVersion == "0.2.2", "after " .. before .. " not remembered: " .. tostring(ns.db.lastVersion))
            win:Hide()
            ns.WelcomeOnLogin()
            assert(not win:IsShown(), "the What's new window again at the next login after " .. before)
        end
    end)
    local win = _G.GathercraftWhatsNew
    if win then win:Hide() end
    C_AddOns.GetAddOnMetadata, ns.db.lastVersion, ns.freshInstall = keep.meta, keep.last, keep.fresh
    if not ok then error(err, 0) end
end)
-- 0.2.3: test builds under their own marks after the release 0.2.2 - 0.2.3-a1 for 0.2.3 P3, 0.2.3-a2 for P4, 0.2.3-a3 for the P3 R1 fixes.
-- No What's new window for them: 0.2.3, its changelog and its What's new come with its release commit.
step("Version 0.2.3-a3: the TOC says it, /gcr shows it, no What's new window after 0.2.3-a2, 0.2.3-a1, 0.2.2, 0.2.2-a8, 0.2.2-a7, 0.2.2-a6, 0.2.2-a5, 0.2.2-a4, 0.2.2-a3, 0.2.2-a2, 0.2.2-a1, 0.2.1, 0.2.1-a1, 0.2.0 or 0.1.23 (0.2.3 P3 R1)", function()
    local version = toc:match("## Version: ([%w%.%-]+)")
    assert(version == "0.2.3-a3", "TOC version: " .. tostring(version))
    local function Read(name) local f = assert(io.open(ROOT .. "/" .. name)) local s = f:read("*a") f:close() return s end
    -- "What's new" has no entry for it nor for 0.2.3 yet: the build is not a release; 0.2.2's stays
    local welcome = Read("Welcome.lua")
    for _, mark in ipairs({ "0.2.3-a1", "0.2.3-a2", "0.2.3-a3", "0.2.3" }) do
        assert(not welcome:find('["' .. mark .. '"]', 1, true), "Welcome.lua has a What's new entry for " .. mark)
    end
    assert(welcome:find('["0.2.2"]', 1, true), "the What's new of 0.2.2 is gone")
    -- the changelog is still 0.2.2's
    local changelog = Read("CHANGELOG.md")
    assert(changelog:match("^(## v[^\r\n]*)") == "## v0.2.2 – 2026-11-23" and not changelog:find("0.2.3", 1, true), "the changelog has a 0.2.3 section")
    -- /gcr: the main window shows the TOC version ("v" and it)
    assert(Read("Main.lua"):find('version:SetText(v and ("v" .. v) or "")', 1, true), "the main window does not show the TOC version")
    local keep = { meta = C_AddOns.GetAddOnMetadata, last = ns.db.lastVersion, fresh = ns.freshInstall }
    local ok, err = pcall(function()
        C_AddOns.GetAddOnMetadata = function(_, field) if field == "Version" then return version end end
        ns.freshInstall = false
        for _, before in ipairs({ "0.2.3-a2", "0.2.3-a1", "0.2.2", "0.2.2-a8", "0.2.2-a7", "0.2.2-a6", "0.2.2-a5", "0.2.2-a4", "0.2.2-a3", "0.2.2-a2", "0.2.2-a1", "0.2.1", "0.2.1-a1", "0.2.0", "0.1.23" }) do
            local win = _G.GathercraftWhatsNew
            if win then win:Hide() end
            ns.db.lastVersion = before
            ns.WelcomeOnLogin()
            win = _G.GathercraftWhatsNew
            assert(not (win and win:IsShown()), "a What's new window after " .. before)
            assert(ns.db.lastVersion == "0.2.3-a3", "after " .. before .. " not remembered: " .. tostring(ns.db.lastVersion))
        end
    end)
    local win = _G.GathercraftWhatsNew
    if win then win:Hide() end
    C_AddOns.GetAddOnMetadata, ns.db.lastVersion, ns.freshInstall = keep.meta, keep.last, keep.fresh
    if not ok then error(err, 0) end
end)
-- 0.2.2 P1 point 4, d4 (Sync 2.0 analysis of 21.11.2026, part d4): a node
-- keeps at most 4 reporter names, not 8. Only the push brake (from 3),
-- self-healing (real from more than 3), unparking (a new name) and the
-- merge read them. Names already saved stay (no migration).
step("Sync 0.2.2: at most 4 reporter names per node - the 5th is not kept; push brake, self-healing and unparking as before; names saved before stay (0.2.2 P1 d4)", function()
    local Z = 1467
    local keep = { nodes = ns.db.nodes[Z], counts = ns.db.sync.counts and ns.db.sync.counts.confirmed or 0 }
    local function Names(n) local k = 0 for _ in pairs(n.heardBy or {}) do k = k + 1 end return k end
    local function jump(sec)
        NOW = NOW + sec
        for _, t in ipairs(timers) do t.at = t.at + sec end
    end
    local function Report(who, x)
        fire("CHAT_MSG_ADDON", "Gathercraft", ("N:%d;o1731,o,%d,5000,2770"):format(Z, x), "CHANNEL", who, nil, nil, nil, "GathercraftSync")
        advance(1)
    end
    local ok, err = pcall(function()
        -- a spot from sync, reported by one player so far
        local n = { id = "o1731", name = "Copper Vein", type = "ore", x = 0.40, y = 0.50, count = 1, last = 1,
            source = "sync", heard = 1, heardBy = { ["Rep A"] = true } }
        -- a spot saved by an older version with 8 names
        local old = { id = "o1731", name = "Copper Vein", type = "ore", x = 0.70, y = 0.50, count = 1, last = 1,
            source = "sync", heard = 8, heardBy = {} }
        for i = 1, 8 do old.heardBy["Old " .. i] = true end
        ns.db.nodes[Z] = { n, old }
        ns.NotifyNodesChanged() advance(1)
        local counts = function() return (ns.db.sync.counts or {}).confirmed or 0 end
        local before = counts()
        -- three more players: names 2, 3 and 4 are kept and counted
        for _, who in ipairs({ "Rep B", "Rep C", "Rep D" }) do Report(who, 4000) end
        assert(Names(n) == 4 and n.heard == 4, ("4 players: %d names kept, heard %s"):format(Names(n), tostring(n.heard)))
        assert(counts() == before + 3, ("4 players: %d confirmations counted, 3 wanted"):format(counts() - before))
        -- the 5th: not kept, not counted as a confirmation
        Report("Rep E", 4000)
        assert(Names(n) == 4 and not n.heardBy["Rep E"] and n.heard == 4, ("the 5th player: %d names, heard %s"):format(Names(n), tostring(n.heard)))
        assert(counts() == before + 3, "the 5th player was counted as a confirmation")
        -- names saved before stay: 8, and a new player is not added
        Report("Rep F", 7000)
        assert(Names(old) == 8 and old.heard == 8 and not old.heardBy["Rep F"], ("an older spot with 8 names: now %d, heard %s"):format(Names(old), tostring(old.heard)))
        -- push brake: an own spot that 4 others reported is not sent after a
        -- harvest (from 3 on, as before); one that 2 reported still is
        local mine = { id = "o1731", name = "Copper Vein", type = "ore", x = 0.25, y = 0.50, count = 1, last = 1 }
        local two = { id = "o1731", name = "Copper Vein", type = "ore", x = 0.55, y = 0.50, count = 1, last = 1 }
        table.insert(ns.db.nodes[Z], mine)
        table.insert(ns.db.nodes[Z], two)
        ns.NotifyNodesChanged() advance(1)
        for _, who in ipairs({ "Rep B", "Rep C", "Rep D", "Rep E", "Rep F" }) do Report(who, 2500) end
        for _, who in ipairs({ "Rep B", "Rep C" }) do Report(who, 5500) end
        assert(Names(mine) == 4 and mine.heard == 4, ("an own spot, 5 players: %d names, heard %s"):format(Names(mine), tostring(mine.heard)))
        advance(5)
        local function Sent(x)
            local k = 0
            for _, m in ipairs(sentMessages) do if m:find(("o1731,o,%d,5000"):format(x), 1, true) then k = k + 1 end end
            return k
        end
        local was25, was55 = Sent(2500), Sent(5500)
        ns.SyncShare(Z, mine)
        ns.SyncShare(Z, two)
        advance(5)
        assert(Sent(2500) == was25, "push brake: an own spot that 4 others reported was sent")
        assert(Sent(5500) > was55, "test setup: an own spot that 2 others reported was not sent") -- (to the channel and the guild)
        -- self-healing: with 4 reporters the spot counts as real - never parked
        for _ = 1, 30 do ns.SyncSelfHeal(n) jump(1800) end
        assert(not ns.IsParked(n), "4 reporters: parked by self-healing")
        -- unparking: only spots with at most 3 reporters are ever parked
        -- (self-healing leaves the others alone); a 4th player brings one
        -- back, and his name is kept
        local p3 = { id = "o1731", name = "Copper Vein", type = "ore", x = 0.10, y = 0.50, count = 1, last = 1,
            source = "sync", heard = 3, heardBy = { ["Alt 1"] = true, ["Alt 2"] = true, ["Alt 3"] = true }, parked = time() }
        table.insert(ns.db.nodes[Z], p3)
        ns.NotifyNodesChanged() advance(1)
        assert(ns.IsParked(p3), "test setup: parked")
        Report("Rep G", 1000)
        assert(not ns.IsParked(p3) and p3.heardBy["Rep G"] and Names(p3) == 4, "a 4th player did not bring back a parked spot with 3 reporters")
    end)
    ns.db.nodes[Z] = keep.nodes
    ns.NotifyNodesChanged() advance(1)
    if not ok then error(err, 0) end
end)
-- 0.2.2 P1 point 4, d1 (Sync 2.0 analysis of 21.11.2026, part d1): every
-- client says which Gathercraft it runs - "V:gc<version>", once after it
-- joined the channel and once per login in the guild, nothing more.
-- /gcr sync shows the versions of the players of the last hour, and each
-- player's in the list of the last 8. Old clients leave the message alone:
-- "V:" is followed by no number (their "^(%u):(%d+)" finds no zone), and a
-- kind other than N or Q they do not handle (the mixed-version run of
-- tools/sync_stress.lua shows it with real old clients).
step("Sync 0.2.2: V:gc<version> once after joining the channel and once per login in the guild; /gcr sync shows the versions of the last hour (0.2.2 P1 d1)", function()
    local keep = { send = C_ChatInfo.SendAddonMessage, guild = IsInGuild, enabled = ns.db.sync.enabled, public = ns.db.sync.public }
    local sent = {}
    local ok, err = pcall(function()
        C_ChatInfo.SendAddonMessage = function(prefix, msg, chan, target)
            sent[#sent + 1] = { msg = msg, chan = chan }
            sentMessages[#sentMessages + 1] = msg
            return 0
        end
        local function V(chan)
            local k = 0
            for _, s in ipairs(sent) do
                if s.msg:sub(1, 2) == "V:" and (not chan or s.chan == chan) then k = k + 1 end
            end
            return k
        end
        local function Login()
            wipe(ns.SyncVersionSaid) -- (a login in the game starts afresh)
            fire("PLAYER_LOGIN") advance(12)
        end
        local saidAs = "V:gc" .. C_AddOns.GetAddOnMetadata("Gathercraft", "Version")
        -- (what waits in the queue from before goes out first: at most 60
        -- messages, one every 1.2 s - it is not counted here)
        advance(75)
        sent = {}
        -- 1. a login, in a guild, the public channel on: one to the channel, one to the guild
        ns.db.sync.enabled, ns.db.sync.public = true, true
        IsInGuild = function() return true end
        Login()
        assert(V("CHANNEL") == 1 and V("GUILD") == 1, ("a login: %d to the channel, %d to the guild"):format(V("CHANNEL"), V("GUILD")))
        for _, s in ipairs(sent) do
            if s.msg:sub(1, 2) == "V:" then assert(s.msg == saidAs, "the message is " .. s.msg) end
        end
        -- old clients: no zone in it ("^(%u):(%d+)"), and short
        assert(not saidAs:match("^(%u):(%d+)") and #saidAs <= 255, "an old client reads a zone from " .. saidAs)
        -- 2. the same session: a second login event, /gcr sync on - nothing more
        fire("PLAYER_LOGIN") advance(12)
        ns.SyncCommand("on") advance(3)
        assert(V() == 2, ("said again within the session: %d messages"):format(V()))
        -- 3. the channel left and joined again: once more to the channel
        ns.SyncCommand("public") advance(1)
        ns.SyncCommand("public") advance(3)
        assert(V("CHANNEL") == 2 and V("GUILD") == 1, ("joined again: %d to the channel, %d to the guild"):format(V("CHANNEL"), V("GUILD")))
        -- 4. no guild: only the channel; channel off: only the guild; sync off: nothing
        local before = { c = V("CHANNEL"), g = V("GUILD") }
        IsInGuild = function() return false end
        Login()
        assert(V("CHANNEL") == before.c + 1 and V("GUILD") == before.g, "no guild: not just one to the channel")
        IsInGuild = function() return true end
        ns.db.sync.public = false
        before = { c = V("CHANNEL"), g = V("GUILD") }
        Login()
        assert(V("CHANNEL") == before.c and V("GUILD") == before.g + 1, "channel off: not just one to the guild")
        ns.db.sync.public, ns.db.sync.enabled = true, false
        before = V()
        Login()
        assert(V() == before, "sync off: a version was sent")
        ns.db.sync.enabled = true
        Login()

        -- 5. heard from others: their versions in /gcr sync; a bad one is not taken
        local function Msg(text, who) fire("CHAT_MSG_ADDON", "Gathercraft", text, "CHANNEL", who, nil, nil, nil, "GathercraftSync") advance(1) end
        Msg("N:1412;o1617,h,4458,7168,2447", "Vers Ann")
        Msg("V:gc0.2.2-a1", "Vers Ann")
        Msg("V:gc0.2.2-a1", "Vers Bob")
        Msg("V:gc0.2.3", "Vers Cid")
        Msg("Q:1412:10", "Vers Dan") -- no version heard
        Msg("V:gc0.2.2|cffff0000red", "Vers Eve") -- not a version
        Msg("V:gc" .. ("9"):rep(30), "Vers Fay") -- too long
        Msg("V:0.2.2", "Vers Gus") -- without gc
        local mark = #log
        slash("sync")
        local said = {}
        for i = mark + 1, #log do said[#said + 1] = log[i] end
        local all = table.concat(said, "\n")
        local head = (ns.L["  Versions of the players seen (1h): %s"]):match("^(.-)%%s")
        local line
        for _, l in ipairs(said) do if l:find(head, 1, true) then line = l end end
        assert(line, "/gcr sync shows no versions line")
        assert(line:find("0.2.2-a1: 2", 1, true) and line:find("0.2.3: 1", 1, true), "the versions line: " .. line)
        assert(line:find((ns.L["no version heard: %d"]):match("^(.-)%%d"), 1, true), "the versions line says nothing of the players without one: " .. line)
        assert(not line:find("|cff", 1, true) and not line:find("9999999999", 1, true) and not line:find("0.2.2: ", 1, true), "a bad version was taken: " .. line)
        -- the list of the last 8: each player with his version, "-" without one
        local function Row(name)
            for _, l in ipairs(said) do if l:find(name, 1, true) then return l end end
        end
        assert(Row("Vers Ann") and Row("Vers Ann"):sub(-#" 0.2.2-a1") == " 0.2.2-a1", "Ann's row: " .. tostring(Row("Vers Ann")))
        assert(Row("Vers Dan") and Row("Vers Dan"):sub(-2) == " -", "Dan's row: " .. tostring(Row("Vers Dan")))
        -- the version message did not move Ann to another zone
        assert(Row("Vers Ann"):find(ns.GetZoneName(1412), 1, true), "Ann's zone after her version: " .. Row("Vers Ann"))
        -- every language has the texts
        for lang, d in pairs(ns.Locales) do
            for _, key in ipairs({ "  Versions of the players seen (1h): %s", "no version heard: %d" }) do
                assert(d[key] and d[key] ~= key, lang .. ": not translated: " .. key)
            end
        end
    end)
    C_ChatInfo.SendAddonMessage, IsInGuild = keep.send, keep.guild
    ns.db.sync.enabled, ns.db.sync.public = keep.enabled, keep.public
    if not ok then error(err, 0) end
end)
-- 0.2.2 P1 point 4, d1 (Sync 2.0 analysis of 21.11.2026): what the game
-- says to a send is read. SendAddonMessage returns a result code; three
-- are counted - throttled, the channel throttled, the channel not valid -
-- in /gcr perf (the minute) and /gcr sync (since login). The message is
-- dropped as before; true, false, success and other codes count nothing.
step("Sync 0.2.2: what the game says to a send - throttled, channel throttled, channel not valid - in /gcr perf and /gcr sync (0.2.2 P1 d1)", function()
    local Z = 1468
    local keep = { send = C_ChatInfo.SendAddonMessage, nodes = ns.db.nodes[Z], map = player.map }
    local ok, err = pcall(function()
        -- the game's answers to our messages of this zone, one after the other
        local answers = { 3, 8, 7, 3, 0, true, false, 99 }
        local mine = 0
        C_ChatInfo.SendAddonMessage = function(prefix, msg, chan)
            sentMessages[#sentMessages + 1] = msg
            if msg:find("N:" .. Z .. ";", 1, true) then
                mine = mine + 1
                return answers[mine]
            end
            return 0
        end
        local function Refused()
            local mark = #log
            slash("sync")
            local head = (ns.L["  Refused by the game when sending (since login): %d throttled, %d channel throttled, %d channel not valid"]):match("^(.-)%%d")
            for i = mark + 1, #log do
                if log[i]:find(head, 1, true) then
                    local a, b, c = log[i]:sub(log[i]:find(head, 1, true) + #head):match("^(%d+)%D+(%d+)%D+(%d+)")
                    return tonumber(a), tonumber(b), tonumber(c)
                end
            end
        end
        local a0, b0, c0 = Refused()
        assert(a0 and b0 and c0, "/gcr sync shows no line of what the game refused")
        -- eight own spots of this zone, each sent to the channel and the guild:
        -- the first eight messages get the eight answers
        local list = {}
        for i = 1, 4 do list[i] = { id = "o1731", name = "Copper Vein", type = "ore", x = 0.1 + i * 0.15, y = 0.5, count = 1, last = 1 } end
        ns.db.nodes[Z] = list
        ns.NotifyNodesChanged() advance(1)
        -- start at a new minute, so the minute of /gcr perf holds all of them
        advance(60 - GetTime() % 60 + 0.5)
        for _, n in ipairs(list) do ns.SyncShare(Z, n) end
        advance(15)
        assert(mine == 8, ("test setup: %d messages of the zone sent, 8 wanted"):format(mine))
        local a1, b1, c1 = Refused()
        assert(a1 - a0 == 2 and b1 - b0 == 1 and c1 - c0 == 1,
            ("/gcr sync: %d throttled, %d channel throttled, %d channel not valid - 2, 1, 1 wanted"):format(a1 - a0, b1 - b0, c1 - c0))
        -- /gcr perf: the last full minute
        advance(60 - GetTime() % 60 + 0.5)
        local mark = #log
        ns.SyncPerf()
        local perfLine
        for i = mark + 1, #log do if log[i]:find("perf (last full minute)", 1, true) then perfLine = log[i] end end
        assert(perfLine, "test setup: no /gcr perf line of the last full minute")
        assert(perfLine:find("refused by the game when sending: 2 throttled, 1 channel throttled, 1 channel not valid", 1, true),
            "/gcr perf: " .. perfLine)
        -- every language has the line, with its three numbers
        for lang, d in pairs(ns.Locales) do
            local key = "  Refused by the game when sending (since login): %d throttled, %d channel throttled, %d channel not valid"
            assert(d[key] and d[key] ~= key and select(2, d[key]:gsub("%%d", "")) == 3, lang .. ": not translated, or not three numbers")
        end
    end)
    C_ChatInfo.SendAddonMessage = keep.send
    ns.db.nodes[Z], player.map = keep.nodes, keep.map
    ns.NotifyNodesChanged() advance(1)
    if not ok then error(err, 0) end
end)
-- 0.2.2 P1 point 4, d1 (Sync 2.0 analysis of 21.11.2026): honest counters.
-- What arrives and is not counted in "Received from other players" gets a
-- line of its own in /gcr sync: repeats (the same player again for a spot
-- or a waiting report) and spots already confirmed by 4 players (d4).
step("Sync 0.2.2: /gcr sync counts repeats and spots already confirmed by 4 players apart from what it counts (0.2.2 P1 d1)", function()
    local Z, NEW = 1469, 1470
    local keep = { nodes = ns.db.nodes[Z], pending = ns.db.sync.pending[NEW], spawns = ns.HasKnownSpawns }
    local ok, err = pcall(function()
        local function Report(who, x, map)
            fire("CHAT_MSG_ADDON", "Gathercraft", ("N:%d;o1731,o,%d,5000,2770"):format(map or Z, x), "CHANNEL", who, nil, nil, nil, "GathercraftSync")
            advance(1)
        end
        local key = "  Received but not counted (all sessions): %d repeats (the same player again), %d for spots already confirmed by %d players"
        local function Line()
            local mark = #log
            slash("sync")
            local head = ns.L[key]:match("^(.-)%%d")
            for i = mark + 1, #log do
                local at = log[i]:find(head, 1, true)
                if at then
                    local a, b, c = log[i]:sub(at + #head):match("^(%d+)%D+(%d+)%D+(%d+)")
                    return tonumber(a), tonumber(b), tonumber(c)
                end
            end
        end
        local r0, f0, keepN = Line()
        assert(r0 and f0 and keepN == 4, "/gcr sync shows no line of what is not counted, or not 4 players: " .. tostring(keepN))
        local c0 = select(3, ns.SyncCounts())
        local n = { id = "o1731", name = "Copper Vein", type = "ore", x = 0.40, y = 0.50, count = 1, last = 1,
            source = "sync", heard = 1, heardBy = { ["Rep A"] = true } }
        ns.db.nodes[Z] = { n }
        ns.NotifyNodesChanged() advance(1)
        Report("Rep A", 4000) -- the same player again: a repeat
        for _, who in ipairs({ "Rep B", "Rep C", "Rep D" }) do Report(who, 4000) end -- confirmations 2 to 4
        Report("Rep E", 4000) -- a 5th: already confirmed by 4
        Report("Rep E", 4000) -- (and again: his name is not kept, so it is the same)
        -- a waiting report in a zone without known spawn points, sent twice by one player
        ns.HasKnownSpawns = function(m) if m == NEW then return false end return keep.spawns and keep.spawns(m) end
        Report("Rep X", 3000, NEW)
        Report("Rep X", 3000, NEW)
        local r1, f1 = Line()
        assert(r1 - r0 == 2, ("repeats: %d counted, 2 wanted (Rep A again, Rep X again)"):format(r1 - r0))
        assert(f1 - f0 == 2, ("already confirmed by 4: %d counted, 2 wanted (Rep E twice)"):format(f1 - f0))
        assert(select(3, ns.SyncCounts()) - c0 == 3, ("confirmations: %d counted, 3 wanted"):format(select(3, ns.SyncCounts()) - c0))
        -- kept over a reload: in the saved data
        assert(ns.db.sync.counts.repeats and ns.db.sync.counts.full, "not in the saved data")
        for lang, d in pairs(ns.Locales) do
            assert(d[key] and d[key] ~= key and select(2, d[key]:gsub("%%d", "")) == 3, lang .. ": not translated, or not three numbers")
        end
    end)
    ns.db.nodes[Z], ns.db.sync.pending[NEW], ns.HasKnownSpawns = keep.nodes, keep.pending, keep.spawns
    ns.NotifyNodesChanged() advance(1)
    if not ok then error(err, 0) end
end)
-- 0.2.2 P2a (Merkliste aus 0.1.23; Belgeron's German client): recipes and
-- skills were kept under "Kräuterkunde" and "Angeln" - the names of the
-- game's skill list, which are not the spells' names ProfKey knew. Now the
-- names of the game's list of professions count by their skill line, the
-- gathering spells too, and after the login saved data under such a name
-- move to the English one: two lists of one profession are put together,
-- nothing of either is lost.
step("Crafting 0.2.2: a profession's name from the game's list counts by its skill line - saved data under \"Kräuterkunde\" or \"Angeln\" move to Herbalism and Fishing, nothing lost (0.2.2 P2a)", function()
    local key = (UnitName("player") or "?") .. "-" .. GetNormalizedRealmName()
    local keep = { names = { PROFS[1][1], PROFS[4][1] }, recipes = ns.db.recipes, db = ns.db.recipeDB, pending = ns.db.recipePending }
    local ok, err = pcall(function()
        local function Copy(t) local c = {} for k, v in pairs(t) do c[k] = type(v) == "table" and Copy(v) or v end return c end
        ns.db.recipes = keep.recipes and Copy(keep.recipes) or {}
        ns.db.recipeDB = keep.db and Copy(keep.db) or {}
        ns.db.recipePending = keep.pending and Copy(keep.pending) or {}
        -- what an older version kept for this character in a German client
        local char = ns.db.recipes[key] or {}
        ns.db.recipes[key] = char
        char["Kräuterkunde"] = { list = { ["Herb Recipe A"] = "2447:1:1:1|765:1" }, rank = 120, rankAt = 2000, updated = 2000 }
        char["Herbalism"] = { list = { ["Herb Recipe B"] = "2449:1:1:1|785:1", ["Herb Recipe A"] = "2447:2:2:1|765:2" }, rank = 100, rankAt = 1000, updated = 1000 }
        char["Angeln"] = { list = {}, rank = 50, rankAt = 1500 }
        char["Alchemy"] = { list = { ["Minor Healing Potion"] = "118:1:1:1|2447:1,765:1" }, rank = 60, rankAt = 1200 }
        local alchemyBefore = Copy(char["Alchemy"])
        ns.db.recipeDB["Angeln"] = { ["Fish Recipe"] = "6303:1:1:0|6256:1" }
        ns.db.recipePending["Kräuterkunde"] = { ["Waiting Herb"] = "0|Item765:1" }
        -- the game's list of professions in that client; the login reads it
        PROFS[1][1], PROFS[4][1] = "Kräuterkunde", "Angeln"
        fire("PLAYER_LOGIN") advance(4)
        -- the names count as the professions of their skill lines
        assert(ns.ProfKey("Kräuterkunde") == "Herbalism" and ns.ProfKey("kräuterkunde") == "Herbalism", "Kräuterkunde is " .. tostring(ns.ProfKey("Kräuterkunde")))
        assert(ns.ProfKey("Angeln") == "Fishing", "Angeln is " .. tostring(ns.ProfKey("Angeln")))
        assert(ns.ProfKey("Alchemy") == "Alchemy" and ns.ProfKey("Herbalism") == "Herbalism", "an English name changed")
        -- the character's lists: one Herbalism with both recipes, the later skill; Fishing; Alchemy as it was
        assert(char["Kräuterkunde"] == nil and char["Angeln"] == nil, "a German name is still kept")
        local h = char["Herbalism"]
        assert(h and h.list["Herb Recipe A"] and h.list["Herb Recipe B"], "Herbalism lost a recipe")
        assert(h.list["Herb Recipe A"] == "2447:2:2:1|765:2", "a recipe both had: not the English list's")
        assert(h.rank == 120 and h.rankAt == 2000, ("Herbalism's skill: %s, the later one is 120"):format(tostring(h.rank)))
        assert(char["Fishing"] and char["Fishing"].rank == 50, "Fishing's skill is lost")
        for k, v in pairs(alchemyBefore) do
            if type(v) ~= "table" then assert(char["Alchemy"][k] == v, "Alchemy changed: " .. k) end
        end
        assert(char["Alchemy"].list["Minor Healing Potion"] == alchemyBefore.list["Minor Healing Potion"], "Alchemy's recipe changed")
        -- the account's recipe book and the waiting recipes
        assert(ns.db.recipeDB["Angeln"] == nil and ns.db.recipeDB["Fishing"] and ns.db.recipeDB["Fishing"]["Fish Recipe"], "the recipe book still has Angeln")
        assert(ns.db.recipePending["Kräuterkunde"] == nil and ns.db.recipePending["Herbalism"] and ns.db.recipePending["Herbalism"]["Waiting Herb"],
            "the waiting recipes still have Kräuterkunde")
        -- a recipe a trainer names under "Angeln" waits under Fishing
        ns.RememberRecipe("Angeln", 0, "A Product Nobody Knows", { { "Nothing Like It", 1 } })
        assert(ns.db.recipePending["Angeln"] == nil and ns.db.recipePending["Fishing"] and ns.db.recipePending["Fishing"]["A Product Nobody Knows"],
            "a trainer's recipe waits under Angeln")
        -- again: nothing moves, nothing is lost
        local snapshot = Copy(ns.db.recipes[key])
        ns.CraftNormalizeAgain()
        for prof, info in pairs(snapshot) do
            for name in pairs(info.list or {}) do assert(ns.db.recipes[key][prof].list[name], "a second time lost " .. prof .. " " .. name) end
        end
    end)
    PROFS[1][1], PROFS[4][1] = keep.names[1], keep.names[2]
    ns.db.recipes, ns.db.recipeDB, ns.db.recipePending = keep.recipes, keep.db, keep.pending
    if not ok then error(err, 0) end
end)
-- 0.2.2 P2b (Merkliste aus 0.1.23; Sven: Leatherworking given up, its
-- recipes stayed in the list of his professions): "my" professions are the
-- ones the game's list of professions names now - or whose window was read
-- in this session. One given up keeps its recipes in the saved data (learnt
-- again, they are back) but leaves the profit list and "my" professions.
-- When the game's list can't tell (none, a hidden place, a place we can't
-- name), every profession kept counts, as before.
step("Crafting 0.2.2: a profession given up leaves the profit list and \"my\" professions - its recipes stay saved; when the game's list can't tell, all count (0.2.2 P2b)", function()
    local key = (UnitName("player") or "?") .. "-" .. GetNormalizedRealmName()
    local keep = { recipes = ns.db.recipes, profs = GetProfessions, p5 = PROFS[5], secret = issecretvalue }
    local ok, err = pcall(function()
        ns.db.recipes = { [key] = {
            -- read long ago, before this session: given up
            Leatherworking = { list = { ["Light Armor Kit"] = "2304:1:1:1|2318:1" }, updated = 1, rank = 75, rankAt = 1 },
            -- read long ago, and in the game's list now
            Tailoring = { list = { ["Bolt of Linen Cloth"] = "2996:1:1:1|2589:2" }, updated = 1, rank = 60, rankAt = 1 },
            -- not in the game's list, but its window was read in this session
            Alchemy = { list = { ["Minor Healing Potion"] = "118:1:1:1|2447:1,765:1" }, updated = time(), rank = 40, rankAt = time() },
        } }
        PROFS[5] = { "Tailoring", 60, 75, 197, 0 }
        GetProfessions = function() return 1, 2, nil, 4, 5, nil end
        local function Mine()
            local set = {}
            for _, p in ipairs(ns.CraftData.MyProfessions()) do set[p] = true end
            return set
        end
        local function ListProfs()
            local set = {}
            for _, r in ipairs(ns.CraftEvaluate(nil, true)) do set[r.prof] = true end
            return set
        end
        local m, l = Mine(), ListProfs()
        assert(not m.Leatherworking, "a profession given up is still one of mine")
        assert(not l.Leatherworking, "a profession given up is still in the profit list")
        assert(m.Tailoring and l.Tailoring, "a profession in the game's list is not mine")
        assert(m.Alchemy and l.Alchemy, "a profession whose window was read in this session is not mine")
        -- (the session began with its first login: another login event in it,
        -- a while later, changes nothing - counter-probe b4)
        advance(30)
        fire("PLAYER_LOGIN") advance(1)
        assert(Mine().Alchemy, "a second login event of the session: the window read in it no longer counts")
        -- its recipes stay saved; and with only Leatherworking asked for, it is all there
        assert(ns.db.recipes[key].Leatherworking and ns.db.recipes[key].Leatherworking.list["Light Armor Kit"], "the recipes of the one given up were deleted")
        local only = ns.CraftEvaluate("Leatherworking", true)
        assert(#only == 1 and only[1].prof == "Leatherworking", "Leatherworking on its own: " .. #only .. " rows")
        -- learnt again: its window is read now - it is back
        ns.db.recipes[key].Leatherworking.updated = time()
        assert(Mine().Leatherworking and ListProfs().Leatherworking, "learnt again and its window read: not back")
        ns.db.recipes[key].Leatherworking.updated = 1
        -- the game's list can't tell: every profession counts, as before
        PROFS[5] = { "Werkkunst", 60, 75, 9999, 0 } -- a place we can't name
        assert(Mine().Leatherworking and ListProfs().Leatherworking, "a place we can't name: a profession was left out")
        PROFS[5] = { "Tailoring", 60, 75, 197, 0 }
        local SECRET = newproxy(true)
        issecretvalue = function(v) return rawequal(v, SECRET) end
        GetProfessions = function() return 1, SECRET, nil, 4, 5, nil end -- a hidden place
        assert(Mine().Leatherworking, "a hidden place: a profession was left out")
        issecretvalue = keep.secret
        GetProfessions = nil -- no such list in this client
        assert(Mine().Leatherworking and ListProfs().Leatherworking, "no list in this client: a profession was left out")
    end)
    ns.db.recipes, GetProfessions, PROFS[5], issecretvalue = keep.recipes, keep.profs, keep.p5, keep.secret
    if not ok then error(err, 0) end
end)
-- 0.2.2 P2-M1 (Codex, P2 round 1): a place of the game's list of professions
-- that is in use but gives no skill line (maybe not loaded yet) is not a free
-- place. The list is not read in full then and can't tell what you have:
-- nothing leaves "my" professions. Only a list read in full can tell that a
-- profession is gone.
step("Crafting 0.2.2: a place in use whose skill line the game does not give leaves the list unread - no profession leaves \"my\" professions until it is read in full (0.2.2 P2-M1)", function()
    local key = (UnitName("player") or "?") .. "-" .. GetNormalizedRealmName()
    local keep = { recipes = ns.db.recipes, profs = GetProfessions, p2 = PROFS[2], secret = issecretvalue }
    local ok, err = pcall(function()
        -- both read long ago, before this session: only the game's list counts
        ns.db.recipes = { [key] = {
            Mining = { list = { ["Smelt Copper"] = "2840:1:1:1|2770:1" }, updated = 1, rank = 30, rankAt = 1 },
            Alchemy = { list = { ["Minor Healing Potion"] = "118:1:1:1|2447:1,765:1" }, updated = 1, rank = 40, rankAt = 1 },
        } }
        local function Mine()
            local set = {}
            for _, p in ipairs(ns.CraftData.MyProfessions()) do set[p] = true end
            return set
        end
        -- 1. Codex' case: two places, Herbalism with its line, Mining without one
        GetProfessions = function() return 1, 2 end
        PROFS[2] = { "Mining", 30, 75, nil, 0 }
        local slots, unclear, places, complete = ns.ProfessionSlots()
        assert(places == 2 and not unclear and #slots == 1 and slots[1].line == 182, "test setup: the readable places")
        assert(Mine().Mining, "an incomplete profession list excluded Mining")
        assert(ns.CraftCurrentProfessions() == nil, "an incomplete profession list tells what you have")
        assert(complete == false, "a place in use without its line: the list counts as read in full")
        -- (Alchemy is in no place either way: the list read in full would drop it - below)
        -- 2. read in full again: Mining is yours, Alchemy (in no place) is not
        PROFS[2] = { "Mining", 30, 75, 186, 0 }
        assert(select(4, ns.ProfessionSlots()) == true, "the list read in full: not complete")
        local now = ns.CraftCurrentProfessions()
        assert(now and now.Mining and now.Herbalism, "the list read in full: Mining or Herbalism not in it")
        local m = Mine()
        assert(m.Mining and not m.Alchemy, ("the list read in full: Mining %s, Alchemy %s"):format(tostring(m.Mining), tostring(m.Alchemy)))
        -- 3. Mining given up: its place is free now - it leaves "my" professions
        GetProfessions = function() return 1, nil end
        assert(select(4, ns.ProfessionSlots()) == true, "a free place: the list counts as not read in full")
        assert(not Mine().Mining, "Mining given up (its place free) is still one of mine")
        assert(ns.db.recipes[key].Mining and ns.db.recipes[key].Mining.list["Smelt Copper"], "the recipes of the one given up were deleted")
        -- 4. a place in use for which the game gives nothing at all: unread as well
        GetProfessions = function() return 1, 2 end
        PROFS[2] = {}
        assert(select(4, ns.ProfessionSlots()) == false and Mine().Mining, "a place in use with no answer: Mining left")
        -- 5. a hidden place and a place we can't name: as before (not mine to change here)
        PROFS[2] = { "Werkkunst", 30, 75, 9999, 0 }
        assert(select(4, ns.ProfessionSlots()) == true and ns.CraftCurrentProfessions() == nil and Mine().Mining, "a place we can't name: Mining left")
        local SECRET = newproxy(true)
        issecretvalue = function(v) return rawequal(v, SECRET) end
        GetProfessions = function() return 1, SECRET end
        local _, unclear2, _, complete2 = ns.ProfessionSlots()
        assert(unclear2 and complete2 == false and Mine().Mining, "a hidden place: Mining left, or the list counts as read in full")
        issecretvalue = keep.secret
        -- 6. /gcr crafttest says so
        GetProfessions = function() return 1, 2 end
        PROFS[2] = { "Mining", 30, 75, nil, 0 }
        local mark = #log
        slash("crafttest")
        local said
        for i = mark + 1, #log do if log[i]:find("(a place in use without its line)", 1, true) then said = true end end
        assert(said, "/gcr crafttest does not say a place in use gives no line")
    end)
    ns.db.recipes, GetProfessions, PROFS[2], issecretvalue = keep.recipes, keep.profs, keep.p2, keep.secret
    if not ok then error(err, 0) end
end)
-- 0.2.2 P2-M2 (Codex, P2 round 1): a name the game gives - in its list of
-- professions, or as a profession's spell - is asked whether it is hidden
-- before anything looks at it: its type, whether it is empty, lower(), the
-- names known. The hidden name here is a Lua stand-in that notes every look
-- at it (its type says "string", like the game's hidden strings); the
-- game's own hidden strings can only be seen in the client.
step("Crafting 0.2.2: a hidden profession name is asked about first - nothing looks at it, not its type, not whether it is empty (0.2.2 P2-M2)", function()
    local keep = { secret = issecretvalue, type = type, p1 = PROFS[1], p2 = PROFS[2], profs = GetProfessions, spell = C_Spell.GetSpellName }
    local realType = type
    local SECRET = newproxy(true)
    local asked, looks = false, {}
    local function Look(how) looks[#looks + 1] = how .. (asked and " (after it was found hidden)" or " (before the secret check)") end
    local mt = getmetatable(SECRET)
    mt.__index = function(_, k) Look("index " .. realType(k) .. " " .. (realType(k) == "string" and k or "?")) return function() return "x" end end
    mt.__eq = function() Look("==") return false end
    mt.__lt = function() Look("<") return false end
    mt.__le = function() Look("<=") return false end
    mt.__concat = function() Look("..") return "x" end
    mt.__len = function() Look("#") return 1 end
    mt.__tostring = function() Look("tostring") return "x" end
    local function Looked(what)
        assert(#looks == 0, what .. ": looked at the hidden name - " .. table.concat(looks, ", "))
    end
    local ok, err = pcall(function()
        issecretvalue = function(v) if rawequal(v, SECRET) then asked = true return true end return false end
        type = function(v) if rawequal(v, SECRET) then Look("type") return "string" end return realType(v) end
        -- 1. the game's list: Herbalism's place gives a hidden name with its line
        GetProfessions = function() return 1, 2 end
        PROFS[1] = { SECRET, 52, 75, 182, 0 }
        ns.CraftNormalizeAgain()
        Looked("the names of the game's list (LearnSlotNames)")
        assert(asked, "test setup: the hidden name was not asked about")
        assert(ns.ProfKey("Herbalism") == "Herbalism", "a hidden name changed Herbalism")
        -- 2. a place we can't name by its line, with a hidden name: the list can't tell
        asked = false
        PROFS[1] = keep.p1
        PROFS[2] = { SECRET, 30, 75, 9999, 0 }
        assert(ns.CraftCurrentProfessions() == nil, "a hidden name of a place we can't name: the list tells what you have")
        Looked("the game's list, a place we can't name (CurrentProfessions)")
        PROFS[2] = keep.p2
        -- 3. a hidden profession name handed to ProfKey (a trainer's, RememberRecipe): back as it came
        asked = false
        assert(rawequal(ns.ProfKey(SECRET), SECRET), "a hidden name is not handed back as it came")
        Looked("ProfKey")
        -- 4. a profession's spell with a hidden name (Herbalism's, 2366; and
        -- Smelting's, 2656, read on its own): the names are built without them
        assert(ns.CraftNamesAnew, "test setup: no ns.CraftNamesAnew")
        for _, hidden in ipairs({ 2366, 2656 }) do
            asked = false
            C_Spell.GetSpellName = function(id) if id == hidden then return SECRET end return keep.spell(id) end
            ns.CraftNamesAnew()
            ns.CraftNormalizeAgain()
            Looked("the names of the professions' spells (ProfKey), spell " .. hidden)
            assert(asked, "test setup: the hidden spell name was not asked about, spell " .. hidden)
            assert(ns.ProfKey("Herbalism") == "Herbalism" and ns.ProfKey("Mining") == "Mining", "a hidden spell name changed the English names, spell " .. hidden)
        end
    end)
    type, issecretvalue = realType, keep.secret
    PROFS[1], PROFS[2], GetProfessions, C_Spell.GetSpellName = keep.p1, keep.p2, keep.profs, keep.spell
    -- the names as they were (built again from the game's real ones)
    if ns.CraftNamesAnew then ns.CraftNamesAnew() ns.CraftNormalizeAgain() end
    if not ok then error(err, 0) end
end)
-- 0.2.2 P2 R2-M1 (Codex, P2 round 2): a hidden profession name the game
-- gives - a trainer's, the profession window's, or one handed to
-- RememberRecipe - stores nothing: no recipe, no waiting recipe, no
-- character's list under it, and nothing looks at it on the way (ProfKey
-- hands it back as it came, P2-M2; the ones who use it stop). A readable
-- name beside each case is stored as before. The hidden name is a Lua
-- stand-in, as in the P2-M2 step; the game's own hidden strings can only be
-- seen in the client.
step("Crafting 0.2.2: a hidden profession name stores nothing - not through RememberRecipe, not from a trainer, not from the profession window; a readable one as before (0.2.2 P2 R2-M1)", function()
    local G = { "GetNumTrainerServices", "GetTrainerServiceInfo", "GetTrainerServiceItemLink", "GetTrainerServiceSkillReq",
        "GetTrainerServiceSkillLine", "GetTrainerServiceNumReagents", "GetTrainerServiceReagentInfo", "GetTrainerServiceReagentLink",
        "ClassTrainerFrameTitleText", "ClassTrainerFrame", "C_TooltipInfo", "GetTradeSkillLine", "GetNumTradeSkills", "GetTradeSkillInfo",
        "GetTradeSkillItemLink", "GetTradeSkillNumMade", "GetTradeSkillNumReagents", "GetTradeSkillReagentInfo",
        "GetTradeSkillReagentItemLink", "issecretvalue" }
    local keep = {}
    for _, k in ipairs(G) do keep[k] = rawget(_G, k) end
    local keepDB = { ns.db.recipes, ns.db.recipeDB, ns.db.recipePending }
    local realType = type
    local SECRET = newproxy(true)
    local asked, looks = false, {}
    local function Look(how) looks[#looks + 1] = how .. (asked and " (after it was found hidden)" or " (before the secret check)") end
    local mt = getmetatable(SECRET)
    mt.__index = function(_, k) Look("index " .. realType(k) .. " " .. (realType(k) == "string" and k or "?")) return function() return "x" end end
    mt.__eq = function() Look("==") return false end
    mt.__lt = function() Look("<") return false end
    mt.__le = function() Look("<=") return false end
    mt.__concat = function() Look("..") return "x" end
    mt.__len = function() Look("#") return 1 end
    mt.__tostring = function() Look("tostring") return "x" end
    local function Keys(t)
        local n = 0
        for _ in pairs(t or {}) do n = n + 1 end
        return n
    end
    local function Fresh()
        ns.db.recipes, ns.db.recipeDB, ns.db.recipePending = {}, {}, {}
        asked = false
    end
    -- nothing stored at all (the tables were empty), nothing looked at
    local function Nothing(what)
        assert(asked, what .. ": test setup: the hidden name was not asked about")
        assert(#looks == 0, what .. ": looked at the hidden name - " .. table.concat(looks, ", "))
        assert(rawget(ns.db.recipeDB, SECRET) == nil and rawget(ns.db.recipePending, SECRET) == nil,
            what .. ": a recipe stored under the hidden profession name")
        assert(Keys(ns.db.recipeDB) == 0 and Keys(ns.db.recipePending) == 0,
            what .. ": a recipe stored - " .. Keys(ns.db.recipeDB) .. " professions with recipes, " .. Keys(ns.db.recipePending) .. " with waiting ones")
        for _, char in pairs(ns.db.recipes) do
            assert(rawget(char, SECRET) == nil and Keys(char) == 0, what .. ": a character's profession list stored")
        end
    end
    local NAME, REAGENT = "R2 Unknown Elixir", "R2 Unknown Root"
    local ok, err = pcall(function()
        issecretvalue = function(v) if rawequal(v, SECRET) then asked = true return true end return false end
        type = function(v) if rawequal(v, SECRET) then Look("type") return "string" end return realType(v) end
        -- 1. RememberRecipe handed a hidden name (Codex's R2 probe)
        Fresh()
        ns.RememberRecipe(SECRET, 1, NAME, { { REAGENT, 1 } })
        Nothing("RememberRecipe")
        Fresh()
        assert(ns.RememberRecipe("Alchemy", 1, NAME, { { REAGENT, 1 } }) == false and ns.db.recipePending.Alchemy
            and ns.db.recipePending.Alchemy[NAME], "test setup: RememberRecipe with Alchemy - the recipe does not wait")
        -- 2. a trainer without links (Forever): the profession by the skill
        -- line, the reagents from the tooltip (Codex's R2 trainer probe); the
        -- trainer's title names Alchemy - a hidden name is not read as the
        -- title's either
        ClassTrainerFrameTitleText, ClassTrainerFrame = { GetText = function() return "Alchemy Trainer" end }, nil
        GetNumTrainerServices = function() return 1 end
        GetTrainerServiceInfo = function() return NAME, nil, "available" end
        GetTrainerServiceItemLink = function() return nil end
        GetTrainerServiceNumReagents = function() return 0 end
        C_TooltipInfo = { GetTrainerService = function() return { lines = { { leftText = NAME }, { leftText = "Reagents: " .. REAGENT } } } end }
        local skillReq, skillLine
        GetTrainerServiceSkillReq = function() return skillReq, 1 end
        GetTrainerServiceSkillLine = function() return skillLine end
        -- each read is a visit of its own (its message is said), and a hidden
        -- entry counts as one without skill: "none noted"
        local NONE = (ns.L["Trainer: %d entries, none noted (headers %d, no item %d, no skill %d, no reagents %d). Please send this line."]):format(1, 0, 0, 1, 0)
        local function Trainer(what)
            fire("TRAINER_CLOSED")
            local mark = #log
            ns.ReadTrainer()
            if not what then return end
            Nothing(what)
            local said = false
            for i = mark + 1, #log do if log[i]:find(NONE, 1, true) then said = true end end
            assert(said, what .. ": the trainer does not say \"" .. NONE .. "\"")
        end
        Fresh()
        skillReq, skillLine = nil, "Alchemy"
        Trainer()
        assert(ns.db.recipePending.Alchemy and ns.db.recipePending.Alchemy[NAME], "test setup: a trainer's readable Alchemy - the recipe does not wait")
        Fresh()
        skillReq, skillLine = nil, SECRET
        Trainer("a trainer without links, a hidden skill line")
        Fresh()
        skillReq, skillLine = SECRET, "Alchemy"
        Trainer("a trainer without links, a hidden required skill")
        -- 3. a trainer with links: the recipe is complete at once
        GetTrainerServiceItemLink = function() return "|Hitem:118::|h" end
        GetTrainerServiceNumReagents = function() return 1 end
        GetTrainerServiceReagentInfo = function() return "Peacebloom", 134400, 1 end
        GetTrainerServiceReagentLink = function() return "|Hitem:2447::|h" end
        Fresh()
        skillReq, skillLine = "Alchemy", nil
        Trainer()
        assert(Keys(ns.db.recipeDB.Alchemy) == 1, "test setup: a trainer's readable Alchemy with links - not stored")
        Fresh()
        skillReq, skillLine = SECRET, nil
        Trainer("a trainer with links, a hidden required skill")
        fire("TRAINER_CLOSED")
        -- 4. the profession window names its profession
        local windowName
        GetTradeSkillLine = function() return windowName, 77, 150 end
        GetNumTradeSkills = function() return 1 end
        GetTradeSkillInfo = function() return "R2 Window Potion", "optimal" end
        GetTradeSkillItemLink = function() return "|Hitem:118::|h" end
        GetTradeSkillNumMade = function() return 1, 1 end
        GetTradeSkillNumReagents = function() return 1 end
        GetTradeSkillReagentInfo = function() return "Peacebloom", 134400, 1, 0 end
        GetTradeSkillReagentItemLink = function() return "|Hitem:2447::|h" end
        Fresh()
        windowName = "Alchemy"
        fire("TRADE_SKILL_SHOW") advance(1)
        local stored = false
        for _, char in pairs(ns.db.recipes) do
            if char.Alchemy and Keys(char.Alchemy.list) == 1 then stored = true end
        end
        assert(stored and Keys(ns.db.recipeDB.Alchemy) == 1, "test setup: the profession window's readable Alchemy - not stored")
        Fresh()
        windowName = SECRET
        fire("TRADE_SKILL_SHOW") advance(1)
        Nothing("the profession window, a hidden name")
    end)
    type = realType
    for _, k in ipairs(G) do _G[k] = keep[k] end
    ns.db.recipes, ns.db.recipeDB, ns.db.recipePending = keepDB[1], keepDB[2], keepDB[3]
    if not ok then error(err, 0) end
end)
-- 0.2.2 P2e (Nachtrag zum Fahrplan, 21.11.2026; P2d counted 19,472 world
-- map pins in 45 zones with Sven's saved data, every one looked at every
-- 3 s): the pass every 3 s looks only at the pins that can be seen - the
-- world map pins shown now (none while the map is closed) and the minimap
-- pins of your zone. A world map pin coming into sight gets its colour and
-- alpha right then; the run target's pin keeps its own look.
step("World map pins 0.2.2: the pass every 3 s looks only at the shown ones - none while the map is closed; a pin coming into sight is right at once (0.2.2 P2e)", function()
    local Z = 1471
    local keep = { nodes = ns.db.nodes[Z], map = player.map, x = player.x, y = player.y }
    local ok, err = pcall(function()
        local function Node(x, extra)
            local n = { id = "o1731", name = "Copper Vein", type = "ore", x = x, y = 0.5, count = 1, last = 1 }
            for k, v in pairs(extra or {}) do n[k] = v end
            return n
        end
        local A, B, C = Node(0.40), Node(0.50, { emptyUntil = time() + 600 }), Node(0.60, { emptyUntil = time() + 600 })
        ns.db.nodes[Z] = { A, B, C }
        player.map, player.x, player.y = Z, 0.5, 0.5
        fire("ZONE_CHANGED_NEW_AREA") advance(1)
        ns.NotifyNodesChanged() advance(1)
        local function Pin(n, mini)
            local found
            for _, f in ipairs(allFrames) do
                if f.node == n and not f.isTarget and ((mini and f.isMini) or (not mini and f.isWorld)) then found = f end
            end
            return found
        end
        local calls = {}
        local function Spy(f)
            if rawget(f, "SetAlpha") then return f end
            calls[f] = 0
            f.SetAlpha = function(self, a) calls[self] = calls[self] + 1 self.__alpha = a end
            return f
        end
        local wa, wb, wc = Spy(Pin(A)), Spy(Pin(B)), Spy(Pin(C))
        -- (0.2.2 W4: the minimap pins near you are looked at - B lies where you stand; C, 500 yd
        -- off, is not registered, not on the minimap: its look comes when it is near, W4's own step)
        local mb = Spy(Pin(B, true))
        assert(wa and wb and wc and mb, "test setup: the pins of the three nodes")
        local function Reset() for f in pairs(calls) do calls[f] = 0 end end
        -- 1. the map closed: no world map pin is looked at; the minimap pins are
        Reset()
        ns.PinsUpdateAlpha()
        assert(calls[wa] == 0 and calls[wb] == 0 and calls[wc] == 0, ("the map closed: world map pins looked at (%d, %d, %d)"):format(calls[wa], calls[wb], calls[wc]))
        assert(calls[mb] > 0, "the minimap pin near you is not looked at")
        -- 2. the map shows A: A is looked at, B and C not
        Reset()
        wa:Show()
        assert(calls[wa] == 1, "A came into sight and got no alpha: " .. calls[wa])
        ns.PinsUpdateAlpha()
        assert(calls[wa] == 2 and calls[wb] == 0 and calls[wc] == 0, ("A shown: A %d, B %d, C %d calls"):format(calls[wa], calls[wb], calls[wc]))
        -- 3. B's cooldown ran out while it was out of sight: right as soon as it shows
        assert(wb.__alpha and wb.__alpha < 1, "test setup: B is not dimmed while on cooldown")
        B.emptyUntil = time() - 1
        ns.PinsUpdateAlpha()
        assert(wb.__alpha < 1, "test setup: B was looked at although hidden")
        local tinted = 0
        local ring = wb.ring
        if ring then
            local real = ring.SetVertexColor
            ring.SetVertexColor = function(self, ...) tinted = tinted + 1 return real(self, ...) end
        end
        wb:Show()
        assert(wb.__alpha == 1, "B came into sight still dimmed: " .. tostring(wb.__alpha))
        assert(not ring or tinted > 0, "B came into sight without its colour")
        if ring then ring.SetVertexColor = nil end
        -- 4. the run target's pin is shown and keeps its look; its node's own pin steps aside as before
        ns.SetRouteTarget(Z, C)
        local tw = ns.RouteTargetPins()
        tw:Hide() tw:Show()
        wc:Show()
        Reset()
        ns.PinsUpdateAlpha()
        assert(tw:GetAlpha() == 1, "the run target's pin was made see-through: " .. tostring(tw:GetAlpha()))
        assert(calls[wc] == 1 and wc.__alpha == 0, "C's own pin under the gold ring: not hidden")
        ns.ClearRouteTarget()
        -- 5. the map closed again: nothing
        wa:Hide() wb:Hide() wc:Hide() tw:Hide()
        Reset()
        ns.PinsUpdateAlpha()
        assert(calls[wa] == 0 and calls[wb] == 0 and calls[wc] == 0, "the map closed again: world map pins looked at")
        -- 6. your skill changes a colour while the map is closed (rare: a
        -- skill-up, training): every world map pin takes it at once, shown or not
        local keepSkill, keepMax = PROFS[2][2], PROFS[2][3]
        local function Col(pin)
            local c = pin.ring and pin.ring.__color
            return c and ("%.2f %.2f %.2f"):format(c[1], c[2], c[3]) or "-"
        end
        local okSkill, errSkill = pcall(function()
            PROFS[2][2], PROFS[2][3] = 1, 300 -- Copper: orange
            ns.PinsUpdateAlpha()
            local low = Col(wa)
            PROFS[2][2] = 200 -- Copper: grey
            Reset()
            ns.PinsUpdateAlpha()
            assert(low ~= "-" and Col(wa) ~= low, "a skill change with the map closed: the hidden pin kept its colour " .. low)
            assert(calls[wa] == 1 and calls[wb] == 1 and calls[wc] == 1,
                ("a skill change with the map closed: alpha of the hidden pins %d, %d, %d"):format(calls[wa], calls[wb], calls[wc]))
            -- the next pass without a change: none again
            Reset()
            ns.PinsUpdateAlpha()
            assert(calls[wa] == 0 and calls[wb] == 0 and calls[wc] == 0, "after the skill change: world map pins still looked at")
        end)
        PROFS[2][2], PROFS[2][3] = keepSkill, keepMax
        ns.PinsUpdateAlpha()
        for f in pairs(calls) do f.SetAlpha = nil end
        if not okSkill then error(errSkill, 0) end
    end)
    if ns.ClearRouteTarget then ns.ClearRouteTarget() end
    ns.db.nodes[Z] = keep.nodes
    player.map, player.x, player.y = keep.map, keep.x, keep.y
    fire("ZONE_CHANGED_NEW_AREA") advance(1)
    ns.NotifyNodesChanged() advance(1)
    if not ok then error(err, 0) end
end)
step("World map pins 0.2.2 W-B1: the route line on the world map only while the map is open, the head taken off in one call before it is drawn again - riding adds no map pins (0.2.2 W5)", function()
    -- Sven, 22.11.2026 (the performance diagnosis, part A 1.5; his check L4:
    -- a run, the world map opened once and closed, 2-3 minutes of riding -
    -- Gathercraft's memory 99 -> 155 MB). The head of the route line (you ->
    -- next node) added its dots to the world map again every 0.1 s while you
    -- ride, without taking them off: the game's map took a new pin for each.
    -- W5: the line's world map dots only while the map is open; the head's
    -- taken off in one call before they are added again; opened, the line is
    -- there as before, closed, it is off the world map. The minimap line
    -- stays as it was.
    local W = HBD_WORLD
    local HEAD, LINE = "GathercraftRouteHead", "GathercraftRoute"
    local Z = 1473
    local saved = { map = player.map, x = player.x, y = player.y, lineHidden = ns.db.routeLineHidden, miniHidden = ns.db.routeLineMiniHidden,
        length = ns.db.routeLineLength, mode = ns.db.routeMode, nodes = ns.db.nodes[Z] }
    -- (both lines on, the length as it comes, a Smart run - whatever the steps before left)
    ns.db.routeLineHidden, ns.db.routeLineMiniHidden, ns.db.routeLineLength, ns.db.routeMode = nil, nil, nil, nil
    local function Count(ref) local n = 0 for _ in pairs(W.reg[ref] or {}) do n = n + 1 end return n end
    local function Ride(seconds)
        for _ = 1, seconds * 2 do
            local t = ns.run and ns.run.target
            if t then
                local dx, dy = t.x - player.x, t.y - player.y
                local d = math.sqrt(dx * dx + dy * dy)
                if d > 0.001 then player.x, player.y = player.x + dx / d * 0.0005, player.y + dy / d * 0.0005 end
            end
            advance(0.5)
        end
    end
    local ok, err = pcall(function()
        -- a zone of its own with veins in a row (as in "Farm run: the line to the next node follows you")
        local function own(x, y) return { id = "o1731", name = "Copper Vein", type = "ore", x = x, y = y, count = 3, last = 1 } end
        ns.db.nodes[Z] = { own(0.30, 0.50), own(0.40, 0.55), own(0.50, 0.45), own(0.60, 0.55), own(0.70, 0.50) }
        player.map, player.x, player.y = Z, 0.25, 0.50
        ns.StartRun("ore", Z) advance(2)
        assert(ns.run and ns.run.target and ns.run.path, "no run with a path")
        -- the world map closed: the line is drawn again - on the minimap as before, not on the world map
        local lineMini0 = HBD_ADDS[LINE] and HBD_ADDS[LINE].mini or 0
        WorldMapFrame:Hide() advance(1)
        assert((HBD_ADDS[LINE] and HBD_ADDS[LINE].mini or 0) > lineMini0, "the world map closed: the route line on the minimap was not drawn again")
        -- riding with it closed: no world map dots, the head on the minimap goes on
        local function Mini() return HBD_ADDS[HEAD] and HBD_ADDS[HEAD].mini or 0 end
        local a0 = { head = W.adds[HEAD] or 0, line = W.adds[LINE] or 0, mini = Mini(), all = W.rmAll[HEAD] or 0 }
        Ride(10)
        -- (nothing of the head is on the map: it does not take it off again and again - each call goes over every pin the map holds)
        assert((W.rmAll[HEAD] or 0) == a0.all, ((W.rmAll[HEAD] or 0) - a0.all) .. " calls took the head off the closed world map while riding")
        assert((W.adds[HEAD] or 0) == a0.head and (W.adds[LINE] or 0) == a0.line,
            ("riding with the world map closed added %d head and %d line dots to the world map"):format((W.adds[HEAD] or 0) - a0.head, (W.adds[LINE] or 0) - a0.line))
        assert(Count(HEAD) == 0 and Count(LINE) == 0, ("the world map closed, still %d head and %d line dots on it"):format(Count(HEAD), Count(LINE)))
        assert(Mini() > a0.mini, "the head of the route line on the minimap was not drawn while riding")
        -- opened: the line is there; riding on, no dot is added while it is on the map
        WorldMapFrame:Show() advance(0.5)
        assert(Count(LINE) > 0, "the world map opened during a run: no route line on it")
        local d0 = { head = W.dup[HEAD] or 0, line = W.dup[LINE] or 0 }
        Ride(5)
        assert((W.dup[HEAD] or 0) == d0.head and (W.dup[LINE] or 0) == d0.line,
            ("with the map open %d head and %d line dots were added again while still on the map"):format((W.dup[HEAD] or 0) - d0.head, (W.dup[LINE] or 0) - d0.line))
        -- the same line every time it is drawn on the open map
        LINE_PTS = {}
        ns.RedrawRouteLine()
        local first = LINE_PTS
        LINE_PTS = {}
        ns.RedrawRouteLine()
        assert(#first > 0 and #first == #LINE_PTS, ("the line on the open map: %d dots, then %d"):format(#first, #LINE_PTS))
        for i, p in ipairs(first) do assert(p[1] == LINE_PTS[i][1] and p[2] == LINE_PTS[i][2], "the line on the open map moved at dot " .. i) end
        -- closed again: off the world map
        WorldMapFrame:Hide() advance(0.5)
        assert(Count(HEAD) == 0 and Count(LINE) == 0, ("closed again, still %d head and %d line dots on the world map"):format(Count(HEAD), Count(LINE)))
    end)
    ns.StopRun()
    WorldMapFrame:Show()
    ns.db.nodes[Z] = saved.nodes
    player.map, player.x, player.y = saved.map, saved.x, saved.y
    ns.db.routeLineHidden, ns.db.routeLineMiniHidden, ns.db.routeLineLength, ns.db.routeMode = saved.lineHidden, saved.miniHidden, saved.length, saved.mode
    advance(2)
    if not ok then error(err, 0) end
end)
step("World map pins 0.2.2 W-A: a rebuild takes our world map pins off in one call, a login builds once, a zone seen first on the world map gets only its own pins, none added twice (0.2.2 W1-W3)", function()
    -- Sven, 22.11.2026 (the performance diagnosis, part A): with his data a
    -- full rebuild cost HereBeDragons 0.6-0.9 s - every one of 19,472 world
    -- map pins was taken off on its own, and each taking off goes over all the
    -- pins the map holds. It came four times after a login and with every
    -- zone looked at on the world map for the first time (its known spawn
    -- points come in). W1: one call takes them all off. W2: the zones of
    -- before load quietly, then one rebuild. W3: a zone new on the world map
    -- adds the pins of its own new points and nothing else is redone - the
    -- same pins a rebuild gives. What is seen stays the same.
    local W, REF = HBD_WORLD, "Gathercraft"
    local data = GathercraftQuestieData
    local function InUse(mapID)
        local n, shared, kinds = 0, 0, 0
        for _, f in ipairs(allFrames) do
            if f.isWorld and f.node and not f.isTarget and (not mapID or f.mapID == mapID) then
                n = n + 1
                if f.others and #f.others > 0 then shared, kinds = shared + 1, kinds + #f.others end
            end
        end
        return n, shared, kinds
    end
    -- what is registered now: every world map pin in use
    local function Resync()
        local r = {}
        for _, f in ipairs(allFrames) do if f.isWorld and f.node and not f.isTarget then r[f] = true end end
        W.reg[REF] = r
    end
    local function Mark() return { adds = W.adds[REF] or 0, one = W.rmOne[REF] or 0, all = W.rmAll[REF] or 0, dup = W.dup[REF] or 0 } end
    local function Since(m)
        local now = Mark()
        return { adds = now.adds - m.adds, one = now.one - m.one, all = now.all - m.all, dup = now.dup - m.dup }
    end
    -- zones with known spawn points that nothing has loaded yet
    local fresh = {}
    for mapID in pairs(data and data.zones or {}) do
        if not ns.db.nodes[mapID] and not (ns.db.spawnZones or {})[mapID] then fresh[#fresh + 1] = mapID end
    end
    table.sort(fresh)
    assert(#fresh >= 5, "fewer than 5 zones with known spawn points not loaded yet: " .. #fresh)
    local saved = { world = ns.db.worldPinsHidden, mini = ns.db.miniPinsHidden, getMap = WorldMapFrame.GetMapID }
    ns.db.worldPinsHidden, ns.db.miniPinsHidden = nil, nil
    local ok, err = pcall(function()
        ns.NotifyNodesChanged() advance(2)
        Resync()
        -- W1: a rebuild - all pins off, then on again
        local n0 = InUse()
        assert(n0 > 0, "no world map pins to start with")
        local m = Mark()
        ns.TogglePins() -- (off)
        local s = Since(m)
        assert(s.one == 0, ("a rebuild took %d world map pins off one by one"):format(s.one))
        assert(s.all == 1, ("a rebuild took the world map pins off with %d calls, want 1"):format(s.all))
        m = Mark()
        ns.TogglePins() -- (on)
        s = Since(m)
        assert(InUse() == n0 and s.adds == n0, ("on again: %d added, %d in use, %d before"):format(s.adds, InUse(), n0))
        assert(s.dup == 0, s.dup .. " world map pins added while still registered (rebuild)")
        -- W2: a login with three zones of before still to load - one rebuild
        ns.db.spawnZones = ns.db.spawnZones or {}
        for i = 1, 3 do ns.db.spawnZones[fresh[i]] = true end
        m = Mark()
        -- (something asks for a rebuild right before - in deDE the names of the
        -- nodes do, in whichever order the parts see PLAYER_LOGIN)
        ns.NotifyNodesChanged()
        fire("PLAYER_LOGIN") advance(15)
        s = Since(m)
        local n1 = InUse()
        for i = 1, 3 do assert(ns.db.nodes[fresh[i]] and #ns.db.nodes[fresh[i]] > 0, "zone " .. fresh[i] .. " of before not loaded at login") end
        assert(n1 > n0, "the zones loaded at login got no world map pins")
        assert(s.all == 1 and s.one == 0, ("after a login the world map pins were taken off %d times in one call and %d one by one, want once in one call"):format(s.all, s.one))
        assert(s.adds <= n1, ("a login added %d world map pins for %d in use: it built more than once"):format(s.adds, n1))
        assert(s.dup == 0, s.dup .. " world map pins added while still registered (login)")
        -- W3: a zone seen first on the world map
        local Z = fresh[4]
        WorldMapFrame.GetMapID = function() return Z end
        m = Mark()
        WorldMapFrame:OnMapChanged() advance(2)
        s = Since(m)
        local nz, sharedZ, kindsZ = InUse(Z)
        assert(ns.db.nodes[Z] and #ns.db.nodes[Z] > 0 and nz > 0, "the zone seen on the world map got no points or no pins")
        assert(s.all == 0 and s.one == 0, ("a zone new on the world map rebuilt the pins (%d calls in one, %d one by one)"):format(s.all, s.one))
        assert(s.adds == nz, ("a zone new on the world map added %d world map pins, its own are %d"):format(s.adds, nz))
        assert(s.dup == 0, s.dup .. " world map pins added while still registered (zone)")
        -- the same pins a rebuild gives them
        local total = InUse()
        ns.TogglePins() ns.TogglePins()
        local rz, rShared, rKinds = InUse(Z)
        assert(rz == nz and rShared == sharedZ and rKinds == kindsZ and InUse() == total,
            ("the zone's pins are not what a rebuild gives: %d pins, %d shared spots with %d more kinds against %d/%d/%d"):format(nz, sharedZ, kindsZ, rz, rShared, rKinds))
        -- a zone's points coming in during a run: the run chooses its group of zones again, as before
        -- (a run of its own on veins of a zone of its own: the steps before may leave no herb run possible)
        local RZ, keep = 1474, { map = player.map, x = player.x, y = player.y, nodes = ns.db.nodes[1474] }
        local function own(x, y) return { id = "o1731", name = "Copper Vein", type = "ore", x = x, y = y, count = 3, last = 1 } end
        ns.db.nodes[RZ] = { own(0.30, 0.50), own(0.40, 0.55), own(0.50, 0.45) }
        player.map, player.x, player.y = RZ, 0.25, 0.50
        ns.StartRun("ore", RZ) advance(1)
        local hadRun = ns.run ~= nil
        if hadRun then
            ns.run.groupDone = true
            ns.ImportQuestieZone(fresh[5], true)
        end
        local kept = hadRun and ns.run.groupDone
        ns.StopRun() advance(1)
        ns.db.nodes[RZ] = keep.nodes
        player.map, player.x, player.y = keep.map, keep.x, keep.y
        assert(hadRun, "no run")
        assert(kept == nil, "a zone's points came in during a run, and it kept its group of zones")
    end)
    -- the five zones go again (the session keeps them as loaded)
    for i = 1, 5 do
        ns.db.nodes[fresh[i]] = nil
        if ns.db.spawnZones then ns.db.spawnZones[fresh[i]] = nil end
    end
    ns.db.worldPinsHidden, ns.db.miniPinsHidden = saved.world, saved.mini
    WorldMapFrame.GetMapID = saved.getMap
    ns.NotifyNodesChanged() advance(2)
    if not ok then error(err, 0) end
end)
step("Minimap pins 0.2.2 W4: the 3-s look sets colour and alpha of the pins near you only, one that comes near gets its look then (0.2.2 W4)", function()
    -- Sven, 22.11.2026 (the performance diagnosis, section 4): every 3 s the
    -- colour and alpha of all minimap pins of the zone were set, also the far
    -- ones the minimap does not show (1.4-1.8 ms in The Barrens with his
    -- data). W4: the look goes over the pins registered near you (the only
    -- ones the minimap shows); one that comes near gets its colour and alpha
    -- when it is registered, so it looks as before. A colour change still
    -- goes to every pin of the zone at once.
    local M, REF = HBD_MINI, "Gathercraft"
    local saved = { x = player.x, y = player.y, setAlpha = methods.SetAlpha, mini = ns.db.miniPinsHidden, world = ns.db.worldPinsHidden }
    local changedNode, keepUntil
    ns.db.miniPinsHidden, ns.db.worldPinsHidden = nil, nil
    local ok, err = pcall(function()
        -- after a rebuild the book of registered minimap pins is right
        M.reg[REF] = {}
        ns.NotifyNodesChanged() advance(2)
        local zone = ns.GetPlayerPos()
        local zonePins, near = {}, M.reg[REF]
        for _, f in ipairs(allFrames) do
            if f.isMini and f.node and not f.isTarget and f.mapID == zone then zonePins[#zonePins + 1] = f end
        end
        local far = {}
        for _, f in ipairs(zonePins) do if not near[f] then far[#far + 1] = f end end
        assert(#far > 0 and #zonePins > #far, ("the zone has %d minimap pins, %d far away: nothing to look at"):format(#zonePins, #far))
        local touched = {}
        methods.SetAlpha = function(self, a) touched[self] = true return saved.setAlpha(self, a) end
        ns.PinsUpdateAlpha()
        methods.SetAlpha = saved.setAlpha
        local farTouched, nearTouched = 0, 0
        for _, f in ipairs(far) do if touched[f] then farTouched = farTouched + 1 end end
        for f in pairs(near) do if touched[f] then nearTouched = nearTouched + 1 end end
        assert(farTouched == 0, ("the 3-s look set the alpha of %d minimap pins far away (of %d)"):format(farTouched, #far))
        assert(nearTouched > 0, "the 3-s look set no minimap pin near you")
        -- a far pin whose node went empty meanwhile: near, it shows it at once
        local m = far[1]
        changedNode, keepUntil = m.node, m.node.emptyUntil
        m.node.emptyUntil = time() + 600
        player.x, player.y = m.node.x, m.node.y
        ns.MiniPinLook()
        assert(M.reg[REF][m], "walked to a far pin: it did not come on")
        local atOn = m:GetAlpha()
        ns.PinsUpdateAlpha()
        assert(atOn == m:GetAlpha() and atOn < 1, ("a pin that came near showed alpha %.2f, the next look made it %.2f"):format(atOn, m:GetAlpha()))
    end)
    methods.SetAlpha = saved.setAlpha
    if changedNode then changedNode.emptyUntil = keepUntil end
    player.x, player.y = saved.x, saved.y
    ns.db.miniPinsHidden, ns.db.worldPinsHidden = saved.mini, saved.world
    ns.MiniPinLook()
    advance(2)
    if not ok then error(err, 0) end
end)
-- 0.2.3 P3 (R8; night order 22.11.2026): your best runs per zone, from a short
-- history of your own runs - this computer only. A run counts for a best run
-- from 10 minutes of riding; per hour is per hour from start to end (a pause
-- only makes it slower). Best runs are per character, zone, filter and goal.
step("Run history 0.2.3: the runs and their best - first, new best, slower, too short, a pause, another character, filter or goal; 20 kept per zone (0.2.3 P3)", function()
    local keep = { hist = ns.db.runHistory, key = ns.PlayerKey }
    local ok, err = pcall(function()
        ns.db.runHistory = nil
        local char = "Player-1-0000AAAA"
        ns.PlayerKey = function() return char end
        local function Run(nodes, minutes, active, extra)
            local s = { zone = 1412, elapsed = minutes * 60, active = active * 60, nodes = nodes, value = nodes * 1000, unknownPrice = 0,
                filter = "herb", goal = "gold", way = "smart", skill = 2, herbSkill = 150, oreSkill = 60 }
            for k, v in pairs(extra or {}) do s[k] = v end
            return ns.RunHistoryAdd(s)
        end
        -- 1. the first run that counts (30 min, 25 of them riding): 60 nodes = 120 per hour
        local r = Run(60, 30, 25)
        assert(r and r.counted and r.first and not r.newBest, "the first run that counts is not called the first")
        assert(math.abs(r.nodes - 120) < 1e-6 and math.abs(r.gold - 120000) < 1e-6, ("first run: %s nodes/h, %s copper/h"):format(tostring(r.nodes), tostring(r.gold)))
        local e = ns.db.runHistory[1412][1]
        assert(e.f == "herb" and e.g == "gold" and e.k == "smart" and e.a == 1500 and e.e == 1800 and e.n == 60 and e.v == 60000
            and e.u == 0 and e.s == 2 and e.c == char and e.h == 150 and e.o == 60 and type(e.t) == "number", "the run kept is not the run")
        -- 2. faster: a new best, the best is the new one
        r = Run(80, 30, 28)
        assert(r.counted and r.newBest and r.newNodes and r.newGold and math.abs(r.nodes - 160) < 1e-6, "a faster run is not a new best")
        -- 3. slower: no new best, the best stays the faster one
        r = Run(50, 30, 28)
        assert(r.counted and not r.newBest and math.abs(r.nodes - 160) < 1e-6, "a slower run changed the best")
        -- 4. too short (9 minutes of riding), however fast: not counted, the best stays
        r = Run(40, 9, 9)
        assert(not r.counted and not r.newBest and math.abs(r.nodes - 160) < 1e-6, "a run under 10 minutes of riding counted")
        -- 5. a pause: the same 80 nodes and 28 minutes riding, but 60 minutes from start to end - slower, not better
        r = Run(80, 60, 28)
        assert(r.counted and not r.newBest and math.abs(r.nodes - 160) < 1e-6, "a pause made a run better")
        -- 6. only the gold is better: a new best (gold per hour), nodes per hour stays
        r = Run(70, 30, 28, { value = 70 * 5000 })
        assert(r.newBest and r.newGold and not r.newNodes and math.abs(r.nodes - 160) < 1e-6 and math.abs(r.gold - 700000) < 1e-6, "a better gold per hour is not a new best")
        -- 7. another character, filter or goal: its own first run
        char = "Player-1-0000BBBB"
        assert(Run(30, 30, 25).first, "another character's run compared with this one's")
        char = "Player-1-0000AAAA"
        assert(Run(30, 30, 25, { filter = "both" }).first and Run(30, 30, 25, { goal = "skill" }).first, "another filter or goal compared")
        assert(Run(30, 30, 25, { zone = 1411 }).first, "another zone compared")
        -- 8. no zone of its own (a run over several zones), or no time: not kept
        local count = #ns.db.runHistory[1412]
        assert(Run(30, 30, 25, { zone = false }) == nil and Run(30, 0, 0) == nil and #ns.db.runHistory[1412] == count, "a run without a zone or time was kept")
        -- 9. 20 runs kept per zone: the oldest goes
        for i = 1, 30 do Run(i, 30, 25, { skill = 100 + i }) end
        local list = ns.db.runHistory[1412]
        assert(#list == ns.RUN_HISTORY_KEEP and ns.RUN_HISTORY_KEEP == 20, ("%d runs kept in a zone"):format(#list))
        assert(list[1].s == 111 and list[20].s == 130, ("kept: from skill %s to %s, want the last 20"):format(tostring(list[1].s), tostring(list[20].s)))
        assert(#ns.db.runHistory[1411] == 1, "another zone's runs were dropped")
        -- 10. a saved history that is not a table (an older or broken file): a fresh one, no error
        ns.db.runHistory = "x"
        assert(Run(60, 30, 25).first and type(ns.db.runHistory) == "table", "a broken history: no fresh one")
        ns.db.runHistory[1412] = 5
        assert(Run(60, 30, 25).first and #ns.db.runHistory[1412] == 1, "a broken zone list: no fresh one")
    end)
    ns.db.runHistory, ns.PlayerKey = keep.hist, keep.key
    if not ok then error(err, 0) end
end)
-- 0.2.3 P3-M1 (Codex, P3 round 1): the best the summary shows is the best the
-- history keeps once the run went in and the oldest went out - what
-- RunHistoryBest says; "New personal best" only against the best before the
-- run, not for one that is first only because the best run just went out.
-- The line says it is about the last runs here, and that nodes and gold per
-- hour are each a best of their own (not one run).
step("Run history 0.2.3: the best shown is the best kept, not one that just went out; a new best only against the best before the run (0.2.3 P3-M1)", function()
    local keep = { hist = ns.db.runHistory, key = ns.PlayerKey }
    local ok, err = pcall(function()
        local char = "Player-1-0000AAAA"
        ns.PlayerKey = function() return char end
        local KEEP = ns.RUN_HISTORY_KEEP
        -- a run of 10 minutes, all of them riding: n nodes = 6n per hour
        local function Run(nodes, extra)
            local s = { zone = 1412, elapsed = 600, active = 600, nodes = nodes, value = nodes * 1000, unknownPrice = 0,
                filter = "herb", goal = "gold", way = "smart", skill = 0, herbSkill = 150, oreSkill = 60 }
            for k, v in pairs(extra or {}) do s[k] = v end
            return ns.RunHistoryAdd(s)
        end
        local function Best() return ns.RunHistoryBest(1412, char, "herb", "gold") end
        local function Same(a, b) return a and b and math.abs(a - b) < 1e-6 end
        local FULL = "Your best of the last %d runs here (%s), each on its own: %d nodes per hour, %s per hour"
        -- 1. Codex's case: 100 nodes (600 per hour), then 19 runs of 10 (60 per hour): 20 kept.
        -- The next run, 20 nodes (120 per hour), pushes the first one out
        ns.db.runHistory = nil
        Run(100)
        for _ = 1, KEEP - 1 do Run(10) end
        local r = Run(20)
        local b = Best()
        assert(#ns.db.runHistory[1412] == KEEP and b and Same(b.nodes, 120), "test setup: the best of the runs kept is not 120 nodes per hour")
        assert(Same(r.nodes, b.nodes) and Same(r.gold, b.gold), ("the summary shows %s nodes and %s copper per hour, the history keeps %s and %s"):format(
            tostring(r.nodes), tostring(r.gold), tostring(b.nodes), tostring(b.gold)))
        assert(not r.newBest and not r.newNodes and not r.newGold, "first only because the best run went out: called a new best")
        local line, notes = ns.RunSummaryBestLines({ best = r })
        assert(line == (ns.L[FULL]):format(KEEP, ns.L["Gold"], 120, ns.Money(120000, true)), "the best line after the best run went out: " .. tostring(line))
        assert(not (notes and notes:find(ns.L["New personal best here!"], 1, true)), "the notes call it a new best: " .. tostring(notes))
        -- 2. better than the best before it (120): a new best, shown as kept
        r = Run(30)
        assert(r.newBest and r.newNodes and Same(r.nodes, 180) and Same(Best().nodes, 180), "a run better than the best before it is not a new best")
        -- 3. a run too short to count once the only counted runs went out: no best line left
        ns.db.runHistory = nil
        Run(100)
        for _ = 1, KEEP - 1 do Run(10, { active = 60 }) end
        r = Run(10, { active = 60 })
        assert(not r.counted and r.nodes == nil and Best() == nil, "the counted run went out, yet a best is shown: " .. tostring(r.nodes))
        assert(ns.RunSummaryBestLines({ best = r }) == nil, "a best line without a counted run kept")
        -- 4. the text in the nine translations, with the same placeholders in the same order; the old one gone
        local function Codes(s)
            local list = {}
            for code in s:gmatch("%%[%d%$]*[sd]") do list[#list + 1] = code end
            return table.concat(list, " ")
        end
        for _, lang in ipairs({ "deDE", "esES", "frFR", "itIT", "koKR", "ptBR", "ruRU", "zhCN", "zhTW" }) do
            local tr = ns.Locales[lang] and ns.Locales[lang][FULL]
            assert(type(tr) == "string" and tr ~= "" and tr ~= FULL, ("no %s translation of %q"):format(lang, FULL))
            assert(Codes(tr) == Codes(FULL), ("%s: other placeholders (or another order) in %q: %s"):format(lang, FULL, tr))
            assert(ns.Locales[lang]["Best run here (%s): %d nodes per hour, %s per hour"] == nil, lang .. ": the old best line is still there")
        end
    end)
    ns.db.runHistory, ns.PlayerKey = keep.hist, keep.key
    if not ok then error(err, 0) end
end)
-- 0.2.3 P3-M2 (Codex, P3 round 1): the best gold per hour carries the state of
-- its prices. From a run with nodes without a price it is a lower bound ("at
-- least ... (some prices unknown)"), apart from this run's own note; of runs
-- with the same gold per hour the one with every price known counts, then
-- the newer one.
step("Run history 0.2.3: the best gold per hour says when its prices were not all known - a lower bound, apart from this run's note; with the same gold per hour the run with every price known (0.2.3 P3-M2)", function()
    local keep = { hist = ns.db.runHistory, key = ns.PlayerKey }
    local ok, err = pcall(function()
        local char = "Player-1-0000AAAA"
        ns.PlayerKey = function() return char end
        local KEEP = ns.RUN_HISTORY_KEEP
        local function Run(nodes, extra)
            local s = { zone = 1412, elapsed = 600, active = 600, nodes = nodes, value = nodes * 1000, unknownPrice = 0,
                filter = "herb", goal = "gold", way = "smart", skill = 0, herbSkill = 150, oreSkill = 60 }
            for k, v in pairs(extra or {}) do s[k] = v end
            return ns.RunHistoryAdd(s)
        end
        local function Best() return ns.RunHistoryBest(1412, char, "herb", "gold") end
        local function Same(a, b) return a and b and math.abs(a - b) < 1e-6 end
        local FULL = "Your best of the last %d runs here (%s), each on its own: %d nodes per hour, %s per hour"
        local LOWER = "Your best of the last %d runs here (%s), each on its own: %d nodes per hour, at least %s per hour (some prices unknown)"
        local function Shown(text, nodes, gold) return (ns.L[text]):format(KEEP, ns.L["Gold"], nodes, ns.Money(gold, true)) end
        local function Has(notes, text) return notes and notes:find(text, 1, true) ~= nil end
        local function This(n) return (ns.L["Gold per hour from known prices only (%d nodes without one)."]):format(n) end
        -- 1. the best gold per hour from a run with a node without a price; this run with every price known
        ns.db.runHistory = nil
        Run(10, { value = 10000, unknownPrice = 1 })
        local r = Run(10, { value = 100 })
        assert(Same(r.gold, 60000) and (r.goldUnknown or 0) > 0 and (r.unknown or 0) == 0, ("an old best with a price unknown: %s copper per hour, its state %s, this run's %s"):format(
            tostring(r.gold), tostring(r.goldUnknown), tostring(r.unknown)))
        assert((Best().goldUnknown or 0) > 0, "RunHistoryBest does not say the best gold per hour had a price unknown")
        local line, notes = ns.RunSummaryBestLines({ best = r })
        assert(line == Shown(LOWER, 60, 60000), "a best gold per hour with a price unknown is not shown as a lower bound: " .. tostring(line))
        assert(not Has(notes, This(0)) and not Has(notes, This(1)), "this run (every price known) gets the note about unknown prices: " .. tostring(notes))
        -- 2. the other way: the best with every price known, this run with two nodes without a price
        ns.db.runHistory = nil
        Run(10, { value = 10000 })
        r = Run(10, { value = 100, unknownPrice = 2 })
        assert(Same(r.gold, 60000) and (r.goldUnknown or 0) == 0 and r.unknown == 2, "an old best with every price known: its state or this run's is wrong")
        line, notes = ns.RunSummaryBestLines({ best = r })
        assert(line == Shown(FULL, 60, 60000), "a best gold per hour with every price known is shown as a lower bound: " .. tostring(line))
        assert(Has(notes, This(2)), "this run's unknown prices are not told: " .. tostring(notes))
        -- 3. the same gold per hour twice: the run with every price known counts, whichever came first;
        -- of two with prices unknown the newer one
        for _, order in ipairs({ { 1, 0 }, { 0, 1 } }) do
            ns.db.runHistory = nil
            Run(10, { value = 10000, unknownPrice = order[1] })
            r = Run(10, { value = 10000, unknownPrice = order[2] })
            assert((r.goldUnknown or 0) == 0 and (Best().goldUnknown or 0) == 0, ("the same gold per hour, prices unknown %d then %d: the run with every price known does not count"):format(order[1], order[2]))
            assert(ns.RunSummaryBestLines({ best = r }) == Shown(FULL, 60, 60000), "the same gold per hour: shown as a lower bound")
        end
        ns.db.runHistory = nil
        Run(10, { value = 10000, unknownPrice = 1 })
        r = Run(10, { value = 10000, unknownPrice = 3 })
        assert(r.goldUnknown == 3 and Best().goldUnknown == 3, "the same gold per hour, both with prices unknown: not the newer run's state")
        -- 4. the text in the nine translations, with the same placeholders in the same order
        local function Codes(s)
            local list = {}
            for code in s:gmatch("%%[%d%$]*[sd]") do list[#list + 1] = code end
            return table.concat(list, " ")
        end
        for _, lang in ipairs({ "deDE", "esES", "frFR", "itIT", "koKR", "ptBR", "ruRU", "zhCN", "zhTW" }) do
            local tr = ns.Locales[lang] and ns.Locales[lang][LOWER]
            assert(type(tr) == "string" and tr ~= "" and tr ~= LOWER, ("no %s translation of %q"):format(lang, LOWER))
            assert(Codes(tr) == Codes(LOWER), ("%s: other placeholders (or another order) in %q: %s"):format(lang, LOWER, tr))
        end
    end)
    ns.db.runHistory, ns.PlayerKey = keep.hist, keep.key
    if not ok then error(err, 0) end
end)
step("Run history 0.2.3: a run ends in its zone's history - riding time from moving and gathering, not standing, death, a taxi or a hidden position; nodes without a price; the summary's lines (0.2.3 P3)", function()
    local keep = { hist = ns.db.runHistory, map = player.map, x = player.x, y = player.y, dead = UnitIsDeadOrGhost, taxi = UnitOnTaxi,
        secret = issecretvalue, off = ns.db.summaryOff, send = SendChatMessage }
    local ok, err = pcall(function()
        ns.db.runHistory, ns.db.summaryOff = nil, nil
        local card
        local function Start(x)
            player.map, player.x, player.y = 1412, x or 0.40, 0.50
            ns.StartRun("herb", 1412) advance(1)
            assert(ns.run and ns.run.zone == 1412, "test setup: no run in Mulgore")
        end
        -- 2 yd a second (the mock's map is 5000 yd wide)
        local function Ride(seconds) for _ = 1, seconds do player.x = player.x + 0.0004 advance(1) end end
        -- (item 999991: no price at all - no vendor price either; every other item of the mock has one)
        local NOPRICE = 999991
        local function Gather(item)
            local p = { items = { { id = item, qty = 2 } } }
            local info, cinfo = GetItemInfo, C_Item and C_Item.GetItemInfo
            local function Without(f)
                return function(id, ...)
                    if id == NOPRICE then return "Item" .. id, nil, 1, 1, 1, "Trade Goods", "Herb", 20, "", 134400, 0 end
                    return f(id, ...)
                end
            end
            GetItemInfo = Without(info)
            if cinfo then C_Item.GetItemInfo = Without(cinfo) end
            for _, f in ipairs(ns.gatherListeners) do f({ type = "herb", name = "Peacebloom" }, p) end
            GetItemInfo = info
            if cinfo then C_Item.GetItemInfo = cinfo end
            return p
        end
        local function Last() local l = ns.db.runHistory[1412] return l[#l] end
        -- what the run's end hands the summary
        local shown
        keep.show = ns.ShowRunSummary
        ns.ShowRunSummary = function(s) shown = s return keep.show(s) end
        -- 1. 11 minutes: ride, gather (a priced item and one without a price), stand a while at a node
        Start()
        Ride(300)
        local priced = Gather(2770)
        local unpriced = Gather(999991)
        assert(priced.value > 0 and priced.valueMissing == 0 and unpriced.valueMissing == 1, ("test setup: prices %s/%s, missing %s/%s"):format(
            tostring(priced.value), tostring(unpriced.value), tostring(priced.valueMissing), tostring(unpriced.valueMissing)))
        advance(8) -- at the node: gathering, counts as riding
        Ride(300)
        advance(120) -- standing: does not count
        ns.StopRun()
        local e = Last()
        assert(e and e.n == 2 and e.u == 1 and e.v > 0 and e.f == "herb" and e.k == "smart" and e.c == ns.PlayerKey(), "the run was not kept as it was")
        assert(e.a >= 605 and e.a <= 615, ("riding time %d s, want about 609 (600 riding, 8 at the node, the 120 standing not)"):format(e.a))
        assert(e.e >= 728 and e.e <= 732, ("time from start to end %d s, want about 730"):format(e.e))
        card = _G.GathercraftRunSummary
        assert(card and card:IsShown(), "test setup: no summary")
        assert(shown and shown.best and shown.best.counted and shown.best.first and shown.best.unknown == 1,
            "the summary was not told: the first counted run here, one node without a price")
        local best, notes = ns.RunSummaryBestLines({ best = { counted = true, first = true, unknown = 1, minutes = 10 } })
        assert(best == ns.L["First counted run here."] and notes:find((ns.L["Gold per hour from known prices only (%d nodes without one)."]):format(1), 1, true),
            "first run: the summary's lines " .. tostring(best) .. " / " .. tostring(notes))
        -- the line shared in chat does not carry the best run
        local sent = {}
        SendChatMessage = function(msg) sent[#sent + 1] = msg end
        ns.ShareRunSummary("GUILD")
        assert(sent[1] and not sent[1]:find(ns.L["First counted run here."], 1, true) and not sent[1]:find("best", 1, true), "the shared line carries the best run: " .. tostring(sent[1]))
        SendChatMessage = keep.send
        -- 2. standing at the start, then 11 minutes in which the character is dead, on a taxi or its position hidden: under 10 minutes of riding
        Start()
        UnitIsDeadOrGhost = function() return true end
        Ride(200)
        UnitIsDeadOrGhost = keep.dead
        UnitOnTaxi = function() return true end
        Ride(200)
        UnitOnTaxi = keep.taxi
        -- jumps of 1000 yd and more every second (a teleport, a portal): not riding
        for _ = 1, 100 do player.x = (player.x + 0.2) % 0.8 + 0.1 advance(1) end
        -- a hidden position: the history's own look once a second, 200 times, with the
        -- clock held (the route's code is not part of this: only the history is asked)
        -- (the stand-in's type says "number", as the game's hidden numbers do: only the
        -- secret check can tell it)
        local SECRET = newproxy(true)
        issecretvalue = function(v) return rawequal(v, SECRET) end
        local HBD = LibStub("HereBeDragons-2.0")
        local where, clock, realType = HBD.GetPlayerWorldPosition, GetTime, type
        local t = GetTime()
        GetTime = function() return t end
        HBD.GetPlayerWorldPosition = function() return SECRET, SECRET, 1 end
        type = function(v) if rawequal(v, SECRET) then return "number" end return realType(v) end
        local okTick, errTick = pcall(function()
            for _ = 1, 200 do t = t + 1 player.x = player.x + 0.0004 ns.RunHistoryTick() end
        end)
        type = realType
        HBD.GetPlayerWorldPosition, GetTime = where, clock
        issecretvalue = keep.secret
        assert(okTick, "the history's look at a hidden position: " .. tostring(errTick))
        Ride(30)
        Gather(2770)
        ns.StopRun()
        e = Last()
        assert(e.a >= 25 and e.a <= 45, ("riding time %d s - dead, on a taxi, jumping or hidden for 700 s, then 30 s riding"):format(e.a))
        best, notes = ns.RunSummaryBestLines({ best = { counted = false, unknown = 0, minutes = 10 } })
        assert(best == nil and notes == (ns.L["Not counted for your best runs: under %d minutes of riding."]):format(10), "too short: " .. tostring(notes))
        -- 3. a second run of 11 minutes riding, faster: a new best in the summary
        Start()
        for i = 1, 6 do Ride(100) Gather(2770) end
        Ride(60)
        shown = nil
        ns.StopRun()
        assert(shown and shown.best and shown.best.counted and shown.best.newBest and shown.best.newNodes, "a faster run: the summary was not told it is a new best")
        assert(e and shown.best.nodes > 6 / (Last().e / 3600) - 1e-6, "the summary's best is not the new run's")
        best, notes = ns.RunSummaryBestLines({ best = { counted = true, newBest = true, nodes = 33, gold = 1234, goal = "gold", unknown = 0 } })
        assert(best == (ns.L["Your best of the last %d runs here (%s), each on its own: %d nodes per hour, %s per hour"]):format(ns.RUN_HISTORY_KEEP, ns.L["Gold"], 33, ns.Money(1234, true)) and notes == ns.L["New personal best here!"],
            "new best: " .. tostring(best) .. " / " .. tostring(notes))
        local now = ns.RunHistoryBest(1412, ns.PlayerKey(), "herb", Last().g)
        assert(now and now.nodes > 6 / (Last().e / 3600) - 1e-6, "the faster run is not the best")
        -- 4. the summary turned off: the run is kept all the same
        ns.db.summaryOff = true
        local n = #ns.db.runHistory[1412]
        Start()
        Ride(60)
        Gather(2770)
        advance(100)
        ns.StopRun()
        assert(#ns.db.runHistory[1412] == n + 1, "with the summary off the run was not kept")
        ns.db.summaryOff = nil
        -- 5. a new run replacing the old one: the old one is not kept (no summary, no history)
        Start()
        Ride(30)
        Start(0.6)
        ns.StopRun(true)
        assert(#ns.db.runHistory[1412] == n + 1, "a run replaced by another (or stopped quietly) was kept")
    end)
    if ns.run then ns.StopRun(true) end
    if keep.show then ns.ShowRunSummary = keep.show end
    local card = _G.GathercraftRunSummary
    if card then card:Hide() end
    ns.db.runHistory, ns.db.summaryOff = keep.hist, keep.off
    UnitIsDeadOrGhost, UnitOnTaxi, issecretvalue, SendChatMessage = keep.dead, keep.taxi, keep.secret, keep.send
    player.map, player.x, player.y = keep.map, keep.x, keep.y
    if not ok then error(err, 0) end
end)
step("Run history 0.2.3: never shared - Sync and the shared summary line know nothing of it (0.2.3 P3)", function()
    local function Src(file)
        local f = assert(io.open(ROOT .. "/" .. file))
        local t = f:read("*a") f:close()
        return t
    end
    for _, file in ipairs({ "Sync.lua", "Main.lua", "Options.lua" }) do
        assert(not Src(file):find("runHistory", 1, true) and not Src(file):find("RunHistory", 1, true), file .. " reads the run history")
    end
    local mine = Src("RunHistory.lua")
    for _, call in ipairs({ "SendAddonMessage", "SendChatMessage", "C_ChatInfo", "ns.Sync" }) do
        assert(not mine:find(call, 1, true), "RunHistory.lua calls " .. call)
    end
    local welcome = Src("Welcome.lua")
    local share = welcome:match("local function ShareText%(s%)(.-)\nend\n")
    assert(share and not share:find("best", 1, true), "the shared summary line uses the best run")
end)
-- 0.2.3 P4 (Fahrplan; Sven's measurement 11.11.2026: Goldthorn 143 yd,
-- Kingsblood about 150-160 yd, the minimap zoomed out fully): the search
-- range of Find Herbs / Find Minerals. The known target pin within it gets a
-- mark, the run window a hint - only the distance from you to that pin
-- counts; the game's tracking dots are never read, nothing skips by itself.
local function ShownText(text)
    for _, o in ipairs(allFrames) do
        local t = o.GetText and o:GetText()
        if t and tostring(t):find(text, 1, true) and (not o.IsVisible or o:IsVisible()) then return o end
    end
end
step("Search range 0.2.3: the run target within it gets a light-blue ring and the run window says so - 150 yd, adjustable; a chest, a hidden position or out of range: nothing; nothing skips by itself (0.2.3 P4)", function()
    local W = IdentityWorld()
    local keep = { range = ns.db.searchRange, ring = ns.db.searchRing, secret = issecretvalue }
    local HINT = ns.L["In search range - no yellow dot? Press Skip."]
    local ok, err = pcall(function()
        ns.db.searchRange, ns.db.searchRing = nil, nil
        local a = W.Node("o1617", "Silverleaf", 0, { item = 765 })
        W.Set({ a })
        W.At(-200) ns.StartRun("herb", 1412) W.Wait(1)
        assert(ns.run and ns.run.target == a, "test setup: the run does not head for the Silverleaf")
        local function Marked()
            local world, mini = ns.RouteTargetPins()
            local shown = world and world.searchMark and world.searchMark:IsShown() and mini and mini.searchMark and mini.searchMark:IsShown()
            return ns.RouteTargetInRange() and ns.run.inSearchRange and shown and true or false
        end
        -- 1. the default is 150 yd: at 200 and 160 yd nothing, at 140 the mark and the hint
        assert(ns.SearchRange() == 150, "the search range is " .. ns.SearchRange() .. " yd, want 150")
        assert(not Marked() and not ShownText(HINT), "200 yd: marked")
        W.At(-160) W.Wait(1)
        assert(not Marked(), "160 yd: marked")
        W.At(-140) W.Wait(1)
        assert(Marked(), "140 yd: the target pin is not marked")
        assert(ShownText(HINT), "140 yd: the run window does not say it")
        -- 2. nothing skips by itself: a minute in range, the target stays
        W.Wait(60)
        assert(ns.run.target == a and Marked(), "in range for a minute: the target changed or lost its mark")
        -- 3. adjustable: 100 yd - 140 is out, 90 in; and kept within 60..250
        ns.db.searchRange = 100 W.Wait(1)
        assert(not Marked() and not ShownText(HINT), "range 100, at 140 yd: still marked")
        W.At(-90) W.Wait(1)
        assert(Marked(), "range 100, at 90 yd: not marked")
        ns.db.searchRange = 500
        assert(ns.SearchRange() == 250, "a range of 500 is not kept to 250")
        ns.db.searchRange = 10
        assert(ns.SearchRange() == 60, "a range of 10 is not kept to 60")
        ns.db.searchRange = nil
        -- 4. a target the tracking does not show (a chest): no mark, even close by
        a.type = "chest" ns.SearchRangeCheck()
        assert(not Marked(), "a chest within the range is marked")
        a.type = "ore" ns.SearchRangeCheck()
        assert(Marked(), "an ore spot within the range is not marked")
        a.type = "herb"
        -- 5. a hidden position (its type says "number", as the game's do): never compared, the mark goes
        local SECRET = newproxy(true)
        issecretvalue = function(v) return rawequal(v, SECRET) end
        local HBD = LibStub("HereBeDragons-2.0")
        local where, realType = HBD.GetPlayerWorldPosition, type
        HBD.GetPlayerWorldPosition = function() return SECRET, SECRET, 1 end
        type = function(v) if rawequal(v, SECRET) then return "number" end return realType(v) end
        local okCheck, errCheck = pcall(ns.SearchRangeCheck)
        type = realType
        HBD.GetPlayerWorldPosition = where
        issecretvalue = keep.secret
        assert(okCheck, "a hidden position: " .. tostring(errCheck))
        assert(not Marked(), "a hidden position: still marked")
        W.Wait(1)
        assert(Marked(), "readable again: not marked")
        -- 6. Skip pressed with the next spot in range too: the new target gets the mark (its pin starts without)
        local b = W.Node("o1617", "Silverleaf", 40, { item = 765 })
        W.Set({ a, b })
        W.At(-100) W.Wait(1)
        assert(ns.run.target == a and Marked(), "test setup: Silverleaf A in range as the target")
        ns.SkipNode() advance(0.1)
        assert(ns.run.target == b, "test setup: Skip did not go to Silverleaf B")
        W.Wait(1)
        assert(Marked(), "the next target in range after Skip: not marked")
        -- 7. the run ends: no mark
        ns.StopRun(true) W.Wait(1)
        assert(not ns.RouteTargetInRange(), "the mark stays after the run")
    end)
    ns.db.searchRange, ns.db.searchRing, issecretvalue = keep.range, keep.ring, keep.secret
    W.Restore()
    if not ok then error(err, 0) end
end)
step("Search range 0.2.3: the ring on the minimap - off by default; on: 40 dots around you at the range, again when you move, gone with the run (0.2.3 P4)", function()
    local W = IdentityWorld()
    local keep = { range = ns.db.searchRange, ring = ns.db.searchRing }
    local ok, err = pcall(function()
        ns.db.searchRange, ns.db.searchRing = nil, nil
        W.Set({ W.Node("o1617", "Silverleaf", 0, { item = 765 }) })
        W.At(-300) ns.StartRun("herb", 1412) W.Wait(1)
        assert(ns.SearchRingDots() == 0, "a ring although it is off")
        ns.db.searchRing = true W.Wait(1)
        local n, at = ns.SearchRingDots()
        local HBD = LibStub("HereBeDragons-2.0")
        local px, py = HBD:GetPlayerWorldPosition()
        assert(n == 40 and at and math.abs(at.x - px) < 0.01 and math.abs(at.y - py) < 0.01 and at.range == 150,
            ("the ring: %d dots, centre %s, range %s"):format(n, at and ("%.0f/%.0f"):format(at.x, at.y) or "-", at and tostring(at.range) or "-"))
        W.At(-290) W.Wait(1)
        local _, at2 = ns.SearchRingDots()
        assert(at2 and math.abs(at2.x - (px + 10)) < 0.01, "the ring does not follow you")
        ns.db.searchRange = 120 W.Wait(1)
        assert(select(2, ns.SearchRingDots()).range == 120, "the ring does not take the new range")
        ns.db.searchRing = nil W.Wait(1)
        assert(ns.SearchRingDots() == 0, "the ring stays when it is turned off")
        ns.db.searchRing = true W.Wait(1)
        ns.StopRun(true) W.Wait(1)
        assert(ns.SearchRingDots() == 0, "the ring stays after the run")
    end)
    ns.db.searchRange, ns.db.searchRing = keep.range, keep.ring
    W.Restore()
    if not ok then error(err, 0) end
end)
step("Search range 0.2.3: on Rares & prices for now - the range (150 yd, steps of 10) and the ring switch; General keeps its rows; the game's tracking is never read (0.2.3 P4)", function()
    local keep = ns.db.searchRange
    local f = assert(io.open(ROOT .. "/SearchRange.lua"))
    local src = f:read("*a") f:close()
    for _, call in ipairs({ "GetTrackingInfo", "GetNumTrackingTypes", "SetTracking", "C_Minimap", "GetChildren", "GetRegions", "SkipNode", "CastSpell", "GetPingPosition" }) do
        assert(not src:find(call, 1, true), "SearchRange.lua uses " .. call)
    end
    -- open, also when an earlier step left the options open (then they stay open)
    local win = _G.GathercraftOptions
    local wasOpen, wasSection = win:IsShown(), ns.db.optionsSection
    if not wasOpen then ns.ToggleOptions() end
    advance(1)
    local function PageOf(text)
        for _, o in ipairs(allFrames) do
            if o.GetText and o:GetText() == text then
                local p = o.__parent
                while p and not p.key do p = p.__parent end
                if p then return p.key end
            end
        end
    end
    -- the farm runs' page is full and General keeps its three free rows
    -- (v0.1.23 P4): Rares & prices, under a head of its own, until P7b
    assert(PageOf(ns.L["Search range"]) == "alerts", "the search range is not under Rares & prices: " .. tostring(PageOf(ns.L["Search range"])))
    assert(PageOf(ns.L["Show the search range on the minimap during farm runs"]) == "alerts", "the ring switch is not under Rares & prices")
    assert(PageOf(ns.L["How far Find Herbs shows nodes (ore: assumed the same)"]) == "alerts", "the search range's line is not under Rares & prices")
    local head -- (the text is the farm runs' page's name too)
    for _, o in ipairs(allFrames) do
        if o.GetText and o:GetText() == ns.L["Farm runs"] and o.__parent and o.__parent.key == "alerts" then head = o end
    end
    assert(head, "Rares & prices has no head 'Farm runs' over the search range")
    local ROOM = 640 - 112 - 18 - 4 - 66
    local used = ns.OptionsUsedHeight()
    assert(used.general <= ROOM - 3 * 26, ("General goes down to %d px: its three free rows are gone"):format(used.general))
    assert(used.alerts <= ROOM, ("Rares & prices goes down to %d px of %d"):format(used.alerts, ROOM))
    -- its value: 150 yd; the buttons go in steps of 10, within 60..250
    -- (the value is found by its page, not by being visible: an earlier step
    -- may have put the options into a tab of the main window, and the mock's
    -- logins may have built them more than once - the newest counts)
    ns.ShowOptionsSection("alerts") win:Refresh() advance(1)
    local value
    for _, o in ipairs(allFrames) do
        if o.__kind == "FontString" and o:GetText() == "150" .. ns.L[" yd"] then
            local p = o.__parent
            while p and not p.key do p = p.__parent end
            if p and p.key == "alerts" then value = o end
        end
    end
    assert(value, "Rares & prices does not show 150 yd")
    local minus, plus
    -- (the buttons are found next to the value: the one left of it and the one right of it)
    for _, o in ipairs(allFrames) do
        local p = o.__pts and o.__pts.LEFT
        if p and p[1] == value and o.GetText and o:GetText() == "+" then plus = o end
    end
    for _, o in ipairs(allFrames) do
        local p = value.__pts and value.__pts.LEFT
        if p and p[1] == o then minus = o end
    end
    assert(plus and minus and minus:GetText() == "-", "test setup: the search range's buttons")
    plus.__scripts.OnClick(plus)
    assert(ns.SearchRange() == 160 and ns.db.searchRange == 160, "+ does not add 10 yd")
    for _ = 1, 20 do plus.__scripts.OnClick(plus) end
    assert(ns.SearchRange() == 250, "+ goes past 250 yd")
    for _ = 1, 30 do minus.__scripts.OnClick(minus) end
    assert(ns.SearchRange() == 60, "- goes below 60 yd")
    for _ = 1, 9 do plus.__scripts.OnClick(plus) end
    assert(ns.SearchRange() == 150 and ns.db.searchRange == nil, "back at 150 yd the default is not saved as nothing")
    ns.ShowOptionsSection(wasSection or "map")
    if not wasOpen then ns.ToggleOptions() end
    advance(1)
    ns.db.searchRange = keep
end)
step("Long run (10 min) for leaks", function() slash("run herb") advance(600) slash("stop") end)
step("Test mock: OnUpdate runs for the same frames in the same order as going over every frame (tools only)", function()
    -- The mock's advance() goes over the frames that have an OnUpdate only
    -- (see updFrames). It must call what going over all frames made so far
    -- called: in the order the frames were made, a frame made in the middle
    -- of a round still in that round, an older frame that gets its OnUpdate
    -- in the middle of a round from the next round on, nobody twice. (Last of
    -- all steps, so the steps before it see the same OnUpdate calls as before.)
    local seen = {}
    local function Rec(tag) return function() seen[#seen + 1] = tag end end
    local function Rounds()
        seen = {}
        for i = 1, 3 do C_Timer.After(i / 10, function() end) end
        advance(0.35)
        return table.concat(seen)
    end
    local function Repeats(s, unit)
        return #s >= #unit * 3 and s:gsub(unit, "") == ""
    end
    local A, B, C = CreateFrame("Frame"), CreateFrame("Frame"), CreateFrame("Frame")
    local D
    C:SetScript("OnUpdate", function()
        seen[#seen + 1] = "C"
        if not D then
            B:SetScript("OnUpdate", Rec("B"))                  -- older than C: from the next round on
            D = CreateFrame("Frame")
            D:SetScript("OnUpdate", Rec("D"))                  -- made now: in this round, after C
        end
    end)
    A:SetScript("OnUpdate", Rec("A"))                          -- set after C, made before it: called before it
    local s = Rounds()
    assert(s:sub(1, 3) == "ACD", "the first round: " .. s:sub(1, 8) .. " (want A C D: B from the next round on, D in this one)")
    assert(Repeats(s:sub(4), "ABCD"), "the rounds after it: " .. s:sub(4, 20) .. " (want A B C D each)")
    B:Hide()
    s = Rounds()
    assert(Repeats(s, "ACD"), "a hidden frame: " .. s:sub(1, 12))
    A:SetScript("OnUpdate", nil)
    s = Rounds()
    assert(Repeats(s, "CD"), "a removed OnUpdate: " .. s:sub(1, 12))
    A:SetScript("OnUpdate", Rec("A"))
    s = Rounds()
    assert(Repeats(s, "ACD"), "an OnUpdate set again: " .. s:sub(1, 12))
    local E = CreateFrame("Frame")
    E.__scripts.OnUpdate = Rec("E")                            -- a new frame, set right in the table (as a few steps do)
    s = Rounds()
    assert(Repeats(s, "ACDE"), "an OnUpdate set right in __scripts: " .. s:sub(1, 16))
    local F = CreateFrame("Frame")
    F:HookScript("OnUpdate", Rec("F"))                         -- a new frame, only hooked
    D:HookScript("OnUpdate", Rec("d"))
    s = Rounds()
    assert(Repeats(s, "ACDdEF"), "a hooked OnUpdate: " .. s:sub(1, 18))
    for _, f in ipairs({ A, B, C, D, E, F }) do f:SetScript("OnUpdate", nil) end
    s = Rounds()
    assert(s == "", "after all are removed: " .. s:sub(1, 12))
end)

